window.WK_MAT={"app":"中医外科学","edition":"第六版","publisher":"中国中医药出版社","chapters":[{"id":"ch06","no":"第六章","num":6,"name":"疮疡","cardId":"d0600","diseaseIds":["d0601","d0602","d0602a","d0602b","d0602c","d0602d","d0602e","d0603","d0603a","d0603b","d0603c","d0603d","d0604","d0604a","d0604b","d0604c","d0604d","d0605","d0606","d0607","d0608","d0608a","d0608b","d0609","d0609a","d0609b","d0610","d0611","d0612","d0613"]},{"id":"ch07","no":"第七章","num":7,"name":"乳房疾病","cardId":"d0700","diseaseIds":["d0701","d0702","d0703","d0704","d0705","d0706","d0707","d0708","d0709","d0710"]},{"id":"ch08","no":"第八章","num":8,"name":"瘿","cardId":"d0800","diseaseIds":["d0801","d0802","d0803","d0804","d0805"]},{"id":"ch09","no":"第九章","num":9,"name":"瘤、岩","cardId":"d0900","diseaseIds":["d0901","d0902","d0903","d0904","d0905","d0906"]},{"id":"ch10","no":"第十章","num":10,"name":"皮肤及性传播疾病","cardId":"d1000","diseaseIds":["d1001","d1002","d1003","d1004","d1005","d1006","d1007","d1008","d1009","d1010","d1011","d1012","d1013","d1014","d1015","d1016","d1017","d1018","d1019","d1020","d1021","d1022","d1023","d1024","d1025","d1026","d1027","d1028","d1029","d1030","d1031","d1032","d1033"]},{"id":"ch11","no":"第十一章","num":11,"name":"肛肠疾病","cardId":"d1100","diseaseIds":["d1101","d1101a","d1101b","d1101c","d1102","d1103","d1104","d1105","d1106","d1107","d1108","d1109"]},{"id":"ch12","no":"第十二章","num":12,"name":"泌尿男性生殖系疾病","cardId":"d1200","diseaseIds":["d1201","d1202","d1203","d1204","d1205","d1206","d1207","d1208","d1209","d1210","d1211","d1212","d1213"]},{"id":"ch13","no":"第十三章","num":13,"name":"周围血管及淋巴管疾病","cardId":"d1300","diseaseIds":["d1301","d1302","d1303","d1304","d1304a","d1304b","d1304c","d1305"]},{"id":"ch14","no":"第十四章","num":14,"name":"其他外科疾病","cardId":"","diseaseIds":["d1401","d1402","d1403","d1404","d1405","d1406","d1407"]}],"cards":[{"id":"d0600","kind":"chapter","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"本章概述","displayName":"疮疡·本章概述","parentId":"","printedPage":43,"pdfPage":58,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"广义疮疡泛指一切体表浅显的外科疾病。"},{"t":"p","x":"狭义疮疡是指各种致病因素侵袭人体后引起的体表感染性疾病。"},{"t":"p","x":"本章论述的是狭义疮疡，是中医外科最常见的疾病，相当于西医学的体表外科感染。疮疡的致病因素分外因(六淫邪毒、特殊之毒、外来伤害等)和内因(情志内伤、饮食不节、房事损伤等)两大类。"},{"t":"p","x":"各种致病因素可以单独致病，亦可多种因素同时致病。内因和外因常相合为病。外因引起的疮疡以“热毒”“火毒”最为多见，常起病急，发展快，多属阳证，如疔、痈、发等；"},{"t":"p","x":"内伤因素引起的疮疡大多因虚致病，起病缓，发病慢，多属阴证，如流痰、瘰疬等。各种致病因素侵袭人体后，局部气血凝滞，营卫不和，经络阻塞，产生肿痛，此为疮疡初期(肿疡)。"},{"t":"p","x":"疮疡发生以后，正邪交争的结果决定着疮疡的发展和转归。若正能胜邪，则邪热不能鸱张，肿势逐渐局限，疮疡消散；"},{"t":"p","x":"若正不胜邪，热毒壅滞不散，热胜肉腐成脓，导致脓肿形成，即为疮疡中期(成脓)。此时如治疗得当，切开引流，或正气尚足，脓肿破溃，毒随脓泄，形成溃疡，腐脱新生，最后疮口愈合，即为疮疡后期(溃疡期)。"},{"t":"p","x":"疮疡轻证可无全身症状，火毒、热毒较重的常有发热、头痛、全身不适等全身症状；若因失治误治，或人体气血虚弱，不能托毒外达，导致邪毒走散，内攻脏腑，可见烦躁不安、神昏谵语、四肢厥逆，甚者危及生命。"},{"t":"p","x":"红、肿、热、痛、溃脓及功能障碍，这是疮疡共同的局部症状。但这些症状的出现及轻重，受感邪性质、病程长短、病变范围和病位深浅等因素的影响。"},{"t":"p","x":"如火热阳邪致病，局部以红热见症；风寒痰浊致病，初始局部多不红不热，待化火生热才见红热。"},{"t":"p","x":"病位浅，初起局部症状即十分显著；病位深，如附骨疽等，虽有肿热痛，但皮色不变或仅微红。在疮疡的发生过程中，由于病理变化或功能障碍产生的一些形态改变，对临床诊断常有一定的价值。"},{"t":"p","x":"如颜面疔疮患者局部疮口突然凹陷，皮色暗红，常是走黄的征兆；红丝疔必有红丝一条或数条；"},{"t":"p","x":"蛇头疔指端肿胀，其形如蛇头。膝关节流痰因大小腿肌肉萎缩后状如鹤膝，又称“鹤膝痰”。"},{"t":"p","x":"骼窝流注初起，大腿拘挛跛行。而溃疡形态、色泽的不同，脓液的形质色泽和气味改变，腐肉脱落的难易，以及四畔的变化等亦可帮助疾病的诊断和预后判断。"},{"t":"p","x":"此外，辨别疮疡有无损伤骨骼和穿透内膜(即胸膜或腹膜)也很重要。疮疡损伤骨骼多在四肢，局部胖肿，触之骨骼增粗，或疮口胬肉外翻，经久不愈，脓出腥臭，以纸捻探之有锯齿感，多为损骨。"},{"t":"p","x":"疮疡透膜多在躯干，肿势漫无边际，触之绵软，或有捻发音，多为气肿或透膜；破溃脓出似蟹沫，或夹有气泡，在胸壁有时可听到如儿啼声，在腹部有时可看到有粪便流出。"},{"t":"p","x":"配合B超、X线片、CT等检查，常有助于明确诊断。较轻的浅部疮疡，有时可仅用外治收功；严重的病症则需内治、外治相结合。"},{"t":"p","x":"疮疡病的治疗可按发病过程分期辨证施治。疮疡内治法的总则为消、托、补。"},{"t":"p","x":"疮疡初期尚未成脓时，用消法使之消散，并针对病因、病情运用清热解毒、和营行瘀、理气、解表、温通、通里、理湿等治法，其中清热解毒为疮疡最常用的治法；"},{"t":"p","x":"疮疡中期脓成不溃或脓出不畅，用托法以托毒外出，根据患者具体情况分别采用透托法或补托法；疮疡后期体质虚弱者，用补法以恢复正气，使疮疡早日愈合。"},{"t":"p","x":"疮疡外治法的总则为消、腐、敛。疮疡初期宜箍毒消肿。"},{"t":"p","x":"阳证可选用金黄散(膏)、玉露散(膏)等，或用清热解毒消肿的新鲜草药捣烂外敷；阴证可选用回阳玉龙散(膏)、阳和解凝膏等；"},{"t":"p","x":"半阴半阳证选用冲和散(膏)。中期脓肿形成宜切开排脓，并予七三丹、五五丹等提脓祛腐；"},{"t":"p","x":"腐脱新生用八二丹、九一丹、生肌玉红膏等祛腐生肌；腐肉脱尽改用生肌散、白玉膏等生肌敛口。"},{"t":"p","x":"疮口太小或成漏时，用白降丹、千金散药线腐蚀；疮面胬肉突出时用平胬丹。疮口脓水较多或渗液较多，可辨证使用中药溶液湿敷。"},{"t":"p","x":"根据情况配合使用垫棉法或扩创法。此外、砭镰法、火针烙法、刺络拔罐、拖线疗法、挑治等均可用于疮疡的治疗。"},{"t":"p","x":"此外、在疮疡的治疗中、还要重视患者的精神调摄、少食辛辣炙煿助火之物及肥甘厚腻之品，忌食鱼腥发物、保持大便通畅、重视护理换药等。若患消渴病等，应及时治疗。"},{"t":"p","x":"体虚者应注重健身，增强体质。"}],"entries":["e0001"]}]},{"id":"d0601","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"疖","displayName":"疖","parentId":"","printedPage":44,"pdfPage":59,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"疖是指发生在肌肤浅表部位、范围较小的急性化脓性疾病。其临床特点是色红、灼热、疼痛，突起根浅，肿势局限，范围多小于3cm，易脓、易溃、易敛。"},{"t":"p","x":"根据病因、证候不同，又可分有头疖、无头疖、蝼蛄疖、疖病等。疖之病名首见于《肘后备急方》。"},{"t":"p","x":"本病相当于西医学的疖、头皮穿凿性脓肿、疖病等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"疖常因内郁湿火，外感风邪，两相搏结，蕴阻肌肤所致；或夏秋季节感受暑湿热毒，暑湿蕴蒸肌肤，引起痱子，复经搔抓，破伤染毒而成。"},{"t":"p","x":"头部疖肿若处理不当、疮口过小引起脓毒潴留，或搔抓染毒，导致脓毒旁窜，在头顶皮肉较薄处易蔓延、窜空而成蝼蛄疔。若伴消渴或习惯性便秘等慢性疾病者，阴虚内热，或脾虚便溏，更易染毒发病，并可反复发作，缠绵难愈，发为疖病。"},{"t":"p","x":"西医学认为，疖是单个毛囊及其所属皮脂腺或汗腺的急性"},{"t":"img","src":"img/fig/f0601.jpg","alt":"图6-1毛囊及毛囊周围炎"},{"t":"p","x":"化脓性炎症(图6-1)，常见的致病菌为金黄色葡萄球菌或白色葡萄球菌。"}],"entries":["e0002","e0003"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现局部皮肤红肿疼痛，可伴有发热。"},{"t":"p","x":"有头疖：患处皮肤上有一红色结块，范围小于3cm，灼热疼痛，突起根浅，中心有一脓头，出脓即愈。无头疖：皮肤上有一红色结块，范围小于3cm，无脓头，表面灼热，触之疼痛，2～3天化脓、溃后多迅速愈合。"},{"t":"p","x":"蝼蛄疖：多发于儿童头部。临床常见两种类型：①坚硬型，疮肿小，根脚坚硬，出脓愈后会复发，常为一处未愈，他处又生；"},{"t":"p","x":"②多发型，疮大如梅李，相联三五枚，溃破不愈，头皮窜空，如蝼蛄串穴之状。"},{"t":"p","x":"不论何型，迁延日久，可损及颅骨。疖病：好发于项后发际、背部、臀部。"},{"t":"p","x":"几个到几十个，反复发作，缠绵不愈。也可在身体各处散发疖肿，一处将愈，他处续发，或间隔周余、月余再发。"},{"t":"p","x":"患消渴病、习惯性便秘或营养不良者易患本病。"},{"t":"h","lv":3,"x":"(2)辅助检查必要时可进行血常规、血糖、免疫功能等方面的检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-1)"},{"t":"table","img":"img/tab/t0601.jpg","cap":"表6-1疖与痈、颜面部疔疮、囊肿型痤疮的鉴别"}],"entries":["e0004"]},{"title":"治疗","blocks":[{"t":"p","x":"以清热解毒为主。夏秋发病者须兼清暑化湿；疖病多虚实夹杂，治疗宜扶正固本与清热解毒并施；"},{"t":"p","x":"对伴消渴病等慢性病者，须积极治疗原发疾病。症状轻微者可单以外治收功。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s060101","name":"热毒蕴结证","clinic":"好发于项后发际、背部、臀部。轻者疖肿只有一两个，多则可散发全身，或簇集一处，或此愈彼起；伴发热、口渴、溲赤、便秘；舌苔黄，脉数","treat":"清热解毒","formula":"五味消毒饮、黄连解毒汤加减。热毒盛者，加黄连、栀子；大便秘结者，加生大黄；疖肿难化，加僵蚕、浙贝母","formulaNames":["五味消毒饮","黄连解毒汤"]},{"t":"syn","sid":"s060102","name":"暑热浸淫证","clinic":"发于夏秋季节，以小儿及产妇多见。局部皮肤红肿结块，灼热疼痛，根脚浅，范围局限；可伴发热、口干、便秘、溲赤等；舌苔薄腻，脉滑数","treat":"清暑化湿解毒","formula":"清暑汤加减。疖在头面部，加野菊花、防风；疖在身体下部，加黄柏、苍术；大便秘结者，加生大黄、枳实","formulaNames":["清暑汤"]},{"t":"syn","sid":"s060103","name":"体虚毒恋，阴虚内热证","clinic":"疖肿常此愈彼起，不断发生，或散发全身各处，或固定一处，疖肿较大，易转变成有头疽；常伴口干唇燥；舌质红，苔薄，脉细数","treat":"养阴清热解毒","formula":"仙方活命饮合增液汤加减。口干唇燥者，加芦根","formulaNames":["仙方活命饮","增液汤"]},{"t":"syn","sid":"s060104","name":"体虚毒恋，脾胃虚弱证","clinic":"疖肿泛发全身各处，成脓、收口时间均较长，脓水稀薄；常伴面色萎黄，神疲乏力，纳少便溏；舌质淡或边有齿痕，苔薄，脉濡","treat":"健脾和胃、清化湿热","formula":"五神汤合参苓白术散加减。脓成溃迟，加皂角刺、川芎","formulaNames":["五神汤","参苓白术散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起用千捶膏盖贴、或用金黄散或玉露散调成糊状敷于患处，或紫金锭水调外敷；"},{"t":"p","x":"也可用鲜野菊花叶、蒲公英、芙蓉叶、龙葵、败酱草、丝瓜叶取其一种，洗净捣烂敷于患处，每天1～2次。"},{"t":"p","x":"(2)脓成宜切开排脓。"},{"t":"p","x":"蝼蛄疔宜做“十”字形切开，如遇出血，可用棉垫加多头带缚扎以压迫止血。若有死骨、待松动时用镊子钳出。"},{"t":"p","x":"(3)后期予九一丹、太乙膏盖贴；脓尽用生肌散、白玉膏收口。"},{"t":"p","x":"可配合垫棉法，使皮肉粘连而愈合。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺法疖肿初起，可用三棱针围绕病灶周围点刺放血。"},{"t":"p","x":"疖脓熟未溃，或虽溃而疮口过小，脓出不畅者，可选用火针烙法。颈部多发性疖肿可在背部寻找反应点进行挑治治疗。"},{"t":"p","x":"(2)中成药六应丸或六神丸口服。"},{"t":"p","x":"(3)西医治疗病情较重者，应使用有效抗生素治疗。"},{"t":"p","x":"如有糖尿病者，必须控制血糖。"}]}],"entries":["e0005","e0006","e0007","e0008","e0009","e0010","e0011"]},{"title":"预防与调护","blocks":[{"t":"p","x":"颜面部疖肿忌挤压、搔抓，防止碰伤。"}],"entries":["e0012"]}]},{"id":"d0602","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"疔","displayName":"疔","parentId":"","printedPage":46,"pdfPage":61,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"疔是一种发病迅速，易于变化而危险性较大的急性化脓性疾病。多发于颜面部和手足等处。"},{"t":"p","x":"病情变化迅速，容易造成毒邪走散。疔的范围很广，名称繁多，证因各异。"},{"t":"p","x":"根据发病部位和性质不同，分为颜面部疔疮、手足部疔疮、红丝疔、烂疔、疫疔。"}],"entries":["e0013"]}]},{"id":"d0602a","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"颜面部疔疮","displayName":"疔·颜面部疔疮","parentId":"d0602","printedPage":46,"pdfPage":61,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"颜面部疔疮是指发生于颜面部的急性化脓性疾病。"},{"t":"p","x":"其临床特点为发于颜面部，病变迅速，疮形如粟，坚硬根深，状如钉丁，全身热毒症状明显，易成走黄之变。由于发病部位不同，名称各异，如眉心疔、眉棱疔、眼胞疔、颧疔、人中疔等。"},{"t":"p","x":"名称虽繁，但其病因、辨证论治基本相同。本病相当于西医学的颜面部疖、痈。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因火热之毒为患。内伤饮食，如恣食膏粱厚味、醇酒辛辣炙煿之品，或外感风热火毒，或皮肤破损染毒，致气血凝滞，火毒结聚，热胜肉腐而成。"},{"t":"p","x":"若火毒炽盛，内燔营血，则成走黄重证。西医学认为，本病常见致病菌为金黄色葡萄球菌或白色葡萄球菌。"},{"t":"p","x":"若发生在上唇周围和鼻部，如被挤压或挑破，感染易经由内眦静脉和眼静脉进入颅内海绵窦，引起化脓性海绵窦静脉炎。"}],"entries":["e0014","e0015"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现多发于额前、倾、颊、鼻、口唇等部。"},{"t":"p","x":"初期：在颜面部忽起一粟米样脓头，红肿热痛，肿势范围3～6cm，根深坚硬，重者有恶寒发热等全身症状。中期：第5～7日，肿痛加剧，脓头破溃。"},{"t":"p","x":"伴有发热、口渴等全身症状。后期：第7～10日，肿势局限，根软溃脓，脓栓随脓外出，肿消痛止，身热减退。"},{"t":"p","x":"一般10～14天可痊愈。若处理不当、或妄加挤压，或不慎碰伤，或过早切开等，可引起疔疮走黄(顶陷色黑无脓，肿势扩散，伴壮热烦躁、神昏谵语等)。"},{"t":"p","x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"p","x":"必要时做细菌培养。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-2)"},{"t":"table","img":"img/tab/t0602.jpg","cap":"表6-2颜面部疔疮与有头疽的鉴别"},{"t":"p","x":"颜面部疔疮与疖的鉴别见表6-1。"}],"entries":["e0016"]},{"title":"治疗","blocks":[{"t":"p","x":"以清热解毒为法。切忌早期切开引流。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0602a01","name":"热毒蕴结证","clinic":"红肿高突，根脚收束；伴发热、头痛；舌红，苔黄，脉数","treat":"清热解毒","formula":"五味消毒饮、黄连解毒汤加减。毒盛肿甚者，加大青叶，重用黄连；壮热口渴者，加淡竹叶、石膏、知母","formulaNames":["五味消毒饮","黄连解毒汤"]},{"t":"syn","sid":"s0602a02","name":"火毒炽盛证","clinic":"疮形平塌，肿势散漫，皮色紫暗，焮热疼痛；伴高热，头痛，烦渴，呕恶，溲赤，便秘；舌红，苔黄腻，脉洪数","treat":"凉血清热解毒","formula":"犀角地黄汤、黄连解毒汤、五味消毒饮加减。痛甚，加乳香、没药；不易出脓者，加皂角刺；便秘者，加生大黄","formulaNames":["犀角地黄汤","黄连解毒汤","五味消毒饮"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起宜箍毒消肿，用金黄散、玉露散调糊围敷，或千捶膏盖贴，或六神丸、紫金锭研碎水调外敷。"},{"t":"p","x":"(2)脓成宜切开排脓。"},{"t":"p","x":"若脓成，中央有脓栓，不愿手术者，用七三丹撒于疮顶部、再用千捶膏敷贴，以蚀疮破头、提脓祛腐。"},{"t":"p","x":"(3)溃后宜提脓祛腐，疮口掺七三丹、八二丹，疮周外敷金黄膏。"},{"t":"p","x":"若脓出不畅，用七三丹、八二丹药线引流；脓尽改用生肌散、太乙膏或红油膏盖贴生肌收口。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)中成药蟾酥丸、西黄丸口服。"},{"t":"p","x":"(2)西医治疗必要时可应用抗生素，并配合支持疗法。"}]}],"entries":["e0017","e0018","e0019","e0020","e0021"]},{"title":"预防与调护","blocks":[{"t":"p","x":"忌内服发散药。忌灸法，忌早期切开及针挑、忌挤脓，以免疔毒走散入血。"}],"entries":["e0022"]}]},{"id":"d0602b","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"手足部疔疮","displayName":"疔·手足部疔疮","parentId":"d0602","printedPage":48,"pdfPage":63,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"手足部疔疮是发生在手足部的急性化脓性疾病。"},{"t":"p","x":"其临床特点是手部多见，发病较急，红肿热痛明显，易损筋伤骨。本病因发病部位、形态不同而有多种命名，常见的有蛇眼疔、蛇头疔、鱼肚疔或蛇腹疔、托盘疔、足底疔等。"},{"t":"p","x":"本病相当于西医学的甲沟炎、化脓性指头炎、化脓性腱鞘炎、掌中间隙感染、足底皮下脓肿等病。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"内因脏腑火毒炽盛，外因手足部外伤染毒，如刺伤、昆虫咬伤等，致火毒之邪阻塞经络，气血凝滞，热胜肉腐，甚则损筋伤骨。托盘疔还可由手少阴心经、手厥阴心包经火毒炽盛为患；足底疔多由湿热下注引起。"},{"t":"p","x":"西医学认为，本病多为局部外伤后感染所致，或附近软组织、筋膜间隙等处感染而引起。致病菌多为金黄色葡萄球菌。"}],"entries":["e0023","e0024"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现手足部疔疮发病部位多有受伤史。"},{"t":"p","x":"蛇眼疔：初起时一侧甲缘红肿疼痛，2～3天成脓。红肿延及甲周可成甲周围炎。"},{"t":"p","x":"脓毒浸淫甲下，可形成甲下脓肿(指甲背面显黄白色或灰白色脓液积聚阴影)，甲下溃空或有胬肉突出，甚至指(趾)甲脱落。蛇头疔：初起指端麻痒灼痛肿胀，10天左右成脓，指端肿如蛇头，跳痛剧烈，伴有恶寒发热、头痛、全身不适等症状。"},{"t":"p","x":"若溃后脓臭不愈，余肿不消，或胬肉突出，多为损筋伤骨。蛇肚疔：患指红肿疼痛，呈圆柱状，屈伸受限。"},{"t":"p","x":"7～10天成脓。脓成难溃。"},{"t":"p","x":"若损伤筋脉，则愈合缓慢，常影响手指的屈伸。托盘疔：手掌肿胀高突，手背肿甚，疼痛剧烈。"},{"t":"p","x":"伴有恶寒发热、头痛等全身症状。2周左右成脓，脓可向周围蔓延，损伤筋骨，或并发疔疮走黄。"},{"t":"p","x":"足底疔：初起足底部疼痛，按之坚硬。3～5日脓成，脓点隐现。"},{"t":"p","x":"重者肿连足背。伴有恶寒发热、头痛等症状。"},{"t":"p","x":"辨别手指部有脓无脓，除依据一般化脓日期及触诊外，可采用透光法。辨别有无死骨，可用探针深入疮孔，如触及粗糙的骨质，是为损骨。"},{"t":"p","x":"辨别有无伤筋，可观察手指屈伸功能。"},{"t":"p","x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例增高。"},{"t":"p","x":"必要时做脓液细菌培养加药敏试验。X线片可确定有无骨质破坏。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-3、表6-4)"},{"t":"table","img":"img/tab/t0603.jpg","cap":"表6-3托盘疔与手发背的鉴别"},{"t":"table","img":"img/tab/t0604.jpg","cap":"表6-4足底疔与足发背鉴别"}],"entries":["e0025"]},{"title":"治疗","blocks":[{"t":"p","x":"以清热解毒为主，发于下肢者应清热利湿。脓成后应尽早切开排脓。"},{"t":"p","x":"愈后须加强关节功能锻炼。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0602b01","name":"火毒凝结证","clinic":"局部红肿热痛，麻痒相兼；伴畏寒发热；舌质红，苔黄，脉数","treat":"清热解毒","formula":"五味消毒饮、黄连解毒汤加减","formulaNames":["五味消毒饮","黄连解毒汤"]},{"t":"syn","sid":"s0602b02","name":"热胜肉腐证","clinic":"红肿明显，疼痛剧烈，痛如鸡啄；若溃后肿痛不退，胬肉外突，甚者损筋蚀骨；舌质红，苔黄，脉数","treat":"清热透脓托毒","formula":"五味消毒饮合透脓散加减","formulaNames":["五味消毒饮","透脓散"]},{"t":"syn","sid":"s0602b03","name":"湿热下注证","clinic":"足底部红肿热痛；伴恶寒，发热，头痛，纳呆；舌质红，苔黄腻，脉滑数","treat":"清热解毒利湿","formula":"五神汤合萆薢渗湿汤加减","formulaNames":["五神汤","萆薢渗湿汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期金黄膏或玉露膏外敷。"},{"t":"p","x":"蛇眼疔也可用10%黄柏溶液湿敷。"},{"t":"p","x":"(2)成脓期脓成应及早切开排脓，尽可能循经直开。"},{"t":"p","x":"蛇眼疔宜沿甲旁0.2cm挑开引流。蛇头疔宜在指掌面一侧做纵行切口，必要时可对口引流；"},{"t":"p","x":"蛇肚疔宜在手指侧面做纵行切口，切口长度不得超过上下指关节面。托盘疔应依掌横纹切开，切口应够大，手掌处显有白点者，应先剪去厚皮，再挑破脓头。"},{"t":"p","x":"甲下溃空者须拔甲，拔甲后敷以红油膏纱布包扎。"},{"t":"p","x":"(3)溃后期溃后可用七三丹提脓祛腐。"},{"t":"p","x":"若胬肉高突，用平胬丹外敷；若已损骨，久不收口，可用2%～10%黄柏溶液浸泡患指。有死骨，待死骨松动时钳出死骨。"},{"t":"p","x":"脓尽用生肌散、白玉膏外敷。手指屈伸障碍者，待伤口愈合后，用桂枝、桑枝、红花、丝瓜络、伸筋草等煎汤熏洗，并加强患指屈伸功能锻炼。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)填塞法适用于初期甲沟炎，可用填塞法引流与减压。"},{"t":"p","x":"(2)手术疗法适用于甲沟炎非手术治疗无效者。"},{"t":"p","x":"包括甲板部分切除术、全甲拔除术、甲皱襞切除术/甲缘切除缝合术、甲母质切除术等。"},{"t":"p","x":"(3)其他参见“颜面部疔疮”。"}]}],"entries":["e0026","e0027","e0028","e0029","e0030","e0031"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.手部疔疮患者忌持重物或剧烈活动，以三角巾悬吊固定。生于手掌部者宜手掌向下，使脓液容易流出。"},{"t":"p","x":"足部疔疮宜抬高患肢，尽量少行走。2.愈后影响手指屈伸功能者，宜加强功能锻炼。"}],"entries":["e0032"]}]},{"id":"d0602c","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"红丝疔","displayName":"疔·红丝疔","parentId":"d0602","printedPage":50,"pdfPage":65,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"红丝疔是发于四肢，皮肤呈红丝显露，迅速向上走窜的急性感染性疾病。"},{"t":"p","x":"可伴恶寒发热等全身症状，邪毒重者可内攻脏腑，发生走黄。《肘后备急方》称之为“遍病”。"},{"t":"p","x":"宋代严用和《济生方》明确指出本病应属疔疮范畴。本病相当于西医学的急性淋巴管炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病外因手足疔疮，或足癣糜烂，或皮肤破损染毒，内有火毒凝聚，毒邪循经上窜而成。若火毒走窜，内攻脏腑，可成走黄之证。"},{"t":"p","x":"西医学认为，本病是由β-溶血性链球菌或金黄色葡萄球菌经由损伤的皮肤、黏膜或其他感染性病灶侵入淋巴管引起的淋巴管及其周围组织急性炎症。"}],"entries":["e0033","e0034"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现好发于四肢内侧，常有手足部生疔、皮肤破损或足癣等病史。"},{"t":"p","x":"多先在手足生疔部位或皮肤破损处见红肿热痛，继则在前臂或小腿内侧皮肤上起红丝一条或多条，迅速向躯干方向走窜。腋窝或腘窝、腹股沟部常有臖核肿大作痛。"},{"t":"p","x":"轻者红丝较细，无全身症状，1～2日可愈；重者红丝较粗，伴有恶寒发热、头痛、乏力等全身症状。"},{"t":"p","x":"病变在深部可见条索状肿块和压痛。若伴有高热、神昏谵语、胸痛、咳血等症，是为“走黄”。"},{"t":"p","x":"有的还可出现结块，一处未愈，他处又起，有的二三处相互串连。结块化脓，则肿胀疼痛更剧，溃后一般容易收口，若二三处串连贯通，则收口较慢。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例可增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-5)"},{"t":"table","img":"img/tab/t0605.jpg","cap":"表6-5红丝疔与青蛇毒、股肿的鉴别"}],"entries":["e0035"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗宜清热解毒，佐以凉血活血。应积极治疗原发病灶。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0602c01","name":"火毒入络证","clinic":"患肢红丝较细，红肿疼痛；全身症状较轻；苔薄黄，脉濡数","treat":"清热解毒","formula":"五味消毒饮加减。热毒盛者，加生地黄、黄连、栀子；发于下肢，加黄柏、牛膝","formulaNames":["五味消毒饮"]},{"t":"syn","sid":"s0602c02","name":"火毒入营证","clinic":"患肢红丝粗肿明显，迅速向近端蔓延；并伴臖核肿大作痛，寒战高热，头痛，口渴；苔黄腻，脉洪数","treat":"凉血清营，解毒散结","formula":"犀角地黄汤、黄连解毒汤、五味消毒饮加减。成脓，加皂角刺","formulaNames":["犀角地黄汤","黄连解毒汤","五味消毒饮"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期可外敷金黄膏、玉露散；"},{"t":"p","x":"若结块成脓则宜切开排脓，外敷红油膏；脓尽改用生肌散、白玉膏收口。"},{"t":"p","x":"(2)红丝细者宜用砭镰法，以刀针沿红丝行走途径，寸寸挑断，微令出血，或在红丝尽头挑断，挑破处均盖贴太乙膏掺红灵丹。"}]}],"entries":["e0036","e0037","e0038","e0039"]},{"title":"预防与调护","blocks":[{"t":"p","x":"参见“手足部疔疮”。"}],"entries":["e0040"]}]},{"id":"d0602d","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"烂疔","displayName":"疔·烂疔","parentId":"d0602","printedPage":51,"pdfPage":66,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"烂疔是发生于皮肉之间的急性化脓性疾病。"},{"t":"p","x":"其临床特点是来势急骤凶险，焮热肿胀，疼痛彻骨，肿胀迅速蔓延，极易化腐，患处皮肉很快大片腐烂脱落，疮形凹如匙面，流出脓液稀薄如水、臭秽，易并发走黄，危及生命。"},{"t":"p","x":"《备急千金要方·疔肿》首载“烂疔”，指出“其状色稍黑，有白斑，疮中溃，溃有脓水流出，疮形大小如匙面。忌沸热食、烂臭物”。"},{"t":"p","x":"中医文献中又称“水疔”“卸肉疔”“烂皮疔”“脱靴疔”等。本病相当于西医学的气性坏疽。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因皮肉破损，接触潮湿泥土、脏物等，感染特殊毒气，又有湿热火毒内蕴，以致毒聚肌肤，气血凝滞，热胜肉腐而成。若湿热火毒炽盛走窜入营，则易成走黄重证。"},{"t":"p","x":"西医学认为，本病多由梭状芽孢杆菌感染引起。"}],"entries":["e0041","e0042"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现患者多为农民和战士。"},{"t":"p","x":"发病前多有手足创伤和接触泥土、脏物史。好发于足部，手臂、手背等也可发生。"},{"t":"p","x":"潜伏期一般为2～3天。初起患肢有沉重、“胀裂样”疼痛，皮肤高度水肿，迅速蔓延成片，皮肤暗红。"},{"t":"p","x":"伴高热、寒战、头痛、烦躁、呕吐、面色苍白或神昏谵语；1～2天后，肿胀疼痛剧烈，皮肤上出现含暗红色液体的水疱，破后流出臭秽浆水。"},{"t":"p","x":"疮周紫黑，中央坏死，疮面略带凹形，轻按患处有捻发音，重按则有污脓溢出，稀薄如水，混以气泡。腐肉大片脱落，疮口日见扩大。"},{"t":"p","x":"若身热渐退，脓液转稠者，为转机之象；若高热持续不退，患处腐烂及肿势蔓延，是“走黄”之征，可有生命危险。"},{"t":"p","x":"(2)辅助检查脓液细菌培养可发现革兰染色阳性梭状芽孢杆菌。"},{"t":"p","x":"X线检查患部见气泡阴影。血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-6)"},{"t":"table","img":"img/tab/t0606.jpg","cap":"表6-6烂疔与流火、发的鉴别"}],"entries":["e0043"]},{"title":"治疗","blocks":[{"t":"p","x":"须中西医结合抢救治疗。湿火炽盛证，内治宜清热泻火、利湿解毒、和营散瘀，方予黄连解毒汤合萆薢化毒汤加减。"},{"t":"p","x":"毒入营血证，宜凉血解毒、清热利湿，予犀角地黄汤、黄连解毒汤合三妙丸加减。神昏谵语者加安宫牛黄丸或紫雪散。"},{"t":"p","x":"外治初起用玉露膏外敷，明确诊断后立即广泛、纵深切开，清创，引流畅通。用七三丹、五五丹或蟾酥合剂提脓祛腐。"},{"t":"p","x":"腐肉脱落，肉色鲜润红活者，用生肌散、红油膏盖贴。宜早期应用大剂量广谱抗生素。"},{"t":"p","x":"并予对症支持疗法。"}],"entries":["e0044"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.必须严格消毒隔离。用过的敷料应予焚毁，换药用具应彻底消毒。"},{"t":"p","x":"2.其他参照“手足部疔疮”。"}],"entries":["e0045"]}]},{"id":"d0602e","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"疫疔","displayName":"疔·疫疔","parentId":"d0602","printedPage":52,"pdfPage":67,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"疫疔是接触疫畜染毒所致的急性传染性疾病。其临床特点是多发于头面、颈、前臂等暴露部位，初起如虫叮水疱，很快干枯坏死如脐凹，全身症状明显，有传染性、职业性，可发生走黄。"},{"t":"p","x":"因具有传染性，其状如疔，故名疫疔，以其疮形如脐凹陷，又名鱼脐疔。本病首见于《诸病源候论·疔疮病诸候》。"},{"t":"p","x":"本病相当于西医学的皮肤炭疽。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病先有皮肤损伤感染疫毒，阻于肌肤，以致气血凝滞、邪毒蕴结而成。若疫毒内传脏腑，则导致走黄。"},{"t":"p","x":"西医学认为，本病由炭疽杆菌感染引起。其传染源主要是染疫食草动物和杂食动物，以及带菌动物的皮毛、肉及其产品。"}],"entries":["e0046","e0047"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于畜牧业、屠宰业或皮毛制革等工作者。"},{"t":"p","x":"常在接触疫畜或其皮毛后1～3天发病。好发于头面、颈项、手、臂等暴露部位。"},{"t":"p","x":"有传染性。初起皮损为一小红色斑丘疹，奇痒而不痛，全身微热。"},{"t":"p","x":"第2日丘疹顶部变成水疱。第3～4日水疱干燥，形成暗红色或黑色坏死，周围有成群的绿色小水疱，疮形如脐凹，同时局部肿势散漫，周围核肿大。"},{"t":"p","x":"伴有明显的发热、头痛骨楚、苔黄、脉数等症状。10～14日后，腐肉与正常皮肉开始分离，肿势日趋限局，身热渐退，腐肉脱落缓慢。"},{"t":"p","x":"3～4周方可愈合。若局部肿势继续发展，伴有壮热神昏、痰鸣喘急、身冷脉细者，为“走黄”之象。"},{"t":"p","x":"(2)辅助检查血液培养或疱液培养可发现革兰染色阳性炭疽杆菌。"},{"t":"p","x":"血常规示白细胞总数及中性粒细胞比例可增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-7)"},{"t":"table","img":"img/tab/t0607.jpg","cap":"表6-7疫疔与丹毒、颜面部疔疮的鉴别"}],"entries":["e0048"]},{"title":"治疗","blocks":[{"t":"p","x":"应注重预防，治疗宜清热解毒、和营消肿。原则上不做切开引流。"},{"t":"p","x":"常选仙方活命饮合黄连解毒汤加减。壮热神昏者，吞服安宫牛黄丸、紫雪丹等。"},{"t":"p","x":"外治：初、中期宜消肿解毒，用玉露膏掺蟾酥合剂或升丹外敷。也可用蟾酥丸研细外敷。"},{"t":"p","x":"后期腐肉未脱，改掺10%蟾酥合剂或五五丹。腐脱后见肉色鲜红，改掺生肌散，外盖红油膏。"},{"t":"p","x":"宜早期应用大剂量广谱抗生素。首选氟喹诺酮类药物。"},{"t":"p","x":"亦可用蟾酥丸、西黄丸口服。"}],"entries":["e0049"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.炭疽患者及病畜应予以隔离治疗。炭疽患者的分泌物、排泄物及医疗垃圾应消毒焚烧；皮损勿触摸、挤压。"},{"t":"p","x":"其个人物品应予以焚烧、高压灭菌及熏蒸处理；尸体应火化。销毁被污染的饲料，将牲畜从有感染的地区转移。"},{"t":"p","x":"2.对有风险人群进行健康教育，提高防护意识，从事相关工作时做好防护。3.根据传染病流行趋势，在流行地区对重点人群进行炭疽疫苗接种。"},{"t":"p","x":"同时对牲畜广泛接种疫苗，控制动物炭疽，减少人的感染。"}],"entries":["e0050"]}]},{"id":"d0603","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"痈","displayName":"痈","parentId":"","printedPage":53,"pdfPage":68,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"痈者，壅也，是指气血被邪毒壅聚而发生的化脓性疾病。在中医文献中，痈有“内痈”“外痈”之分。"},{"t":"p","x":"内痈是指生于脏腑间的化脓性疾患，其在内科学中有专门论述，本节只论述外痈。"},{"t":"p","x":"外痈是指发生于体表皮肉之间的急性化脓性疾病。"},{"t":"p","x":"其特点是局部光软无头，红肿疼痛(少数初起皮色不变)，结块范围多在6～9cm，发病迅速，易肿、易脓、易溃、易敛，或伴有恶寒发热、口渴等全身症状，一般不会损伤筋骨，也不易造成内陷。"},{"t":"p","x":"中医文献中，有很多关于痈的记载，如《景岳全书·外科钤·论证》曰：“痈者，热壅于外，阳毒之气也，其肿高，其色赤，其痛甚，其皮薄而泽，其脓易化，其口易敛，其来速者其愈亦速。"},{"t":"p","x":"《素问·生气通天论》曰：“营气不从，逆于肉理，乃生痈肿。”《灵枢·痈疽》曰：“热胜则肉腐，肉腐则为脓，然不能陷于骨髓，骨髓不为焦枯，五脏不为伤，故命曰痈。"},{"t":"p","x":"这些记载详细地论述了痈的病因病机、临床表现及转归预后。本病相当于西医学的皮肤浅表脓肿、急性化脓性淋巴结炎等。"},{"t":"p","x":"一般的痈发无定处，随处可生。因发病部位不同而名称繁多，包括生于颈部的颈痈、生于腋下的腋痈、生于肘部的肘痈、生于胯腹部的胯腹痈、生于委中穴的委中毒、生于脐部的脐痈。"},{"t":"p","x":"上述疾病除具有一般痈的共性外，又各有其特点，故分别论述，其他如囊痈、子痈、肛痈、乳痈等在病因、证治及转归等方面与上述痈不同、故分别在泌尿男性生殖系疾病、肛肠疾病、乳房疾病的相应章节中论述。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"外感六淫邪毒、皮肤外伤感染毒邪或过食膏粱厚味，聚湿生浊，邪毒湿浊留阻肌肤，郁结不散，皆可致营卫不和、气血凝滞、经络壅遏、化火为毒而成痈肿。"}],"entries":["e0051","e0052"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现痈可发生于体表的任何部位。"},{"t":"p","x":"初起在患处皮肉之间突然肿胀，光软无头，迅速结块，表皮焮红，灼热疼痛；少数病例初起皮色不变，到酿脓时才转为红色。"},{"t":"p","x":"轻者无全身症状，重者可伴恶寒发热、头痛、泛恶等全身症状。成脓在发病后7天左右，即使体质较差者亦不超过2周。"},{"t":"p","x":"局部肿势逐渐高突，疼痛加剧，痛如鸡啄。若按之中软有波动感者，为脓已成熟，多伴有发热持续不退等全身症状。"},{"t":"p","x":"溃后脓出多稠厚，色黄白。若为外伤血肿化脓，则可夹杂赤紫色血块；"},{"t":"p","x":"若疮口过小或袋脓，可致脓流不畅，影响愈合；若气血虚者、则脓水稀薄，疮面新肉难生，不易收口。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例可增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-8)"},{"t":"table","img":"img/tab/t0608.jpg","cap":"表6-8痈与脂瘤染毒、有头疽、发的鉴别"}],"entries":["e0053"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗宜清热解毒、和营消肿，并结合发病部位辨证用药。外治按一般阳证疮疡治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s060301","name":"火毒凝结证","clinic":"局部突然肿胀，光软无头，迅速结块，皮肤焮红，灼热疼痛，日后逐渐扩大，变成高肿发硬；重者可伴有恶寒发热，头痛，泛恶，口渴；舌苔黄腻、脉弦滑或洪数","treat":"清热解毒，行瘀活血","formula":"仙方活命饮加减。发于上部，加牛蒡子、野菊花；发于中部，加龙胆草、黄芩、栀子；发于下部，加苍术、黄柏、川牛膝","formulaNames":["仙方活命饮"]},{"t":"syn","sid":"s060302","name":"热胜肉腐证","clinic":"红热明显，肿势高突，疼痛剧烈，痛如鸡啄，溃后脓出则肿痛消退；舌红，苔黄，脉数","treat":"和营清热，透脓托毒","formula":"仙方活命饮合五味消毒饮加减","formulaNames":["仙方活命饮","五味消毒饮"]},{"t":"syn","sid":"s060303","name":"气血两虚证","clinic":"脓水稀薄，疮面新肉不生，色淡红而不鲜或暗红，愈合缓慢；伴面色无华，神疲乏力，纳少；舌质淡胖，苔少、脉沉细无力","treat":"益气养血，托毒生肌","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起用金黄膏，或用金黄散以冷开水调成糊状外敷。"},{"t":"p","x":"热盛者可用玉露膏或玉露散外敷，或太乙膏外敷，掺药均可用红灵丹或阳毒内消散。"},{"t":"p","x":"(2)成脓宜切开排脓，以得脓为度。"},{"t":"p","x":"(3)溃后先用药线蘸八二丹插入疮口，3～5日后改用九一丹，外盖金黄膏或玉露膏。"},{"t":"p","x":"待肿势消退十之八九时，改用红油膏盖贴。脓腐已尽，见出透明浅色黏液时，改用生肌散、太乙膏或生肌白玉膏或生肌玉红膏盖贴。"},{"t":"p","x":"(4)袋脓可先用垫棉法加压包扎，如无效可扩创引流。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)中成药可选用蟾酥丸、西黄丸口服。"},{"t":"p","x":"(2)西医治疗必要时可应用抗生素，并配合支持疗法。"}]}],"entries":["e0054","e0055","e0056","e0057","e0058","e0059"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持局部皮肤清洁。2.平素少食辛辣炙煿助火之物及肥甘厚腻之品，患病时忌烟酒及辛辣、鱼腥发物。"},{"t":"p","x":"3.有全身症状者宜静卧休息，并减少患部活动。"}],"entries":["e0060"]}]},{"id":"d0603a","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"颈痈","displayName":"痈·颈痈","parentId":"d0603","printedPage":55,"pdfPage":70,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"颈痈，俗名痰毒，又称时毒，是发生在颈部两侧的急性化脓性疾病。其临床特点是多见于儿童，冬春易发，初起时局部肿胀、灼热、疼痛而皮色不变，结块边界清楚，具有明显的风温外感症状。"},{"t":"p","x":"《疡科心得集·辨颈痈锁喉痈论》较详细地论述了颈痈的病因病机：“颈痈生于颈之两旁，多因风温痰热而发。盖风温外袭，必鼓动其肝木，而相火亦因之俱动，相火上逆，脾中痰热随之，颈为少阳络脉循行之地，其循经之邪至此而结，故发痈也。"},{"t":"p","x":"本病相当于西医学的颈部急性化脓性淋巴结炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生多由外感风温、风热之邪，内伤情志，气郁化火，以致外邪内热夹痰蕴结于少阳、阳明经络，气血凝滞，热胜肉腐而成，或因患乳蛾、口疳、龋齿或头面疮疔毒邪流窜至颈部而成。"}],"entries":["e0061","e0062"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于儿童，冬春季易发。"},{"t":"p","x":"发病前多有乳蛾、口疳、龋齿或头面疮疔，或附近有皮肤黏膜破伤病史。多生于颈旁两侧，也可发生于耳后、颌下、颏下。"},{"t":"p","x":"初起结块形如鸡卵，皮色不变，肿胀，灼热，疼痛，活动度不大，逐渐漫肿坚实，焮热疼痛。伴有寒热、头痛、项强等症状。"},{"t":"p","x":"若4～5日后发热不退，皮色渐红，肿势高突，疼痛加剧如鸡啄，伴口干、便秘、溲赤等症状，是欲成脓。至7～10日按之中软而有波动感者，为脓已成。"},{"t":"p","x":"溃后脓出黄白稠厚，肿退痛减，10～14日可以愈合。若火毒炽盛或素体虚弱，病变可向对侧蔓延，或压迫结喉，形成锁喉痈、甚则危及生命。"},{"t":"p","x":"部分病例因大量使用抗生素或苦寒药物治疗，形成慢性迁延性炎症者，结块质地较坚硬，需1～2个月后才能消散。如不能控制病情、也会再次出现红肿热痛而化脓。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例可增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-9)"},{"t":"table","img":"img/tab/t0609.jpg","cap":"表6-9颈痈、痄腮与臖核的鉴别"}],"entries":["e0063"]},{"title":"治疗","blocks":[{"t":"p","x":"宜散风清热、解毒化痰，以达到消肿止痛的目的。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0603a01","name":"风热痰毒证","clinic":"颈旁结块，初起色白濡肿，形如鸡卵，灼热疼痛，逐渐红肿化脓；伴有恶寒发热，头痛，项强，咽痛，口干，溲赤，便秘。苔薄腻，脉滑数","treat":"散风清热，化痰消肿","formula":"牛蒡解肌汤或银翘散加减。成脓时加皂角刺等","formulaNames":["牛蒡解肌汤","银翘散"]},{"t":"p","x":"成脓时加皂角刺等。2.外治疗法参见“痈”。"}],"entries":["e0064","e0065"]},{"title":"预防与调护","blocks":[{"t":"p","x":"参见“痈”。"}],"entries":["e0066"]}]},{"id":"d0603b","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"腋痈","displayName":"痈·腋痈","parentId":"d0603","printedPage":56,"pdfPage":71,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"腋痈，又名夹肢痈，是发生于腋窝的急性化脓性疾病。其临床特点是腋下暴肿、灼热、疼痛而皮色不变，发热恶寒，上肢活动不利，约2周成脓，溃后容易形成袋脓。"},{"t":"p","x":"本病相当于西医学的腋部急性化脓性淋巴结炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"腋痈常由上肢皮肤破损染毒，或有疮疡等病灶，毒邪循经流窜至腋部所致，或因肝脾郁热，兼忿怒气郁，导致气滞血壅，经脉阻滞而成。"}],"entries":["e0067","e0068"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现发病前多有手部或臂部皮肤皲裂、破损或疮疡等病史。"},{"t":"p","x":"初起多见腋部肿胀，皮色不变，灼热疼痛，同时上肢活动不利，伴有恶寒发热、纳呆等症状。若疼痛日增、寒热不退，势在酿脓。"},{"t":"p","x":"经10～14天肿块中间变软，皮色转红，按之波动感明显，为脓已成，应切开排脓。若流出的脓液稠厚，肿消痛止，则疮口容易收敛；"},{"t":"p","x":"若切开或溃后脓流不尽，肿势不退，多因切口太小，或因任其自溃而疮口过小，或因疮口位置偏高，导致袋脓。此时需及时扩创，否则可迁延日久，难以收口。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-10)"},{"t":"table","img":"img/tab/t0610.jpg","cap":"表6-10腋痈与腋疽的鉴别"}],"entries":["e0069"]},{"title":"治疗","blocks":[{"t":"p","x":"内治以清肝解郁、消肿化毒为主。外治注意低位引流，必要时加用垫棉法，以促进早日愈合。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0603b01","name":"肝郁痰火证","clinic":"腋部肿胀热痛；伴有发热，头痛，胸胁牵痛；舌质红，苔黄，脉弦数","treat":"清肝解郁，消肿化毒","formula":"柴胡清肝汤加减。脓成加皂角刺等","formulaNames":["柴胡清肝汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)参照“痈”。"},{"t":"p","x":"(2)脓成切开时宜循经直开，低位引流，切口适宜。"},{"t":"p","x":"若有袋脓应及时扩创，疮口将敛时需应用垫棉压迫，紧压疮口，以加速愈合。"}]}],"entries":["e0070","e0071","e0072"]},{"title":"预防与调护","blocks":[{"t":"p","x":"参照“痈”。"}],"entries":["e0073"]}]},{"id":"d0603c","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"脐痈","displayName":"痈·脐痈","parentId":"d0603","printedPage":57,"pdfPage":72,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"脐痈是生于脐部的急性化脓性疾病。其临床特点是初起脐部微肿，渐大如瓜，溃后脓稠无臭则易敛，脓水臭秽则成漏。"},{"t":"p","x":"本病相当于西医学的脐炎，或卵黄管残留、脐尿管异常继发感染。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"脐痈多先有脐部湿疮出水，复因搔抓染毒，或先天脐部发育不良，又有心脾湿热，下移于小肠，致使火毒结聚脐部，血凝毒滞而成。若日久不愈可致心脾两伤，气血耗损，余毒难尽而成脐漏。"}],"entries":["e0074","e0075"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病前往往有脐孔湿疮病史、或脐孔曾有尿液或粪便排出史。"},{"t":"p","x":"初起脐部微痛微肿、皮色或红或白，渐渐肿大如瓜、或高突如铃，根盘较大，触痛明显，或绕脐而生。酿脓时可伴有恶寒发热等全身症状。"},{"t":"p","x":"溃后若脓水稠厚无臭味者易敛；若脓出臭秽，或夹有粪块样物质，脐孔正中下方触及条状硬结者，往往形成脐漏、日久不易收口。"},{"t":"h","lv":3,"x":"(2)辅助检查久不收口者，应做瘘管造影以明确诊断。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-11)"},{"t":"table","img":"img/tab/t0611.jpg","cap":"表6-11脐痈与脐疮的鉴别"}],"entries":["e0076"]},{"title":"治疗","blocks":[{"t":"p","x":"以清火利湿解毒为主。对溃破成漏者应进行手术治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0603c01","name":"湿热火毒证","clinic":"脐部红肿高突，灼热疼痛；伴恶寒发热，纳呆口苦；舌苔薄黄，脉滑数","treat":"清火利湿解毒","formula":"黄连解毒汤合四苓散加减。脓成或溃脓不畅，加皂角刺、生黄芪；热毒炽盛者，加败酱草、红藤；脐周肿痒，加苦参、白鲜皮","formulaNames":["黄连解毒汤","四苓散"]},{"t":"syn","sid":"s0603c02","name":"脾气虚弱证","clinic":"溃后脓出臭秽，或夹有粪汁，或排出尿液，或脐部胬肉外翻，久不收敛；伴面色萎黄，肢软乏力，纳呆，便溏；舌苔薄，脉濡","treat":"健脾益气托毒","formula":"四君子汤合托里透脓汤加减","formulaNames":["四君子汤","托里透脓汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)参照“痈”。"},{"t":"p","x":"(2)成漏者疮口中可插入七三丹药线提脓，待脓腐脱尽后加用垫棉法。"},{"t":"p","x":"3.其他疗法对反复发作，或久不收口而成漏者，可行手术治疗。"}]}],"entries":["e0077","e0078","e0079","e0080"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.参照“痈”。2.保持脐部清洁、干燥，勿用手抠挖、搔抓。"},{"t":"p","x":"3.积极治疗脐部先天性疾病。"}],"entries":["e0081"]}]},{"id":"d0603d","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"委中毒","displayName":"痈·委中毒","parentId":"d0603","printedPage":59,"pdfPage":74,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"委中毒是发生在腘窝委中穴的急性化脓性疾病。"},{"t":"p","x":"其临床特点是初起木硬疼痛，皮色不红，小腿屈伸不利；愈后可有短期屈曲难伸。本病相当于西医学的腘窝部急性化脓性淋巴结炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"寒湿侵袭，蕴积化热，或湿热下注，或患肢皮肤破伤(足跟皱裂、冻疮溃烂、脚湿气、湿疮等)感染毒邪，致使湿热蕴阻，经络阻隔，气血凝滞而成。"}],"entries":["e0082","e0083"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现发病前多有患侧足、腿皮肤破伤史。"},{"t":"p","x":"初起在委中穴木硬疼痛，皮色如常或微红，形成结块后患侧小腿屈伸困难，行动不便。伴有恶寒发热、纳呆等症状。"},{"t":"p","x":"若肿痛加剧，身热不退，2～3周后可成脓。溃后2周左右疮口愈合。"},{"t":"p","x":"脓成后切口过小或位置偏高，或任其自溃，脓出不畅，可影响疮口愈合。疮口愈合后患肢仍然屈曲难伸者，需经2～3个月的功能锻炼方可恢复正常。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-12)"},{"t":"table","img":"img/tab/t0612.jpg","cap":"表6-12委中毒与胶瘤的鉴别"}],"entries":["e0084"]},{"title":"治疗","blocks":[{"t":"p","x":"治以清热利湿、和营祛瘀为主。初起重在消散，脓成宜透脓托毒，溃后气血已亏者则宜益气养血、生肌收口。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0603d01","name":"气滞血瘀证","clinic":"初起木硬疼痛，皮色如常或微红，活动稍受限；伴恶寒发热；舌苔白腻，脉滑数","treat":"和营活血，消肿散结","formula":"活血散瘀汤加减","formulaNames":["活血散瘀汤"]},{"t":"syn","sid":"s0603d02","name":"湿热蕴阻证","clinic":"腘窝部木硬肿胀，焮红疼痛，小腿屈曲难伸；伴恶寒发热，口苦且干、纳呆；舌苔黄腻，脉滑数","treat":"清利湿热，和营活血","formula":"活血散瘀汤合五神汤加减","formulaNames":["活血散瘀汤","五神汤"]},{"t":"syn","sid":"s0603d03","name":"气血两亏证","clinic":"起发缓慢，脓成难溃，溃后脓出如蛋清状，疮口收敛迟缓，小腿屈伸不利；舌质淡，苔薄或薄腻、脉细","treat":"调补气血","formula":"八珍汤加减","formulaNames":["八珍汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)参照“痈”。"},{"t":"p","x":"(2)脓成后应切开引流。"},{"t":"p","x":"切开引流时、一般实行切口方向与腘横纹平行的横切口或“S”形切口，尽量避免越过关节，以免瘢痕形成影响关节功能。若溃后流脓不畅，多因切口过小，以致形成袋脓，需及时扩创。"},{"t":"p","x":"脓出如鸡蛋清样黏液时，即停用药线，改用生肌散收口，并以棉垫紧压疮口，可加速愈合。"}]}],"entries":["e0085","e0086","e0087","e0088","e0089"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.参照“痈”。2.愈后患肢筋缩难伸者，可加强患肢功能锻炼，直至功能恢复。"}],"entries":["e0090"]}]},{"id":"d0604","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"发","displayName":"发","parentId":"","printedPage":60,"pdfPage":75,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"发是病变范围较痈大的急性化脓性疾病。其临床特点是初起无头，红肿蔓延成片，中央明显，四周较淡、边界不清，灼热疼痛，有的3～5日后中央色褐腐溃，周围湿烂，或中软而不溃，全身症状明显。"},{"t":"p","x":"本病相当于西医学的蜂窝织炎。在中医文献中，发常和痈、有头疽共同命名。"},{"t":"p","x":"有些虽名为发，其实属于有头疽的范畴，如《外科启玄》中的“体疽发”“对心发”“莲子发”等虽有发的病名，实质均是有头疽。此外，有些痈之大者属发的范畴，应命名为发，但文献中亦有称作痈的，如锁喉痈、臀痈等。"},{"t":"p","x":"常见的发有发生于结喉处的锁喉痈、生于臀部的臀痈、生于手背部的手发背、生于足背的足发背，虽均属发的范围，但因证治不同，故分别叙述。"}],"entries":["e0091"]}]},{"id":"d0604a","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"锁喉痈","displayName":"发·锁喉痈","parentId":"d0604","printedPage":60,"pdfPage":75,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"锁喉痈又称猛疽、结喉痈，是发于颈前正中结喉处的急性化脓性疾病，因其红肿绕喉故名，俗称盘颈痰毒。"},{"t":"p","x":"其临床特点是来势暴急，初起结喉处红肿绕喉，根脚散漫，坚硬灼热疼痛，范围较大，肿势蔓延至颈部两侧、腮颊及胸前，可连及咽喉、舌下，并发喉风、重舌甚至痉厥等险症，伴壮热口渴、头痛项强等全身症状。"},{"t":"p","x":"本病相当于西医学的口底部蜂窝织炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因外感风温，客于肺胃，或患痧痘、麻疹之后，体虚余毒未清，或素体虚弱，口唇齿龈生疮、咽喉糜烂等感染邪毒，导致痰热上蕴结喉，气血凝滞、热胜肉腐而成。"}],"entries":["e0092","e0093"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现多发生于儿童，发病前有口唇、咽喉糜烂及痧痘史。"},{"t":"p","x":"结喉部红肿绕喉，根脚散漫，坚硬灼热疼痛，来势凶猛。经2～3天后，肿势可延及两颈，甚至上延腮颊，下至胸前。"},{"t":"p","x":"可因肿连咽喉、舌下而并发喉风、重舌以致汤水难下。伴有壮热口渴，头痛项强，大便秘结，小便短赤，甚至气喘痰壅而发生痉厥。"},{"t":"p","x":"若肿势渐趋局限，按之中软应指者，为脓已成熟。溃后脓出黄稠、热退肿消者，病情轻；"},{"t":"p","x":"溃后脓出稀薄、疮口有空壳，或脓从咽喉部溃出，全身虚弱者，病情重，收口亦慢。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-13)"},{"t":"table","img":"img/tab/t0613.jpg","cap":"表6-13锁喉痈、颈痈与瘿痈的鉴别"}],"entries":["e0094"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗宜清热解毒、化痰消肿。病初兼用疏风清热之品；中期佐以凉血透脓；后期应顾护气血津液及脾胃。"},{"t":"p","x":"成脓后应及早切开减压。必要时配合西医治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0604a01","name":"痰热蕴结证","clinic":"红肿绕喉，坚硬疼痛，肿势散漫；壮热口渴，头痛项强，大便燥结，小便短赤；舌红绛，苔黄腻、脉弦滑数或洪数","treat":"散风清热，化痰解毒","formula":"普济消毒饮加减。壮热口渴者，加生地黄、天花粉、生石膏；便秘者，加枳实、生大黄、芒硝；气喘痰壅者，加鲜竹沥、天竺黄、莱菔子；痉厥者，加安宫牛黄丸化服，或紫雪散吞服","formulaNames":["普济消毒饮"]},{"t":"syn","sid":"s0604a02","name":"热胜肉腐证","clinic":"肿势局限，按之中软应指，脓出黄稠，热退肿减；舌红，苔黄，脉数","treat":"清热化痰，和营托毒","formula":"仙方活命饮加减","formulaNames":["仙方活命饮"]},{"t":"syn","sid":"s0604a03","name":"热伤胃阴证","clinic":"溃后脓出稀薄，疮口有空壳，或脓从咽喉溃出，收口缓慢；胃纳不香，口干少津；舌光红，脉细","treat":"清养胃阴","formula":"益胃汤加减","formulaNames":["益胃汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起用玉露散、金黄散或双柏散以金银花露或菊花露调敷。"},{"t":"p","x":"(2)成脓应及早切开引流。"},{"t":"p","x":"(3)溃后用九一丹药线引流，外盖金黄膏或红油膏。"},{"t":"p","x":"脓尽改用生肌散、白玉膏。"}]}],"entries":["e0095","e0096","e0097","e0098","e0099"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极处理原发病灶。2.高热时应卧床休息，气喘痰壅时取半卧位。"},{"t":"p","x":"初期、成脓期宜进半流质饮食。"}],"entries":["e0100"]}]},{"id":"d0604b","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"臀痈","displayName":"发·臀痈","parentId":"d0604","printedPage":61,"pdfPage":76,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"臀痈是发生于臀部肌肉丰厚处范围较大的急性化脓性疾病。"},{"t":"p","x":"由肌内注射引起者俗称针毒。《医宗金鉴·外科心法要诀·臀痈》中记载：“臀痈证属膀胱经，坚硬闷肿湿热凝，肉厚之处迟溃敛，最宜红活高肿疼。"},{"t":"p","x":"《洞天奥旨·臀痈》曰：“臀之上乃足太阳膀胱之所属也。本经多血少气，而臀上尤气之难周到者也、故不生痈则已，一生痈则肉必大疼，以气少不及运动耳。"},{"t":"p","x":"总的来说，臀痈的临床特点可概括为发病来势急，病位深、范围大，难于起发，成脓较快，但腐溃较难，收口亦慢。本病相当于西医学的臀部蜂窝织炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"急性者多由湿热火毒内生，或臀部注射时感染毒邪，亦可从局部疮疔发展而来，导致湿热火毒相互搏结，逆于肉理，营气不从、肉腐化脓而成。慢性者多由湿痰凝结，或注射药液吸收不良所致。"}],"entries":["e0101","e0102"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现局部常有注射史，或患疮疖、或臀部周围有皮肤破损病灶。"},{"t":"p","x":"急性者多由于肌内注射染毒引起，臀部一侧初起疼痛、肿胀焮红，患肢步行困难、皮肤红肿以中心最为明显而四周较淡，边缘不清，红肿逐渐扩大而有硬结。2～3天后皮肤湿烂，随即变成黑色腐溃，或中软不溃。"},{"t":"p","x":"溃后一般脓稠，若伴有大块腐肉脱落，以致疮口深大而形成空腔，则收口甚慢，需1个月左右方能痊愈。初起即伴有恶寒发热、头痛、骨节酸痛及胃纳不佳等全身症状，酿脓时壮热不退，待脓出腐脱后诸症逐渐减轻。"},{"t":"p","x":"慢性者初起多漫肿、皮色不变，红热不显而结块坚硬，有疼痛或压痛，患肢步行不便，进展较为缓慢，全身症状也不明显。一般经过治疗后，多能自行消退。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-14)"},{"t":"table","img":"img/tab/t0614.jpg","cap":"表6-14臀痈、有头疽与流注的鉴别"}],"entries":["e0103"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗以清热利湿解毒为主。外治切开排脓时，切口应取低位、够大够深，以排脓通畅为目的。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0604b01","name":"湿火蕴结证","clinic":"臀部先痛后肿，焮红灼热，或湿烂溃脓；伴恶寒发热，头痛骨楚，食欲不振；舌质红，苔黄或黄腻，脉数","treat":"清热解毒，和营化湿","formula":"黄连解毒汤合仙方活命饮加减。局部红热不显者，加重活血祛瘀之品，如桃仁、红花、泽兰，适当减少清热解毒之品","formulaNames":["黄连解毒汤","仙方活命饮"]},{"t":"syn","sid":"s0604b02","name":"湿痰凝滞证","clinic":"漫肿不红，结块坚硬，病情进展缓慢；多无全身症状；舌苔薄白或白腻，脉缓","treat":"和营活血，利湿化痰","formula":"桃红四物汤合仙方活命饮加减","formulaNames":["桃红四物汤","仙方活命饮"]},{"t":"syn","sid":"s0604b03","name":"气血两虚证","clinic":"溃后腐肉大片脱落，疮口较深，形成空腔，收口缓慢；面色萎黄，神疲乏力，纳谷不香；舌质淡，苔薄白、脉细","treat":"调补气血","formula":"八珍汤加减","formulaNames":["八珍汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)未溃红热明显者用玉露膏，红热不显者用金黄膏或冲和膏外敷。"},{"t":"p","x":"(2)成脓宜切开排脓。"},{"t":"p","x":"切口应注意低位、够大够深，并清除腐肉，以排脓顺畅为目的。"},{"t":"p","x":"(3)溃后用八二丹、红油膏盖贴，脓腔深者用药线引流；"},{"t":"p","x":"脓尽用生肌散、白玉膏收口；疮口有空腔不易愈合者，用垫棉法加压促进愈合。"}]}],"entries":["e0104","e0105","e0106","e0107","e0108"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.患病后宜少活动，否则易使肿势扩散而病情加剧。2.肌内注射必须注意消毒、并注意使粉针剂充分溶解后再注射。"}],"entries":["e0109"]}]},{"id":"d0604c","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"手发背","displayName":"发·手发背","parentId":"d0604","printedPage":63,"pdfPage":78,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"手发背又名手背毒、手背发、蜘蛛背，是发于手背部的急性化脓性疾病。其临床特点是全手背漫肿，红热疼痛，手心不肿，若溃迟敛难，久则损筋伤骨。"},{"t":"p","x":"本病相当于西医学的手背部蜂窝织炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多由饮食不节，情志内伤，湿火内生，或局部外伤染毒，导致湿热结聚手背，气血壅滞，热胜肉腐所致。"}],"entries":["e0110","e0111"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现初起手背漫肿，边界不清，胀痛不舒，或有怕冷、发热等全身症状。"},{"t":"p","x":"在7～10天时化脓，患部中间肿胀高突，皮色紫红，灼热疼痛如鸡啄，全身症状加重。若按之有波动感者，为脓已成。"},{"t":"p","x":"溃破时皮肤湿烂，脓水色白或黄，或夹有血水，逐渐脓少而愈合。如2～3周肿势不趋限局，溃出脓稀薄而臭，是为损骨之征。"},{"t":"p","x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"p","x":"X线摄片可确定有无死骨。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-15)"},{"t":"table","img":"img/tab/t0615.jpg","cap":"表6-15手发背、托盘疔与毒虫咬伤的鉴别"}],"entries":["e0112"]},{"title":"治疗","blocks":[{"t":"p","x":"初起宜清热解毒、利湿消肿、脓成后宜透脓托毒、溃后则宜补益生肌。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0604c01","name":"湿热壅阻证","clinic":"手背漫肿、红热疼痛，化脓溃破、伴皮肤湿烂，易损筋伤骨，疮口难愈；或伴壮热恶寒，头痛骨楚；舌苔黄腻、脉数","treat":"清热解毒，和营化湿","formula":"五味消毒饮合仙方活命饮加减","formulaNames":["五味消毒饮","仙方活命饮"]},{"t":"syn","sid":"s0604c02","name":"气血不足证","clinic":"日久肿势不趋限局，溃后脓液稀薄；伴神疲乏力；舌质淡，苔薄，脉细","treat":"调补气血","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起用金黄膏或玉露膏外敷。"},{"t":"p","x":"(2)脓成切开排脓。"},{"t":"p","x":"(3)溃后八二丹药线引流，红油膏盖贴；脓尽改用生肌散、白玉膏。"}]}],"entries":["e0113","e0114","e0115","e0116"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强劳动保护，若手部外伤，应及时治疗，勿使毒邪从皮肤破损处乘隙而入。2.患手忌持重，并用三角巾悬吊固定，手背朝下以利引流。"},{"t":"p","x":"3.疮口收敛后，可加强患肢功能锻炼以恢复其功能。"}],"entries":["e0117"]}]},{"id":"d0604d","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"足发背","displayName":"发·足发背","parentId":"d0604","printedPage":64,"pdfPage":79,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"足发背是发于足背部的急性化脓性疾病。"},{"t":"p","x":"其临床特点是全足背高肿炊红疼痛，足心不肿。本病相当于西医学的足背部蜂窝织炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因局部外伤感染毒邪，或湿热下注，导致湿热毒邪壅阻肌肤，气血凝滞，热胜肉腐而成。"}],"entries":["e0118","e0119"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现初起足背红肿灼热疼痛，肿势弥漫，边界不清，影响活动。"},{"t":"p","x":"一般5～7天迅速增大化脓，伴有寒战高热、纳呆、泛恶等全身症状。溃破后脓出稀薄，夹有血水，皮肤湿烂，全身症状多随之减轻。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-16)"},{"t":"table","img":"img/tab/t0616.jpg","cap":"表6-16足发背与丹毒的鉴别"}],"entries":["e0120"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗以清热利湿解毒为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0604d01","name":"湿热下注证","clinic":"足背红肿弥漫，灼热疼痛，化脓溃破；伴寒战高热，纳呆，或泛恶；舌质红，苔黄腻，脉滑数","treat":"清热解毒，和营利湿","formula":"五神汤加减。成脓者加皂角刺","formulaNames":["五神汤"]},{"t":"p","x":"成脓者加皂角刺。2.外治疗法参照“手发背”。"}],"entries":["e0121","e0122"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.患足忌行走。宜抬高患肢，并使患足置于有利于脓液引流的位置。"},{"t":"p","x":"2.有足部外伤时应及时治疗，勿使毒邪从皮肤破损处乘隙而入。"}],"entries":["e0123"]}]},{"id":"d0605","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"有头疽","displayName":"有头疽","parentId":"","printedPage":65,"pdfPage":80,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"有头疽是发生于肌肤间的急性化脓性疾病。"},{"t":"p","x":"其临床特点是初起皮肤上即有粟粒样脓头，焮热红肿胀痛，迅速向深部及周围扩散，脓头相继增多，溃烂后状如莲蓬、蜂窝，范围常超过9cm，大者可在30cm以上。"},{"t":"p","x":"好发于项后、背部等皮肤厚韧之处，多见于中老年人及消渴病患者，并容易发生内陷。《疡科心得集·辨脑疽对口论》中载本病“初起形色俱不正，寒热不加重，身虽发热，面色形寒，疡不高肿，根盘平塌，散漫不收”。"},{"t":"p","x":"有头疽在古代文献中常以疽和发共同命名，根据发病部位不同有多种病名。如生在头顶部的称百会疽；"},{"t":"p","x":"生于鬓角者，称鬓疽；生于项部者，名脑疽，又名对口疮、对口发；"},{"t":"p","x":"发于脊背部正中者，称为背疽，又名发背；生于背部两侧的称搭手，又分上搭手、中搭手、下搭手等；"},{"t":"p","x":"生于少腹部者，名少腹疽；生于四肢部者，名太阴疽、石榴疽、臀疽、腿疽等。"},{"t":"p","x":"根据发病原因不同亦有多种病名。如过饮药酒兼厚味，积毒蕴发者，称酒毒发；湿痰郁结而成者，称痰注发。"},{"t":"p","x":"还有以形状命名者，如莲子发、蜂窝发等；以穴位命名者，如百会疽、膻中疽、中脘疽等。然其病因病机、临床表现和治疗方法基本相似，故并作有头疽论述。"},{"t":"p","x":"本病相当于西医学的痈。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.外感风温、湿热，邪毒凝聚肌表，以致气血运行失常而成。2.情志内伤，恼怒伤肝，思虑伤脾，肝脾郁结，气郁化火；"},{"t":"p","x":"或劳伤虚损，恣欲伤肾，劳伤精气，肾水亏损，相火炽盛；或恣食膏粱厚味，脾胃运化失常，湿热火毒内生。"},{"t":"p","x":"以上均能导致脏腑蕴毒而发。本病总由外感风温、湿热，内有脏腑蕴毒，内外邪毒互相搏结，凝聚肌肤，以致营卫不和，气血凝滞，经络阻隔而成。"},{"t":"p","x":"素体虚弱时更易发生，如消渴病患者常易并发本病。若阴虚之体，水亏火炽，则热毒蕴结更甚；"},{"t":"p","x":"若气血虚弱之体，正虚毒滞难化，不能透毒外出。此两者均可使病情加剧、甚至发生疽毒内陷。"},{"t":"p","x":"西医学认为，本病是由金黄色葡萄球菌感染引起的多个相邻的毛囊及其所属皮脂腺或汗腺的急性化脓性疾病。"}],"entries":["e0124","e0125"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现凡在皮肤坚韧、肌肉丰厚之处均可发生，以项、背部为多见。"},{"t":"p","x":"好发于成年人、以中老年人居多。初期：局部红肿结块，肿块上有粟粒状脓头，作痒作痛，逐渐向周围和深部扩散，脓头增多，色红、灼热、疼痛。"},{"t":"p","x":"伴有恶寒发热、头痛、食欲不振、舌苔白腻或黄腻、脉多滑数或洪数等明显的全身症状。此为一候。"},{"t":"p","x":"溃脓期：疮面腐烂、形似蜂窝、肿势范围大小不一，常超过10cm，甚至大逾盈尺；伴高热口渴，便秘溲赤。"},{"t":"p","x":"如脓液畅泄、腐肉逐渐脱落、红肿热痛随之减轻，全身症状也渐减或消失。此为二至三候，病变范围大者往往需3～4周。"},{"t":"p","x":"收口期：脓腐渐尽，新肉生长、肉色红活、逐渐收口而愈。亦有少数病例腐肉虽脱，但新肉生长迟缓。"},{"t":"p","x":"此为四候、常需1～3周。一般而言、发于项背部的病情较重，不易透脓，内陷变证多见；"},{"t":"p","x":"发于四肢部的病情较轻，容易透脓、内陷变证少见。但病情的轻重、顺逆、是否内陷，与热毒的轻重、气血的盛衰、患者年龄的大小等均有密切关系。"},{"t":"p","x":"若兼见神昏谵语、气息急促、恶心呕吐、腰痛、尿少、尿赤、发斑等严重全身症状者，为合并内陷。体虚或消渴病患者容易并发内陷。"},{"t":"p","x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显升高。"},{"t":"p","x":"脓液培养多见金黄色葡萄球菌生长。糖尿病患者血糖水平升高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-17)"},{"t":"table","img":"img/tab/t0617.jpg","cap":"表6-17有头疽、发际疮与脂瘤染毒的鉴别"}],"entries":["e0126"]},{"title":"治疗","blocks":[{"t":"p","x":"应明辨虚实，分证论治，谨防疽毒内陷。积极治疗消渴等病，必要时配合西医西药治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s060501","name":"火毒凝结证","clinic":"多见于壮年正实邪盛者。局部红肿高突，灼热疼痛，根脚收束，迅速化脓脱腐，脓出黄稠；伴发热，口渴，尿赤；舌苔黄，脉数有力","treat":"清热泻火，和营托毒","formula":"黄连解毒汤合仙方活命饮加减。恶寒发热者，加荆芥、防风；便秘者，加生大黄、枳实；溲赤者，加萆薢、车前子","formulaNames":["黄连解毒汤","仙方活命饮"]},{"t":"syn","sid":"s060502","name":"湿热壅滞证","clinic":"局部症状与火毒凝结证相同；伴全身壮热，朝轻暮重，胸闷呕恶；舌苔白腻或黄腻，脉濡数","treat":"清热化湿、和营托毒","formula":"仙方活命饮加减。胸闷呕恶者，加藿香、佩兰、厚朴","formulaNames":["仙方活命饮"]},{"t":"syn","sid":"s060503","name":"阴虚火炽证","clinic":"多见于消渴病患者。肿势平塌，根脚散漫，皮色紫滞，脓腐难化，脓水稀少或带血水，疼痛明显；伴发热烦躁，口干唇燥，饮食少思，大便秘结，小便短赤；舌质红，苔黄少津，脉细弦数","treat":"滋阴生津，清热托毒","formula":"竹叶黄芪汤加减。初起加天花粉、金银花、连翘，溃脓期加皂角刺，溃后加西洋参","formulaNames":["竹叶黄芪汤"]},{"t":"syn","sid":"s060504","name":"气虚毒滞证","clinic":"多见于年迈体虚、气血不足患者。肿势平塌，根脚散漫，皮色灰暗不泽，化脓迟缓，腐肉难脱，脓液稀少，色带灰绿，闷肿胀痛，容易形成空腔；伴低热，小便频数，口渴喜饮，精神萎靡，面色少华；舌质淡红，苔白或微黄，脉数无力","treat":"扶正托毒","formula":"托里排脓汤加减","formulaNames":["托里排脓汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起患部红肿，脓头尚未溃破，属火毒凝结证或湿热壅滞证，用金黄膏或千捶膏外敷；"},{"t":"p","x":"阴虚火炽证或气虚毒滞证用冲和膏外敷。"},{"t":"p","x":"(2)酿脓期以八二丹掺疮口；如脓水稀薄而带灰绿色者，改用七三丹，外敷金黄膏。"},{"t":"p","x":"(3)脓肿形成采用手术扩创排脓，行“十”字形或“双十”字形切开，务求脓泄畅达。"},{"t":"p","x":"如大块坏死组织一时难脱，可分次祛除，以不出血为度。切开时应注意尽量保留皮肤，以减少愈合后瘢痕形成。"},{"t":"p","x":"(4)溃后期若脓腐阻塞疮口，脓液蓄积，引流不畅者，可用五五丹药线或八二丹药线多枚分别插入疮口，蚀脓引流；"},{"t":"p","x":"或用棉球蘸五五丹或八二丹，松松填于脓腔以祛腐。待脓腐大部脱落，疮面渐洁，改掺九一丹，外敷红油膏。"},{"t":"p","x":"疮面脓腐已净，新肉渐生，以生肌散掺疮口，外敷白玉膏。若疮口有空腔，皮肤与新肉一时不能黏合者，可用垫棉法加压包扎。"},{"t":"p","x":"需要注意的是，初起脓栓未松动时，不可强行剥出，以防止毒邪扩散；后期毒邪未尽应慎用垫棉法，以免毒邪不得外泄反陷入里。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)糖尿病患者需降糖治疗。"},{"t":"p","x":"(2)根据病情及脓液培养的结果选用抗生素治疗。"}]}],"entries":["e0127","e0128","e0129","e0130","e0131","e0132","e0133"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持疮周皮肤清洁，及时更换敷料，以免脓水浸淫。2.切忌挤压。"},{"t":"p","x":"患在项部者，可用四头带包扎；患在背部者，睡时宜侧卧；"},{"t":"p","x":"患在上肢者，宜用三角巾悬吊；患在下肢者，宜抬高患肢，减少活动。"},{"t":"p","x":"3.严密观察病情，防止内陷发生。"}],"entries":["e0134"]}]},{"id":"d0606","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"流注","displayName":"流注","parentId":"","printedPage":67,"pdfPage":82,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"流注是发于肌肉深部的急性化脓性疾病。"},{"t":"p","x":"其临床特点是好发于四肢、躯干肌肉丰厚处的深部或髂窝部，发病急，局部漫肿疼痛，皮色如常，易走窜，常见此处未愈，他处又起。《医宗金鉴·外科心法要诀》载其“流者流行，注者住也。"},{"t":"p","x":"发无定处，随在可生”。本病相当于西医学的脓血症、多发性肌肉深部脓肿及髂窝部脓肿。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总因正气不足，邪毒流窜，经络气血凝滞而成。1.暑湿流注因夏秋季节感受暑湿，客于营卫。阻于肌肉而成。"},{"t":"p","x":"2.余毒流注因患疔疮、疖、痈强行挤压或过早切开，或其他热病失治使热毒窜入血分，稽留肌肉而发。3.瘀血流注多因跌打损伤瘀血，或产后恶露停滞，壅滞经络而成。"},{"t":"p","x":"4.髂窝流注除上述病因外，会阴、肛门、外阴、下肢破损或生疮疖，或附近脏器染毒阻滞经络亦可成。西医学认为、本病的主要致病菌是金黄色葡萄球菌，其次是溶血性链球菌。"},{"t":"p","x":"致病菌经血液循环至软组织，停留凝聚而成脓肿。"}],"entries":["e0135","e0136"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现除头面、前后二阴、腕、踝等远端少见外，余部位均可发生，尤以腰、臀、大腿后部、髂窝部多见。"},{"t":"p","x":"初起四肢近端或躯干有一处或数处肌肉疼痛漫肿、微热而皮色不变。2～3天后肿胀、焮热、疼痛明显，可扪及肿块；伴寒战高热、关节疼痛等全身症状。"},{"t":"p","x":"继则肿块增大，疼痛加剧，2周左右肿块中央红热，按之有波动感；兼高热汗出，口渴欲饮。"},{"t":"p","x":"溃后脓黄稠，瘀血流注夹瘀血块。后肿痛消，身热退、食欲增，约2周脓尽收口。"},{"t":"p","x":"若溃后身热不退，可能他处新发，伴消瘦、面色无华、脉虚数等症。若兼神昏谵语、胸胁疼痛、咳喘痰血等、为毒传脏腑，致内陷变证或内痈。"},{"t":"p","x":"骼窝流注仅发于骼窝一侧。初起患侧大腿拘挛跛行，伴恶寒发热、头痛等症。"},{"t":"p","x":"2～3日后局部疼痛，大腿上缩内收，屈曲难伸。倘将患肢拉直，则剧痛牵腰致腹前凸，脊柱弓状。"},{"t":"p","x":"7～10天后，骼窝部可触及一长圆形硬块，有压痛。1个月左右成脓，皮色如常、中软、波动感不显。"},{"t":"p","x":"可在骼窝或腰部破溃，溃后20天左右收口，愈后患侧大腿屈曲难伸，1～2个月恢复正常。"},{"t":"p","x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显升高。"},{"t":"p","x":"疑有血行播散、深部脓肿或重要部位受累者，应及时进行血培养、影像学检查(如彩超、CT或MRI)。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-18)"},{"t":"table","img":"img/tab/t0618.jpg","cap":"表6-18髂窝流注、环跳疽与髋关节流痰的鉴别"}],"entries":["e0137"]},{"title":"治疗","blocks":[{"t":"p","x":"治宜清热解毒、和营通络。溃后清余邪，缓补防余毒流窜。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s060601","name":"余毒攻窜证","clinic":"发病前有疔疮、痈、疖等病史，局部漫肿疼痛；伴壮热、口渴，甚则神昏谵语；舌苔黄，脉洪数","treat":"清热解毒，凉血通络","formula":"黄连解毒汤合犀角地黄汤加减。脓成加当归、皂角刺，去生地黄；神昏谵语加安官牛黄丸化服或紫雪散吞服","formulaNames":["黄连解毒汤","犀角地黄汤"]},{"t":"syn","sid":"s060602","name":"暑湿交阻证","clinic":"多发于夏秋，局部漫肿疼痛；初起伴恶寒发热，头胀，胸闷，呕恶，周身骨节酸痛；舌苔白腻，脉滑数","treat":"解毒清暑化湿","formula":"清暑汤加减。结块质硬加当归、丹参，脓成加皂角刺","formulaNames":["清暑汤"]},{"t":"syn","sid":"s060603","name":"瘀血凝滞证","clinic":"劳伤筋脉诱发多在四肢内侧；跌打损伤诱发多发于伤处，漫肿疼痛，皮色红紫，溃脓夹瘀血块；产后恶露停滞则多在小腹及大腿。发病缓，起初全身症状轻或无，化脓时高热；苔薄白或黄腻，脉涩或数","treat":"和营活血，祛瘀通络","formula":"活血散瘀汤加减。劳伤筋脉，加忍冬藤、黄柏、薏苡仁、萆薢等；跌打损伤，加三七；产后瘀阻，加制香附、益母草、红花等；脓成可加皂角刺","formulaNames":["活血散瘀汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期肿而无块，外敷金黄膏或玉露膏；肿而有块，贴太乙膏掺红灵丹。"},{"t":"p","x":"(2)脓成脓熟宜切开引流。"},{"t":"p","x":"(3)溃后先用八二丹药线引流，脓净换生肌散，均以红油膏或太乙膏盖贴。"},{"t":"p","x":"结块二三处贯通可切开后换药，并用垫棉法，促疮口愈合。"}]}],"entries":["e0138","e0139","e0140","e0141","e0142"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.正确处理原发皮损。2.骼窝流注愈后功能障碍者，需行下肢伸屈功能锻炼。"}],"entries":["e0143"]}]},{"id":"d0607","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"丹毒","displayName":"丹毒","parentId":"","printedPage":69,"pdfPage":84,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"丹毒是患部皮肤突然发红成片、色如涂丹的急性感染性疾病。本病发无定处，根据其发病部位的不同有不同的病名。"},{"t":"p","x":"如生于躯干部者，称内发丹毒；发于头面部者，称抱头火丹；"},{"t":"p","x":"发于小腿足部者，称流火；新生儿多生于臀部，称赤游丹毒。"},{"t":"p","x":"其临床特点是起病突然，恶寒发热，局部皮肤忽然变赤，色如丹涂脂染，焮热肿胀，边界清楚，迅速扩大，数日内可逐渐痊愈，但易复发。《素问·至真要大论》云：“少阳司天，客胜则丹胗外发，及为丹疮疡。"},{"t":"p","x":"《诸病源候论·丹毒病诸候》云：“丹者，人身忽然焮赤，如丹涂之状，故谓之丹。或发手足，或发腹上，如手掌大，皆风热恶毒所为。"},{"t":"p","x":"重者，亦有疽之类，不急治，则痛不可堪，久乃坏烂。”本病西医学也称丹毒，相当于西医学的急性网状淋巴管炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由血热火毒为患。素体血分有热，或在肌肤破损处(如鼻腔黏膜、耳道皮肤或头皮等破伤，脚湿气糜烂，毒虫咬伤，臁疮等)有湿热火毒之邪乘隙侵入，郁阻肌肤而发。"},{"t":"p","x":"1.风热毒蕴发于头面部，多夹风热。2.肝脾湿火发于胸腹腰胯部、多夹肝脾郁火。"},{"t":"p","x":"3.湿热毒蕴发于下肢。多夹湿热。"},{"t":"p","x":"4.胎火蕴毒发于新生儿，多由胎热火毒所致。西医学认为，本病是由溶血性链球菌从皮肤或黏膜的细微破损处侵入皮内网状淋巴管，所引起的急性炎症性疾病。"},{"t":"p","x":"反复发作者还应评估足癣、静脉或淋巴回流障碍、肥胖、糖代谢异常等相关因素。"}],"entries":["e0144","e0145"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现多发于小腿、颜面部。发病前多有皮肤或黏膜破损史。"},{"t":"p","x":"发病急骤，初起往往先有恶寒发热、头痛骨楚、胃纳不香、便秘溲赤、苔薄白或薄黄、舌质红、脉洪数或滑数等全身症状。继则局部皮肤见小片红斑，迅速蔓延成大片鲜红斑，边界清楚，略高出皮肤表面、压之皮肤红色减退，放手后立即恢复。"},{"t":"p","x":"若因热毒炽盛而显现紫斑时，则压之不退色。患部皮肤肿胀，表面紧张光亮，摸之灼手，触痛明显。"},{"t":"p","x":"一般预后良好，经5～6天后消退，皮色由鲜红转为暗红及棕黄色，脱屑而愈。病情严重者，红肿处可伴发紫癜、瘀点、瘀斑、水疱或血疱，偶有化脓或皮肤坏死。"},{"t":"p","x":"亦有一边消退，一边发展，连续不断，缠绵数周者。患处附近臖核可发生肿大疼痛。"},{"t":"p","x":"抱头火丹如由于鼻部破损引起者，先发于鼻额，继而两眼睑肿胀不能开视；如由于耳部破损引起者，先肿于耳之上下前后，再肿及头角；"},{"t":"p","x":"如由于头皮破损引起者，先肿于头额，次肿及项部。流火多由趾间皮肤破损引起，先肿于小腿，也可延及大腿，愈后易复发，常因反复发作，下肢皮肤肿胀、粗糙增厚而形成大脚风。"},{"t":"p","x":"新生儿赤游丹毒常游走不定，多有皮肤坏死，全身症状严重。本病若出现红肿斑片由四肢或头面向胸腹蔓延者，属逆证。"},{"t":"p","x":"新生儿及年老体弱者，若火毒炽盛易致毒邪内攻，出现壮热烦躁、神昏谵语、恶心呕吐等全身症状，甚则危及生命。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-19)"},{"t":"table","img":"img/tab/t0619.jpg","cap":"表6-19丹毒与发、接触性皮炎、类丹毒的鉴别"}],"entries":["e0146"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗以凉血清热、解毒化瘀为主。发于头面者，须兼散风清火；发于胸腹腰胯者，须兼清肝泻脾；"},{"t":"p","x":"发于下肢者，须兼利湿清热。在内治的同时结合外敷、熏洗、砭镰等外治法，能提高疗效、缩短疗程、减少复发。"},{"t":"p","x":"若出现毒邪内攻之证，须中西医结合救治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s060701","name":"风热毒蕴证","clinic":"发于头面部，皮肤炊红灼热，肿胀疼痛，甚则发生水疱，眼胞肿胀难睁；伴恶寒，发热，头痛；舌质红，苔薄黄，脉浮数","treat":"疏风清热解毒","formula":"普济消毒饮加减。大便干结者，加生大黄、芒硝；咽痛者，加生地黄","formulaNames":["普济消毒饮"]},{"t":"syn","sid":"s060702","name":"肝脾湿火证","clinic":"发于胸腹腰胯部，皮肤红肿蔓延，摸之灼手，肿胀疼痛；伴口干且苦；舌红，苔黄腻，脉弦滑数","treat":"清肝泻火利湿","formula":"柴胡清肝汤合龙胆泻肝汤加减","formulaNames":["柴胡清肝汤","龙胆泻肝汤"]},{"t":"syn","sid":"s060703","name":"湿热毒蕴证","clinic":"发于下肢，局部红赤肿胀、灼热疼痛，或见水疱、紫斑，甚至结毒化脓或皮肤坏死，或反复发作，可形成大脚风；伴发热，胃纳不香；舌红，苔黄腻，脉滑数","treat":"利湿清热解毒","formula":"五神汤合萆薢渗湿汤加减。肿胀甚者，或形成大脚风者，加防己、赤小豆、丝瓜络、鸡血藤等","formulaNames":["五神汤","萆薢渗湿汤"]},{"t":"syn","sid":"s060704","name":"胎火蕴毒证","clinic":"发生于新生儿，多见于臀部，局部红肿灼热，常呈游走性；或伴壮热烦躁，甚则神昏、呕吐","treat":"凉血清热解毒","formula":"犀角地黄汤合黄连解毒汤加减。高热烦躁、惊厥者，加服安宫牛黄丸或紫雪丹；舌绛苔光者，加玄参、麦冬、石斛等","formulaNames":["犀角地黄汤","黄连解毒汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)外敷法用玉露散或金黄散，以冷开水或鲜丝瓜叶捣汁或金银花露调敷。"},{"t":"p","x":"或用鲜荷叶、鲜蒲公英、鲜地丁全草、鲜马齿苋、鲜冬青树叶等捣烂湿敷。干后调换，或以冷开水时时湿润。"},{"t":"p","x":"(2)砭镰法患处消毒后，用七星针或三棱针叩刺患部皮肤，放血泄毒。"},{"t":"p","x":"此法只适用于下肢复发性丹毒，禁用于赤游丹毒、抱头火丹患者。此外，若流火结毒成脓，可在坏死部位做小切口引流，掺九一丹，外敷红油膏。"}]}],"entries":["e0147","e0148","e0149","e0150","e0151","e0152"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.患者应卧床休息，多饮水，床边隔离。流火患者应抬高患肢30°～40°。"},{"t":"p","x":"2.有肌肤破损者应及时治疗，以免感染毒邪而发病。因脚湿气导致的下肢复发性丹毒患者应彻底治愈脚湿气，可减少复发。"}],"entries":["e0153"]}]},{"id":"d0608","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"无头疽","displayName":"无头疽","parentId":"","printedPage":71,"pdfPage":86,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"无头疽是发生于骨与关节间的急、慢性化脓性疾病的统称，因其初起无头故名。"},{"t":"p","x":"其临床特点是发病急骤，初起无头，发无定处，病位较深，漫肿，皮色不变，疼痛彻骨，难消，难溃，难敛。儿童常见。"},{"t":"p","x":"发于四肢长管骨者多损骨，生于关节者易造成畸形。《外科证治全书》云：“阴疽之形，皆阔大平塌，根盘坚硬，皮色不异，或痛或不痛，乃外科最险之证。"},{"t":"p","x":"本病相当于西医学的化脓性骨髓炎、化脓性关节炎。历代中医外科文献所述无头疽的概念范围既广又杂，现根据疾病性质、证治的不同，把流痰、流注等疾病列出分述。"},{"t":"p","x":"生在胁肋的胁肋疽相当于西医学的胸壁结核或肋骨结核，生在腋中的腋疽、生在股间的股阴疽相当于西医学的淋巴结结核，分别归入流痰、凛疬的范畴。"},{"t":"p","x":"好发于四肢末端，可致趾(指)骨节脱落的脱疽，以及发于乳房深部而形成脓肿的乳疽，分别归入周围血管疾病和乳房疾病。本节选择临床常见的附骨疽、环跳疽作为典型疾病介绍。"}],"entries":["e0154"]}]},{"id":"d0608a","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"附骨疽","displayName":"无头疽·附骨疽","parentId":"d0608","printedPage":72,"pdfPage":87,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"附骨疽是一种毒气深沉、附着于骨的化脓性疾病。"},{"t":"p","x":"其临床特点是儿童常见，多发于四肢长骨，局部胖肿，附筋着骨，推之不移，疼痛彻骨，溃后脓水淋漓，不易收口，可形成窦道，损伤筋骨。生于大腿外侧者称附骨疽，生于大腿内侧者谓咬骨疽，生于股胫部者称股胫疽等。"},{"t":"p","x":"病名虽异，而其病因、证治相仿，故合并论述，统名为附骨疽。《备急千金要方》云：“以其无破，附骨成脓，故名附骨疽。"},{"t":"p","x":"本病相当于西医学的急、慢性化脓性骨髓炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.湿热瘀阻因患疔疮、有头疽、疮疖等化脓性疾病，或伤寒、天花、麻疹、猩红热等病后余毒未清，湿热壅盛；"},{"t":"p","x":"或由于外来伤害，尤其是开放性骨折、局部骨骼损伤，又感邪毒，瘀血化热，邪热深窜留着筋骨，使经脉阻隔，气血不和，血凝毒聚而发。2.热毒炽盛初起未能及时控制，邪毒化火，毒火炽盛，灼伤筋骨，酝酿成脓。"},{"t":"p","x":"3.脓毒蚀骨脓成未及时引流或引流后余毒未清，深伏而腐蚀筋骨，形成死骨或窦道。西医学认为，本病是各种感染因素造成的骨髓炎症，以病程长短分为急性和慢性，急性骨髓炎以骨质吸收、破坏为主，慢性骨髓炎以死骨和新生骨形成为主。"}],"entries":["e0155","e0156"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现好发于气血未充、骨骼柔弱的小儿，10岁以下男孩尤为多见。"},{"t":"p","x":"多发于四肢骨干，以胫骨最常见，股骨次之。常有明显化脓性病灶，或有外伤、感受邪毒等诱发因素。"},{"t":"p","x":"初期：起病急骤，先有全身不适，寒战，继而高热达39～40℃。初起患肢持续剧痛、疼痛彻骨，1～2日即不能活动，随后出现皮肤微红、微热、胖肿，骨胀明显。"},{"t":"p","x":"若在大腿部红肿则不易发现，但手指深压皮肤可见凹陷，病变骨端深压痛和纵轴叩击痛阳性。成脓期：化脓时间在患病后3～4周，局部焮红、胖肿、骨胀明显，全身高热持续。"},{"t":"p","x":"溃后：脓出之初多稠厚，渐转稀薄，淋漓不尽，不易收口而形成窦道。患处可摸到粗大骨骼、高低不平，以探针探之，常可触到粗糙朽骨，此时即转为慢性，可迁延数年。"},{"t":"p","x":"以后常反复发作，大多数病例均有一个或数个不易愈合的窦道，窦口凹陷，周围常并发湿疮、脓疱及色素沉着。必待朽骨出尽以后，疮口才能愈合。"},{"t":"p","x":"本病若见高热烦躁、神昏谵语等症，则为并发内陷，可危及生命。"},{"t":"p","x":"(2)辅助检查 ①血常规：初起血常规示白细胞总数及中性粒细胞比例明显增高，病久红细胞总数及血红蛋白含量降低。"},{"t":"p","x":"②细菌培养：血液及局部穿刺液细菌培养可呈阳性，药敏试验有助于选择敏感抗生素。"},{"t":"p","x":"③影像检查：99m锝-MDP骨显像对本病的早期诊断有帮助。"},{"t":"p","x":"X线摄片常在发病约2周后才能显示病变。CT检查较X线摄片能提早发现病灶，并可显示局部软组织的变化。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-20)"},{"t":"table","img":"img/tab/t0620.jpg","cap":"表6-20附骨疽与流痰、流注的鉴别"}],"entries":["e0157"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热解毒、化湿和营为治法，分期辨证论治。若能早期诊断，正确治疗，尚有消退之机，否则易成慢性，日久不愈。"},{"t":"p","x":"外治要固定患处，脓熟切开引流，窦道形成用腐蚀药或手术治疗，脓尽空腔或疮口深用垫棉法。必要时配合抗生素和支持疗法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0608a01","name":"湿热瘀阻证","clinic":"患肢疼痛彻骨，不能活动，继则局部胖肿，皮色不变，按之灼热，有明显骨压痛，患肢纵轴叩击痛阳性；伴寒战高热；舌苔黄，脉数","treat":"清热化湿，行瘀通络","formula":"仙方活命饮合五神汤加减","formulaNames":["仙方活命饮","五神汤"]},{"t":"syn","sid":"s0608a02","name":"热毒炽盛证","clinic":"起病1～2周后，高热持续不退；患肢胖肿，疼痛剧烈，皮肤焮红灼热，内已酿脓；舌苔黄腻，脉洪数","treat":"清热化湿，和营托毒","formula":"黄连解毒汤合仙方活命饮加减","formulaNames":["黄连解毒汤","仙方活命饮"]},{"t":"syn","sid":"s0608a03","name":"脓毒蚀骨证","clinic":"溃后脓水淋漓，久则形成窦道，患肢肌肉萎缩，可摸到粗大骨骼，以探针检查常可触及粗糙朽骨；伴乏力、神疲、头昏、心悸、低热等；舌淡红，苔薄黄，脉濡细","treat":"调补气血，清化余毒","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起金黄膏或玉露膏外敷，患肢夹板固定，以减少疼痛和防止病理性骨折。"},{"t":"p","x":"(2)脓成及早切开引流。"},{"t":"p","x":"(3)溃后用七三丹或八二丹药线引流，红油膏或冲和膏盖贴；"},{"t":"p","x":"脓尽改用生肌散、白玉膏。"},{"t":"p","x":"(4)窦道形成用千金散或五五丹药线腐蚀，疮口扩大后改用八二丹药线引流，太乙膏或红油膏盖贴。"},{"t":"p","x":"若触及死骨松动，可用镊子夹出；如无死骨，脓液转黏稠时，即使疮口仍较深，也应停用药线，否则不易收口。"},{"t":"p","x":"若有空腔或疮口较深时，可用垫棉法，以促疮口愈合。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术清创适用于窦道经久不敛，死骨大或多，疮口小而深，不能自动排出朽骨者。"},{"t":"p","x":"(2)中成药可选用小金丸、牛黄解毒片、西黄丸或醒消丸口服。"},{"t":"p","x":"(3)抗生素和支持疗法适用于低龄、体弱且病情严重者，抗生素需早期、足量使用，并配合必要的支持疗法。"}]}],"entries":["e0158","e0159","e0160","e0161","e0162","e0163"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.平素加强锻炼、增加饮食营养。患病后禁食鱼腥发物及辛辣之品。"},{"t":"p","x":"2.急性期卧床休息，患肢抬高并用夹板固定。慢性期应避免负重及跌跤。"},{"t":"p","x":"3.积极治疗原发病。疾病治愈后须继续服药3～6个月，以防复发。"}],"entries":["e0164"]}]},{"id":"d0608b","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"环跳疽","displayName":"无头疽·环跳疽","parentId":"d0608","printedPage":74,"pdfPage":89,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"环跳疽、又称股阴疽，是发生于环跳穴(髋关节)的急性化脓性疾病。其临床特点是好发于儿童，男多于女，发病急骤，局部漫肿疼痛，影响关节屈伸，全身症状严重，溃后难敛，易致残疾。"},{"t":"p","x":"《外科大成》云：“环跳疽，生环跳穴，漫肿隐痛，尺脉沉紧，腿不能伸。”本病相当于西医学的化脓性髋关节炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.基本同“附骨疽”。2.也可直接由关节附近外伤感染毒邪，或附骨疽脓毒流注关节而发生。"}],"entries":["e0165","e0166"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现好发于4～14岁儿童，男性多于女性。"},{"t":"p","x":"初期：来势较急，初起即恶寒壮热，髋部隐痛，皮色不变，活动受限，尤其旋转活动受限。继则疼痛加剧，不能屈伸，臀部外突，大腿略有外展、外旋，纵轴叩击痛阳性。"},{"t":"p","x":"成脓期：皮肤灼热，皮色微红，疼痛剧烈，漫肿上延腰胯，下及大腿，伴壮热持续不退。局部按之有波动感者，为内已成脓，成脓时间在患病后1～3个月内。"},{"t":"p","x":"溃后：脓出初见黄稠，日后稀薄，因已损骨，多不易愈合。可使关节畸形、僵硬，不能活动，或造成病理性脱位等。"},{"t":"h","lv":3,"x":"(2)辅助检查"},{"t":"p","x":"X线摄片：在发病早期仅见关节周围软组织肿胀，后期可见关节软骨破坏，间隙变窄、骨质有脱钙现象。血常规：初起血常规示白细胞总数及中性粒细胞比例明显增高。"},{"t":"p","x":"细菌培养：血液及关节腔穿刺液细菌培养可呈阳性，药敏试验有助于选择敏感抗生紫。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-21)"},{"t":"table","img":"img/tab/t0621.jpg","cap":"表6-21环跳疽与臀部流注、骼窝流注的鉴别"}],"entries":["e0167"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗可参照“附骨疽”。脓成也可做关节腔敏感抗生素冲洗，每日1次。"},{"t":"p","x":"本病后期关节挛缩、肌肉萎缩、伸屈困难，或僵硬不能活动者，治宜益气化瘀、通经活络，用补阳还五汤加减。"}],"entries":["e0168"]},{"title":"预防与调护","blocks":[{"t":"p","x":"参照“附骨疽”。"}],"entries":["e0169"]}]},{"id":"d0609","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"走黄与内陷","displayName":"走黄与内陷","parentId":"","printedPage":75,"pdfPage":90,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"走黄与内陷为疮疡阳证疾病过程中，因火毒炽盛，毒邪走散，或正气不足，正不胜邪，客于营血，内攻脏腑引起的危重病证。继发于疔疮的病变称为走黄；因疽毒或除疔疮以外的其他疮疡引起的病变称为内陷。"},{"t":"p","x":"本病相当于西医学的全身性外科感染(脓毒症)。西医学认为，本病的发生是致病菌数量多、毒力强和(或)机体抗感染能力低下所致，由于致病菌、毒素及其介导的多种炎症介质对机体的损害而发病，常继发于各种化脓性感染和严重创伤后的感染。"}],"entries":["e0170"]}]},{"id":"d0609a","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"走黄","displayName":"走黄与内陷·走黄","parentId":"d0609","printedPage":75,"pdfPage":90,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"走黄是疔疮火毒炽盛，早期失治、误治，毒势未能及时控制，走散入营，内攻脏腑而引起的一种全身性危急病证。“黄即横，散也”;“黄即毒也，疔毒内走攻心”。"},{"t":"p","x":"其临床特点是疮顶忽然凹陷，色黑无脓，肿势迅速扩散，伴见高热头痛、烦躁不安、神志昏愦等症。凡是疔疮均可能发展为走黄，颜面部疔疮、烂疔尤易发生。"},{"t":"p","x":"《疮疡经验全书·疔疮》云：“疔疮初生时，红软温和，忽然顶陷黑，谓之‘癀走’，此症危矣。"},{"t":"p","x":"《疡科心得集·疡证总论》曰：“外证虽有一定之形，而毒气之流行亦无定位，故毒入于心则昏迷，人于肝则痉厥，入于脾则腹疼胀，入于肺则喘嗽，入于肾则目暗手足冷，入于六腑，亦皆各有变象，兼证多端，七恶叠见。”"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"走黄主要在于火毒炽盛，毒邪走散，客入营血，内攻脏腑而成。生疔之后，早期失治，未能控制毒势；"},{"t":"p","x":"或挤压碰伤，过早切开，或误食辛热之药及膏粱厚味等发物，或妄用艾灸，均可使疔毒走散，入营入血，内攻脏腑而发生走黄。颜面为诸阳之会，颜面疔疮多火毒为患，两阳相遇，正邪交争剧烈，故易引起走黄。"}],"entries":["e0171","e0172"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断"},{"t":"h","lv":3,"x":"(1)临床表现本病发病急，病情重，发展迅速，变化多端。"},{"t":"p","x":"局部表现：在疔疮原发病灶处忽然疮顶凹陷，色黑无脓，肿势软漫，迅速向周围扩散、边界不清，失去护场，皮色转为暗红。"},{"t":"p","x":"全身症状：寒战、高热(体温多在39℃以上)，或体温不升，头痛，烦躁，胸闷，四肢酸软无力，舌质红绛、苔黄燥，脉洪数或滑数；或伴恶心呕吐，口渴喜饮，便秘腹胀或腹泻；"},{"t":"p","x":"或伴身发瘀斑、风疹块、黄疸等；甚至出现神志昏糊、呓语谵妄、咳嗽气喘、胁痛痰黄、发痉发厥等；"},{"t":"p","x":"或伴手足发冷，脉沉细数等；或伴肢体拘急，骨节肌肉疼痛；"},{"t":"p","x":"或并发附骨疽、流注等。以上各症常可相兼出现。"},{"t":"p","x":"(2)辅助检查白细胞计数显著增高，或降低、左移、幼稚型增多，出现毒性颗粒；"},{"t":"p","x":"尿中可出现蛋白、血细胞、酮体等；出现电解质、酸碱代谢失衡；肝肾功能受损。"},{"t":"p","x":"脓液和血液的细菌培养可发现致病菌，药敏试验有助于指导疾病治疗。"}],"entries":["e0173"]},{"title":"治疗","blocks":[{"t":"p","x":"应采取中西医结合治疗。根据温病的证治规律和走黄火毒炽盛的特点辨证论治，处理原发病灶是重要的治疗环节。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0609a01","name":"毒盛入血证","clinic":"原发病灶处忽然疮顶陷黑无脓，肿势软漫，迅速向周围扩散，边界不清，皮色转为暗红；寒战、高热(体温多在39℃以上)，头痛，烦躁，胸闷，四肢酸软无力；舌质红绛，舌苔多黄燥，脉洪数或滑数","treat":"凉血清热解毒","formula":"犀角地黄汤、黄连解毒汤、五味消毒饮三方合并加减。神志昏糊，加紫雪丹，或安宫牛黄丸；咳吐痰血、加贝母、天花粉、藕节炭；大便秘结，苔黄腻，脉滑数有力，加生大黄(后下)、元明粉(分冲)；呕吐口渴，加淡竹叶、生石膏(打碎)；阴液损伤，加石斛、玄参、麦冬；惊厥，加钩藤(后下)、龙齿(先煎)；并发黄疸，加生大黄(后下)、茵陈","formulaNames":["犀角地黄汤","黄连解毒汤"]},{"t":"p","x":"2.外治疗法根据不同疔疮的原发病灶，选择相应的外治法。颜面疔疮早期应药物外敷以箍肿消毒，避免毒邪走散；"},{"t":"p","x":"中期脓肿应及时切开，后期应引流通畅；烂疔应及时清除坏死组织，清除异物，引流通畅。"},{"t":"p","x":"3.其他疗法及时、彻底处理原发病灶；早期足量应用敏感、广谱抗生素；"},{"t":"p","x":"支持疗法，补充血容量，纠正低蛋白血症等；对症处理，控制高热，维持水、电解质平衡；"},{"t":"p","x":"治疗全身性疾病，保护重要脏器功能。"}],"entries":["e0174","e0175"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.本病危重，应严密观察病情，注意体温、脉搏、呼吸等生命体征的变化。2.保证患者充分睡眠，绝对卧床休息，并固定患部，减少活动。"},{"t":"p","x":"3.加强营养，饮食宜清淡，忌荤腥发之物及甜腻之品，视病情给予半流质或普食。4.疔疮尤其是颜面部疔疮切忌挤压、碰伤、过早切开。"}],"entries":["e0176"]}]},{"id":"d0609b","kind":"sub","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"内陷","displayName":"走黄与内陷·内陷","parentId":"d0609","printedPage":76,"pdfPage":91,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"内陷是除疔疮外的其他阳证疮疡病程中出现的危急病证，因正气不足，火毒炽盛，正不胜邪，毒不外泄，反陷入里，客于营血，内传脏腑所致。本病多继发于有头疽，故又称疽毒内陷。"},{"t":"p","x":"其临床特点是肿势隆起的疮顶忽然内陷，或溃疡脓腐未净而忽然干枯无脓，或脓净疮面红活而忽变光白板亮、伴邪盛热极或正虚邪盛或阴阳两竭的全身证候。根据病变不同阶段的临床表现分为火陷、干陷和虚陷三种。"},{"t":"p","x":"发生于有头疽的1～2候毒盛期的，称火陷；发生于2～3候溃脓期的，称干陷；"},{"t":"p","x":"发生于4候收口期的，称虚陷。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"内陷发生的根本原因在于正气不足，火毒炽盛，加之治疗失时或不当，以致正不胜邪，反陷入里，客于营血，内犯脏腑。而三陷之病机因所处病期不同而有所区别。"},{"t":"p","x":"1.火陷由于阴液不足，火毒炽盛，复因挤压疮口，或治疗不当或失时，以致正不胜邪，毒邪客于营血，内犯脏腑而成。2.干陷由于气血两亏，正不胜邪，不能酿化成脓，载毒外出，以致正虚毒盛而成。"},{"t":"p","x":"3.虚陷毒邪虽已衰退，而气血大伤，脾气不复，肾阳亦衰，导致生化乏源，阴阳两竭，余毒走窜入营。"}],"entries":["e0177","e0178"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断"},{"t":"p","x":"(1)临床表现多见于老年人，或有消渴病史者。"},{"t":"p","x":"常并发于脑疽、背疽患者，尤以脑疽更为多见。局部症状：疮顶不高或陷下，肿势平塌，散漫不聚，疮色紫滞或晦暗，疮面脓少或干枯无脓，脓水灰薄或偶带绿色，腐肉虽脱而疮面忽变光白板亮，新肉难生，局部灼热剧痛或闷胀疼痛或不痛。"},{"t":"p","x":"全身症状：高热、寒战，或体温不升，头痛烦躁，或精神不振，甚至神昏谵语，气粗喘急，或气息低微，胸闷胸痛，咳嗽痰血，胁肋疼痛，恶心呕吐，腹胀腹痛，便秘或腹泻，汗多肢冷，或痉厥，或黄疸等。"},{"t":"p","x":"一般而言，火陷辨证为邪盛热极证，干陷辨证为正虚邪盛证，虚陷辨证为脾肾阳衰证或阴伤胃败证。"},{"t":"p","x":"(2)实验室检查血常规示白细胞计数及中性粒细胞比例显著增高，虚陷证有时白细胞计数可降低。"},{"t":"p","x":"血液培养多有细菌生长。可出现血糖升高、尿糖阳性。"}],"entries":["e0179"]},{"title":"治疗","blocks":[{"t":"p","x":"应采取中西医结合治疗。扶正祛邪，审邪正之消长，随症治之；正确处理原发病灶。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s0609b01","name":"邪盛热极证","clinic":"多发生于疽证1～2候毒盛期。疮顶不高，根盘散漫，疮色紫滞，疮面干枯无脓，灼热剧痛；壮热口渴，便干溲赤，烦躁不安，神昏谵语；苔黄腻或黄燥，舌质红绛，脉洪数、滑数或弦数","treat":"凉血清热解毒，养阴清心开窍","formula":"清营汤合黄连解毒汤、安宫牛黄丸、紫雪丹，加皂角刺。若寒战、高热、厥冷，此为热极生寒，热深厥深，宜清泄里热，宣通郁阳，用桂枝合白虎汤加减","formulaNames":["清营汤","黄连解毒汤","安宫牛黄丸","紫雪丹"]},{"t":"syn","sid":"s0609b02","name":"正虚邪盛证","clinic":"多发生于疽证2～3候溃脓期。疮面腐烂，脓少而薄，疮色灰暗，肿势平塌，散漫不聚，闷胀疼痛，或微痛；发热或恶寒，神疲，食少，自汗胁痛，气息急促；舌苔黄腻或灰腻，脉虚数。或体温反而不高，肢冷，大便溏薄，小便频数，舌质淡，脉沉细等","treat":"补养气血，托毒透邪，佐以清心安神","formula":"托里消毒散、安宫牛黄丸加减","formulaNames":["托里消毒散","安宫牛黄丸"]},{"t":"syn","sid":"s0609b03","name":"脾肾阳衰证","clinic":"多发生于疽证4候收口期。肿势已退，疮口腐肉已尽，而水稀薄色灰，或偶带绿色，新肉不生，状如镜面，光白板亮，不知疼痛；虚热不退，形神委顿，纳食日减，或有腹痛便泄，自汗肢冷，气息低促；舌质淡红，苔薄白或无苔，脉沉细或虚大无力；甚至昏迷厥脱","treat":"温补脾肾","formula":"附子理中汤加减","formulaNames":["附子理中汤"]},{"t":"syn","sid":"s0609b04","name":"阴伤胃败证","clinic":"局部症状同脾肾阳衰证；伴口舌生糜，纳少口干；舌质红绛、舌光如镜，脉象细数","treat":"生津养胃","formula":"益胃汤加减","formulaNames":["益胃汤"]},{"t":"p","x":"2.外治疗法根据原发病灶的不同，选择相应的外治法。3.其他疗法参照“走黄”。"}],"entries":["e0180","e0181","e0182","e0183","e0184"]},{"title":"预防与调护","blocks":[{"t":"p","x":"参照“走黄”。"}],"entries":["e0185"]}]},{"id":"d0610","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"流痰","displayName":"流痰","parentId":"","printedPage":77,"pdfPage":92,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"流痰是一种发于骨与关节部位的感染性疾病。"},{"t":"p","x":"因其脓液可流窜于病变附近或较远的组织部位形成脓肿，脓液稀薄如痰，故名流痰；后期出现虚痨症状，故又有“骨痨”之称。"},{"t":"p","x":"本病的病变部位以脊椎最多，其次为下肢膝、髋、踝关节、再次为上肢肘、肩、腕、指等骨关节。一般为单发，但脓肿形成时脓液可走窜到原发病灶之外的颈、胸、胁、腰、腹、腿等处。"},{"t":"p","x":"《外科医案汇编》云：“痰凝于肌肉、筋骨、骨空之处、无形可征、有血肉可以成脓，即为流痰。”本病相当于西医学的骨与关节结核。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.寒痰凝聚索体肝肾不足，致肾阳虚衰。阳虚不能温煦，寒邪乘虚内侵，凝聚于骨骼关节；"},{"t":"p","x":"脾胃虚弱、运化失司、水湿内停，聚湿成痰。寒、痰相互交结，凝聚于骨与关节。"},{"t":"p","x":"2.阴虚内热寒痰凝聚日久，郁而化热，热盛则腐肉败骨为脓，耗伤阴血津液；热邪持续灼伤阴津、致阴液亏虚。"},{"t":"p","x":"3.肝肾亏虚脓水淋漓不止，久耗气血精微，致肝肾精血严重亏虚。4.气血两虚脓毒长期外泄，耗伤气血；病痛困扰，脾胃受损，气血生化之源不足。"},{"t":"p","x":"西医学认为，流痰是一种继发性结核病，结核杆菌经血循环到达骨与关节部位，在机体抵抗力下降时引起疾病发生。"}],"entries":["e0186","e0187"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"初期：患处隐隐酸痛，动则疼痛加剧，休息时减轻。疼痛逐渐加剧，关节活动障碍，下肢跛行；"},{"t":"p","x":"浅表关节部位可见肿痛。或有寒热表现。"},{"t":"p","x":"儿童患者常在睡眠时痛醒哭叫，俗称“夜哭”。成脓：起病后半年至1年形成脓肿，不热不红，或皮肤微红，局部或有疼痛，按之应指。"},{"t":"p","x":"伴有发热，朝轻暮重。溃后：溃后脓液稀薄，夹有败絮样物质或死骨，久不愈合，形成窦道；"},{"t":"p","x":"疮口凹陷，周围皮色紫暗。病变在四肢者，发生关节脱位或骨折，肌肉萎缩；"},{"t":"p","x":"病变在颈椎、胸椎、腰椎者，则四肢强直不遂，或瘫痪，甚至二便失禁。病变静止后出现各种后遗症，如关节功能障碍、关节屈曲挛缩畸形、脊柱后突畸形(驼背)、儿童骨骼破坏后肢体长度不等。"},{"t":"p","x":"由于病变部位不同，临床上可出现一些相应的特殊表现。"},{"t":"p","x":"(2)辅助检查 ①实验室检查：红细胞总数及血红蛋白含量可降低；"},{"t":"p","x":"混合感染时白细胞计数可增高；红细胞沉降率在活动期明显增快，提示疾病静止、复发情况；"},{"t":"p","x":"结核菌素试验呈阳性；脓液培养可有结核杆菌生长。"},{"t":"p","x":"②影像学检查：X线摄片示早期滑膜肿胀，骨质疏松，有脱钙现象；"},{"t":"p","x":"后期见关节软骨破坏，或有病理性脱位，骨关节面明显破坏，死骨形成。CT检查较X线摄片更清晰。"},{"t":"p","x":"MRI检查可显示早期炎症病变，具有早期诊断价值；脊柱结核MRI检查可观察脊髓的受压、变性状况。"},{"t":"p","x":"B超检查可反映脓肿的位置和大小。"},{"t":"p","x":"③关节镜检查和滑膜活检可诊断滑膜结核。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-22)"},{"t":"table","img":"img/tab/t0622.jpg","cap":"表6-22流痰与历节风、骨肉瘤鉴别"}],"entries":["e0188"]},{"title":"治疗","blocks":[{"t":"p","x":"以扶正祛邪为总则。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s061001","name":"寒痰凝聚证","clinic":"病变部位隐隐酸痛，动则疼痛加剧，休息时减轻，疼痛逐渐加剧，关节活动障碍；无明显全身症状；舌淡，苔薄，脉濡细","treat":"补肾温经，散寒化痰","formula":"阳和汤加减","formulaNames":["阳和汤"]},{"t":"syn","sid":"s061002","name":"阴虚内热证","clinic":"脓肿形成，皮色微红，中有软陷，重按应指；伴午后潮热，颧红，夜间盗汗，口燥咽干，食欲减退，或咳嗽痰血；舌红少苔，脉细数","treat":"养阴清热托毒","formula":"六味地黄丸合清骨散加减","formulaNames":["六味地黄丸","清骨散"]},{"t":"syn","sid":"s061003","name":"肝肾亏虚证","clinic":"疮口流脓稀薄，或夹有败絮样物，形成窦道；患肢肌肉萎缩、关节畸形；病在脊椎可导致身体强直，甚至瘫痪；伴腰脊酸痛，盗汗；舌红苔薄，脉细数或虚数","treat":"补益肝肾","formula":"左归丸合香贝养荣汤加减","formulaNames":["左归丸","香贝养荣汤"]},{"t":"syn","sid":"s061004","name":"气血两虚证","clinic":"疮口流脓稀薄，日久不愈；伴面色无华，形体畏寒，心悸，失眠，自汗；舌淡红，苔薄白，脉濡细或虚大","treat":"补气养血","formula":"人参养荣汤或十全大补汤加减","formulaNames":["人参养荣汤","十全大补汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期回阳玉龙膏、阳和解凝膏掺桂麝散或黑退消敷贴。"},{"t":"p","x":"(2)成脓切开排脓，引流通畅。"},{"t":"p","x":"(3)溃后窦道形成应药线引流，提脓祛腐生肌；收口之时宜改掺生肌散。"},{"t":"p","x":"袋脓者宜扩创。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)抗结核药联合使用抗结核一线药物，小剂量长期使用，疗程不少于12个月。"},{"t":"p","x":"早期患者可用抗结核药做关节腔内注射、冲洗。"},{"t":"p","x":"(2)病灶清除术手术清除脓液、死骨、干酪样坏死物及结核性肉芽肿，并局部用抗结核药物治疗。"}]}],"entries":["e0189","e0190","e0191","e0192","e0193","e0194","e0195"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.局部制动：采用石膏、支架固定、皮牵引等方法限制活动，以防止病理性骨折、脱位；发生于胸椎、腰椎、髋关节等部位者，须睡木板床；"},{"t":"p","x":"发生于肘、膝、指部者，用夹板固定。2.全身症状未控制时均应绝对卧床休息。"},{"t":"p","x":"3.合理饮食、加强营养。4.清心静养，节制房事，以利康复。"},{"t":"p","x":"5.若发生瘫痪卧床，应预防褥疮发生。"}],"entries":["e0196"]}]},{"id":"d0611","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"瘰疬","displayName":"瘰疬","parentId":"","printedPage":80,"pdfPage":95,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"凛疬是一种发生于颈部的慢性感染性疾病。"},{"t":"p","x":"其结核累累如串珠，故名瘰疬。其临床特点是好发于颈部及耳后、起病缓慢，多见于体弱儿童及青年女性。"},{"t":"p","x":"《外科枢要·论凛疬》云：“其候多生于耳前后项腋间，结聚成核。初觉憎寒恶热，咽项强痛。"},{"t":"p","x":"本病相当于西医学的颈部淋巴结结核，继发于肺结核或肺外器官结核。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"情志内伤，肝气郁结，肝木乘脾土，脾失健运，痰湿内生，气滞痰凝，结于颈项；或肝郁化火，下灼肾阴，阴虚火旺，热盛肉腐而成脓。"},{"t":"p","x":"溃后脓水淋漓，耗伤气血，经久难愈。或因肺痨阴虚，肺肾阴亏，致阴虚火旺，肺津不能输布，灼津为痰，痰火凝结而成。"},{"t":"p","x":"西医学认为，本病是由于结核杆菌侵入淋巴结引起的慢性炎症。"}],"entries":["e0197","e0198"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"前期：颈部结核如豆，一个或数个不等，孤立或成串状，皮色不变，按之坚实，推之活动，不热不痛。多无全身症状。"},{"t":"p","x":"中期：颈部结核增大，疼痛，皮核粘连，皮色转暗红，扪之微热，按之有应指感，为脓已成，相邻的结核可融合成块，推之不动。伴有低热、食欲不振、全身乏力等症状。"},{"t":"p","x":"后期：脓肿切开或自行破溃后脓液稀薄，夹有败絮样物质，疮口为潜行性空腔，疮面肉色灰白，疮周皮肤紫暗，疮口经久不愈，形成窦道。"},{"t":"p","x":"伴有潮热、咳嗽、盗汗等肺肾阴亏之症，或面色无华、精神倦怠、头晕、失眠、经闭等气血两虚之症，或腹胀便溏、形瘦纳呆等脾虚之症。以上为常见临床表现。"},{"t":"p","x":"但也有患者数枚结核、肿块、成脓、成漏同时出现。本病愈后可因体虚、劳累而复发，以产后多见。"},{"t":"p","x":"若结核数年不溃，无明显增大，推之可动，病情较轻；若初起结核累累数枚，坚肿不移，融合成团，病情较重。"},{"t":"p","x":"(2)辅助检查红细胞沉降率可增快，结核菌素试验阳性，脓液培养可见结核杆菌生长。"},{"t":"p","x":"必要时取病灶组织做病理检查，有助于明确诊断。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-23)"},{"t":"table","img":"img/tab/t0623.jpg","cap":"表6-23瘰疬与失荣、臖核、颈痈的鉴别"}],"entries":["e0199"]},{"title":"治疗","blocks":[{"t":"p","x":"以扶正祛邪为总则。痰凝为凛疬形成之病机。"},{"t":"p","x":"气滞、体虚为痰形成之源。采取虚实辨证，三期论治，合理用药，内外结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s061101","name":"气滞痰凝证","clinic":"多见于凛疬初期，肿块坚实；无明显全身症状；舌淡，苔腻，脉弦滑","treat":"疏肝理气，化痰散结","formula":"逍遥散合二陈汤加减","formulaNames":["逍遥散","二陈汤"]},{"t":"syn","sid":"s061102","name":"阴虚火旺证","clinic":"结核肿块逐渐增大，皮核相连，皮色转暗红；伴午后潮热，夜间盗汗；舌红少苔，脉细数","treat":"滋阴降火","formula":"知柏地黄汤加减","formulaNames":["知柏地黄汤"]},{"t":"syn","sid":"s061103","name":"气血两虚证","clinic":"溃后脓液清稀，夹有败絮样物质；形体消瘦，精神倦怠，面色无华；舌淡质嫩，苔薄，脉细","treat":"益气养血","formula":"香贝养荣汤加减","formulaNames":["香贝养荣汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期局部外敷冲和膏或阳和解凝膏。"},{"t":"p","x":"(2)中期潜行性穿刺抽脓，冲洗，或切开引流。"},{"t":"p","x":"(3)后期溃疡疮面外用七三丹或八二丹，红油膏或冲和膏外敷。"},{"t":"p","x":"腐脱新生时，外用生肌玉红膏纱条；腐肉已尽，新肉鲜红时，用生肌散或白玉膏。形成空腔，皮肉不能黏合时，采用垫棉法；窦道用药线引流、扩创手术。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医疗法抗结核治疗，选择异烟肼、利福平、链霉素、乙胺丁醇等药物。"},{"t":"p","x":"(2)中成药内消瘰疬丸口服。"},{"t":"p","x":"(3)针刺疗法初期可直接刺人肿大结块，配合肝俞、膈俞等穴位；"},{"t":"p","x":"每日1次，中等刺激。"},{"t":"p","x":"(4)拔核疗法适用于肿核较小、日久不消、体质尚好者。"},{"t":"p","x":"用白降丹少许掺于太乙膏上，盖贴于结块处，结核脱落后改用生肌散、白玉膏。"}]}],"entries":["e0200","e0201","e0202","e0203","e0204","e0205"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗其他部位的虚劳病变。2.合理饮食，加强营养。"}],"entries":["e0206"]}]},{"id":"d0612","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"窦道","displayName":"窦道","parentId":"","printedPage":82,"pdfPage":97,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"窦道是一种只有外口而没有内口的病理性盲道。"},{"t":"p","x":"其临床特点是深部组织通向体表的管道，有一个或多个外口、管道或短或长或短、或直或弯。《诸病源候论·瘘候》中提出：“脓血不止，谓之漏也。”"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.余毒未清手术之后，局部气血受损，余毒未清，与瘀血互结，蕴蒸化脓，溃口难敛，形成窦道。或疮疡溃后，引流不畅，或切开过早，毒邪未净，深窜入里。"},{"t":"p","x":"2.气血两虚久病耗伤，脾胃虚弱、气血生化乏源，以致疮疡溃后新肉难生，疮口日久不敛。西医学认为，本病是手术外伤或异物存在导致的局部感染，脓肿切开引流不畅、特异性感染等亦可导致窦道发生。"}],"entries":["e0207","e0208"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现常有局部手术或附骨疽、流痰等外科感染病史，局部有疮口，常有脓性分泌物流出，时多时少，经久不愈；"},{"t":"p","x":"有时疮口可见死骨流出；病久疮周皮肤暗紫，疮口胬肉突起；"},{"t":"p","x":"一般无全身症状。若外口暂时封闭，脓液引流不畅，则局部红肿热痛，或伴有发热等症状。"},{"t":"p","x":"(2)辅助检查X线窦道造影、B超、CT等检查可明确窦道的位置、形态、数量、长度、与邻近器官的关系、有利于治疗和评判疗效。"},{"t":"p","x":"脓液细菌培养加药敏试验有助于了解细菌种类，指导治疗。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表6-24)"},{"t":"table","img":"img/tab/t0624.jpg","cap":"表6-24窦道与瘘管的鉴别"}],"entries":["e0209"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s061201","name":"余毒未清证","clinic":"疮口脓水淋漓，疮周红肿热痛，或瘙痒不适；可伴有轻度发热；舌苔薄黄或黄腻，脉数","treat":"清热和营托毒","formula":"仙方活命饮加减","formulaNames":["仙方活命饮"]},{"t":"syn","sid":"s061202","name":"气血两虚证","clinic":"疮口脓水稀薄，肉芽色淡不泽；伴面色萎黄，神疲倦怠，纳差寐少；舌淡苔薄，脉细","treat":"益气养血，和营托毒","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)腐蚀法使用八二丹或七三丹等提脓祛腐药做成药线，腐蚀管壁，引流脓液。"},{"t":"p","x":"(2)垫棉法脓液排尽后，用棉垫加压包扎窦道部位，使管壁塌陷，组织粘连，促进愈合。"},{"t":"p","x":"尤其适用于乳房部窦道。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)内窥镜治疗是在直视下对窦道进行诊断、清创、引流和闭合等一系列操作的技术。"},{"t":"p","x":"感染严重、有巨大脓腔或癌性窦道，可能需要联合外科手术。"},{"t":"p","x":"(2)切除法对于长期不愈、管壁纤维组织增厚、药线无法腐蚀的窦道，可行窦道切除术，彻底切除全部管壁组织，创口一期缝合或开放换药。"},{"t":"p","x":"(3)负压引流通过专用敷料密闭窦道创面，持续低负压吸引，能有效清除脓液及坏死组织，刺激肉芽生长，促进窦道闭合，显著缩短疗程。"},{"t":"p","x":"此外，扩创法、冲洗法等亦可应用于窦道修复，促进创面愈合。"}]}],"entries":["e0210","e0211","e0212","e0213","e0214"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.手术严格执行无菌操作，避免术后感染的发生。2.感染性疾病手术时彻底清除坏死组织，引流通畅，尽快愈合疮口。"},{"t":"p","x":"3.保持窦道周围皮肤清洁干燥。4.加强营养，促进疮口愈合。"}],"entries":["e0215"]}]},{"id":"d0613","kind":"main","chapterId":"ch06","chapterNo":"第六章","chapterName":"疮疡","name":"褥疮","displayName":"褥疮","parentId":"","printedPage":83,"pdfPage":98,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"久病卧床，压迫成疮，称为褥疮，也称席疮。《外科启玄》云：“席疮乃久病着床之人，挨擦磨破而成。"},{"t":"p","x":"其临床特点是多见于半身不遂、瘫痪、久病重病长期卧床不起的患者；好发于易受压和摩擦的部位，如骶尾部、髋部、背部、足跟部、枕部，局部皮肉腐烂流脓，经久不愈。"},{"t":"p","x":"本病西医学称为压疮、压力性损伤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"褥疮多因久病气血虚弱，局部长期受压、磨损致气虚血瘀，肌肤失养，皮肉坏死而成，易于染毒。1.气血瘀滞患者或因重伤、大病，长期卧床不起，躯体局部长时间受压；"},{"t":"p","x":"或因年老、久病，气虚而推动无力，导致血行不畅，瘀血内生。2.蕴毒腐溃长期卧床受压摩擦，局部气血瘀滞，瘀久化热，复染邪毒，热毒蕴结于局部，腐败血肉，则腐肉成脓；"},{"t":"p","x":"若气虚不能托毒外出，热毒入里，则腐肉迅速蔓延，深处可达筋骨、脓臭色败；若毒邪深入，可内陷营血，甚至危及生命(败血症)。"},{"t":"p","x":"3.气血两虚病程迁延，脓水淋漓不断，耗伤气血；加之患者本身多为久病卧床之体、已有气血亏虚，无力托毒外出，亦不能滋养肌肤，故见疮面色淡，腐肉虽脱但新肉难生，创口迟迟难以愈合。"},{"t":"p","x":"西医学认为，本病是由于压力或压力联合剪切力导致的皮肤和/或皮下组织局部损伤，常见于骶尾部、足跟、髋部等骨突区域。"}],"entries":["e0216","e0217"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断"},{"t":"p","x":"(1)临床表现初起压迫部位皮肤出现暗红，逐渐变紫暗，或出现水疱，痛或不痛，疮周平坦散漫；"},{"t":"p","x":"可发生皮肤坏死，液化溃烂，脓液臭秽，范围扩大，腐肉脱落，形成溃疡，深达筋膜、肌肉、骨膜。若疮面腐肉渐脱，新肉生长，色泽鲜红，褥疮可愈合。"},{"t":"p","x":"若腐烂蔓延不止，溃疡日渐扩大，出现绿9色脓水、腥臭稀薄、或如粉浆污水、体虚形瘦者，褥疮迁延难愈，甚或出现脓毒走窜，内传脏腑，预后较差。"},{"t":"h","lv":3,"x":"(2)分期(表6-25)"},{"t":"table","img":"img/tab/t0625.jpg","cap":"表6-25褥疮(压疮)NPUAP/EPUAP分期"},{"t":"h","lv":3,"x":"(3)辅助检查疮面脓液细菌培养及药敏试验有助于指导疾病治疗。"}],"entries":["e0218"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s061301","name":"气血瘀滞证","clinic":"局部皮肤出现红斑，继而紫暗红肿或有破溃；舌边有瘀斑，苔薄，脉弦","treat":"理气活血","formula":"血府逐瘀汤加减","formulaNames":["血府逐瘀汤"]},{"t":"syn","sid":"s061302","name":"蕴毒腐溃证","clinic":"褥疮溃烂，腐肉及脓水较多，或有恶臭，严重者溃烂深达筋骨，四周漫肿；伴有发热或低热，精神菱靡，不思饮食；舌红苔少，脉细数","treat":"益气养阴，理气托毒","formula":"生脉散、透脓散加减","formulaNames":["生脉散","透脓散"]},{"t":"syn","sid":"s061303","name":"气血两虚证","clinic":"疮面腐肉难脱，或腐肉虽脱但疮色淡，愈合缓慢；伴有面色无华，神疲乏力，纳差食少；舌淡苔少，脉沉细无力","treat":"补气养血，托毒生肌","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起局部按摩，外擦红灵酒或外撒滑石粉。"},{"t":"p","x":"或用红外线、频谱仪照射，每日2次。"},{"t":"p","x":"(2)溃疡期清除坏死组织，腐烂处用九一丹或红油膏纱条外敷；"},{"t":"p","x":"脓水较多，可用蒲公英、紫花地丁、马齿苋各30g水煎溶液湿敷或淋洗。"},{"t":"p","x":"(3)溃疡后期疮口腐肉脱净，改用生肌散、生肌玉红膏，必要时加用垫棉法。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)负压封闭引流技术利用专用敷料填塞或覆盖创面、用生物半透膜密封，通过引流管连接负压源，进行持续或间断的负压吸引，及时、彻底地清除创面渗液、脓液和坏死组织。"},{"t":"p","x":"(2)手术疗法常见以下方法："},{"t":"p","x":"清创术：对于大面积、深达骨面、经保守治疗无效的褥疮，采用机械清创、酶学清创、自溶性清创等、彻底清除坏死、失活组织。植皮术：非骨突部位的浅表创面，基底肉芽组织生长良好，难以自行上皮化愈合，采用植皮术，加速创面覆盖。"},{"t":"p","x":"皮瓣移植术：对于骨、肌腱外露的褥疮，将带有血液供应的皮肤、皮下组织乃至肌肉的复合组织块(皮瓣)转移至创面，能够封闭创面，提供良好的血运和软组织垫，促进修复。"}]}],"entries":["e0219","e0220","e0221","e0222","e0223","e0224"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强护理，重在预防。长期卧床患者应定时翻身，受压部位保持皮肤干燥，床褥柔软透气，或使用气垫床，或用50%酒精擦洗，或用滑石粉外擦。"},{"t":"p","x":"2.发现受压部位皮肤颜色变暗，应及时就医处理。3.加强营养，积极治疗基础病。"}],"entries":["e0225"]}]},{"id":"d0700","kind":"chapter","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"本章概述","displayName":"乳房疾病·本章概述","parentId":"","printedPage":86,"pdfPage":101,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"发生在乳房的疾病统称为乳房疾病。女性发病率显著高于男性。"},{"t":"p","x":"《妇科玉尺·妇女杂病》指出：“妇女之疾，关系最钜者，则莫如乳。"},{"t":"p","x":"本病早在汉代就有记载。历代文献对多种乳房疾病的病因、症状、治法有比较详细的描述，对现代诊治乳房疾病仍有一定的指导意义。"},{"t":"p","x":"本章讨论的主要内容包括乳痈、乳发、粉刺性乳痈、乳痨、乳漏、乳癖、乳疬、乳核、乳岩、乳衄等。"}],"entries":["e0226"]},{"title":"乳房与脏腑经络的关系","blocks":[{"t":"p","x":"乳房位于胸前第2和第6肋骨水平之间，由乳头、乳晕、乳络、乳囊组成。脏腑功能与乳房的生理病理关系密切。"},{"t":"p","x":"肾为先天之本，主藏精，肾气盛则天癸至，女子月事按时而下，乳房发育，孕育后分泌乳汁而哺乳；肾气衰则天癸竭，乳房随之衰萎。"},{"t":"p","x":"脾胃为后天之本，气血生化之源，乳汁由水谷精微化生，脾胃气壮则乳汁多而浓，反之则少而稀。肝主藏血，主疏泄，对女性月经、胎产及乳汁的排泄至关重要。"},{"t":"p","x":"乳房与肝经、胃经、肾经及冲任两脉息息相关，足阳明胃经行贯乳中；足太阴脾经络胃上膈，布于胸中；"},{"t":"p","x":"足厥阴肝经上膈，布胸胁，绕乳头而行；足少阴肾经上贯肝膈而与乳相联。"},{"t":"p","x":"冲任两脉起于胞中。任脉循腹里，上关元至胸中；冲脉夹脐上行，至胸中而散。"},{"t":"p","x":"故有称“男子乳头属肝，乳房属肾；女子乳头属肝，乳房属胃”。若脏腑功能失常，经脉闭阻不畅，冲任失调，均可导致乳房疾病的发生。"}],"entries":["e0227"]},{"title":"病因病机","blocks":[{"t":"p","x":"乳房疾病的发生主要是由于肝气郁结，或胃热壅滞，或痰瘀凝结，或肝肾不足，或乳汁蓄积，或外邪侵袭等，影响相关脏腑、经脉的生理功能而产生病变。如《外证医案汇编》曰：“乳症，皆云肝脾郁结，则为癖核；胃气壅滞，则为痈疽。"},{"t":"p","x":"化脓性乳房疾病多因乳头破碎或畸形、感染邪毒，或嗜食厚味、脾胃积热，或情志内伤、肝气不舒，以致乳汁郁滞，排泄障碍，或痰浊壅滞，郁久化热，热胜肉腐而成脓肿。"},{"t":"p","x":"肿块性乳房疾病多因忧思郁怒，肝脾受损，气滞痰凝，或肝肾不足，冲任失调，气血运行失常，导致气滞、血瘀、痰凝，阻滞乳络而成。"}],"entries":["e0228"]},{"title":"辨证要点","blocks":[{"t":"p","x":"临床辨证除观察乳房局部病变外，尚须结合全身症状，从而辨证求因、审因论治。现将辨证要点归纳分述如下："},{"t":"p","x":"1.肝胃郁热由于肝气不舒，失于条达，胃经积热，经络阻塞，气血瘀滞，日久化热，致局部红肿热痛，成脓时则剧痛。2.肝气郁结情志不畅，郁闷忧思，致肝气不舒而失于条达，气不舒则气滞血瘀；"},{"t":"p","x":"肝郁犯脾，脾失健运，则痰浊内生。气滞痰瘀互结而成肿核，形如桃李，质地坚实或坚硬，表面光滑，推之可动或固定不移。"},{"t":"p","x":"3.肝肾不足由于先天不足或后天失调，以致肝肾亏损，冲任失调，精血不足，水不涵木，易致肝火上升，火灼津为痰，痰瘀互结，聚而成核。乳核生长与发展，常与发育、月经、妊娠等有关，胀痛常在经前加重。"},{"t":"p","x":"4.阴虚痰凝由于肺肾阴虚，肺津不布。致阴虚火旺。灼津为痰，痰火循经结于乳房。其肿块皮色不变、微微作痛，化脓迟缓。脓水清稀。"},{"t":"p","x":"常伴有午后潮热，夜间盗汗，形瘦食少；舌质红。苔满白。脉细数。如乳痨。"}],"entries":["e0229"]},{"title":"乳房检查方法","blocks":[{"t":"p","x":"及时正确地进行乳房检查、对于乳房疾病的早期发现、早期诊断有着重要意义。乳房检查的体位可采用立位、坐位或仰卧位。"},{"t":"p","x":"1.望诊患者站立，乳房完全显露。注意乳房的形状、大小是否对称；"},{"t":"p","x":"乳房表而有无突起或凹陷、皮肤如果有凹陷，可让患者两臂高举过头，或用手抬高乳房，使凹陷部分更为明显；乳头有无内缩或抬高；"},{"t":"p","x":"乳房皮肤有无发红、水肿，或橘皮样、湿疹样改变等；乳房浅表静脉是否怒张。"},{"t":"p","x":"2.触诊立位与卧位相结合，根据需要选择。应先检查健侧乳房，再检查患侧，以便对比。"},{"t":"p","x":"正确的检查方法是四指并拢，用指腹平放在乳房上轻柔触摸，切勿用手指去抓捏，否则会将捏起的腺体组织误认为是乳腺肿块。"},{"t":"p","x":"其顺序是先触按整个乳房，然后按照一定顺序触按乳房的四个象限：外上(不要遗漏腋尾部)、外下、内下、内上象限，继而触按乳晕部，挤压乳头，注意有无液体从乳窍溢出。最后触摸腋窝、锁骨下及锁骨上，检查区域淋巴结情况。"},{"t":"p","x":"触诊时应注意以下几个问题：①发现乳房内有肿块时，应注意肿块的位置、数目、形状、大小、质地、边界、表面情况、活动度及有无压痛。"},{"t":"p","x":"②肿块是否与皮肤粘连，可用手指轻轻提起肿块附近的皮肤，以确定有无粘连。"},{"t":"p","x":"③检查乳房的时间最好选择在月经来潮的第7～10天，因为这段时间是乳房生理最平稳时期，如有病变容易被发现。"},{"t":"p","x":"④确定肿块的性质，还需要结合年龄、病史及其他辅助检查结果。"},{"t":"p","x":"触诊的准确性取决于经验、手感、正确的检查方法等。腋窝淋巴结、锁骨上下淋巴结的检查在乳房疾病诊断中也很重要。"},{"t":"p","x":"检查时医生与患者正对而立，用左手检查患者右侧，用右手检查患者左侧，并让患者将上臂靠近胸壁，前臂松弛放在检查者的手臂上。先查腋窝，再查锁骨上区域及锁骨下区域。"},{"t":"p","x":"如触及淋巴结，应注意其位置、数目、形状、大小、质地、边界、表面情况、活动度及有无压痛等。"}],"entries":["e0230"]},{"title":"常用辅助检查","blocks":[{"t":"p","x":"1.超声检查乳房超声属无损伤性检查，对年轻女性更为合适，可清晰显示乳腺的解剖层次，明确病灶位置，对乳腺囊性或实性肿块的鉴别有意义。"},{"t":"p","x":"乳腺良恶性病变的超声鉴别可在二维声像图的基础上结合彩色多普勒观察血流情况，提高判断的准确性。2.钼靶X线摄影钼靶摄片可观察乳腺腺体结构、肿块、钙化情况。"},{"t":"p","x":"典型乳腺癌钼靶摄片表现为密度增高的肿块影，边界不规则，或有毛刺征，腺体结构扭曲，颗粒细小、密集的钙化等影像特征。"},{"t":"p","x":"3.磁共振乳房磁共振是一种无放射性损伤的检查方式，具有良好的分辨率，能够三维立体观察乳房病变，对于乳房病变性质、病变范围都有极高的敏感性和较高的特异性、能更好地显示病灶的大小、形态、位置及范围，为疾病诊断和外科手术提供有价值的参考。"},{"t":"p","x":"4.病理检查乳腺肿块可进行细针穿刺细胞学检查和空心针定位穿刺组织病理学检查。对疑为乳腺癌者，也可行肿块切除手术，做快速冰冻切片进行病理诊断、但不主张做肿块部分切取活检。"},{"t":"p","x":"有乳头溢液者，可做溢液涂片细胞学检查。乳头糜烂疑为湿疹样乳腺癌时，可做乳头糜烂部刮片或印片细胞学检查。"}],"entries":["e0231"]},{"title":"治疗","blocks":[{"t":"p","x":"1.内治《外证医案汇编·乳胁腋肋部》指出：“治乳症，不出一气字定之矣。”“若治乳从一气字着笔，无论虚实新久、温凉攻补，各方之中夹理气疏络之品，使其乳络疏通。"},{"t":"p","x":"气为血之帅，气行则血行⋯⋯自然壅者易通，郁者易达、结者易散，坚者易软。”《外科正宗·乳痈乳岩论》在乳痈、乳岩治法中说：“初起发热恶寒，头眩体倦，六脉浮数，邪正在表、宜散之。"},{"t":"p","x":"发热无寒，恶心呕吐，口千作渴，胸膈不利者、宜清之。忧郁伤肝，思虑伤脾，结肿坚硬微痛者，宜疏肝行气。"},{"t":"p","x":"已成焮肿发热，疼痛有时，已欲作脓者，宜托里消毒。脓已成而胀痛者，宜急开之。"},{"t":"p","x":"脾胃虚弱，宜更兼补托。溃而不敛，脓水清稀，肿不消、疼不止，宜大补气血。"},{"t":"p","x":"结核不知疼痛，久而渐大，破后惟流污水，宜养血清肝。”现将常用治法分述如下："},{"t":"p","x":"(1)疏风解表法适用于乳痈、乳发等初起证属邪阻经络，营卫不和者。"},{"t":"p","x":"乳房结块肿痛；伴有恶寒发热；舌苔薄白，脉浮数。选方瓜蒌牛蒡汤、银翘散等。"},{"t":"p","x":"(2)疏肝清热法适用于乳痈、粉刺性乳痈等证属肝郁化热者。"},{"t":"p","x":"乳房结块红肿高突，灼热疼痛，中软应指；舌苔黄，脉弦数。选方内疏黄连汤、柴胡清肝散等。"},{"t":"p","x":"(3)扶正托毒法适用于乳痈、乳痨、乳漏、乳岩等证属气血两虚，不能托毒外出，或脓虽外泄却难以生肌收口者。"},{"t":"p","x":"疮形平塌，漫肿不收，日久不易破溃，隐隐作痛；或溃后脓水清稀，久不收口；或乳岩破溃渗流血水；舌质淡红，脉沉细无力。"},{"t":"p","x":"选方托里透脓汤、托里消毒散、香贝养荣汤、归脾汤等。"},{"t":"p","x":"(4)解郁化痰法适用于乳癖、乳岩等证属肝失疏泄、痰气互结者。"},{"t":"p","x":"乳房胀痛，结块形成，质地坚实或坚硬，表面光滑，推之可动或固定不移；舌苔白腻，脉弦滑。"},{"t":"p","x":"选方开郁散、逍遥蒌贝散、小金丹等。"},{"t":"p","x":"(5)调摄冲任法适用于乳疬、乳癖等证属肝肾不足、冲任失调者。"},{"t":"p","x":"乳房结块的发生或发展常与乳房发育或月经、妊娠等有关，或乳房胀痛常在月经前加重；伴有头晕耳鸣，腰酸肢软，发育不良，或月经不调；"},{"t":"p","x":"舌苔薄，脉弦细数。选用二仙汤、右归饮、六味地黄丸等。"},{"t":"p","x":"(6)滋阴化痰法适用于乳痨证属肺肾阴虚、痰火凝结者。"},{"t":"p","x":"乳房肿块初起皮色不变，微微作痛，化脓时皮色暗红，化脓迟缓，溃后脓水清稀，易成窦道；舌红苔薄，脉细数。"},{"t":"p","x":"选方消疬丸、六味地黄汤、清骨散等。"},{"t":"h","lv":2,"x":"2.外治"},{"t":"p","x":"(1)敷贴应区分阳证和阴证。"},{"t":"p","x":"①乳痈、乳发、粉刺性乳痈等属阳证，初起宜以清热解毒、活血消肿为主，用金黄散、玉露散、双柏散等，以水或蜜调后外敷，每日1～2次，或用金黄膏、玉露膏外敷；"},{"t":"p","x":"脓成后宜及时切开排脓；溃破后提脓祛腐，选用药线引流；"},{"t":"p","x":"脓尽腐脱，肉芽新鲜，改用生肌散、生肌玉红膏等。"},{"t":"p","x":"②乳痨等属阴证，初起用阳和解凝膏掺桂麝散或黑退消敷贴；"},{"t":"p","x":"脓熟后可切开排脓；溃后用药线引流，红油膏盖贴；"},{"t":"p","x":"腐脱肉红，改用生肌散、生肌玉红膏。"},{"t":"p","x":"(2)手术对肿块性乳房疾病，经积极药物治疗无明显好转时，或疑有恶变者，应及时手术切除肿块。"}],"entries":["e0232"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.避免长期忧思郁怒、焦虑紧张，保持规律作息。2.日常保持乳头、乳晕清洁。"},{"t":"p","x":"3.发现乳头内陷(先天或后天)，需尽早纠正。4.适度运动，保持充足睡眠，避免过度劳累。"},{"t":"p","x":"5.月经结束后3～7天，可自我检查乳房。6.每半年至1年做1次乳腺超声，40岁以上女性每1年至1年半加做1次乳房钼靶。"},{"t":"p","x":"7.避免长期穿过紧的上衣，选择尺码合适、透气的内衣。8.经期：注意保暖、忌生冷饮食，减少剧烈运动，缓解乳房胀痛。"},{"t":"p","x":"9.哺乳期：掌握正确哺乳姿势，每次哺乳后排空乳汁；乳头皲裂时，及时用温和药膏护理；"},{"t":"p","x":"暂停患侧哺乳时，用吸奶器排空。10.绝经后：关注乳房萎缩变化，定期检查，避免随意服用激素类保健品。"},{"t":"p","x":"11.严格按疗程服药、外用药清洁局部后使用，避免擅自停药或更换药物。12.化脓性疾病忌食辛辣、发物，肿块性疾病忌食含激素食物。"}],"entries":["e0233"]}]},{"id":"d0701","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳痈","displayName":"乳痈","parentId":"","printedPage":89,"pdfPage":104,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳痈是发生在乳房的最常见的急性化脓性疾病。"},{"t":"p","x":"其临床特点是乳房结块，红肿热痛，溃后脓出稠厚，伴恶寒发热等全身症状。好发于产后1个月以内的哺乳妇女，尤以初产妇为多见。"},{"t":"p","x":"发生于哺乳期的称“外吹乳痈”，占到全部乳痈病例的90%以上；发生于怀孕期(妊娠期)的称“内吹乳痈”；在非哺乳期和非妊娠期发生的称为“不乳儿乳痈”，临床少见。"},{"t":"p","x":"乳痈之名首见于晋代皇甫谧《针灸甲乙经·妇人杂病》，曰：“乳痈有热，三里主之。”古代文献中亦有称“妒乳”“吹乳”“乳毒”等。"},{"t":"p","x":"本病相当于西医学的急性化脓性乳腺炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"外吹乳痈多因肝郁胃热，或夹风热毒邪侵袭，乳汁淤积，乳络闭阻，气血瘀滞，热盛肉腐而成脓。内吹乳痈多由妊娠期胎气上冲，结于阳明胃络而成，色红者多热，色白者气郁胎旺。"},{"t":"p","x":"1.肝胃蕴热乳头属肝，乳房属胃。新产伤血，肝失所养，若忿怒郁闷，肝气不舒，则肝之疏泄失畅，乳汁分泌或排出失调，或饮食不节，胃中积热，或肝气犯胃，肝胃失和，郁热阻滞乳络，均可导致乳汁淤积，气血瘀滞，热盛肉腐。"},{"t":"p","x":"2.乳汁淤积因乳头破碎，怕痛拒哺，或乳头内陷等先天畸形，妨碍乳汁排出，或乳汁多而少饮，或初产妇乳络不畅，或断乳不当，均可引起乳汁淤滞不得出，宿乳蓄积，化热酿脓。"},{"t":"p","x":"3. 外邪侵袭新产体虚，哺乳露胸，感受风邪，或乳头破碎，外邪乘隙而入，或乳儿含乳，口中热气入乳窍，邪热蕴结于肝胃之经，闭阻乳络，热盛肉腐。"},{"t":"p","x":"西医学认为，本病多因产后乳汁淤积，或乳头破损，细菌沿淋巴管、乳管侵入乳房，继发感染。致病菌多为金黄色葡萄球菌。"}],"entries":["e0234","e0235"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现本病多见于产后未满月的哺乳期妇女，尤其是初产妇。"},{"t":"p","x":"初起乳房局部肿胀疼痛，乳汁排出不畅，或有结块。伴恶寒发热、头痛骨楚，或胸闷不舒，纳少泛恶，大便干结等。"},{"t":"p","x":"成脓期乳房结块逐渐增大，疼痛加重，或焮红灼热，同侧腋窝淋巴结肿大压痛。伴壮热不退，口渴喜饮，便秘溲赤。"},{"t":"p","x":"7～10天成脓。若初起大量使用抗生素或过用寒凉中药，导致乳房局部结块质硬，迁延数月难消。"},{"t":"p","x":"部分僵块也可再次染毒酿脓。若邪热鸱张则可发展为乳发、乳疽，甚至出现热毒内攻脏腑的危象；"},{"t":"p","x":"若脓出肿痛不减，身热不退，可能形成袋脓，或脓液旁侵形成传囊乳痈；若乳汁从疮口溢出，或疮口脓水淋沥，久难收口，则为乳漏。"},{"t":"p","x":"均为乳痈之变证。"},{"t":"p","x":"(2)辅助检查血常规、C反应蛋白(CRP)、脓液培养等检查有助于明确病情。"},{"t":"p","x":"B超检查有助于确定脓肿形成与否和脓肿的位置、数目、范围。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-1)"},{"t":"table","img":"img/tab/t0701.jpg","cap":"表7-1乳痈与粉刺性乳痈、炎性乳腺癌的鉴别"}],"entries":["e0236"]},{"title":"治疗","blocks":[{"t":"p","x":"强调及早处理，以消为贵。注重疏络通乳，避免过用寒凉药物。"},{"t":"p","x":"积极配合使用多种外治法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070101","name":"肝胃郁热证","clinic":"乳房肿胀疼痛，结块或有或无，皮色不变或微红，排乳不畅；伴恶寒发热，头痛骨楚，胸闷呕恶，纳谷不馨，大便干结；舌质红，苔薄白或薄黄，脉浮数或弦数","treat":"疏肝清胃，通乳消肿","formula":"瓜蒌牛蒡汤加减。乳汁壅滞者，加鹿角霜、漏芦、王不留行、路路通等通络下乳","formulaNames":["瓜蒌牛蒡汤"]},{"t":"syn","sid":"s070102","name":"热毒炽盛证","clinic":"乳房肿痛加重，结块增大，皮肤焮红灼热，继之结块中软应指，或脓出不畅，红肿热痛不消；伴壮热不退，口渴喜饮，便秘溲赤；舌质红，苔黄腻，脉洪数","treat":"清热解毒，托里透脓","formula":"五味消毒饮合透脓散加减。热甚者，加生石膏、知母清热除烦","formulaNames":["五味消毒饮","透脓散"]},{"t":"syn","sid":"s070103","name":"正虚邪滞证","clinic":"溃后乳房肿痛减轻，脓液清稀，淋沥不尽，日久不愈，或乳汁从疮口溢出；伴面色少华，神疲乏力，或低热不退，纳谷不馨；舌质淡，苔薄，脉细","treat":"益气和营，托毒生肌","formula":"托里消毒散加减。漏乳者，加山楂、麦芽回乳","formulaNames":["托里消毒散"]},{"t":"syn","sid":"s070104","name":"气血凝滞证","clinic":"乳房结块质硬，微痛不热，皮色不变或暗红，日久不消；舌质正常或瘀暗，苔薄白，脉弦涩","treat":"疏肝活血，温阳散结","formula":"四逆散加鹿角片、桃仁、丹参等","formulaNames":["四逆散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起因乳汁淤积而局部肿痛者可予手法按摩。"},{"t":"p","x":"按摩前宜先行热敷5～10分钟，并嘱患者取坐位，搽以少量润滑剂。术者站在患者身侧或身后，左手托起乳房，右手五指顺着乳络方向，首先轻拿提拉乳头及乳晕部；"},{"t":"p","x":"继而采用五指指腹揉、推、挤、抓的手法，按摩患乳部硬结肿块处，沿放射状从乳房向乳晕部揉抓；随后、右手拇指与食指夹持患侧乳晕及乳头部，不断轻拉揪提，宿乳即喷射状排出；"},{"t":"p","x":"直至结块消失、乳房松软、瘀乳排尽，疼痛明显减轻为度。操作宜轻柔。"},{"t":"p","x":"对于有成脓征象者，应禁忌使用。皮肤红热明显者，可用金黄散或玉露散或双柏散，加冷开水或金银花露调敷；"},{"t":"p","x":"或鲜菊花叶、鲜蒲公英、仙人掌单味适量捣烂外敷；或金黄膏或玉露膏外敷。"},{"t":"p","x":"皮色微红或不红者，用冲和膏外敷。"},{"t":"p","x":"(2)成脓宜切开排脓。"},{"t":"p","x":"脓肿在乳房部，做放射状切口或循皮纹切开；乳晕部脓肿，宜在乳晕旁做弧形切口；"},{"t":"p","x":"乳房后位脓肿，宜在乳房下方皱襞部做弧形切口。"},{"t":"p","x":"(3)溃后用药线引流，外敷金黄膏；"},{"t":"p","x":"脓腔较大者可用油膏纱布填塞；待脓净流出黄稠滋水，改用生肌散、红油膏或白玉膏盖贴。"},{"t":"p","x":"可配合垫棉法加快愈合。"},{"t":"p","x":"(4)袋脓或乳汁从疮口溢出可加用垫棉法。"},{"t":"p","x":"若失败则做扩创引流。"},{"t":"p","x":"(5)传囊若红肿疼痛明显，则按初起处理；"},{"t":"p","x":"若局部已成脓，宜再做一辅助切口引流或用拖线法。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)抗生素出现壮热不退，热毒内攻脏腑危象时须加用抗生素。"},{"t":"p","x":"(2)针灸疗法适用于乳痈初起。"},{"t":"p","x":"选取肩井、膻中、足三里、列缺、膈俞、血海等穴，泻法15分钟，每日1次。"},{"t":"p","x":"(3)回乳先减少哺乳次数以减少乳汁分泌，再用麦芽、山楂各60g，或生枇杷叶15g(包)煎汤代茶，外敷芒硝。"},{"t":"p","x":"酌情使用溴隐亭2.5mg口服。"}]}],"entries":["e0237","e0238","e0239","e0240","e0241","e0242","e0243"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.及早纠正乳头内陷，及时治疗乳头破碎。2.培养良好的哺乳习惯，注意乳头和乳儿口腔的清洁。"},{"t":"p","x":"3.忌食辛辣炙煿之品，保持心情舒畅。4.高热时可采用物理降温。"},{"t":"p","x":"须用吸奶器吸尽乳汁，或手法推拿排空乳汁。"}],"entries":["e0244"]}]},{"id":"d0702","kind":"attach","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳发","displayName":"乳痈·乳发","parentId":"d0701","printedPage":91,"pdfPage":106,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳发是发生在乳房且容易溃烂坏死的急性化脓性疾病。"},{"t":"p","x":"其临床特点是病变范围较乳痈大，局部焮红漫肿疼痛，迅速出现皮肉腐烂，病情较重，甚至可发生热毒内攻。多发生于哺乳期妇女。"},{"t":"p","x":"本病相当于西医学的乳房部蜂窝织炎或坏疽。本病的主要致病因素：①外感六淫：外感风温、湿热之邪，侵袭乳房肌肤，致使局部气血凝滞，经络阻塞，进而化热酿毒，腐肉成脓。"},{"t":"p","x":"②情志内伤：情志不畅，肝郁化火、加之胃热壅滞，肝胃蕴热，循经上攻乳房，气血凝滞，热盛肉腐。"},{"t":"p","x":"③饮食不节：过食辛辣炙煿、膏粱厚味，脾胃运化失常，湿热内生，蕴结于乳房，热盛肉腐。"},{"t":"p","x":"④乳汁淤积：对于产后妇女，若乳汁排出不畅，乳汁淤积于乳房内，可化热酿毒，若未能及时消散，病情发展可致本病。"},{"t":"p","x":"临床发病较急，主要分为初期、成脓期、溃后期。各期临床表现：①初期：乳房部皮肤焮红漫肿，疼痛剧烈，伴有恶寒发热、头痛骨楚等全身症状。"},{"t":"p","x":"乳房局部皮肤呈现大片红肿，边界不清，触痛明显，皮温升高。全身症状可表现为发热，体温升高，同时伴有怕冷、头痛、全身关节酸痛等。"},{"t":"p","x":"②成脓期："},{"t":"p","x":"发病数日后，肿块中央变软，按之应指，局部皮肤湿烂，继而发黑溃腐，迅速向周围扩散，可累及全乳；常伴高热、溲赤等全身症状。"},{"t":"p","x":"乳房局部皮肤可出现破溃，流出大量脓液、伴有恶臭，周围皮肤红肿范围扩大。全身症状加重，高热持续不退，患者可出现口渴喜饮、大便干结、小便短赤等。"},{"t":"p","x":"③溃后期：若腐肉渐脱，新肉生长，身热渐退，可逐渐愈合。"},{"t":"p","x":"若病情严重，正虚邪盛，出现高热神昏、烦躁不安等逆证，可危及生命。病情好转时，乳房疮面腐肉逐浙脱落、有新鲜肉芽组织生长，全身症状逐渐减轻。"},{"t":"p","x":"如果患者体质虚弱、病情未能得到有效控制、邪毒内陷、可出现高热、谵语等严重的全身中毒症状、预后较差。血常规检查示：白细胞总数及中性粒细胞比例明显增高。"},{"t":"p","x":"脓液或乳汁或血液细菌培养及药敏试验有助于选用抗生素。内治：初起治宜清肝泻火、解毒利湿，方用龙胆泻肝汤加减。"},{"t":"p","x":"成脓时佐以透托，前方加皂角刺等。若出现火毒内攻之证，治宜清热解毒、凉血开窍，方用犀角地黄汤合黄连解毒汤、安宫牛黄丸等加减。"},{"t":"p","x":"外治：可参照乳痈的处理方法。全身治疗需要加用抗生素，首选广谱抗革兰阳性菌抗生素，或根据细菌培养结果选择。"},{"t":"p","x":"酌情使用支持疗法。"}],"entries":["e0245"]}]},{"id":"d0703","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"粉刺性乳痈","displayName":"粉刺性乳痈","parentId":"","printedPage":92,"pdfPage":107,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"粉刺性乳痈是发生于非哺乳期、非妊娠期女性的慢性炎症性乳腺疾病。"},{"t":"p","x":"其临床特点是常有乳头凹陷或溢液，溃破后脓液中夹有粉刺样物质，反复发作，形成瘘管，经久难愈。历代文献中并无与之相符的疾病记载。"},{"t":"p","x":"1985年顾伯华主编的《实用中医外科学》中首次提出了“粉刺性乳痈”的病名。本病相当于西医学的浆细胞性乳腺炎、肉芽肿性小叶性乳腺炎、乳腺导管扩张症等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"素有乳头凹陷畸形，加之情志抑郁不畅，肝郁气滞，营气不从，经络阻滞，气血瘀滞，聚结成块，郁蒸腐肉酿脓而成，溃后容易成瘘管；若气郁化火，迫血妄行，可有乳头溢血。"},{"t":"p","x":"西医学认为，本病多由乳头凹陷或乳腺导管上皮细胞脱落及大量脂质分泌物积聚于导管内而导致其扩张，积聚物刺激导管壁而引起炎性细胞浸润和纤维组织增生。"},{"t":"p","x":"逐渐累及腺叶而形成肿块，炎症急性发作时可形成脓肿，脓液中常夹有脂质样物质，脓肿破溃后可形成通往输乳孔的瘘管。"}],"entries":["e0246","e0247"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于非哺乳期、非妊娠期的女性。"},{"t":"p","x":"单侧乳房发病多见，也可双侧发病。偶见于男性。"},{"t":"p","x":"病程可持续数月或数年。部分患者伴有先天性乳头凹陷，可伴粉刺样分泌物或淡黄色油脂样分泌物。"},{"t":"p","x":"本病临床表现复杂多样，常见以下症状：乳头溢液：可以是本病早期的一种表现。"},{"t":"p","x":"多表现为间歇性、自发性，并可持续较长时间。溢液性状多为浆液样，也有乳汁样、脓血性或血性，数量或多或少。"},{"t":"p","x":"先天性乳头凹陷者乳窍多有粉刺样物分泌，并带有臭味。乳房肿块：是本病最为常见的表现。"},{"t":"p","x":"往往起病突然，发展迅速。乳房局部疼痛不适，有刺痛或钝痛，触诊可及肿块。"},{"t":"p","x":"肿块大小不等，形状不规则，质地硬韧，表面可呈结节样，边界欠清，常与皮肤粘连，但无胸壁固定，可推移。继而肿块局部可出现红肿热痛，红肿范围迅速扩大，形成脓肿；"},{"t":"p","x":"有的乳房皮肤水肿，呈橘皮样变。可伴患侧腋下淋巴结肿大、压痛。"},{"t":"p","x":"一般无发热等全身症状。也有部分患者一直以乳房肿块为主诉，持续数年而始终无明显的红肿表现。"},{"t":"p","x":"乳漏：脓肿自溃或切开后，脓液夹有粉刺样物，常形成与乳孔相通的漏管，迁延不愈，反复发作。"},{"t":"p","x":"(2)辅助检查乳腺超声和磁共振检查有助于明确诊断，判断病变范围。"},{"t":"p","x":"一般脓液培养无细菌生长。乳腺空芯针穿刺病灶组织病理学检查可见非特异性炎症性病变。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-2)"},{"t":"table","img":"img/tab/t0702.jpg","cap":"表7-2粉刺性乳痈与乳岩、乳晕部疖、乳衄的鉴别"}],"entries":["e0248"]},{"title":"治疗","blocks":[{"t":"p","x":"中医药治疗本病有良好的疗效，在辨证论治的同时，注意内治与外治相结合。未溃偏重内治，已溃偏重外治，而且药物外治、手术外治及其他外治方法根据具体情况配合使用。"},{"t":"p","x":"乳头溢液患者宜寻找病因，适当对症处理。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070301","name":"肝经蕴热证","clinic":"乳头溢液或乳头凹陷有粉刺样物溢出，乳房结块红肿疼痛，按之灼热；伴发热，头痛，大便干结，尿黄；舌质红，舌苔黄腻，脉弦数或滑数","treat":"疏肝清热，活血消肿","formula":"柴胡清肝汤加白花蛇舌草、山楂等。乳头有血性溢液者，加茜草炭、牡丹皮、生地榆、仙鹤草；乳头溢液呈水样者，加生薏苡仁、茯苓；脓成者，加白芷、皂角刺","formulaNames":["柴胡清肝汤"]},{"t":"syn","sid":"s070302","name":"余毒未清证","clinic":"脓肿自溃或切开后久不收口，脓水淋沥，形成乳漏，时发时敛，局部有僵硬肿块或红肿溃破；舌质淡红或红，舌苔薄黄，脉弦","treat":"益气扶正，和营托毒","formula":"托里消毒散加减。局部僵块明显者，加桃仁、鹿角片；脓水稀薄，创面色淡者，倍生黄芪，加熟地黄、枸杞子；乳头孔或脓水中脂质分泌物多者，加乌梅、炒谷芽、炒麦芽","formulaNames":["托里消毒散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)肿块初起时用金黄膏外敷。"},{"t":"p","x":"(2)成脓后切开引流，术后创口药线或药捻引流，金黄膏盖贴。"},{"t":"p","x":"(3)复杂性瘘管或多发脓肿宜切开扩创，切开瘘管和脓腔，在探针引导下酌情切开通向乳头孔的瘘管，清除坏死组织。"},{"t":"p","x":"可根据情况选用乳头矫形法、拖线法及垫棉法等。"},{"t":"p","x":"(4)创面脓腐已净，采用生肌散、白玉膏等生肌敛疮之品促使愈合。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)病灶局限者可行乳腺区段切除缝合术。"},{"t":"p","x":"个别年龄较大、乳房肿块较大或皮肤粘连严重或形成多个窦道者，可行乳房单纯切除术或保留乳头、乳晕的乳腺切除术。"},{"t":"p","x":"(2)病情严重时可考虑酌情加用抗生素、糖皮质激素治疗。"}]}],"entries":["e0249","e0250","e0251","e0252","e0253"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持乳头清洁、经常清除分泌物，避免乳房受到外力撞击或佩戴过紧的文胸。2.发病后忌食海鲜、辛辣炙煿之物。"}],"entries":["e0254"]}]},{"id":"d0704","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳漏","displayName":"乳漏","parentId":"","printedPage":94,"pdfPage":109,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳漏是指发生于乳房或乳晕部位的脓肿破溃后，久不收敛而形成的慢性瘘管或窦道。"},{"t":"p","x":"其临床特点是疮口脓水淋沥，渗出物中可夹杂乳汁、豆腐渣样或脂质样分泌物，经久难愈。本病相当于西医学的乳房瘘管和窦道。"},{"t":"p","x":"若能早期诊断并及时治疗，一般预后良好；但部分患者可能迁延不愈，反复发作，治疗较为棘手。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.乳房部乳漏多因乳痈、乳发溃后或手术伤及乳络，脓液与乳汁外溢，久不愈合而成；亦可由乳痨溃破，体虚难愈所致。"},{"t":"p","x":"2.乳晕部漏管则多因乳头内陷，感染毒邪；或脂瘤染毒溃脓，疮口难以收敛，形成慢性漏道。"}],"entries":["e0255","e0256"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"乳房部漏管：多继发于乳痈、乳发或乳痨病史，疮口经久不愈，持续溢泌乳汁或脓血，疮面肉芽苍白不泽，周边皮肤浸淫潮湿。乳痨溃破成瘘者，疮口多凹陷，周围皮肤紫暗，脓水清稀或夹有败絮样物质，或伴有潮热、盗汗、舌质红、脉细数等。"},{"t":"p","x":"乳晕部漏管：多发于非哺乳或非妊娠期的妇女。常伴有乳头内缩，并在乳晕部有结块，红肿疼痛，全身症状较轻；"},{"t":"p","x":"溃后脓液中兼有灰白色脂质样物，带有臭气，疮孔与乳窍相通，反复发作，久不收口。"},{"t":"p","x":"(2)辅助检查乳腺导管或漏管X线造影常可明确乳漏的部位、漏管走向及支管情况。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-3)"},{"t":"table","img":"img/tab/t0703.jpg","cap":"表7-3乳漏和乳痨的鉴别"}],"entries":["e0257"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗的关键在于明确漏管形成的原因及其路径，以外治为主，内治为辅。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070401","name":"余毒未清证","clinic":"乳漏反复发作，红肿疼痛，疮口流脓或溢乳，结块僵硬，周围皮肤潮湿；舌红苔黄、脉滑数","treat":"清热解毒","formula":"银花甘草汤加减。疮口流脓水，加薏苡仁、冬瓜子、天花粉","formulaNames":["银花甘草汤"]},{"t":"syn","sid":"s070402","name":"正虚毒恋证","clinic":"漏口脓乳不止，肉芽暗淡；伴面色苍白，神疲乏力，气短懒言；舌淡苔白，脉细弱","treat":"扶正托毒","formula":"托里消毒饮加减。脓水清稀加肉桂、炮姜","formulaNames":["托里消毒饮"]},{"t":"syn","sid":"s070403","name":"阴虚痰热证","clinic":"脓出稀薄，夹有败絮状物质，疮口久不愈合，疮周皮色暗红；伴潮热顺红，形瘦食少；舌红苔少，脉细数","treat":"养阴清热","formula":"六味地黄汤合清骨散加减。潮热颧红明显加胡黄连、秦艽","formulaNames":["六味地黄汤","清骨散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)腐蚀法用八二丹或七三丹药捻，或中医搔刮祛除脓腐，外敷红油膏。"},{"t":"p","x":"脓尽后改用生肌散、生肌玉红膏，必须使创面从基底部长起。"},{"t":"p","x":"(2)垫棉法适用于疮口漏乳不止或乳房部漏脓腐脱尽后，以促进疮口愈合。"},{"t":"p","x":"(3)切开疗法适用于浅层漏管及药物外敷治疗失败者，手术的关键是切开通向乳头孔的漏管或扩张的乳腺导管。"},{"t":"p","x":"切开后创面用药同腐蚀法。"},{"t":"p","x":"(4)挂线疗法适用于深层漏管，常配合切开疗法。"}]}],"entries":["e0258","e0259","e0260","e0261","e0262"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗乳痈、乳发、乳痨，切开排脓时切口与乳络方向一致。2.乳头内陷者经常用温水清洗乳头，乳房部粉瘤及时行手术切除。"}],"entries":["e0263"]}]},{"id":"d0705","kind":"attach","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳痨","displayName":"乳漏·乳痨","parentId":"d0704","printedPage":95,"pdfPage":110,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳痨是发生于乳房部的慢性化脓性疾病，因其后期常伴有虚劳表现，故得此名；"},{"t":"p","x":"又因溃后脓液稀薄如痰，亦被称为“乳痰”。本病的临床特点是病程进展缓慢，初起乳房内出现一个或数个梅李样结块，边界不清，与皮肤粘连；"},{"t":"p","x":"日久破溃后脓液稀薄，多伴有阴虚内热之证。本病相当于西医学的乳房结核。"},{"t":"p","x":"乳痨多因患者素体虚弱，肺肾阴亏，以致阴虚火旺，虚火灼津为痰，痰火互结，凝聚成核；或因情志不畅，肝郁化火，进一步灼伤阴液，炼液为痰；"},{"t":"p","x":"亦可因肝气横逆犯脾，脾失健运，痰湿内生，终致痰火凝结，阻滞乳络而发病。此外，本病还可继发于肺痨、凛疬等其他虚损性或结核类疾病。"},{"t":"p","x":"乳痨好发于20～40岁体质偏弱的已婚女性，患者常伴有其他部位的结核病史。疾病初起时，乳房内出现一个或数个结块，大小不等，边界不清，质地硬而不坚，推之可动，不痛或微痛，皮色不变，全身症状常不明显。"},{"t":"p","x":"病情进展缓慢，数月后结块逐渐增大，与皮肤粘连，皮色微红或不红，逐渐变软成脓，并可伴有胸胁或腋下淋巴结肿大；此时多出现潮热颧红、形瘦食少、夜寐盗汗等虚热之象。"},{"t":"p","x":"脓肿破溃后，可形成单个或多个溃疡，流出稀薄如絮的脓液，疮口常呈潜行性空腔或窦道，同时全身可见明显虚象，如身体瘦弱、潮热盗汗、纳差神疲等。在疾病活动期，实验室检查常可见红细胞沉降率(ESR)增快，结核菌素试验呈阳性；"},{"t":"p","x":"脓液涂片检查中有时可发现结核杆菌。必要时可行病理组织切片检查，为明确诊断提供依据。"},{"t":"p","x":"治疗上通常采用规范的抗结核药物进行基础治疗。中医常用治法包括解郁化痰、软坚散结及养阴清热等。"},{"t":"p","x":"乳痨在临床可分为三种常见证型：①气滞痰凝证：多见于乳痨初起，症见乳房梅李状肿块，不红不热，质硬韧，微痛可动，或伴情志不畅、胸闷胁胀，苔薄腻，脉弦滑，治宜疏肝解郁、滋阴化痰，Q方选开郁散合消疬丸加减。"},{"t":"p","x":"②正虚邪恋证：多见于化脓或溃后，结块增大、皮色暗红、按之变软，溃后脓水稀薄夹败絮样物，久不敛口成窦道，伴面色㿠白、神疲纳差，舌淡苔薄白，脉虚无力，治宜托里透脓，方用托里消毒散加减。"},{"t":"p","x":"③阴虚痰热证：见脓稀夹败絮、窦道久不愈，伴潮热撷红、干咳形瘦，舌红少苔，脉细数，治宜养阴清热，方选六味地黄汤合清骨散加减。"},{"t":"p","x":"外治：初起宜用阳和解凝膏掺桂麝散或黑退消敷贴；成脓期波动感明显者，应及时切开排脓；"},{"t":"p","x":"溃后可插入七三丹或八二丹药线引流，外盖红油膏；待腐脱新生则改用生肌散、生肌玉红膏收口。"},{"t":"p","x":"若已形成漏管，可插入白降丹或红升丹药捻化腐蚀管，脓尽后再以生肌散促进愈合。抗结核治疗通常采用异烟肼、利福平与乙胺丁醇联合用药方案。"},{"t":"p","x":"在中医辨证指导下，可配合使用具有化痰散结、活血解毒功效的中成药辅助治疗，例如小金丹或内消凛疬丸。"}],"entries":["e0264"]}]},{"id":"d0706","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳癖","displayName":"乳癖","parentId":"","printedPage":96,"pdfPage":111,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳癖是指乳腺组织既非炎症也非肿瘤的良性增生性疾病。"},{"t":"p","x":"其临床特点是单侧或双侧乳房疼痛并出现肿块，乳痛和肿块之变化常与月经周期及情志波动密切相关。肿块常为多发性，形态不一，或呈颗粒、结节、片块状，边界不清、质韧、活动尚可，经前增大变硬、经后缩小软化。"},{"t":"p","x":"本病好发于25～45岁的中青年妇女，其发病率约占乳房疾病的75%，是临床上最常见的乳房疾病。历代文献有“乳癖”“乳中结核”“乳痞”等名称。"},{"t":"p","x":"明代龚居中《外科活人定本·卷之二》首将其定义为乳房肿块，谓：“乳癖，此症生于正乳之上，乃厥阴阳明经之所属也⋯⋯何谓之癖？若硬而不痛，如顽核之类。"},{"t":"p","x":"《医宗金鉴·外科心法要诀·胸乳部》称其为“乳中结核”，并系统提出辨证论治，曰：“初起气实者宜服清肝解郁汤，气虚宜服香贝养荣汤；若郁结伤脾，食少不寐者，服归脾汤。"},{"t":"p","x":"外俱用木香饼熨法，消之甚效。”本病相当于西医学的乳腺增生病。"},{"t":"p","x":"有研究发现，本病可能有一定的癌变倾向，有乳腺癌家族史者更应引起重视。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.情志不畅或郁怒伤肝，导致肝郁气滞，气血不畅，乳络受阻，引发乳房疼痛。日久气郁化火，炼津成痰，加之血行不畅而成瘀，终致气滞、痰凝、血瘀互结，聚积成块。"},{"t":"p","x":"2.因饮食不节、劳倦过度或思虑伤脾，致脾胃受损，运化失职，水湿内停，聚湿成痰。痰浊阻滞，气机不畅，影响血行，渐致瘀血内生。"},{"t":"p","x":"痰瘀互结，阻滞乳络，气血不通，发为乳癖。3.因肝肾不足，冲任失调，气血瘀滞，或脾肾阳虚，痰湿内结，经脉阻塞而致乳房结块、疼痛，月经不调。"}],"entries":["e0265","e0266"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病年龄多在25～45岁之间，城市女性发病率高于农村。"},{"t":"p","x":"此外，社会经济地位较高、受教育程度较高、月经初潮年龄较早、生育次数较少、初次怀孕年龄较大、未进行母乳喂养及绝经时间较晚的女性，均为本病的高危人群。乳房疼痛以胀痛为主，也可有呈刺痛或牵拉样痛。"},{"t":"p","x":"疼痛多与月经周期相关，经前加重，经后缓解，也可随情绪波动而变化。严重者疼痛明显，不可触碰，并在行走或活动时加剧。"},{"t":"p","x":"疼痛部位主要集中在乳房肿块处，并可向胸胁、肩背部放射。部分患者可伴有乳头疼痛和或瘙痒，乳痛重者影响工作或生活。"},{"t":"p","x":"乳房肿块可发生于单侧或双侧，多见于乳房外上象限，但也可见于其他象限。肿块质地中等或硬韧，表面光滑或呈颗粒状，活动度良好，多数伴有压痛。"},{"t":"p","x":"其大小不一、直径通常在1～2cm之间，较大者可超过3cm。肿块的形态常可分为以下几种类型：①片块型：肿块呈厚薄不等的片块状、圆盘状或长圆形，数目不一，质地中等或有韧性，边界清，活动度良好。"},{"t":"p","x":"②结节型：肿块呈扁平或串珠状结节，形态不规则，边界欠清，质地中等或偏硬，活动度好。"},{"t":"p","x":"亦可见肿块呈米粒或砂粒样结节。"},{"t":"p","x":"③混合型：有结节、条索、片块、砂粒样等多种形态肿块混合存在者。"},{"t":"p","x":"④弥漫型：肿块分布超过乳房3个象限以上者。"},{"t":"p","x":"乳房肿块可在经前期增大、变硬，经后则有所缩小、变软。个别患者可伴有乳头溢液，呈白色或黄色，或呈浆液状。"},{"t":"p","x":"乳房疼痛与肿块既可同时出现，也可先后发生；部分患者以疼痛为主，部分则以肿块更为突出。"},{"t":"p","x":"患者常伴有月经失调、心烦易怒等症状。"},{"t":"p","x":"(2)辅助检查乳房超声检查、钼靶X线摄片有助于诊断和鉴别诊断。"},{"t":"p","x":"对于肿块较硬或较大者，可考虑做组织病理学检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-4)"},{"t":"table","img":"img/tab/t0704.jpg","cap":"表7-4乳癖和乳岩的鉴别"}],"entries":["e0267"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗本病的关键在于缓解疼痛和消除肿块，应根据患者具体情况进行辨证论治。若患者长期服药后肿块未见消退，反而持续增大，且质地变硬、边缘不清，存在恶变疑虑时，应考虑手术切除治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070601","name":"肝郁痰凝证","clinic":"多见于青壮年妇女，乳房肿块，质韧不坚，胀痛或刺痛，症状随喜怒消长；伴有胸闷胁胀，善郁易怒，失眠多梦，心烦口苦；苔薄黄，脉弦滑","treat":"疏肝解郁，化痰散结","formula":"逍遥蒌贝散加减。乳房胀痛明显者，加延胡索、川楝子、八月札；心烦易怒者，加栀子、牡丹皮、黄芩等","formulaNames":["逍遥蒌贝散"]},{"t":"syn","sid":"s070602","name":"痰瘀互结证","clinic":"多见于中年女性，乳房肿块质硬，或有结节，疼痛位置固定；伴月经色暗夹血块；舌质紫暗或有瘀斑，苔白腻，脉沉涩","treat":"活血化瘀，化痰散结","formula":"二陈汤合桃红四物汤加减。疼痛明显者，加延胡索、川楝子；肿块坚硬者，加三棱、莪术；脾虚痰湿重者，加白术、苍术","formulaNames":["二陈汤","桃红四物汤"]},{"t":"syn","sid":"s070603","name":"冲任失调证","clinic":"多见于中年妇女，乳房肿块月经前加重，经后减缓，乳房疼痛较轻或无疼痛；伴有腰酸乏力，神疲倦怠，月经失调，量少色淡，或闭经；舌淡，苔白，脉沉细","treat":"调摄冲任，和营散结","formula":"二仙汤合四物汤加减。肿块较硬者、加生牡蛎、海藻、莪术等；伴有乳头溢液者，加白花蛇舌草、黄芩、蒲公英等；月经不调、腰膝酸软者，加菟丝子、女贞子、益母草等","formulaNames":["二仙汤","四物汤"]},{"t":"p","x":"月经不调、腰膝酸软者，加菟丝子、女贞子、益母草等。2.外治疗法阳和解凝膏掺黑退消或桂麝散盖贴；或用大黄粉以醋调敷。"},{"t":"p","x":"过敏者忌用。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针灸疗法常用穴位有乳根、膺窗、膻中、期门、内关等，以开郁结、调气血、止疼痛等。"},{"t":"p","x":"(2)按摩疗法按揉行间达太冲；"},{"t":"p","x":"或自乳头向下推按至期门穴36次，并压期门穴上轻揉72次。"}]}],"entries":["e0268","e0269","e0270","e0271","e0272"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.应保持心情舒畅、情绪稳定。2.适当控制脂肪类食物的摄入。"},{"t":"p","x":"3.及时治疗月经失调等妇科疾患和其他内分泌疾病。4.发病高危人群要重视定期检查。"}],"entries":["e0273"]}]},{"id":"d0707","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳疬","displayName":"乳疬","parentId":"","printedPage":98,"pdfPage":113,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳疬是指男女儿童或中老年男性在乳晕部出现的疼痛性结块。"},{"t":"p","x":"其临床特点是乳晕中央有扁圆形肿块，质地中等，伴轻压痛。《外科正宗·乳痈论》提出：“男子乳疾，与妇人微异，女损肝胃，男损肝肾。"},{"t":"p","x":"盖怒火房欲过度，以致肝虚血燥，肾虚精怯，血脉不得上行，肝筋无以荣养，遂结肿痛。”本病相当于西医学的乳房异常发育症。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"男子由于肾气不充，肝失所养；女子因冲任失调，气滞痰凝所致。中老年男性发病多因年高肾亏，或房劳伤肾，虚火自炎，或情志不畅，气郁化火，灼津成痰，导致痰火互结而成。"},{"t":"p","x":"西医学认为，本病与性激素代谢有关，或误食含雌激素的药物、食物所致，幼女患病应结合性早熟综合诊治。"}],"entries":["e0274","e0275"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现好发于50～70岁的中老年男性，10岁以下的女孩，13～17岁的男孩。"},{"t":"p","x":"乳房稍大或肥大，乳晕下有扁圆形肿块，质地中等或稍硬，边界清，活动佳，局部有压痛或胀痛、少数患者乳头有乳汁样分泌物。部分男性患者伴有发音较高、面部无须、臀部宽阔、阴毛呈女性分布等女性化征象；"},{"t":"p","x":"老年人可伴睾丸萎缩、前列腺肿瘤或肝硬化等。部分患者有长期使用雌激素类药物史。"},{"t":"p","x":"部分患者肿块会自行消失。"},{"t":"p","x":"(2)辅助检查可进行肝功能、性激素等检测，以及乳房、卵巢、睾丸、前列腺等超声检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-5)"},{"t":"table","img":"img/tab/t0705.jpg","cap":"表7-5乳疬与男性乳岩的鉴别"}],"entries":["e0276"]},{"title":"治疗","blocks":[{"t":"p","x":"需要寻找原发病因、如药物而致乳房肥大者，停药后即逐渐消退。有疼痛或其他兼症者，应辨证治疗。"},{"t":"p","x":"乳房明显肥大影响美观者，可考虑手术治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070701","name":"肝气郁结证","clinic":"性情急躁，遇事易怒，乳房肿块疼痛，触痛明显，胸胁牵痛；舌红，苔白，脉弦","treat":"疏肝散结","formula":"逍遥蒌贝散加减。烦躁易怒者，加黄芩、牡丹皮、栀子","formulaNames":["逍遥蒌贝散"]},{"t":"syn","sid":"s070702","name":"肾气亏虚证","clinic":"多见于中老年人。轻者多无全身症状。重者偏于肾阳虚，则见面色无华，腰腿酸软，倦怠乏力，舌淡苔白，脉沉弱；偏于肾阴虚，则见头目眩晕，五心烦热，眠少梦多，舌红苔少，脉弦细","treat":"补益肾气","formula":"偏于肾阳虚者，方用右归丸合小金丹。偏于肾阴虚者，方用左归丸合小金丹。心烦难寐者，加知母、黄柏、百合、夜交藤","formulaNames":["右归丸","小金丹"]},{"t":"p","x":"2.外治疗法用阳和解凝膏掺黑退消或桂麝散敷贴。3.其他疗法男性患者乳房明显肥大影响美观者，可考虑手术治疗。"},{"t":"p","x":"幼女患者慎用手术切除活检术。"}],"entries":["e0277","e0278","e0279"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持心情愉快，避免恼怒忧思。2.忌烟酒及辛辣刺激性食物。"},{"t":"p","x":"避免滥用可能含有雌激素的药物、食物。3.避免服用对肝脏有损害或影响激素代谢的药物。"},{"t":"p","x":"4.积极治疗原发病，如肾病、睾丸疾病等；有肝病者，适当进行保肝治疗。"}],"entries":["e0280"]}]},{"id":"d0708","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳核","displayName":"乳核","parentId":"","printedPage":99,"pdfPage":114,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳核是指发生在乳房部的良性肿瘤。"},{"t":"p","x":"其临床特点是好发于20～25岁青年女性，乳中结核形如丸卵，边界清楚，表面光滑，推之活动。历代文献将本病归属“乳痞”“乳中结核”等范畴。"},{"t":"p","x":"本病相当于西医学的乳腺纤维腺瘤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"情志内伤，肝气郁结，或忧思伤脾，运化失司，痰湿内生，气滞痰凝；或冲任失调，气滞血瘀痰凝，积聚于乳房胃络而成。"}],"entries":["e0281","e0282"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多发于20～25岁女性，其次是15～20岁和25～30岁女性。"},{"t":"p","x":"肿块常单个发生，或可见多个在单侧或双侧乳房内同时或先后出现。肿块形状呈圆形或椭圆形，大小不一，边界清楚，质地坚实，表面光滑，与周围组织无粘连，活动度大，触诊常有滑脱感。"},{"t":"p","x":"肿块一般不伴疼痛，少数伴轻微胀痛。一般生长缓慢，妊娠期可迅速增大，应排除恶变可能。"},{"t":"p","x":"(2)辅助检查超声检查可见肿块边界清楚和完整，内部回声分布均匀，后方回声多数增强。"},{"t":"p","x":"钼靶X线摄片可见边缘整齐的圆形或椭圆形致密肿块影，界清，四周可见透亮带。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表7-6)"},{"t":"table","img":"img/tab/t0706.jpg","cap":"表7-6乳核与乳岩、乳癖的鉴别"}],"entries":["e0283"]},{"title":"治疗","blocks":[{"t":"p","x":"对单发纤维腺瘤的治疗以手术切除为宜，对多发或复发性纤维腺瘤可用中药控制肿瘤生长、减少复发，甚至消除肿块。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070801","name":"肝气郁结证","clinic":"肿块较小，发展缓慢，不红不热，不觉疼痛，推之可移；伴胸闷、喜叹息；苔薄白，脉弦","treat":"疏肝解郁，化痰散结","formula":"逍遥散加减。肿块坚韧者，加三棱、莪术、生牡蛎、石见穿等","formulaNames":["逍遥散"]},{"t":"syn","sid":"s070802","name":"血瘀痰凝证","clinic":"肿块较大，坚硬木实，重坠不适；伴胸胁牵痛，烦闷急躁，或月经不调、痛经等症；舌质暗红，苔薄腻，脉弦滑或弦细","treat":"疏肝活血，化痰散结","formula":"逍遥散合桃红四物汤加山慈菇、海藻。月经不调者，加仙茅、淫羊藿等","formulaNames":["逍遥散","桃红四物汤"]},{"t":"p","x":"月经不调者，加仙茅、淫羊藿等。2.外治疗法阳和解凝膏掺黑退消外贴。"},{"t":"p","x":"3.其他疗法肿块较大者或短期内肿块增长较快者应行手术切除，术后均须做病理检查，必要时行术中冰冻切片检查。"}],"entries":["e0284","e0285","e0286"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.调摄情志，避免郁怒。2.定期检查，发现肿块及时诊治。"},{"t":"p","x":"3.少食厚味及炙烤之物。"}],"entries":["e0287"]}]},{"id":"d0709","kind":"main","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳岩","displayName":"乳岩","parentId":"","printedPage":100,"pdfPage":115,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳岩是指发生在乳房部的恶性肿瘤。"},{"t":"p","x":"其临床特点是乳房肿块质地坚硬，凹凸不平，边界不清，推之不移，或乳头溢血，晚期可见溃烂凸如泛莲或菜花。乳岩是女性最常见的恶性肿瘤之一。"},{"t":"p","x":"在中医文献中，乳岩又称为“石痈”“妒乳”“乳中结核”等。最早描述本病的记载见于《肘后备急方·治痈疽妒乳诸毒肿方》。"},{"t":"p","x":"《外科正宗·乳痈乳岩论》的论述较为全面，指出乳岩的病因乃“忧郁伤肝，思虑伤脾、积想在心，所愿不得志者，致经络痞涩”。乳岩包括西医学的乳腺癌、乳腺肉瘤、恶性叶状肿瘤等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.情志失调女子以肝为先天，肝主疏泄，性喜条达而恶抑郁，肝属木，克脾土。情志不畅，所愿不遂，肝失条达，气机不畅，气郁则瘀；"},{"t":"p","x":"肝郁克犯脾土，运化失职则痰浊内生，肝脾两伤，经络阻塞、痰瘀互结于乳房而发病。2.饮食失节久嗜厚味炙煿，则湿热蕴结脾胃，化生痰浊，随气流窜，结于乳中，阻塞经络，气血不行，日久成岩。"},{"t":"p","x":"3.冲任不调冲为血海、任主胞胎，冲任之脉隶属肝肾。冲任失调则气血失和，月经不行，气郁血瘀、阻塞经络，结于乳中而成乳岩。"},{"t":"p","x":"乳岩多发于绝经期前后，故与冲任失调有密切关系。此外，在经气虚弱的情况下，感受毒邪之气，阻塞经络，气滞血瘀，日久停痰结瘀，亦可导致乳岩。"},{"t":"p","x":"总之，乳岩的发病是情志失调、饮食失节、冲任不调或先天禀赋不足引起机体阴阳平衡失调、脏腑失和所致。西医学认为，未曾生育或哺乳的妇女，月经初潮早或绝经晚的妇女，以及有乳腺癌家族史的妇女，乳腺癌的发病率相对较高。"},{"t":"p","x":"男性乳腺癌较少发生。"}],"entries":["e0288","e0289"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病年龄一般在40～60岁，绝经期妇女发病率相对较高。"},{"t":"p","x":"乳腺癌可分为一般类型乳腺癌及特殊类型乳腺癌。"},{"t":"p","x":"1)一般类型乳腺癌常为乳房内触及无痛性肿块，边界不清，质地坚硬，表面不光滑，不易推动，常与皮肤粘连而呈现酒窝征，个别可伴乳头血性或水样溢液。"},{"t":"p","x":"后期随着癌肿逐渐增大，产生不同程度疼痛，皮肤可呈橘皮样水肿、变色；病变周围可出现散在的小肿块，状如堆栗；"},{"t":"p","x":"乳头内缩或抬高，偶可见到皮肤溃疡。晚期出现乳房肿块溃烂，疮口边缘不整齐，中央凹陷似岩穴，有时外翻似菜花，时渗紫红色血水，恶臭难闻。"},{"t":"p","x":"癌肿转移至腋下及锁骨上时，可触及散在、质硬无痛的臀核，以后渐大，互相粘连，融合成团。逐渐出现形体消瘦、面色苍白、憔悴等恶病质貌。"},{"t":"p","x":"2)特殊类型乳腺癌"},{"t":"p","x":"炎性癌：临床少见，多发于青年妇女，半数发生在妊娠或哺乳期。起病急骤，乳房迅速增大、皮肤肿胀，色红或紫红，发热，但无明显的肿块。"},{"t":"p","x":"转移甚广，对侧乳房往往不久即被侵及，并很早出现腋窝部、锁骨上淋巴结肿大。本病恶性程度极高，病程较短，预后不佳。"},{"t":"p","x":"湿疹样癌：临床较少见，其发病占女性乳腺癌的0.7%～3%。早期临床表现似慢性湿疮，乳头和乳晕的皮肤发红，轻度糜烂，有浆液渗出，有时覆盖着黄褐色的鳞屑状痂皮。"},{"t":"p","x":"病变的皮肤甚硬、与周围分界清楚。多数患者感到奇痒，或有轻微灼痛。"},{"t":"p","x":"中期为数年后病变蔓延到乳晕以外的皮肤，色紫而硬，乳头凹陷。后期表现为溃后易于出血，乳头逐渐蚀落，疮口凹陷，边缘坚硬，乳房内也可出现坚硬的肿块。"},{"t":"p","x":"(2)辅助检查超声检查、钼靶X线摄片和磁共振等影像学检查是诊断乳腺癌的重要参考。"},{"t":"p","x":"典型的乳腺癌影像在超声检查中可见实质性占位病变，形状不规则，边缘不齐，光点不均匀、血流丰富；钼靶X线摄片可见病变部位致密的肿块影，形态不规则，边缘呈现毛刺状或结节状，密度不均匀、或有不规则簇状钙化影；"},{"t":"p","x":"磁共振检查除观察肿块形态外，造影剂的使用更增加了影像诊断的准确性。病理检查是乳腺癌最终确诊的依据。"},{"t":"p","x":"2.鉴别诊断乳岩与乳癖、乳核的鉴别见表7-6。"}],"entries":["e0290"]},{"title":"治疗","blocks":[{"t":"p","x":"早期诊断是乳岩治疗的关键，原则上以手术治疗为主。中医药治疗是乳腺癌综合治疗的重要部分，对晚期患者，特别是手术后患者有良好的调治作用，对放化疗有减毒增效作用，可提高患者生存质量，或延长生存期。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s070901","name":"肝郁痰凝证","clinic":"乳房部肿块皮色不变、质硬而边界不清；情志抑郁，或性情急躁，胸闷胁胀，或伴经前乳房作胀或少腹作胀；苔薄，脉弦","treat":"疏肝解郁，化痰散结","formula":"神效瓜蒌散合开郁散加减。疼痛明显者，加乳香、没药","formulaNames":["神效瓜蒌散","开郁散"]},{"t":"p","x":"情志抑郁，或性情急躁，胸闷胁胀，或伴经前乳房作胀或少腹作胀；苔薄，脉弦。治法：疏肝解郁，化痰散结。"},{"t":"syn","sid":"s070902","name":"冲任失调证","clinic":"乳房结块坚硬；经期紊乱，素有经前期乳房胀痛，或婚后从未生育，或有多次流产史；舌淡，苔薄，脉弦细","treat":"调摄冲任，理气散结","formula":"二仙汤合开郁散加减。月经紊乱者，加当归、丹参、香附、郁金等；肿块坚硬者，加莪术、石见穿、蜂房、半枝莲等","formulaNames":["二仙汤","开郁散"]},{"t":"syn","sid":"s070903","name":"正虚毒盛证","clinic":"乳房肿块扩大，溃后愈坚，渗流血水，不痛或剧痛；精神萎靡，面色晦暗或苍白，饮食少进，心悸失眠；舌紫或有瘀斑，苔黄，脉弱无力","treat":"调补气血，清热解毒","formula":"八珍汤加减。酌加半枝莲、白花蛇舌草、石见穿等清热解毒之品。肿块溃破出血者，加茜草、仙鹤草等；心悸失眠者，加五味子、川芎、麦冬、灵芝等","formulaNames":["八珍汤"]},{"t":"syn","sid":"s070904","name":"气血两亏证","clinic":"多见于癌肿晚期或手术、放化疗后，患者形体消瘦，面色萎黄或㿠白，头晕目眩，神倦乏力，少气懒言；术后切口皮瓣坏死糜烂，时流渗液，皮肤灰白，腐肉色暗不鲜；舌质淡，苔薄白，脉沉细","treat":"补益气血，宁心安神","formula":"人参养荣汤加味。酌加半枝莲、龙葵、白花蛇舌草等清热解毒之品","formulaNames":["人参养荣汤"]},{"t":"syn","sid":"s070905","name":"脾虚胃弱证","clinic":"手术或放化疗后食欲不振，神疲肢软，恶心欲呕，肢肿倦怠；舌淡，苔薄，脉细弱","treat":"健脾和胃","formula":"参苓白术散或理中汤加减。恶心呕吐者，加半夏、竹茹；胃脘胀满者，加八月札、莱菔子；便溏者，加薏苡仁、怀山药等。除以上几种常见类型外，还可见到放化疗后胃阴虚，出现口腔糜烂、牙龈出血等症者，治宜清养胃阴，方用益胃汤加减","formulaNames":["参苓白术散","理中汤"]},{"t":"p","x":"除以上几种常见类型外，还可见到放化疗后胃阴虚，出现口腔糜烂、牙龈出血等症者，治宜清养胃阴，方用益胃汤加减。2.外治疗法适用于有手术禁忌证，或已远处广泛转移，不适宜手术者。"},{"t":"p","x":"初起用阿魏消痞膏外贴，溃后用海浮散或红油膏外敷，坏死组织脱落后改用生肌玉红膏、生肌散外敷。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术治疗、化疗、放疗手术仍是乳腺癌治疗的首选方法，近年来手术范围渐趋缩小，辅助采用化疗、放疗可进一步提高疗效。"},{"t":"p","x":"正确掌握适应证、合理治疗依然十分重要。"},{"t":"p","x":"(2)内分泌治疗和靶向治疗分别适用于雌激素受体(ER)、孕激素受体(PR)阳性患者和人表皮生长因子受体-2(HER-2)基因过表达患者。"},{"t":"p","x":"前者主要有雌激素拮抗剂、芳香化酶抑制剂、GnRH类似物等，后者目前主要采用靶向抗HER-2基因治疗。"}]}],"entries":["e0291","e0292","e0293","e0294","e0295","e0296","e0297"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.普及防癌知识宣传，推广和普及乳房自我检查。2.重视乳腺癌高危人群的定期检查。"},{"t":"p","x":"3.治疗乳腺良性疾病。"}],"entries":["e0298"]}]},{"id":"d0710","kind":"attach","chapterId":"ch07","chapterNo":"第七章","chapterName":"乳房疾病","name":"乳衄","displayName":"乳岩·乳衄","parentId":"d0709","printedPage":103,"pdfPage":118,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"乳衄是指乳窍不时溢出少量血液。"},{"t":"p","x":"其临床特点是乳头单个或多个乳孔溢出血性液体，或有乳晕下单发肿块。引起乳衄的疾病有多种，如乳腺导管内乳头状瘤、乳腺癌、乳腺增生病等。"},{"t":"p","x":"乳腺导管内乳头状瘤包括大导管内乳头状瘤和多发性导管内乳头状瘤，前者发生在大导管近乳头的壶腹部，后者发生在乳腺的中小导管内。乳头属肝，忧思郁怒，肝气不舒，郁久化火，灼伤血络，迫血妄行；"},{"t":"p","x":"或因思虑伤脾，脾不统摄，血不循经，溢于乳窍所致。本病多发生于40～50岁经产妇女。"},{"t":"p","x":"导管内乳头状瘤所引起的乳衄，乳头溢出血性液体常为间歇性、自发性，或仅在内衣上见有棕黄色血迹。有的乳晕部能摸到豆大圆形肿物，质地较软，不与皮肤粘连，推之可活动。"},{"t":"p","x":"压迫肿物时，常可见从乳头内溢出血性或黄色液体。多无明显痛感，仅少数当肿块较大而阻塞输乳管或因积血不易排出时，可出现疼痛。"},{"t":"p","x":"乳腺癌所引起的乳衄，其溢液多为单侧单孔，常伴明显肿块，且多位于乳晕区以外，肿块质地坚硬，活动度差，表面不光滑。溢液涂片细胞学检查可找到癌细胞。"},{"t":"p","x":"部分乳癖患者可伴有乳头溢液，常为双侧多孔溢液，以浆液性为多，血性较少，且有乳房肿块，并有周期性乳房疼痛等症。乳腺导管内窥镜、乳腺MRI及乳头分泌物细胞学检查有助于诊断。"},{"t":"p","x":"肝火偏旺证者，治宜疏肝解郁、凉血止血，方用丹栀逍遥散加减；脾虚失统证者，治宜健脾养血止血，方用归脾汤加减。"},{"t":"p","x":"本病以手术治疗为主，药物治疗为辅。对单发的导管内乳头状瘤可做病变导管切除术，对切除组织常规做病理检查。"},{"t":"p","x":"若有恶变者，则按乳腺癌行手术治疗。"}],"entries":["e0299"]}]},{"id":"d0800","kind":"chapter","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"本章概述","displayName":"瘿·本章概述","parentId":"","printedPage":105,"pdfPage":120,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"瘿是颈前结喉两侧肿块性疾病的总称，相当于西医学的甲状腺疾病。刘熙《释名》曰：“瘿，婴也，在颈婴喉也。"},{"t":"p","x":"其临床特点是颈前结喉处或为漫肿，或为结块，可随吞咽动作上下移动。在古代文献中有五瘿之分，如宋代陈无择《三因极一病证方论·瘿瘤证治》中记载：“坚硬不可移者，曰名石瘿；"},{"t":"p","x":"皮色不变，即名肉瘿；筋脉露结者，名筋瘿；"},{"t":"p","x":"赤脉交络者，名血瘿；随忧愁消长者，名气瘿。"},{"t":"p","x":"临床上气瘿、肉瘿、石瘿仍较常见，而血瘿与筋瘿多属颈部血管肿瘤，或因肿大的甲状腺压迫引起颈部浅表静脉扩张的并发症。古代文献无瘿痈病名，因其具有局部肿胀、疼痛等痈的特点，与亚急性甲状腺炎相对应而定名。"},{"t":"p","x":"慢性淋巴细胞性甲状腺炎(又称桥本甲状腺炎)为西医学病名，尚未归纳在上述瘿病分类之中。"}],"entries":["e0300"]},{"title":"脏腑经络归属","blocks":[{"t":"p","x":"颈部经络所属与任、督、肝、肾经络有一定的联系。瘿病发于颈前结喉两侧，颈前属任脉所主，任脉起于少腹中极穴之下，沿腹和胸部正中线直上，抵达咽喉，再上至颊部，经过面部进入两目；"},{"t":"p","x":"颈部也有督脉分支所过，盖督脉其循少腹直上者，贯脐中央，上贯心，入喉；任督两脉皆系于肝肾，肝肾之经脉皆循喉咙。"},{"t":"p","x":"临床上瘿病多因情志不畅，肝气郁结而发病；而肾阴不足，肝失所养，冲任不调，又可出现月经紊乱、心悸多汗、两手震颤等全身症状。"},{"t":"p","x":"在瘿的辨证过程中，结合病位的经络所属辨证施治，对临床有一定的指导意义。"}],"entries":["e0301"]},{"title":"病因病机","blocks":[{"t":"p","x":"瘿病的病因与情志失调、水土因素、禀赋遗传、外感六淫等有关。在致病因素的作用下，脏腑经络功能失调，气滞、血瘀、痰浊凝结于颈部，是其主要病机。"},{"t":"p","x":"如《外科正宗·瘿瘤论》所说：“夫人生瘿瘤之症，非阴阳正气结肿，乃五脏瘀血、浊气、痰滞所成。”1.气滞情志不畅，肝失疏泄，气机升降失常，则形成气滞。"},{"t":"p","x":"气郁日久，积聚成形，或与外来或内生致病因素合邪为病，即可导致瘿病的发生或加重，如气瘿随气消长。2.血瘀气为血之帅，气行则血行。"},{"t":"p","x":"气滞日久必致血瘀，形成癥结肿块、质地较硬、如石瘿。3.痰凝肝气郁滞，横逆犯脾，脾失健运，痰湿内生，或因外邪所侵、体质虚弱等，多能使气机阻滞，津液积聚为痰，痰凝成核，颈前结块较软或韧，如肉瘿。"},{"t":"p","x":"4.外感风温风火客于肺胃，积热上壅，热毒灼津为痰，痰火凝聚，搏结而成，如瘿痈。5.冲任失调禀赋不足，劳损伤正，冲任失调，肝木失养，肾阴亏虚，可引起瘿病，伴心悸、烦热、多汗及月经不调等相应症状。"},{"t":"p","x":"阴损及阳，可致脾肾阳虚。"}],"entries":["e0302"]},{"title":"甲状腺检查方法","blocks":[{"t":"p","x":"1.望诊检查者位于患者对面，观察两侧甲状腺大小是否对称，有无肿块隆起等。2.触诊检查者位于患者对面，也可站在患者后面，双手手指放于甲状腺部位触摸甲状腺大小及有无结节。"},{"t":"p","x":"若有结节，要注意其位置、大小、数目、硬度、有否压痛及边界是否清晰等，并检查肿块是否随吞咽动作上下移动。触诊时还需注意气管有无移位，有无血管震颤，颈部淋巴结是否肿大等。"}],"entries":["e0303"]},{"title":"常用辅助检查","blocks":[{"t":"p","x":"1.超声检查甲状腺超声检查可了解甲状腺有无肿大及肿大程度，可了解甲状腺血供情况，或有无甲状腺结节、并发现结节的大小、数量、边缘是否清楚等。"},{"t":"p","x":"2.血液检测主要有血清甲状腺激素(FT、FT、T、T)，血清促甲状腺激素(TSH)，可了解甲状腺功能；"},{"t":"p","x":"甲状腺自身抗体TPOAb(甲状腺过氧化物酶抗体)、TgAb(甲状腺球蛋白抗体)和TRAb(促甲状腺激素受体抗体)，可辅助诊断甲状腺疾病、评估病情严重程度、指导治疗及监测预后。"},{"t":"p","x":"3.甲状腺核素检查(甲状腺摄I率和甲状腺扫描)通过放射性同位素示踪对甲状腺进行功能和形态的评估。"},{"t":"p","x":"4.病理检查甲状腺结节不能除外恶变时，应做甲状腺细针穿刺细胞学检查(FNAC)，以及对切除组织的快速冰冻病理检查、术后常规病理检查等。"}],"entries":["e0304"]},{"title":"治疗","blocks":[{"t":"p","x":"1.内治瘿痈、桥本甲状腺炎适宜口服药物治疗。气瘿、肉瘿及石瘿晚期不适合手术者，亦可口服药物治疗。"},{"t":"p","x":"富碘中药的使用，古今认识有所不同。由于缺碘曾是瘿病的主要病因，历代医家多采用含碘丰富的植物类药，如海藻、昆布、海带、黄药子等。"},{"t":"p","x":"黄药子有一定毒性，临床不可过量使用。但随着碘缺乏致甲状腺疾病减少，现代主张对伴有甲亢的瘿病宜慎用富碘中药，对不伴甲亢的瘿病仍可选用。"},{"t":"p","x":"现将常用治法分述如下："},{"t":"p","x":"(1)理气解郁适用于结块漫肿软绵或坚硬如石，发病与精神因素有关，或见急躁易怒，胸闷，善太息，苔薄白，脉弦滑。"},{"t":"p","x":"用逍遥散加减。"},{"t":"p","x":"(2)活血祛瘀适用于肿块日久，或质地坚硬，表面凸凹不平，推之不移，痛有定处，肌肤甲错，舌紫暗，有瘀点瘀斑，脉涩或沉细。"},{"t":"p","x":"用桃红四物汤加减。"},{"t":"p","x":"(3)化痰软坚适用于肿块按之坚实或有性感，咽喉如有梅核堵塞，胸闷不舒，苔薄腻，脉滑。"},{"t":"p","x":"用海藻玉壶汤加减。"},{"t":"p","x":"(4)清热化痰适用于颈部肿胀疼痛，伴有头疼、发热、舌红、苔黄、脉弦数。"},{"t":"p","x":"多属痰火郁结，用柴胡清肝汤加减。"},{"t":"p","x":"(5)调摄冲任适用于气瘿漫肿，面色无华，腰酸肢冷，月经量少色淡，甚或闭经，舌淡，苔白，脉沉细。"},{"t":"p","x":"多属冲任不调、肾阳虚衰，用右归饮加减。"},{"t":"h","lv":2,"x":"2.外治"},{"t":"p","x":"(1)敷贴应区分阳证和阴证，阳证可外贴金黄散、四黄散，阴证可外贴阳和解凝膏等。"},{"t":"p","x":"(2)手术石瘿及其他瘿病肿物较大，出现压迫症状，或伴有甲亢等，可手术治疗。"},{"t":"p","x":"3.其他疗法出现甲亢时用抗甲状腺药物，出现甲减时用甲状腺激素替代药物。放射性I可破坏甲状腺滤泡细胞，用于甲亢及恶性肿瘤转移的治疗。"}],"entries":["e0305"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持心情舒畅，勿郁怒动气，勿长期熬夜。2.避免放射线照射颈前甲状腺区，尤其在青少年时期。"},{"t":"p","x":"3.伴有甲亢时，应适当减少富碘中药和含碘食物的摄入。"}],"entries":["e0306"]}]},{"id":"d0801","kind":"main","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"气瘿","displayName":"气瘿","parentId":"","printedPage":107,"pdfPage":122,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"气瘿是指颈前结喉部漫肿，伴有结块，按之较柔软的瘿病。"},{"t":"p","x":"因其肿块可随喜怒而消长，故称为气瘿、俗称“大脖子病”。其临床特点是女性多见；"},{"t":"p","x":"颈前结喉两侧弥漫性肿大，伴有结节，质地不硬，皮色如常，生长缓慢。本病相当于西医学的单纯性甲状腺肿。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"气瘿的形成，多由于所居之地的水源及食物中含碘不足，加之情志不畅、冲任失调等导致。如《诸病源候论·瘿候》所言：“瘿者，由忧恚气结所生，亦曰饮沙水，沙随气入于脉，搏颈下而成之。”"},{"t":"p","x":"1.肝郁痰凝情志不畅，忧思恼怒，致肝气郁结，脾失健运，痰湿内生，导致气滞痰凝，结于颈部。2.肝郁肾虚青春期、妊娠期妇女等，气机不畅，肾气亏损，冲任失养，亦可引发本病。"},{"t":"p","x":"3.饮食因素居住在山区、高原等缺碘地区，饮食中缺碘是引起地方性甲状腺肿的主要原因，食盐加碘后缺碘致病减少。西医学认为，本病的病因与甲状腺激素原料(碘)的缺乏、甲状腺激素需要量的激增及甲状腺素合成和分泌障碍等有关。"},{"t":"p","x":"同时，西医学也指出，长期过量的碘摄入也可引起甲状腺疾病，如结节性甲状腺肿等。"}],"entries":["e0307","e0308"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现女性多见。"},{"t":"p","x":"颈前结喉处漫肿，一侧或两侧可及多个结节，光滑，质软不痛，随吞咽动作而上下移动。如漫肿结节较大时，可压迫气管、食管和喉返神经等而引起各种症状，如呼吸困难、吞咽不利、声音嘶哑等。"},{"t":"p","x":"(2)辅助检查B超检查甲状腺增大，甲状腺内多发囊性、实性或囊实性结节。"},{"t":"p","x":"颈部X线检查可以帮助判断有无气管受压、偏移。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表8-1)"},{"t":"table","img":"img/tab/t0801.jpg","cap":"表8-1气瘿与肉瘿、瘿痈、石瘿的鉴别"}],"entries":["e0309"]},{"title":"治疗","blocks":[{"t":"p","x":"一般采用内治法，以疏肝解郁、化痰软坚为主。如果结块较大，如超过4cm以上，出现明显压迫症状时可以手术。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s080101","name":"肝郁痰凝证","clinic":"颈前结喉处漫肿、结块，边缘不清，随喜怒消长，皮色如常，质软无压痛；伴急躁易怒，善太息；舌质淡红，苔薄，脉沉弦","treat":"疏肝解郁，化痰软坚","formula":"四海舒郁丸加减。气短、便溏者、加黄芪、党参、白术、茯苓等益气健脾；结节较大偏硬时，加赤芍、三棱、莪术、山慈菇等活血散结。含碘丰富的中药如海带、海藻、昆布等临床适当运用，不可过量","formulaNames":["四海舒郁丸"]},{"t":"syn","sid":"s080102","name":"肝郁肾虚证","clinic":"颈前结喉处漫肿、结块；伴有腰酸头晕，神疲乏力，月经不调；舌质淡，脉沉细","treat":"疏肝补肾，调摄冲任","formula":"四海舒郁丸合右归饮加减","formulaNames":["四海舒郁丸","右归饮"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)中成药可口服夏枯草制剂及小金丹制剂。"},{"t":"p","x":"(2)手术巨大气瘿，压迫症状明显者，应手术治疗。"}]}],"entries":["e0310","e0311","e0312","e0313"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.在缺碘地区，坚持食用加碘盐；多进食含碘丰富的食物，如海带、紫菜、虾皮等。2.怀孕期因碘需求量增加也应多补充含碘食物。"},{"t":"p","x":"3.保持心情舒畅，勿郁怒动气。"}],"entries":["e0314"]}]},{"id":"d0802","kind":"main","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"肉瘿","displayName":"肉瘿","parentId":"","printedPage":108,"pdfPage":123,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肉瘿是指瘿病中结喉肿块较局限而柔韧者。"},{"t":"p","x":"其临床特点是颈前喉结一侧或两侧结块，柔韧而圆，如肉之团，随吞咽动作而上下移动，发展缓慢。好发于中青年女性。"},{"t":"p","x":"本病相当于西医学的甲状腺腺瘤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于忧思郁怒，气滞、痰浊、瘀血凝结而成。情志抑郁，肝失条达，气滞血瘀；或忧思郁怒，肝旺侮土，脾失运化，痰湿内蕴。"},{"t":"p","x":"气滞、湿痰、瘀血随经络而行，留注于结喉，聚而成形，乃成肉瘿。西医学对本病的病因认识尚不清楚，可能与碘代谢变化、女性激素、地理环境及家族遗传有关。"}],"entries":["e0315","e0316"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于20～40岁女性。"},{"t":"p","x":"在结喉一侧或双侧有单个肿块，呈半圆形，表面光滑，可随吞咽动作上下移动，按之不痛，生长缓慢，一般无明显全身症状。若肿物突然增大，并出现局部疼痛，常因甲状腺腺瘤囊内出血所致。"},{"t":"p","x":"部分患者可伴有急躁、心悸、脉数、消瘦、乏力等甲状腺功能亢进(甲亢)征象。少数患者可发生癌变。"},{"t":"p","x":"(2)辅助检查B超检查显示甲状腺内有实质性肿块，或有液性暗区，边界清楚，有包膜，多为单个。"},{"t":"p","x":"若为高功能自主性腺瘤，甲状腺同位素扫描为热结节，伴有FT、FT升高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表8-2)"},{"t":"table","img":"img/tab/t0802.jpg","cap":"表8-2肉瘿与甲状舌骨囊肿的鉴别"}],"entries":["e0317"]},{"title":"治疗","blocks":[{"t":"p","x":"多采用内治法，以理气解郁、化痰软坚为主。必要时可手术。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s080201","name":"气滞痰凝证","clinic":"颈前结喉一侧或两侧肿块，呈圆形或卵圆形，质地柔韧；一般无明显全身症状，如肿块过大可有呼吸不畅或吞咽不利；苔薄腻、脉弦滑","treat":"理气解郁，化痰软坚","formula":"逍遥散合海藻玉壶汤加减","formulaNames":["逍遥散","海藻玉壶汤"]},{"t":"syn","sid":"s080202","name":"气阴两虚证","clinic":"颈部结喉处肿块，质地柔韧；伴有急躁易怒、汗出心悸、失眠多梦、消谷善饥、形体消瘦月经不调、手部震颤等；舌红，苔薄，脉弦","treat":"益气养阴，软坚散结","formula":"生脉散合消凛丸加减。失眠者，加茯神、珍珠母等镇心安神；急躁、手抖者，加生石决明钩藤等平肝息风","formulaNames":["生脉散","消凛丸"]},{"t":"p","x":"失眠者，加茯神、珍珠母等镇心安神；急躁、手抖者，加生石决明钩藤等平肝息风。2.外治疗法阳和解凝膏掺黑退消或桂麝散外敷。"},{"t":"p","x":"3.其他疗法结节较大，内服药治疗3个月以上无改善者，或伴有甲亢，或近期肿块增大较快，有恶变倾向者，应考虑手术治疗。囊内出血者可在B超引导下行穿刺抽吸治疗。"}],"entries":["e0318","e0319","e0320"]},{"title":"预防与调护","blocks":[{"t":"p","x":"注意观察肿物大小和质地变化，如短期内甲状腺结节明显增大，除外囊内出血后，应警惕癌变。"}],"entries":["e0321"]}]},{"id":"d0803","kind":"main","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"瘿痈","displayName":"瘿痈","parentId":"","printedPage":109,"pdfPage":124,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"瘿痈是指结喉处突然出现肿块，伴有疼痛的疾病。"},{"t":"p","x":"其临床特点为结喉处结块、肿胀、疼痛，伴有发热，起病急骤。本病相当于西医学的亚急性甲状腺炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"外感风热火毒和风温疫毒之邪，侵入肺卫，加之内伤七情，肝郁化火，或素有内热，灼津成痰，导致风热夹痰上攻，壅滞于颈前。后期热病伤阴耗气，日久可致气阴两虚或阴损及阳，阳气亏虚。"}],"entries":["e0322","e0323"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于30～50岁成年人，发病前常有感冒、咽痛等病史。"},{"t":"p","x":"颈结喉处突然出现肿胀疼痛，疼痛牵引至同侧头部、耳后枕部，活动或吞咽时加重，皮色不变，按之质地坚硬压痛明显。肿块可由颈部一侧发展至另一侧。"},{"t":"p","x":"伴有口干咽痛，发热以午后为甚。发展进程中可见心悸、心烦、失眠、双手颤抖，急躁易怒；女子可见月经不调、经量稀少。"},{"t":"p","x":"病程日久也可见肢冷肿胀、神疲乏力、气短懒言等症。"},{"t":"p","x":"(2)辅助检查初期血清T、T值升高，甲状腺吸碘率降低，两者呈分离现象。"},{"t":"p","x":"血沉增快。白细胞总数及中性粒细胞比例正常或增高。"},{"t":"p","x":"甲状腺超声有助于诊断。后期可以出现短暂性甲状腺功能减退(甲减)。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表8-3)"},{"t":"table","img":"img/tab/t0803.jpg","cap":"表8-3瘿痈与颈痈、锁喉痈的鉴别"}],"entries":["e0324"]},{"title":"治疗","blocks":[{"t":"p","x":"本病初期甲亢阶段，治疗以疏风清热、化痰散结为主；热退痛减后，治以疏肝清热、养阴散结为主；"},{"t":"p","x":"后期出现甲减时，治疗以益气温阳为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s080301","name":"风热痰凝证","clinic":"结喉处结块，疼痛明显，疼痛牵扯颌下、耳后或枕部，拒按；伴恶寒发热，头身疼痛，口渴，咽干；舌红苔薄黄，脉浮数或滑数","treat":"疏风清热，化痰散结","formula":"牛蒡解肌汤加减。热甚时，加石膏、知母、黄芩等清肺胃内热；头面疼痛明显者，加白芷、羌活、川芎等祛风止痛；夏季发病，舌苔厚腻者，可加藿香、佩兰等芳香化浊之品","formulaNames":["牛蒡解肌汤"]},{"t":"syn","sid":"s080302","name":"肝郁内热证","clinic":"身热渐退，颈前肿痛；伴胸闷不舒，急躁易怒，口苦咽干，怕热多汗；舌红少苔或苔薄黄，脉弦数","treat":"疏肝清热，佐以养阴","formula":"柴胡清肝汤加减","formulaNames":["柴胡清肝汤"]},{"t":"syn","sid":"s080303","name":"气虚阳虚证","clinic":"颈前结块及疼痛消失；畏寒肢冷，腹胀纳呆，面目浮肿，乏力气短；舌淡，苔薄白，脉沉","treat":"益气温阳，健脾化痰","formula":"阳和汤加减","formulaNames":["阳和汤"]},{"t":"p","x":"2.外治疗法金黄散、四黄散等水或蜜调外敷于颈部肿大处，每日1～2次，具有清热消肿、散结止痛作用。3.其他疗法后期出现甲减时可以补充小剂量左甲状腺素(L-T₄)。"}],"entries":["e0325","e0326","e0327","e0328"]},{"title":"预防与调护","blocks":[{"t":"p","x":"减少上呼吸道感染的发生。"}],"entries":["e0329"]}]},{"id":"d0804","kind":"main","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"慢性淋巴细胞性甲状腺炎","displayName":"慢性淋巴细胞性甲状腺炎","parentId":"","printedPage":110,"pdfPage":125,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"慢性淋巴细胞性甲状腺炎又称桥本甲状腺炎，是一种自身免疫性疾病。其临床特点是起病隐匿，发展缓慢，病程较长；"},{"t":"p","x":"主要表现为甲状腺肿大，多数为弥漫性，质地韧；大多发展成甲减，也可伴有甲亢。"},{"t":"p","x":"本病尚无对应中医病名，根据其颈前肿大的特点，归属于中医学“瘿病”范畴。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生与七情失调、劳倦内伤和体质遗传等因素有关。多属本虚标实之证，痰瘀互结为标，正气亏虚为本。"},{"t":"p","x":"1.肝郁痰凝忧思恼怒，导致肝气郁结，气化不利、聚津成痰；痰凝、气滞和血瘀互结，形成瘿肿。"},{"t":"p","x":"2.脾肾阳虚素体阳虚，劳倦伤气，脾失健运，肾失运化，痰湿凝聚，结于颈前；脾虚生化无源，气虚推动无力；"},{"t":"p","x":"肾阳不足，机体失于温煦，可导致诸多虚寒征象。3.气阴两虚病久耗气伤阴，或气郁化火耗伤气阴等，都可导致气阴两虚；"},{"t":"p","x":"或阴精亏虚，阴不制阳，引起阴虚阳亢。西医学认为，本病的发生是遗传和环境因素共同作用的结果，自身免疫功能失调是其主要发病机制。"}],"entries":["e0330","e0331"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于中年女性，起病隐匿，发展缓慢。"},{"t":"p","x":"主要表现为甲状腺弥漫性肿大，或伴有结节，表面光滑，质韧。可有颈部憋闷不适。"},{"t":"p","x":"伴有甲减时，表现为乏力、怕冷、心动过缓、肿胀等；伴有甲亢时，表现为怕热、心慌、消瘦、急躁、心动过速等。"},{"t":"p","x":"(2)辅助检查抗甲状腺抗体TPOAb、TgAb明显增高是其特征。"},{"t":"p","x":"甲状腺功能多表现为甲减，亦可出现甲亢，或正常。B超示甲状腺弥漫性肿大，回声不均，可伴有结节。"},{"t":"p","x":"甲状腺穿刺细胞学检查有大量淋巴细胞浸润可确诊。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表8-4)"},{"t":"table","img":"img/tab/t0804.jpg","cap":"表8-4慢性淋巴细胞性甲状腺炎与气瘿、石瘿的鉴别"}],"entries":["e0332"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以内治为主，仅有甲状腺肿大时治疗重在消瘿散结，伴有甲状腺功能异常时以扶正补虚为主。必要时配合西药治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s080401","name":"肝气郁滞证","clinic":"颈前肿块质地中等或质硬，咽喉有梗阻感；情绪抑郁，胸闷不舒，乏力，大便溏或不爽，女子月经不调；舌质红，苔薄黄，脉弦滑","treat":"疏肝理气，软坚散结","formula":"柴胡疏肝散加减","formulaNames":["柴胡疏肝散"]},{"t":"syn","sid":"s080402","name":"血瘀痰结证","clinic":"颈前肿块质地坚韧，或有结节感，局部闷胀不适，有咽喉阻塞感及其他压迫感，轻度疼痛；纳差，便秘；舌质暗或有瘀斑，苔微黄，脉沉细或弦滑","treat":"活血祛瘀，化痰散结","formula":"桃红四物汤加减","formulaNames":["桃红四物汤"]},{"t":"syn","sid":"s080403","name":"气阴两虚证","clinic":"颈前肿块质地中等或质韧，有轻度压迫感；可见眼突，神疲乏力，心悸气短，怕热，多汗，易怒，口渴、食多、便溏、失眠多梦、形体消瘦；舌质红，苔少，脉细数无力","treat":"益气养阴，化痰散结","formula":"生脉散合消凛丸加减。偏阴虚火旺者宜养阴降火，方选知柏地黄汤加减","formulaNames":["生脉散","消凛丸"]},{"t":"syn","sid":"s080404","name":"脾肾阳虚证","clinic":"颈前肿块质韧，有咽部梗阻及压迫感；形寒肢冷，神疲懒言，乏力气短，肢体肿胀，腹胀纳差，腰膝酸软、女子月经不调；舌质胖嫩，边有齿痕，苔白，脉沉细弱","treat":"温补脾肾，散寒化瘀","formula":"金匮肾气丸合阳和汤加减","formulaNames":["金匮肾气丸","阳和汤"]},{"t":"p","x":"2.外治疗法可外贴冲和膏或阳和解凝膏。3.其他疗法根据病情需要可配合西药治疗，如甲减者服用左甲状腺素(L-T₄)，甲亢者给予抗甲状腺药物治疗。"}],"entries":["e0333","e0334","e0335","e0336","e0337"]}]},{"id":"d0805","kind":"main","chapterId":"ch08","chapterNo":"第八章","chapterName":"瘿","name":"石瘿","displayName":"石瘿","parentId":"","printedPage":112,"pdfPage":127,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"石瘿是指瘿病肿块坚硬如石者，属于恶性病变。"},{"t":"p","x":"其临床特点是结喉处结块，坚硬如石，高低不平，推之不移。如《三因极一病证方论·瘿瘤证治》所说：“坚硬不可移者，名曰石瘿。"},{"t":"p","x":"本病相当于西医学的甲状腺癌。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病是由于情志内伤，肝脾气逆，痰湿内生，气滞血瘀与痰湿凝结，上逆于颈部而成。亦有由肉瘿等日久转化而来。"},{"t":"p","x":"手术或病变转移复发等可耗伤正气，导致虚损。1.痰瘀内结情志内伤，肝郁脾虚，导致气滞、痰凝、血瘀，互结颈前而成。"},{"t":"p","x":"2.瘀热伤阴痰瘀结聚颈前，加之素体虚弱或病久耗伤正气，或手术和I治疗等耗气伤津，导致阴液亏损与痰瘀互结同时存在，虚实并见。3.气阴两虚禀赋不足，年老体弱，术后耗伤正气等，导致气阴两虚。"},{"t":"p","x":"西医学认为，本病的发生与遗传、核辐射、自身免疫功能失调、高碘饮食等因素有关。"}],"entries":["e0338","e0339"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于30～40岁女性，多为颈前结喉处单个肿块，质地坚硬如石，表面凹凸不平，推之不移。"},{"t":"p","x":"若肿块压迫，可引起呼吸或吞咽困难、声音嘶哑等症。容易出现颈淋巴结转移。"},{"t":"p","x":"少数患者原有其他瘿病。"},{"t":"p","x":"(2)辅助检查甲状腺同位素扫描显示甲状腺肿物为冷结节；"},{"t":"p","x":"超声和CT检查显示甲状腺肿物质地不均，内有沙粒样钙化，边缘不清。穿刺细胞学或活组织病理检查可确诊。"},{"t":"p","x":"2.鉴别诊断石瘿与气瘿、肉瘿、瘿痈的鉴别见表8-1。"}],"entries":["e0340"]},{"title":"治疗","blocks":[{"t":"p","x":"首选手术治疗。术后或不能手术者配合中药治疗。"},{"t":"p","x":"在辨证论治的基础上，可加用解毒散结等抗肿瘤中药辨病治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s080501","name":"痰瘀内结证","clinic":"颈部结喉处肿块坚硬如石，高低不平，推之不移；颈部憋闷或疼痛，全身症状可不明显；舌暗红，苔薄黄，脉弦","treat":"解郁化痰，活血消坚","formula":"海藻玉壶汤合桃红四物汤加减","formulaNames":["海藻玉壶汤","桃红四物汤"]},{"t":"syn","sid":"s080502","name":"瘀热伤阴证","clinic":"结喉处肿块坚硬，或伴有颈部他处发现转移性结块；口干咽燥，声音嘶哑，咳嗽少痰，形倦体瘦；舌紫暗，或见瘀斑，脉沉涩","treat":"化瘀散结，和营养阴","formula":"通窍活血汤合养阴清肺汤加减","formulaNames":["通窍活血汤","养阴清肺汤"]},{"t":"syn","sid":"s080503","name":"气阴两虚证","clinic":"颈前结节有或无；神疲气短，心慌心悸，口干咽燥；舌红，少苔，脉细弱","treat":"益气养阴，扶正固本","formula":"生脉饮加味","formulaNames":["生脉饮"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)中成药可配合小金丹及夏枯草制剂口服。"},{"t":"p","x":"(2)手术治疗一旦确诊，宜手术切除。"},{"t":"p","x":"(3)术后I治疗对分化型甲状腺癌术后，有清除残留甲状腺及残存病灶的作用。"},{"t":"p","x":"(4)TSH抑制治疗术后需终生服用左甲状腺素，以预防甲状腺功能减退及抑制甲状腺癌复发。"}]}],"entries":["e0341","e0342","e0343","e0344","e0345"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗良性甲状腺病，预防癌变。2.定期检测甲状腺功能、甲状腺B超等。"}],"entries":["e0346"]}]},{"id":"d0900","kind":"chapter","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"本章概述","displayName":"瘤、岩·本章概述","parentId":"","printedPage":114,"pdfPage":129,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"查问本章所瘤是发生于体表的良性肿瘤、凡瘀血、痰滞、浊气停留产生的结块。"},{"t":"p","x":"其临床特点是多生于体表的局限性肿块，生长缓慢、一般没有自觉症状。《灵枢》中有筋瘤、肠瘤、脊瘤、肉瘤等记载。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》将生于体表的肿瘤分为气瘤、血瘤、筋瘤、肉瘤、骨瘤、脂瘤六类。而内脏肿瘤，后世文献多归于癥瘕范畴。"},{"t":"p","x":"岩是发生于体表的恶性肿瘤的统称，为外科疾病中最凶险者。其临床特点是局部肿块坚硬，高低不平，皮色不变，推之不移，溃烂后如翻花石榴，色紫恶臭，疼痛剧烈，预后不良。"},{"t":"p","x":"古代“岩”的字义与“癌”相通。《疡科心得集》中将“舌菌”“乳岩”“失荣”“肾岩翻花”称之为外科“四大绝症”。"}],"entries":["e0347"]},{"title":"病因病机","blocks":[{"t":"p","x":"瘤、岩是全身性疾病的局部表现、病因复杂，外因可归纳为六淫之邪或环境污染，内因为正气不足、七情所伤和饮食不节等。核心病机为本虚标实，正气亏虚为本，气滞、血瘀、痰凝、湿热或阴毒结聚为标。"},{"t":"p","x":"瘤主要是邪气偏盛、岩主要是正气不足。西医学认为、肿瘤是在多种原因作用下人体细胞增生与异常分化形成的新生物，且恶性肿瘤生长能力旺盛、多数学者认为与各种致癌因素、易感性和遗传因素密切相关。"}],"entries":["e0348"]},{"title":"辨证","blocks":[{"t":"p","x":"中医外科所涉及的瘤、岩多局限在体表。在早、中期或未溃之前多以实证为主，晚期或溃后则以虚实夹杂或虚证为主。"},{"t":"p","x":"根据临床表现一般分为如下证型：1.气郁痰凝证局部肿块硬韧，可活动，患部皮色不变，无疼痛；"},{"t":"p","x":"可伴有胸闷，胁胀，纳差，精神抑郁等；舌质淡红，苔薄白腻，脉弦滑。"},{"t":"p","x":"2.寒痰凝结证局部肿块木硬，表面光滑，肿块活动度较差，患部皮肤色白，无痛，肤温不高；可伴周身倦怠，胸闷不舒，畏寒怕冷；舌质淡，苔白或白腻，脉沉滑。"},{"t":"p","x":"3.气滞血瘀证肿块坚硬，表面高低不平，推之不动；疼痛症状可有胀痛、灼痛、刺痛、割痛等不同，缓剧可有差异，但其主要痛位固定不移；"},{"t":"p","x":"舌质暗褐或有瘀斑，苔薄白，脉弦紧或涩。4.毒热蕴结证肿块增大，疼痛，皮肤色红，肤温较高，或肿块溃烂，状如翻花，时流紫褐色血水，痛如火燎，分泌物恶臭；"},{"t":"p","x":"可伴发热，心烦，口干或苦，尿黄，大便干结；舌质红，少苔或苔黄，脉滑数。"},{"t":"p","x":"5.正虚邪实证多见于岩的晚期。肿块增大、增多，邻近或远处转移，或岩肿溃烂，渗流腐臭血水，疮面灰暗，高低不平，久不收口；"},{"t":"p","x":"伴全身消瘦，神倦无力，低热，面色萎黄无华，不思饮食；舌质淡，苔薄或少苔、无苔，脉细涩无力。"}],"entries":["e0349"]},{"title":"治疗","blocks":[{"t":"p","x":"瘤、岩的治疗有手术、放疗、化疗、中医药及生物治疗等各种方法。瘤以手术切除为主；岩早期以手术治疗为主，中晚期应采取中西医结合治疗。"},{"t":"p","x":"在治疗岩病时应正确处理以下三种关系：一是扶正与祛邪相统一。"},{"t":"p","x":"应遵循扶正不留邪、祛邪不伤正的原则。岩病早期、正气未衰，重在祛邪，但不可伤正；"},{"t":"p","x":"中期耗精伤气，正虚邪实或邪正相持，治以攻补兼施；晚期正气已衰，不任攻伐，或远处转移而不宜攻伐，治以扶正调理为主，或少佐祛邪。"},{"t":"p","x":"二是局部与整体相结合。岩病早期局部症状体征为全身整体病变的局部表现。"},{"t":"p","x":"同样，全身病变也能影响局部的治疗效果。术后患者还应重视局部解剖变化对于全身功能的影响。"},{"t":"p","x":"三是标本缓急相兼顾。对于岩病，治疗其原发病，为治其本；"},{"t":"p","x":"若在病程中出现并发症，则应及时对症处理、为急则治其标；待标症缓解后，再治其原发病，是谓缓则治其本。"},{"t":"p","x":"具体的治疗方法如下：1.内治法下述为辨证分型的常用治法，临证时尚须根据个体之不同，重视扶正基础上的祛邪解毒。"},{"t":"p","x":"(1)气郁痰凝证治宜理气化痰、解毒散结，方用开郁散合通气散坚丸加减。"},{"t":"p","x":"(2)寒痰凝结证治宜温经化痰、解毒散结，方用阳和汤合万灵丹加减。"},{"t":"p","x":"(3)气滞血瘀证治宜软坚化瘀、解毒散结，方用散肿溃坚汤合活血散瘀汤加减。"},{"t":"p","x":"(4)毒热蕴结证治宜清热凉血、解毒散结，方用黄连解毒汤合当归芦荟丸加减。"},{"t":"p","x":"(5)正虚邪实证治宜益气养血、解毒散结，方用保元汤合散肿溃坚汤加减。"},{"t":"h","lv":3,"x":"2.外治法"},{"t":"p","x":"(1)可辨证选用阳和解凝膏、冲和膏、金黄膏、阳毒内消散、阴毒内消散、桂麝散、红灵丹等外敷。"},{"t":"p","x":"紫金锭、小金丸、蟾酥丸、新癀片等亦可分别研末，茶水调涂肿块部位。"},{"t":"p","x":"(2)脓腐未尽之溃疡面可选用红升丹、生肌玉红膏等；腐肉已尽可用生肌白玉膏。"},{"t":"h","lv":3,"x":"3.其他疗法"},{"t":"h","lv":3,"x":"(1)手术治疗根据病情选择手术治疗。"},{"t":"h","lv":3,"x":"(2)激光与冷冻治疗主要运用于部分良性肿瘤。"},{"t":"h","lv":3,"x":"(3)放疗和化疗适用于恶性肿瘤，酌情选用。"}],"entries":["e0350"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.避免接触污染环境和毒性物质。2.及时检查，早发现、早诊断、早治疗。"},{"t":"p","x":"3.科学饮食，加强营养，杜绝不良嗜好。保持心情舒畅。"},{"t":"p","x":"4.适度锻炼，提高抗病能力。"}],"entries":["e0351"]}]},{"id":"d0901","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"血瘤","displayName":"血瘤","parentId":"","printedPage":115,"pdfPage":130,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"血瘤是指体表血络扩张，纵横交集而形成的良性肿瘤。"},{"t":"p","x":"其临床特点是病变局部色泽鲜红或紫，可呈局限性柔软肿块状，边界清或尚清。《外科正宗·瘿瘤论》曰：“血瘤者，微紫微红，软硬间杂，皮肤隐隐，缠若红丝，擦破血流，禁之不住。"},{"t":"p","x":"本病相当于西医学的良性血管瘤或脉管畸形。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"血瘤发病多见鲜红或紫，故与火邪为患相关。1.心肾火毒禀受父母肾中之伏火，肾水不能上济心火，迫血结瘤。"},{"t":"p","x":"2.肝火燔灼郁怒伤肝，肝火内动，燔灼阴血成瘤。3.脾失统血脾虚运化失职，离经之血与痰相结，凝聚成瘤。"},{"t":"p","x":"西医学认为，血瘤通常是由血管内皮细胞异常增生或血管畸形所致。"}],"entries":["e0352","e0353"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多为先天性，常见类型包括婴幼儿血管瘤、先天性血管瘤、静脉畸形等。"},{"t":"p","x":"婴幼儿血管瘤：出生后6个月为早期增殖期，表现为明显隆起的草莓样斑块或肿瘤。6～9个月为晚期增殖期，少数可持续至24个月。"},{"t":"p","x":"90%的患儿在4岁时瘤体完全消退，消退后部分患儿残存瘢痕、萎缩、色索减退等退行性变。先天性血管瘤：出生时即有病灶且无增殖期。"},{"t":"p","x":"好发于头面部和肢体、多为单发。形态多为隆起或斑块状、边界清楚、色紫红或蓝紫、表面可见毛细血管、周围可见白色晕环及放射状浅表扩张静脉，皮温偏高、有时可触及搏动。"},{"t":"p","x":"静脉畸形：旧称海绵状血管瘤，为静脉异常发育的结构畸形、以下肢和头颈部多见，皮肤颜色可为正常或深蓝色。局部为柔软、压缩性、无搏动的包块。"},{"t":"p","x":"(2)辅助检查对于位置较深的海绵状血管瘤，可通过超声检查、X线检查等确诊。"},{"t":"p","x":"如果对周围正常组织器官有损害，或引起并发症等，可通过CT、核磁共振(MRI)等检查血管瘤的危害程度。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表9-1)"},{"t":"table","img":"img/tab/t0901.jpg","cap":"表9-1血瘤与血痣、筋瘤的鉴别"}],"entries":["e0354"]},{"title":"治疗","blocks":[{"t":"p","x":"本病采用内、外治相结合，应根据血管瘤的类型、部位、大小、深浅用药。手术、冷冻、激光治疗也是重要方法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090101","name":"心肾火毒证","clinic":"肿块色泽鲜红，边界不清，不痛不痒；伴面赤口渴，口舌生疮，尿黄便干；舌质红，苔薄黄，脉细数","treat":"清心泻火解毒","formula":"芩连二母丸合凉血地黄汤加减。口舌生疮者加淡竹叶、玄参","formulaNames":["芩连二母丸","凉血地黄汤"]},{"t":"syn","sid":"s090102","name":"肝经火旺证","clinic":"多发于头面或胸胁，肿块呈丘疹或结节状，表面色红，易出血；伴心烦易怒，咽干口苦；舌质红，苔微黄，脉弦数","treat":"清肝泻火解毒","formula":"丹栀逍遥散合清肝芦荟丸加减。结节明显者加三棱、莪术，易出血者加茜草、仙鹤草","formulaNames":["丹栀逍遥散","清肝芦荟丸"]},{"t":"syn","sid":"s090103","name":"脾失统血证","clinic":"瘤体不大，边界尚清，表面紫红，好发于下肢，质地柔软易出血，无疼痛；伴纳呆便溏；舌质淡，苔白或白腻，脉细","treat":"健脾化湿解毒","formula":"顺气归脾丸加减","formulaNames":["顺气归脾丸"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)清凉膏合藤黄膏外敷。"},{"t":"p","x":"瘤体较小者亦可用五妙水仙膏外搽。"},{"t":"p","x":"(2)若出血，可用云南白药掺敷伤口。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术疗法适用于孤立的病变、较大的血管瘤或内脏血管瘤。"},{"t":"p","x":"(2)冷冻、激光疗法适用于浅表较小病变。"},{"t":"p","x":"(3)其他局部疗法局部注射疗法、强脉冲光治疗等。"}]}],"entries":["e0355","e0356","e0357","e0358","e0359","e0360"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.妊娠期间勿过食辛辣厚味，以免引动胎火。2.防止瘤体破溃出血。"}],"entries":["e0361"]}]},{"id":"d0902","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"肉瘤","displayName":"肉瘤","parentId":"","printedPage":117,"pdfPage":132,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肉瘤是发于皮里膜外，由脂肪组织过度增生而形成的良性肿瘤。"},{"t":"p","x":"其临床特点是瘤体质地柔软似棉，外观肿形似馒，用力可以压扁，推之可以移动，与皮肤无粘连，瘤体表面皮肤如常，亦无疼痛；生长缓慢。《外科正宗·瘿瘤论》云：“肉瘤者，软若绵，硬似馒，皮色不变，不紧不宽。"},{"t":"p","x":"本病相当于西医学的脂肪瘤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"思虑过度或饮食劳倦伤脾，脾失运化，痰湿内生，脾气不行，痰气郁结，发为肉瘤；或郁怒伤肝，失于疏泄，木旺侮土，气痰阻滞，逆于肉理，乃生本病。"},{"t":"p","x":"西医学认为，脂肪瘤的形成主要与遗传因素、脂肪代谢异常、激素变化及局部组织受慢性刺激有关。"}],"entries":["e0362","e0363"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于成年女性，可发于身体各部，好发于肩、背、腹、臀及前臂皮下。"},{"t":"p","x":"大小不一，边界清楚，皮色不变，生长缓慢，触之柔软，呈扁平团块状或分叶状，推之可移动，基底较广阔，一般无疼痛。多发者常见于四肢、胸或腹部，呈多个较小的圆形或卵圆形结节，质地较一般肉瘤略硬，压之有轻度疼痛。"},{"t":"p","x":"(2)辅助检查B超可以准确判断其位置、大小。"},{"t":"p","x":"酌情可行组织病理学检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表9-2)"},{"t":"table","img":"img/tab/t0902.jpg","cap":"表9-2肉瘤与气瘤的鉴别"}],"entries":["e0364"]},{"title":"治疗","blocks":[{"t":"p","x":"瘤体局限者治疗以手术切除为主，较小者可不处理，可配合中医药治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090201","name":"气郁痰凝证","clinic":"肿块多为单个，少数为多发，大小不一，瘤体柔软如绵，推之可移动，皮色不变，生长缓慢；舌淡，苔白、脉滑","treat":"理气健脾，化痰散结","formula":"化坚二陈丸合十全流气饮加减。心烦易怒、口干口苦者，加赤芍、牡丹皮、生地黄以清泻肝火","formulaNames":["化坚二陈丸","十全流气饮"]},{"t":"p","x":"心烦易怒、口干口苦者，加赤芍、牡丹皮、生地黄以清泻肝火。2.外治疗法阳和解凝膏掺黑退消或桂麝散外敷。"},{"t":"p","x":"3.其他疗法单发且小者，可不处理。有明显增大趋势，或伴有疼痛，或瘤体较大者，宜行手术切除。"}],"entries":["e0365","e0366"]},{"title":"预防与调护","blocks":[{"t":"p","x":"注意合理饮食，勿过食辛辣炙煿、肥甘厚味之品。"}],"entries":["e0367"]}]},{"id":"d0903","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"筋瘤","displayName":"筋瘤","parentId":"","printedPage":118,"pdfPage":133,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"筋瘤是以筋脉色紫，盘曲突起，状如蚯蚓，形成团块为主要表现的浅表静脉病变。《外科正宗·瘿瘤论》云：“筋瘤者，坚而色紫，累累青筋盘曲，甚者结若蚯蚓。"},{"t":"p","x":"本病好发于下肢，相当于西医学的下肢静脉功能不全，俗称下肢静脉曲张。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于长期从事站立负重工作，劳倦伤气，或多次妊娠，气滞血瘀，血壅于下，结成筋瘤；或骤受风寒或涉水淋雨，寒湿侵袭，凝结筋脉，筋挛血瘀，成块成瘤；"},{"t":"p","x":"或因外伤筋脉，瘀血凝滞，阻滞筋脉络道而成。西医学认为，下肢静脉曲张是由于静脉瓣膜关闭功能不全、静脉壁薄弱及浅静脉内压力持续升高所引起。"}],"entries":["e0368","e0369"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现好发于长久站立工作者或怀孕的妇女，多见于下肢。"},{"t":"p","x":"早期感觉患肢坠胀不适，站立时明显，行走或平卧时消失。患肢浅静脉逐渐怒张，小腿静脉盘曲如条索状，色带青紫，甚则状如蚯蚓，瘤体质地柔软，抬高患肢或向远心方向挤压可缩小，但患肢下垂放手顷刻充盈回复。"},{"t":"p","x":"后逐渐出现足踝部甚至小腿部水肿，按之凹陷。病程久者皮肤出现色素沉着、痒疹、皮肤硬化等表现，易出现皮肤溃疡。"},{"t":"p","x":"出现条索状红肿、灼热、压痛等症多为伴发青蛇毒，经治疗后则条索状肿胀较为坚韧。瘤体如被碰破，流出大量瘀血，经压迫或缝扎后可止血。"},{"t":"p","x":"(2)辅助检查彩色多普勒超声检查、下肢CT静脉造影(computed tomography venography,CTV)、下肢磁共振静脉造影(magnetic resonance venography,MRV)及下肢静脉造影检查，评估静脉系统的结构和功能异常，如显示是否存在下肢深静脉血栓、先天性静脉畸形及骼静脉压迫等情况。"},{"t":"p","x":"2.鉴别诊断筋瘤与血瘤的鉴别，见表9-1。"}],"entries":["e0370"]},{"title":"治疗","blocks":[{"t":"p","x":"本病采用中西医结合的治疗方法，中医注重辨证论治，各种手术、微创治疗也是重要的治疗方法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090301","name":"劳倦伤气证","clinic":"久站久行或劳累时瘤体增大，下坠不适感加重；常伴气短乏力，脘腹坠胀，腰酸；舌淡，苔薄白，脉细缓无力","treat":"补中益气，活血舒筋","formula":"补中益气汤加减","formulaNames":["补中益气汤"]},{"t":"syn","sid":"s090302","name":"寒湿凝筋证","clinic":"瘤色紫暗、喜暖、下肢轻度肿胀；伴形寒肢冷，口淡不渴，小便清长；舌淡暗，苔白腻，脉弦细","treat":"暖肝散寒，活血通脉","formula":"暖肝煎合当归四逆汤加减","formulaNames":["暖肝煎","当归四逆汤"]},{"t":"syn","sid":"s090303","name":"外伤瘀滞证","clinic":"青筋盘曲、状如蚯蚓，表面色青紫，患肢肿胀疼痛；舌有瘀点，脉细涩","treat":"活血化瘀，和营消肿","formula":"活血散瘀汤加减","formulaNames":["活血散瘀汤"]},{"t":"syn","sid":"s090304","name":"火旺血燥证","clinic":"下肢青筋盘曲，瘤体灼热；伴五心烦热，口干；舌红，苔黄，脉细数","treat":"清肝泻火，养血舒筋","formula":"清肝芦荟丸加减。出现局部红肿灼热硬结者，加蒲公英、黄柏、金银花等清热解毒；肢体肿胀者，可加泽兰、防己等利湿消肿","formulaNames":["清肝芦荟丸"]},{"t":"p","x":"2.外治疗法排除下肢动脉疾病后，建议患肢外用医用弹力袜或用弹力绷带。并发青蛇毒、湿疮、腑疮者，可参考有关章节治疗。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术疗法凡是诊断明确的筋瘤，无手术禁忌证者，都可手术治疗。"},{"t":"p","x":"一般行大隐或小隐静脉高位结扎、主干静脉剥脱及曲张静脉切除术，有条件者可选用腔内射频消融术、激光电凝术等微创治疗方法。"},{"t":"p","x":"(2)硬化剂注射疗法适用于程度较轻的单纯性下肢静脉曲张，亦可作为手术的辅助疗法，处理残留或复发的曲张静脉。"}]}],"entries":["e0371","e0372","e0373","e0374","e0375","e0376"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.长期站立工作或分娩后，适当加强下肢锻炼，配合按摩等以促进气血流通，改善症状。2.患筋瘤者穿医用弹力袜或用弹力绷带包扎，防止外伤；"},{"t":"p","x":"并发湿疮者应积极治疗，避免搔抓感染。"}],"entries":["e0377"]}]},{"id":"d0904","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"脂瘤","displayName":"脂瘤","parentId":"","printedPage":119,"pdfPage":134,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"脂瘤是皮脂潴留郁积而形成的囊肿，又称粉瘤。其临床特点是皮下圆形结节，边界清楚，中央见粗大毛孔，可有黑点，内有粉渣样物。"},{"t":"p","x":"《外科启玄》云：“凡粉瘤大而必软，久久渐大，似乎有脓非脓，乃是粉浆于内。”《外科证治全书》云：“然每有愈而复发者，乃内有脓囊，化净膏贴，生肌自愈。"},{"t":"p","x":"本病相当于西医学的皮脂腺囊肿。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病因痰湿凝滞于皮肤之间所致。腠理津沫滞聚而排泄不畅，渐以成瘤；"},{"t":"p","x":"或饮食不节，损伤脾胃，运化失司，痰湿凝滞，郁结不散，发为本病。若蕴久化热，或搔抓染毒，则红肿热痛，甚则酿脓溃破。"},{"t":"p","x":"西医学认为，本病是由于皮脂腺腺管阻塞，致皮脂腺分泌物淤积，而形成的囊性肿物。"}],"entries":["e0378","e0379"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"临床表现多发于头面、背、臀等皮脂腺丰富的部位，可发生于任何年龄，青春发育期多见。"},{"t":"p","x":"皮肤局部见圆形或椭圆形隆起性结节，边界清楚，与皮肤粘连，基底部推之可动，表面可见粗大毛孔并有黑色小点，囊内为皮脂与表皮角化物堆积的粉渣样物，用力挤之可见溢出，且有臭味。"},{"t":"p","x":"脂瘤染毒后可见局部红肿，逐渐化脓、破溃，脓液夹有粉渣样物，可反复发作。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表9-3)"},{"t":"table","img":"img/tab/t0903.jpg","cap":"表9-3脂瘤与肉瘤、痈的鉴别"}],"entries":["e0380"]},{"title":"治疗","blocks":[{"t":"p","x":"手术将脂瘤完整切除，是最根本的治疗方法。脂瘤染毒时可予中药内服外治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090401","name":"痰湿化热证","clinic":"皮肤素有结节，突然红肿、灼热、疼痛，甚至跳痛，化脓破溃，脓出夹有豆渣样分泌物；可伴发热；舌红，苔黄，脉数","treat":"清热化湿，和营解毒","formula":"五味消毒饮合二陈汤加减","formulaNames":["五味消毒饮","二陈汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)局部红肿者，用金黄膏或玉露膏外敷。"},{"t":"p","x":"(2)已成脓者，宜“十”字形切开引流，以七三丹棉球填塞腔内，待囊壁被腐蚀脱落后，再掺生肌散生肌收口。"},{"t":"p","x":"3.其他疗法手术切除。脂瘤染毒者可等红肿消退后再行手术切除。"}]}],"entries":["e0381","e0382","e0383"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.平时保持皮肤清洁，避免搔抓、挤压已存在的脂瘤。2.注意饮食清淡，多食新鲜蔬菜水果，少食辛辣炙煿、肥甘厚味之品。"}],"entries":["e0384"]}]},{"id":"d0905","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"失荣","displayName":"失荣","parentId":"","printedPage":120,"pdfPage":135,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"失荣是发于颈部及耳之前后的岩肿，因其晚期气血亏虚而瘀滞，出现面容憔悴、形体消瘦，状如树之枝叶枯萎、失去荣华而得名。"},{"t":"p","x":"多见于40岁以上的男性，属古代外科“四大绝症”之一。本病相当于西医学的颈部淋巴结转移癌和原发性恶性肿瘤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"因足少阳胆经循行耳之前后，肝与胆相表里，故失荣的发生与肝胆密切相关。如七情内伤，肝失条达，气机不舒，气滞血瘀；"},{"t":"p","x":"木旺克土，脾失健运，水湿运化失常，聚湿为痰。痰瘀脏毒凝结于少阳。阳明之络，日久耗气伤血，遂发本病。"}],"entries":["e0385","e0386"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"原发性颈部恶性肿瘤：肿块生长快，质地坚硬，早期为圆形或椭圆形，可活动；后期体职增大，数量增多、融合成团块状或连结成串，表面不平，活动度差。"},{"t":"p","x":"常见的原发性恶性肿瘤有恶性腮腺混合瘤、甲状腺癌、恶性淋巴瘤。转移性颈部恶性肿瘤：大多可找到原发病灶，颈部肿块初为一个或数个肿大的淋巴结，增大较原发性颈部肿瘤慢，且多数先有原发肿瘤的相应临床表现。"},{"t":"p","x":"临床上以鼻咽、口腔部及消化、呼吸系统癌肿转移至颈部者为多见。"},{"t":"p","x":"(2)辅助检查进行全面细致的体格检查以寻找原发病灶，或肿块局部做组织病理学检查以确诊。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表9-4)"},{"t":"table","img":"img/tab/t0904.jpg","cap":"表9-4失荣与瘰疬、肉瘿的鉴别"}],"entries":["e0387"]},{"title":"治疗","blocks":[{"t":"p","x":"本病应尽早选择手术治疗或放疗，并配合中医辨证论治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090501","name":"气郁痰结证","clinic":"颈部或耳前后出现坚硬肿块，聚结成团，与周围组织粘连而固定，轻度刺痛或胀痛，颈项牵扯感，活动转侧不利；可伴心烦，胸闷，胁痛；舌质淡红，苔腻，脉弦滑","treat":"解郁散结，化痰解毒","formula":"化坚二陈丸合开郁散加减","formulaNames":["化坚二陈丸","开郁散"]},{"t":"syn","sid":"s090502","name":"阴毒结聚证","clinic":"颈部肿块坚硬，不痛不胀，推之不动，患部初起皮色如常，后可呈橘皮样变；伴畏寒肢冷，纳呆便溏；舌质淡，苔白腻，脉沉细","treat":"温阳散寒，化痰解毒","formula":"阳和汤加减","formulaNames":["阳和汤"]},{"t":"syn","sid":"s090503","name":"瘀毒化热证","clinic":"颈部岩肿迁延日久，肿块迅速增大，中央变软，周围坚硬，溃后渗流血水，状如翻花，并向四周漫肿而波及面部、胸部、肩背等处，可出现疼痛，头颈部活动受限；可伴发热，消瘦；舌质红，苔黄，脉数","treat":"清热散瘀，化痰解毒","formula":"黄连解毒汤合化坚二陈丸加减","formulaNames":["黄连解毒汤","化坚二陈丸"]},{"t":"syn","sid":"s090504","name":"气血两亏证","clinic":"颈部肿块溃破翻花，长期渗流腐臭血水，不能愈合，肉芽苍白水肿、高低不平；伴低热，乏力，消瘦；舌质淡，苔白或无苔，脉细","treat":"补益气血，化瘀解毒","formula":"八珍汤合四妙汤加减","formulaNames":["八珍汤","四妙汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)早期颈部肿块为气郁痰结证者，可外贴太乙膏。"},{"t":"p","x":"局部可用阿魏消痞膏外贴，每周1次。"},{"t":"p","x":"(2)早期颈部肿块为阴毒结聚证者，可外贴阳和解凝膏。"},{"t":"p","x":"(3)岩肿溃破翻花者，可用白降丹掺于疮面，其上敷太乙膏。"},{"t":"p","x":"若溃久气血衰败，疮面不鲜者，可用神灯照法熏其疮面后掺以阴毒内消散，外敷阳和解凝膏。"},{"t":"p","x":"(4)若肿块溃后、可选用蟾酥膏(蟾酥20g，凡士林100g，调成软膏)外敷，待癌组织脱落后改用生肌玉红膏外治。"},{"t":"p","x":"应熟悉颈部的局部解剖，在实施上述外治操作时严禁伤及颈部重要的神经、血管。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)全身化疗。"},{"t":"p","x":"(2)局部病变可用放射治疗。"}]}],"entries":["e0388","e0389","e0390","e0391","e0392","e0393","e0394"]},{"title":"预防与调护","blocks":[{"t":"p","x":"对颈部肿大淋巴结或肿块应尽早明确诊断。"}],"entries":["e0395"]}]},{"id":"d0906","kind":"main","chapterId":"ch09","chapterNo":"第九章","chapterName":"瘤、岩","name":"肾岩","displayName":"肾岩","parentId":"","printedPage":122,"pdfPage":137,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"阴茎乃男子之外肾，岩肿生于阴茎，故名“肾岩”。若肾岩日久疮面溃破，形如熟透之石榴，皮裂翻开，则又称“肾岩翻花”。"},{"t":"p","x":"其临床特点是阴茎表面出现丘疹、结节、疣状物突起坚硬，溃后状如翻花；好发于阴茎马口及其边缘，后期可侵犯整个阴茎。"},{"t":"p","x":"本病相当于西医学的阴茎癌。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.湿毒瘀结外感寒湿邪毒或肝经湿毒下注阴茎，结于前阴而发为本病。2.火毒炽盛湿浊邪毒瘀久化热，滞于阴茎，可发生肿块、结节；"},{"t":"p","x":"热盛肉腐，可致结节溃烂翻花。3.阴虚火旺病久火毒耗散阴津，或素体肝肾亏虚而致阴虚火旺，可出现低热、贫血、消瘦等症状。"},{"t":"p","x":"西医学认为本病的发病原因尚不清楚，其发生机制也尚未完全阐明。迄今为止，已确定的风险因素包括人乳头瘤病毒(human papilloma virus,HPV)感染、包茎、阴茎头炎、硬化性苔藓样变、阴茎创伤等。"}],"entries":["e0396","e0397"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病常发生于中老年人，多有包茎、包皮过长史。"},{"t":"p","x":"初起在包皮系带附近、阴茎龟头、冠状沟部或尿道口处见丘疹、溃疡、红斑、结节、疣状增生物等，逐渐增大，刺痒，边缘硬而不齐，有分泌物或出血。晚期则破溃，状如翻花石榴子样，分泌物恶臭，疼痛加重。"},{"t":"p","x":"严重者阴茎溃烂脱落，并可侵及耻骨部及阴囊。阴茎癌转移以淋巴转移为主，并呈逐级转移的特点。"},{"t":"p","x":"以腹股沟淋巴结最为多见。本病早期一般无明显全身症状，晚期可见发热、消瘦、贫血、无力、食欲不振等临床表现。"},{"t":"h","lv":3,"x":"(2)辅助检查组织病理学检查可以明确诊断。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表9-5)"},{"t":"table","img":"img/tab/t0905.jpg","cap":"表9-5肾岩与阴茎乳头状瘤、尖锐湿疣、阴茎白斑、阴茎结核的鉴别"}],"entries":["e0398"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以手术治疗为主，可配合中医辨证治疗或其他疗法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s090601","name":"湿毒瘀结证","clinic":"阴茎龟头或冠状沟出现丘疹或菜花状结节，逐渐增大，痒痛不休，溃后渗流血水，可见腹股沟淋巴结肿大；伴畏寒，乏力，小便不畅，尿道涩痛；舌质淡红，苔白腻，脉沉弦","treat":"利湿行浊，化瘀解毒","formula":"三妙丸合散肿溃坚汤加减","formulaNames":["三妙丸","散肿溃坚汤"]},{"t":"syn","sid":"s090602","name":"火毒炽盛证","clinic":"阴茎赘生结节，红肿胀痛，溃烂后状如翻花，渗出物腐臭难闻；伴发热，口干苦，大便秘结，小便短赤；舌质红，苔黄腻，脉弦数或滑数","treat":"清热泻火，消肿解毒","formula":"龙胆泻肝汤合四妙勇安汤加减","formulaNames":["龙胆泻肝汤","四妙勇安汤"]},{"t":"syn","sid":"s090603","name":"阴虚火旺证","clinic":"多见于肾岩手术、放化疗后或病变晚期，阴茎溃烂脱落；伴口渴咽干，疲乏无力，五心烦热，身体消瘦；舌红，少苔，脉细数","treat":"滋阴壮水，清热解毒","formula":"大补阴丸合知柏地黄丸加减","formulaNames":["大补阴丸","知柏地黄丸"]},{"t":"p","x":"2.外治疗法岩肿溃烂不洁，用五五丹或千金散撒于疮面，或用红灵丹油膏外敷；腐蚀至岩肿平复后，改用九一丹。"},{"t":"p","x":"如创面渗血可掺海浮散，外敷生肌玉红膏，创面清洁后改用红油膏或生肌白玉膏。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)局部治疗5-氟尿嘧啶(5-FU)或咪喹莫特局部治疗。"},{"t":"p","x":"(2)化疗常用以顺铂为基础的治疗方案。"},{"t":"p","x":"(3)放疗单纯放疗适用于尚未侵犯尿道或海绵体的表浅鳞状上皮癌。"},{"t":"p","x":"(4)手术根据病变范围和浸润程度可选择保留阴茎手术、阴茎部分切除术或阴茎全切除术等。"}]}],"entries":["e0399","e0400","e0401","e0402","e0403"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.包茎和部分包皮过长者需手术治疗。2.及时处理阴茎局部病变，如乳头状瘤、尖锐湿疣、黏膜白斑、阴茎皮角等。"},{"t":"p","x":"对可疑癌变者应及时行组织病理学检查，以期明确诊断。"}],"entries":["e0404"]}]},{"id":"d1000","kind":"chapter","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"本章概述","displayName":"皮肤及性传播疾病·本章概述","parentId":"","printedPage":125,"pdfPage":140,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"发生于人体皮肤、黏膜及皮肤附属器的疾病统称为皮肤病。皮肤病的病种很多，目前可以命名的多达2000余种、常见病有200余种。"},{"t":"p","x":"主要通过直接或间接性接触传播的一组传染性疾病称为性传播疾病(sexually transmitted disease, STD)，简称为“性病”，过去又称为“花柳病”。"},{"t":"p","x":"1975年世界卫生组织(WHO)正式决定使用性传播疾病来代替旧名，病种涵盖了梅毒、非淋菌性尿道炎、生殖器疱疹、艾滋病(acquired immune deficiency syndrome,AIDS)、尖锐湿疣、传染性软疣等，总数达50多种。"},{"t":"p","x":"本章仅介绍部分临床常见及代表性疾病。"}],"entries":["e0405"]},{"title":"病因病机","blocks":[{"t":"p","x":"皮肤病的病因复杂，但归纳起来不外乎外因、内因两类。外因主要是六淫(特别是风、湿、热)、疫疠之气、虫、毒等；"},{"t":"p","x":"内因主要是七情内伤、饮食劳倦、禀赋不耐等。其病机主要因气血失和、脏腑失调、邪毒结聚而致生风、生湿、化燥、致虚、致瘀、化热、伤阴等。"},{"t":"p","x":"性传播疾病主要由性接触染毒致病，属特殊病种，其病因病机分述于各病中。1.风邪许多皮肤病与风邪有着密切关系。"},{"t":"p","x":"风邪可以单独直接致病，也可以与他邪合而致病。凡人体腠理不密，卫气不固，风邪乘虚入侵，阻于皮肤，内不得通，外不得泄，致营卫不和，气血运行失常，肌肤失于濡养，则可致皮肤病发生。"},{"t":"p","x":"由风邪引起的皮肤病一般具有以下特点：发无定处，骤起骤消，如瘾疹；剧烈瘙痒，皮肤干燥、脱屑，如风瘙痒；"},{"t":"p","x":"多发于上部，如白屑风。临床上风邪常与他邪相兼为病，如风湿、风热、风寒等。"},{"t":"p","x":"2.湿邪湿有内湿、外湿之分，可单独致病，也可相合致病。湿邪侵入肌肤，郁结不散，与气血相搏，其皮肤损害以水疱为主，或皮肤糜烂，或浸淫四窜、滋水淋漓。"},{"t":"p","x":"常患病于下部，病程缠绵，难以速愈，愈后易发。3.热邪热为阳邪，火热同源。"},{"t":"p","x":"热为火之渐，热微则痒；火为热之甚，热盛则痛。外感热邪，或脏腑实热，蕴阻肌肤，不得外泄，熏蒸肌表，均可发生皮肤病。"},{"t":"p","x":"热邪致病多发于人体上部，其皮肤损害以红斑、红肿、脓疱、糜烂为主，自觉瘙痒或疼痛。4.虫由虫致生的皮肤病多种多样，虫不同则皮损也不相同。"},{"t":"p","x":"一为皮肤中寄生虫直接致病，如疥虫引起的疥疮，癣虫(真菌)引起的足癣等病；一为由昆虫的毒素侵入或过敏引起的皮肤病、如蚊虫叮咬所致虫咬皮炎等。"},{"t":"p","x":"由于古代条件所限，中医文献中对部分皮肤病认为是虫蚀所致，例如将真菌所致皮肤病也归为虫蚀为患；或以虫来形容皮肤病的瘙痒，如“痒如虫行”、而皮损中实非有虫，应予以区别。"},{"t":"p","x":"由虫引起的皮肤病，其症状是皮肤瘙痒甚剧，有的表现为糜烂，有的能互相传染，有的可伴局部虫斑、脘腹疼痛，大便中可查到虫卵等。5.毒由毒引起的皮肤病，可分为药物毒、食物毒、漆毒、虫毒等。"},{"t":"p","x":"其病机不外乎中毒或禀赋不耐，机体对某物质过敏而成。由毒邪引发的皮肤病，发病前有食“毒”物史或曾内服某种药物，或接触某种物质，或有毒虫叮咬史，大多需经过一定的潜伏期后方可发病。"},{"t":"p","x":"其皮损表现为灼红、肿胀、丘疹、水疱、风团、糜烂等多种形态，或痒或痛，轻则局限一处，重则泛发全身。停止上述毒邪来源后，其病去也快。"},{"t":"p","x":"病重者皮肤暴肿，起大疱，破流滋水，皮肤层层剥脱，甚则危及生命，如药物毒。6.血瘀为皮肤病重要的病因病机。"},{"t":"p","x":"凡外感六淫、内伤七情，均可导致气机不畅，气为血之帅，血随气行，气滞则血瘀而为病。"},{"t":"p","x":"血瘀证候多见于慢性皮肤病，其特点如皮损色暗、紫红、青紫，或出现肌肤甲错、色素沉着、瘀斑、肥厚、结节、肿块、瘢痕，舌紫或有瘀点，脉弦涩等，如瓜藤缠、黧黑斑。7.血虚风燥亦为皮肤病的重要病机。"},{"t":"p","x":"多种慢性皮肤病因长期皮肤瘙痒，寝食不安，脾虚食减，脾胃失其健运、阴血失其化源；或风湿郁久，郁而化热化火，伤其阴血，致阴血亏虚；"},{"t":"p","x":"或本虚病久，均可导致血虚风燥。其皮损特点以干燥、肥厚、粗糙、脱屑为主，自觉瘙痒，病程较长，如牛皮癣、白疕、慢性湿疮、风瘙痒等慢性皮肤病。"},{"t":"p","x":"8.肝肾不足脏腑失调是皮肤病重要的病因病机，其中以肝肾不足为多见。肝肾不足主要包括先天之精不足及后天精血不足。"},{"t":"p","x":"如肝血虚，爪甲失养，则指甲肥厚、干燥、变脆；肝虚血燥，筋气失荣，则生疣目；"},{"t":"p","x":"肝经火郁血滞，可致血痣。肾精不充，发失所养，则毛发干枯易脱；肾虚，本色上泛，则面生黧黑斑。"},{"t":"p","x":"因肝肾不足所致的皮肤病大多呈慢性过程，其皮损表现为干燥、肥厚、粗糙、脱屑，或伴毛发枯槁、脱发、色素沉着、甲病变，或伴生疣目、血痣等。因肾为先天之本，故某些先天性、遗传性皮肤病与肝肾亦有一定的关系，如鱼鳞病、各种脱发。"},{"t":"p","x":"总之、皮肤病的发生往往不是单一原因所引起，常为数个以上的病因共同作用所致。或内伤与外感兼夹在一起，或为实证，或为虚证，或虚实夹杂。"},{"t":"p","x":"所以在审因辨证时要善于分析，才能得出正确的结论。"}],"entries":["e0406"]},{"title":"辨证","blocks":[{"t":"p","x":"1.皮肤病的常见症状皮肤病在发病过程中，可产生一系列的自觉症状和他觉症状，是皮肤病辨证与诊断的重要依据。"},{"t":"p","x":"(1)自觉症状即患者主观的感觉。"},{"t":"p","x":"皮肤病的自觉症状取决于原发病的性质、病变程度及患者的个体差异等。最常见的症状是瘙痒，其次是疼痛，此外尚有灼热、麻木、蚁行感等。"},{"t":"p","x":"1)瘙痒可由多种因素引起，但重在风邪及热邪的辨证。"},{"t":"p","x":"一般急性皮肤病的瘙痒多由外风所致，故其有症状流窜不定、泛发且起病迅速的特点，可有风寒、风热、风湿热的不同。"},{"t":"p","x":"①风寒所致瘙痒，遇寒加重，皮疹色白；"},{"t":"p","x":"②风热所致瘙痒，皮疹色红，遇热加重；"},{"t":"p","x":"③风湿热所致瘙痒，抓破有渗液或起水疱。"},{"t":"p","x":"此外，营血有热所致瘙痒，皮损色红灼热，见丘疹、红斑、瘀点、瘀斑、风团，瘙痒剧烈，抓破出血。慢性皮肤病的瘙痒原因复杂，寒、湿、痰、瘀、虫淫、血虚风燥、肝肾不足等因素均可导致瘙痒。"},{"t":"p","x":"①寒证瘙痒除因寒邪外袭外，尚可由脾肾阳虚生内寒而致瘙痒，皮疹色淡，发热症状不明显，或呈寒性结节、溃疡等；"},{"t":"p","x":"②湿热所致瘙痒皮疹可表现为流滋或水疱；"},{"t":"p","x":"③痰邪所致瘙痒则常出现结节；"},{"t":"p","x":"④瘀血所致瘙痒可见紫斑、色素沉着等；"},{"t":"p","x":"⑤瘀血夹湿所致瘙痒剧烈，皮损结节坚硬，顽固难愈；"},{"t":"p","x":"⑥虫淫所致瘙痒表现为痒如虫行或蚁走，阵发性奇痒难忍，且多具传染性；"},{"t":"p","x":"⑦血虚风燥及肝肾不足所致瘙痒常有血痂或糠秕样脱屑、皮肤干裂、苔藓样变等。"},{"t":"p","x":"2)疼痛皮肤病有疼痛症状者不多，一般多由寒邪，热邪或痰凝血瘀阻滞，经络不通所致，“通则不痛，痛则不通”。"},{"t":"p","x":"①寒证疼痛表现为局部青紫，遇寒加剧，得温则缓；"},{"t":"p","x":"②热证疼痛有红肿、发热与疼痛性皮损；"},{"t":"p","x":"③痰凝血瘀疼痛可有痰核结节或瘀斑、青紫，疼痛位置多固定不移。"},{"t":"p","x":"此外，有些较重的皮肤病后期或年老体弱、气血亏虚的蛇串疮患者，虽皮肤损害已愈，但后遗疼痛，且较剧烈，属虚证兼气滞血瘀疼痛。"},{"t":"p","x":"3)灼热感为热邪蕴结或火邪炽盛，炙灼肌肤的自觉感受，常见于急性皮肤病。"},{"t":"p","x":"4)蚁行感、麻木感为皮肤病较特殊的局部自觉症状。"},{"t":"p","x":"蚁行感与瘙痒感颇为近似，但程度较轻，由虫淫为患或气血失和所致。"},{"t":"p","x":"麻木感常见于一些特殊的皮肤病，如麻风病的皮损，有的慢性皮肤病后期如带状疱疹后遗症也偶见麻木的症状，一般认为麻木为气血虚或毒邪炽盛或湿痰瘀血阻络，导致经脉失养，或气血凝滞，经络不通所致。"},{"t":"p","x":"(2)他觉症状为皮肤病的客观体征。"},{"t":"p","x":"以表现在患部的皮肤损害最具诊断意义。皮肤损害(简称皮损)，也称皮疹、分为原发性和继发性两大类，但有时二者不能截然分开，如脓疱为原发性皮损，但也可继发于丘疹或水疱。"},{"t":"p","x":"掌握这些基本皮损的特点，对皮肤病诊断、辨证治疗都非常重要。"},{"t":"p","x":"1)原发性皮损是皮肤病在其病变过程中，直接发生及初次出现的皮损，有斑疹、丘疹、斑块、风团、结节、囊肿、水疱、脓疱等。"},{"t":"p","x":"斑疹：为局限性皮肤黏膜的颜色改变，与周围皮肤平齐，无隆起或凹陷(图10-1)。直径达到或超过1cm时，称为斑片。"},{"t":"p","x":"分为红斑、色素沉着斑、色素减退斑等。红斑压之退色者多属血热；"},{"t":"p","x":"压之不退色者除血热外，尚兼血瘀；红斑稀疏者为热轻，密集者为热重，红而带紫为热毒炽盛。"},{"t":"p","x":"红斑常见于丹毒、药毒等皮肤病。色素沉着斑如黧黑斑，是肝肾不足、气血瘀滞所致。"},{"t":"p","x":"色素减退斑多由气血凝滞或血虚兼风邪所致，最常见者为白驳风。丘疹：为高出皮面的实性丘形小粒，直径一般小于1cm，多为风热、血热所致(图10-1)。"},{"t":"p","x":"丘疹数目多少不一，有散在分布的；有的互相融合而成扁平隆起的片状损害，直径大于1cm，称斑块。"},{"t":"p","x":"丘疹顶端扁平的称扁平丘疹，常见于扁瘊、牛皮癣、湿疮等。介于斑疹与丘疹之间，稍有隆起的皮损称斑丘疹。"},{"t":"p","x":"丘疹顶部有较小水疱或脓疱时，称丘疱疹或丘脓疱疹。斑块：为局限性、实质性的表浅隆起性皮损，直径>1cm(图10-2)。"},{"t":"p","x":"斑块可触及，为丘疹扩大或较多丘疹融合而成，常见于白疕等。风团：为皮肤上局限性水肿隆起，常突然发生，迅速消退，消退后多不留痕迹，发作时伴有剧痒(图10-2)。"},{"t":"p","x":"有红色与白色之分，红色者多为风热所致，白色者多为风寒所致，常见于瘾疹。"},{"t":"img","src":"img/fig/f1002.jpg","alt":"图10-2斑块和风团"},{"t":"img","src":"img/fig/f1001.jpg","alt":"图10-1斑疹和丘疹"},{"t":"p","x":"结节：为大小不一、境界清楚的实质性损害，质较硬，深在皮下或高出皮面，多由气血凝滞所致，常见于结节性红斑、结节性痒疹等病(图10-3)。囊肿：为含有液体或黏稠物及细胞成分的囊样皮损(图10-3)。"},{"t":"p","x":"呈球形或卵圆形，触之有囊性感，大小不等。常见于聚合性痤疮、表皮囊肿，辨证多为痰湿。"},{"t":"p","x":"水疱：为内有腔隙、含有液体、高出皮面的损害(图10-4)。直径大于1cm者称大疱。"},{"t":"p","x":"水疱内含有血性液体者称血疱。水疱为白色，血疱为红色或紫红色。"},{"t":"p","x":"水疱的疱壁一般较薄易破，破后形成糜烂，干燥后结痂脱屑。水疱常发于红斑之上，多属湿热或热毒所致，常见于湿疮、接触性皮炎、虫咬皮炎等。"},{"t":"p","x":"脓疱：疱内含有脓液，其色呈浑浊或为黄色，周围常有红晕，疱破后形成糜烂或溃疡，溢出脓液，结脓痂(图10-4)。多因湿热或热毒炽盛所致，常见于脓疱疮等。"},{"t":"img","src":"img/fig/f1004.jpg","alt":"图10-4水疱和脓疱"},{"t":"img","src":"img/fig/f1003.jpg","alt":"图10-3结节和囊肿"},{"t":"p","x":"2)继发性皮损是原发性皮损经过搔抓、感染、治疗处理和在损害修复过程中演变而成，有鳞屑、浸渍、糜烂、溃疡、萎缩、痂、抓痕、苔藓样变、皲裂、瘢痕、色素沉着等。"},{"t":"p","x":"鳞屑：为表皮角质层的脱落(图10-5)，大小、厚薄、形态不一，可呈糠秕状(如风热疮)、蛎壳状(如白疕)或大片状(如剥脱性皮炎)。急性病后见之，多为余热未清；慢性病见之，多由血虚生风、生燥、皮肤失于濡养所致。"},{"t":"p","x":"浸渍：因皮肤角质层吸收较多水分导致表皮变软变白，摩擦后表皮易脱落而露出糜烂面(图10-常见于足趾缝等皮肤皱褶部位、或皮肤长时间潮湿浸水所致。"},{"t":"p","x":"浸渍辨证属湿，浸渍糜烂属湿热。糜烂：为局限性的表皮或黏膜上皮缺损，系由水疱、脓疱破裂，痂皮脱落等露出的红色湿润面，多属湿热为患(图10-6)。"},{"t":"p","x":"糜烂因损害较浅，愈合较快，一般不留瘢痕。溃疡：为皮肤或黏膜深层真皮或皮下组织的局限性缺损(图10-6)。"},{"t":"p","x":"溃疡大小不一，疡面有脓液、浆液或血液，基底可有坏死组织。多为热盛肉腐而成，常见于疮疔、外伤染毒等溃烂后形成，愈后可留有瘢痕。"},{"t":"img","src":"img/fig/f1006.jpg","alt":"图10-6糜烂和溃疡"},{"t":"img","src":"img/fig/f1005.jpg","alt":"图10-5屑和浸渍"},{"t":"p","x":"萎缩：为皮肤的结构成分减少、变薄所致(图10-7)。表皮萎缩时皮肤呈半透明羊皮纸样外观，皮纹变浅或消失，其下血管较为清晰可见；"},{"t":"p","x":"真皮或皮下脂肪萎缩时皮肤呈局限性凹陷，皮纹不变。常见于一些慢性皮肤病的皮损表现，多因气血两虚、营卫失和、肌肤失养而成，如皮痹等。"},{"t":"p","x":"痂：皮损处的渗液、滋水、渗血或脓液与脱落组织及药物等混合干燥后即形成痂(图10-7)。脓痂为热毒未清所致；血痂为血热络伤，血溢所结；滋痂为湿热所致。"},{"t":"p","x":"抓痕：因搔抓将表皮抓破、擦伤而形成的线状或点状损害，表面结成血痂(图10-8)。多由风盛或内热所致。"},{"t":"p","x":"苔藓样变：为皮肤增厚、粗糙、皮嵴隆起、皮沟加深、干燥、局限性边界清楚的大片或小片损害(图10-8)。常为一些慢性瘙痒性皮肤病的主要表现，多由血虚风燥、肌肤失养所致，常见于牛皮癣、慢性湿疮等。"},{"t":"img","src":"img/fig/f1008.jpg","alt":"图10-8抓痕和苔藓样变"},{"t":"img","src":"img/fig/f1007.jpg","alt":"图10-7萎缩和痂"},{"t":"p","x":"皲裂：为皮肤上的线形坼裂(图10-9)，好发于掌跖、指趾、口角等处；多由血虚风燥所致。"},{"t":"p","x":"瘢痕：为外伤后或溃疡愈合形成的新生结缔组织，表面光滑，无正常皮肤纹理及附属器(图10-增生性瘢痕高于皮肤表面，色红，质硬，有痒痛感，为局部气血凝滞不散所致；"},{"t":"p","x":"萎缩性瘢痕低于皮肤表面，色白、柔软，一般无自觉症状，为局部气血失和、皮肤失于濡养所致。色素沉着：为皮肤中色素增加所致，多呈褐色、暗褐色或黑褐色(图10-10)。"},{"t":"p","x":"色素沉着有的属原发性皮损，如黧黑斑、黑变病等，多由肝火、肾虚引起；有的属继发性皮损，如一些慢性皮肤病之后期局部皮肤色素沉着，多因气血失和所致，如慢性湿疮、固定型药毒等。"},{"t":"img","src":"img/fig/f1009.jpg","alt":"图10-9腋裂和癌痕"},{"t":"img","src":"img/fig/f1010.jpg","alt":"图10-10色素沉着"},{"t":"p","x":"2.皮肤病的性质按照临床表现来分，皮肤病主要分为急性、慢性两大类，急性者大多为实证，慢性者以虚证为主。"},{"t":"h","lv":2,"x":"(1)急性皮肤病大多起病急骤。"},{"t":"p","x":"皮损表现以原发性为主，如红斑、丘疹、水疱、脓疱、风团、结节等，亦可相继出现糜烂、鳞屑、结痂等继发性皮损。病因大多为风、湿、热、虫、毒，以实证为主。"},{"t":"p","x":"与肺、脾、心三脏的关系最为密切。《素问·至真要大论》指出：“诸痛痒疮，皆属于心。"},{"t":"p","x":"因心主热，火之化，热甚则疮痛，热微则疮痒。《诸病源候论·疮病诸候》曰：“肺主气，候于皮毛；脾主肌肉。"},{"t":"p","x":"气虚则肤腠开，为风湿所乘；内热则脾气温，脾气温则肌肉生热也。湿热相搏，故头面身体皆生疮。”"},{"t":"h","lv":2,"x":"(2)慢性皮肤病大多发病缓慢。"},{"t":"p","x":"皮损表现以继发性为主，如苔藓样变、色素沉着、皲裂、鳞屑等，或伴有脱发、指(趾)甲变化。病因大多为血瘀或营血不足，肝肾亏损，冲任失调，以虚证为主。"},{"t":"p","x":"与肝、肾两脏关系最为密切。肝藏血，血虚则生风生燥，肤失濡养而为病；"},{"t":"p","x":"肾藏精，黑色属肾，发为肾之华，肾精不足则可产生皮肤的色素改变及脱发等病。"}],"entries":["e0407"]},{"title":"治法","blocks":[{"t":"p","x":"依据皮肤病的病因病机、皮损特点、患者体质、病情轻重，采用辨证论治、内外合治的原则进行治疗，以期达到早日康复的目的。但皮肤病多为人体全身性疾病在皮肤上的表现，许多全身性疾病可反映在皮肤上；"},{"t":"p","x":"而皮肤上的局部刺激也可引起全身性病变。因此，中医治疗皮肤病主张“治外必本诸内”，局部与整体并重。"},{"t":"p","x":"治疗方法分内治、外治两大类，在临床应用时必须根据患者的体质情况及不同的致病因素和皮损形态，拟定内治和外治的法则。"}],"entries":["e0408"]},{"title":"(一)内治","blocks":[{"t":"h","lv":3,"x":"1.祛风法"},{"t":"p","x":"(1)疏风清热用于风热证。"},{"t":"p","x":"代表方如银翘散、桑菊饮、消风散。常用药物如荆芥、防风、蝉蜕、牛蒡子、金银花、连翘、桑叶、菊花、黄芩、生地黄、栀子等。"},{"t":"p","x":"(2)疏风散寒用于风寒证。"},{"t":"p","x":"代表方如麻黄汤、桂枝麻黄各半汤。常用药物如麻黄、桂枝、羌活、荆芥、防风等。"},{"t":"p","x":"(3)祛风胜湿用于风湿证。"},{"t":"p","x":"代表方如独活寄生汤。常用药物如细辛、防风、独活、桑寄生、桑艽、茯苓等。"},{"t":"p","x":"(4)驱风潜镇用于风邪久羁证或肝风内动证。"},{"t":"p","x":"代表方如镇肝熄风汤、天麻钩藤饮。常用药物如乌梢蛇、蝉蜕、全蝎、龙骨、牡蛎、磁石、珍珠母、钩藤等。"},{"t":"h","lv":3,"x":"2.清热法"},{"t":"p","x":"(1)清热解毒用于实热证。"},{"t":"p","x":"代表方如五味消毒饮、黄连解毒汤。常用药物如金银花、蒲公英、紫花地丁、连翘、黄连、黄芩、栀子、黄柏、板蓝根等。"},{"t":"p","x":"(2)清热凉血用于血热证。"},{"t":"p","x":"代表方如犀角地黄汤、化斑解毒汤。常用药物如水牛角粉、栀子、黄连、赤芍、牡丹皮、生石膏、槐花、生地黄、白茅根、紫草等。"},{"t":"h","lv":3,"x":"3.祛湿法"},{"t":"p","x":"(1)清热燥湿用于湿热证和暑湿证。"},{"t":"p","x":"代表方如茵陈蒿汤、龙胆泻肝汤、萆薢渗湿汤。常用药物如茵陈、车前草、栀子、龙胆草、黄柏、萆薢、薏苡仁、滑石等。"},{"t":"p","x":"(2)健脾化湿用于脾虚湿盛证。"},{"t":"p","x":"代表方如除湿胃苓汤。常用药物如苍术、厚朴、陈皮、薏苡仁、藿香、佩兰等。"},{"t":"p","x":"(3)滋阴除湿用于阴虚夹湿证。"},{"t":"p","x":"代表方如滋阴除湿汤。常用药物如生地黄、当归、玄参、茯苓、泽泻、黄柏等。"},{"t":"p","x":"(4)淡渗利湿用于水湿内停证。"},{"t":"p","x":"代表方如五苓散、猪苓汤。常用药物如茯苓、猪苓、泽泻、薏苡仁、滑石等。"},{"t":"p","x":"(5)祛风除湿用于风湿痹证。"},{"t":"p","x":"代表方如九味羌活汤。常用药物如羌活、独活、防风、秦艽、威灵仙等。"},{"t":"p","x":"(6)温阳胜湿用于阳虚水泛证。"},{"t":"p","x":"代表方如苓桂术甘汤。常用药物如附子、干姜、肉桂、白术、茯苓等。"},{"t":"h","lv":3,"x":"4.润燥法"},{"t":"p","x":"(1)养血润燥用于血虚风燥证。"},{"t":"p","x":"代表方如四物汤、当归饮子。常用药物如熟地黄、当归、川芎、白芍、女贞子、墨旱莲、白蒺藜、何首乌、火麻仁等。"},{"t":"p","x":"(2)凉血润燥用于血热风燥证。"},{"t":"p","x":"代表方如凉血消风散。常用药物如生地黄、牡丹皮、水牛角粉、当归、丹参、槐花、白茅根、紫草、生石膏等。"},{"t":"h","lv":3,"x":"5.活血法"},{"t":"p","x":"(1)理气活血用于气滞血瘀证。"},{"t":"p","x":"代表方如桃红四物汤。常用药物如当归、赤芍、桃仁、红花、川芎、生地黄、香附、郁金等。"},{"t":"p","x":"(2)活血化瘀用于瘀血凝结证。"},{"t":"p","x":"代表方如通窍活血汤、血府逐瘀汤。常用药物如川芎、桃仁、红花、赤芍、牛膝、水蛭、枳壳等。"},{"t":"h","lv":3,"x":"6.温通法"},{"t":"p","x":"(1)温阳通络用于寒湿阻络证。"},{"t":"p","x":"代表方如当归四逆汤、独活寄生汤。常用药物如麻黄、桂枝、当归、羌活、独活、制川乌、红花、细辛、牛膝等。"},{"t":"p","x":"(2)通络除痹用于寒凝皮痹证。"},{"t":"p","x":"代表方如阳和汤。常用药物如麻黄、熟地黄、肉桂、干姜、白芥子、鹿角胶等。"},{"t":"h","lv":3,"x":"7.软坚法"},{"t":"p","x":"(1)消痰软坚用于痰核证。"},{"t":"p","x":"代表方如海藻玉壶汤。常用药物如法半夏、浙贝母、陈皮、青皮、海藻、昆布等。"},{"t":"p","x":"(2)活血软坚用于瘀血内结证。"},{"t":"p","x":"代表方如活血散瘀汤。常用药物如当归、川芎、赤芍、桃仁、三棱、莪术、苏木等。"},{"t":"h","lv":3,"x":"8.补肾法"},{"t":"p","x":"(1)滋补肾阴用于阴虚内热证或肝肾阴虚证。"},{"t":"p","x":"代表方如知柏地黄汤、大补阴丸。常用药物如生地黄、玄参、麦冬、山茱萸、龟甲、女贞子、墨旱莲、知母、黄柏等。"},{"t":"p","x":"(2)温补肾阳用于脾肾阳虚证。"},{"t":"p","x":"代表方如肾气丸、右归丸。常用药物如肉桂、附子、枸杞子、山茱萸、菟丝子、巴戟天、仙茅、淫羊藿等。"}],"entries":["e0409"]},{"title":"(二)外治","blocks":[{"t":"p","x":"皮肤病的病变部位多在皮肤或黏膜，采用各种外治法可以减轻患者的自觉症状，并使皮损迅速消退，有些皮肤病单用外治即可达到治疗目的。因此，外治法在皮肤病的治疗中十分重要，也是最直接的治法。"},{"t":"p","x":"皮肤病外治可分药物外治和非药物外治，火针疗法、埋线疗法、拔罐疗法等非药物外治疗法近年来在临床应用广泛、疗效好，操作简便，其相关内容参见总论及教材数字化部分，以下重点论述药物外治疗法。"},{"t":"p","x":"在使用药物外治疗法时，必须根据皮损情况，依照外用药物的使用原则进行辨证施治，正确使用外用剂型及药物。外治法同样遵循同病异治、异病同治的治疗法则。"},{"t":"p","x":"现将外用药物的常用剂型及使用原则分述如下。"},{"t":"h","lv":3,"x":"1.外用药物的剂型"},{"t":"p","x":"(1)溶液是药物的水溶液，将单味药或复方加水，煎熬至一定浓度，滤过药渣所得。"},{"t":"p","x":"具有清洁、止痒、消肿、收敛、清热解毒的作用。适用于急性皮肤病渗出较多或剧烈红肿或脓性分泌物多的皮损。"},{"t":"p","x":"可用于湿敷和熏洗。常用药物如苦参、黄柏、蛇床子、马齿苋、生地榆、金银花、野菊花、蒲公英、千里光等煎出液；"},{"t":"p","x":"或10%黄柏溶液、康复新液、3%硼酸溶液、生理盐水及蒸馏水等。溶液用于湿敷是治疗皮肤病常用的方法，适用于急性红肿、渗出糜烂的皮损，或浅表溃疡。"},{"t":"p","x":"使用时将5～6层消毒纱布置于溶液中浸透，稍加拧挤至不滴水为度，冷敷于患处，每次10～15分钟，可间隔1～2小时操作1次；如渗液不多，可间隔4～5小时操作1次。"},{"t":"p","x":"溶液熏洗应温度适当，一般以37℃左右为宜，通常冷湿敷疗效更佳，太热易烫伤皮肤。"},{"t":"p","x":"(2)粉剂(又名散剂)为单味或复方中药研磨或粉碎成极细粉末的制剂。"},{"t":"p","x":"具有保护、吸收、蒸发、干燥、止痒的作用。适用于无渗液的急性或亚急性皮炎。"},{"t":"p","x":"常用药物如青黛散、六一散、滑石粉、止痒扑粉等。用法为每天3～5次扑患处。"},{"t":"p","x":"(3)洗剂(又名混悬剂、悬垂剂)是粉加水混合在一起的制剂，粉不溶于水，故久置后一些药粉沉淀于水底，使用时需振荡摇匀。"},{"t":"p","x":"有清凉止痒、保护、干燥、消斑解毒的作用。适应证同粉剂。"},{"t":"p","x":"常用药物如三黄洗剂、炉甘石洗剂、颠倒散洗剂等。用法为用前摇匀，外搽皮损处，每日4～6次。"},{"t":"p","x":"若制剂中有薄荷脑、樟脑、冰片等清凉药物，婴儿面部、外阴等薄嫩处，皮肤破损处及寒冷冬天不宜使用。"},{"t":"p","x":"(4)酊剂是将药物浸泡于50%～75%乙醇或白酒中，密封7～30天后滤过而成的酒浸剂(也有用醋浸泡的醋剂)。"},{"t":"p","x":"具有收敛散风、活血消肿、杀菌止痒、溶解皮脂、刺激色素生长等作用。适用于慢性瘙痒性皮肤病、色素脱失性皮肤病、脱发、脚湿气、鹅掌风、圆癣等。"},{"t":"p","x":"常用药物如复方土槿皮酊、百部酊、补骨脂酊等。用法为用棉棒蘸药液直接外涂皮损区，每天1～3次。"},{"t":"p","x":"凡急性炎症性皮肤病破皮糜烂者及面部、外阴等皮肤薄嫩处禁用。"},{"t":"p","x":"(5)油剂为粉剂与植物油调成糊状或以药物浸在植物油中煎炸后滤去药渣而成。"},{"t":"p","x":"具有润泽保护、解毒收敛、止痒生肌、软化痂皮的作用。适用于亚急性皮肤病中有少量渗出、鳞屑、痂皮、溃疡的皮损。"},{"t":"p","x":"常用药物如紫草油、青黛散油、三石散油、蛋黄油等。常用的植物油为麻油、菜籽油、花生油等，以麻油为最佳，有清凉润肤之功。"},{"t":"p","x":"用法为每天外搽患处1～2次。"},{"t":"p","x":"(6)软膏是将药物研成细粉，用凡士林、羊毛脂等作为基质调成的均匀、细腻、半固体状的剂型。"},{"t":"p","x":"具有保护、润滑、杀菌、止痒、去痂的作用。适用于一切慢性皮肤病具有结痂、皲裂、苔藓样变等皮损者。"},{"t":"p","x":"常用药物如青黛膏、黄连膏、金黄膏、5%硫黄软膏等。用法为每天外搽皮损处2～3次，或涂于纱布上敷贴于患部，再用塑料薄膜封包、去痂时宜涂厚些。"},{"t":"p","x":"用于皲裂、苔藓样变皮损时。加用热烘疗法效果更好。"},{"t":"p","x":"凡糜烂、渗出及分泌物较多的皮损忌用。此外、还有乳剂、凝胶、气雾剂等剂型在临床亦较常用。"},{"t":"p","x":"2.外用药物使用原则主要是根据皮损表现来选择适当的剂型和药物。"},{"t":"p","x":"(1)根据病情阶段正确选择剂型皮肤炎症在急性阶段，若仅有红斑、丘疹、水疱而无糜烂、渗液者、应选洗剂、粉剂；"},{"t":"p","x":"若有大量渗液或明显红肿、则用溶液作开放性冷湿敷。皮肤炎症在亚急性阶段，渗液与糜烂很少，红肿减轻、有鳞屑和结痂，则用油剂为宜。"},{"t":"p","x":"皮肤炎症在慢性阶段，有浸润肥厚、苔藓样变者，应选软膏及酊剂。"},{"t":"p","x":"(2)根据疾病性质合理选择药物如有感染时先用清热解毒、抗感染制剂控制感染，然后再针对原来皮损选用药物。"},{"t":"p","x":"(3)用药宜先温和后强烈先用性质比较温和的药物，尤其是儿童或妊娠期、哺乳期女性患者不宜使用刺激性强、浓度高的药物。"},{"t":"p","x":"面部、阴部皮肤慎用刺激性强的药物。"},{"t":"p","x":"(4)用药浓度宜先低后浓先用低浓度制剂，根据病情需要再提高浓度。"},{"t":"p","x":"一般急性皮肤病用药宜温和舒缓，顽固性慢性皮损可用刺激性较强和浓度较高的药物。"},{"t":"p","x":"(5)随时注意用药反应一旦出现皮肤过敏、刺激或中毒反应，应立即停用，并给予相应处理。"}],"entries":["e0410"]},{"title":"预防与调护","blocks":[{"t":"p","x":"皮肤病虽形于外，必本于内。预防调护须秉持中医整体观，外在防护与内在调理并重，不可偏废。"},{"t":"p","x":"1.固护正气顺应四时，起居有常。生活规律，避免熬夜，劳逸适度，保证充足睡眠；坚持适度锻炼，增强体质。"},{"t":"p","x":"2.避其外邪避风寒、暑热、湿浊等外邪侵袭，避免接触已知的过敏原(如花粉、尘螨、动物皮毛)或刺激物(如化学制剂、劣质化妆品)。3.饮食有节饮食宜清淡、均衡、易消化。"},{"t":"p","x":"禀赋不耐者慎食鱼腥发物(海鲜、牛羊肉等)，血热证者忌辛辣燥热、温补之品，湿热证者忌肥甘厚味、辛辣甜腻，脾胃虚弱者忌生冷寒凉。4.情志调摄情志舒畅，避免五志过极；保持乐观情绪，避免焦虑抑郁加重病情。"},{"t":"p","x":"5.皮肤清洁与保护保持患处干燥或润泽，穿着柔软透气棉质衣物。注意防护，减少物理性(如过度搔抓、暴晒、摩擦)与生物性(如虫咬、感染源)损伤。"}],"entries":["e0411"]}]},{"id":"d1001","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"热疮","displayName":"热疮","parentId":"","printedPage":132,"pdfPage":147,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"热疮是高热过程中或发热后在皮肤黏膜交界处所发生的急性疱疹性皮肤病。其临床特点是皮损为成群的水疱，有的互相融合，自觉灼热痒痛，多在1周后痊愈，一般无全身症状，但易于复发。"},{"t":"p","x":"宋代《圣济总录》记载：“热疮本于热盛，风气因而乘之，故特谓之热疮。”本病多见于高热患者的发病过程中或发热后，如感冒、猩红热、疟疾等。"},{"t":"p","x":"好发于口唇、鼻孔周围、面颊等皮肤黏膜交界处。而发于外阴的则与不洁性接触有关。"},{"t":"p","x":"本病相当于西医学的单纯疱疹。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.肺胃热盛初期外感风温热毒，邪气阻于肺胃二经，肺胃热盛，蕴蒸皮肤，循经而发。常见于口周、鼻周等胃经循行部位。"},{"t":"p","x":"2.湿热下注由于情志内伤，肝气郁结，久而化火，肝经火毒蕴积，或恣食辛辣刺激之品，脾胃功能失调，湿热内生，或接触不洁之毒，湿热火毒之邪下注，阻于阴部而成疮。"},{"t":"p","x":"3.阴虚内热后期正虚毒恋，反复发作，热邪伤津，阴虚内热，多因遇发热、受凉、经期或过劳等情况、正气进一步受损，则伏邪循经而发。"},{"t":"p","x":"西医学认为，本病是由单纯疱疹病毒(herpes simplex virus, HSV)引起，分为HSV-I型和HSV-Ⅱ型。HSV-I型多引起口周黏膜疱疹，HSV-Ⅱ型多引起生殖器疱疹。"},{"t":"p","x":"发热、日晒、月经来潮、妊娠、胃肠功能障碍等常为诱发因素。"}],"entries":["e0412","e0413"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于高热患者的发病过程中或发热后，好发于皮肤黏膜交界处，常见于口角、唇缘、鼻孔周围、面颊及外阴等部位。"},{"t":"p","x":"皮损初起为红斑，灼热而痒，继而形成针头大小簇集成群的水疱，内含透明浆液，破裂后露出糜烂面，逐渐干燥，结痂脱落而愈，留有轻微色素沉着。病程1～2周，易反复发作。"},{"t":"h","lv":3,"x":"(2)辅助检查血常规、分泌物细胞培养等检查有助于诊断。"},{"t":"p","x":"2.鉴别诊断热疮与黄水疮的鉴别见表10-1，与蛇串疮的鉴别见表10-2。"},{"t":"table","img":"img/tab/t1001.jpg","cap":"表10-1热疮与黄水疮的鉴别"}],"entries":["e0414"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热解毒、养阴清热为主要治法。初发以清热解毒治之，反复发作者以扶正祛邪并治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100101","name":"肺胃热盛证","clinic":"疱疹多见于颜面部或口唇、鼻侧，群集小水疱，灼热痒痛；可伴轻度周身不适，心烦郁闷，大便干，小便黄；舌红，苔黄，脉弦数","treat":"疏风清热","formula":"辛夷清肺饮加减。水疱灼热痒痛者，加淡竹叶、地肤子以清热泻火，除湿止痒","formulaNames":["辛夷清肺饮"]},{"t":"syn","sid":"s100102","name":"湿热下注证","clinic":"疱疹发于外阴，灼热痛痒，水疱易破、糜烂；可伴有尿赤、尿频、尿痛；舌红，苔黄腻，脉数","treat":"清热利湿","formula":"龙胆泻肝汤加减。水疱较重者，加草藤、黄柏引热下行，除湿解毒","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s100103","name":"阴虚内热证","clinic":"周期性发作，反复不愈；伴口干唇燥，午后微热；舌红，苔薄或少苔，脉细数","treat":"养阴清热","formula":"增液汤加减。反复不愈伴乏力气短者，加太子参、猪苓以益气生津，健脾渗湿","formulaNames":["增液汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起者局部碘伏消毒，可用梅花针叩刺或火针刺法。"},{"t":"p","x":"(2)局部外用药以清热解毒、燥湿收敛为主。"},{"t":"p","x":"水疱初期可用茶水调二味拔毒散外搽。"},{"t":"p","x":"(3)水疱破溃，以糜烂、渗出偏重者，可用马齿苋煎水湿敷。"},{"t":"p","x":"(4)皮损以结痂为主者，可用青黛膏、黄连膏等外搽。"},{"t":"p","x":"3.其他疗法局部外用3%阿昔洛韦水剂或乳剂，或1%喷昔洛韦乳膏等。病情严重者可以口服阿昔洛韦或泛昔洛韦、连续7天。"}]}],"entries":["e0415","e0416","e0417","e0418","e0419"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持局部清洁，促使干燥结痂、防止继发感染。结痂后宜涂软膏，防其痂壳裂开。"},{"t":"p","x":"2.反复发作者应避免诱发因素。"}],"entries":["e0420"]}]},{"id":"d1002","kind":"attach","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"生殖器疱疹","displayName":"热疮·生殖器疱疹","parentId":"d1001","printedPage":134,"pdfPage":149,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"生殖器疱疹是由单纯疱疹病毒Ⅱ型病毒(HSV-Ⅱ)感染所引起的一种性传播疾病。古代文献称之为“阴疮”“阴疳”“瘙疳”。"},{"t":"p","x":"其临床特点是外阴局部出现群集小疱、糜烂，自觉灼痛，反复发作。临床上分为原发性生殖器疱疹和复发性生殖器疱疹。"},{"t":"p","x":"该病发于外阴、病在下焦，与肝、脾、肾关系最密切。房事不洁是引起生殖器疱疹最主要的原因。"},{"t":"p","x":"其病机为外受湿热淫毒，侵及肝经，邪毒下注，蕴于前阴，郁久化热化火；或素体阴虚，或房劳过度，肝肾阴虚，脾失健运，正虚毒恋，遇劳则再发。"},{"t":"p","x":"原发性生殖器疱疹潜伏期2～7天，初发损害为1个或多个小而瘙痒的红斑、丘疹，迅速变成小水疱，3～5天后可形成脓疱，破溃后表面糜烂、溃疡、结痂，伴有疼痛。"},{"t":"p","x":"复发性生殖器疱疹多在原发皮疹后1年内复发，一般复发间歇期3～4周至3～4个月。发热、受凉、早产、精神因素、消化不良、慢性病、疲劳等是常见的诱发的因素。"},{"t":"p","x":"常见的并发症有脑膜炎、脑炎、骶神经根炎及脊髓脊膜炎、疱疹性指头炎及泌尿生殖系统广泛感染等。疱液细胞学检查镜下可见多核巨细胞或核内病毒包涵体，疱液病毒培养有单纯疱疹病毒和细胞病变。"},{"t":"p","x":"本病需与硬下疳、软下疳及接触性皮炎等鉴别。硬下疳表现为无痛性溃疡与无痛性腹股沟淋巴结肿大，有时容易与生殖器疱疹的溃疡和淋巴结肿大混淆；"},{"t":"p","x":"但硬下疳溃疡基底较硬，可检测到梅毒螺旋体，梅毒血清反应阳性。生殖器疱疹目前尚无特效根治方法。"},{"t":"p","x":"治疗目的为缩短病程，减轻症状；防止继发感染和并发症；防止病情复发。"},{"t":"p","x":"强调辨证论治，扶正祛邪，内外结合治疗。肝经湿热证宜清热利湿、化浊解毒，用龙胆泻肝汤加减；"},{"t":"p","x":"阴虚毒恋证宜滋阴降火、解毒除湿，用知柏地黄丸加减。西医治疗主要包括抗病毒和提高机体免疫力。"},{"t":"p","x":"外治可参考“热疮”。"}],"entries":["e0421"]}]},{"id":"d1003","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"蛇串疮","displayName":"蛇串疮","parentId":"","printedPage":134,"pdfPage":149,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"蛇串疮是一种皮肤上出现成簇水疱，多呈带状分布，痛如火燎的急性疱疹性皮肤病。"},{"t":"p","x":"其临床特点是皮肤上出现红斑、小丘疹、水疱或丘疱疹，累累如串珠，排列成带状，沿一侧周围神经分布区出现，局部刺痛或伴同侧附近脊核。多数患者愈后很少复发，少数患者可多次发病。"},{"t":"p","x":"好发于成人，老年人病情尤重。本病首见于《诸病源候论·疮病诸候》，曰：“甑带疮者，绕腰生。"},{"t":"p","x":"此亦风湿搏于血气所生。状如甑带，因以为名。"},{"t":"p","x":"其多发于胸胁部，故又名缠腰火丹，亦称为火带疮、蛇丹、蜘蛛疮等。本病相当于西医学的带状疱疹。"},{"t":"p","x":"带状疱疹后遗症也可参考本病治疗。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于情志内伤，肝气郁结，久而化火，肝经火毒蕴积，多发于躯干；或夹风邪上窜头面，或夹湿邪下注，发于阴部及下肢。"},{"t":"p","x":"或因脾胃素虚、饮食不节、劳累过度、久病耗伤，脾失健运以致内生湿浊，复感外邪毒气，内外合邪发于肌肤。年老体弱者常因血虚肝旺，湿热毒蕴，导致气血凝滞，或气血亏虚，气虚血瘀，经络阻塞不通，以致疼痛剧烈，病程迁延。"},{"t":"p","x":"总之，本病初期以湿热火毒为主，后期是正虚血瘀为患。西医学认为，带状疱疹与水痘是由同一病毒即水痘-带状疱疹病毒引起的不同疾病。"}],"entries":["e0422","e0423"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"特征性皮损：初起为红色斑丘疹，继而出现簇集成群水疱、累累如串珠。分布特点：排列成带状，多发于身体一侧，常单侧性沿皮神经分布，一般不超过正中线。"},{"t":"p","x":"发病部位：好发于腰肋部、胸部或头面部，也可发于上肢、下肢。发病特点及病程：好发于春秋季节，多见于成年人，病程一般2周左右。"},{"t":"p","x":"老年人病程可达3～4周，更易出现重症皮损及后遗神经痛。前驱症状：发疹前常有患处皮肤灼热、刺痛，疼痛可早于皮疹出现，或与皮疹同时发生。"},{"t":"p","x":"或伴全身不适、乏力或低热。特殊部位的并发症：发于眼部和耳部者病情较重，疼痛剧烈，伴有附近臀核疼痛，甚至影响视力和听觉。"},{"t":"p","x":"轻症者可无皮损，仅有刺痛感，或稍潮红，无典型水疱；重者有脓疱、血疱或坏死。"},{"t":"p","x":"(2)辅助检查血常规、疱疹基底部刮取物、活检组织标本固定后染色镜检等有助于诊断。"},{"t":"p","x":"染色镜检可见多核巨细胞和核内嗜酸性包涵体。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-2)"},{"t":"table","img":"img/tab/t1002.jpg","cap":"表10-2蛇串疮与热疮、漆疮的鉴别"}],"entries":["e0424"]},{"title":"治疗","blocks":[{"t":"p","x":"本病治疗以清热利湿、行气活血止痛为主要治法。初期以清热利湿为主，后期以活血通络止痛为主，体虚者以扶正祛邪与通络止痛并用。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100301","name":"肝经湿热证","clinic":"皮损鲜红，灼热刺痛，疱壁紧张；口苦咽干，心烦易怒，大便干燥，小便黄；舌质红，苔薄黄或黄腻，脉弦滑数","treat":"清肝利湿，解毒止痛","formula":"龙胆泻肝汤加减。发于头面者，加金银花、升麻；有血疱者，加水牛角粉、牡丹皮；有脓疱者，加茵陈、土茯苓；疼痛明显者，加延胡索、白芍","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s100302","name":"脾虚湿蕴证","clinic":"皮损色淡，疼痛持续，疱壁松弛；口不渴，食少腹胀，大便时溏；舌淡或正常，苔白或白腻，脉沉缓或滑","treat":"健脾利湿、解毒止痛","formula":"除湿胃苓汤加减。发于下肢者、加川牛膝、黄柏；水疱大而多者，加土茯苓、萆薢、车前草","formulaNames":["除湿胃苓汤"]},{"t":"syn","sid":"s100303","name":"气滞血瘀证","clinic":"皮疹减轻或消退后局部疼痛不止，放射到附近部位，痛不可忍，坐卧不安，重者可持续数月或更长时间；舌暗，苔白，脉弦细","treat":"理气活血，通络止痛","formula":"桃红四物汤加减。心烦眠差者，加栀子、酸枣仁；疼痛剧烈者，加制乳香、制没药、蜈蚣；年老体虚者，加黄芪、党参等","formulaNames":["桃红四物汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起用浓茶水调二味拔毒散外涂；"},{"t":"p","x":"或六神丸研碎水调外败；或外搽双柏散、三黄洗剂、清凉乳剂，每天3次；"},{"t":"p","x":"或鲜马齿苋、野菊花叶、玉簪花叶捣烂外敷。"},{"t":"p","x":"(2)水疱破后用黄连膏、四黄膏或青黛膏外涂。"},{"t":"p","x":"(3)若水疱不破或水疱较大者，可用三棱针或消毒空针刺破，吸尽疱液或使疱液流出，以减轻胀痛不适感。"},{"t":"p","x":"3.其他疗法疱疹急性期可用刺络放血、拔罐、针灸疗法等，疱疹恢复期和后遗症期可用针灸、火针、穴位注射、穴位埋线、热奄包、拔罐等方法。"},{"t":"p","x":"(1)针刺疗法"},{"t":"p","x":"围针：沿疱疹或疼痛分布带边缘每隔3cm取一针刺点，捻转得气后，留针30分钟，取针，每日1次，连刺7天。体针：取内关、曲池、阳陵泉、足三里、合谷、三阴交、支沟、阿是穴、夹脊穴等。"},{"t":"p","x":"火针：以毫针先刺破疱壁，释放疱液，再以毫针针尖经酒精灯火焰烧红后，迅速对皮损或疼痛部位进行快速点刺，5～7日1次。"},{"t":"p","x":"(2)刺络拔罐疗法患部阿是穴。"},{"t":"p","x":"消毒后用皮肤针或三棱针局部叩刺，刺络出血后进行拔罐。"},{"t":"p","x":"(3)穴位注射疗法选取患侧与皮损部位相对应的夹脊穴，用无菌注射器垂直穴位刺入，患者有酸胀感即为得气，注入药物。"},{"t":"p","x":"每点注射1～3mL，总量不超过20mL。"},{"t":"p","x":"(4)西医治疗"},{"t":"p","x":"抗病毒药物：早期足量应用(72小时内)，可用阿昔洛韦或泛昔洛韦口服；皮疹广泛严重者可静脉滴注阿昔洛韦，5～7日为1个疗程。"},{"t":"p","x":"止痛药物：可选普瑞巴林去痛片、布洛芬、吲哚美辛、扶他林、戴芬等，也可选择阿司匹林。急性疼痛可选用三环类抗抑郁药如阿米替林，亚急性或慢性疼痛可选用普瑞巴林。"},{"t":"p","x":"强效阿片类仅限短期剧痛使用，警惕成瘾风险。"}]}],"entries":["e0425","e0426","e0427","e0428","e0429"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.忌用热水烫洗患处。早期忌辛辣刺激食物，后期注意营养均衡。"},{"t":"p","x":"2.皮损局部保持清洁、干燥，忌用刺激性强的软膏涂敷，以防皮损范围扩大或加重病情。"}],"entries":["e0430"]}]},{"id":"d1004","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"疣","displayName":"疣","parentId":"","printedPage":136,"pdfPage":151,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"疣是一种发生于皮肤浅表的良性赘生物。因其皮损形态及发病部位不同而名称各异。"},{"t":"p","x":"发于手背、手指、头皮等处者，称千日疮、疣目、枯筋箭或痪子；丘疹扁平，肤色或褐色，发于颜面、手背、前臂等处者，称扁猴；"},{"t":"p","x":"丘疹呈脐凹、蜡样光泽的，发于胸背部的赘疣，称鼠乳；丘疹呈角化性，发于足跖部者，称跖疣；"},{"t":"p","x":"皮疹为单个丝状突起，发于颈周围及眼险部位者，称丝状疣或线痪。疣之病名最早见于《五十二病方》，曰：“即燔其末，以久(灸)尤(疣)末，热，即拔尤(疣)去。"},{"t":"p","x":"本病西医学亦称疣，一般分为寻常疣、扁平疣、传染性软疣、掌跖疣和丝状疣等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由风热毒邪搏于肌肤而生；或怒动肝火，肝旺血燥，筋气不荣，肌肤不润所致。其中跖疣多由局部气血凝滞而成，外伤、摩擦常为其诱因。"},{"t":"p","x":"正如《外科正宗·杂疮毒门》说：“枯筋箭乃忧郁伤肝，肝无荣养，以致筋气外发。”西医学认为，疣是由人类乳头瘤病毒(HPV)感染引起的表皮良性赘生物。"}],"entries":["e0431","e0432"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"疣目：相当于西医学的寻常疣。多发于儿童及青年。"},{"t":"p","x":"最初为一个针头大至绿豆大的疣状赘生物，呈半球形或多角形，突出表面，色灰白或污黄，表面蓬松枯槁，状如花蕊，粗糙而坚硬。以后体积可渐次增大，发展成乳头状赘生物，此为原发性损害，称母痪。"},{"t":"p","x":"此后由于自身接种，数目增多，一般为两三个，多则十余个至数十个不等，有时可呈群集状。好发于手背、手指，也可见于头面部。"},{"t":"p","x":"病程呈慢性，有自然消退者。一般无自觉症状，常因搔抓、碰撞、摩擦破伤而易出血。"},{"t":"p","x":"扁猴：相当于西医学的扁平疣。多发于青年男女，故又称青年扁平疣。"},{"t":"p","x":"皮损为表面光滑的扁平丘疹，针头、米粒到黄豆大小，呈淡红色、褐色或正常皮肤颜色。数目很多，散在分布，或簇集成群，有的互相融合，常因搔抓沿表皮剥蚀处发生而形成一串新的损害。"},{"t":"p","x":"好发于颜面部和手背。一般无自觉症状，偶有瘙痒感，有时可自行消退，但也可复发。"},{"t":"p","x":"鼠乳：相当于西医学的传染性软疣。多见于儿童。"},{"t":"p","x":"皮损为半球形丘疹，米粒到黄豆、豌豆大小。中央有脐凹，表面有蜡样光泽，挑破顶端可挤压出白色乳酪样物质。"},{"t":"p","x":"数目不定，数个到数十个不等，呈散在性或簇集性分布，但不相互融合。好发于躯干和面部。"},{"t":"p","x":"有轻度传染性，愈后不留瘢痕，可自行消失。跖疣：相当于西医学的掌跖疣。"},{"t":"p","x":"发生在手掌、足底或指(趾)间。皮损为角化性丘疹，中央稍凹，外周有稍带黄色高起的角质环，除去表面角质后，或见疏松的白色乳头状角质物，挑破后易出血，数目多时可融合成片。"},{"t":"p","x":"可有压痛。常在外伤部位发生，足部多汗者易生本病。"},{"t":"p","x":"丝状疣：中年妇女较多见，多生于颈项或眼睑部位。皮损为单个细软的丝状突起，呈褐色或淡红色，可自行脱落，不久又可长出新的皮损。"},{"t":"p","x":"一般无自觉症状。"},{"t":"p","x":"(2)辅助检查血常规、活检组织标本固定后染色镜检等有助于诊断，不同类型的疣组织病理学表现有差异，但均有颗粒层、棘层上部细胞空泡化和电镜下核内病毒颗粒。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-3、表10-4)"},{"t":"table","img":"img/tab/t1003.jpg","cap":"表10-3扁瘊与扁平苔藓的鉴别"},{"t":"table","img":"img/tab/t1004.jpg","cap":"表10-4跖疣与鸡眼、胼胝的鉴别"}],"entries":["e0433"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热解毒散结为主要治法。扁平疣、疣目宜内外合治，其余疣多可单纯采用外治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"h","lv":3,"x":"(1)疣目"},{"t":"syn","sid":"s100401","name":"风热血燥证","clinic":"疣目结节如豆，坚硬粗糙，大小不一，高出皮肤，色黄或红；舌红，苔薄，脉弦数","treat":"清热解毒，养血活血","formula":"治疾方加减。疣体坚硬者，加丹参、乌梅；压痛明显者，加磁石、石决明","formulaNames":["治疾方"]},{"t":"syn","sid":"s100402","name":"湿热血瘀证","clinic":"疣目结节疏松，色灰或褐，大小不一，高出皮肤；舌暗红，苔薄，脉细","treat":"清化湿热，活血化瘀","formula":"马齿苋合剂加减。湿热较重者，加薏苡仁、苍术。(2)扁疾","formulaNames":["马齿苋合剂"]},{"t":"syn","sid":"s100403","name":"风热蕴结证","clinic":"皮疹淡红，数目较多，或微痒，或不痒，病程短；伴口干不欲饮；舌红，苔薄白或薄黄，脉浮数或弦","treat":"疏风清热，解毒散结","formula":"马齿苋合剂加减。皮疹痒者，加僵蚕、白芷","formulaNames":["马齿苋合剂"]},{"t":"syn","sid":"s100404","name":"热瘀互结证","clinic":"病程较长，皮疹较硬，大小不一，其色黄褐或暗红，不痒不痛；舌红或暗红，苔薄白，脉沉弦","treat":"活血化瘀，清热散结","formula":"桃红四物汤加减。皮疹日久不消者，加三棱、莪术；肌肤甲错者，加阿胶、鹿角胶。疣目、扁瘊皮损少者及鼠乳、掌跖疣、丝状疣一般不需内服治疗","formulaNames":["桃红四物汤"]},{"t":"p","x":"2.外治疗法各种疣均可选用木贼草、板蓝根、马齿苋、香附、苦参、白鲜皮、薏苡仁等中药，煎汤趁热洗涤患处，每天2～3次，持续治疗可使部分皮疹脱落。"},{"t":"p","x":"(1)疣目"},{"t":"p","x":"推疣法：用于治疗头大蒂小，明显高出皮面的疣。在疣的根部用棉花棒与皮肤平行或呈30°角向前推进，用力不宜猛。"},{"t":"p","x":"有的疣体仅用此法即可推除，推除后创面压迫止血；或掺上桃花散少许，并用纱布盖贴，胶布固定。"},{"t":"p","x":"鸦胆子敷贴法：先用热水浸洗患部，用刀刮去表面的角质层，然后将鸦胆子仁5粒捣烂敷贴，用玻璃纸及胶布固定，3天换药1次。"},{"t":"p","x":"荸荠或菱蒂摩擦法：荸荠削去皮，用白色果肉摩擦疣体，每天3～4次，每次摩擦至疣体角质层软化、脱掉、微有痛感及点状出血为止，一般数天可愈。或取菱蒂长约3cm，洗去污垢，用切面在患部不断涂擦、每次2～3分钟，每天6～8次。"},{"t":"p","x":"(2)扁疾"},{"t":"p","x":"擦洗法：用内服方的第二煎汁外洗，以海螵蛸蘸药汁轻轻擦洗疣体，使之微红为度，每天2～3次。鸦胆子涂法：用鸦胆子仁油外涂患处，每天1次。"},{"t":"p","x":"用于治疗散在扁瘊，防止正常皮肤受损。"},{"t":"p","x":"(3)鼠乳"},{"t":"p","x":"挑刺法：用一次性注射器针头挑破患处，挤尽白色乳酪样物，再用碘酒或75%酒精点患处，若损害较多应分批治疗，并要对挤出的软疣小体进行严格消杀处理，避免皮肤接触。"},{"t":"p","x":"刮疣法：先局部消毒后用刮匙刮去疣体，部分大的疣体刮除后会有创面渗血，用棉棒压迫止血即可，亦可在创面上撒涂珍珠粉。"},{"t":"p","x":"(4)跖疣"},{"t":"p","x":"外敷法：用千金散局部外敷，亦可用乌梅肉(将乌梅用盐水浸泡1天，混为泥状)每次少许敷贴患处。"},{"t":"p","x":"手术疗法：常规消毒，局麻下先以刀尖在疣与正常组织交界处修割，然后用止血钳钳住疣体中央，向外拉出，可以见到一个疏松的软蕊，但软蕊周围不易挖净而易复发，故修割后可敷腐蚀药，如千金散或鸡眼膏。"},{"t":"p","x":"敷药时间不宜过长，一般5～7天即可，否则腐蚀过深会影响愈合。"},{"t":"p","x":"(5)丝状疣采用结扎法，可用细丝线或头发结扎疣的根底部，数日后即可自行脱落。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针灸疗法"},{"t":"p","x":"艾灸疗法：疣目少者可用艾炷灸疣体，每日1次，每次3壮，至脱落为止。针刺疗法：适用于疣目、跖疣。"},{"t":"p","x":"用针尖从疣顶部刺入并达到基底部，四周再用针刺以加强刺激，针后挤出少许血液，有效者3～4天可萎缩，逐渐脱落。火针疗法：适用于疣目、扁猴、跖疣、丝状疣。"},{"t":"p","x":"(2)物理疗法根据不同适应证，可采取冷冻、微波、电灼、激光等物理疗法。"},{"t":"p","x":"(3)西医治疗外用干扰素、维A酸霜、咪喹莫特乳膏等；"},{"t":"p","x":"皮损泛发者可使用阿昔洛韦等核苷类抗病毒药，或使用胸腺肽、卡介菌多糖核酸等免疫调节剂。"}]}],"entries":["e0434","e0435","e0436","e0437","e0438","e0439"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.扁疾忌搔抓，以防抓破后皮损加重。2.疣目应避免摩擦或挤压，以防出血。"},{"t":"p","x":"生于甲下者疼痛异常，宜早治。3.跖疣应避免挤压。"},{"t":"p","x":"4.鼠乳应防抓破后自身接种，并应避免继发感染。"}],"entries":["e0440"]}]},{"id":"d1005","kind":"attach","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"尖锐湿疣","displayName":"疣·尖锐湿疣","parentId":"d1004","printedPage":139,"pdfPage":154,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"尖锐湿疣是由人类乳头瘤病毒所引起的一种病毒性赘生物，又称生殖器疣、性病疣，属于中医学“瘙疾”的范畴。本病主要因性滥交或房事不洁，感受秽浊之毒，毒邪蕴聚，酿生湿热，湿热下注皮肤黏膜而产生赘生物。"},{"t":"p","x":"西医学认为，本病病原体为人类乳头瘤病毒(HPV)的6、11、16和18型，主要经性接触传播、少数患者由污染的日用物品间接传播。"},{"t":"p","x":"皮损初起为柔软淡红色小丘疹，逐渐增大增多，表面凹凸不平，湿润柔软呈乳头状，菜花状或鸡冠状，低温干燥的部位皮损呈扁平疣状。"},{"t":"p","x":"男性好发于龟头、冠状沟、包皮内侧、包皮系带、尿道口、阴茎体及阴囊，女性好发于大小阴唇、阴道口、会阴、阴道、宫颈及阴阜，两性均可累及肛周、直肠及腹股沟等部位。"},{"t":"p","x":"本病有与尖锐湿疣患者不洁性交或生活接触史，潜伏期1～8个月，平均3个月。常无明显自觉症状，可有轻微瘙痒、白带增多有臭味等表现。"},{"t":"p","x":"与生殖器癌发生的关系密切。醋酸白试验阳性，疣体组织病理学检查有特异性。"},{"t":"p","x":"本病应与生殖器鳞状细胞癌、扁平湿疣、生殖器鲍温样丘疹病、假性湿疣、阴茎珍珠状丘疹等鉴别。本病的治疗原则为清热解毒，燥湿除疣。"},{"t":"p","x":"临床常以中西医结合内外同治。外治法用清热解毒药煎水先熏后洗或用五妙水仙膏点涂疣体、鸦胆子仁捣烂涂敷。"},{"t":"p","x":"内治湿毒下注证宜利湿化浊、清热解毒，方用萆薢化毒汤加减；火毒炽盛证宜清火解毒、化浊利湿，方用黄连解毒汤加减。"},{"t":"p","x":"西医治疗主要包括局部用药、抗病毒治疗、提高机体免疫力，以及光动力、激光、电灼、冷冻、手术疗法等。同时积极治疗性伴侣，避免交叉感染。"}],"entries":["e0441"]}]},{"id":"d1006","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"癣","displayName":"癣","parentId":"","printedPage":140,"pdfPage":155,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"癣是发生在表皮、毛发、指(趾)甲的浅部真菌性皮肤病。具有传染性、长期性和广泛性的特征，一直是皮肤病防治工作的重点。"},{"t":"p","x":"本病发生部位不同，名称各异。临床常见的癣病有发于头部的白秃疮、肥疮，发于手部的鹅掌风，发于足部的脚湿气，发于面、颈、躯干、四肢的圆癣、紫白癜风等。"},{"t":"p","x":"本节只讨论浅在的常见皮肤真菌病，如头癣、手足癣、体癣等。本节只讨论浅在的常见皮肤真菌病，相当于西医学的头癣、手足癣、体癣等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由生活起居不慎，感染真菌，复因风、湿、热邪外袭，郁于腠理，淫于皮肤所致。病发于头皮、毛发，则发为白秃疮、肥疮；"},{"t":"p","x":"病发于趾丫，则发为脚湿气；发于手掌部，则为鹅掌风；"},{"t":"p","x":"发于体表、股阴间，则为紫白癜风、圆癣、阴癣等。如表现为发热起疹，瘙痒脱屑者，多为风热盛所致；"},{"t":"p","x":"若见渗流滋水，瘙痒结痂者，多为湿热盛引起；若见皮肤肥厚、燥裂、瘙痒者，多由郁热化燥，气血不和，肤失营养所致。"}],"entries":["e0442","e0443"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"1)白秃疮相当于西医学的白癣。"},{"t":"p","x":"本病是头癣的一种，多见于学龄儿童，男性多于女性。皮损特征：在头皮有圆形或不规则覆盖灰白鳞屑的斑片。"},{"t":"p","x":"病损区毛发干枯无泽，常在距头皮0.2～0.4cm处折断而呈参差不齐。"},{"t":"p","x":"头发易于拔落且不疼痛，病发根部包绕有白色鳞屑形成的菌鞘。自觉瘙痒。"},{"t":"p","x":"发病部位以头顶、枕部居多，但发缘处一般不被累及。青春期可自愈，秃发也能再生、不遗留瘢痕。"},{"t":"p","x":"2)肥疮相当于西医学的黄癣。"},{"t":"p","x":"俗称“黄癞”，是头癣的一种，多见于农村，好发于儿童。皮损特征：有黄癣痂堆积，癣痂呈蜡黄色，肥厚，富黏性，边缘翘起，中心微凹，上有毛发贯穿、质脆易粉碎，有特殊的鼠尿臭。"},{"t":"p","x":"除去黄癣痂，其下为鲜红湿润的糜烂面。病变区头发干燥无光泽。"},{"t":"p","x":"久之，毛囊被破坏而成永久性脱发。病变痊愈后，遗留萎缩性瘢痕。"},{"t":"p","x":"本病多由儿童期染病，延至成年始趋向愈，甚至终生不愈。少数糜烂化脓，常致附近出现臖核肿痛。"},{"t":"p","x":"3)鹅掌风相当于西医学的手癣。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》记载：此证“初起紫白斑点，叠起白皮、坚硬且厚，干枯燥裂，延及遍手”。本病以成年人多见，男女老幼均可染病。"},{"t":"p","x":"多数为单侧发病、也可波及双手。夏天起水疱病情加重，冬天则枯裂疼痛明显。"},{"t":"p","x":"皮损特征：初起为掌心或指缝水疱，或掌部皮肤角化脱屑、水疱，水疱多透明如晶，散在或簇集，瘙痒难忍。水疱破后干涸，叠起白屑，中心向愈，四周继发疱疹，并可延及手背、腕部。"},{"t":"p","x":"若反复发作，可致手掌皮肤肥厚，枯槁干裂，疼痛，屈伸不利，宛如鹅掌。损害若侵及指甲，可使甲板被蛀蚀变形，甲板增厚或萎缩翘起，色灰白而成灰指甲(甲癣)。"},{"t":"p","x":"鹅掌风病程为慢性，反复发作。"},{"t":"p","x":"4)脚湿气相当于西医学的足癣。"},{"t":"p","x":"本病以脚丫糜烂瘙痒伴有特殊臭味而得名。若皮损处感染邪毒、足趾焮红肿痛，起疱糜烂渗液而臭者，称“臭田螺”“田螺疱”。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》记载：“田螺疱⋯⋯此证多生足掌，而手掌罕见⋯⋯初生形如豆粒，黄疱闷胀，硬疼不能着地。连生数疱、皮厚难于自破，传度三五成片湿烂；甚则足跗俱肿，寒热往来。"},{"t":"p","x":"我国南方地区气温高、潮湿，发病率高。多发于成年人，儿童少见。"},{"t":"p","x":"夏秋病重，多起水疱、糜烂；冬春病减，多干燥裂口。脚湿气主要发生在趾缝，也见于足底。"},{"t":"p","x":"皮损特征：皮下水疱，趾间浸渍糜烂、渗流滋水，以及角化过度、脱屑、瘙痒等。分为水疱型、糜烂型、脱屑型，但常以1～2种皮肤损害为主。"},{"t":"p","x":"水疱型：多发于足弓及趾的两侧，为成群或分散的深在性皮下水疱，瘙痒，疱壁厚，内容物清澈，不易破裂。数天后干燥脱屑，或融合成多房性水疱，撕去疱壁可显示蜂窝状基底及鲜红色糜烂面。"},{"t":"p","x":"糜烂型：发生于趾缝间，尤以第3、4趾间多见。表现为趾间潮湿，皮肤浸渍发白。"},{"t":"p","x":"如将白皮除去后，基底呈鲜红色。剧烈瘙痒，往往搓至皮烂疼痛、渗流血水方止。"},{"t":"p","x":"此型易并发感染。脱屑型：多发生于趾间、足跟两侧及足底。"},{"t":"p","x":"表现为角化过度、干燥、粗糙、脱屑、皲裂。常由水疱型发展而来，且老年患者居多。"},{"t":"p","x":"水疱型和糜烂型常因抓破而继发感染，致小腿丹毒、红丝疔或足丫化脓，局部红肿，趾间糜烂，渗流腥臭滋水，胯下臖核肿痛，并可出现形寒发热、头痛骨楚等全身症状。"},{"t":"p","x":"5)圆癣相当于西医学的体癣。"},{"t":"p","x":"本病因皮损多呈钱币状、圆形，故名圆癣，亦称铜钱癣。以青壮年男性多见，多发于夏季，好发于面部、颈部、躯干及四肢近端。"},{"t":"p","x":"发于股胯、外阴等处者，称阴癣(股癣)。圆癣初起为丘疹或水疱，逐渐形成边界清楚的钱币形红斑，其上覆盖细薄鳞屑。"},{"t":"p","x":"病灶中央皮疹消退，呈自愈倾向，但向四周蔓延，有丘疹、水疱、脓疱、结痂等损害。圆癣的皮损特征为环形或多环形、边界清楚、中心消退、外围扩张的斑块。"},{"t":"p","x":"斑块一般为钱币大或更大，多发时可相互融合形成连环形。若发于腰间，常沿扎裤带处的皮肤多汗潮湿处传播，形成带形损害。"},{"t":"p","x":"阴癣发于胯间与阴部相连的皱褶处，向下可蔓延到阴囊，向后至臀间沟，向上可蔓延至下腹部。由于患部多汗潮湿，易受摩擦，故瘙痒明显，发展较快，皮肤损害基本同圆癣。"},{"t":"p","x":"自觉瘙痒，搔抓日久皮肤可呈苔藓样变，病情多在夏季发作或扩大，入冬痊愈或减轻。"},{"t":"p","x":"6)紫白癜风相当于西医学的花斑癣，俗称汗斑。"},{"t":"p","x":"本病常发于多汗体质青年，可在家庭中互相传染。皮损好发于颈项、躯干，尤其是多汗部位及四肢近心端。"},{"t":"p","x":"为大小不一、边界清楚的圆形或不规则的无炎症性斑块，色淡褐、灰褐至深褐色，或轻度色素减退、或附少许糠秕状细鳞屑，常融合成片。有轻微痒感，常夏发冬愈，复发率高。"},{"t":"p","x":"(2)辅助检查 ①真菌直接镜检：将取得的病变部鳞屑或分泌物用氢氧化钾涂片镜检，该方法简单、快速，较易掌握。"},{"t":"p","x":"但镜检仅能确定菌丝和孢子的有无，阳性表示真菌存在，且一次阴性不能完全排除真菌。"},{"t":"p","x":"②真菌培养：可将取得的病变部鳞屑或分泌物做鉴定菌种的培养。"},{"t":"p","x":"常用培养基为沙堡琼脂培养基，培养阳性后可转种到特殊培养基，根据形态、生化等特性进行菌种鉴定。深部真菌病须做病变组织的病理学检查。"},{"t":"p","x":"③伍德灯检查：可辅助本病诊断。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-5、表10-6)"},{"t":"table","img":"img/tab/t1005.jpg","cap":"表10-5鹅掌风、脚湿气脱屑型与掌跖角化病、手部湿疮的鉴别"},{"t":"table","img":"img/tab/t1006.jpg","cap":"表10-6紫白癫风与白驳风、风热疮的鉴别"}],"entries":["e0444"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以杀虫止痒为主要治法，必须彻底治疗。癣病以外治为主；"},{"t":"p","x":"若皮损广泛，自觉症状较重，或抓破染毒者，则以内治、外治相结合为宜。抗真菌西药治疗有一定优势，可中西药合用。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100601","name":"风湿毒聚证","clinic":"多见于肥疮、鹅掌风、脚湿气，症见皮损泛发，蔓延浸淫，或大部分头皮毛发受累，黄痂堆积，毛发脱而头秃；或手如鹅掌，皮肤粗糙，皮下水疱；或趾丫糜烂、浸渍剧痒；苔薄白，脉濡","treat":"祛风除湿，杀虫止痒","formula":"消风散加地肤子、白鲜皮，或苦参汤加白鲜皮、威灵仙","formulaNames":["消风散","苦参汤"]},{"t":"syn","sid":"s100602","name":"湿热下注证","clinic":"多见于脚湿气伴抓破染毒，症见足丫糜烂，渗流臭水或化脓，肿连足背，或见红丝上窜，胯下臖核肿痛；甚或形寒高热；舌红，苔黄腻，脉滑数","treat":"清热化湿，解毒消肿","formula":"湿重于热者用萆薢渗湿汤，湿热兼瘀者用五神汤，湿热并重者用龙胆泻肝汤","formulaNames":["萆薢渗湿汤","五神汤","龙胆泻肝汤"]},{"t":"p","x":"舌红，苔黄腻，脉滑数。治法：清热化湿，解毒消肿。"},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)白秃疮、肥疮采用拔发疗法。"},{"t":"p","x":"其方法为剪发后每天以0.5%明矾水或热肥皂水洗头，然后在病灶处敷药(敷药宜厚)，可用5%硫黄软膏或雄黄膏，用薄膜盖上，包扎或戴帽固定。每天如上法换药1次。"},{"t":"p","x":"敷药1周病发比较松动时，即用镊子将病发连根拔除(争取在3天内拔完)。拔发后继续薄涂原用药膏，每天1次，连续2～3周。"},{"t":"p","x":"(2)鹅掌风、脚湿气"},{"t":"p","x":"水疱型：可选用1号癣药水、2号癣药水、复方土槿皮酊外搽，或二矾汤熏洗，或鹅掌风浸泡方或藿黄浸剂(藿香30g，黄精、大黄、皂矾各12g，醋1kg)浸泡。"},{"t":"p","x":"糜烂型：可选用1:1500高锰酸钾溶液、3%硼酸溶液、二矾汤或半边莲60g煎汤待温，浸泡5分钟、次以皮脂膏或雄黄膏外搽。脱屑型：可选用以上软膏外搽，浸泡剂浸泡。"},{"t":"p","x":"如角化增厚较剧，可选用10%水杨酸软膏厚涂，外用油纸包扎，每晚1次，使其角质剥脱；然后再用抗真菌药物，也可用市售治癣中成药。"},{"t":"p","x":"(3)灰指甲每日以小刀刮除病甲变脆部分，然后用棉花蘸2号癣药水或30%冰醋酸浸涂。"},{"t":"p","x":"或用鹅掌风浸泡方浸泡，白凤仙花捣烂敷病甲上，或采用拔甲方法。"},{"t":"p","x":"(4)圆癣可选用1号癣药水、2号癣药水、复方土槿皮酊等外搽。"},{"t":"p","x":"阴癣由于患部皮肤薄嫩，不宜选用刺激性强的外用药物。若皮损有糜烂痒痛者，宜选用青黛膏外涂。"},{"t":"p","x":"(5)紫白癜风用密陀僧散，以茄子片蘸药涂搽患处，或用2号癣药水，或1%土槿皮酊外搽，每天2～3次。"},{"t":"p","x":"治愈后继续用药1～2周，以防复发。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)头癣内服药一般单独使用，可选伊曲康唑、特比萘芬，疗程6周。"},{"t":"p","x":"肝功能不良者应慎用药物。"},{"t":"p","x":"(2)体癣和股癣皮损较广泛者，内服药可选伊曲康唑等。"},{"t":"p","x":"外用药物可选水杨酸苯甲酸酊、特比萘芬软膏等。每日1～2次，疗程2周以上。"},{"t":"p","x":"(3)手癣和足癣内服药可选伊曲康唑等。"},{"t":"p","x":"既往有肝病史者应慎用。外用咪唑类溶液或霜剂。"},{"t":"p","x":"皮肤干燥甚至皲裂者用软膏剂，局部封包疗效更好。"},{"t":"p","x":"(4)花斑癣皮损面积广泛者可内服伊曲康唑至真菌培养阴性为止，以后改为每月服1次以防止复发。"},{"t":"p","x":"外用可选5%～10%硫黄软膏等，连用2周。"}]}],"entries":["e0445","e0446","e0447","e0448","e0449"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.对已有患者要早发现、早治疗，并坚持治疗以巩固疗效。对患癣病的动物也要及时处理，以消除传染源。"},{"t":"p","x":"2.要针对不同癣病的传染途径做好消毒灭菌工作。白秃疮、肥疮患者要注意理发工具及患者梳、帽、枕巾等的灭菌；"},{"t":"p","x":"脚湿气患者要注意保持足部干燥，勿与他人共用洗脚盆、浴巾、鞋袜等，鞋袜宜干爽透风，并经常洗涤、暴晒；圆癣、阴癣、紫白癜风患者的内衣、裤、床单等要常洗换、暴晒，并宜煮沸消毒。"}],"entries":["e0450"]}]},{"id":"d1007","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"虫咬皮炎","displayName":"虫咬皮炎","parentId":"","printedPage":143,"pdfPage":158,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"虫咬皮炎是被致病虫类叮咬，接触其毒液或虫体的毒毛而引起的一种皮炎。较常见的致病害虫有蝶、螨、隐翅虫、刺毛虫、跳蚤、虱类、臭虫、飞蛾、蜂等。"},{"t":"p","x":"其临床特点是皮肤上出现红斑、风团、丘疹、水疱、瘀点，呈散在性分布。多见于昆虫孳生的夏秋季节，好发于暴露部位。"},{"t":"p","x":"一般无全身不适，严重者可有畏寒发热、头痛恶心、胸闷、呼吸困难等全身中毒症状。虫咬皮炎为西医学病名，属中医学“恶虫叮咬”“射工伤”“蚝虫鳌”“蜂叮疮”等的范畴。"},{"t":"p","x":"《外科正宗·恶虫叮咬》曰：“恶虫，乃各禀阴阳毒种而生，且如蜈蚣用钳，蝎蜂用尾，蛇以舌，见之者勿触其恶，自不被螫、苟有所伤，各寻类而推治。”"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"人体皮肤被昆虫叮咬，接触其毒液、或接触虫体的有毒毛刺，邪毒侵入肌肤，与气血相搏；或禀赋不耐、过敏而成本病。"},{"t":"p","x":"西医学认为，虫咬皮炎是因虫类叮咬，昆虫将口器刺人皮肤吸血，或将毒汁注入体内，或接触其毒液及虫体的毒毛所致。"}],"entries":["e0451","e0452"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于昆虫孳生的夏秋季节，好发于暴露部位。"},{"t":"p","x":"尤以小儿及青少年多见。皮损以丘疹、风团或瘀点为多见，亦可出现红斑、丘疱疹或水疱，皮损中央常可见有刺吮点，散在分布或数个成群。"},{"t":"p","x":"由于搔抓而水疱破裂，引起糜烂，有的可继发感染，或局部臖核肿大。自觉奇痒，灼热红肿或疼痛。"},{"t":"p","x":"一般无全身不适，严重者有畏寒发热、头痛、恶心、胸闷、呼吸困难等全身中毒症状。因虫类不同，其皮损表现也有差异："},{"t":"p","x":"蝶虫皮炎：叮咬后局部出现瘀点和黄豆大小的风团，奇痒，个别发生水疱，甚至引起丘疹性荨麻疹。螨虫皮炎：粟米至黄豆大小的红色丘疱疹，或为紫红色的肿块或风团，有时可见到虫咬的痕迹，或因搔抓而有抓痕和血痂。"},{"t":"p","x":"隐翅虫皮炎：皮损多呈线状或条索状红肿，上有密集的丘疹、水疱或脓疱。桑毛虫皮炎：皮损为绿豆至黄豆大小的红色斑丘疹、丘疱疹或风团，剧痒。"},{"t":"p","x":"松毛虫皮炎：皮损为斑疹、风团，间有丘疹、水疱、脓疱、皮下结节等。不少患者伴有关节红肿疼痛，甚至化脓，但脓液培养无细菌生长。"},{"t":"p","x":"蜂螫皮炎：伤处有烧灼感，或显著的痛痒感，局部很快出现红肿。如被群蜂同时螫伤，可发生大面积的肿胀。"},{"t":"p","x":"可伴有头晕、恶心、呕吐等症状，严重者可晕厥。"},{"t":"p","x":"(2)辅助检查对疑似桑毛虫、松毛虫皮炎患者，可用解剖显微镜直接检查，或以透明胶纸粘贴皮疹后用低倍显微镜检查，找到毒毛则可予以确诊。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-7)"},{"t":"table","img":"img/tab/t1007.jpg","cap":"表10-7虫咬皮炎与瘾疹、湿疮的鉴别"}],"entries":["e0453"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以预防为主，发病后以外治为主，轻者外治可愈，重者内、外合治。治法主要为清热解毒止痒。"},{"t":"p","x":"外治是关键。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100701","name":"热毒蕴结证","clinic":"皮疹较多，成片红肿，水疱较大，瘀斑明显，皮疹附近臖核肿大；伴畏寒，发热，头痛，恶心，胸闷；舌红，苔黄，脉数","treat":"清热解毒，消肿止痒","formula":"五味消毒饮合黄连解毒汤加减。瘙痒剧烈者，加地肤子、白鲜皮、苦参","formulaNames":["五味消毒饮","黄连解毒汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起红斑、丘疹、风团等皮损，用1%薄荷三黄洗剂(即三黄洗剂加薄荷脑1g)外搽。"},{"t":"p","x":"(2)生于毛发处者，剃毛后外搽50%百部酊杀虫止痒。"},{"t":"p","x":"(3)感染邪毒，水疱破后糜烂红肿者，可用马齿苋煎汤湿敷，再用青黛散油剂涂搽；"},{"t":"p","x":"或外用颠倒散洗剂外搽。"},{"t":"p","x":"(4)松毛虫、桑毛虫皮炎可用胶布粘去毛刺，外涂5%碘酒。"},{"t":"p","x":"(5)蜂螫皮炎应先拔去毒刺，火罐吸出毒汁，消毒后用紫金锭磨水外涂。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)外涂1%～2%薄荷洗剂或炉甘石洗剂或5%樟脑乙醇以止痒。"},{"t":"p","x":"隐翅虫皮炎外用肥皂水或1:5000～1:8000高锰酸钾溶液湿敷，再涂1:10聚维酮碘溶液。虱病可用扑灭司林乳膏。"},{"t":"p","x":"(2)内服可选抗组胺药物。"}]}],"entries":["e0454","e0455","e0456","e0457"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持环境清洁卫生，消灭害虫。2.衣服、被褥应勤洗勤晒，防虫藏身。"},{"t":"p","x":"3.注意防护，远离昆虫分布区，户外活动时涂防虫叮咬药物。4.发病期间忌海鲜鱼腥发物，多饮水，多吃蔬菜、水果，保持大便通畅。"}],"entries":["e0458"]}]},{"id":"d1008","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"疥疮","displayName":"疥疮","parentId":"","printedPage":145,"pdfPage":160,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"疥疮是由疥虫(人型疥螨)寄生在人体皮肤所引起的一种接触传染性皮肤病。其临床特点是夜间剧痒，在皮损处有灰白色、浅黑色或普通皮色的隧道，可找到疥虫。"},{"t":"p","x":"疥疮在中医文献中又称“虫疥”“癞疥”“干疤疥”；若继发感染，称为“脓窝疥”。《诸病源候论·疥候》曰：“疥疮，多生手足指间，染渐生至于身体，痒，有脓汁⋯⋯其疮里有细虫，甚难见。"},{"t":"p","x":"小儿多因乳养之人病疥，而染着小儿也。”本病西医学亦称疥疮。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"疥疮是由疥虫通过密切接触传染所致。其传染性很强，在家庭或集体宿舍中可相互传播、可因使用患者用过而未经消毒的衣服、被席、用具等传染而得。"},{"t":"p","x":"本病发生后，患者常伴有湿热之邪郁于肌肤的症状。西医学的认识与中医学基本相同，疥螨俗称疥虫，种类很多，主要有人型疥螨和动物疥螨。"},{"t":"p","x":"西医学认为，疥疮由人型疥螨引起。疥螨寄生在人体表皮角质层内，从卵到成虫需15天左右，疥螨离开人体后可存活2～3天，可通过气味和体温寻找新的宿主。"},{"t":"p","x":"动物疥螨亦可感染人，但因人的皮肤不是其合适的栖息地，人感染后症状较轻，有自限性。"}],"entries":["e0459","e0460"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病传染性极强，冬春季多见。"},{"t":"p","x":"易在集体生活的人群中和家庭内流行。典型临床表现：皮损好发于皮肤薄嫩和皱褶处，如手指侧、指缝、腕肘关节屈侧、腋窝前缘、女性乳房下、下腹、外阴、腹股沟、大腿内侧等处。"},{"t":"p","x":"头面部和头皮、掌跖一般不易累及，但婴幼儿例外。皮疹主要为红色小丘疹、丘疱疹、小水疱、隧道、结节和结痂。"},{"t":"p","x":"水疱常见于指缝；结节常见于阴囊、下腹等处；"},{"t":"p","x":"隧道为疥疮的特异性皮疹，长约0.5mm，弯曲、微隆起，呈淡灰色或皮色，在隧道末端有1个针头大的灰白色或微红的小点，为疥虫隐藏处。如不及时治疗，迁延日久则全身遍布抓痕、结痂、黑色斑点，甚至脓疱。"},{"t":"p","x":"久病男性患者阴茎、阴囊有结节，女性皮损主要在下腹、会阴部。患者常有奇痒，遇热或夜间尤甚，常影响睡眠。"},{"t":"p","x":"特殊临床类型：“挪威疥”是一种严重的疥疮，多发生于身体虚弱或免疫功能低下的患者。其特点是皮疹广泛分布、皮肤干燥、结痂、脱屑，感染严重，局部淋巴结肿大，往往有特殊臭味。"},{"t":"p","x":"(2)辅助检查刮取皮损部位，阳性标本可找到疥螨或椭圆形、淡黄色的薄壳虫卵。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-8)"},{"t":"table","img":"img/tab/t1008.jpg","cap":"表10-8疥疮与丘疹性荨麻疹、虱病的鉴别"}],"entries":["e0461"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以杀虫止痒为主要治法。必须隔离治疗，以外治为主。"},{"t":"p","x":"一般不需内服药，若抓破染毒则须内外合治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100801","name":"湿热蕴结证","clinic":"皮损以水疱为多，丘疱疹泛发，壁薄液多，破流脂水，浸淫糜烂，或脓疱多，或起红丝走窜，臖核肿痛；舌红，苔黄腻，脉滑数","treat":"清热化湿，解毒杀虫","formula":"黄连解毒汤合三妙丸加减","formulaNames":["黄连解毒汤","三妙丸"]},{"t":"p","x":"舌红，苔黄腻，脉滑数。治法：清热化湿，解毒杀虫。"},{"t":"p","x":"2.外治疗法疥疮以外治杀虫为主。硫黄治疗疥疮，古今皆为常用特效药物。"},{"t":"p","x":"临床多与水银、雄黄等杀虫药配用，以油调敷，或与大枫子、蓖麻仁等有油脂之果仁捣膏用之。"},{"t":"p","x":"目前临床常用浓度5%～20%的硫黄软膏，小儿用5%～10%、成人用10%～15%的浓度，若患病时间长，可用20%的浓度，但浓度不宜过高，否则易产生皮炎；亦可用含水银的制剂一扫光或雄黄软膏等外搽。"},{"t":"p","x":"具体的涂药方法：先以花椒9g和地肤子30g煎汤外洗，或用温水肥皂洗涤全身后再搽药。一般先搽好发部位、再涂全身。"},{"t":"p","x":"每天早、晚各涂1次，连续3天、第4天洗澡，换洗席被，此为1个疗程。一般治1～2个疗程，停药后观察1周左右，如无新皮损出现，即为痊愈。"},{"t":"p","x":"因为疥虫卵在产生后1周左右才能发育为成虫，故治疗后观察以1周为妥。3.其他疗法目前临床常用优力肤乳剂、疥宁霜等外搽，每日1次。"}],"entries":["e0462","e0463"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.接触疥疮患者后，用肥皂水洗手。患者所用衣服、毛巾等均须煮沸消毒，或在阳光下充分暴晒、以便杀灭疥虫及虫卵。"},{"t":"p","x":"2.彻底消灭传染源，注意消毒隔离。家庭和集体宿舍中的患者应分居，并积极治疗，以杜绝传染源。"}],"entries":["e0464"]}]},{"id":"d1009","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"日晒疮","displayName":"日晒疮","parentId":"","printedPage":147,"pdfPage":162,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"日晒疮是皮肤受日光暴晒而引起的炎症性皮肤病。其临床特点是皮肤暴晒部位焮红漫肿，甚至燎浆起疱，灼热痒痛。"},{"t":"p","x":"多发于盛夏及春末夏初。明代《外科启玄·日晒疮》记载：“三伏炎天，勤苦之人，劳于工作，不惜身命，受酷日晒曝，先疼后破而成疮者，非血气所生也。"},{"t":"p","x":"本病相当于西医学的日光性皮炎，又称日晒伤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.禀赋不耐，腠理不密，不能耐受日光暴晒，热毒侵袭，灼伤皮肤，而致局部炊红漫肿。2.湿热内蕴，又反复日晒，盛夏暑湿与热毒之邪侵袭，与内湿相搏，壅滞于肌肤，而出现红斑、水疱、糜烂等病变。"},{"t":"p","x":"西医学认为，本病是因皮肤受到了超过耐受量的日光照射，引起表皮、真皮的炎症反应，发病情况视日光强度、暴晒时间及个体皮肤敏感性而异。"}],"entries":["e0465","e0466"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多在照射日光后数小时至十余小时内发病。"},{"t":"p","x":"好发于皮肤暴露部位，如颜面、颈项、前臂、手背。皮损表现为弥漫性红斑、水肿，伴灼热、疼痛感，重者可出现水疱，甚至糜烂。"},{"t":"p","x":"部分患者呈多形性损害，表现为丘疹、丘疱疹、水肿性红斑等。反复发作或长期日晒者，可出现慢性损害，如皮肤增厚、角化、萎缩、毛细血管扩张、色素沉着或减退。"},{"t":"p","x":"局部灼热、瘙痒，甚至灼痛。一般无明显全身症状，若皮损面积大时，可伴有发热、畏寒、头痛、乏力、恶心等。"},{"t":"p","x":"皮损轻者一般在2～3天后开始消退，红斑渐变为暗红或红褐色，脱屑，消退后留色素沉着。"},{"t":"h","lv":3,"x":"(2)辅助检查必要时可行光斑试验和紫外线红斑反应试验等检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-9)"},{"t":"table","img":"img/tab/t1009.jpg","cap":"表10-9日晒疮与漆疮、癞皮病的鉴别"}],"entries":["e0467"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s100901","name":"热毒侵袭证","clinic":"多见于夏季，暴露部位皮肤日晒后弥漫性潮红、肿胀，或见红色丘疹集簇，甚者可发生水疱、大疱，局部有刺痛、灼热、瘙痒感；可伴有发热、头痛、口渴、大便干结、小便短赤等；舌质红或红绛、苔黄，脉数","treat":"清热凉血解毒","formula":"清营汤加减。身热、口渴、汗出者，加白虎汤","formulaNames":["清营汤"]},{"t":"syn","sid":"s100902","name":"暑湿热毒证","clinic":"日晒部位皮肤红肿，红色丘疹、小水疱、糜烂、渗液，瘙痒较著；可伴身热不扬，头胀痛，胸闷，纳呆，小便短赤；舌质红，苔白腻或黄腻，脉滑数或濡数","treat":"清暑利湿解毒","formula":"三石汤合清暑汤加减。皮损红肿明显者，加白茅根","formulaNames":["三石汤","清暑汤"]},{"t":"p","x":"皮损红肿明显者，加白茅根。2.外治疗法外搽以遮光、止痒、消炎为原则。"},{"t":"p","x":"(1)轻者先以凉水湿敷患处，再酌情选用炉甘石洗剂、氧化锌油等外涂。"},{"t":"p","x":"(2)糜烂、渗液较多，选用生石膏、生地榆、金银花、生甘草等，水煎，待凉后湿敷患处，每日2～3次。"},{"t":"p","x":"(3)脱皮痛痒明显者，选用湿润烧伤膏或青黛膏，外涂，每日2～3次。"}],"entries":["e0468","e0469","e0470"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.避免烈日过度暴晒，外出时注意防晒，如撑伞、穿浅色长袖衣衫、戴宽边帽子，涂全波段防晒剂。2.避免接触光感性物质，如化妆品中的香料、某些染料、沥青、荧光增白剂。"},{"t":"p","x":"某些药物如磺胺、四环素、阿司匹林等，泥螺，以及很多绿叶野菜、蔬菜含光敏物质，患者应忌食。"}],"entries":["e0471"]}]},{"id":"d1010","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"湿疮","displayName":"湿疮","parentId":"","printedPage":148,"pdfPage":163,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"湿疮是一种由多种内外因素引起的具有渗出倾向的炎症性皮肤病。"},{"t":"p","x":"因皮损总有湿烂、渗液、结痂而得名。其临床特点是皮损对称分布，多形性损害，剧烈瘙痒，有渗出倾向，反复发作，易成慢性等。"},{"t":"p","x":"根据病程可分为急性、亚急性、慢性三类。急性湿疮以丘疱疹为主，炎症明显，易渗出；"},{"t":"p","x":"亚急性湿疮红肿和渗出减轻，以丘疹、结痂、鳞屑为主；慢性湿疮以苔藓样变为主，易反复发作。"},{"t":"p","x":"本病可发生于任何年龄、性别和季节，以先天禀赋不耐者为多。根据皮损形态不同，名称各异。"},{"t":"p","x":"如浸淫全身、滋水较多者，称为浸淫疮；以丘疹为主者，称为血风疮或粟疮。根据发病部位的不同，其名称也不同。"},{"t":"p","x":"如发于耳部者，称为旋耳疮；发于手足部者，称为瘟疮；"},{"t":"p","x":"发于阴囊部者，称为肾囊风；发于脐部者，称为脐疮；"},{"t":"p","x":"发于肘、膝弯曲部者，称为四弯风；发于乳头者，称为乳头风。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》记载：“浸淫疮⋯⋯此证初生如疥，搔痒无时，蔓延不止，抓津黄水，浸淫成片，由心火、脾湿受风而成。"},{"t":"p","x":"该书中还指出：“血风疮⋯⋯此证由肝、脾二经湿热，外受风邪，袭于皮肤，郁于肺经，致遍身生疮，形如粟米，搔痒无度。抓破时，津脂水浸淫成片，令人烦躁、口渴、搔痒，日轻夜甚。"},{"t":"p","x":"本病相当于西医学的湿疹。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于禀赋不耐，饮食失节，或过食辛辣刺激荤腥动风之物，脾胃受损，失其健运，湿热内生，又兼外感风湿热邪，内外两邪相搏，浸淫肌肤；或素体脾虚，脾为湿困，水湿停滞，生化乏源；"},{"t":"p","x":"或因湿热蕴久，耗伤阴血，日久生风化燥，肌肤失养所致。急性者以湿热为主，亚急性者多与脾虚湿恋有关，慢性者则多与血虚风燥有关。"},{"t":"p","x":"发于小腿者则常由经脉弛缓、青筋暴露，气血运行不畅，湿热蕴阻，肤失濡养所致。"},{"t":"p","x":"西医学认为，湿疹的发病原因复杂，发病机制与各种外因(生活环境、外界刺激、食物、吸入物等)、内因(慢性感染病灶、神经精神因素、内分泌及代谢改变等)相互作用有关，某些患者可能由迟发型变态反应介导。"}],"entries":["e0472","e0473"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"1)急性湿疮相当于西医学的急性湿疹。"},{"t":"p","x":"起病较快，皮损常为对称性、原发性和多形性(常有红斑、潮红、丘疹、丘疱疹、水疱、脓疱、流滋、结痂并存)。可发于身体的任何部位，亦可泛发全身，但常发于头面、耳后、手足、阴囊、外阴、肛门等，多呈对称分布。"},{"t":"p","x":"病变常为片状或弥漫性，无明显边界。皮损为多数密集的粟粒大小的丘疹、丘疱疹，基底潮红，由于搔抓，丘疹、丘疱疹或水疱顶端抓破后流滋、糜烂及结痂，皮损中心较重，外周有散在丘疹、红斑、丘疱疹，故边界不清。"},{"t":"p","x":"如不转化为慢性，1～2个月可脱去痂皮而愈。自觉瘙痒剧烈，搔抓、肥皂热水烫洗、饮酒、食辛辣发物均可使皮损加重，瘙痒加剧，重者影响睡眠。"},{"t":"p","x":"搔抓染毒多致糜烂、渗液、化脓，形成脓疱，脓液渗出或结黄绿色或污褐色痂，并可发生臖核肿大等。"},{"t":"p","x":"2)亚急性湿疮相当于西医学的亚急性湿疹。"},{"t":"p","x":"常由急性湿疮未能及时治疗，或处理失当，病程迁延所致；也可初发即呈亚急性湿疮。红肿及渗出较急性湿疮减轻，以丘疹、结痂、鳞屑为主，仅有少量水疱及轻度糜烂。"},{"t":"p","x":"自觉剧烈瘙痒。"},{"t":"p","x":"3)慢性湿疮相当于西医学的慢性湿疹。"},{"t":"p","x":"常由急性和亚急性湿疮处理不当，长期不愈，或反复发作而成。部分患者一开始即表现为慢性湿疮的症状。"},{"t":"p","x":"皮损可发生于身体任何部位，常见于小腿、手足、肘窝、腘窝、外阴、肛门等处。表现为皮肤肥厚粗糙，触之较硬，色暗红或紫褐，皮纹显著或呈苔藓样变。"},{"t":"p","x":"皮损表面常附有鳞屑，伴抓痕、血痂、色素沉着，部分皮损可出现新的丘疹或水疱，抓破后有少量流滋，当急性发作时可有明显的渗出。发生于手足及关节部位者常易出现皲裂，而致皮损部疼痛，影响活动。"},{"t":"p","x":"患者自觉瘙痒，常呈阵发性，夜间或精神紧张、饮酒、食辛辣发物时瘙痒加剧。病程较长，反复发作，时轻时重。"},{"t":"p","x":"4)特定部位湿疮某些特定部位湿疮，临床表现有一定的特异性。"},{"t":"p","x":"耳部湿疮：又称旋耳疮。多发生在耳后皱襞处，也可见于耳轮上部及外耳道，皮损表现为红斑、流滋、结痂及皲裂，有时带脂溢性，常两侧对称。"},{"t":"p","x":"头部湿疮：多由染发剂、生发剂、洗发剂等刺激所引起。呈弥漫性，甚至累及整个头皮，可有脓性流滋，覆以或多或少的黄痂，痂多时可将头发黏结成团，或化脓染毒而发生臭味，甚至可使头发脱落。"},{"t":"p","x":"面部湿疮：常见于额部、眉部、耳前等处。皮损为淡色或微红的斑，其上有或多或少的鳞屑，常对称分布，自觉瘙痒。"},{"t":"p","x":"由于面部经常洗擦或使用化妆品刺激，病情易反复发作。乳房湿疮：主要见于女性，尤其是哺乳期女性。"},{"t":"p","x":"损害发生于乳头、乳晕及其周围、表现为潮湿、糜烂、流滋，上覆以鳞屑，或结黄色痂皮，反复发作可出现皲裂、疼痛，自觉瘙痒。"},{"t":"p","x":"脐部湿疮：皮损为位于脐窝的鲜红或暗红色斑片、或有糜烂、流滋、结痂，皮损边界清楚，很少累及脐周皮肤，常有臭味，自觉瘙痒，病程较长。手部湿疮：由于手是暴露部位，接触致病因素机会较多，故手部湿疮极为常见。"},{"t":"p","x":"好发于指背及指端掌面，可蔓延至手背和手腕部，亦可发生于掌侧，具局限性，皮损形态多样，边界不清，表现为潮红、小丘疱疹、糜烂、流滋、结痂；至慢性时皮肤肥厚粗糙，因手指经常活动而皲裂，病程较长，顽固难愈。"},{"t":"p","x":"阴囊湿疮：为湿疮中常见的一种。局限于阴囊皮肤，有时可延至肛周，甚至阴茎部。"},{"t":"p","x":"有潮湿型和干燥型两种。前者表现为阴囊皮肤水肿性肿胀、潮红、糜烂、流滋、结痂，日久皮肤肥厚，色素加深；"},{"t":"p","x":"后者潮红、肿胀不如前者，皮肤浸润变厚，呈灰色，上覆鳞屑，且有裂隙，因经常搔抓而有不规则小片色素脱失，瘙痒剧烈，夜间更甚，常影响睡眠和工作。女阴湿疮：累及大小阴唇及其附近皮肤。"},{"t":"p","x":"患处浸润肥厚，境界清楚，有时呈水肿性。瘙痒剧烈，常有搔抓，可见糜烂、抓痕。"},{"t":"p","x":"月经及分泌物的刺激可使病程慢性难愈。肛周湿疹：局限于肛门周围皮肤，少数可累及会阴部。"},{"t":"p","x":"常潮湿，皮肤浸润肥厚，可发生皲裂。瘙痒剧烈。"},{"t":"p","x":"小腿湿疮：好发于小腿下1/3内侧，常伴有青筋暴露，皮损呈局限性暗红色，弥漫密集丘疹、丘疱疹，糜烂、流滋，日久皮肤变厚、色素沉着。常伴发小腿溃疡。"},{"t":"p","x":"部分患者皮损中心色素减退。钱币状湿疮：是湿疮的一种特殊类型，因其皮损似钱币状而得名。"},{"t":"p","x":"常发于冬季，与皮肤干燥同时发生。皮损好发于手足背、四肢伸侧、肩、臀、乳房等处。"},{"t":"p","x":"皮损为红色小丘疹或丘疱疹，密集而呈钱币状，滋水较多。慢性者皮肤肥厚，表面有结痂及鳞屑，皮损周围散发丘疹、水疱，常呈“卫星状”。"},{"t":"p","x":"自觉瘙痒剧烈，反复发作，不易治愈。"},{"t":"p","x":"(2)辅助检查可进行过敏原检测以协助明确病因，有可疑外因接触史者(如手部湿疮)可做皮肤斑贴试验。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-10、表10-11、表10-12)"},{"t":"table","img":"img/tab/t1010.jpg","cap":"表10-10急性湿疮与接触性皮炎的鉴别"},{"t":"table","img":"img/tab/t1011.jpg","cap":"表10-11慢性湿疮与牛皮癣的鉴别"},{"t":"table","img":"img/tab/t1012.jpg","cap":"表10-12手足部湿疮与鹅掌风、脚湿气鉴别"}],"entries":["e0474"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热利湿止痒为主要治法。急性者以清热利湿为主，慢性者以养血润肤为主。"},{"t":"p","x":"外治宜用温和的药物，以免加重病情。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101001","name":"湿热蕴肤证","clinic":"发病快，病程短，皮损潮红，有丘疱疹，灼热瘙痒无休，抓破渗液流脂水；伴心烦口渴，身热不扬，大便干，小便短赤；舌红，苔薄白或黄，脉滑或数","treat":"清热利湿止痒","formula":"龙胆泻肝汤合萆薢渗湿汤加减。水疱多，破后流滋多者，加土茯苓、鱼腥草；热盛者，加黄连解毒汤；瘙痒重者，加紫荆皮、地肤子","formulaNames":["龙胆泻肝汤","萆薢渗湿汤"]},{"t":"syn","sid":"s101002","name":"脾虚湿蕴证","clinic":"发病较缓，有丘疹、丘疱疹，瘙痒，抓后少许渗出，可见鳞屑；伴纳少，腹胀便溏，易疲乏；舌淡胖，苔白腻，脉濡缓","treat":"健脾利湿止痒","formula":"除湿胃苓汤或参苓白术散加减","formulaNames":["除湿胃苓汤","参苓白术散"]},{"t":"syn","sid":"s101003","name":"血虚风燥证","clinic":"病程久，反复发作，皮损色暗或色素沉着，或皮损粗糙肥厚，剧痒难忍，遇热或肥皂水洗后瘙痒加重；伴有口干不欲饮，纳差，腹胀；舌淡，苔白，脉弦细","treat":"养血润肤，祛风止痒","formula":"当归饮子或四物消风饮加减","formulaNames":["当归饮子","四物消风饮"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)急性湿疮初起仅有潮红、丘疹，或少数水疱而无渗液时，外治宜清热安抚，避免刺激。"},{"t":"p","x":"可选用清热止痒的中药苦参、黄柏、地肤子、荆芥等煎汤湿敷，或用三黄洗剂、炉甘石洗剂外搽。"},{"t":"p","x":"若水疱糜烂、渗出明显时，外治宜收敛、消炎，促进表皮恢复、可选用黄柏、生地榆、马齿苋、野菊花等煎汤，或10%黄柏溶液等制剂，对皮损进行冷湿敷；用青黛散麻油调搽。"},{"t":"p","x":"急性湿疮后期滋水减少时，外治宜保护皮损，避免刺激，促进角质新生，清除残余炎症，可选黄连膏、青黛膏外搽。"},{"t":"p","x":"(2)亚急性湿疮外治原则为消炎、止痒、燥湿、收敛，选用青黛膏、3%黑豆馏油、5%黑豆馏油软膏外搽。"},{"t":"p","x":"(3)慢性湿疮可选用各种软膏剂、乳剂，根据瘙痒及皮肤肥厚程度加入不同浓度的止痒剂、角质促成和溶解剂，一般可外搽5%硫黄软膏、10%～20%黑豆馏油软膏。"},{"t":"p","x":"亦可选用中药药浴疗法、中药熏蒸疗法、中药封包疗法等。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针灸疗法"},{"t":"p","x":"针刺疗法：适用于湿疹各个阶段，辨证取穴。刺络拔罐疗法：适用于慢性湿疹皮损肥厚、苔藓样变或瘙痒患处。"},{"t":"p","x":"火针疗法：适用于局限性慢性湿疹，皮损肥厚浸润明显者。"},{"t":"p","x":"(2)西医治疗"},{"t":"p","x":"内服西药：以抗炎、止痒为目的，选用抗组胺药、镇静剂。必要时可两种配合或交替使用。"},{"t":"p","x":"急性期可选用钙剂、维生素C、硫代硫酸钠等静脉给药。合并感染者加用抗生素。"},{"t":"p","x":"外用西药：急性期无渗液者用氧化锌油，渗出多者用3%硼酸溶液湿敷；当渗出减少时，可用糖皮质激素霜剂，可与油剂交替使用。"},{"t":"p","x":"亚急性期用糖皮质激素乳剂、糊剂。慢性期选用软膏、硬膏、涂膜剂。"},{"t":"p","x":"对顽固局限肥厚性损害可用糖皮质激素局部封包。为防止和控制继发性感染，可加用抗生素。"}]}],"entries":["e0475","e0476","e0477","e0478","e0479","e0480"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.忌用热水烫洗，忌用肥皂等刺激物洗患处。避免搔抓，以防感染和刺激皮损。"},{"t":"p","x":"2.保护皮肤屏障功能，对皮肤干燥的亚急性及慢性湿疹加用保湿剂。3.忌食易致敏和有刺激性的食物，如辛辣、鱼虾、牛羊肉、酒类等。"},{"t":"p","x":"4.急性湿疮或慢性湿疮急性发作期间，应暂缓预防注射各种疫苗和接种牛痘。"}],"entries":["e0481"]}]},{"id":"d1011","kind":"attach","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"婴儿湿疮","displayName":"湿疮·婴儿湿疮","parentId":"d1010","printedPage":152,"pdfPage":167,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"婴儿湿疮又称奶癣、胎敛疮，是发于1～2岁婴儿的过敏性皮肤病。其临床特点：好发于头面，重者可延及躯干和四肢，皮损呈多形性，多对称分布，可有渗液，瘙痒明显，患儿常有家族过敏史。"},{"t":"p","x":"本病相当于西医学的婴儿湿疹。本病多由于禀性不耐，脾胃运化失职，内有胎火湿热，外受风湿热邪，两者蕴阻肌肤而成；"},{"t":"p","x":"或因消化不良、食物过敏、衣服摩擦、肥皂水洗涤刺激等诱发。临床表现方面，皮损好发于颜面，多自两颊开始，渐侵至额部、眉间、头皮，反复发作，严重者可侵延至颈部、肩胛部，甚至遍及全身。"},{"t":"p","x":"皮损形态多样，分布大多对称，时轻时重。在面部者，初为簇集的或散在的红斑或丘疹；"},{"t":"p","x":"在头皮或眉部者，多有油腻性鳞屑和黄色发亮的结痂。病轻者仅有淡红的斑片，伴有少量的丘疹、小水疱和小片糜烂流滋；"},{"t":"p","x":"病重者红斑鲜艳，水疱多，以糜烂流滋为主。转为亚急性者水疱减少，暗红色斑片，丘疹稀疏，附有鳞屑。"},{"t":"p","x":"若过分搔抓、摩擦、洗烫，则糜烂加重，流滋增多，并可向颈部、躯干、四肢蔓延。常因皮肤破损而继发感染，引起附近臖核肿痛，伴有发热等全身症状。"},{"t":"p","x":"因剧痒，患儿常用手搔抓，烦躁，哭闹不安，常影响健康和睡眠。有些婴儿湿疹到2岁后未愈，有家族过敏史或有哮喘、过敏性鼻炎等病史，应考虑为特应性皮炎。"},{"t":"p","x":"根据发病年龄及皮损特点，婴儿湿疮可分为3型：①脂溢型：多发于出生后1～2个月的婴儿。皮损在前额、面颊、眉周围，呈小片红斑，上附黄色鳞屑，颈部、腋下、腹股沟常有轻度糜烂。"},{"t":"p","x":"②湿型(渗出型)：多发于外形肥胖、3～6个月的婴儿。"},{"t":"p","x":"皮损有红斑、丘疹、水疱、糜烂、流滋。易继发感染而有发热、臖核肿大等症状。"},{"t":"p","x":"③干型(干燥型)：多发于瘦弱或皮肤干燥的1岁以上婴儿。"},{"t":"p","x":"皮损为淡红色或暗红色斑片、干燥、脱屑，或有丘疹和片状浸润，常反复发作，迁延难愈。临床上需与黄水疮(脓疱疮)相鉴别。"},{"t":"p","x":"中药内治上，胎火湿热证治宜凉血清火、利湿止痒，方选消风导赤汤加减；脾虚湿蕴证治宜健脾利湿，方选小儿化湿汤加土茯苓、鱼腥草。"},{"t":"p","x":"外治法使用上，脂溢型和湿型用生地榆、黄柏煎水或马齿苋合剂冷湿敷，待流滋、糜烂减轻后、选用青黛散油、黄连油或蛋黄油外搽；干型用三黄洗剂、黄柏霜外搽。"}],"entries":["e0482"]}]},{"id":"d1012","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"接触性皮炎","displayName":"接触性皮炎","parentId":"","printedPage":153,"pdfPage":168,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"接触性皮炎是指因皮肤或黏膜接触某些外界致病物质所引起的皮肤急性或慢性炎症反应。"},{"t":"p","x":"其临床特点是发病前均有明显的接触某种物质的病史，好发于接触部位，皮疹有红斑、丘疹、水疱、糜烂、渗出、结痂等。中医文献中没有一个统一的病名来概括接触性皮炎，而是根据接触物质的不同及其引起的症状特点而有不同的名称。"},{"t":"p","x":"如因漆刺激而引起者，称为漆疮；因贴膏药引起者，称为膏药风；"},{"t":"p","x":"接触马桶引起者，称为马桶癣等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于患者禀赋不耐，皮肤腠理不密，接触某些物质，例如漆、药物、塑料、橡胶制品、染料和某些植物的花粉、叶、茎等，使毒邪侵入皮肤，蕴郁化热，邪热与气血相搏而发病。但体质因素是发病的主要原因，同一种物质，禀赋不耐者接触后易发病。"},{"t":"p","x":"1.风热蕴肤外感风邪，兼夹热毒，郁于腠理。2.湿热毒蕴湿热内蕴，与热毒相搏，蕴于肌肤。"},{"t":"p","x":"3.血虚风燥病久耗伤阴血，生风化燥，肌肤失养。西医学认为，接触性皮炎分为原发刺激性接触性皮炎和变态反应性接触性皮炎两种。"},{"t":"p","x":"①刺激性接触性皮炎：接触物(如强酸、强碱等)本身具有强烈刺激性，任何人接触该物均可发病。"},{"t":"p","x":"或虽刺激性较小，但接触时间长也可致病。"},{"t":"p","x":"②变应性接触性皮炎：为典型的IV型超敏反应。"},{"t":"p","x":"接触物为致敏因子，本身并无刺激性，多数人接触后不发病，仅有少数过敏体质者接触后发病。能引起接触性皮炎的接触物质很多，主要有动物性、植物性和化学性三种。"},{"t":"p","x":"本病的发病机制十分复杂，目前尚未完全阐明。"}],"entries":["e0483","e0484"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病发生前有明显的接触史，均有一定的潜伏期，第一次在4～5天或更长，再次接触发病时间缩短，多数在数小时或1天左右。"},{"t":"p","x":"但由强酸、强碱等强烈的刺激物所致者可立即发生皮损而无潜伏期。一般急性发病，常见于暴露部位，如面、颈、四肢。"},{"t":"p","x":"皮损的形态、范围、严重程度取决于接触物质种类、性质、浓度、接触时间的久暂、接触部位和面积大小，以及机体对刺激物的反应程度。典型皮损边界清楚，多局限于接触部位，形态与接触物大抵一致。"},{"t":"p","x":"皮疹一般为红斑、肿胀、丘疹、水疱或大疱、糜烂、渗出、结痂等，一个时期内以某一种皮损为主。若为强酸、强碱或其他强烈化学物质接触，常可引起坏死或溃疡。"},{"t":"p","x":"若发生在组织疏松部位，如眼睑、包皮、阴囊处，则表现为皮肤局限性水肿，皮肤光亮，表面纹理消失，无明确边缘。若患者反应强烈，则皮疹不仅局限于接触部位，还可播散到其他部位，甚至泛发全身。"},{"t":"p","x":"自觉瘙痒、烧灼感，重者疼痛。少数患者伴有怕冷、发热、头痛、恶心等全身症状。"},{"t":"p","x":"病因去除和恰当处理后可在1～2周内痊愈。但反复接触或处理不当，可转变为亚急性或慢性，皮损表现为肥厚粗糙，呈苔藓样变。"},{"t":"p","x":"(2)辅助检查将可疑致敏物用适宜溶剂配制成适当浓度，进行斑贴试验。"},{"t":"p","x":"若结果呈阳性，则提示患者对该受试物过敏。2.鉴别诊断(表10-13)接触性皮炎与急性湿疮的鉴别见表10-10，与颜面丹毒的鉴别见"},{"t":"table","img":"img/tab/t1013.jpg","cap":"表10-13。"}],"entries":["e0485"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热祛湿止痒为主要治法。首先应找出致病原因，避免接触过敏物质，否则治疗无效。"},{"t":"p","x":"急性者以清热祛湿为主，慢性者以养血润燥为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101201","name":"风热蕴肤证","clinic":"起病较急，好发于头面部，皮损色红，肿胀轻，其上为红斑或丘疹，自觉瘙痒、灼热；心烦，口干、小便微黄；舌红，苔薄白或薄黄，脉浮数","treat":"疏风清热止痒","formula":"消风散加减","formulaNames":["消风散"]},{"t":"syn","sid":"s101202","name":"湿热毒蕴证","clinic":"起病急骤，皮损面积较广泛，其色鲜红肿胀，上有水疱或大疱，水疱破后则糜烂渗液，自觉灼热、瘙痒；伴发热，口渴，大便干，小便短黄；舌红，苔黄，脉弦滑数","treat":"清热祛湿，凉血解毒","formula":"龙胆泻肝汤合化斑解毒汤加减。渗出多者，加土茯苓、紫荆皮、马齿苋；红肿面积广泛者，加熟大黄、紫荆皮、桑白皮","formulaNames":["龙胆泻肝汤","化斑解毒汤"]},{"t":"syn","sid":"s101203","name":"血虚风燥证","clinic":"病程长，病情反复发作，皮损肥厚、干燥、有鳞屑，或呈苔藓样变，瘙痒剧烈，有抓痕及结痂；舌淡红，苔薄，脉弦细","treat":"养血润燥，祛风止痒","formula":"当归饮子加减。瘙痒甚者，加僵蚕、徐长卿","formulaNames":["当归饮子"]},{"t":"p","x":"瘙痒甚者，加僵蚕、徐长卿。2.外治疗法用药宜简单、温和、无刺激性。"},{"t":"p","x":"(1)皮损以红斑、丘疹为主者，选用三黄洗剂外搽，或选用青黛散冷开水调涂，或1%～2%樟脑、5%薄荷脑粉剂外涂，每日5～6次。"},{"t":"p","x":"(2)大量渗出、糜烂者，选用马齿苋、黄柏、苦参、蒲公英、桑叶等组方煎水湿敷，或用10%黄柏溶液湿敷。"},{"t":"p","x":"(3)结痂者，选用青黛膏、清凉油乳剂等外搽。"},{"t":"p","x":"(4)皮损肥厚粗糙，有鳞屑，或呈苔藓样者，选用软膏或霜剂，如3%黑豆馏油、糠馏油软膏。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"西医治疗可内服抗组胺药，重症泛发者可短期应用糖皮质激素口服或静脉注射。外用药物治疗："},{"t":"p","x":"轻度红肿、丘疹、水疱而无渗液时，用炉甘石洗剂；有明显渗液时，可用3%硼酸溶液冷湿敷；"},{"t":"p","x":"无明显渗出时，多应用糖皮质激素霜剂。"}]}],"entries":["e0486","e0487","e0488","e0489","e0490"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.明确病因，避免继续接触过敏物质。2.与职业有关者应加强防护措施。"}],"entries":["e0491"]}]},{"id":"d1013","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"药毒","displayName":"药毒","parentId":"","printedPage":155,"pdfPage":170,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"药毒是指药物通过口服、注射、吸入或皮肤黏膜直接用药等途径，进入人体后所引起的皮肤或黏膜的急性炎症反应。"},{"t":"p","x":"中医文献中又称为“中药毒”。其临床特点：发病前有用药史，并有一定的潜伏期，常突然发病，皮损形态多样，颜色鲜艳，可泛发或仅限于局部，病情轻重不一，严重者可累及多个系统，甚至危及生命。"},{"t":"p","x":"男女老幼均可发病，尤以禀赋不耐者为多见。随着药物的广泛应用、新药的不断出现及药物滥用的加剧、药毒的发病率不断增高。"},{"t":"p","x":"《诸病源候论》《备急千金要方》等书中都有关于“药毒”的记载。如《诸病源候论·解诸药毒候》曰：“凡药物云有毒及有大毒者，皆能变乱于人为害，亦能杀人。"},{"t":"p","x":"本病相当于西医学的药疹，亦称药物性皮炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由禀赋不耐，药毒内侵所致。1.湿毒蕴肤患者禀湿热之体，受药毒侵扰，体内湿热蕴蒸，郁于肌肤。"},{"t":"p","x":"2.热毒入营风热之邪侵袭腠理，热入营血，或禀血热之体，受药毒侵扰，火毒炽盛，燔灼营血，外发皮肤，内攻脏腑。3.气阴两虚病久药毒灼伤津液，气阴两伤，肌肤失养；"},{"t":"p","x":"或久病阴液耗竭，阳无所附，浮越于外，病重而危殆。西医学认为，药疹主要是由药物过敏引起。"},{"t":"p","x":"各型超敏反应均可参与其发病，如I型超敏反应(荨麻疹型药疹)、Ⅱ型超敏反应(紫癜型药疹)、Ⅲ型超敏反应(血管炎型药疹)、IV型超敏反应(剥脱性皮炎型、麻疹型或湿疹型药疹)。"},{"t":"p","x":"此外，部分药疹还可通过其他免疫效应途径，或与药物代谢相关酶的缺陷及抑制等引起。引起本病的药物较多，任何一种药物在一定条件下都有引起药疹的可能。"},{"t":"p","x":"常引起药疹的药物有抗生素类、解热镇痛类、安眠镇静药及各种预防接种的生物制品，近年来也有某些中草药、中成药引起药毒的报道。"}],"entries":["e0492","e0493"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"1)基本特征本病临床表现复杂，基本具有以下特征：①发病前有用药史。"},{"t":"p","x":"②有一定的潜伏期，第一次发病多在用药后5～20天，重复用药常在24小时内发生，短者甚至在用药后瞬间或数分钟内发生。"},{"t":"p","x":"③突然发病，自觉瘙痒，重者伴有发热、倦怠、纳差、大便干燥、小便黄赤等全身症状。"},{"t":"p","x":"④皮损形态多样，颜色鲜艳，分布呈全身性、对称性，可泛发或仅限于局部。"},{"t":"p","x":"2)常见类型药毒的临床表现多种多样，不同患者用同一种药物可引起不同的皮疹和症状，常见的临床类型有以下几种："},{"t":"p","x":"固定型药毒：典型皮损为圆形或椭圆形水肿性紫红斑，边界清楚，重者红斑中央形成水疱或大疱。单发或多发。"},{"t":"p","x":"经1～2周后急性炎症消退，留有褐色色素沉着斑，终年不退，发作次数越多，色素沉着越深。如再服此药，可在数分钟或数小时后先感原发疹部位瘙痒，随之局部发生同样皮损，但损害可扩大，呈现中央暗红、边缘鲜红的表现，并可增发新疹。"},{"t":"p","x":"可发生于身体任何部位，好发于皮肤黏膜交界处，如唇、眼睑、外生殖器、肛门周围，此处皮疹很易擦破而糜烂、感染，发生严重水肿，甚至形成溃疡。荨麻疹型药毒：症状为大小不等的风团，颜色较一般荨麻疹红，持续时间较长。"},{"t":"p","x":"自觉瘙痒，可有刺痛及触痛感。也可发生血管性水肿，也可以是血清病样综合征或过敏性休克的症状之一。"},{"t":"p","x":"麻疹型或猩红热型药毒：又称为发疹型药毒，是药毒中最常见的类型。麻疹型药毒皮损为密集、红色、针头至米粒大的斑疹或斑丘疹、常对称分布，可泛发全身，以躯干为多，形态类似麻疹，黏膜、掌跖也可受累，可有程度不等的瘙痒。"},{"t":"p","x":"猩红热型药毒开始为小片红斑，从面、颈、上肢、躯干向下发展，快者24小时，慢者3～4天可遍及全身，为水肿性鲜红色斑疹，弥漫对称分布，互相融合，似泥红热。麻疹型和猩红热型药毒全身症状较轻，无麻疹或猩红热的中毒症状。"},{"t":"p","x":"白细胞数可升高，少数患者肝功能可有一过性异常。停药后1～2周、皮疹颜色变淡，糠状或大片脱屑，体温渐下降。"},{"t":"p","x":"若不及时停药，则可发展为重症药毒。湿疹型药毒：大都先由外用药物引起局部接触性过敏，发生湿疹样皮炎后，再服用或注射同样的或化学结构相似的药物，即可发生泛发的湿疹样皮损。"},{"t":"p","x":"一般无全身症状。病程常在1个月以上。"},{"t":"p","x":"多形红斑型药毒：临床表现与多形红斑相似，皮损为豌豆至蚕豆大的圆形或椭圆形水肿性红斑、丘疹，红斑中心呈紫红色或有水疱，有虹膜样或靶样损害，境界清楚。"},{"t":"p","x":"重者可全身泛发红斑、水疱、大疱、糜烂，包括口、鼻、眼、肛门、外生殖器等部位，有全身不适、畏寒、高热及重要脏器的累及，称史-约综合征(Stevens-Johnson syndrome)。"},{"t":"p","x":"紫癜型药毒：轻者双小腿出现针头至豆大或更大的紫红色瘀点或瘀斑，散在或密集分布，皮疹平或稍隆起。重者可累及四肢、躯干，有时可有风团，甚至中央有小血疱。"},{"t":"p","x":"大疱性表皮松解型药毒：是最严重的一型药毒。发病急，1～4天皮损遍及全身，全身中毒症状重，有高热、疲乏、咽痛等。"},{"t":"p","x":"初起皮损发生于面、颈、胸部，为紫红或暗红色略带铁灰色斑，很快扩大、增多、融合，红斑上出现大小不等的松弛性水疱及表皮松解，水疱极易破，形成大片糜烂面或外观无水疱，该处表皮极松，可以用手指推动，稍用力表皮即可擦掉，似烫伤样外观。"},{"t":"p","x":"眼、鼻、口、消化道、呼吸道黏膜均可剥脱。皮肤有明显疼痛感。"},{"t":"p","x":"其他重要脏器如心、肝、肾、脑等均可同时严重受累。严重者可因感染、重要脏器病变、水电解质失衡等造成死亡。"},{"t":"p","x":"剥脱性皮炎或红皮病型药毒：属重症药毒，可开始即有全身皮肤潮红肿胀，或从麻疹型或猩红热型发展而来。面部及手足皮损尤为严重，可伴有丘疱疹或小水疱、糜烂、渗液、结痂。"},{"t":"p","x":"2周左右全身皮肤大量脱屑，呈落叶状或鳞片状，手足呈手套袜套样剥脱，头发、指(趾)甲可脱落。常伴有明显的全身症状，如畏寒、发热、胃肠道症状等，可出现蛋白尿、低蛋白血症、肝肾功能损害、白细胞计数显著增高或降低。"},{"t":"p","x":"常有全身浅表淋巴结肿大。严重者全身衰竭或继发感染而死亡。"},{"t":"p","x":"(2)辅助检查 ①血常规检查见白细胞数增多，常伴有嗜酸性粒细胞比例增高。"},{"t":"p","x":"②若多脏器受累者可见肝功能异常，血清转氨酶增高；"},{"t":"p","x":"肾功能异常，出现血尿、蛋白尿，血尿素氮、肌酐增高；心脏受累可见心电图异常。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-14、表10-15)"},{"t":"table","img":"img/tab/t1014.jpg","cap":"表10-14麻疹型或猩红热型药毒与麻疹、猩红热的鉴别"},{"t":"table","img":"img/tab/t1015.jpg","cap":"表10-15荨麻疹型、多形红斑型、紫癜型药毒与瘾疹、猫眼疮、葡萄疫的鉴别"}],"entries":["e0494"]},{"title":"治疗","blocks":[{"t":"p","x":"停用一切可疑致敏药物，临床以清热利湿解毒为主。重症宜中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101301","name":"湿毒蕴肤证","clinic":"皮疹为红斑、丘疹、风团、水疱，甚则糜烂渗液，表皮剥脱；伴灼热剧痒，口干、大便燥结，小便黄赤，或有发热；舌红，苔薄白或黄，脉滑或数","treat":"清热利湿，解毒止痒","formula":"萆薢渗湿汤或龙胆泻肝汤加减。肿胀糜烂者，加白茅根；剧烈瘙痒者、加白鲜皮","formulaNames":["萆薢渗湿汤","龙胆泻肝汤"]},{"t":"syn","sid":"s101302","name":"热毒入营证","clinic":"皮疹鲜红或紫红，甚则为紫斑、血疱，灼热痒痛；伴高热，神志不清、口唇焦燥，口渴不欲饮，大便干结，小便短赤；舌红绛，苔少或镜面舌，脉洪数","treat":"清热凉血，解毒护阴","formula":"清营汤加减。神昏谵语者，加紫雪丹或安宫牛黄丸","formulaNames":["清营汤"]},{"t":"syn","sid":"s101303","name":"气阴两虚证","clinic":"严重药毒后期大片脱屑；伴低热，神疲乏力，气短，口干欲饮；舌红、少苔，脉细数","treat":"益气养阴，清解余热","formula":"增液汤合益胃汤加减。低热者，加青蒿、鳖甲等","formulaNames":["增液汤","益胃汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药溻渍对于皮疹鲜红、糜烂者可用马齿苋等清热解毒中药，后期皮疹色暗者可用当归等活血化瘀中药，煮水局部溻渍。"},{"t":"p","x":"(2)中药熏洗消退期皮疹暗红，选用鸡血藤、丹参等活血化瘀中药煎剂外用熏洗治疗。"},{"t":"p","x":"(3)中药涂擦皮疹消退，皮肤粗糙，局部皮肤瘙痒，可选用黄连膏局部涂擦。"},{"t":"p","x":"中药溻渍或中药熏洗治疗后行中药涂擦疗效更佳。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西药治疗多饮水或静脉输液，以促进致敏药物从体内排出。"},{"t":"p","x":"轻型药毒一般于停药后皮损多能迅速消退。可给予抗组胺药、维生素C及钙剂等治疗。"},{"t":"p","x":"必要时口服泼尼松片，控制症状后逐渐减量至停药。局部若以红斑、丘疹为主者，可外用炉甘石洗剂及糖皮质激素霜剂；"},{"t":"p","x":"以糜烂渗出为主者，可间歇湿敷，外用氧化锌油。重型药毒包括重症多形红斑型、大疱性表皮松解型、剥脱性皮炎型等，应尽早使用足量糖皮质激素，并给予积极的抗过敏治疗；"},{"t":"p","x":"加强全身的支持疗法，注意水、电解质平衡及蛋白质等的摄入量，补充多种维生素，流质饮食，可给能量合剂，必要时输血浆；加强护理，预防和治疗并发症，防止继发感染。"},{"t":"p","x":"对药物引起的过敏性休克或药物过敏伴急性咽喉水肿时，须首先皮下注射1:1000的肾上腺素"},{"t":"p","x":"0.5～1.0mL，同时静脉推注相当于泼尼松剂量1mg/kg的糖皮质激素(氢化可的松、地塞米松或甲泼尼龙)治疗，以预防呼吸道阻塞，但同时必须做好气管内插管或气管切开和吸氧的准备。"},{"t":"p","x":"(2)针灸疗法伴瘙痒明显，夜寐不安者，可选用王不留行籽于神门、肺、心、肝等耳穴贴压。"}]}],"entries":["e0495","e0496","e0497","e0498","e0499","e0500"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.预防本病发生的关键是合理用药，避免滥用药物。用药前必须询问患者有无药物过敏史。"},{"t":"p","x":"应用青霉素及抗毒血清制剂时，用药前要做过敏试验。2.用药过程中要注意观察用药后的反应，遇到全身出疹、瘙痒，要考虑药疹的可能，应及时诊断、及时处理。"}],"entries":["e0501"]}]},{"id":"d1014","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"瘾疹","displayName":"瘾疹","parentId":"","printedPage":158,"pdfPage":173,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"瘾疹是一种皮肤出现风团，时隐时现的瘙痒性、过敏性皮肤病。"},{"t":"p","x":"其临床特点是皮肤上出现风团，色红或白，形态各异，发无定处，骤起骤退，退后不留痕迹，自觉瘙痒。《诸病源候论·风瘙身体瘾疹候》曰：“邪气客于皮肤，复逢风寒相折，则起风瘙瘾疹。"},{"t":"p","x":"古代文献中称之为“瘾疹”“风疹块”等。本病相当于西医学的荨麻疹。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由禀赋不足，复感外邪所致。先天禀赋不足，表虚不固，风寒、风热外袭，客于肌表，致使营卫失调而发；"},{"t":"p","x":"或饮食不节，过食辛辣肥厚，或有肠道寄生虫，使肠胃积热，复感风邪，内不得疏泄，外不得透达，郁于皮毛腠理之间而发。此外，情志内伤，冲任不调，肝肾不足，血虚生风生燥，阻于肌肤也可发病。"},{"t":"p","x":"西医学认为，荨麻疹的病因复杂，约3/4的患者找不到原因，特别是慢性荨麻疹。"}],"entries":["e0502","e0503"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现荨麻疹一般分为急性、慢性和特殊类型。"},{"t":"p","x":"急性荨麻疹整个病程短于6周，多数能治愈，并能找到病因，如感染、药物、食物、接触过敏等；慢性荨麻疹病程超过6周、反复发作、常难以找到病因。"},{"t":"p","x":"1)急性荨麻疹皮疹为大小不等的风团，色淡红、鲜红或苍白色，孤立、散在或融合成片，数小时内风团减轻，变为红斑而渐消失，但不断有新的风团出现。"},{"t":"p","x":"病情严重者可有胸闷、心慌、血压下降、发生过敏性休克样症状。累及胃肠道黏膜而出现恶心、呕吐、腹痛、腹泻；"},{"t":"p","x":"累及食管，食管水肿致进食困难；累及喉头黏膜可出现喉头水肿、呼吸困难，甚至窒息。"},{"t":"p","x":"如伴有高热、寒战等全身中毒症状，应注意有无严重感染的可能。大约有90%的急性荨麻疹在2～3周后症状消失。"},{"t":"p","x":"2)慢性荨麻疹全身症状一般较轻，风团时多时少，反复发生，病程在6周以上。"},{"t":"p","x":"大多数患者不能找到病因。"},{"t":"p","x":"3)特殊类型荨麻疹"},{"t":"p","x":"皮肤划痕症：亦称人工荨麻疹。用钝器划或用手搔抓皮肤后，沿着划痕发生条状隆起，并有瘙痒，不久即消退。"},{"t":"p","x":"寒冷性荨麻疹：较常见。可分为家族性(较罕见)和获得性两种。"},{"t":"p","x":"好发于面部、手背等暴露部位，在接触冷物、冷空气、冷风或食冷物后发生红斑、风团，有轻到中等程度瘙痒。胆碱能性荨麻疹：遇热、进食辛辣食物、饮酒、情绪紧张、工作紧张、剧烈运动等刺激后数分钟发生风团。"},{"t":"p","x":"压迫性荨麻疹：身体受压部位如臀部、上肢、掌跖等处受到一定压力后，4～8小时局部发生肿胀性斑块，多数有痒感，或灼痛、刺痛感等，可伴寒战、发热等全身症状。"},{"t":"p","x":"日光性荨麻疹：皮肤被紫外线照射后，在暴露部位出现水肿性红斑、风团，持续1分钟或数小时后消退，自觉瘙痒或针刺感。光感试验阳性。"},{"t":"p","x":"水源性荨麻疹：接触水的皮肤几分钟内出现风团，自觉瘙痒，1小时左右消退。该型发病与水温无关。"},{"t":"p","x":"自身免疫性荨麻疹：在临床上表现为严重而持续性的风团，瘙痒剧烈。皮损主要侵犯四肢躯干，面颈部不易受累，同时伴有发热、畏寒、关节痛等。"},{"t":"p","x":"患者具有自身免疫性疾病的病史或家族史，特别是甲状腺炎具有提示意义。"},{"t":"p","x":"(2)辅助检查血液中嗜酸性粒细胞比例升高。"},{"t":"p","x":"若伴感染时，白细胞总数及中性粒细胞、淋巴细胞比例可升高。自身免疫性荨麻疹患者可出现血沉、抗核抗体、补体、甲状腺功能异常。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-16)"},{"t":"table","img":"img/tab/t1016.jpg","cap":"表10-16荨麻疹与丘疹性荨麻疹、阑尾炎的鉴别"}],"entries":["e0504"]},{"title":"治疗","blocks":[{"t":"p","x":"寻找病因、对症处理。中医以辨证论治为主，特殊类型者采用中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101401","name":"风寒束表证","clinic":"风团色白，遇寒加重，得暖则减；恶寒，口不渴；舌淡红，苔薄白，脉浮紧","treat":"疏风散寒，解表止痒","formula":"桂枝麻黄各半汤加减。畏寒怕冷者，加玉屏风散；恶心欲呕者，加法半夏、陈皮等","formulaNames":["桂枝麻黄各半汤"]},{"t":"syn","sid":"s101402","name":"风热犯表证","clinic":"风团鲜红，灼热剧痒，遇热加重，得冷则减；伴有发热，恶寒，咽喉肿痛；舌质红，苔薄白或薄黄，脉浮数","treat":"疏风清热，解表止痒","formula":"消风散加减。风团颜色鲜红者，加牡丹皮、生地黄等；口渴者，加玄参；瘙痒剧烈者，加白鲜皮、徐长卿等","formulaNames":["消风散"]},{"t":"syn","sid":"s101403","name":"胃肠湿热证","clinic":"风团片大色红，瘙痒剧烈；发疹的同时伴脘腹疼痛，恶心呕吐，神疲纳呆，大便秘结或泄泻；舌质红，苔黄腻，脉弦滑数","treat":"疏风解表，通腑泄热","formula":"防风通圣散加减。有肠道寄生虫者，加乌梅、使君子、槟榔等；大便稀溏者，加四君子汤；恶心呕吐者，加藿香等","formulaNames":["防风通圣散"]},{"t":"syn","sid":"s101404","name":"血虚风燥证","clinic":"反复发作，迁延日久，午后或夜间加剧；伴心烦易怒，口干，手足心热；舌红少津，脉沉细","treat":"养血祛风，润燥止痒","formula":"当归饮子加减。心烦失眠者，加酸枣仁、柏子仁等；手足心热者，加白薇、青蒿等；瘙痒剧烈者，加磁石、钩藤等","formulaNames":["当归饮子"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药熏洗瘙痒明显，无胸闷憋气者适用。"},{"t":"p","x":"风团色红，瘙痒明显者，选用马齿苋、白鲜皮等解毒止痒中药熏洗；风团色淡白，皮肤干燥者，选用当归、茯苓、白术等健脾养血中药熏洗，每日1次。"},{"t":"p","x":"(2)中药保留灌肠因饮食不慎而诱发者，采用苦参、黄柏等中药保留灌肠以泻浊解毒，每日1次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西药治疗"},{"t":"p","x":"急性荨麻疹：可选用1～2种抗组胺药物治疗。伴感染时，应积极寻找病因，控制感染；"},{"t":"p","x":"严重者可使用糖皮质激素；伴有喉头水肿、呼吸困难时应立即抢救。"},{"t":"p","x":"慢性荨麻疹：应积极寻找病因，一般以抗组胺药物治疗为主，可根据风团发生的时间决定给药的时间。风团控制后应逐渐减量。"},{"t":"p","x":"一种抗组胺药治疗无效时，可几种抗组胺药联用或交替使用。特殊类型荨麻疹：常选用兼有抗5-羟色胺、抗乙酰胆碱作用的抗组胺药物，或与肥大细胞膜稳定剂联合应用。"},{"t":"p","x":"(2)针灸疗法"},{"t":"p","x":"毫针：皮疹发于上半身者，取曲池、内关穴；发于下半身者，取血海、足三里、三阴交穴；"},{"t":"p","x":"发于全身者，配风市、风池、大椎、大肠俞穴等。耳针取肝区、脾区、肾上腺、皮质下、神门穴等。"},{"t":"p","x":"每日1次、10次为1个疗程。耳穴贴压：用王不留行籽在耳部的内分泌、神门、肾上腺、肺、脾等穴位贴压以疏风止痒。"},{"t":"p","x":"2～3天更换一次，双耳交替，10次为1个疗程。刺络拔罐：用三棱针在背部大椎、肺俞、脾俞点刺3～5针，上罐，出血5～10mL时取罐。"},{"t":"p","x":"对急性荨麻疹患者可泄热止痒，每周2次。"}]}],"entries":["e0505","e0506","e0507","e0508","e0509","e0510","e0511"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.记录生活日记，积极寻找过敏原。2.禁用或禁食某些对机体致敏的药物或食物，避免接触致敏物品，积极防治某些肠道寄生虫病。"},{"t":"p","x":"3.忌食鱼腥虾蟹、辛辣、酒等。"}],"entries":["e0512"]}]},{"id":"d1015","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"猫眼疮","displayName":"猫眼疮","parentId":"","printedPage":161,"pdfPage":176,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"猫眼疮是一种以靶形或虹膜状红斑为主，兼有丘疹或丘疱疹等多形性损害的急性炎症性皮肤病。"},{"t":"p","x":"其临床特点：发病急骤，皮损为红斑、丘疹、丘疱疹等多形性损害，典型皮损有虹膜样特征性红斑；重症可有严重的黏膜、内脏损害。"},{"t":"p","x":"本病易复发，好发于春秋季节，女性多于男性，以10～30岁者发病率最高。猫眼疮之名首见于《医宗金鉴·外科心法要诀》，曰“猫眼疮名取象形，痛痒不常无血脓，光芒闪烁如猫眼，脾经湿热外寒凝”，阐述了猫眼疮的临床特点和病因病机。"},{"t":"p","x":"古时又称之为“雁疮”或“寒疮”。本病相当于西医学的多形红斑。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多由素体禀赋不耐，腠理不固，感受不耐之物，搏于肌肤而发；或阳气不足，卫外不固，风寒、风热之邪侵袭肌肤而发；"},{"t":"p","x":"或因过食辛辣肥甘，损伤脾胃，湿浊内生，蕴久化热，湿热蕴阻肌肤而发；或素体湿热内蕴，复感毒邪，热毒内蕴，燔灼营血，以致火毒炽盛，蕴结肌肤而发。"},{"t":"p","x":"西医学认为，本病病因复杂，常因致敏物、感染、药物、食物及物理因素(寒冷、日光、放射线)等引起。另外，某些疾病(风湿热、自身免疫病、恶性淋巴瘤等)也可出现多形红斑样皮损。"}],"entries":["e0513","e0514"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现多见于春秋两季。"},{"t":"p","x":"前驱症状可见头痛、低热、四肢倦怠、食欲不振、关节肌肉疼痛等。按病情特点分为轻症和重症两型。"},{"t":"p","x":"1)轻症：最常见，青年女性为多，以10～30岁者发病率最高。"},{"t":"p","x":"皮损为多形性，有红斑、丘疹、水疱、大疱、紫癜、风团等。"},{"t":"p","x":"典型损害为水肿性圆形红斑，或淡红色扁平丘疹，境界清楚，皮损呈远心性扩展，1～2天内直径可达1～2cm，红斑中央略凹陷，其颜色较边缘略深、中央常为水疱、紫癜或坏死区，边缘为轻度的水肿环，周围绕以鲜红色晕，称为靶形损害或虹膜状损害，伴轻度瘙痒，无明显的全身症状。"},{"t":"p","x":"多对称发于手足背、前臂、踝部和面颈部；口腔黏膜、外阴黏膜亦可累及。轻症者病程2～4周，易复发。"},{"t":"p","x":"2)重症：多见于儿童，男性多于女性。"},{"t":"p","x":"起病急骤，前驱症状明显。皮损广泛分布于全身各处，常为水肿性红斑、水疱、大疱、血疱和瘀斑等，自觉疼痛；"},{"t":"p","x":"或皮疹不多，但黏膜损害广泛且严重，口腔、鼻咽、眼、尿道、肛门或呼吸道黏膜广泛累及，发生大片糜烂和坏死，其中眼损害可造成视力减退甚至失明。可伴发支气管炎、肺炎、消化道出血、关节炎及内脏损害等。"},{"t":"p","x":"重症者病程3～6周、预后差。"},{"t":"p","x":"(2)辅助检查血常规检查白细胞计数及嗜酸性粒细胞比例增高，红细胞沉降率增快，抗链球菌溶血素“O”值增高，C反应蛋白增高，若肾脏受累可出现蛋白尿、血尿、尿素氮增高等。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-17)"},{"t":"table","img":"img/tab/t1017.jpg","cap":"表10-17猫眼疮与冻疮、疱疹样皮炎的鉴别"}],"entries":["e0515"]},{"title":"治疗","blocks":[{"t":"p","x":"祛除致病因素，控制感染，避免接触可疑致敏原、药物等；同时结合患者病情进行对症治疗，以减轻症状和缩短病程。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101501","name":"风寒阻络证","clinic":"春秋发病，水肿性红斑，色暗红或紫红，发于颜面及手足时形如冻疮，水肿明显，遇冷加重，得热则减；伴畏寒，小便清长；舌质淡，苔白，脉沉紧","treat":"温经散寒，活血通络","formula":"当归四逆汤加减。畏寒肢冷明显者，加伸筋草；关节疼痛者，加羌活、独活、威灵仙；水肿明显者，加防己、车前子、泽泻；斑色紫暗者，加丹参、泽兰","formulaNames":["当归四逆汤"]},{"t":"syn","sid":"s101502","name":"风热蕴肤证","clinic":"以红斑、丘疹、小风团样损害为主，颜色鲜红，自觉瘙痒；可伴发热，咽干咽痛，关节酸痛，便干溲黄；舌质红，苔薄黄，脉浮数","treat":"疏风清热，凉血解毒","formula":"消风散加减。红斑鲜红伴灼热者，加牡丹皮、紫草、茜草；水肿、水疱明显者，加车前草、白茅根；关节疼痛甚者，加秦艽、松节、老鹳草；咽干咽痛者，加射干、玄参、山豆根","formulaNames":["消风散"]},{"t":"syn","sid":"s101503","name":"湿热蕴结证","clinic":"水肿性红斑，色泽鲜红，兼见水疱，或口腔糜烂，外阴湿烂，自感痒痛；或见发热头重，身倦乏力，纳呆呕恶，溲赤，便秘或黏滞不爽；舌质红，苔黄腻，脉弦滑","treat":"清热利湿，解毒止痒","formula":"龙胆泻肝汤加减。伴恶心泛呕者，加半夏、竹茹；发热头重者，加藿香、佩兰；瘙痒甚者、加白鲜皮、刺蒺藜","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s101504","name":"火毒炽盛证","clinic":"起病急骤，全身泛发红斑、大疱、糜烂、瘀斑，口腔、二阴破溃糜烂；伴高热恶寒，头痛无力，恶心呕吐，关节疼痛，大便秘结，小便黄赤；舌质红，苔黄，脉滑数","treat":"清热凉血，解毒利湿","formula":"清瘟败毒饮合导赤散加减。高热、口干唇燥者、加玄参、天花粉；壮热不退者，加羚羊角粉0.3g冲服，或用紫雪散1～2g冲服；大便秘结者，加生大黄；恶心呕吐者，加半夏、竹茹","formulaNames":["清瘟败毒饮","导赤散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)皮损以红斑、丘疹、水疱、糜烂为主者，以清热、收敛、止痒为主。"},{"t":"p","x":"用三黄洗剂水煎后湿敷患处、每日3～4次，并外搽黄连膏。"},{"t":"p","x":"(2)皮损呈水疱、大疱，渗出明显者，以清热、燥湿、消肿为主。"},{"t":"p","x":"用马齿苋30g、黄柏30g、地榆30g水煎冷敷患处，每次20分钟，每日3～5次，冷敷后外搽紫草油。"},{"t":"p","x":"(3)黏膜糜烂者可用生肌散或锡类散外吹患处，每日2～4次；"},{"t":"p","x":"若口腔黏膜糜烂，可用蒲黄药液含漱，并用青吹口散外吹。3.其他疗法轻症者用抗组胺药、钙剂、维生素C；重症者应尽早应用足量糖皮质激素，同时保持水、电解质平衡，保证热量、蛋白质和维生素的摄入，若合并感染应及时给予抗感染治疗。"}]}],"entries":["e0516","e0517","e0518","e0519","e0520","e0521"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.寻找并祛除致病因素，及时控制感染，停用可疑致敏药物。2.重症患者若皮肤大疱破溃、糜烂，应加强护理，皮损处及时换药；"},{"t":"p","x":"并注意床上用品及衣物的消毒、更换，防止感染。"}],"entries":["e0522"]}]},{"id":"d1016","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"葡萄疫","displayName":"葡萄疫","parentId":"","printedPage":163,"pdfPage":178,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"葡萄疫是以皮肤、黏膜下出现瘀点或瘀斑为主要表现的一种血管炎性疾病。其临床特点是皮肤或黏膜出现紫红色瘀点、瘀斑，压之不退色，可伴有腹痛、关节痛或肾脏病变，一般无血液系统疾病。"},{"t":"p","x":"本病多见于儿童及青少年，好发于四肢伸侧，尤多见于小腿，且春季发病较多。"},{"t":"p","x":"葡萄疫之病名首见于《外科正宗·杂疮毒门》，曰：“葡萄疫，其患多生于小儿，感受四时不正之气，郁于皮肤不散，结成大小青紫斑点，色若葡萄，发在遍体头面，乃为腑症。”古代文献中有称“肌衄”“斑毒”等。"},{"t":"p","x":"本病相当于西医学的过敏性紫癜。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由禀赋不耐，邪伤脉络所致。血不循经或瘀血阻滞络道，血溢脉外，凝滞肌肤，发为紫斑。"},{"t":"p","x":"累及脏腑则发为腹痛、尿血、便血之症。1.热毒伤络多因外感风热，邪毒入里，脏腑蕴热，灼伤脉络，血不循经，热邪迫血妄行，外溢肌肤，内渗脏腑。"},{"t":"p","x":"2.湿热伤营湿热蕴肤，郁热化毒，伤及脉络，阻塞脉道、血不循经，血外溢肌肤而出疹，内则蕴阻肠胃、关节而发病。3.脾气亏虚素体脾虚，气虚不固，统血无权，血溢脉外而发斑。"},{"t":"p","x":"4.脾肾两虚阴血不足，虚火上炎，灼伤脉络，血随火动，渗于脉外，而成紫斑；或火不生土，运化无力，或思虑、饮食伤脾，脾阳虚衰，不能统血，血溢脉外而发斑；"},{"t":"p","x":"肾阳虚衰，气化失司，水湿内停，湿热下注而发斑疹。西医学认为，本病病因复杂，细菌、病毒、食物、药物等均可导致发病，此外，恶性肿瘤和自身免疫性疾病亦可成为致病因素。"}],"entries":["e0523","e0524"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病前常有上呼吸道感染、食用鱼虾发物或服药过敏等病史。"},{"t":"p","x":"皮疹以四肢伸侧为主，尤多见于小腿部，亦可泛发于臀部及躯干。表现为针尖到绿豆大小的瘀点或瘀斑，色鲜红或紫红，压之不退色，多对称或成批出现，1周左右转为黄褐色。"},{"t":"p","x":"多一面消退，一面又发新皮损。皮疹若融合成片，严重时可出现风团、红斑、水肿、血疱、溃疡、坏死等。"},{"t":"p","x":"无瘙痒或偶有瘙痒，易反复发作。单纯型仅有皮肤损害，而未累及内脏，一般无明显全身症状；"},{"t":"p","x":"关节型皮损可出现风团、红斑、血疱、并伴有腕、肘、膝、踝关节等处疼痛；腹型者除皮疹外、伴有恶心呕吐，腹痛腹泻、甚至便血等，重者出现肠套叠或肠穿孔；"},{"t":"p","x":"肾型者皮损较重，伴有蛋白尿、血尿、管型尿，后期可转为慢性肾炎、尿毒症，或同时兼见关节、胃肠道症状及肾脏损害。"},{"t":"p","x":"(2)辅助检查白细胞有轻度至中度增高，嗜酸性粒细胞计数有时增高，红细胞沉降率增快。"},{"t":"p","x":"肾型者尿中有红细胞、蛋白、管型。血小板计数、出凝血时间、血块收缩时间均正常。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-18)"},{"t":"table","img":"img/tab/t1018.jpg","cap":"表10-18而萄疫与血小板减少性紫癜的鉴别"}],"entries":["e0525"]},{"title":"治疗","blocks":[{"t":"p","x":"治疗早期以清热凉血、活血化瘀为主，后期以补脾益肾为基本原则，结合病证，对症治疗，标本兼顾。同时，尽可能寻找并避免致敏因素。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101601","name":"热毒发斑证","clinic":"起病急，皮疹为鲜红色较密集的瘀点或瘀斑，高出皮面；伴发热恶寒，咽痛口干，甚者鼻衄，大便秘结，小便短赤；舌质红绛，舌苔黄腻，脉洪数。本证多见于单纯型","treat":"清热凉血，化瘀消斑","formula":"犀角地黄汤合银翘散加减。瘙痒者，加蝉蜕等疏风散热止痒","formulaNames":["犀角地黄汤","银翘散"]},{"t":"syn","sid":"s101602","name":"湿热伤络证","clinic":"皮疹多见于下肢，为鲜红色较密集的瘀点、瘀斑或大片紫癜；伴关节红肿疼痛、肿胀，或恶心、呕吐、腹痛、便血，或血尿；舌质红，舌苔黄腻，脉滑数。本证多见于关节型、腹型及肾型","treat":"清热利湿，通络消斑","formula":"茵陈蒿汤合犀角地黄汤加减。伴关节痛者，加虎杖、桑枝、土茯苓等清热祛湿利关节；恶心呕吐者，加黄连、半夏等降逆止呕；腹痛者，加延胡索、山楂、木香等行气散瘀止痛；血尿者，加蒲黄、大蓟、小蓟等凉血止血，散瘀利尿；尿蛋白者，加白茅根、知母、黄柏、大蓟、小蓟等清热凉血利尿","formulaNames":["茵陈蒿汤","犀角地黄汤"]},{"t":"p","x":"本证多见于关节型、腹型及肾型。治法：清热利湿，通络消斑。"},{"t":"syn","sid":"s101603","name":"脾气亏虚证","clinic":"病程较长，反复发作，迁延日久，皮疹紫暗或暗淡，分布稀疏；伴面色萎黄，神疲气短、自汗乏力，纳呆便溏；舌质淡，或有齿痕，舌苔薄，脉濡细","treat":"健脾益气，养血止血","formula":"归脾汤加减。纳呆者，加砂仁、焦三仙、鸡内金等行气消食和胃；气虚甚者，加党参、升麻等益气升提","formulaNames":["归脾汤"]},{"t":"syn","sid":"s101604","name":"脾肾两虚证","clinic":"病程日久，反复发作，皮疹紫红；伴见面色萎黄，神疲乏力，午后潮红，颧红盗汗，五心烦热；舌质红、少苔，脉细数。或皮疹淡紫，触之欠温，遇寒加重；伴见头晕耳鸣，腰膝酸软，身寒肢冷，腹痛喜按、食少纳呆，五更泄泻；舌质淡，舌苔薄，脉沉迟","treat":"滋阴降火，温脾肾阳","formula":"大补阴丸或金匮肾气丸加减。若阳虚明显者，加制附子、细辛、吴茱萸等温补肾阳","formulaNames":["大补阴丸","金匮肾气丸"]},{"t":"p","x":"舌质淡，舌苔薄，脉沉迟。治法：滋阴降火，温脾肾阳。"},{"t":"p","x":"若阳虚明显者，加制附子、细辛、吴茱萸等温补肾阳。2.外治疗法若有局部皮损，可用黄连膏外涂；若瘙痒，可外用炉甘石洗剂外擦。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"西医治疗抗组胺药物治疗，同时亦可配合维生素C、芦丁片、钙剂等。急性期腹痛症状明显及并发肾炎者，可应用糖皮质激素、免疫抑制剂、解痉止痛药等治疗。"}]}],"entries":["e0526","e0527","e0528","e0529","e0530","e0531"]},{"title":"预防与调护","blocks":[{"t":"p","x":"积极寻找并消除可疑致病因素。预防上呼吸道感染，避免服用可致敏的药物或食物。"}],"entries":["e0532"]}]},{"id":"d1017","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"瓜藤缠","displayName":"瓜藤缠","parentId":"","printedPage":165,"pdfPage":180,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"瓜藤缠是一种发生于下肢的结节红斑性、皮肤血管炎性皮肤病。"},{"t":"p","x":"其临床特点是散在性皮下结节，鲜红至紫红色，大小不等，压痛，好发于小腿伸侧。多见于青中年女性，以春秋季发病者为多。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》云：“此证生于腿胫，流行不定，或发一二处，疮顶形似牛眼，根脚漫肿⋯⋯若绕胫而发，即名瓜藤缠。”本病相当于西医学的结节性红斑。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"素体血分有热，外感湿邪，湿与热结，或脾虚失运，水湿内生，湿郁化热，湿热下注，气滞血瘀，瘀阻经络而发；或体虚之人气血不足，卫外不固，寒湿之邪乘虚外袭，客于肌肤腠理，流于经络，气血瘀滞而发。"},{"t":"p","x":"西医学认为，本病病因不明，可由感染性、免疫性、炎症性疾病，肿瘤、药物、妊娠等因素引起。"}],"entries":["e0533","e0534"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病前常有低热、倦怠、咽痛、食欲不振等前驱症状。"},{"t":"p","x":"皮损好发于两小腿伸侧，为鲜红色疼痛性结节，略高出皮面，蚕豆至杏核大或桃核大，对称性分布，若数个结节融合在一起则大如鸡卵，皮损周围水肿，但境界清楚，皮肤紧张，自觉疼痛，压之更甚，颜色由鲜红渐变为暗红。"},{"t":"p","x":"约经数天或数周，颜色及结节逐渐消退，不留痕迹，不化脓，亦不溃破。在缓解期常残存数个小结节，新的结节可再次出现。"},{"t":"p","x":"皮损发生部位除小腿外，少数患者可发于上肢及面颈部。本病发病急，一般在6周左右可自愈，但亦有长达数月不愈者。"},{"t":"p","x":"部分患者可因劳累、感冒、妇女行经而复发。"},{"t":"p","x":"(2)辅助检查外周血白细胞总数正常或稍升高，红细胞沉降率加快，C反应蛋白增高。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-19)"},{"t":"table","img":"img/tab/t1019.jpg","cap":"表10-19瓜藤缠与硬结性红斑、皮肤变应性血管炎的鉴别"}],"entries":["e0535"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以活血化瘀、散结止痛为基本治疗原则。结合病证，或清热利湿，或散寒祛湿。"},{"t":"p","x":"严重病例可采用中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101701","name":"湿热瘀阻证","clinic":"发病急骤，皮下结节略高出皮面，灼热红肿，压痛明显；伴头痛，咽痛，关节痛，发热，口渴，大便干，小便黄；舌质微红，苔薄黄或黄腻，脉滑微数","treat":"清热利湿，祛瘀通络","formula":"萆薢渗湿汤合桃红四物汤加减。咽喉疼痛、畏寒发热者，加山豆根、荆芥、牛蒡子、桔梗；关节疼痛明显者，加牛膝、防己；大便干者，加生大黄","formulaNames":["萆薢渗湿汤","桃红四物汤"]},{"t":"syn","sid":"s101702","name":"寒湿入络证","clinic":"皮损暗红，反复缠绵不愈；伴有关节痛，遇寒加重，肢冷，口不渴，大便不干；舌质淡，苔白或白腻，脉沉缓或迟","treat":"散寒祛湿，化瘀通络","formula":"阳和汤加减。关节疼痛，遇寒加重，肢冷明显者，加制附子","formulaNames":["阳和汤"]},{"t":"p","x":"关节疼痛，遇寒加重，肢冷明显者，加制附子。2.外治疗法以散结、止痛为原则。"},{"t":"p","x":"(1)中药外敷皮下结节较大，红肿疼痛者，外敷金黄膏、四黄膏或玉露膏；"},{"t":"p","x":"皮下结节色暗红，红肿不明显者，外敷冲和膏。"},{"t":"p","x":"(2)中药熏洗蒲公英、丹参、紫草各30g，荆芥、牡丹皮、当归各20g，水煎外洗。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺疗法主穴取足三里、三阴交、昆仑、阳陵泉等穴，实证用泻法，虚证用补法，隔日1次。"},{"t":"p","x":"(2)西医治疗疼痛明显者可考虑给予非甾体抗炎药；"},{"t":"p","x":"皮损广泛，炎症较重，疼痛剧烈者，可考虑使用免疫抑制剂或糖皮质激素，合并感染者抗感染治疗。"}]}],"entries":["e0536","e0537","e0538","e0539"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.注意休息，适当抬高患肢，以减轻局部肿痛。2.避风寒，防潮湿；冬季注意保暖，以防复发。"}],"entries":["e0540"]}]},{"id":"d1018","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"风瘙痒","displayName":"风瘙痒","parentId":"","printedPage":167,"pdfPage":182,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"风瘙痒是一种无明显原发性皮肤损害而以瘙痒为主要症状的皮肤感觉异常的皮肤病，亦称痒风。"},{"t":"p","x":"《外科证治全书·痒风》记载：“遍身搔痒，并无疮疥，搔之不止。”其临床特点是皮肤阵发性瘙痒，搔抓后常出现抓痕、血痂、色素沉着和苔藓样变等继发性损害。"},{"t":"p","x":"临床上有局限性、泛发性两种。局限性者以阴部、肛门周围最为多见，泛发性者可泛发全身。"},{"t":"p","x":"本病相当于西医学的皮肤瘙痒症。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"禀赋不耐，血热内蕴，外感之邪侵袭，则易血热生风，因而致痒；久病体弱，气血亏虚，风邪乘虚外袭，血虚易生风，肌肤失养而致本病；"},{"t":"p","x":"饮食不节，过食辛辣、油腻，或饮酒，损伤脾胃，湿热内生，化热生风，内不得疏泄，外不得透达，郁于皮肤腠理而发本病。西医学认为，其致病因素比较复杂，有内因和外因两方面。"},{"t":"p","x":"常见的内因有内分泌疾病(如糖尿病)、肝胆疾病、内脏肿瘤、感染性疾病、神经障碍性疾病、妊娠等，外因有环境因素、物理性或化学性刺激等。"}],"entries":["e0541","e0542"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"临床表现好发于老年及青壮年人，多见于冬季，少数也有夏季发作。主要表现为瘙痒剧烈，常呈阵发性，以夜间为著。"},{"t":"p","x":"无原发性皮损，由于经常搔抓，患处皮肤常伴抓痕、血痂，也可有湿疹样变、苔藓样变及色素沉着等继发性损害。根据发生部位可分为全身性瘙痒症和局限性瘙痒症。"},{"t":"p","x":"前者见于因皮肤干燥、基础疾病引起的老年性皮肤瘙痒症，以及与季节关系明显的季节性瘙痒症；后者见于肛门瘙痒症、外阴瘙痒症等。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-20)"},{"t":"table","img":"img/tab/t1020.jpg","cap":"表10-20风瘙痒与虱病、疥疮的鉴别"}],"entries":["e0543"]},{"title":"治疗","blocks":[{"t":"p","x":"尽可能祛除一切可疑致病因素。中医治疗以祛风清热凉血为主，并发内部疾病时宜标本兼顾，采用内外兼治的方法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101801","name":"风热血热证","clinic":"皮肤瘙痒剧烈，遇热更甚，皮肤抓破后有血痂；伴心烦，口渴，小便色黄，大便干燥；舌质红，苔薄黄，脉浮数","treat":"疏风清热，凉血止痒","formula":"消风散合四物汤加减","formulaNames":["消风散","四物汤"]},{"t":"syn","sid":"s101802","name":"湿热内蕴证","clinic":"瘙痒不止，抓破后继发感染或湿疹样变；伴口干口苦，胸胁闷胀，纳谷不香，小便黄赤，大便秘结；舌质红，苔黄腻，脉滑数或弦数","treat":"清热利湿，解毒止痒","formula":"龙胆泻肝汤加减","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s101803","name":"血虚风燥证","clinic":"一般以老年人多见，病程较久，皮肤干燥，抓破后可有少量脱屑，血痕累累，情绪波动可引起发作或瘙痒加剧；伴头晕眼花，失眠多梦；舌红，苔薄，脉细数或弦数","treat":"养血润燥，祛风止痒","formula":"当归饮子加减","formulaNames":["当归饮子"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药熏洗治疗适用于无明显抓痕、血痂及皮疹无渗出的患者。"},{"t":"p","x":"采用当归、丹参、鸡血藤、白鲜皮、连翘等养血活血、解毒止痒的中药煎剂对皮损部位进行熏洗，温度33～38℃，每日1次，每次15分钟。"},{"t":"p","x":"(2)中药蒸汽治疗适用于皮损肥厚，呈苔藓样变的患者。"},{"t":"p","x":"采用当归、丹参、生地黄、火麻仁、地骨皮、白鲜皮等具有清热解毒、活血润肤作用的中药煎剂熏蒸皮损，每周3次，10次为1个疗程。"},{"t":"p","x":"(3)中药涂擦治疗适用于皮肤干燥者。"},{"t":"p","x":"可用黄连膏等外擦，以润肤止痒。"},{"t":"p","x":"(4)中药封包治疗适用于皮肤干燥、脱屑者。"},{"t":"p","x":"用黄连膏外搽皮肤干燥处，用保鲜膜将皮肤封包40分钟，以加强皮肤对药物的吸收，保持皮肤水分，以润肤止痒。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西药治疗主要为镇静止痒，可应用各种抗组胺类和镇静类药物，亦可选用盐酸普鲁卡因静脉封闭疗法或钙剂。"},{"t":"p","x":"局部外用药以止痒为主，可选用止痒剂及润肤剂，也可选用各种糖皮质激素制剂。外阴、肛门黏膜区避免使用刺激性药物。"},{"t":"p","x":"(2)针灸疗法"},{"t":"p","x":"毫针：适用于顽固性瘙痒继发苔藓样变者。根据经络辨证选取背部俞穴和相应腧穴进行针灸治疗，以达到活血化瘀通络、养血祛风止痒的作用。"},{"t":"p","x":"每日1次，10次为1个疗程。"}]}],"entries":["e0544","e0545","e0546","e0547","e0548","e0549"]},{"title":"预防与调护","blocks":[{"t":"p","x":"避免用搔抓、摩擦或热水烫洗等方式止痒，不用碱性强的肥皂洗澡。"}],"entries":["e0550"]}]},{"id":"d1019","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"牛皮癣","displayName":"牛皮癣","parentId":"","printedPage":168,"pdfPage":183,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"牛皮癣是一种患处皮肤状如牛项之皮，肥厚且坚硬的慢性瘙痒性皮肤病。"},{"t":"p","x":"其临床特点：皮损多是圆形或多角形的扁平丘疹，融合成片，搔抓后皮损肥厚，皮沟加深，皮嵴隆起，形成苔藓样变，呈阵发性瘙痒。《外科正宗》曰：“牛皮癣如牛项之皮，顽硬且坚，抓之如朽木。"},{"t":"p","x":"因好发于颈部，顽固难愈，古代文献又称之为“摄领疮”“顽癣”等。本病相当于西医学的慢性单纯性苔藓，又名神经性皮炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病初起为风湿热之邪阻滞肌肤或硬领等外来机械刺激所引起；病久耗伤阴液，营血不足，血虚生风生燥，皮肤失去濡养而成。"},{"t":"p","x":"肝火郁滞，情志不遂，郁闷不舒，或紧张劳累，心火上炎，以致气血运行失职，凝滞肌肤，每易成为诱发的重要因素，且致病情反复。西医学认为，本病病因不明。精神紧张、焦虑、失眠及搔抓等刺激常为本病诱因及加重因素。"}],"entries":["e0551","e0552"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)好发部位好发于颈项、上眼睑、四肢关节伸侧、腰骶部、外阴、肛周等部位，多局限于一处或两侧对称分布。"},{"t":"p","x":"(2)皮损特点常先有局部瘙痒，经不断搔抓或摩擦后出现圆形或多角形扁平丘疹，呈皮色或淡褐色。"},{"t":"p","x":"皮损逐渐融合成苔藓样变，边界清楚。"},{"t":"p","x":"(3)临床分型按其发病部位、皮损多少分为局限性和播散性。"},{"t":"p","x":"局限性，皮损仅见于颈项等局部；播散性，分布较广泛，可泛发全身。"},{"t":"p","x":"(4)自觉症状自觉阵发性瘙痒，常于局部刺激、精神烦躁时加剧，夜间尤甚。"},{"t":"h","lv":3,"x":"(5)病程慢性经过，常多年不愈，易反复发作。"},{"t":"p","x":"2.鉴别诊断牛皮癣与紫癜风的鉴别见表10-21，与慢性湿疮的鉴别见表10-11。"},{"t":"table","img":"img/tab/t1021.jpg","cap":"表10-21牛皮癣与紫癜风的鉴别"}],"entries":["e0553"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以祛邪止痒、扶正润肤为治疗原则。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s101901","name":"肝郁化火证","clinic":"皮疹色红；伴心烦易怒，失眠多梦，眩晕，心悸，口苦咽干；舌边尖红，脉弦数","treat":"疏肝理气，泻火止痒","formula":"龙胆泻肝汤合丹栀逍遥散加减。痒甚者，加僵蚕、乌梢蛇","formulaNames":["龙胆泻肝汤","丹栀逍遥散"]},{"t":"syn","sid":"s101902","name":"风湿蕴肤证","clinic":"皮损呈暗红或淡褐色片状，粗糙肥厚，剧痒时作，夜间尤甚；舌淡红、苔薄白或白腻、脉濡缓","treat":"祛风除湿，清热止痒","formula":"消风散加减。瘙痒剧烈者，加刺猬皮、乌梢蛇","formulaNames":["消风散"]},{"t":"syn","sid":"s101903","name":"血虚风燥证","clinic":"皮损色淡或灰白，状如枯木，肥厚粗糙似牛皮；心悸怔忡，失眠健忘、女子月经不调；舌淡，苔薄，脉沉细","treat":"养血润燥，息风止痒","formula":"当归饮子加减","formulaNames":["当归饮子"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药熏洗适用于播散性神经性皮炎且皮肤干燥者。"},{"t":"p","x":"用鸡血藤、当归、丹参、三棱、莪术、白鲜皮等具有活血化瘀、软坚散结功效的中药煎剂对皮损部位进行熏洗治疗，每日1次，每次20～30分钟。"},{"t":"p","x":"(2)中药蒸汽治疗适用于病程长，皮损呈苔藓样变者。"},{"t":"p","x":"用当归、丹参、茯苓、白术、白鲜皮等具有清热解毒、活血化瘀功效的中药煎剂熏蒸皮损，每日1次，每次10～20分钟。"},{"t":"p","x":"(3)中药涂搽适用于皮疹表面干燥者。"},{"t":"p","x":"选用黄连膏、青黛膏等中药油膏局部涂搽，每日1～2次。"},{"t":"p","x":"(4)封包疗法适用于皮损肥厚者。"},{"t":"p","x":"局部皮损涂擦中药油膏后，用保鲜薄膜将皮损处封包40分钟，每日1～2次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针灸治疗"},{"t":"p","x":"毫针：适用于容易摩擦部位的皮损及瘙痒顽固者，可进行皮损周围毫针围刺治疗。拔罐：躯干、四肢皮损肥厚处可走罐治疗，以疏通经络、行气活血、解毒止痒，每日1次，7天为1个疗程。"},{"t":"p","x":"艾灸：适用于浸润肥厚、范围较小的损害，或经过反复治疗皮损变化不明显者。可选用艾条进行局部皮损处灸疗，每天1次，7天为1个疗程。"},{"t":"p","x":"火针：用火烧红针迅速刺入皮损内，深度至皮损微渗血为度，每周1～2次。"},{"t":"p","x":"(2)西医治疗 ①皮损广泛者，可选用镇静剂或抗组胺药内服，亦可用普鲁卡因静脉封闭或钙剂静脉注射。"},{"t":"p","x":"②外用药常选用各种糖皮质激素制剂和各种止痒制剂。"}]}],"entries":["e0554","e0555","e0556","e0557","e0558","e0559"]},{"title":"预防与调护","blocks":[{"t":"p","x":"避免各种机械性、物理性刺激，避免硬质衣领摩擦。"}],"entries":["e0560"]}]},{"id":"d1020","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"白疕","displayName":"白疕","parentId":"","printedPage":170,"pdfPage":185,"syndromeCount":6,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"白疕是一种以红斑、丘疹、鳞屑损害为主要表现的慢性复发性炎症性系统性疾病。"},{"t":"p","x":"其临床特点是在红斑的基础上覆盖多层银白色鳞屑，刮去鳞屑有薄膜及露水珠样出血点。病程较长，反复发作，不易根治。"},{"t":"p","x":"男女老幼皆可罹患，具有一定的遗传倾向，在自然人群中的发病率为0.1%～3%。初发病例季节性明显，多冬重夏轻，但部分患者可相反，数年之后则季节性不明显。"},{"t":"p","x":"白疕之名首见于《外科大成·白疕》，曰：“白疕，肤如疹疥，色白而痒，搔起白疕，俗呼蛇风。”古代文献中有称“松皮癣”“干癣”“蛇虱”“白壳疮”等。"},{"t":"p","x":"本病相当于西医学的银屑病。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"多因素体营血亏损，血热内蕴，化燥生风，肌肤失养所致。1.初起多因内有蕴热，复感风寒或风热之邪，阻于肌肤，蕴结不散而发；"},{"t":"p","x":"或机体蕴热偏盛，或性情急躁，心火内生，或外邪入里化热，或恣食辛辣肥甘及荤腥发物，伤及脾胃，郁而化热，内外之邪相合，蕴于血分，血热生风而发。"},{"t":"p","x":"2.病久耗伤营血，阴血亏虚，生风化燥，肌肤失养，或加之素体虚弱，气血不足，病程日久，气血运行不畅，以致经脉阻塞，气血瘀结，肌肤失养而反复不愈；"},{"t":"p","x":"或热蕴日久，生风化燥，肌肤失养，或流窜关节，闭阻经络，或热毒炽盛，气血两燔而发。"},{"t":"p","x":"西医学认为，本病的确切病因尚未明确，目前认为是遗传因素与环境因素等多因素相互作用的多基因遗传病，通过免疫介导的共同通路，最后引起角质形成细胞增殖。"}],"entries":["e0561","e0562"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现根据白疕的临床特征，可分为寻常型、脓疱型、关节病型、红皮病型，其中寻常型占99%以上，以上四型可合并发生或相互转化。"},{"t":"p","x":"除皮肤关节症状外，银屑病患者常合并其他系统性疾病，如心血管疾病、代谢性疾病、心理疾病等，称为银屑病共病。"},{"t":"p","x":"1)寻常型为本病最常见的类型。"},{"t":"p","x":"皮损初起为针头大小的丘疹，逐渐扩大为绿豆、黄豆大小的淡红色或鲜红色丘疹或斑丘疹，可融合成形态不同的斑片，边界清楚，表面覆盖多层银白色鳞屑，刮除鳞屑则露出发亮的半透明薄膜，称薄膜现象；"},{"t":"p","x":"再刮除薄膜，出现多个筛状出血点，称为点状出血现象。此为本病特征性皮损。"},{"t":"p","x":"发生在头部，其发呈束状，但毛发正常，无脱落；发生在指甲则甲板呈顶针状；发生在面部的皮损可呈小片红斑；"},{"t":"p","x":"发生在口腔黏膜则为灰白色斑片，四周有红晕，基底浸润；发生在龟头则为光滑、干燥性红斑，边界清楚，刮之有白色鳞屑；"},{"t":"p","x":"小腿前反复发作的皮损可有苔藓样变。皮损可发生于身体各处，多对称分布。"},{"t":"p","x":"初发时多在头皮及肘、膝关节等处。临床上可见点滴状、钱币状、斑块状、地图状、蛎壳状、混合状等多种形态。"},{"t":"p","x":"少数轻型病例初次发病可有自愈情况；但当反复患咽炎、扁桃体炎，或紧张劳累，或恣食腥膻发物、辛辣等，往往可诱发或复发。"},{"t":"p","x":"病程缓慢，有的自幼发病，持续十余年或数十年，甚至有迁延终生者。病程一般可分为以下三期："},{"t":"p","x":"①进行期：新皮疹不断出现，原皮疹不断扩大，颜色鲜红，鳞屑较厚，针刺、搔抓、外伤、手术等损伤可导致受损部位出现典型的皮疹，称为同形反应。"},{"t":"p","x":"②静止期：皮损稳定，基本无新疹出现，原皮疹色暗红，鳞屑较多，既不扩大，也不消退。"},{"t":"p","x":"③退行期：皮损缩小或变平，颜色变淡，鳞屑减少，或从中心开始消退，遗留暂时性的色素减退斑或色素沉着斑。"},{"t":"p","x":"2)脓疱型可继发于寻常型，亦可为原发性，一般分为泛发性和局限性两种。"},{"t":"p","x":"泛发性脓疱型：临床表现为皮疹初发多为炎性红斑，或在寻常型银屑病的皮损上出现密集的、针尖到粟粒大、黄白色浅在的小脓疱，表面覆盖少量鳞屑，2周左右消退，再发新脓疱；"},{"t":"p","x":"严重者可急性发病，全身出现密集脓疱，并融合成“脓湖”，可伴有发热、关节肿痛、全身不适；可并发肝、肾等器官的损害，亦可因继发感染、电解质紊乱或衰竭而死亡。"},{"t":"p","x":"局限性脓疱：以掌跖脓疱病多见，临床表现为皮损仅限于手、足部，掌跖出现对称性红斑，其上密集针尖至粟粒大小的深在脓疱，不易破溃，1～2周后干枯、结痂、脱皮，脓疱常反复发生，顽固难愈。"},{"t":"p","x":"3)关节病型常有寻常型银屑病的基本皮肤损害，伴有关节炎的表现，以侵犯远端指(趾)关节为主，常不对称，亦可侵犯大关节和脊柱。"},{"t":"p","x":"受累关节红肿、疼痛，重者可有关节腔积液、强直、关节畸形。此型往往经年累月而不易治愈。"},{"t":"p","x":"4)红皮病型常由寻常型银屑病发展而成，或由于治疗不当，或外用刺激性很强的药物，或长期大量应用激素后突然停药而引起。"},{"t":"p","x":"全身皮肤弥漫性潮红或紫红、肿胀、浸润、大量糠状脱屑，仅有少量片状正常皮肤(称“皮岛”)，掌跖角化，指(趾)甲增厚甚至脱落。伴有发热、畏寒、浅表淋巴结肿大等全身症状。"},{"t":"p","x":"病程较长，常数月或数年不愈。"},{"t":"p","x":"(2)辅助检查血白细胞总数增高及血沉加快。"},{"t":"p","x":"脓疱型者细菌培养阴性。组织病理检查具有以下改变："},{"t":"p","x":"寻常型：主要为角化过度伴角化不全，角化不全区可见Munro微脓肿，颗粒层变薄或消失，棘层增厚，表皮突延长，深入真皮。真皮乳头呈杵状向表皮内上伸。"},{"t":"p","x":"真皮浅层血管周围淋巴细胞、中性粒细胞浸润。脓疱型：表皮内可见海绵状脓疱，多位于棘细胞上层，疱内充满中性粒细胞。"},{"t":"p","x":"真皮浅层血管扩张，周围可见淋巴细胞、组织细胞及少量中性粒细胞浸润。"},{"t":"p","x":"红皮病型：除银屑病的病理改变外，与慢性皮炎相似，呈明显的角化不全，颗粒层消失，棘层肥厚，上皮脚延长，表皮细胞内及细胞间水肿，真皮浅层水肿，血管扩张充血，周围炎性细胞浸润。"},{"t":"p","x":"2.鉴别诊断白疕与白屑风的鉴别见表10-22，与风热疮的鉴别见表10-23。"},{"t":"table","img":"img/tab/t1022.jpg","cap":"表10-22白疕与白屑风的鉴别"}],"entries":["e0563"]},{"title":"治疗","blocks":[{"t":"p","x":"寻常型进行期多以清热凉血解毒为基本治则，静止期多以养血滋阴润燥或活血化瘀、解毒通络为基本治则。脓疱型、关节病型、红皮病型及银屑病共病应中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102001","name":"血热内蕴证","clinic":"皮疹多呈点滴状，发展迅速，颜色鲜红，层层鳞屑，瘙痒剧烈，刮去鳞屑有点状出血；伴口干舌燥、咽喉疼痛，心烦易怒，便干溲赤；舌质红，苔薄黄，脉弦滑或数","treat":"清热凉血，解毒消斑","formula":"犀角地黄汤加减","formulaNames":["犀角地黄汤"]},{"t":"syn","sid":"s102002","name":"血虚风燥证","clinic":"病程较久，皮疹多呈斑片状，颜色淡红，鳞屑减少，干燥皲裂，自觉瘙痒；伴口咽干燥；舌质淡红，苔少，脉沉细","treat":"养血滋阴，润肤息风","formula":"当归饮子加减。风盛瘙痒明显者，加白鲜皮、乌梢蛇","formulaNames":["当归饮子"]},{"t":"syn","sid":"s102003","name":"气血瘀滞证","clinic":"皮损反复不愈，皮疹多呈斑块状，鳞屑较厚，颜色暗红；舌质紫暗有瘀点、瘀斑、脉涩或细缓","treat":"活血化瘀，解毒通络","formula":"桃红四物汤加减。病程日久，反复不愈者，加土茯苓、白花蛇舌草、蜈蚣；皮损肥厚色暗者，加三棱、莪术","formulaNames":["桃红四物汤"]},{"t":"syn","sid":"s102004","name":"湿毒蕴积证","clinic":"皮损多发生在腋窝、腹股沟等皱褶部位，红斑糜烂有渗出，痂屑黏厚，瘙痒剧烈，或表现为掌跖红斑、脓疱、脱皮；或伴关节酸痛、肿胀，下肢沉重；舌质红，苔黄腻，脉滑","treat":"清利湿热，解毒通络","formula":"萆薢渗湿汤加减。脓疱泛发者，加蒲公英、紫花地丁、半枝莲；关节肿痛明显者，加羌活、独活、秦艽、忍冬藤；瘙痒剧烈者，加白鲜皮、地肤子","formulaNames":["萆薢渗湿汤"]},{"t":"syn","sid":"s102005","name":"风寒湿痹证","clinic":"皮疹红斑不鲜，鳞屑色白而厚，抓之易脱，关节肿痛，活动受限，甚至僵硬畸形；伴形寒肢冷；舌质淡，苔白腻，脉濡滑","treat":"祛风除湿，散寒通络","formula":"独活寄生汤合桂枝芍药知母汤加减","formulaNames":["独活寄生汤","桂枝芍药知母汤"]},{"t":"syn","sid":"s102006","name":"火毒炽盛证","clinic":"全身皮肤潮红、肿胀，大量脱皮，或有密集小脓疱，伴局部灼热痒痛；壮热畏寒，头身疼痛、口渴欲饮、便干溲赤；舌质红绛，苔黄腻，脉弦滑数","treat":"清热泻火，凉血解毒","formula":"清瘟败毒饮加减","formulaNames":["清瘟败毒饮"]},{"t":"p","x":"2.外治疗法寻常型进行期皮损宜用温和之剂，可用黄连膏外搽，每日1次；寻常型静止期、消退期皮损可用内服煎剂的药渣煎水，待温洗浴浸泡患处，再以黄连膏外搽，亦可采用中药药浴熏洗疗法；"},{"t":"p","x":"红皮病型、脓疱型可用紫草油外搽，每日2次。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺疗法"},{"t":"p","x":"体针：进行期不宜采用，适于静止期、退行期。取穴大椎、肺俞、曲池、合谷、血海、三阴交，头面部加风池、迎香，下肢加足三里、丰隆。"},{"t":"p","x":"中等强度刺激，留针半小时，每日1次，10次为1个疗程，症状好转后改为隔日1次。耳针：取穴肺、神门、内分泌、心、大肠穴等，耳穴埋针或贴压。"},{"t":"p","x":"(2)游走罐适合斑块肥厚性皮损。"},{"t":"p","x":"(3)西医治疗常选用抗生素、维生素类、维A酸类、免疫抑制剂、免疫调节剂、生物制剂及紫外光照射等疗法。"}]}],"entries":["e0564","e0565","e0566","e0567","e0568","e0569","e0570","e0571"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.预防感染和外伤。2.进行期或红皮病型不宜用刺激性强的药物，忌热水洗浴。"}],"entries":["e0572"]}]},{"id":"d1021","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"风热疮","displayName":"风热疮","parentId":"","printedPage":173,"pdfPage":188,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"风热疮是一种斑疹色红如玫瑰、脱屑如糠秕的急性自限性皮肤病。"},{"t":"p","x":"其临床特点是初发时多在躯干部先出现玫瑰红色母斑，其长轴与皮纹一致，上有糠秕样鳞屑，继则分批出现较多、形态相仿而较小的子斑。好发于青中年，春秋季多见。"},{"t":"p","x":"有自限性，一般4～6周可自行消退，但也有少数患者病程长达2～3个月，甚至更长时间。中医文献对本病早有记载。"},{"t":"p","x":"《外科秘录》称“风热疮”。《外科正宗》称“风癣”。"},{"t":"p","x":"本病相当于西医学的玫瑰糠疹。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由各种诱因致肌肤郁闭，腠理闭塞而发病。1.外感风热，郁闭肌肤风热外感，郁滞肌肤腠理，不得宣泄而发。"},{"t":"p","x":"2.血分有热，化燥生风过食辛辣炙煿，或情志抑郁化火，导致血分蕴热，热伤阴液而化燥生风，外泛肌肤而成。西医学认为，本病病因尚未明确，多认为与病毒感染有关。"}],"entries":["e0573","e0574"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)好发年龄与季节好发于青中年，春秋季多见。"},{"t":"h","lv":3,"x":"(2)好发部位好发于躯干及四肢近端。"},{"t":"p","x":"(3)皮损特点初发为一个如指甲盖大小或稍大的圆形或椭圆形的淡红色或黄红色鳞屑斑，称为原发斑或母斑。"},{"t":"p","x":"母斑出现1～2周后，随即出现多数与母斑相似而形状较小的红斑，称为子斑或继发斑。皮损或横或斜，椭圆形，长轴与皮纹走行一致，中心略有细微皱纹，边缘不整，略似锯齿状，表面附有少量糠秕状细小鳞屑，多数孤立不相融合。"},{"t":"p","x":"斑疹颜色不一，自鲜红至褐色、褐黄或灰褐色不等。"},{"t":"p","x":"(4)自觉症状有不同程度的瘙痒，部分患者初起可伴有周身不适、头痛、咽痛、轻度发热、颈或腋下臖核肿大等全身症状。"},{"t":"p","x":"(5)病程本病预后良好，一般经4～6周可自然消退，亦有迁延至2～3个月，甚至更长一段时间才痊愈者。"},{"t":"p","x":"愈后一般不复发。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-23)"},{"t":"table","img":"img/tab/t1023.jpg","cap":"表10-23风热疮与白疕、紫白癜风的鉴别"}],"entries":["e0575"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以疏风清热止痒为主要治法。初期以疏风清热为主，后期以养血活血为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102101","name":"风热蕴肤证","clinic":"发病急骤，皮损呈圆形或椭圆形淡红色斑片，中心有细微皱纹，表面有少量糠秕状鳞屑；伴心烦口渴，大便干，尿微黄；舌红，苔白或薄黄，脉浮数","treat":"疏风清热止痒","formula":"消风散加减","formulaNames":["消风散"]},{"t":"syn","sid":"s102102","name":"风热血燥证","clinic":"皮疹为鲜红或紫红色斑片，鳞屑较多，皮损范围大，瘙痒较剧，伴有抓痕、血痂等；舌红，苔少，脉弦数","treat":"清热凉血，养血润燥","formula":"凉血消风散加减","formulaNames":["凉血消风散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)皮损早期用三黄洗剂外搽，中后期外涂黄连膏，每天2～3次。"},{"t":"p","x":"(2)用苦参、蛇床子、黄柏、生大黄各30g，生甘草10g，煎汤外洗患处。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺疗法取穴合谷、曲池、大椎、肩髃、肩井、血海、足三里，宜泻法，留针10～15分钟，每日1次，10次为1个疗程。"},{"t":"p","x":"(2)西医治疗瘙痒明显者可口服抗组胺药物，外用炉甘石洗剂等止痒药物；"},{"t":"p","x":"UVB照射可明显缩短病程。"}]}],"entries":["e0576","e0577","e0578","e0579","e0580"]},{"title":"预防与调护","blocks":[{"t":"p","x":"保持心情舒畅，不食辛辣及鱼腥发物。"}],"entries":["e0581"]}]},{"id":"d1022","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"紫癜风","displayName":"紫癜风","parentId":"","printedPage":174,"pdfPage":189,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"紫癜风是一种特发性炎症性皮肤病。"},{"t":"p","x":"其临床特点是以紫红色的多角形扁平丘疹为典型皮损，表面有蜡样光泽，常伴有黏膜损害。好发于成年人，病程为慢性。"},{"t":"p","x":"本病相当于西医学的扁平苔藓。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生总由内因、外因致病邪气相合，气血凝滞，蕴阻皮肤、黏膜而成。1.外因多为感受风湿热之邪，搏于肌肤所致。"},{"t":"p","x":"2.久病血虚生风生燥，或肝肾阴虚，肌肤失于濡养而成。3.久病不愈，肝气郁滞，气滞血瘀，致皮损呈苔藓样斑片。"},{"t":"p","x":"西医学认为，本病病因尚不清楚，可能与免疫、遗传、病毒感染、神经精神因素、某些药物等有关。"}],"entries":["e0582","e0583"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现好发于四肢屈侧，病程慢性，易反复发作。"},{"t":"p","x":"典型皮损为高起的紫红色多角形扁平丘疹，粟粒至绿豆大小或更大，境界清楚，表面有蜡样薄膜，可见白色光泽小点或细浅的白色网状条纹(Wickham纹)，为特征性皮损。"},{"t":"p","x":"病程中皮疹逐渐增多并可相互融合，呈苔藓状斑片，周围可有散在皮疹，但各个皮疹大多仍保持其原发固有的形态特点。急性期搔抓后可出现线状串珠形同形反应。"},{"t":"p","x":"常伴有不同程度的瘙痒。黏膜损害较常见，以口腔及外阴为主，可单发于黏膜，亦可与皮肤同时并发，表现为乳白色斑点，斑细小孤立，或排成环状、线状及不规则的网状。"},{"t":"p","x":"发生于口腔者多见于与臼齿相对的颊黏膜处。口腔黏膜及口唇、阴唇部扁平苔藓易继发癌变。"},{"t":"p","x":"另外，头皮损害可造成永久性脱发，甲受累可引起甲板增厚或变薄，甚至脱甲。临床上可分为多种亚型，如急性泛发性扁平苔藓、慢性局限性扁平苔藓、色素型扁平苔藓、肥厚型扁平苔藓及大疱型扁平苔藓等。"},{"t":"p","x":"(2)辅助检查组织病理有特征性，表现为表皮角化过度，颗粒层楔形增厚，棘层不规则增厚，表皮突呈锯齿状，基底细胞液化变性。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-24)"},{"t":"table","img":"img/tab/t1024.jpg","cap":"表10-24紫癜风与牛皮癣、原发性皮肤淀粉样变的鉴别"}],"entries":["e0584"]},{"title":"治疗","blocks":[{"t":"p","x":"本病初期以疏风除湿、清热止痒为主，后期以养血滋阴、活血化瘀为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102201","name":"风湿热证","clinic":"皮疹广泛，为紫红色扁平丘疹，自觉瘙痒；多并发黏膜损害，甚或出现糜烂、溃疡；可伴乏力纳呆；舌质红，苔薄腻，脉濡或数","treat":"祛风止痒，清热燥湿","formula":"消风散加减","formulaNames":["消风散"]},{"t":"syn","sid":"s102202","name":"血虚风燥证","clinic":"皮肤干燥，皮疹暗红，或融合成片状、环状、线状等，瘙痒较剧；伴咽干鼻燥；舌红少苔，脉沉细","treat":"养血滋阴，润肤息风","formula":"当归饮子加减","formulaNames":["当归饮子"]},{"t":"p","x":"舌红少苔，脉沉细。治法：养血滋阴，润肤息风。"},{"t":"syn","sid":"s102203","name":"气滞血瘀证","clinic":"病程较长，皮疹融合成肥厚性斑片，色褐红或紫红色，皮肤粗糙，瘙痒明显；舌质紫或边有瘀点，脉涩","treat":"行气活血，解毒止痒","formula":"逍遥散合桃红四物汤加减","formulaNames":["逍遥散","桃红四物汤"]},{"t":"syn","sid":"s102204","name":"肝肾阴虚证","clinic":"皮疹较局限，颜色较暗，或中央萎缩；若阴虚湿热下注，则皮疹多发于阴部，以肛门、龟头等处为主；伴腰膝酸软；舌红少苔，脉沉细数","treat":"滋阴降火","formula":"知柏地黄丸加减","formulaNames":["知柏地黄丸"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)皮损瘙痒明显者，可外搽百部酊。"},{"t":"p","x":"(2)皮损泛发者，用三黄洗剂外搽。"},{"t":"p","x":"(3)黏膜溃疡者，可用锡类散外吹或外涂患处。"},{"t":"p","x":"亦可用金银花30g，生甘草10g，煎水漱口或湿敷。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺疗法"},{"t":"p","x":"体针：主穴取曲池、血海，备用穴取合谷、三阴交、阿是穴。中等强度刺激，每日1次，留针15～30分钟。"},{"t":"p","x":"耳针：取穴肺、神门、肾上腺、皮质下等处或敏感点，留针或埋针。梅花针：皮损肥厚者亦可用七星针在患处来回击刺，以少量出血为宜，每日1次。"},{"t":"p","x":"(2)西医治疗瘙痒甚者可用抗组胺药内服。"},{"t":"p","x":"病情严重或顽固难愈者可酌情使用激素、免疫抑制剂或羟氯喹。"}]}],"entries":["e0585","e0586","e0587","e0588","e0589","e0590","e0591"]},{"title":"预防与调护","blocks":[{"t":"p","x":"勿用热水烫洗或过度搔抓，以免皮损产生同形反应而扩散。"}],"entries":["e0592"]}]},{"id":"d1023","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"白驳风","displayName":"白驳风","parentId":"","printedPage":176,"pdfPage":191,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"白驳风是指皮肤出现大小不同、形态各异的白斑为主要临床表现的后天性局限性色素脱失性皮肤病。"},{"t":"p","x":"其临床特点是皮肤白斑与周围正常皮肤的交界处有色素沉淀圈，边界清楚；亦可泛发全身。本病为慢性病程，易诊难治。"},{"t":"p","x":"深肤色人群较浅肤色者发病率高。“白癜”之名首见于《诸病源候论·白癜候》，曰：“白癜者，面及颈项、身体皮肉色变白，与肉色不同，亦不痒痛，谓之白癜。"},{"t":"p","x":"中医文献中又称之为“斑白”“斑驳”等。本病相当于西医学的白癜风。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由气血失和、脉络瘀阻所致。1.肝郁气滞情志内伤，肝气郁结，气机不畅，复感风邪，搏于肌肤。"},{"t":"p","x":"2.肝肾不足素体肝肾虚弱，或亡精失血，伤及肝肾，致肝肾不足，外邪侵入，郁于肌肤。3.气滞血瘀跌打损伤，化学灼伤，络脉瘀阻，毛窍闭塞，肌肤腠理失养，酿成白斑。"},{"t":"p","x":"西医学认为，本病发病原因不明。具有遗传素质的个体在多种因素刺激下，免疫、代谢等功能紊乱、进而引起酪氨酸酶系统活性受抑、自身黑素细胞遭到破坏，最终导致皮肤色素局限性脱失。"}],"entries":["e0593","e0594"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现皮损呈白色或乳白色斑点或斑片，逐渐扩大，边界清楚，周边色素常反见增加，患处毛发亦可变白。"},{"t":"p","x":"皮损大小不等，形态各异，常融合成片。本病男女皆可罹患，可发于任何年龄、任何部位，尤以暴露及摩擦损伤部位多见，可对称或单侧分布，亦可沿神经走行呈节段性分布。"},{"t":"p","x":"泛发全身者可仅存少许正常皮肤。患处皮肤光滑，无脱屑、萎缩等变化，无明显自觉症状，有的皮损中心可出现色素岛状褐色斑点。"},{"t":"p","x":"进展期正常皮肤可出现“同形反应”，病程慢性迁延，有时可自行好转或消退。"},{"t":"p","x":"(2)辅助检查皮肤病理检查显示表皮内黑素细胞及黑素颗粒减少或缺失。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-25)"},{"t":"table","img":"img/tab/t1025.jpg","cap":"表10-25白驳风与单纯糠疹、花斑癣、贫血痣的鉴别"}],"entries":["e0595"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以调和气血、疏通脉络为治则。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102301","name":"肝郁气滞证","clinic":"白斑散在渐起，数目不定；伴有心烦易怒，胸胁胀痛，夜寐不安，女子月经不调；舌质正常或淡红，苔薄，脉弦","treat":"疏肝理气，活血祛风","formula":"逍遥散加减。发于头面者，加蔓荆子、菊花；发于下肢者，加木瓜、牛膝","formulaNames":["逍遥散"]},{"t":"syn","sid":"s102302","name":"肝肾不足证","clinic":"多见于体虚或有家族史的患者。病史较长，白斑局限或泛发；伴头晕耳鸣，失眠健忘，腰膝酸软；舌质红，少苔，脉细弱","treat":"滋补肝肾，养血祛风。9-","formula":"六味地黄丸加减","formulaNames":["六味地黄丸"]},{"t":"p","x":"病史较长，白斑局限或泛发；伴头晕耳鸣，失眠健忘，腰膝酸软；舌质红，少苔，脉细弱。治法：滋补肝肾，养血祛风。"},{"t":"syn","sid":"s102303","name":"气血瘀滞证","clinic":"多有外伤、病史缠绵。白斑局限或泛发，边界清楚、局部可有刺痛；舌质紫暗或有瘀斑、瘀点、苔薄白、脉涩","treat":"活血化瘀，通经活络","formula":"通窍活血汤加减。跌打损伤后而发者，加乳香、没药；局部有刺痛者，加制鬼箭羽、白芷；发于下肢者、加牛膝、木瓜；病久者，加苏木、补骨脂","formulaNames":["通窍活血汤"]},{"t":"p","x":"2.外治疗法30%补骨脂酊外用，同时可配合日光照射5～10分钟，或紫外线照射，每日或隔日1次。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医治疗治疗核心：分期控制进展(激素/免疫调节剂)，并促进复色(NB-UVB/308nm激光)；稳定期可选移植手术，泛发型>50%可脱色治疗。"},{"t":"p","x":"(2)针刺疗法"},{"t":"p","x":"梅花针：局部叩刺。在白斑周围用较强刺激，有防止皮疹扩大的作用，可配合外用药涂搽，每日1次。"},{"t":"p","x":"耳针：取肺、肾、内分泌、肾上腺，每次选2～3穴，单耳埋针，双耳交替，每周轮换。火针疗法：用于静止期白斑。"}]}],"entries":["e0596","e0597","e0598","e0599","e0600"]},{"title":"预防与调护","blocks":[{"t":"p","x":"可进行适当的日光浴及理疗，要注意光照的强度和时间，并在正常皮肤上搽避光剂或盖遮挡物，以免晒伤。"}],"entries":["e0601"]}]},{"id":"d1024","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"黧黑斑","displayName":"黧黑斑","parentId":"","printedPage":178,"pdfPage":193,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"黧黑斑是指由于皮肤色素沉着而在面部呈现局限性褐色斑的皮肤病。"},{"t":"p","x":"其临床特点是色斑对称分布，大小不定，形状不规则，无自觉症状，日晒后加重。本病好发于青中年女性，尤以孕妇或经血不调的妇女为多，男性亦可发病，部分患者可伴有其他慢性病史。"},{"t":"p","x":"黧黑斑之病名首见于《外科正宗·女人面生黧黑斑》，曰：“黧黑斑者，水亏不能制火，血弱不能华肉，以致火燥，结成黑斑，色枯不泽。宜朝服肾气丸，以滋化源，早晚以玉容丸洗之，兼戒忧思、动火、劳伤，日久渐退。"},{"t":"p","x":"本病属中医学“面尘”的范畴，因肝病引起者称为“肝斑”，因妊娠而发病者称为“妊娠斑”。本病相当于西医学的黄褐斑。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多与肝、脾、肾三脏关系密切，气血不能上荣于面为主要病机。1.肝郁气滞情志不畅导致肝郁气滞，气郁化热，熏蒸于面，灼伤阴血而生。"},{"t":"p","x":"2.肝肾不足本病女性患者较多，多为冲任失调，肝肾不足，水火不济，虚火上炎所致。3.脾虚湿蕴饮食不节，忧思过度，损伤脾胃，脾失健运，湿热内生，熏蒸而致病。"},{"t":"p","x":"4.气滞血瘀一些慢性疾病致营卫失和，气血运行不畅，气滞血瘀，面失所养而成。西医学认为，本病多与雌激素和孕激素在体内增多，刺激黑素细胞分泌黑素和促进黑色素的沉着堆积有关。"}],"entries":["e0602","e0603"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现男女均可发生，尤以青中年女性多见，皮损夏重冬轻。"},{"t":"p","x":"如发生于孕妇，多开始于孕后2～5个月，分娩后逐渐消退，但也有不消退者；皮损为淡褐色至深褐色、淡黑色斑片，大小不等、形状各异，孤立散在或融合成片、边缘较明显，一般多呈蝴蝶状。"},{"t":"p","x":"对称发生于颜面，尤以两颊、额部、鼻、唇及颏等处多见；无自觉症状，病程不定，慢性经过。"},{"t":"h","lv":3,"x":"(2)辅助检查皮肤组织病理检查显示表皮中色素过度沉着。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-26)"},{"t":"table","img":"img/tab/t1026.jpg","cap":"表10-26黄褐斑与雀斑、艾迪生病、瑞尔黑变病的鉴别"}],"entries":["e0604"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以疏肝、健脾、补肾、化瘀为治则。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102401","name":"肝郁气滞证","clinic":"多见于女性，斑色深褐，弥漫分布；伴有烦躁不安，胸胁胀满，经前乳房胀痛，月经不调，口苦咽干；舌质红，苔薄，脉弦细","treat":"疏肝理气，活血消斑","formula":"逍遥散加减。斑色深褐而面色晦暗者，加桃仁、红花、益母草","formulaNames":["逍遥散"]},{"t":"syn","sid":"s102402","name":"肝肾不足证","clinic":"斑色褐黑，面色晦暗；伴有头晕耳鸣，腰膝酸软，失眠健忘，五心烦热；舌质红，少苔，脉细","treat":"补益肝肾，滋阴降火","formula":"六味地黄丸加减。褐斑日久色深者，加丹参、僵蚕","formulaNames":["六味地黄丸"]},{"t":"syn","sid":"s102403","name":"脾虚湿蕴证","clinic":"斑色灰褐，状如尘土附着；伴有疲乏无力，纳呆困倦，月经色淡，白带量多；舌质淡胖边有齿痕，苔白腻，脉濡或细","treat":"健脾益气，祛湿消斑","formula":"参苓白术散加减","formulaNames":["参苓白术散"]},{"t":"syn","sid":"s102404","name":"气滞血瘀证","clinic":"斑色灰褐或黑褐；多伴有慢性肝病病史，或月经色暗有血块，或痛经；舌质暗红、有瘀斑，苔薄，脉涩","treat":"理气活血，化瘀消斑","formula":"桃红四物汤加减。病程长者，加僵蚕、白芷","formulaNames":["桃红四物汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)白附子、白芷、滑石各250g，共研细末，蘸取适量粉末，均匀涂抹于面部，避免接触眼周及黏膜。"},{"t":"p","x":"(2)赤芍、丹参、桃仁、红花、白及、僵蚕、白丁香、白附子等份，研成粉末，加适当基质配制成中药面膜，每次敷于面部30分钟、每日1次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医治疗口服维生素C和维生素E。"},{"t":"p","x":"外用氢醌乳膏。"},{"t":"p","x":"(2)针刺疗法"},{"t":"p","x":"体针：取肝俞、肾俞、风池为主穴，迎香、太阳、曲池、血海为辅穴。肝郁加内关、太冲，脾虚加足三里、气海、肾虚加三阴交、阴陵泉。"},{"t":"p","x":"毫针刺入，留针20分钟，每日1次，10次为1个疗程。耳针：取内分泌、皮质下、热穴(位于耳甲腔、对耳屏内侧面及耳轮结节处)，消毒皮肤后用三棱针尖刺破至微出血，再以消毒棉球敷盖。"}]}],"entries":["e0605","e0606","e0607","e0608","e0609","e0610","e0611"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.注意防晒、避免使用劣质化妆品。2.保持心情舒畅、注意劳逸结合。"},{"t":"p","x":"3.多食含维生素C的蔬菜、水果。"}],"entries":["e0612"]}]},{"id":"d1025","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"粉刺","displayName":"粉刺","parentId":"","printedPage":180,"pdfPage":195,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"粉刺是一种以颜面、胸、背等处见丘疹顶端如刺状，可挤出白色碎米样粉汁为主的毛爽、皮脂腺的慢性炎症。"},{"t":"p","x":"其临床特点是丘疹、脓疱等皮疹多发于颜面、前胸、后背等处，常伴有皮脂溢出。多见于青春期男女。"},{"t":"p","x":"《素问·生气通天论》记载：“汗出见湿，乃生痤痱⋯⋯劳汗当风，寒薄为鲏，郁乃痤。”《医宗金鉴·外科心法要诀》对肺风粉刺记载曰：“此证由肺经血热而成，每发于面鼻，起碎疙瘩，形如黍屑，色赤肿痛，破出白粉汁。"},{"t":"p","x":"《外科大成》载：“肺风，由肺经血热，郁滞不行，而生酒刺也。宜枇杷清肺散；或用荷叶煮糊为丸，白滚水服；外用白矾末，酒化涂之。"},{"t":"p","x":"《疡医大全》载：“颠倒散：硫黄、大黄各等分，研末，凉水调敷。”中医文献中又称“肺风粉刺”“面疮”“酒刺”，俗称“青春疙瘩”“青春痘”。"},{"t":"p","x":"本病相当于西医学的痤疮。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病早期以肺热及肠胃湿热为主，晚期有痰瘀。1.肺经风热素体阳热偏盛，肺经蕴热，复受风邪，熏蒸面部而发。"},{"t":"p","x":"2.肠胃湿热过食辛辣、肥甘厚味，肠胃湿热互结，上蒸颜面而致。3.痰湿瘀滞脾气不足，运化失常，湿浊内停，郁久化热，热灼津液，煎炼成痰，湿热瘀痰凝滞肌肤而发。"},{"t":"p","x":"西医学认为，本病的发生主要与毛囊皮脂腺导管角化异常、皮脂分泌过多、微生物定植诱发局部炎症、炎症反应的相互作用密切相关。饮食、心理压力、睡眠质量等因素也可能影响粉刺的发生发展。"}],"entries":["e0613","e0614"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病好发于颜面、颈、胸背等处。"},{"t":"p","x":"皮损初起为针头大小的毛囊性丘疹，或为白头粉刺、黑头粉刺，可挤出白色或淡黄色脂栓，因感染而成红色小丘疹，顶端可出现小脓疱。愈后可留暂时性色素沉着或轻度凹陷性瘢痕。"},{"t":"p","x":"严重者称为聚合性痤疮，感染部位较深，出现紫红色结节、脓肿、囊肿，甚至破溃形成窦道和瘢痕，或呈橘皮样改变，常伴皮脂溢出。皮疹反复发生，常因饮食不节、月经前后而加重。"},{"t":"p","x":"自觉有轻度瘙痒，炎症明显时伴疼痛。病程长短不一，部分患者青春期后可逐渐痊愈。"},{"t":"p","x":"参照Pillsbury分类法及国际痤疮分级，该病根据皮损性质常分为3度4级，分别为：①轻度(I级)：皮损以粉刺为主；"},{"t":"p","x":"②中度(Ⅱ级)：以粉刺为主，炎性丘疹散发，局限于面部；"},{"t":"p","x":"③中重度(Ⅲ级)：皮损以大量炎性丘疹及脓疱为主，有结节，可发于面、颈、胸背部；"},{"t":"p","x":"④重度(IV级)：皮损以结节、囊肿为主，形成囊肿性痤疮或聚合性痤疮，伴有瘢痕形成。"},{"t":"h","lv":3,"x":"(2)辅助检查部分女性患者有性激素异常。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-27)"},{"t":"table","img":"img/tab/t1027.jpg","cap":"表10-27粉刺与酒齄鼻、职业性痤疮、颜面播散性粟粒性狼疮的鉴别"}],"entries":["e0615"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清热祛湿为基本治疗原则，或配合化痰散结、活血化瘀等，内、外治相结合。轻度及轻中度痤疮以外用药物治疗为主，中重度及重度痤疮在系统治疗的同时辅以外用药物治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102501","name":"肺经风热证","clinic":"丘疹色红，或有痒痛，或有脓疱；伴口渴喜饮，大便秘结，小便短赤；舌质红、苔薄黄，脉弦滑","treat":"疏风清肺","formula":"枇杷清肺饮加减。脓疱多者，加紫花地丁、白花蛇舌草；经前加重者、加香附、益母草、当归","formulaNames":["枇杷清肺饮"]},{"t":"syn","sid":"s102502","name":"肠胃湿热证","clinic":"颜面、胸背部皮肤油腻，皮疹红肿疼痛，或有脓疱；伴口臭、便秘、溲黄；舌质红、苔黄腻，脉滑数","treat":"清热除湿解毒","formula":"茵陈蒿汤加减。脓疱较多者、加白花蛇舌草、野菊花、金银花","formulaNames":["茵陈蒿汤"]},{"t":"syn","sid":"s102503","name":"痰湿瘀滞证","clinic":"皮疹颜色暗红，以结节、脓肿、囊肿、瘢痕为主，或见窦道，经久难愈；伴纳呆腹胀；舌质暗红，苔黄腻，脉滑","treat":"除湿化痰，活血散结","formula":"二陈汤合桃红四物汤加减。伴囊肿成脓者，加贝母、皂角刺、夏枯草；伴结节、囊肿难消者，加三棱、莪术、海藻、昆布","formulaNames":["二陈汤","桃红四物汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药湿敷：取马齿苋、紫花地丁、黄柏等中药水煎液湿敷，每日2次，每次湿敷20分钟。"},{"t":"p","x":"用于炎性丘疹、脓疱皮损，起到清热解毒、减轻炎症的作用。"},{"t":"p","x":"(2)中药面膜：取颠倒散(大黄、硫黄等量研细末)，用水或蜂蜜调成稀糊状，涂于皮损处，避免接触眼周及黏膜。"},{"t":"p","x":"30分钟后清水洗净，每晚1次。用于炎性丘疹、脓疱、结节、囊肿皮损，起到破瘀活血、清热散结的作用。"},{"t":"p","x":"(3)脓肿、囊肿、结节较甚者，可外敷金黄膏，每日2次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医治疗根据病情选择内服抗生素类、维A酸类、抗雄激素药等。"},{"t":"p","x":"抗生素以四环素类、大环内酯类使用最为广泛。配合外用维A酸类、抗菌药物等。"},{"t":"p","x":"女性痤疮患者根据病情需要选择抗雄激素类药物治疗。"},{"t":"p","x":"(2)物理与化学治疗主要包括光动力疗法、红蓝光治疗、激光与光子治疗、化学剥脱治疗(临床常用的剥脱剂主要包括果酸、水杨酸及复合酸)等，作为痤疮辅助或替代治疗及痤疮后遗症处理的选择。"},{"t":"p","x":"(3)针罐疗法"},{"t":"p","x":"火针：适用于皮损以白头粉刺、红色丘疹、脓丘疹及脓肿为主者；囊肿较大者，可使用小火罐拔脓。"},{"t":"p","x":"体针：取穴大椎、合谷、四白、太阳、下关、颊车。肺经风热证，加曲池、肺俞；"},{"t":"p","x":"肠胃湿热证，加大肠俞、足三里、丰隆；月经不调，加膈俞、三阴交。"},{"t":"p","x":"中等刺激，留针30分钟，每日1次，10次为1个疗程。耳针：取穴肺、内分泌、交感、脑点、面颊、额区。"},{"t":"p","x":"皮脂溢出，加脾；便秘，加大肠；月经不调，加子宫、肝。耳穴压豆，每次取穴4～5个，2～3天换豆1次，5次为1个疗程。"},{"t":"p","x":"刺络拔罐：可取大椎、肺俞等穴，用三棱针点刺放血后加拔罐3分钟，每周1～2次。"},{"t":"p","x":"耳尖点刺放血：在耳郭上选定耳尖穴或耳部的内分泌穴、皮质下穴，常规消毒后，用三棱针在耳尖穴上点刺，然后在点刺部位挤出瘀血6～8滴，每周治疗1～2次。"},{"t":"p","x":"(4)痤疮后遗症处理"},{"t":"p","x":"痤疮后红斑：可以选择强脉冲光、脉冲染料激光、非剥脱点阵激光(1440nm、1550nm、1565nm)及长脉冲1064nm Nd: YAG激光治疗。"},{"t":"p","x":"痤疮后色素沉着：外用改善色素类药物如维A酸类药物、熊果苷、左旋维生素C等。或采用果酸、强脉冲光及Q开关1064nm Nd:YAG激光治疗。"},{"t":"p","x":"痤疮后瘢痕：对于萎缩性瘢痕首选剥脱性点阵激光如二氧化碳点阵激光治疗，其次选择离子束或铒激光治疗。也可选用非剥脱点阵激光、微针、射频治疗；"},{"t":"p","x":"一些较大的凹陷性瘢痕，还可以选择钝针分离、填充或手术切除。对于增生性瘢痕与瘢痕疙瘩，目前多采用综合治疗，如激素局部封闭注射、激光治疗(染料激光、二氧化碳点阵激光)；痤疮导致的瘢痕疙瘩亦可以切除后局部放射治疗。"}]}],"entries":["e0616","e0617","e0618","e0619","e0620","e0621"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.经常用温水洗脸、配合温和洁面用品、皮脂较多时可每日洗2～4次。2.避免高糖、油腻饮食摄入，适当控制体重、规律作息、避免熬夜、注意防晒。"},{"t":"p","x":"3.不要滥用化妆品，有些粉质化妆品会堵塞毛孔，造成皮脂淤积而成粉刺。4.禁止用手挤压粉刺，以免炎症扩散，愈后遗留凹陷性瘢痕。"}],"entries":["e0622"]}]},{"id":"d1026","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"白屑风","displayName":"白屑风","parentId":"","printedPage":183,"pdfPage":198,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"白屑风是一种发生在头皮及颜面的慢性疾病，因白屑层层飞扬而定名为白屑风。"},{"t":"p","x":"颜面部以油性皮脂溢出为主要表现者，称为面游风。其临床特点以毛囊口棘状隆起、糠状鳞屑为特征，一般无自觉症状，或有轻度瘙痒，病程长，青壮年患者最多，或在乳儿期发生。"},{"t":"p","x":"《外科正宗·白屑风》中已有详细描述、如：“白屑风，多生于头面、耳项、发中，初起微痒，久则渐生白屑，叠叠飞起，脱而又生。此皆起于热体当风、风热所化。"},{"t":"p","x":"《外科真诠》则曰：“白屑风初生发内，延及面目，耳项燥痒，日久飞起白屑，脱去又生。由肌热当风，风邪侵入毛孔，郁久燥血，肌肤失养，化成燥症也。"},{"t":"p","x":"本病相当于西医学的脂溢性皮炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病主要因素体湿热内蕴，感受风邪所致。1.湿热上蒸湿为重浊之邪，常夹风、热等，以热为多，湿热互结，循经上行，加之恣食肥甘油腻、辛辣之品，以致脾胃运化失常，化湿生热，湿热蕴阻肌肤而成。"},{"t":"p","x":"2.风热血燥风热之邪外袭，郁久耗伤阴血，阴伤血燥；或平素血燥之体，复感风热之邪，血虚生风，风热燥邪蕴阻肌肤，肌肤失于濡养而致。"},{"t":"p","x":"西医学认为，本病与皮脂溢出过度及马拉色菌的定植与感染有关。精神因素、嗜食辛辣油腻、维生素B族缺乏、嗜酒等可加重本病。"}],"entries":["e0623","e0624"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"临床表现本病的皮疹分为干性与湿性。湿性白屑风：多见于青壮年，发生在皮脂腺丰富的头皮和颜面等处。"},{"t":"p","x":"皮肤表现为油腻发亮，手摸之有油黏的感觉，鼻部如涂上一层油，毛囊口扩大，能挤出黄白色的粉汁。头皮毛发油腻，或头屑多，瘙痒，继而头发稀疏、细软、脱落、秃顶。"},{"t":"p","x":"20～40岁最重。干性白屑风：多发于头皮部，头皮有堆叠飞起的油腻鳞屑，抓之如下雪样飘落，头发也可稀疏、变细、变软，容易折断和脱落。"},{"t":"p","x":"有不同程度的瘙痒。本病多病程缓慢，但常有急性发作。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-28)"},{"t":"table","img":"img/tab/t1028.jpg","cap":"表10-28白屑风与头皮白疕、白秃疮的鉴别"}],"entries":["e0625"]},{"title":"治疗","blocks":[{"t":"p","x":"根据本病皮疹干性与湿性的临床特点，干性者以养血润燥为主，湿性者以清热祛湿为主，内治、外治相结合。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102601","name":"湿热蕴结证","clinic":"皮损为潮红斑片，有油腻性痂屑，甚至糜烂、渗出；伴口苦口黏，脘腹痞满，小便短赤，大便臭秽；舌质红，苔黄腻，脉滑数","treat":"清热利湿、健脾和胃","formula":"龙胆泻肝汤加减","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s102602","name":"风热血燥证","clinic":"多发于头面部、为淡红色斑片，干燥、脱屑、瘙痒，或头皮瘙痒，头屑多，毛发干枯脱落；伴口干口渴，大便干燥；舌质偏红，苔薄白或黄，脉细数","treat":"祛风清热，养血润燥","formula":"消风散合当归饮子加减。皮损颜色较红者，加牡丹皮、金银花、青蒿；瘙痒较重者，加白鲜皮、刺蒺藜；皮损干燥明显者，加玄参、麦冬、天花粉","formulaNames":["消风散","当归饮子"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)干性皮损在头皮者，用白屑风酊外搽，每天3次。"},{"t":"p","x":"(2)干性皮损在面部者，用黄连膏薄涂，每天2次。"},{"t":"p","x":"(3)湿性皮损有少量渗出者，可用马齿苋、黄柏、大青叶、龙葵各30g(或任选单味药30g)、水煎滤渣，室温冷却后行局部冷湿敷，每次30分钟，每日2～3次；"},{"t":"p","x":"湿敷后外搽青黛膏。或用脂溢洗方(苍耳子30g，苦参15g，王不留行30g，明矾9g)煎水洗头。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西药全身治疗可口服维生素B、B等；"},{"t":"p","x":"瘙痒剧烈时可用抗组胺药；局部治疗以去脂、消炎、杀菌、止痒为主，常用药物有咪唑类、水杨酸等，如发于头皮部可选用2%酮康唑溶液外洗。"},{"t":"p","x":"(2)针灸疗法取合谷、曲池、大椎、血海、足三里等穴，施泻法，隔日1次。"}]}],"entries":["e0626","e0627","e0628","e0629","e0630"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.忌食荤腥、油腻，少食甘甜、辛辣及浓茶、咖啡、酒等，多食水果、蔬菜。2.避免搔抓、烫洗，不用刺激性强的洁面及洗头用品。"}],"entries":["e0631"]}]},{"id":"d1027","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"酒齄鼻","displayName":"酒齄鼻","parentId":"","printedPage":184,"pdfPage":199,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"酒齄鼻是以面部红斑和毛细血管扩张为特点的慢性皮肤病。其临床特点是鼻及颜面中央部持续性红斑和毛细血管扩张，伴丘疹、脓疱、鼻赘。"},{"t":"p","x":"《诸病源候论·酒候》云：“此由饮酒，热势冲面，而遇风冷之气相搏所生，故令鼻面生篮，赤疱匝匝然也。”因鼻色紫红如酒渣，故名酒齄鼻。"},{"t":"p","x":"中医文献又称之为“赤鼻”，俗称“红鼻头”“酒糟鼻”。本病相当于西医学的玫瑰痤疮，旧称酒渣鼻。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病早期往往为体内郁热，日久则为气滞血瘀。1.肺胃热盛肺胃积热上蒸，复遇风寒外袭，血瘀凝结而成。"},{"t":"p","x":"2.热毒蕴肤多发于嗜酒之人，酒气熏蒸，热毒凝结于鼻，复遇风寒之邪，交阻肌肤所致。3.气滞血瘀热毒日久瘀阻鼻面，气滞血瘀，毒邪聚而不散所致。"},{"t":"p","x":"西医学认为，本病可能是由多种因素诱导的以天然免疫和神经血管调节功能异常为主导的慢性炎症性疾病，与微生态失衡、皮肤屏障功能障碍亦相关。"}],"entries":["e0632","e0633"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病好发于面中部隆突部位，如颧部、颊部、眉间、颏部及鼻部等，部分可累及眼和眼周。"},{"t":"p","x":"主要表现：包括持续性红斑、阵发性潮红、丘疹、脓疱、毛细血管扩张、增生肥大。面部皮肤持续性红斑，可随外界刺激因素(如温度、日晒、情绪或辛辣刺激食物等)周期性加重或减轻，但不会完全自行消退，是诊断的必需条件。"},{"t":"p","x":"阵发性潮红可因触发因素在数秒至数分钟内发生，面颊部较为常见。丘疹、脓疱表现为圆顶状红色丘疹，针头大小的浅表脓疱，也可能会出现结节。"},{"t":"p","x":"毛细血管扩张在浅肤色患者中较多见。增生肥大主要表现为鼻部皮肤增厚、腺体增生和球状外观。"},{"t":"p","x":"次要表现：包括皮肤敏感症状、水肿、皮肤干燥、眼部症状。皮肤敏感症状包括灼热、刺痛、紧绷和瘙痒等，在阵发性潮红发作时更加明显。"},{"t":"p","x":"面部水肿可能伴发或继发于红斑或潮红。皮肤干燥则是大部分患者的表现，少部分可表现为皮肤油腻。"},{"t":"p","x":"眼部症状可表现为眼睛异物感、光敏、视物模糊、灼热刺痛、干燥或瘙痒等。"},{"t":"p","x":"(2)辅助检查无特殊检查，需结合临床表现综合诊断。"},{"t":"p","x":"必要时可结合皮肤镜、组织病理检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-29)"},{"t":"table","img":"img/tab/t1029.jpg","cap":"表10-29酒齄鼻与粉刺、面油风的鉴别"}],"entries":["e0634"]},{"title":"治疗","blocks":[{"t":"p","x":"本病以清泄肺胃积热、理气活血化瘀为基本治疗原则。肥大增生者可采用手术治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102701","name":"肺胃热盛证","clinic":"红斑多发于鼻尖或两翼，压之退色；常嗜酒，伴口干、便秘；舌质红，苔薄黄，脉弦滑","treat":"清泄肺胃积热","formula":"枇杷清肺饮加减。嗜酒者，加葛花","formulaNames":["枇杷清肺饮"]},{"t":"syn","sid":"s102702","name":"热毒蕴肤证","clinic":"在红斑上出现痤疮样丘疹、脓疱，毛细血管扩张明显，局部灼热；伴口干，便秘；舌质红，苔黄，脉数","treat":"清热解毒凉血","formula":"黄连解毒汤合凉血四物汤加减。局部灼热者，加牡丹皮","formulaNames":["黄连解毒汤","凉血四物汤"]},{"t":"syn","sid":"s102703","name":"气滞血瘀证","clinic":"鼻部组织增生，呈结节状，毛孔扩大；舌质暗红，脉沉缓","treat":"活血化瘀散结","formula":"通窍活血汤加减。鼻部组织增生呈结节状者，加海藻、生山楂、王不留行、莪术","formulaNames":["通窍活血汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)鼻部有红斑、丘疹者，可选用颠倒散洗剂外搽，每天3次。"},{"t":"p","x":"(2)鼻部有脓疱者，可选用四黄膏外搽，每天2～3次。"},{"t":"p","x":"(3)肥大增生者，可先用三棱针刺破放血，再用颠倒散外敷。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医治疗内服四环素类抗生素、异维A酸等；"},{"t":"p","x":"外用甲硝唑、克林霉素、壬二酸等；可结合光电等物理治疗。"},{"t":"p","x":"(2)针刺疗法 ①取印堂、迎香、地仓、承浆、颧、大迎、合谷、曲池等穴。"},{"t":"p","x":"②局部以丘疹、脓疱为主，或以红斑及毛细血管扩张为主者，可采用火针治疗。"}]}],"entries":["e0635","e0636","e0637","e0638","e0639","e0640"]},{"title":"预防与调护","blocks":[{"t":"p","x":"避免肥甘厚腻、辛辣刺激、过冷过热等刺激及精神紧张。"}],"entries":["e0641"]}]},{"id":"d1028","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"油风","displayName":"油风","parentId":"","printedPage":186,"pdfPage":201,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"油风是一种头发突然发生斑块状脱落的慢性皮肤病。"},{"t":"p","x":"因头发脱落之处头皮光亮而得名。其临床特点是突然发生斑片状脱发，脱发区皮肤变薄，多无自觉症状。"},{"t":"p","x":"可发生于任何年龄，多见于青年，男女均可发病。《外科正宗·油风》云：“油风，乃血虚不能随气荣养肌肤，故毛发根空，脱落成片，皮肤光亮，痒如虫行，此皆风热乘虚攻注而然。"},{"t":"p","x":"本病俗称“鬼舐头”“鬼剃头”。本病相当于西医学的斑秃。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"肝肾不足，精血亏虚为脱发的主要病因，同时与血热生风、肝郁血燥、气血两虚等相关。脱发早期多实证，如过食辛辣、情志不遂致肝郁化火、血热风，或气滞血瘀、清窍失养，使发脱；"},{"t":"p","x":"脱发时间长、量大、面积广者多虚证，如久病产后气血两虚，或肝肾亏损致血不养发，毛发脱落。西医学认为，本病与遗传、情绪、应激、内分泌失调、自身免疫等因素有关。"}],"entries":["e0642","e0643"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现头发突然成片迅速脱落，脱发区皮肤光滑，边缘的头发松动，容易拔出，拔出时可见发根近端萎缩，呈上粗下细的感叹号(!)样。"},{"t":"p","x":"脱发区呈圆形、椭圆形或不规则形。数目不等，大小不一，可相互连接成片，或头发全部脱光而称为全秃。"},{"t":"p","x":"严重者眉毛、胡须、腋毛、阴毛甚至毳毛等全身毛发脱落，称为普秃。一般无自觉症状，常在过度劳累、睡眠不足、精神紧张或受刺激后发生。"},{"t":"p","x":"病程较长，可持续数月或数年，多数能自愈，但也有反复发作或边长边脱者。"},{"t":"p","x":"(2)辅助检查部分较严重脱发患者可检出甲状腺功能及免疫功能异常、自身抗体、抗核抗体等，排除相关并发疾病。"},{"t":"p","x":"必要时，可进行真菌镜检和梅毒螺旋体抗体检测等，以除外感染性疾病所致脱发。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-30)"},{"t":"table","img":"img/tab/t1030.jpg","cap":"表10-30油风与白屑风、白秃疮、肥疮的鉴别"}],"entries":["e0644"]},{"title":"治疗","blocks":[{"t":"p","x":"本病实证以清热通瘀为主，虚证以补摄为要。选用适当的外治或其他疗法，能促进毛发生长。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102801","name":"血热风燥证","clinic":"突然脱发成片，偶有头皮瘙痒，或伴头部烘热；心烦易怒，急躁不安；舌质红，苔薄，脉弦","treat":"凉血息风，养阴护发","formula":"四物汤合六味地黄汤加减。若风热偏胜，脱发迅猛者，方用神应养真丹加减；瘙痒明显者，加白鲜皮；头部烘热者，加地骨皮","formulaNames":["四物汤","六味地黄汤"]},{"t":"syn","sid":"s102802","name":"气滞血瘀证","clinic":"病程较长，头发脱落前先有头痛或胸胁疼痛等症；伴夜多恶梦，烦热难眠；舌质暗红，有瘀点、瘀斑，苔薄，脉沉细","treat":"通窍活血，祛瘀生发","formula":"通窍活血汤加减。头痛者，加白芷、藁本、天麻","formulaNames":["通窍活血汤"]},{"t":"syn","sid":"s102803","name":"气血两虚证","clinic":"多在病后或产后头发呈斑块状脱落，并呈渐进性加重，范围由小而大，毛发稀疏枯槁，触摸易脱；伴唇白，心悸，气短懒言，倦怠乏力；舌质淡，舌苔薄白，脉细弱","treat":"益气补血，养血生发","formula":"八珍汤加减。乏力、气短明显者，加黄芪","formulaNames":["八珍汤"]},{"t":"syn","sid":"s102804","name":"肝肾不足证","clinic":"病程日久，平素头发焦黄或花白，发病时呈大片均匀脱落，甚或全身毛发脱落；伴头晕，耳鸣，目眩，腰膝酸软；舌质淡，苔薄，脉细","treat":"滋补肝肾，养阴生发","formula":"七宝美髯丹加减。头晕、耳鸣者，加天麻；腰膝酸软者，加杜仲、桑寄生","formulaNames":["七宝美髯丹"]},{"t":"p","x":"头晕、耳鸣者，加天麻；腰膝酸软者，加杜仲、桑寄生。2.外治疗法5%～10%斑蝥酊或10%补骨脂酊或10%辣椒酊外搽。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西医治疗 ①可口服复方甘草酸苷，迅速而广泛的脱发可考虑糖皮质激素治疗，近年来发现JAK抑制剂亦有一定疗效。"},{"t":"p","x":"②局部治疗可外用糖皮质激素乳膏或局部注射糖皮质激素，米诺地尔酊剂涂搽患部等。"},{"t":"p","x":"(2)针刺疗法取百会、头维、生发穴。"},{"t":"p","x":"可在脱发区和沿头皮足太阳膀胱经循行部位用梅花针移动叩击。局部亦可采用火针治疗。"}]}],"entries":["e0645","e0646","e0647","e0648","e0649","e0650"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持心情舒畅、睡眠充足、避免烦躁、忧愁、动怒等。2.加强营养、多食富含维生素的食物、纠正偏食，忌食辛辣刺激性食物。"}],"entries":["e0651"]}]},{"id":"d1029","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"红蝴蝶疮","displayName":"红蝴蝶疮","parentId":"","printedPage":188,"pdfPage":203,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"红蝴蝶疮是一种可累及皮肤和全身多脏器的自身免疫性疾病。"},{"t":"p","x":"本病是一组病谱性疾病，病谱两端为皮肤型红蝴蝶疮和系统性红蝴蝶疮。其临床特点：皮肤型红蝴蝶疮多为慢性局限性，主要为皮肤损害；"},{"t":"p","x":"系统性红蝴蝶疮除有皮肤损害外，常同时累及全身多系统、多脏器，病变呈进行性经过，预后较差。本病多见于15～40岁女性。"},{"t":"p","x":"古代文献没有对其病名的论述，根据症状描述多归为“阴阳毒”“蝴蝶斑”“日晒疮”“痹病”“水肿”等范畴。"},{"t":"p","x":"《金匮要略·百合狐惑阴阳毒病脉证治》曰：“阳毒之为病，面赤斑斑如锦纹、咽喉痛，唾脓血⋯⋯升麻鳖甲汤主之”;“阴毒之为病，面目青，身痛如被杖，咽喉痛⋯⋯升麻鳖甲汤去雄黄、蜀椒主之。"},{"t":"p","x":"这些症状和红蝴蝶疮常见的皮疹、关节痛、发热、咽痛、出血等症状相似。本病相当于西医学的红斑狼疮。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病总由先天禀赋不足、肝肾亏虚而成。精血不足，虚火上炎，兼因腠理不密，日光暴晒，外热入侵，热毒入里，二热相搏，瘀阻脉络，内伤脏腑，外伤肌肤而发病。"},{"t":"p","x":"热毒蕴结肌肤，上泛头面，则面生盘状红蝴蝶疮；热毒内传脏腑，瘀阻于肌肉、关节，则发为系统性红蝴蝶疮。"},{"t":"p","x":"在系统性红蝴蝶疮病程中，或因热毒炽盛，燔灼营血，则可引起急性发作而见高热、肌肉酸楚、关节疼痛；或邪热渐退，则又多表现为低热、乏力、唇干舌红、盗汗等阴虚火旺、肝肾不足证候；"},{"t":"p","x":"或因肝气郁结，久而化火，致气血凝滞；或因病久气血两虚，致心阳不足。"},{"t":"p","x":"疾病后期每多阴损及阳，累及于脾，以致脾肾阳虚，水湿泛滥，膀胱气化失权而见便溏溲少、四肢清冷、下肢甚至全身浮肿等症。在整个发病过程中，热毒炽盛之证可相继或反复出现，甚或表现为热毒内陷、热盛动风。"},{"t":"p","x":"西医学认为，红斑狼疮病因复杂，与遗传、性激素、环境(如紫外线照射、药物、感染)等多种因素有关。"}],"entries":["e0652","e0653"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现本病临床表现存在多样性。"},{"t":"p","x":"1)皮肤型红斑狼疮(cutaneous lupus erythematosus, CLE)根据病程可分为急性、亚急性、慢性3类。"},{"t":"p","x":"急性皮肤型红斑狼疮(acute cutaneous lupus erythematosus,ACLE)：包括局限性和泛发性ACLE。"},{"t":"p","x":"局限性ACLE表现为面颊和鼻背融合性水肿性红斑(蝶形)，可累及额部、颈部、眼眶和胸前V形区(曝光部位)。泛发性ACLE表现为全身对称分布的融合性斑疹、丘疹，夹杂紫癜或瘀斑，颜色深红或鲜红，可发生于身体任何部位。"},{"t":"p","x":"口腔和鼻腔黏膜可见浅溃疡。亚急性皮肤型红斑狼疮(subacute cutaneous lupus erythematosus, SCLE)：好发于暴露部位如上背、肩、手臂伸侧、胸前V形区，常伴高度光敏感。"},{"t":"p","x":"根据皮损特点可分为丘疹鳞屑型和环形红斑型。前者表现为大小不一的红斑、斑块或丘疹，上覆薄层非黏着性鳞屑；"},{"t":"p","x":"后者表现为环形、多环形或弧形外观，为轻度隆起的水肿性红斑。"},{"t":"p","x":"慢性皮肤型红斑狼疮(chronic cutaneous lupus erythematosus, CCLE)：包括局限性和播散性盘状红斑狼疮、疣状红斑狼疮、肿胀性红斑狼疮、深在性红斑狼疮、冻疮样红斑狼疮、Blaschko线状红斑狼疮等。"},{"t":"p","x":"在CLE中盘状红斑狼疮(discoid lupus erythematosus,DLE)占50%～85%，以下主要描述DLE的临床表现。局限性DLE最常发生于头皮、面部、耳部及口唇。"},{"t":"p","x":"典型表现为境界清楚的盘状红斑或斑块，表面覆有黏着性鳞屑，剥离鳞屑可见扩张的毛囊口，形成毛囊角栓，外周色素沉着，中央色素减退、轻度萎缩，并可产生萎缩性瘢痕。发生于头皮、眉毛处的DLE可导致不可逆的瘢痕性脱发。"},{"t":"p","x":"除头面部外，DLE皮损还可累及躯干和四肢，此时称为播散性DLE，且发展为系统性红斑狼疮的风险更高。少数发生于口唇黏膜的DLE皮损经久不愈，易发展为鳞癌。"},{"t":"p","x":"患者多无自觉症状，少数可有轻度瘙痒，部分患者可有光敏、轻度关节痛等症状。"},{"t":"p","x":"2)系统性红斑狼疮(systemic lupus erythematosus, SLE)多见于中青年女性，男女之比为1:10～1:12。"},{"t":"p","x":"本病早期表现多样、症状多不明显。初起可单个器官受累，也可多个系统同时被侵犯。"},{"t":"p","x":"皮肤是最常受累的器官，SLE的皮肤黏膜损害呈现多样性，主要表现为ACLE、SCLE和CCLE的皮疹特点。"},{"t":"p","x":"SLE患者常伴有发热、乏力、纳差、口腔溃疡、关节痛、肺间质病变、浆膜炎、血液及肾脏受累等系统症状，少数情况下可出现呼吸、循环功能障碍或神经精神症状。"},{"t":"p","x":"少数患者红斑狼疮样表现还可能由某些药物诱导发生，如普鲁卡因酰胺、肼苯哒嗪、质子泵抑制剂、抗肿瘤坏死因子α生物制剂等。紫外线照射、某些化妆品、染发剂和纹眉剂等亦可能诱发红斑狼疮加重病情。"},{"t":"h","lv":3,"x":"(2)辅助检查"},{"t":"p","x":"1)一般检查血常规检查示中度贫血，约56%的患者白细胞及血小板减少，血沉加快。"},{"t":"p","x":"尿中有蛋白及红细胞、白细胞和管型；蛋白电泳显示白蛋白减少，γ球蛋白、α球蛋白增多，白蛋白与球蛋白比例倒置。"},{"t":"p","x":"2)免疫学检查 ①狼疮细胞检查：阳性率在60%左右，但特异性低。"},{"t":"p","x":"②抗核抗体检查：阳性率在95%以上，其中抗双链脱氧核糖核酸(deoxyribonucleic acid,DNA)抗体特异性高，阳性率60%～70%，效价与病情轻重成正比。"},{"t":"p","x":"其他如抗Sm抗体、抗SSA抗体、抗SSB抗体阳性率为30%左右。"},{"t":"p","x":"③补体及免疫复合物检查：循环免疫复合物升高，血清总补体及C、C均降低，尤以C下降显著。"},{"t":"p","x":"④狼疮带试验检查：用直接免疫荧光法检测患者皮肤和真皮连接处，可见免疫球蛋白和补体沉积，呈颗粒状、球状或线条状排列的黄绿色荧光带，在系统性红斑狼疮的正常皮肤暴露部位阳性率为50%～70%，皮损部位高达90%以上，诊断意义较大。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-31)"},{"t":"table","img":"img/tab/t1031.jpg","cap":"表10-31红蝴蝶疮与风湿性关节炎、皮肌炎的鉴别"}],"entries":["e0654"]},{"title":"治疗","blocks":[{"t":"p","x":"中医治疗多从补益肝肾、活血化瘀、祛风解毒入手。本病病情复杂，临床多采用中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s102901","name":"热毒炽盛证","clinic":"多见于系统性红蝴蝶疮急性活动期。面部蝶形红斑，色鲜艳，皮肤紫斑，关节肌肉疼痛；伴高热，烦躁口渴，抽搐、大便干结，小便短赤；舌红绛，苔黄腻，脉洪数或细数","treat":"清热凉血，化斑解毒","formula":"犀角地黄汤合黄连解毒汤加减。高热神昏者，加安宫牛黄丸，或服紫雪丹、至宝丹","formulaNames":["犀角地黄汤","黄连解毒汤"]},{"t":"syn","sid":"s102902","name":"阴虚火旺证","clinic":"斑疹暗红，关节痛，足跟痛；伴有不规则发热或持续性低热，手足心热，心烦失眠，疲乏无力，自汗盗汗，面浮红，月经量少或闭经；舌红，苔薄，脉细数","treat":"滋阴降火","formula":"六味地黄丸合大补阴丸、清骨散加减。若潮热明显，加银柴胡、鳖甲","formulaNames":["六味地黄丸","大补阴丸","清骨散"]},{"t":"syn","sid":"s102903","name":"脾肾阳虚证","clinic":"眼睑、下肢浮肿、胸胁胀满，尿少或尿闭，面色无华，腰膝酸软，面热肢冷，口干不渴；舌淡胖，苔少，脉沉细","treat":"温肾助阳，健脾利水","formula":"附桂八味丸合真武汤加减。若小便有蛋白尿，可重用生黄芪，加金樱子、玉米须","formulaNames":["附桂八味丸","真武汤"]},{"t":"syn","sid":"s102904","name":"脾虚肝旺证","clinic":"皮肤紫斑；胸胁胀满，腹胀纳呆，头昏头痛，耳鸣失眠，月经不调或闭经；舌紫暗或有瘀斑，脉细弦","treat":"健脾清肝","formula":"四君子汤合丹栀逍遥散加减。若月经不调或闭经，可加益母草、当归、熟地黄","formulaNames":["四君子汤","丹栀逍遥散"]},{"t":"syn","sid":"s102905","name":"气滞血瘀证","clinic":"多见于盘状局限型及亚急性皮肤型红蝴蝶疮。红斑暗滞，角质栓形成及皮肤萎缩；伴倦怠乏力；舌暗红，苔白或光面舌，脉沉细涩","treat":"疏肝理气，活血化瘀","formula":"逍遥散合血府逐瘀汤加减。若皮疹色红，对紫外光敏感者，加青蒿","formulaNames":["逍遥散","血府逐瘀汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)皮损以红斑为主，选用三黄洗剂外搽，或青黛散冷开水调涂。"},{"t":"p","x":"(2)皮损肥厚粗糙，外涂白玉膏或黄柏霜。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"西医治疗急性发作或重型病例，宜选用糖皮质激素、免疫抑制剂、生物制剂等进行中西医结合治疗。"}]}],"entries":["e0655","e0656","e0657","e0658","e0659","e0660","e0661","e0662"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.避免日光暴晒，夏日应特别注意避免阳光直接照射。2.避免各种诱发因素，对易于诱发本病的药物如青霉素、链霉素、磺胺类、普鲁卡因酰胺、肼苯哒嗪及避孕药等应避免使用，皮损处忌涂有刺激性的外用药。"},{"t":"p","x":"避免使用化妆品、染发剂和纹眉剂等。3.肾脏受损害者，应忌食豆类及植物蛋白含量高的食品，以免加重肾脏负担。"}],"entries":["e0663"]}]},{"id":"d1030","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"淋病","displayName":"淋病","parentId":"","printedPage":191,"pdfPage":206,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"淋病是由淋病双球菌(简称淋球菌)感染所引起的以尿道刺痛、尿道口排出脓性分泌物为主要临床表现的一种病症。淋病属泌尿生殖系感染的性传播疾病，主要通过性交传染，极少数也可通过间接传染。"},{"t":"p","x":"中医学称之为“花柳毒淋”。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.湿热毒蕴淋病的发生多因宿娼恋色或误用污染之器具，湿热秽浊之气由下焦前阴窍口人侵，阻滞于膀胱及肝经，局部气血运行不畅、湿热熏蒸，精败肉腐，气化失司而成本病。"},{"t":"p","x":"2.阴虚毒恋病久及肾，导致肾虚阴亏，瘀结于内，由实转虚，形成虚证或虚实夹杂之证。西医学认为，本病的病原体为淋球菌、系革兰阴性球菌，多寄生在淋病患者的泌尿生殖系统。"}],"entries":["e0664","e0665"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现有不洁性交或间接接触传染史。"},{"t":"p","x":"潜伏期一般为2～10天，平均3～5天。"},{"t":"p","x":"1)男性淋病一般症状和体征较明显。"},{"t":"p","x":"急性淋病：尿道口红肿、发痒及轻度刺痛，继而有稀薄黏液流出，引起排尿不适，24小时后症状加剧。排尿开始时尿道外口刺痛或灼热痛，排尿后疼痛减轻。"},{"t":"p","x":"尿道口溢脓，开始为浆液性分泌物，以后逐渐变稠，出现黄色黏稠的脓性分泌物，特别是晨起分泌物较多。部分患者可有尿频、尿急、夜尿增多。"},{"t":"p","x":"当病变上行蔓延至后尿道时，可出现终末血尿、血精、会阴部轻度坠胀等现象。全身症状一般较轻，少数患者可伴有发热(38℃左右)、全身不适、食欲不振等。"},{"t":"p","x":"慢性淋病：多由急性淋病治疗不当，或在急性期嗜酒及与配偶性交等因素而转为慢性；也有因患者体质虚弱或伴贫血、结核，病情一开始即呈慢性经过。"},{"t":"p","x":"慢性淋病患者表现为尿痛轻微，排尿时仅感尿道灼热或轻度刺痛，常可见终末血尿。尿道外口不见排脓，挤压阴茎根部或用手指压迫会阴部，尿道外口仅见少量稀薄浆液性分泌物。"},{"t":"p","x":"患者多有慢性腰痛，会阴部胀感，夜间遗精，精液带血。淋病反复发作者可出现尿道狭窄，少数可引起输精管狭窄或梗塞，发生精液囊肿。"},{"t":"p","x":"男性淋病可合并淋菌性前列腺炎、附睾炎、精囊炎、膀胱炎等。"},{"t":"p","x":"2)女性淋病约60%的患者无症状或症状较轻，好发于宫颈和尿道。"},{"t":"p","x":"急性淋病：女性急性淋病的主要类型有以下3种：①淋菌性宫颈炎：表现为大量脓性白带，宫颈充血、触痛，伴有外阴刺痒和烧灼感。常与尿道炎并见，可有尿频、尿急等症状。"},{"t":"p","x":"②淋菌性尿道炎："},{"t":"p","x":"表现为尿道口充血、压痛，并有脓性分泌物，轻度尿频、尿急、尿痛，排尿时有烧灼感，挤压尿道旁腺有脓性分泌物。"},{"t":"p","x":"③淋菌性前庭大腺炎：表现为前庭大腺红肿热痛，甚至形成脓肿，触痛明显。"},{"t":"p","x":"全身症状有高热、畏寒等。慢性淋病：常由急性转变而来。"},{"t":"p","x":"表现为下腹坠胀、腰酸背痛、白带较多、下腹疼痛、月经过多等。"},{"t":"p","x":"3)淋菌性肛门直肠炎常见于男性同性恋，女性患者一般由淋菌性宫颈炎的分泌物感染肛门直肠所致。"},{"t":"p","x":"表现为肛门瘙痒和灼热感，伴有脓性分泌物。严重者可有里急后重，并排出大量脓性或血性分泌物。"},{"t":"p","x":"4)淋菌性咽炎常见于口交者。"},{"t":"p","x":"表现为急性咽炎或急性扁桃体炎，出现咽干、咽痛、发热、颈部淋巴结肿大等症状。"},{"t":"p","x":"5)淋菌性结膜炎新生儿患者多因母亲产道感染所致，多为双侧；"},{"t":"p","x":"成人患者多因自我接种或接触被污染的物品所致，多为单侧。表现为眼睑红肿、结膜充血和大量脓性分泌物。"},{"t":"p","x":"严重者可见角膜溃疡，甚至穿孔、失明。"},{"t":"p","x":"6)播散性淋病常出现淋菌性关节炎、淋菌性败血症、脑膜炎、心内膜炎及心包炎等。"},{"t":"p","x":"(2)辅助检查采取病损处分泌物或穿刺液涂片做革兰染色，可找到淋球菌，有助于初步诊断。"},{"t":"p","x":"经培养检查即可确诊。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-32)"},{"t":"table","img":"img/tab/t1032.jpg","cap":"表10-32淋病与非淋菌性尿道炎、念珠菌性尿道炎的鉴别"}],"entries":["e0666"]},{"title":"治疗","blocks":[{"t":"p","x":"西医学以及时、足量的抗生素治疗为主。中西医结合治疗淋病，特别是对慢性淋病和有合并症状淋病的治疗，有一定的优势。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s103001","name":"湿热毒蕴证","clinic":"尿道口红肿、溢脓，尿液混浊如脂，尿急、尿频、尿痛，尿道灼热，严重者尿道黏膜水肿，附近淋巴结红肿疼痛；女性宫颈充血、触痛，并有脓性分泌物，或有前庭大腺红肿热痛等；可伴有发热等全身症状；舌红，苔黄腻，脉滑数","treat":"清热利湿，解毒化浊","formula":"龙胆泻肝汤加减。热毒入络者，合清营汤加减","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s103002","name":"阴虚毒恋证","clinic":"小便不畅、短涩，淋沥不尽，女性带下多，或尿道口见少许黏液，酒后或疲劳易复发；腰酸腿软，五心烦热，食少纳差；舌红，苔少，脉细数","treat":"滋阴降火，利湿祛浊","formula":"知柏地黄丸加减","formulaNames":["知柏地黄丸"]},{"t":"p","x":"2.外治疗法可选用土茯苓、地肤子、苦参、芒硝各30g，煎水外洗局部，每天3次。3.其他疗法临床应早期足量选用以下抗生素治疗：①头孢曲松250mg,1次肌内注射；"},{"t":"p","x":"②大观霉素2.0g(宫颈炎4.0g),1次肌内注射；"},{"t":"p","x":"③环丙沙星500mg，顿服；"},{"t":"p","x":"④左氧氟沙星400mg，顿服；"},{"t":"p","x":"⑤阿奇霉素1g，顿服。"},{"t":"p","x":"治疗结束后2周内，在无性接触史的情况下，符合以下标准为治愈：症状和体征全部消失；在治疗结束后4～7天，做淋球菌复检呈阴性。"}],"entries":["e0667","e0668","e0669"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.杜绝不洁性交，提倡性交时使用避孕套。2.患病期间暂停性行为，并同时治疗性伴侣。"}],"entries":["e0670"]}]},{"id":"d1031","kind":"attach","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"非淋菌性尿道炎","displayName":"淋病·非淋菌性尿道炎","parentId":"d1030","printedPage":192,"pdfPage":207,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"非淋菌性尿道炎是一种由淋球菌以外的多种病原微生物引起的泌尿生殖器黏膜化脓性炎症。"},{"t":"p","x":"主要通过性接触传播，以性活跃期的中青年多见。本病属中医学“淋证”“淋浊”范畴。"},{"t":"p","x":"病原微生物以沙眼衣原体、解脲支原体为多见。另外，阴道滴虫、白色念珠菌、单纯疱疹病毒、巨细胞病毒等均可导致木病的发生。"},{"t":"p","x":"木病的主要病因病机是下焦湿热、肝郁气滞、肝肾亏损，导致脑胱功能失调。三焦水道通调不利。"},{"t":"p","x":"本病的临床表现似淋病而症轻。男性主要表现为尿道炎，可有尿频、尿急、尿痛、尿道刺痒，尿道口潮红，有清稀的黏液性分泌物、亦可并发附睾炎和前列腺炎。"},{"t":"p","x":"女性尿道炎症状常轻微、甚至无症状，可有宫颈炎，宫颈充血、水肿、糜烂、分泌物增多，还可并发前庭大腺炎、阴道炎、子官内膜炎等。如治疗不当、反复发作、可导致不育症。"},{"t":"p","x":"实验室检查：尿道、宫颈分泌物涂片革兰染色、高倍显微镜视野下多形核白细胞数大于5个，淋球菌检查及培养阴性，有条件者可分离培养衣原体、支原体等病原微生物。"},{"t":"p","x":"中药内治分为3个证型：①湿热阻滞证：治宜清热利湿、化浊通淋，方用草分清饮或八正散加减；"},{"t":"p","x":"②肝郁气滞证：治宜疏肝解郁、理气通淋，方用橘核丸加减；"},{"t":"p","x":"③阴虚湿热证：治宜滋阴补肾、清热利湿、方用知柏地黄丸加减。"},{"t":"p","x":"外治可选用苦参、贯众、败酱草、蒲公英等煎水外洗。抗生素可酌情选用红霉素、琥乙红霉素、阿奇霉素、氧氟沙星、环丙沙星等内服。"}],"entries":["e0671"]}]},{"id":"d1032","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"梅毒","displayName":"梅毒","parentId":"","printedPage":193,"pdfPage":208,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"梅毒是由梅毒螺旋体引起的一种慢性传染性疾病。其临床特点是梅毒螺旋体几乎可侵犯人体所有器官，早期主要表现为皮肤黏膜损害，晚期可造成骨骼及眼部、心血管、中枢神经系统等多器官组织的病变。"},{"t":"p","x":"临床表现极为复杂，病程中有时呈无症状的潜伏状态。主要通过性接触和血液传播，危害性极大。"},{"t":"p","x":"梅毒又称“霉疮”。我国第一部论述梅毒的专著《霉疮秘录》，记载霉疮“酷烈匪常，人髓沦肌，流经走络⋯⋯或攻脏腑，或巡孔窍”;“遂令膏粱子弟，形损骨枯，口鼻俱废，甚则传染妻孥，丧身绝育，深可怜惜”。"},{"t":"p","x":"古代文献又称之为“疳疮”“花柳病”等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病为淫秽疫毒与湿热、风邪杂合所致。传播方式主要是精化传染(直接传染)、气化传染(间接传染)和胎中染毒。"},{"t":"p","x":"精化传染主要是与梅毒患者房事精泄时，淫毒乘肝肾之虚入里；气化传染是通过被患者污染的生活用品等触及秽毒，毒气循脾肺二经传入；"},{"t":"p","x":"胎中染毒则是禀受于母体之梅毒疫疠之毒而发。邪之初染，疫毒结于阴器及肛门等处，发为疳疮；"},{"t":"p","x":"流于经脉，则生横痃；后期疫毒内侵，伤及骨髓、关窍、脏腑，变化多端，证候复杂。"},{"t":"p","x":"西医学认为，梅毒的病原体为梅毒螺旋体，又称苍白螺旋体。成人患者主要通过性行为传染，少数可因接吻、输血及接触患者的物品等非直接接触传染；"},{"t":"p","x":"儿童多由胎盘、产道或哺乳传染。梅毒螺旋体经黏膜或破损皮肤进入机体后，即在侵入处组织中繁殖，在外生殖器处形成硬下疳，发为一期梅毒。"},{"t":"p","x":"后在局部免疫反应下，部分螺旋体被消灭，损害逐渐消退，成为一期潜伏梅毒。硬下疳消退后约6周，潜伏的螺旋体大量繁殖，进入血液循环，侵入多种组织内，全身皮肤黏膜广泛出现梅毒疹，成为二期梅毒。"},{"t":"p","x":"由于机体的免疫力，皮肤黏膜的梅毒疹也可消退。但当机体的抵抗力低下时，未被自身免疫力消灭的螺旋体仍然可以引起皮损的再发，成为二期复发性梅毒。"},{"t":"p","x":"2年后进入晚期，此期可为无症状的晚期隐性梅毒。如有复发，则可侵犯任何组织，如皮肤黏膜、神经系统及心血管系统等重要脏器，受累组织内梅毒螺旋体虽少，但具有极大的破坏性而致组织缺损及功能障碍，成为三期梅毒。"},{"t":"p","x":"根据传播途径的不同，梅毒可分为获得性(后天)梅毒和胎传(先天)梅毒；根据病程的长短，梅毒又可分为早期梅毒(一期、二期梅毒)和晚期梅毒(三期梅毒)。"}],"entries":["e0672","e0673"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病好发于青壮年，男性多于女性，早期梅毒最为多见。"},{"t":"p","x":"一般有不洁性交史，或性伴侣有梅毒病史。"},{"t":"p","x":"1)一期梅毒主要表现为疳疮(硬下疳)和横(硬化性淋巴结炎)，一般无全身症状。"},{"t":"p","x":"约90%硬下疳发生在男女外生殖器部位，少数发生在唇、舌、口腔、咽及肛门、直肠等处。其典型表现初为丘疹或浸润性红斑，继之轻度糜烂或成浅表性溃疡，少量浆液性分泌物，内含大量的梅毒螺旋体，传染性极强。"},{"t":"p","x":"边缘隆起、边缘及基底部呈软骨样硬度，直径1～2cm，圆形、常为单个，偶为多个，不痛不痒、可在3～4周后自然消失，不留痕迹或仅留轻度萎缩性瘢痕及色素沉着。"},{"t":"p","x":"硬下疳出现后1～2周、胯腹部或患部附近淋巴结肿大(横痃)、初起形如杏核，渐大如鸡卵，色白坚硬不痛，很少溃破，皮核相互孤立而不粘连，持续时间较久。"},{"t":"p","x":"2)二期梅毒一期梅毒未经治疗或治疗不彻底，梅毒螺旋体由淋巴系统进入血液循环，可形成菌血症播散全身，引起皮肤黏膜及系统性损害，称为二期梅毒。"},{"t":"p","x":"主要表现为杨梅疮。皮肤黏膜损害：其特点是分布广泛、对称，自觉症状轻微，破坏性小，传染性强。"},{"t":"p","x":"主要表现有下列几种：①皮损：早期为直径约0.5cm的圆形或椭圆形淡红色斑块，进一步发展呈多样性，可有斑疹(玫瑰疹)、斑丘疹、丘疹鳞屑性梅毒疹、毛囊疹、脓疱疹、蛎壳状疹、溃疡疹等，这些损害可以单独或合并出现。"},{"t":"p","x":"②扁平湿疣：好发于肛门周围、外生殖器等皮肤互相摩擦和潮湿的部位，稍高出皮面，界限清楚，表面湿烂，其颗粒密聚如菜花，覆有灰白色薄膜，内含大量的梅毒螺旋体。"},{"t":"p","x":"③梅毒性白斑："},{"t":"p","x":"好发于妇女的颈部、躯干、四肢、外阴及肛周，为局限性色素脱失斑，可持续数月。"},{"t":"p","x":"④梅毒性脱发："},{"t":"p","x":"脱发呈虫蚀状。"},{"t":"p","x":"⑤黏膜损害：黏膜红肿及糜烂，黏膜斑内含大量的梅毒螺旋体。"},{"t":"p","x":"骨损害：可发生骨膜炎及关节炎，好发于四肢的长骨和大关节，也可发生于骨骼肌的附着点，如尺骨鹰嘴、髂骨嵴及乳突等处。白天及活动时疼痛较轻，晚上和休息时较重。"},{"t":"p","x":"眼梅毒：可发生虹膜炎、虹膜睫状体炎、视神经炎和视网膜炎等。"},{"t":"p","x":"3)三期梅毒亦称晚期梅毒，主要表现为杨梅结毒。"},{"t":"p","x":"此期特点为病程长，易复发，除皮肤黏膜损害外，常侵犯多个脏器。皮肤梅毒：损害多为局限性、孤立性、浸润性斑块或结节，发展缓慢，破坏性大，愈后留有瘢痕。"},{"t":"p","x":"常见的有：①结节性梅毒疹：多见于面部和四肢，为豌豆大小铜红色的结节，成群而不融合，呈环形、蛇形或星形，质硬，可溃破，愈后留有萎缩性瘢痕。"},{"t":"p","x":"②树胶样肿：初起为无痛性皮下结节，继之中心软化溃破，溃疡基底不平，为紫红色肉芽，分泌如树胶样黏稠脓汁，持续数月至2年，愈后留下瘢痕。"},{"t":"p","x":"③近关节结节：发生于肘、膝、髋等大关节附近的皮下结节，对称发生，表现为无炎症，坚硬，压迫时稍有痛感，无其他自觉症状，发展缓慢，不溃破，治疗后可逐渐消失。"},{"t":"p","x":"黏膜梅毒：主要见于口、鼻腔，为深红色的浸润型，上腭及鼻中隔黏膜树胶肿可侵犯骨质，导致骨坏死，死骨排出后形成上腭、鼻中隔穿孔及马鞍鼻，引起吞咽困难及发音障碍，少数可发生咽喉树胶肿而引起声音嘶哑、呼吸困难。"},{"t":"p","x":"骨梅毒：以骨膜炎为多见，常侵犯长骨，损害较少，疼痛较轻，病程缓慢。其次为骨树胶肿，常见于颅骨等扁骨，可形成死骨及皮肤溃疡。"},{"t":"p","x":"眼梅毒：可发生虹膜睫状体炎、视网膜炎及角膜炎等。心血管梅毒：主要有梅毒性主动脉炎、梅毒性主动脉瓣闭锁不全、梅毒性主动脉瘤和梅毒性冠状动脉狭窄等。"},{"t":"p","x":"神经梅毒：主要类型有无症状神经梅毒、脊髓痨、麻痹性痴呆、脑(脊髓)膜血管型神经梅毒等。"},{"t":"p","x":"4)胎传梅毒(先天梅毒)是母体内的梅毒螺旋体由血液通过胎盘传入胎儿血液中，导致胎儿感染的梅毒。"},{"t":"p","x":"多发生在妊娠4个月后。发病小于2岁者称早期胎传梅毒，大于2岁者称晚期胎传梅毒。"},{"t":"p","x":"胎传梅毒不发生硬下疳，常有严重的内脏损害，对患儿的健康影响很大，病死率高。早期胎传梅毒：多在出生后2周～3个月内出现症状。"},{"t":"p","x":"表现为消瘦，皮肤松弛多皱褶，哭声嘶哑、常因鼻炎而导致呼吸、哺乳困难。皮肤损害可表现为斑疹、斑丘疹、水疱、大疱、脓疱等，多分布在头面、肢端、口周皮肤、口周可见皲裂、愈后留有辐射状瘢痕。"},{"t":"p","x":"此外，也可发生甲周炎、甲床炎、无发、骨髓炎、骨软骨炎、贫血、血小板减少等。大部分患儿可有脾肿大、肝肿大，少数出现活动性神经梅毒。"},{"t":"p","x":"晚期胎传梅毒：患儿发育不良，智力低下，可有前额圆凸、镰刀胫、哈钦森牙、桑椹牙、马鞍鼻、锁骨胸骨关节骨质肥厚、视网膜炎、角膜炎、神经性耳聋、脑脊液异常、肝脾肿大、鼻或腭树胶肿导致口腔及鼻中隔穿孔和鼻畸形。"},{"t":"p","x":"皮肤黏膜损害与成人相似。"},{"t":"p","x":"5)潜伏梅毒(隐性梅毒)梅毒未经治疗或用药剂量不足，无临床症状，血清反应阳性，排除其他可引起血清反应阳性的疾病存在，脑脊液正常，这类情况称为潜伏梅毒。"},{"t":"p","x":"若感染时间在2年以内者称为早期潜伏梅毒，早期潜伏梅毒随时可发生二期复发损害，有传染性；病期在2年以上者称为晚期潜伏梅毒，少有复发，传染性低，但女患者仍可通过胎盘传给胎儿，发生胎传梅毒。"},{"t":"p","x":"(2)辅助检查梅毒螺旋体抗原血清试验阳性，或蛋白印迹试验阳性，均有利于诊断；"},{"t":"p","x":"聚合酶链反应检查梅毒螺旋体DNA阳性；或取硬下疳、病损皮肤、黏膜损害的表面分泌物、肿大的淋巴结穿刺液在暗视野显微镜下查到梅毒螺旋体，均可确诊。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表10-33、表10-34、表10-35)"},{"t":"table","img":"img/tab/t1033.jpg","cap":"表10-33硬下疳与软下疳的鉴别"},{"t":"table","img":"img/tab/t1034.jpg","cap":"表10-34梅毒玫瑰疹与风热疮的鉴别"},{"t":"table","img":"img/tab/t1035.jpg","cap":"表10-35梅毒扁平湿疣与尖锐湿疣的鉴别"}],"entries":["e0674"]},{"title":"治疗","blocks":[{"t":"p","x":"梅毒的治疗原则为及早、足量、规范使用抗生素。中医药治疗梅毒一般仅作为驱梅治疗中的辅助疗法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s103201","name":"肝经湿热证","clinic":"多见于一期梅毒。外生殖器疳疮质硬而润，或伴有横痃，杨梅疮多在下肢、腹部、阴部；兼见口苦口干，小便黄赤，大便秘结；舌质红，苔黄腻，脉弦滑","treat":"清热利湿、解毒驱梅","formula":"龙胆泻肝汤加土茯苓、牡丹皮、赤芍","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s103202","name":"血热蕴毒证","clinic":"多见于二期梅毒。周身起杨梅疮，色如玫瑰，不痛不痒，或见丘疹、脓疱、鳞屑；兼见口干咽燥，口舌生疮，大便秘结；舌质红绛，苔薄黄或少苔，脉细滑或细数","treat":"凉血解毒，泻热散瘀","formula":"清营汤合桃红四物汤加减","formulaNames":["清营汤","桃红四物汤"]},{"t":"syn","sid":"s103203","name":"毒结筋骨证","clinic":"见于杨梅结毒。患病日久，在四肢、头面、鼻咽部出现树胶肿，伴关节、骨骼作痛，活动不利，肌肉消瘦、疼痛夜甚；舌质暗，苔薄白或灰或黄，脉沉细涩","treat":"活血解毒，通络止痛","formula":"五虎汤加减","formulaNames":["五虎汤"]},{"t":"syn","sid":"s103204","name":"肝肾亏损证","clinic":"见于三期梅毒脊髓痨者。患病可达数十年之久，逐渐两足瘫痪或痿弱不行，肌肤麻木或如虫行作痒，筋骨窜痛；腰膝酸软，小便困难；舌质淡，苔薄白，脉沉细弱","treat":"滋补肝肾，填髓息风","formula":"地黄饮子加减","formulaNames":["地黄饮子"]},{"t":"syn","sid":"s103205","name":"心肾亏虚证","clinic":"见于心血管梅毒患者。症见心慌气短，神疲乏力，下肢浮肿，唇甲青紫，腰膝酸软，动则气喘；舌质淡，有齿痕，苔薄白而润，脉沉弱或结代","treat":"养心补肾，祛瘀通阳","formula":"苓桂术甘汤加减","formulaNames":["苓桂术甘汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)疳疮糜烂者，可选用鹅黄散或珍珠散敷于患处，红油膏纱条盖贴，每日2次；"},{"t":"p","x":"溃疡者，疮面上撒七三丹，外盖红油膏纱条，每日1～2次。"},{"t":"p","x":"(2)横痃、杨梅结毒未溃时选用冲和膏，醋、酒各半调成糊状外敷；"},{"t":"p","x":"溃破时先用五五丹掺在疮面上，外盖玉红膏，每日1次；待其腐脓除尽，再用生肌散掺在疮面上，盖玉红膏，每日1次。"},{"t":"p","x":"(3)杨梅疮苦参30g，土茯苓30g，蛇床子30g，蒲公英15g，莱菔子30g，黄柏30g。"},{"t":"p","x":"煎汤外洗，每日1次。3.其他疗法应尽早实施西医驱梅疗法，并足量、规范用药。"},{"t":"p","x":"青霉素类为首选药物，头孢曲松钠可作为青霉素过敏者优先选择的替代药物。"},{"t":"p","x":"(1)早期梅毒普鲁卡因青霉素G80万U，肌内注射，每日1次，连续10～15日；"},{"t":"p","x":"苄星青霉素240万U，分两侧臀部肌内注射，每周1次，连续2～3次。青霉素过敏者，可选用头孢曲松钠1.0g，静脉注射，每日1次，连续10～14日。"},{"t":"p","x":"(2)晚期梅毒普鲁卡因青霉素G80万U，肌内注射，每日1次，连续20日；"},{"t":"p","x":"苄星青霉紫240万U，分两侧臀部肌内注射，每周1次，连续3～4次。青霉素过敏者，可用四环素类或大环内酯类药物。"},{"t":"p","x":"(3)胎传梅毒普鲁卡因青霉素G，每日5万U/kg，肌内注射，连续10～14日；"},{"t":"p","x":"苄星青素5万U/kg，肌内注射。对较大儿童的青霉素用量不应超过成人同期患者的治疗量。"},{"t":"p","x":"青霉素过敏者，可选用红霉素20～30mg/kg，每日分4次口服，连续30日。"}]}],"entries":["e0675","e0676","e0677","e0678","e0679","e0680","e0681"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强梅毒等性病防治知识的宣传和教育工作，提倡健康的性道德观和保障性安全。2.夫妻双方共同治疗。"},{"t":"p","x":"3.做好孕妇胎前检查工作，梅毒患者要避孕，或及早中止妊娠。"}],"entries":["e0682"]}]},{"id":"d1033","kind":"main","chapterId":"ch10","chapterNo":"第十章","chapterName":"皮肤及性传播疾病","name":"艾滋病","displayName":"艾滋病","parentId":"","printedPage":197,"pdfPage":212,"syndromeCount":6,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"艾滋病全称是获得性免疫缺陷综合征，是由人类免疫缺陷病毒(human immunodeficiency virus,HIV)感染所致的以严重免疫缺陷为主要特征的传染病。"},{"t":"p","x":"临床特点是HIV能特异性侵犯CD4⁺T淋巴细胞，引起机体细胞免疫系统严重缺陷，导致各种机会性顽固感染、恶性肿瘤的发生，并对机体各系统尤其是神经系统造成致命的损害。艾滋病主要通过性接触及血液、血液制品和母婴传播传染。"},{"t":"p","x":"由于传染性强，死亡率高，其号称“超级癌症”，已引起全世界的高度重视。艾滋病属于中医学“疫疠”“虚劳”“癥瘕”等范畴。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生总由邪毒外袭和正气不足所致。其病机为邪盛与正虚共存，最终导致正气衰竭，五脏受损，阴阳离决。"},{"t":"p","x":"1.邪毒外袭艾滋病毒为疫疠之邪，具有强烈的传染性，可侵犯肺卫或上蒙清窍而发病。2.正气不足主要为肾不藏精、肾亏体弱，所谓“邪之所凑，其气必虚”，正虚多表现为气虚、肺肾阴虚、脾胃虚弱、脾肾亏虚。"},{"t":"p","x":"大凡由性接触传染者，多为嫖娼、肛交、滥交伐精纵欲者，其肾精处于匮乏状态，易为邪毒所入；"},{"t":"p","x":"而凡吸毒者均用兴奋致幻之品，令人异常亢奋，性欲亢进(暂时)，心神恍惚，不能自持，毒品为燥烈耗气伤精之品，久则致人形容消瘦、精力减退、性功能降低，呈肾精亏乏状态，易为邪毒所犯；"},{"t":"p","x":"至于输血等亦为气血不足，夹邪毒之血液染毒而为病。"},{"t":"p","x":"西医学认为，艾滋病的病原体为HIV，为逆转录C型核糖核酸(ribonucleic acid,RNA)病毒，患者的精液、血液、唾液、眼泪、乳汁、尿液、阴道分泌物中均可分离出HIV，可通过精液、血液及分泌物经血流和破损的皮肤与黏膜传入全身，主要通过性交传染、血液传染和围产期母婴感染。"},{"t":"p","x":"HIV嗜CD4⁺T淋巴细胞在细胞内进行繁殖，使后者不断地破裂、溶解、消失，遭到破坏。"},{"t":"p","x":"由于CD4⁺T淋巴细胞减少，依赖CD4⁺T淋巴细胞参加的细胞免疫反应处于无能状态，致使患者极易发生一系列的原虫、蠕虫、真菌、细菌和病毒等条件性病原体的感染，最后发生少见的恶性肿瘤。"},{"t":"p","x":"同时，HIV能侵犯神经系统，感染脑和脊髓，出现神经系统症状。HIV病毒侵犯人体后，核酸可以与宿主染色体DNA整合，故无论是免疫接种预防还是治疗都极其困难。"}],"entries":["e0683","e0684"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断"},{"t":"p","x":"(1)临床表现本病多见于同性恋者、娼妓、性病患者(特别是有生殖器溃疡者，如梅毒、软下疳、生殖器疱疹等)、多性伴者、接受输血者、父母患艾滋病的儿童等高危人群，目前成人较为多发，在世界范围内主要通过性接触传播。"},{"t":"p","x":"从感染HIV到发展为艾滋病，分为急性HIV感染、无症状HIV感染、艾滋病三个阶段。"},{"t":"p","x":"急性HIV感染：在接触HIV后1～2周，HIV大量复制而CD4*T淋巴细胞急剧下降、造成50%～70%的感染者出现HIV病毒血症和免疫系统急性损伤。"},{"t":"p","x":"表现为发热、出汗、乏力、肌痛、关节痛、厌食、腹痛腹泻、无渗出的咽炎、头痛、怕光和脑膜刺激征，皮肤出现斑丘疹、玫瑰疹或荨麻疹。少数患者可出现脑炎、周围神经炎或急性多发性神经炎。"},{"t":"p","x":"体检可有颈、枕、腋部淋巴结肿大及肝脾肿大。上述表现多在1个月内消失。"},{"t":"p","x":"无症状HIV感染：可由原发HIV感染或急性感染症状消失后迁延而来，短则数月，长则20年，平均8～10年。临床上基本无症状，部分患者可出现持续性淋巴结肿大。"},{"t":"p","x":"血清中能检出HIV及HIV核心蛋白和包膜蛋白的抗体、患者具有传染性。艾滋病：表现为发热、腹泻、体重下降、全身浅表淋巴结肿大。"},{"t":"p","x":"常合并真菌、病毒或细菌性感染，如口腔白色念珠菌病、皮肤单纯疱疹、带状疱疹和脓皮病等；也有患者出现恶性肿瘤，如卡波西肉瘤、淋巴瘤等。"},{"t":"p","x":"卡氏肺孢子菌肺炎或中枢神经系统的感染是多数艾滋病患者死亡的直接原因。未经治疗者在进入此期后平均生存期为12～18个月。"},{"t":"p","x":"(2)辅助检查 ①免疫学检查：CD4⁺T淋巴细胞减少，外周血淋巴细胞显著减少，低于1×10⁹/L;CD4'/CD8'<1(正常为1.75～2.1)；自然杀伤细胞(natural killer cell,NK cell)活性下降，B淋巴细胞功能失调。"},{"t":"p","x":"②HIV检测：常用的有细胞培养分离病毒、检测HIV抗原、检测逆转录酶、检测病毒核酶等。"},{"t":"p","x":"由于操作复杂、价格昂贵，不作为常规筛查之用。"},{"t":"p","x":"③HIV抗体检测：这类方法是确定有无HIV感染的最简便方法，但高危人群若为阴性应在3个月后复查。"},{"t":"p","x":"常用的方法有酶联免疫吸附法(enzyme linked immunosorbent assay,ELISA)、间接免疫荧光法(indirect immunofluorescence, IIF)、明胶颗粒凝集试验(gelatin particle agglutination assay,PA)、蛋白印迹试验(Western Blot, WB)、放射免疫沉淀试验(radio immunoprecipitation test,RIP)。"},{"t":"p","x":"其中前三种用于筛选检查，后两种用于明确诊断。"}],"entries":["e0685"]},{"title":"治疗","blocks":[{"t":"p","x":"抗反转录病毒治疗(antiretroviral therapy,ART)可明显改善HIV感染者的预后，提高患者的生存质量。"},{"t":"p","x":"艾滋病的防治重点在于控制传染源、切断传播途径和保护易感人群三个方面，抓住早期普遍抗病毒治疗、HIV暴露前和暴露后的预防、阻断母婴传播三个环节。"},{"t":"p","x":"中医中药和其他自然疗法已运用于艾滋病的预防和治疗，抗HIV病毒及提高机体免疫功能的中药得以筛选并推向临床，作为在辨证论治的基础上辨病用药的有效治疗手段。针灸的整体调节功能在治疗中也能发挥一定的作用。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s103301","name":"肺卫受邪证","clinic":"见于急性感染期。症见发热，微畏寒，微咳，身痛，乏力，咽痛；舌质淡红，苔薄白或薄黄，脉浮","treat":"宣肺祛风，清热解毒","formula":"银翘散加减。若寒邪为患，选用荆防败毒散加减","formulaNames":["银翘散"]},{"t":"syn","sid":"s103302","name":"肺肾阴虚证","clinic":"多见于以呼吸系统症状为主的艾滋病早、中期患者，尤以卡氏肺孢子菌肺炎、肺结核较多见。症见发热，咳嗽，无痰或少量黏痰，或痰中带血，气短胸痛，动则气喘；全身乏力，消瘦，口干咽痛，盗汗，周身可见淡红色皮疹，伴轻度瘙痒；舌红，少苔，脉沉细数","treat":"滋补肺肾，解毒化痰","formula":"百合固金汤合瓜蒌贝母汤加减","formulaNames":["百合固金汤","瓜蒌贝母汤"]},{"t":"p","x":"舌红，少苔，脉沉细数。治法：滋补肺肾，解毒化痰。"},{"t":"syn","sid":"s103303","name":"脾胃虚弱证","clinic":"多见于以消化系统症状为主者。症见腹泻久治不愈，腹泻呈稀水状便，少数夹有脓血和黏液，里急后重不明显，可有腹痛；兼见发热，消瘦，全身乏力，食欲不振，恶心呕吐，吞咽困难，或腹胀肠鸣，口腔内生鹅口疮；舌质淡，有齿痕，苔白腻，脉濡细","treat":"扶正祛邪，培补脾胃","formula":"补中益气汤合参苓白术散加减","formulaNames":["补中益气汤","参苓白术散"]},{"t":"syn","sid":"s103304","name":"脾肾亏虚证","clinic":"多见于晚期患者，预后较差。症见发热或低热，形体极度消瘦、神情倦怠，心悸气短，头晕目眩、腰膝酸痛、四肢厥逆、食欲不振，恶心，呃逆频作，腹泻剧烈，或五更泄泻，毛发枯槁，面色苍白；舌质淡或胖、苔白、脉细无力","treat":"温补脾肾。益气回阳","formula":"肾气丸合四神丸加减","formulaNames":["肾气丸","四神丸"]},{"t":"syn","sid":"s103305","name":"气虚血瘀证","clinic":"以卡波西肉瘤多见。症见周身乏力，气短懒言，面色苍白。饮食不香。四肢、躯干部出现多发性肿瘤、瘤色紫暗、易于出血、淋巴结肿大；舌质暗，脉沉细无力","treat":"补气化瘀、活血清热","formula":"补阳还五汤、犀角地黄汤合消瘰丸加减","formulaNames":["补阳还五汤","犀角地黄汤","消瘰丸"]},{"t":"syn","sid":"s103306","name":"窍闭痰蒙证","clinic":"多见于出现中枢神经病症的晚期患者。症见发热，头痛，恶心呕吐，神志不清，或神昏谵语，项强惊厥、四肢抽搐、或伴癫痫或痴呆；舌质暗或胖，或干枯，苔黄腻、脉细数或滑","treat":"清热化痰、开窍通闭","formula":"安宫牛黄丸、紫雪丹、至宝丹。若为寒甚者，用苏合香丸豁痰开窍。痰闭缓解后，则治其本、可用生脉散益气养阴","formulaNames":["安宫牛黄丸","紫雪丹","至宝丹"]},{"t":"sub","title":"2.常用有效中药辨病施治","blocks":[{"t":"p","x":"(1)抗HIV有效的中药甘草、人参、党参、黄芪、白术、茯苓、当归、大枣、枸杞子、杜仲、淫羊藿、苦参、柴胡、刺五加、香菇、丹参、黄连、金银花、黄芩、天花粉、紫花地丁、夏枯草、穿心莲、牛蒡子、蟛蜞菊、紫草、狗脊、贯众、千里光、丁公藤、苦瓜、龙胆草、蒲公英、麻黄、水牛角、漏芦、巴豆、槟榔、白头翁、防风、麝香、白屈菜、姜黄、桑白皮、大蒜、山豆根、连翘、鱼腥草、大青叶、白花蛇舌草、野菊花、知母、板蓝根、十大功劳叶等。"},{"t":"p","x":"(2)促进单核细胞吞噬能力的中药人参、党参、黄芪、紫河车、淫羊藿、五加皮、白术、黄精、灵芝、蒲公英、金银花、丹参、桃仁、赤芍、川芎、香菇、云茯苓、甘草。"},{"t":"p","x":"(3)促进巨噬细胞吞噬作用的中药黄芪、党参、人参、白术、灵芝、猪苓、香菇、当归、地黄、蝮蛇、淫羊藿、补骨脂、刺五加、杜仲。"},{"t":"p","x":"(4)增加T细胞的中药人参、灵芝、茯苓、香菇、白术、薏苡仁、黄精、天冬、女贞子、淫羊藿。"},{"t":"p","x":"(5)提高细胞免疫力的中药人参、党参、黄芪、黄精、白术、山药、灵芝、阿胶、菟丝子、淫羊藿、墨旱莲、当归、红花、仙鹤草、丹参、生地黄、女贞子、枸杞子、白芍、川芎、五味子、金银花、黄连等。"},{"t":"p","x":"(6)提高体液免疫力的中药人参、党参、黄芪、白术、灵芝、黄精、山药、墨旱莲、菟丝子、阿胶、淫羊藿、丹参、红花、川芎、当归、仙鹤草、生地黄、女贞子、枸杞子、白芍、金银花、五味子。"},{"t":"p","x":"(7)延长抗体存活及促进其生成的中药麦冬、玄参、沙参、鳖甲、鸡血藤、阿胶、女贞子等可延长抗体存活时间；"},{"t":"p","x":"肉桂、附子、仙茅、淫羊藿、锁阳、菟丝子可促进抗体生成，提高淋巴细胞转化作用。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺针灸可以调动机体的免疫系统，提高抗病能力。"},{"t":"p","x":"可选关元、命门、腰俞、脾俞、足三里、内关、合谷、曲池、百会、阴陵泉、阳陵泉、风池、委中、列缺等穴位。"},{"t":"p","x":"(2)西医治疗HIV实施定点医院治疗制度，目前采用的主要方法：①抗HIV治疗：高效抗反转录病毒治疗法(highly active anti-retroviral therapy,HAART；俗称“鸡尾酒疗法”)。"},{"t":"p","x":"治疗药物有核苷类反转录酶抑制剂(NRTIs)、非核苷类反转录酶抑制剂(NNRTIs)、蛋白酶抑制剂(PIs)、整合酶抑制剂(INSTIs)及融合抑制剂(FIs)五大类(包含复合制剂)；以上各药联合使用，取得了良好疗效。"},{"t":"p","x":"②免疫调节治疗：治疗药物有α-干扰素、白细胞介素2、静脉用人血丙种免疫球蛋白、粒细胞-巨噬细胞集落刺激因子及粒细胞集落刺激因子等。"},{"t":"p","x":"③合并条件性感染和恶性肿瘤者可采取对症处理。"}]}],"entries":["e0686","e0687","e0688","e0689","e0690","e0691","e0692","e0693","e0694"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强宣传普及艾滋病防治知识，不吸毒、提倡合法安全的性生活。2.早期发现、早期诊断、尽快隔离治疗，追踪与患者有性接触的高危人群。"},{"t":"p","x":"3.严格选择供血者、HIV检测应作为供血者的常规检查项目，防止血源传染。4.严格加强普通人群注射消毒管理，提倡使用一次性用品。"}],"entries":["e0695"]}]},{"id":"d1100","kind":"chapter","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"本章概述","displayName":"肛肠疾病·本章概述","parentId":"","printedPage":202,"pdfPage":217,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"肛肠疾病是指发生于直肠、肛管部位的疾病。"},{"t":"p","x":"常见的有痔、肛隐窝炎、肛裂、肛痈、肛漏、脱肛、息肉痔、锁肛痔等、在古代文献中统称为“痔疮”“痔瘘”。"}],"entries":["e0696"]},{"title":"解剖生理概要","blocks":[{"t":"p","x":"直肠及肛管位于消化道的最末端，是通于体外的通道。直肠起源于内胚层，肛管起源于外胚层。"},{"t":"p","x":"直肠全长12～15cm，解剖学的直肠其上端约在第3骶椎平面与乙状结肠相接，下端在尾骨尖稍上方与肛管相连、其上下两端狭小，中间部分膨大，膨大部分称为直肠壶腹。1.直肠的形态直肠走行方向不是直的，而呈弯曲状。"},{"t":"p","x":"在矢状面上沿骶骨和尾骨的前面下行，形成向后突的弯曲，称为直肠骶曲，距肛门7～9cm。接着直肠绕过尾骨尖，转向后下方又形成向前突的弯曲、称为直肠会阴曲，距肛门3～5cm(图11-1)。"},{"t":"p","x":"直肠在冠状面上有三个侧方弯曲，一般中间较大的一个弯曲突向左侧，其上、下各一个侧方弯曲均突向右侧，而直肠的起始和终末两端均在中线上。在做侵入性检查如电子结肠镜检查时，应注意这些弯曲的存在，以避免损伤直肠(图11-2)。"},{"t":"img","src":"img/fig/f1102.jpg","alt":"图11-2直肠的侧弯"},{"t":"img","src":"img/fig/f1101.jpg","alt":"图11-1骶曲和会阴曲"},{"t":"p","x":"直肠上段前面和两侧均被腹膜所覆盖，直肠中段仅前方被腹膜覆盖，腹膜在此处向后反折，形成男性的直肠膀胱陷凹或女性的直肠子宫陷凹，这两个陷凹是男性、女性的腹腔最低点，积液和积血常积聚于此陷凹内(图11-3)。"},{"t":"p","x":"2.直肠的结构直肠腔内有3条半月状的黏膜皱襞，称为直肠横襞。最上方的一个直肠横襞称为上直肠横襞；"},{"t":"p","x":"中间位置的直肠横襞称为中直肠横襞，为最大的一个，位置恒定，内部的环肌层特别发达，常称“肛门第三括约肌”，位于直肠右前壁；"},{"t":"p","x":"最下方的直肠横襞称为下直肠横襞，其位置多位于直肠左后壁，这些皱襞有支撑粪便和调节排便的作用(图11-2)。"},{"t":"p","x":"3.肛管的结构解剖学肛管长2～3cm，上接直肠与肛管交界处的齿状线，下端止于肛门最末端处的肛缘线，其周围有内、外括约肌环绕。肛管的表层为复层上皮，下部为鳞状上皮、表面光滑，无汗腺、皮脂腺和毛。"},{"t":"p","x":"由于直肠下端变得缩窄，其肠腔内黏膜被折成了6～10个纵行的皱襞，称为直肠柱。相邻的两个直肠柱下端之间有半月形皱襞，称为肛门瓣。"},{"t":"p","x":"肛门瓣与直肠柱之间的肠壁黏膜形成开口向上的袋状间隙，称为肛隐窝或肛窦。隐窝底部有肛腺开口，由于该处常积存粪屑，易发生感染，可引发肛隐窝炎，进而导致肛门直肠周围脓肿、肛瘘等疾病。"},{"t":"p","x":"直肠柱的基底部有2～6个乳头状突起，称为肛乳头、其长度一般≤2mm，局部炎症的刺激可使其增大，临床称为肛乳头肥大(图11-4)。"},{"t":"img","src":"img/fig/f1104.jpg","alt":"图11-4肛管的结构"},{"t":"img","src":"img/fig/f1103.jpg","alt":"图11-3直肠与腹膜的覆盖关系(男性)"},{"t":"p","x":"4.直肠肛管的解剖标志线直肠肛管内、外有4条重要的解剖标志线，4条标志线又可以组成3个重要的标志区(带)，即“四线三区”。"},{"t":"p","x":"四条标志线由头侧向尾侧排列分别是肛直线、齿状线、肛白线、肛缘线(图11-5)，四线之间所组成的三区分别是肛柱区、肛梳区、肛皮区(图11-6)。"},{"t":"img","src":"img/fig/f1106.jpg","alt":"图11-6直肠肛管的分区"},{"t":"img","src":"img/fig/f1105.jpg","alt":"图11-5直肠肛管的标志线"},{"t":"p","x":"(1)肛直线与解剖概念不同的是，从外科角度讲，肛直线才是直肠与肛管的交界线(图11-5)，这条分界线的特征有两个：①肛直线与直肠柱(肛柱)的上缘平齐；"},{"t":"p","x":"②肛直线是肛门内括约肌的上缘标志线。"},{"t":"p","x":"肛柱区是肛直线到齿状线的环形带状区域。"},{"t":"p","x":"(2)齿状线肛门瓣与直肠柱的基底在直肠与肛管交界处形成一条不整齐的交界线，称为齿状线。"},{"t":"p","x":"由于齿状线上、下组织起源不同，因此在血液供应、淋巴回流、神经支配、内衬上皮等方面也各不相同。齿状线是解剖上的重要标志线。"},{"t":"p","x":"其主要区别见表11-1。"},{"t":"table","img":"img/tab/t1101.jpg","cap":"表11-1齿状线上、下解剖的比较及临床意义"},{"t":"p","x":"(3)肛白线是肛门内、外括约肌的分界标志线，在进行肛门指检时，往往能触及位于肛白线深面的括约肌间沟。"},{"t":"p","x":"肛梳区是肛管内位于齿状线与肛白线之间、宽约1cm的环形区域，因该区域组织较厚、质地坚韧且表面光滑如梳、故得名“肛梳区”。"},{"t":"p","x":"(4)肛缘线又称肛门缘、是消化道位置最低的分界线。"},{"t":"p","x":"肛皮区是指位于肛白线与肛缘线之间的环形部分，因表面被覆皮肤而得名。"},{"t":"p","x":"另外、基于应用解剖学实践，在肛缘外侧还有一条重要的标志线，这条标志线是肛门外括约肌外轮廓的体表投影线，常用来指导保留括约肌的手术。"},{"t":"p","x":"这条标志线有3个特征：①视诊可见其内侧皮肤较深。呈黑褐色(黄种人)，其外侧皮肤较浅，呈正常的皮肤颜色；"},{"t":"p","x":"②视诊可见此标志线的前缘为会阴体，后缘为尾骨尖，其余侧缘为肛周皮肤皱褶的延伸终点线；"},{"t":"p","x":"③触诊时可触及在此线内侧是具有一定弹性质地的肛门外括约肌，而在其外侧是质地较软的坐骨直肠间隙的脂肪组织(图11-7)。"},{"t":"p","x":"在肛缘线与此标"},{"t":"img","src":"img/fig/f1107.jpg","alt":"图11-7括约肌外轮廓线"},{"t":"p","x":"志线之间的解剖区域，对应于肛门外括约肌外轮蹄的环形皮肤带、是术中辨认肛门外括约肌的重要标志区，因此这个环形皮肤带也称为肛肌区。"},{"t":"p","x":"5.直肠肛管周围的肌肉直肠肛管部周围环绕着许多肌肉组织，参与构成盆底，起到承载腹盆腔内脏器、控制排便等作用，主要包括肛门内括约肌、肛门外括约肌、肛提肌等。其中，肛门内括约肌和肛门外括约肌又被称为“肛门括约肌复合体”。"},{"t":"p","x":"(1)肛门内括约肌是直肠环状平滑肌向下延伸增厚，并环绕于直肠末端而形成的独特肌肉结构。"},{"t":"p","x":"肛门内括约肌上缘平直肠柱的上缘(即“肛直线”)，其下缘位于括约肌间沟(图11-4)。肛门内括约肌受自主神经支配，属于不随意肌，是协助排便的重要肌肉，它提供50%～85%的肛管静息压。"},{"t":"p","x":"(2)肛门外括约肌是由横纹肌构成的围绕肛管周围的环形肌群，它属于随意肌，受脊神经支配，由皮下部、浅部和深部组成。"},{"t":"p","x":"皮下部在肛门缘皮下，呈环形肌束，围绕肛管下部，位于内括约肌的外下方，两者之间形成的环形浅沟，称为括约肌间沟，正好对应于肛白线的部位。手术时皮下部若被切断，不致引起大便失禁。"},{"t":"p","x":"浅部在皮下部与深部之间，其肌纤维起源于尾骨发出的肛尾韧带，肛尾韧带向前延伸到肛管后缘附近，分为两束，于肛门内括约肌平面呈弧形绕过肛管两侧，至肛管前又合二为一，止于会阴中心腱。"},{"t":"p","x":"深部位于浅部的上外侧，亦为环形肌束，深部肌纤维束与耻骨直肠肌相互交织，解剖时较难将其分开(图11-4)。"},{"t":"p","x":"(3)肛提肌薄而阔，起自耻骨联合后下缘、肛提肌腱弓(位于耻骨联合与坐骨棘之间)及坐骨棘，向后下内走行，止于尾骨、肛尾韧带、会阴中心腱，并借肌纤维附着于直肠壁、阴道壁(女性)等结构。"},{"t":"p","x":"肛提肌分为耻骨直肠肌、耻骨尾骨肌和骼骨尾骨肌3个部分，其主要作用是承托盆内脏器、启闭肛门、协助排便(图11-8、图11-9)。"},{"t":"img","src":"img/fig/f1109.jpg","alt":"图11-9男性肛提肌(上面观)"},{"t":"img","src":"img/fig/f1108.jpg","alt":"图11-8女性肛提肌(上面观)"},{"t":"p","x":"肛门外括约肌的深、浅二部围绕直肠纵肌及肛门内括约肌、并且联合肛提肌的耻骨直肠肌，环绕肛管、直肠连接处组成一个肌环，称为肛管直肠环。手术时切断该环可引起肛门失禁。"},{"t":"p","x":"6.直肠肛管周围的间隙直肠肛管周围有许多潜在的间隙。常用的分类方式有三种：①根据间隙分布的前后方位不同、可以把这些间隙分为直肠肛管前方的间隙和直肠肛管后方的间隙。"},{"t":"p","x":"前方的间隙有邓氏筋膜间隙、肛管前间隙等，后方的间隙有直肠后间隙、肛管后间隙等。"},{"t":"p","x":"②根据直肠肛管间隙填充的内容物的不同，可以分为填充了脂肪的“脂肪间隙”，以及没有填充脂肪组织、而是由筋膜与筋膜相互融合所形成的“筋膜间隙”。"},{"t":"p","x":"脂肪间隙有坐骨直肠间隙、肛管前间隙、肛管后间隙、肛周皮下脂肪间隙等，筋膜间隙有括约肌间隙、邓氏筋膜间隙、直肠后间隙、肛提肌上间隙等。"},{"t":"p","x":"③根据直肠肛管周围间隙的位置深在与否，以肛提肌为界，可以把直肠肛管周围的间隙分为肛提肌上方的间隙和肛提肌下方的间隙。"},{"t":"h","lv":2,"x":"(1)肛提肌上方的间隙"},{"t":"p","x":"肛提肌上间隙：是盆膈上筋膜与直肠固有筋膜之间的筋膜间隙(图11-10)，是盆腔和肛周感染较易播散的区域，尤其在腹膜后坏死性筋膜炎感染播散的过程中，肛提肌上间隙是括约肌间隙感染播散的主要部位。"},{"t":"p","x":"直肠后间隙：是直肠固有筋膜与直肠骶骨筋膜之间的筋膜间隙。直肠后间隙的上界与乙状结肠系膜背侧的Toldt's间隙相通，其下界是直肠骶骨筋膜，其前方是直肠固有筋膜，其后方是盆壁筋膜。"},{"t":"h","lv":2,"x":"(2)肛提肌下方的间隙"},{"t":"p","x":"坐骨直肠间隙：位于肛提肌下方，是坐骨结节与肛管之间的一对潜在的楔形脂肪间隙，左右各一。该间隙空间较大，内侧以肛门外括约肌深部和浅部为界，外侧是坐骨结节、闭孔内肌及其筋膜，前方达尿生殖膈，后方至臀大肌下缘；"},{"t":"p","x":"间隙内富含脂肪组织和血管神经，是肛周脓肿的常见好发部位(图11-11)。坐骨直肠间隙向后内侧，可以通过肛管后深间隙(又称“Courtney间隙”)与对侧的坐骨直肠间隙交通，从而形成马蹄形脓肿。"},{"t":"img","src":"img/fig/f1110.jpg","alt":"图11-10直肠肛管周围的间隙1"},{"t":"img","src":"img/fig/f1111.jpg","alt":"图11-11直肠肛管周围的间隙2"},{"t":"p","x":"肛管前间隙：是位于肛提肌下方、肛管前方的脂肪间隙，可分为深浅两部。肛管前浅间隙位于会阴中心腱与皮肤之间，肛管前深间隙位于会阴中心腱的深面(图11-10)。"},{"t":"p","x":"肛管后间隙：是位于肛提肌下方、肛管后方的脂肪间隙，亦可分为深浅两部。肛管后浅间隙位于肛尾韧带与皮肤之间；"},{"t":"p","x":"肛管后深间隙位于肛尾韧带的深面，上方是肛提肌，并与两侧坐骨直肠间隙相通(图11-10)。7.直肠肛管的血管、淋巴和神经直肠、肛管部位的血液供应，主要来自4支动脉，即直肠上动脉、直肠下动脉、肛动脉和骶正中动脉。"},{"t":"p","x":"①直肠上动脉：是肠系膜下动脉的终末支，在直肠上端第3骶椎处分为左、右两支，沿直肠两侧下行，并分出许多小支与直肠下动脉、肛门动脉吻合(图11-"},{"t":"p","x":"12)。"},{"t":"p","x":"②直肠下动脉：为骼内动脉前干的一个分支，主要供应直肠前壁肌层和直肠下部各层，其大小与分布不规则(图11-13)。"},{"t":"p","x":"③肛动脉：由阴部内动脉分出，分数支至肛门内、外括约肌及肛管末端(图11-13)。"},{"t":"p","x":"④骶正中动脉：由腹主动脉分叉上方后壁发出，该动脉细小，分支不定(图11-12)。"},{"t":"img","src":"img/fig/f1112.jpg","alt":"图11-12直肠上动脉和骶正中动脉"},{"t":"img","src":"img/fig/f1113.jpg","alt":"图11-13直肠下动脉和肛动脉"},{"t":"p","x":"直肠肛管部位有两个静脉丛：①齿状线上的直肠上静脉丛：该静脉丛汇集成数支静脉，穿过直肠壁合成为直肠上静脉、经肠系膜下静脉入脾静脉、门静脉。这些静脉无瓣膜，穿过肌层时易受压迫，使直肠上静脉丛扩张而形成内痔。"},{"t":"p","x":"②位于齿状线以下的直肠下静脉丛：汇集于直肠下静脉、肛门静脉，入骼内静脉，进下腔静脉(图11-14)。"},{"t":"p","x":"直肠上静脉丛和直肠下静脉丛在肛白线附近互为交通，使门静脉系统与体静脉系统相通。门静脉高压症患者此处为一侧支循环的通路，故门静脉高压症患者引起的内痔出血不宜做手术结扎。"},{"t":"p","x":"直肠肛管的淋巴组织分为上、下两组。上组在齿状线以上，包括直肠黏膜下层、肌层、浆膜下及肠壁外淋巴网。"},{"t":"p","x":"这些淋巴网的淋巴液主要向3个方向汇流：①向上至直肠上淋巴结，再至肠系膜下淋巴结，最后至腹主动脉根部淋巴结；"},{"t":"p","x":"②向两旁至肛提肌上淋巴结，再至闭孔淋巴结，最后至骼内淋巴结；"},{"t":"p","x":"③向下至两侧坐骨直肠间隙淋巴结，然后穿过肛提肌至骼内淋巴结(图11-15)。"},{"t":"p","x":"下组在齿状线以下，包括肛门外括约肌、肛管和肛门周围皮下的淋巴网，经会阴部流入腹股沟淋巴结，至骼外淋巴结。上、下组淋巴网经吻合支可彼此相通。"},{"t":"img","src":"img/fig/f1115.jpg","alt":"图11-15直肠肛管的淋巴"},{"t":"img","src":"img/fig/f1114.jpg","alt":"图11-14直肠肛管的静脉"},{"t":"p","x":"直肠受属于自主神经系统的交感、副交感神经支配。肛管部的神经受体神经系统的阴部神经的分支支配，分布至肛提肌、外括约肌、肛管及肛门周围皮肤(图11-16)。"},{"t":"p","x":"所以，齿状线以上的黏膜对痛感迟钝，但在直肠胀满和按压时可感到不适；而肛管和肛门周围皮肤感觉异常敏锐，炎症或手术后刺激可引起剧烈疼痛，并引起反射性肛提肌和肛门内括约肌痉挛。"},{"t":"p","x":"另外，膀胱颈部的肌肉也受阴部神经支配，因此，肛门部疾病或手术可引起小便困难、尿潴留等。直肠与肛管的主要生理功能是排泄粪便、分泌黏液、吸收水分和部分药物。"},{"t":"p","x":"排便是一种复杂而协调的反射性生理动作。"},{"t":"p","x":"在正常情况下，粪便贮存于乙状结肠"},{"t":"img","src":"img/fig/f1116.jpg","alt":"图11-16阴部神经"},{"t":"p","x":"内，直肠内无粪便，当结肠出现蠕动时、将粪便推入直肠、使直肠下端膨胀而引起便意，反射性地引起内括约肌舒张和外括约肌松弛，从而排出粪便。直肠下端切除、神经反射障碍、括约肌张力丧失都可以引起大便失禁。"}],"entries":["e0697"]},{"title":"病因病机","blocks":[{"t":"p","x":"肛门直肠疾病的致病因素很多，但常见的主要有风邪、湿邪、燥邪、热邪、气虚、血虚、血瘀等。1.风邪明代戴原礼《秘传证治要诀·肠风脏毒》曰：“血清而色鲜者，为肠风。"},{"t":"p","x":"清代李用粹《证治汇补·便血》曰：“纯下清血者、风也。”说明风邪可引起下血。"},{"t":"p","x":"风性善行而数变，且多夹热，热伤肠络，血不循经，下溢而便血。因风引起的便血，其色鲜红，出血急暴，呈喷射状；多见于内痔实证。"},{"t":"p","x":"2.湿邪湿有内湿与外湿之分。外湿多因久居雾露潮湿之处所致；内湿多由饮食不节，损伤脾胃，脾失运化，湿自内生。"},{"t":"p","x":"湿性重浊，常先伤于下，故肛肠病中因湿邪致病者较多。湿与热结，致肛门部气血纵横、筋脉交错而发内痔；"},{"t":"p","x":"湿性秽浊，热伤络脉，可致下血如烟尘，正如《证治汇补·便血》所云“色如烟尘者，湿也”；湿热蕴阻肛门，经络阻隔，气血凝滞，热盛肉腐而成脓，易致肛痈；湿热下注大肠，肠道气机不利，经络阻滞，瘀血凝聚，可发为息肉痔。"},{"t":"p","x":"3.热邪《丹溪心法·痔疮》曰：“痔者，皆因脏腑本虚，外伤风湿，内蕴热毒。”热为阳邪，易伤津动血，热积肠道，耗伤津液而致热结肠燥，大便秘结不通；"},{"t":"p","x":"便秘日久，可导致局部气血不畅，瘀滞不散，结而为痔；热盛迫血妄行，血不循经，则发生便血；"},{"t":"p","x":"热与湿结，蕴阻肛门，腐蚀血肉而发肛痈。4.燥邪《医宗金鉴·外科心法要诀·痔疮》曰：“肛门围绕，折纹破裂，便结者，火燥也。"},{"t":"p","x":"燥有内燥、外燥之分，引起肛门疾病者多为内燥，常因饮食不节，恣饮醇酒，过食辛辣厚味，以致燥热内结，耗伤津液，无以下润大肠，则大便干结；或素有血虚，血虚津乏，肠道失于濡润而致大便干燥；"},{"t":"p","x":"临厕努责，常使肛门裂伤或擦伤痔核而致便血等。5.气虚《疮疡经验全书·痔漏图说》曰：“又有妇人产育过多，力尽血枯，气虚下陷，及小儿久痢，皆能使肛门突出。"},{"t":"p","x":"说明气虚也是肛门直肠疾病的发病因素之一。以脾胃失运、中气不足为主，妇人生育过多，小儿久泻久痢，老年气血不足、功能衰退，以及某些慢性疾病等，都能导致中气不足，气虚下陷，无以摄纳而引起直肠脱垂不收、内痔脱出不纳。"},{"t":"p","x":"气虚则正不胜邪，不能托毒外出，故肛门、直肠周围发生脓肿时，初起症状不明显，难消难溃，溃后脓水稀薄。6.血虚血虚常因失血过多或脾虚生血乏源所致。"},{"t":"p","x":"在肛门直肠疾病中，常因长期便血而致血虚，血虚则气虚，气虚则无以摄血而致下血，更导致血虚，如此往复，形成恶性循环。血虚生燥，无以润滑肠道，则大便燥结，损伤肛门而致肛裂，或擦伤内痔而便血。"},{"t":"p","x":"创口愈合需赖血的濡养，故血虚可致陈旧性肛裂难以愈合，肛痈易成肛瘘。7.血瘀久坐久立，或负重远行，或生育过多，或久泻久痢，或排便努挣，或气虚失摄等，均可导致血液瘀滞肛门不散；"},{"t":"p","x":"或血络损伤，血离经脉，溢于肛门皮下，瘀血凝聚成块，形成血栓外痔等。总之，上述致病因素可以单独致病，也可多种因素同时存在，如风多夹热、湿热相兼等。"},{"t":"p","x":"在病程中，有的为实证，有的为虚证，有的则为虚中夹实。所以在审证求因时要进行全面分析。"}],"entries":["e0698"]},{"title":"辨证","blocks":[{"t":"p","x":"1.辨症状肛门直肠疾病常见的症状有便血、肿痛、脱垂、坠胀、流脓、便秘、便频、分泌物增多等。由于病因不同，表现的症状及轻重程度也不一致。"},{"t":"p","x":"(1)便血是肛门直肠疾病最常见的症状，可见于内痔、肛裂、直肠息肉、直肠癌等多种疾病。"},{"t":"p","x":"由于疾病不同，病因各异，其表现特点也不一样。血不与大便相混，附于大便表面、或便时点滴而下，或一线如箭，无疼痛者，多为内痔；"},{"t":"p","x":"便血少而肛门部有撕裂样疼痛者，多为肛裂；儿童便血，大便次数和性质无明显改变者、多为直肠息肉；"},{"t":"p","x":"血与黏液相混，其色晦暗、大便次数增多者，应考虑有直肠癌的可能。便血鲜红，血出如箭、并伴有口渴、便秘、尿赤、舌红、脉数等，多属风热肠燥；"},{"t":"p","x":"便血色淡、日久而量多，伴有面色无华、头晕心悸、神疲乏力、舌淡、脉沉细等，属血虚肠燥。"},{"t":"p","x":"(2)肿痛常见于肛旁脓肿、内痔嵌顿、外痔水肿、血栓外痔等。"},{"t":"p","x":"肿势高突，疼痛剧烈，多为湿热阻滞，可伴有胸闷腹胀、体倦身重、食欲不振、发热、苔黄腻、脉濡数等，常见于肛旁脓肿等。"},{"t":"p","x":"微肿微痛者、每因气血、气阴不足又兼湿热下注之虚中夹实证，可伴发热不高、神疲乏力、头晕心悸、盗汗、便溏或便秘、舌淡或红、苔黄或腻、脉濡细等，常为肛旁脓肿症状不明显者或结核性肛周感染。"},{"t":"p","x":"(3)脱垂是Ⅱ、Ⅲ、IV期内痔和息肉痔、直肠脱垂的常见症状。"},{"t":"p","x":"直肠脱垂呈管状、环形；内痔脱出呈颗粒状，如枣形；息肉痔头圆而有长蒂。肛门松弛易脱出，轻者可自行回纳，重者不能自行回纳，伴有面色无华、头晕眼花、心悸气短、自汗盗汗、舌质淡、脉沉细弱等，为气血虚衰、中气下陷；"},{"t":"p","x":"内痔脱出，嵌于肛外，红肿疼痛，不易复位者，多为湿热下迫；若复因染毒，热毒熏灼则局部糜烂坏死，可伴有寒热烦渴、便干溲赤、舌红苔黄或腻、脉弦数等症状。"},{"t":"p","x":"(4)坠胀坠胀是便秘、肛隐窝炎、直肠炎患者常有的症状，坠胀伴有排便不畅或便次频数，多为粪便堵塞、俗称“热结旁流”；坠胀伴有脓血、黏液者，多见于锁肛痔、直肠炎、肛隐窝炎等；"},{"t":"p","x":"直立或行走时坠胀明显，卧床休息后减轻或消失者，多见于直肠黏膜内脱垂等。坠胀伴有乏力、气短、舌淡、脉沉细弱等，多为中气不足，升提无力；"},{"t":"p","x":"坠胀伴身重体倦、食欲不振、溲赤、苔黄或腻、脉弦或数者，多为湿热下注大肠，蕴阻肛门。"},{"t":"p","x":"(5)流脓常见于肛痈或肛瘘。"},{"t":"p","x":"脓出黄稠带粪臭者，多为湿热蕴阻肛门，热盛肉腐而成脓，伴有发热等症状。"},{"t":"p","x":"脓出稀薄不臭，或微带粪臭，淋漓不尽，疮口凹陷，周围有空腔，不易敛合者，多为气阴两亏兼湿热下注之证，可伴低热盗汗、面色萎黄、神疲纳呆、舌淡红、脉濡细或细数等。"},{"t":"p","x":"(6)便秘是痔、肛裂、肛痈等许多肛门直肠病的常见症状。"},{"t":"p","x":"腹满胀痛拒按，大便秘结，伴口臭、心烦、身热、溲赤、舌红苔黄燥、脉数等，多为燥热内结，热结肠燥；腹满作胀，喜按而大便燥结，伴有面色淡白、头晕心悸、神疲乏力、舌质淡、脉细无力等，多为血虚肠燥。"},{"t":"p","x":"(7)便频便次突然增多，伴有腹痛、呕吐者，多为急性肠炎；"},{"t":"p","x":"便意频繁，但排出不畅，无脓血、黏液者，多见于出口梗阻型便秘；便次增多，伴有脓血、黏液，里急后重，多见于直肠癌、溃疡性结直肠炎。"},{"t":"p","x":"伴舌淡、苔薄白，脉沉细无力，多属脾胃虚弱，脾失健运；伴舌红、苔黄或腻，脉弦滑有力，多为湿热下注所致。"},{"t":"p","x":"(8)分泌物常见于内痔脱出、直肠脱垂、肛瘘等。"},{"t":"p","x":"多为湿热下注或热毒蕴结所致，多伴有局部肿痛、口干、食欲不振、胸闷不舒、便溏或干结、溲赤、舌红、苔黄腻、脉弦数等。内痔、直肠脱垂嵌顿及实证肛瘘多见。"},{"t":"p","x":"分泌物清稀不臭，多为气虚脱肛、内痔脱垂或虚证肛瘘。2.辨部位肛门、直肠疾病的好发部位常用膀胱截石位表示。"},{"t":"p","x":"以时钟面的十二等分标记法，将肛门分成12个部位，会阴部正中称12点，骶尾部正中称6点，左侧中点称3点，右侧中点称9点，其余以此类推。"},{"t":"p","x":"内痔好发于肛门齿状线以上3、7、11点处，赘皮外痔多发生于6、12点处，血栓外痔好发于肛缘3、9点处，肛裂好发于6、12点处。过3、9点作一连线，肛瘘瘘管外口发生于连线上方的，其管道多为直行；"},{"t":"p","x":"发生于下方的，其管道往往弯曲，且其内口多在6点附近。凡瘘管外口距肛缘近的，其管道亦短(直通向肛内)；凡肛瘘外口距肛缘较远的，其管道亦长。"},{"t":"p","x":"环肛而生的肛瘘，其内口往往在6点附近。"}],"entries":["e0699"]},{"title":"检查","blocks":[{"t":"p","x":"1.检查注意事项肛门直肠疾病的诊断在详细询问病史后，必须进行必要的直肠肛管检查，才能做出正确诊断。检查前要给予患者适当的解释与安慰，不可在患者毫无思想准备的情况下突然进行，以免患者不合作。"},{"t":"p","x":"操作时动作要轻柔，尽可能减轻患者的痛苦。做肛门、直肠检查时要嘱患者做深呼吸或进行努挣，在指套或肛门镜上涂以润滑剂、先将指端或镜头抵在肛门口，待肛门松弛时徐徐插入。"},{"t":"p","x":"2.体位为了利于检查，暴露病变部位，临床上常采用以下几种体位，各种体位均有一定的优点，应根据检查和治疗的要求选择不同的体位。"},{"t":"p","x":"(1)侧卧位患者向左侧或右侧卧于检查床上，上腿充分向前屈曲，靠近腹部，使臀部及肛门充分暴露(图11-17)。"},{"t":"p","x":"侧卧位是临床常用的检查和治疗体位。"},{"t":"p","x":"(2)膝胸位患者跪伏在检查床上，胸部贴近床面，臀部抬高，使肛门充分暴露(图11-18)。"},{"t":"p","x":"膝胸位适用于检查直肠下部、直肠前壁或身体肥胖的患者。"},{"t":"img","src":"img/fig/f1117.jpg","alt":"图11-17左侧卧位"},{"t":"img","src":"img/fig/f1118.jpg","alt":"图11-18膝胸位"},{"t":"p","x":"(3)截石位患者仰卧于手术床上，两腿屈曲放在腿架上，将臀部移至台边缘，使肛门暴露良好(图11-19)。"},{"t":"p","x":"截石位是肛门直肠手术时常用的体位。"},{"t":"p","x":"(4)蹲位患者蹲踞并用力增加腹压(图11-20)。"},{"t":"p","x":"蹲位是检查脱出性疾病的常用体位，可查到Ⅱ、Ⅲ期内痔和脱肛、息肉痔等。"},{"t":"img","src":"img/fig/f1119.jpg","alt":"图11-19截石位"},{"t":"img","src":"img/fig/f1120.jpg","alt":"图11-20蹲位"},{"t":"p","x":"(5)折刀位患者俯伏于床上，髋关节屈曲，两腿随检查床下垂，臀部抬高，头部稍低。"},{"t":"p","x":"折刀位是肛门直肠手术时的常用体位(图11-21)。"},{"t":"p","x":"(6)弯腰扶椅位患者向前弯腰，双手扶椅，露出臀部。"},{"t":"p","x":"该体位适用于团体检查(图11-22)。"},{"t":"img","src":"img/fig/f1122.jpg","alt":"图11-22弯腰扶椅位"},{"t":"img","src":"img/fig/f1121.jpg","alt":"图11-21折刀位"},{"t":"h","lv":2,"x":"3.检查方法"},{"t":"p","x":"(1)肛门视诊患者取侧卧位或膝胸位，医生用双手将患者臀部分开，查看肛门周围有无外痔、内痔、息肉、脱垂、肛周脓肿、瘘管外口、肛周湿疹、肛门白斑、肛管裂口等。"},{"t":"p","x":"(2)肛门指诊又称肛诊或直肠指诊。"},{"t":"p","x":"患者取侧卧位，医生将戴有手套或指套的右手或左手食指涂上润滑剂、轻轻插入肛管及直肠、查看肛管及直肠下部有无异常改变，如狭窄、硬结、肿块等。若发现肿块，要注意肿块的大小、质地、活动度及指套有无染血等。"},{"t":"p","x":"(3)窥肛器检查俗称肛门镜检查。"},{"t":"p","x":"患者取侧卧位或膝胸位、嘱患者做深呼吸，放松肛门。将已插入塞芯的窥肛器慢慢地插入肛门内、取出塞芯后观察直肠黏膜有无充血、溃疡、息肉、肿瘤等病变；再将窥肛器缓缓退到齿状线附近、查看有无内痔、肛瘘内口、乳头肥大、肛隐窝炎等。"},{"t":"p","x":"(4)探针检查是寻找肛瘘内口及管道的常用检查方法。"},{"t":"p","x":"操作时应耐心、轻柔。禁用暴力。将探针自外口沿硬索状管道慢慢探入，同时以左手食指插入肛内作引导。"},{"t":"p","x":"通过检查可以探知肛瘘管道的走向、深度、长度，以及管道是否弯曲、有无分支、与肛管直肠是否相通等。"},{"t":"p","x":"(5)亚甲蓝染色检查是寻找肛瘘内口常用的方法。"},{"t":"p","x":"肛管直肠内放置一纱布卷，从肛瘘外口注入亚甲蓝稀释液、缓慢取出纱布卷，观察有无染色及染色的部位，以此判定有无内口及内口的位置。4.电子结肠镜检查适用于直肠和结肠的各种病变。"},{"t":"p","x":"尤其是对直肠和结肠肿瘤的早期诊断有重要意义。对原因不明的血便、黏液便、脓血便、慢性腹泻、里急后重、肛门直肠疼痛、粪便变形等，均应做电子结肠镜检查，以便早期明确诊断。"},{"t":"p","x":"但肛管狭窄、妇女月经期、精神病患者，有严重的心、肺、肾病患者及高血压患者不宜做此项检查。"},{"t":"p","x":"操作方法：检查前清洁灌肠，取膝胸位，将涂上润滑剂的结肠镜级缓插入肛门、直肠与结肠，边退镜边观察黏膜颜色，以及有无瘢痕、炎症、出血点、分泌物、结节、息肉、溃疡、肿块等病理改变。"},{"t":"p","x":"对于肿块、息肉、溃疡可做活体组织检查，以进一步明确诊断。术后应休息数小时，并观察患者有无腹痛、便血。"},{"t":"p","x":"必要时测血压及脉搏变化，有出血及肠穿孔时应及时处理。5.X线检查结肠运输试验和排便造影是肛肠科特有的检查，可诊断慢传输型便秘或出口梗阻型便秘。"},{"t":"p","x":"钡剂灌肠拍片可查得直肠和结肠的形状，肠内容物是否通过顺利，有无梗阻或狭窄。直肠和结肠外部病变如骶骨前畸胎瘤，可见有直肠移位。"},{"t":"p","x":"复杂性肛瘘瘘管通道不清、内口不明的，可用碘化油或15%碘化钠水溶剂从外口注入造影。直肠肿瘤与乙状结肠部位的息肉、肿瘤等，均可通过摄片发现病灶。"},{"t":"h","lv":2,"x":"6.实验室及其他检查根据患者的具体情况做必要的化验"},{"t":"p","x":"检查，如血常规、凝血时间、大小便常规、肝功能或其他检查。在手术前还应加做心电图、肝脏超声及相关传染病检查等。"},{"t":"p","x":"其他如直肠腔内超声检查、肛门直肠压力测定、排粪造影、结肠传输试验、CT、核磁共振(MRI)、血管造影、三维建模技术"},{"t":"img","src":"img/fig/f1123.jpg","alt":"图11-23肛瘿的三维建模技术"},{"t":"p","x":"(图11-23)等，已越来越广泛地应用于临床。"}],"entries":["e0700"]},{"title":"治疗","blocks":[{"t":"p","x":"肛门直肠疾病以外治及手术治疗为主，以内治调理为辅，但在一些特殊情况下或对于特殊病种，内治与外治同等重要。"},{"t":"h","lv":2,"x":"1.辨证论治"},{"t":"p","x":"一般用于肛门直肠疾病的初期或不需手术治疗者，或伴有严重的心、肝、肾脏疾病"},{"t":"p","x":"及年老体衰不宜手术者。"},{"t":"p","x":"(1)清热凉血适用于风热肠燥便血、血栓外痔初期等。"},{"t":"p","x":"方用凉血地黄汤或槐角丸等。"},{"t":"p","x":"(2)清热利湿适用于肛痈实证、肛隐窝炎、外痔肿痛等偏湿盛者。"},{"t":"p","x":"方用萆薢渗湿汤或龙胆泻肝汤加减。"},{"t":"p","x":"(3)清热解毒适用于肛痈实证、外痔肿痛等。"},{"t":"p","x":"方用黄连解毒汤或仙方活命饮加减。"},{"t":"h","lv":2,"x":"(4)清热通腑适用于热结肠燥便秘者。方用大承气汤或麻仁丸加减。"},{"t":"p","x":"(5)活血化瘀适用于气滞血瘀或瘀血凝结之外痔。"},{"t":"p","x":"方用活血散瘀汤加减。"},{"t":"p","x":"(6)补养气血适用于素体气血不足或久病气血虚弱者。"},{"t":"p","x":"方用八珍汤或十全大补汤加减。"},{"t":"h","lv":2,"x":"(7)生津润燥适用于血虚津乏便秘者。方用润肠汤或五仁汤加减。"},{"t":"p","x":"(8)补中升陷适用于小儿或年老体衰者、经产妇气虚下陷之直肠脱垂、内痔脱出等。"},{"t":"p","x":"方用补中益气汤。2.外治疗法熏洗、敷药、塞药是治疗肛门直肠疾病常用的外治方法，可选择一种或多种治疗方法。"},{"t":"p","x":"(1)熏洗以药物加水煮沸或用散剂冲泡，先熏后洗，具有清热解毒、消肿止痛、收敛止血、祛风除湿、杀虫止痒等作用。"},{"t":"p","x":"适用于内痔脱垂、嵌顿、术后水肿、外痔肿痛、脱肛、肛周湿疹等。常用五倍子汤、苦参汤加减。"},{"t":"p","x":"(2)敷药即以药物敷于患处。"},{"t":"p","x":"每日大便后先坐浴，再外敷药物，每日1～2次。方用九华膏、五倍子散、黄连膏、消痔膏等，具有消炎、止痛、生肌、收敛、止血等作用。"},{"t":"p","x":"此外，尚有清热消肿的金黄膏，提脓化腐的九一丹，生肌收口的生肌散、白玉膏等。"},{"t":"p","x":"(3)塞药是将药物制成栓剂、纳入肛内，可以溶化、吸收，直接作用于病变部位。"},{"t":"p","x":"一般用于内痔、肛裂、肛瘘、肛周脓肿、肛隐窝炎及其术后，直肠炎也可用栓剂治疗。常用的栓剂有痔疮栓。"},{"t":"p","x":"3.手术疗法如结扎疗法、挂线疗法及手术治疗等，详见各病种。"}],"entries":["e0701"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持大便通畅，每天定时排便，临厕不宜久蹲努责。2.注意饮食卫生，少食辛辣刺激性食物，多吃蔬菜水果，以保持大便通畅。"},{"t":"p","x":"3.保持肛门清洁，常用温水清洗肛门，勤换内裤，便纸要柔软，防止擦伤。4.加强锻炼，增强体质，促进全身气血流畅和增加肠道蠕动。"},{"t":"p","x":"采用导引法、提肛运动等方法加强肛门功能锻炼，是防治肛门直肠疾病的有效方法之一。5.积极治疗易引起痔瘘的高血压病、门静脉高压症、糖尿病等全身疾病，肛门周围的疮、痈、肠道寄生虫病要及时检查与治疗，以防继发肛瘘、肛周湿疹等。"}],"entries":["e0702"]}]},{"id":"d1101","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"痔","displayName":"痔","parentId":"","printedPage":211,"pdfPage":226,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"痔，是直肠末端黏膜下和肛管皮肤下的静脉丛发生扩大、曲张所形成的柔软静脉团，又称痔疮、痔核。以便血、脱出、肿痛为临床特点。"},{"t":"p","x":"男女老幼皆可发病，据2025年国内流行病学调查显示，我国成人肛肠疾病患病率高达50.1%。痔的发病率占肛肠疾病的49.14%，居首位，多见于25～64岁的成年人，男女之间患病率无明显差异。"},{"t":"p","x":"根据其发病部位的不同，临床上可分为内痔、外痔和混合痔(图11-24)。"}],"entries":["e0703"]}]},{"id":"d1101a","kind":"sub","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"内痔","displayName":"痔·内痔","parentId":"d1101","printedPage":211,"pdfPage":226,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"内痔是盆底动力学改变、Treits肌退行变性和肛垫内动静脉吻合调节障碍导致的肛垫肥大或脱垂。内痔是肛门直肠最常见的疾病，好发于截石位的3、7、11点处，通常又称为母痔，其余部位发生的内痔则称为子痔(图11-25)。"},{"t":"p","x":"其主要临床表现是便血、痔核脱出及肛门不适感。"},{"t":"img","src":"img/fig/f1125.jpg","alt":"图11-25母痔区(截石位3、7、11点)"},{"t":"img","src":"img/fig/f1124.jpg","alt":"图11-24痔的分类"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"中医学认为，本病的发生多因脏腑本虚，兼因久坐久立，负重远行，或长期便秘，或泻痢日久，或临厕久蹲，或饮食不节，过食辛辣醇酒厚味，都可导致脏腑功能失调，风湿燥热下迫大肠瘀阻魄门，瘀血浊气结滞不散、筋脉懈纵而成痔。"},{"t":"p","x":"日久气虚，中气下陷，不能摄纳则痔核脱出。1.风伤肠络风善行而数变、又多夹热，风热伤于肠络，导致血不循经而溢于脉外，所下之血色泽鲜红、下血暴急呈喷射状。"},{"t":"p","x":"2.湿热下注多因饮食不节、恣食生冷、肥甘，伤及脾胃而滋生内湿。湿与热结，下迫大肠，导致肛门部气血纵横、经络交错而生内痔。"},{"t":"p","x":"热盛则迫血妄行，血不循经，则血下溢而便血；湿热下注大肠、肠道气机不畅、经络阻滞，则肛门内有块物脱出。"},{"t":"p","x":"3.气滞血瘀气为血之帅，气行则血行，气滞则血瘀。热结肠燥，气机阻滞而运行不畅，气滞则血瘀阻于肛门，故肛门内块物脱出，坠胀疼痛；"},{"t":"p","x":"气机不畅，统摄无力，则血不循经，导致血栓形成。4.脾虚气陷老人气虚，或妇人生育过多，或小儿久泻久痢，均可致脾胃功能失常，脾虚气陷，中气不足，无力摄纳，导致痔核脱出不得回纳。"},{"t":"p","x":"气虚则无以生化，无力摄血，气虚则血虚，导致气血两虚，故下血量多而色淡。西医学对痔的病因病机的认识尚无定论，目前较为认同的是“静脉曲张”“血管增生”“肛垫下移”三种学说。"}],"entries":["e0704","e0705"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现初期常以无痛性便血为主要症状，血液与大便不相混合，多在排便时出现手纸带血、滴血或射血。"},{"t":"p","x":"出血呈间歇性，饮酒、过劳、便秘、腹泻等诱因常使症状加重，出血严重者可出现继发性贫血。随着痔核增大，在排便时可脱出，若不及时回纳可形成内痔嵌顿。"},{"t":"p","x":"患者常伴有大便秘结，内痔持续脱出时有分泌物溢出，并可有肛门坠胀感。"},{"t":"h","lv":3,"x":"(2)分期由于病程长短及病情轻重不同，可分为4期。"},{"t":"p","x":"I期内痔：痔核较小，不脱出，以便血为主。Ⅱ期内痔：痔核较大，大便时可脱出肛外，便后可自行回纳，便血或多或少。"},{"t":"p","x":"Ⅲ期内痔：痔核更大，大便时痔核脱出肛外，甚至行走、咳嗽、喷嚏、站立时也会脱出，不能自行回纳，须用手推回，或平卧、热敷后才能回纳；便血不多或不出血。"},{"t":"p","x":"IV期内痔：痔核脱出，不能及时回纳，嵌顿于外，因充血、水肿和血栓形成，以致肿痛、糜烂和坏死，即嵌顿性内痔。"},{"t":"p","x":"(3)专科检查指诊可触及柔软、表面光滑、无压痛的黏膜隆起。"},{"t":"p","x":"肛门镜下见齿状线上黏膜呈半球状隆起，色暗紫或深红，表面可有糜烂或出血点。"},{"t":"h","lv":3,"x":"(4)辅助检查"},{"t":"p","x":"1)一般检查包括血常规、尿常规、肝肾功能、出凝血时间、凝血酶原时间、心电图、超声检查和胸部X线片等。"},{"t":"p","x":"血常规检查白细胞总数及中性粒细胞比例一般无明显变化。长期便血不及时治疗，可引起红细胞及血红蛋白下降，甚至贫血。"},{"t":"p","x":"2)内窥镜检查 ①肛门镜检查：主要观察内痔的部位、大小、数目、色泽、溃疡和出血点等情况。"},{"t":"p","x":"检查时应按顺序逐项检视，不可遗漏。"},{"t":"p","x":"②电子内镜检查：对于肛门镜检查不满意或有可疑病变不能明确诊断者，可采用电子内镜检查，如电子肛门镜检查、电子直乙结肠镜检查、电子结肠镜检查等。"},{"t":"p","x":"检查前须进行肠道准备，上述检查过程中可进行针对性的图像采集、活体组织检查和治疗。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-2)"},{"t":"table","img":"img/tab/t1102.jpg","cap":"表11-2内痔与直肠息肉、肛乳头肥大、肛裂、直肠脱垂、直肠癌的鉴别"}],"entries":["e0706"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s1101a01","name":"风伤肠络证","clinic":"大便带血、滴血或喷射状出血，血色鲜红，或有肛门瘙痒等；舌质红，苔薄白或薄黄，脉浮数","treat":"清热凉血祛风","formula":"凉血地黄汤加减。大便秘结者加槟榔、大黄等","formulaNames":["凉血地黄汤"]},{"t":"syn","sid":"s1101a02","name":"湿热下注证","clinic":"便血色鲜，量较多，肛内肿物外脱，可自行回缩，肛门灼热；舌质红，苔黄腻，脉弦数","treat":"清热利湿止血","formula":"脏连丸加减。出血量多者，加地榆炭、仙鹤草等；灼热较甚者，加白头翁、秦艽等","formulaNames":["脏连丸"]},{"t":"syn","sid":"s1101a03","name":"气滞血瘀证","clinic":"肛内肿物脱出，甚或嵌顿，肛管紧缩，坠胀疼痛，甚则肛缘水肿、血栓形成，触痛明显；舌质红或暗红，苔白或黄，脉弦细涩","treat":"清热利湿，祛风活血","formula":"止痛如神汤加减。肿物紫暗明显者，加红花、牡丹皮；肿物淡红光亮者，加龙胆草、木通等","formulaNames":["止痛如神汤"]},{"t":"p","x":"舌质红或暗红，苔白或黄，脉弦细涩。治法：清热利湿，祛风活血。"},{"t":"syn","sid":"s1101a04","name":"脾虚气陷证","clinic":"肛门松弛，痔核脱出需手法复位，便血色鲜或淡；面白少华，神疲乏力，少气懒言，纳少便溏；舌质淡，边有齿痕，苔薄白，脉弱","treat":"补中益气","formula":"补中益气汤加减。大便稍干者、加肉苁蓉、火麻仁；贫血较甚时，合四物汤","formulaNames":["补中益气汤"]},{"t":"p","x":"大便稍干者、加肉苁蓉、火麻仁；贫血较甚时，合四物汤。2.外治疗法适用于各期内痔及术后。"},{"t":"p","x":"(1)熏洗以药物加水煮沸、先熏后洗、或用毛巾蘸药液趁热湿敷患处，冷则更换。"},{"t":"p","x":"具有活血止痛、收敛消肿等作用。常用五倍子汤、苦参汤等。"},{"t":"p","x":"(2)外敷将药物敷于患处。"},{"t":"p","x":"具有消肿止痛、收敛止血、祛腐生肌等作用。根据不同病情可选用油膏或散剂，如九华膏、黄连膏、消痔膏等。"},{"t":"p","x":"(3)塞药将药物制成栓剂、塞入肛内。"},{"t":"p","x":"具有消肿、止痛、止血作用。"},{"t":"p","x":"(4)挑治适用于内痔出血。"},{"t":"p","x":"其机理是疏通经络，调理气血，促使肿消痛减。常用穴位有肾俞、大肠俞、长强、上、次、中、下醪等，一般挑治1次即可见效，必要时可隔10日再挑治1次。"},{"t":"p","x":"(5)枯痔即以药物如枯痔散、灰皂散敷于Ⅱ、Ⅲ期脱出肛外的内痔痔核表面，具有强腐蚀作用，能使痔核干枯坏死、达到痔核脱落痊愈的目的。"},{"t":"p","x":"此法目前已较少采用。"},{"t":"sub","title":"3.手术疗法","blocks":[{"t":"p","x":"(1)注射疗法是目前治疗内痔的常用方法，按其所起的作用不同，分为硬化萎缩和坏死枯脱两种方法。"},{"t":"p","x":"由于坏死枯脱疗法术后常有大出血、感染、直肠狭窄等并发症，故目前国内外普遍应用的都是硬化萎缩疗法。适应证：I、Ⅱ、Ⅲ期内痔，内痔兼有贫血者，混合痔的内痔部分。"},{"t":"p","x":"禁忌证：IV期内痔，外痔，内痔伴肛门周围急、慢性炎症或腹泻，内痔伴有严重肺结核、高血压及肝、肾疾病或血液病患者。因腹腔肿瘤引起的内痔和妊娠期妇女。常用药物：首选消痔灵注射液，还可选用芍倍注射液等。"},{"t":"p","x":"操作方法：腰俞穴麻醉或局部麻醉后取侧卧位或截石位，肛门部常规消毒，在肛镜直视下局部常规再次消毒，以10mL针管(5号针头)抽取1:1浓度(即消痔灵注射液或芍倍注射液用1%利多卡因液稀释1倍)注射液10mL，于痔核上距齿状线0.5cm处的黏膜下层，针头斜向15°进行注射，每个痔核注射1～3mL，注入药量多少的标志以痔核弥漫肿胀为度，总量不超过30mL(图11-26)。"},{"t":"p","x":"注射完毕，术者用食指轻轻按摩注射部位，使药液扩散，防止硬结形成。肛管内放入凡士林纱条，外盖纱布，胶布固定。"},{"t":"img","src":"img/fig/f1126.jpg","alt":"图11-26内痔注射疗法"},{"t":"p","x":"注意事项：①注射时必须注意严格消毒，每次注射都须再次消毒；"},{"t":"p","x":"②必须用5号针头进行注射，否则针孔大，易出血；"},{"t":"p","x":"③进针后应先做回血试验，注射药液宜缓缓进行；"},{"t":"p","x":"④进针的针头勿向痔核内各方向乱刺，以免过多损伤痔内血管而引起出血，致使痔核肿大，增加局部的液体渗出，延长痔核的枯脱时间；"},{"t":"p","x":"⑤注意勿使药液注入外痔区，或注射位置过低而使药液向肛管扩散，造成肛门周围水肿和疼痛；"},{"t":"p","x":"⑥操作时应先注射小的痔核，再注射大的痔核，以免小痔核被大痔核挤压、遮盖，从而增加操作的难度。"},{"t":"p","x":"(2)结扎疗法是中医传统的外治法，除丝线结扎外，也可用药制丝线、纸裹药线缠扎痔核根部，以阻断痔核的气血流通，使痔核坏死脱落，遗留创面修复自愈。"},{"t":"p","x":"关于结扎疗法治疗痔疮，早在宋代《太平圣惠方》中就有记载：“用蜘蛛丝，缠系痔鼠乳头，不觉自落。”由于其适应证广，操作简单，远期疗效比较理想，所以目前是治疗内痔广泛使用的方法之一。"},{"t":"p","x":"临床上常用的有单纯结扎法、贯穿结扎法和胶圈套扎法。"},{"t":"p","x":"1)单纯结扎法"},{"t":"p","x":"适应证：I、Ⅱ期内痔。禁忌证：肛门周围有急性脓肿或湿疮者，内痔伴有痢疾或腹泻者、因腹腔肿瘤引起的内痔，内痔伴有严重肺结核、高血压及肝、肾疾病或血液病的患者，临产期孕妇。"},{"t":"p","x":"操作方法：患者取侧卧位(患侧在下)或截石位，尽量暴露臀部，局部或腰俞麻醉后，肛管及直肠下段常规消毒，再用双手示指扩肛、使痔核暴露；"},{"t":"p","x":"用弯血管钳夹住痔核基底部，用左手向肛外同一方向牵引，并在齿状线下方剪一小口，用10号丝线在止血钳下方剪口处结扎，同法处理其他部位的痔。术后肛内纳入痔疮栓一枚或九华膏、红油膏适量、纱布覆盖，胶布固定。"},{"t":"p","x":"2)贯穿结扎法"},{"t":"p","x":"适应证：Ⅱ、Ⅲ期内痔，对纤维型内痔更为适宜。禁忌证：同单纯结扎法。"},{"t":"p","x":"操作方法：基本同单纯结扎法。用弯血管钳夹住痔核基底部，用左手向肛外同一方向牵引、右手用持针钳夹住已穿有丝线的缝针、将双线从痔核基底部中央稍偏上穿过；"},{"t":"p","x":"将已贯穿痔核的双线交叉放置，并用剪刀沿齿状线剪一浅表裂缝、再分段进行“8”字形结扎或做“回”字形结扎；结扎完毕后，用弯血管钳挤压被结扎的痔核，也可在被结扎的痔核内注射6%明矾溶液，以加速痔核坏死；"},{"t":"p","x":"最后将存留在肛外的线端剪去，再将痔核送回肛内，术后肛内纳入痔疮栓一枚或挤入九华膏、红油膏适量，纱布覆盖，胶"},{"t":"img","src":"img/fig/f1127.jpg","alt":"图11-27贯穿结扎法"},{"t":"p","x":"布固定(图11-27)。注意事项：①结扎内痔时，宜先扎小的痔核，后扎大的痔核；"},{"t":"p","x":"②缝针穿过痔核基底部时，不可穿入肌层，否则结扎后可引起肌层坏死或并发肛门直肠周围脓肿；"},{"t":"p","x":"③结扎术后当天不要解大便，若便后痔核脱出，应立即将痔核送回肛内，以免发生水肿，加剧疼痛反应；"},{"t":"p","x":"④结扎后的7～9天为痔核脱落阶段，嘱患者减少行动，大便时不宜用力努挣，以避免术后大出血。"},{"t":"p","x":"3)弹力线套扎法自动弹力线痔疮套扎器是在胶圈套扎器的基础上进一步改进，通过套扎痔核基底部，阻断静脉倒流，减少瘀滞，使痔核组织缺血、坏死、萎缩、脱落，通过套扎痔上黏膜，上提肛垫，消除症状。"},{"t":"p","x":"适应证：各期内痔，各期混合痔的内痔部分，经痔上黏膜环切或其他疗法治疗后痔块或肛垫回缩不全者，以及直肠局灶良性病变，如直肠息肉。禁忌证：环形痔嵌顿或绞窄，存在出血性疾病。"},{"t":"p","x":"操作方法：麻醉成功后，术区常规消毒、铺无菌巾，肛内再次消毒。插入肛门镜，检查痔核的位置及数目，选定套扎部位。"},{"t":"p","x":"连接套扎器与负压吸引器，术者持套扎器将痔核吸入套扎器内，当负压表指针上升至-0.08MPa左右时，释放弹力线并收紧，最后释放气压并剪去多余的弹力线。其余痔核的套扎方法相同。"},{"t":"p","x":"注意事项：①对于轻度内痔，一般采用痔块基底套扎法即可；而对于中、重度内痔，联合采用痔块基底套扎法与痔上黏膜套扎法效果更好。"},{"t":"p","x":"②套扎点至少应位于齿状线上方1.0cm处，切勿扎住齿状线或肛管皮肤，否则会引起疼痛或重度坠胀感，严重者甚至出血与感染。"},{"t":"p","x":"③套扎点一般选择截石位3、"},{"t":"p","x":"7、11点，但应依痔块的具体情况而定。"},{"t":"p","x":"④术后应保持大便通畅。"},{"t":"p","x":"另外，内痔的治疗还有铜离子电化学疗法、低温电凝技术、痔切闭术、痔上黏膜环切术(procedure for prolapsing hemorrhoids,PPH)、痔动脉结扎术(hemorrhoid artery ligatoion,HAL)、选择性痔上黏膜切除术(tissue selccting therapy,TST)、肠镜下内痔电切术等。"}]},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)中成药治疗常用的有槐角丸、地榆丸、脏连丸、化痔片、云南白药等。"},{"t":"p","x":"(2)西药治疗出血明显者，可口服安络血等止血药物改善症状；"},{"t":"p","x":"肿胀疼痛剧烈者，可用地奥司明片等改善微循环，亦可加服消炎镇痛的药物。"},{"t":"p","x":"(3)针灸治疗针灸对痔出血、脱出、肿痛和肛门下坠均有良好效果，常用穴位有攒竹、飞扬、龈交、长强、承山、会阳、委中等。"}]}],"entries":["e0707","e0708","e0709","e0710","e0711","e0712","e0713"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.养成每天定时排便的良好习惯，防止便秘；蹲厕时间不宜过长，以免肛门部瘀血。2.注意饮食调和，足量饮水、多食蔬菜，少食辛辣食物。"},{"t":"p","x":"3.避免久坐久立，定时做提肛锻炼。4.发生内痔应及时治疗，防止进一步发展。"}],"entries":["e0714"]}]},{"id":"d1101b","kind":"sub","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"外痔","displayName":"痔·外痔","parentId":"d1101","printedPage":216,"pdfPage":231,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"外痔是指发生于肛管齿状线之下的痔。"},{"t":"p","x":"多由肛缘皮肤感染，或痔外静脉丛破裂出血，或反复感染、结缔组织增生，或痔外静脉丛扩大曲张而成。其临床特点是自觉肛门坠胀、疼痛，有异物感。"},{"t":"p","x":"由于临床症状、病理特点及其过程不同，外痔可分为炎性外痔、血栓性外痔、结缔组织性外痔、静脉曲张性外痔四种。"}],"entries":["e0715"]},{"title":"炎性外痔","blocks":[{"t":"p","x":"由于肛缘皮肤破损或感染，使其局部产生红肿、疼痛的外痔，称为炎性外痔。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"饮食不节，醉饱无时，恣食肥腻，过食辛辣，内蕴热毒，外伤风湿或破损染毒，以致气血、湿热结聚肛门，冲突为痔。"},{"t":"h","lv":3,"x":"辨病"},{"t":"p","x":"1.诊断多因过食辛辣、饮烈性酒、腹泻、便秘等因素而诱发。起病时肛缘皮肤突然肿胀疼痛，伴肛门异物感，排便、坐位、行走甚至咳嗽等动作时均可加重疼痛。"},{"t":"p","x":"检查可见肛缘皮肤肿胀明显、光亮、色淡红或淡白，触痛明显，内无硬结。"},{"t":"h","lv":4,"x":"2.鉴别诊断(表11-3)"},{"t":"table","img":"img/tab/t1103.jpg","cap":"表11-3炎性外痔、血栓性外痔、结缔组织性外痔的鉴别"},{"t":"h","lv":3,"x":"治疗"},{"t":"p","x":"早期以清热解毒消肿为主，内治、外治相结合。"},{"t":"h","lv":4,"x":"1.辨证论治"},{"t":"syn","sid":"s1101b01","name":"湿热蕴结证","clinic":"肛缘肿物肿胀、疼痛，咳嗽、行走、坐位均可使疼痛加重；便干，溲赤；舌质红，苔薄黄或黄腻，脉滑数或浮数","treat":"清热祛风利湿","formula":"止痛如神汤加减。便秘者加大黄、槟榔等，溲赤者加木通、滑石等","formulaNames":["止痛如神汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)熏洗药物加水煮沸，先熏后洗，或用毛巾蘸药液趁热湿敷患处，冷则更换。"},{"t":"p","x":"具有活血止痛、收敛消肿等作用。常用药物如五倍子汤、苦参汤等。"},{"t":"p","x":"(2)外敷将药物敷于患处。"},{"t":"p","x":"具有消肿止痛、收敛止血、祛腐生肌等作用。常用药物如九华膏、黄连膏、消痔膏等。"},{"t":"p","x":"3.手术疗法外痔反复发炎或痔体较大影响行走者，可考虑手术治疗，采用外痔切除术。"},{"t":"p","x":"(1)适应证炎性外痔。"},{"t":"p","x":"(2)操作方法取截石位或侧卧位，局麻或腰俞麻醉，局部常规消毒，用组织钳提起外痔组织，以剪刀环绕其痔根四周做一梭形切口，切口上端向肛管，将痔体由括约肌内侧间隙分离，切除痔组织，结扎出血点，修剪皮缘，外敷桃花散或云南白药，凡士林纱条敷盖，无菌纱布包扎。"},{"t":"p","x":"每次便后用苦参汤或五倍子汤坐浴，伤面外敷红油膏或黄连膏，直至痊愈。4.其他疗法远红外线、微波或超短波治疗。"}]}],"entries":["e0716","e0717","e0718","e0719","e0720","e0721"]},{"title":"血栓性外痔","blocks":[{"t":"p","x":"血栓性外痔是指痔外静脉破裂出血，血液凝结于皮下，血栓形成而致的圆形肿物。"},{"t":"p","x":"其临床特点是肛门部突然剧烈疼痛，并有暗紫色肿块。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"由于内热血燥，或便时努挣，或用力负重，致使肛缘皮下的痔外静脉破裂，血溢脉外，瘀积皮下而致血栓形成。"},{"t":"h","lv":3,"x":"辨病"},{"t":"p","x":"1.诊断好发于干燥季节，患者以中年男性居多数，病前有便秘、饮酒或用力负重等诱因。起病时肛门部突然剧烈疼痛，肛门缘截石位3、9点处可见暗紫色圆球形肿块，排便、坐下、走路甚至咳嗽等动作时均可加重疼痛。"},{"t":"p","x":"检查可见肛缘皮肤表面隆起一暗紫色圆形结节，界限清楚，质地韧，可移动，触痛明显。"},{"t":"h","lv":4,"x":"2.鉴别诊断(表11-4)"},{"t":"table","img":"img/tab/t1104.jpg","cap":"表11-4血栓性外痔、静脉曲张性外痔、嵌顿性内痔的鉴别"},{"t":"h","lv":3,"x":"治疗"},{"t":"p","x":"血栓较小者可给予外治疗法，佐以内治；血栓较大者可手术剥离治疗。"},{"t":"h","lv":4,"x":"1.辨证论治"},{"t":"syn","sid":"s1101b02","name":"血热瘀阻证","clinic":"肛缘肿物突起，肿痛剧烈难忍，肛门坠胀疼痛，局部可触及硬结节，其色暗紫；伴便秘，口渴，烦热；舌紫，苔淡黄，脉弦涩","treat":"清热凉血。消肿止痛","formula":"凉血地黄汤加减。肿块较硬时可加桃仁、红花，便秘时加大黄、槟榔","formulaNames":["凉血地黄汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)熏洗同炎性外痔。"},{"t":"p","x":"(2)外敷同炎性外痔。"},{"t":"p","x":"3.手术疗法可采用血栓外痔剥离术。"},{"t":"p","x":"(1)适应证血栓性外痔较大，血块不易吸收，炎症水肿局限者。"},{"t":"p","x":"(2)操作方法取侧卧位，病侧在下方，局部常规消毒。"},{"t":"p","x":"局麻后在肿块中央做放射状或梭形切口(图11-28)、用止血钳将血块分离并摘除(图11-29)，然后修剪伤口两侧皮瓣，使创口引流通畅，创面消毒后，外盖无菌纱布，胶布固定。每次便后坐浴并常规换药，直至痊愈。"},{"t":"img","src":"img/fig/f1128.jpg","alt":"图11-28剪开血栓表面皮肤"},{"t":"img","src":"img/fig/f1129.jpg","alt":"图11-29剥离血栓"}]}],"entries":["e0722","e0723","e0724","e0725","e0726","e0727"]},{"title":"结缔组织性外痔","blocks":[{"t":"p","x":"结缔组织性外痔是由急、慢性炎症反复刺激，使肛缘的皮肤增生、肥大而成，痔内无曲张静脉丛。肛门异物感为其主要症状。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"炎性外痔、血栓性外痔、陈旧性肛裂、湿疹等反复发作，或内痔反复脱垂或妊娠分娩，负重努挣，导致邪毒外侵，湿热下注，使局部气血运行不畅，筋脉阻滞，瘀结不散，日久结缔组织增生肥大，结为皮赘。"},{"t":"h","lv":3,"x":"辨病"},{"t":"p","x":"1.诊断肛门边缘处赘生皮瓣，逐渐增大，质地柔软，一般无疼痛，不出血，仅觉肛门有异物感，偶有染毒而肿胀时才觉疼痛，肿胀消失后赘皮依然存在。若发生于截石位6、12点处的外痔，常由肛裂引起；"},{"t":"p","x":"若发生于3、7、11点处的外痔，多伴有内痔；若呈环状或花冠状，多发生于经产妇。"},{"t":"p","x":"2.鉴别诊断参见“炎性外痔”。"},{"t":"h","lv":3,"x":"治疗"},{"t":"p","x":"无临床症状者不需要治疗，只有反复发炎、肿胀明显时才考虑手术治疗。当外痔染毒发炎肿痛时，可外用熏洗法，如苦参汤加减；或外敷消痔膏、黄连膏等。"},{"t":"p","x":"参见“炎性外痔”的外治法。对反复发生炎症或赘皮较大影响清洁卫生者，可考虑手术治疗。"},{"t":"p","x":"可采用外痔切除术，操作方法参见“炎性外痔”。"}],"entries":["e0728","e0729","e0730","e0731"]},{"title":"静脉曲张性外痔","blocks":[{"t":"p","x":"静脉曲张性外痔是痔外静脉丛发生扩大、曲张，在肛缘形成圆形或椭圆形的柔软团块。坠胀不适感为其主要症状。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"多因Ⅱ、Ⅲ期内痔反复脱出，或妊娠分娩，负重努挣，腹压增加，致使筋脉横解，瘀结不散而成。若湿与热结、聚于肛门，则肿胀疼痛。"},{"t":"h","lv":3,"x":"辨病"},{"t":"p","x":"1.诊断发生于肛管齿状线以下，局部有圆形或椭圆形肿物，触之柔软，平时不明显，在排便或下蹲等腹压增加时肿物体积增大，并呈暗紫色、便后或经按摩后肿物体积缩小变软。一般无疼痛，仅有坠胀不适感。"},{"t":"p","x":"若便后肿物不缩小，可致周围组织水肿而引起疼痛。有静脉曲张性外痔的患者多伴有内痔。"},{"t":"p","x":"2.鉴别诊断参见血栓性外痔。"},{"t":"h","lv":3,"x":"治疗"},{"t":"p","x":"无临床症状者不需要治疗。若破损染毒、继发感染者可考虑对症治疗。"},{"t":"h","lv":4,"x":"1.辨证论治"},{"t":"p","x":"若染毒者可按下述证型治疗"},{"t":"syn","sid":"s1101b03","name":"湿热下注证","clinic":"便后肛门缘肿物隆起不缩小，坠胀感明显，甚则灼热疼痛，或有滋水；便干，溲赤；舌红，苔黄腻，脉滑数","treat":"清热利湿，活血散瘀","formula":"萆薢化毒汤合活血散瘀汤加减","formulaNames":["萆薢化毒汤","活血散瘀汤"]},{"t":"p","x":"2.外治疗法肿胀明显时可用苦参汤熏洗，黄连膏外敷。参见“炎性外痔”的外治法。"},{"t":"p","x":"3.手术疗法可采用括约肌内间隙痔静脉丛剥离术。"},{"t":"p","x":"(1)适应证单纯性静脉曲张性外痔，静脉曲张性混合痔的外痔部分。"},{"t":"p","x":"(2)操作方法 ①对静脉曲张性外痔，麻醉满意后，常规消毒铺巾。"},{"t":"p","x":"指法扩肛，使肛门松弛，仔细检查外痔的大小、范围和数量(图11-30)。"},{"t":"p","x":"②设计切口部位，沿静脉曲张的外缘做V形或线形切口，在手术器械的牵拉下暴露括约肌内间隙(图11-31)，用剪刀或电刀潜行剥离括约肌内间隙的外痔静脉丛，并予以全部剔除(图11-32)。"},{"t":"p","x":"③电凝、钳夹或结扎止血。"},{"t":"p","x":"修剪切口皮肤，用丝线间断缝合切口(图11-33)，消毒后无菌敷料加压包扎。"},{"t":"img","src":"img/fig/f1131.jpg","alt":"图11-31沿静脉曲张的痔外缘做V形或线形切口"},{"t":"img","src":"img/fig/f1130.jpg","alt":"图11-30扩肛并显露痔核"},{"t":"img","src":"img/fig/f1133.jpg","alt":"图11-33在括约肌内间隙剥离痔静脉丛"},{"t":"img","src":"img/fig/f1132.jpg","alt":"图11-32在括约肌内间隙暴露痔外静脉丛"}],"entries":["e0732","e0733","e0734","e0735","e0736"]}]},{"id":"d1101c","kind":"sub","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"混合痔","displayName":"痔·混合痔","parentId":"d1101","printedPage":220,"pdfPage":235,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"混合痔是指内、外痔静脉丛曲张，相互沟通吻合，使内痔部分和外痔部分形成一个整体者。"},{"t":"p","x":"临床表现具有内痔、外痔的双重症状。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"多因Ⅱ、Ⅲ期内痔反复脱出，或妊娠分娩，负重努挣，腹压增加，致使筋脉横解，瘀结不散而成。"}],"entries":["e0737","e0738"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断大便时滴血或射血，量或多或少，色鲜，便时常有肿物脱出，能自行回纳或须用手法复位，若合并染毒则可发生嵌顿肿痛。检查可见多发生于膀胱截石位3、7、11点位处，以11点处最多见，内、外痔相连，无明显分界。"}],"entries":["e0739"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"p","x":"参见内痔的“辨证论治”"},{"t":"p","x":"2.外治疗法参见内痔、外痔的“外治法”。3.手术疗法可采用混合痔外剥内扎术，见图11-34。"},{"t":"h","lv":3,"x":"(1)适应证混合痔。"},{"t":"p","x":"(2)操作方法取侧卧位或截石位，局部常规消毒，局部浸润麻醉或腰俞穴麻醉。"},{"t":"p","x":"将混合痔充分暴露，在其外痔部分做“V”字形皮肤切口，在括约肌内侧间隙，用剪刀锐性剥离痔外静脉丛至齿状线处。"},{"t":"p","x":"然后用弯形血管钳夹住被剥离的静脉丛和内痔基底部，在内痔基底正中用圆针粗丝线贯穿做“8”字形结扎，距结扎线1cm处剪去“V”字形皮肤切口内的皮肤及静脉丛，使其在肛门部呈一放射状伤口。"},{"t":"p","x":"同法处理其他痔核后，创面消毒后外用纱布敷盖，胶布固定。术后当天限制大便，每次便后用苦参汤或五倍子汤或温开水坐浴，纳入痔疮栓1枚，外敷黄连膏，直至痊愈。"},{"t":"p","x":"若混合痔的外痔静脉丛不很明显，可在外痔中间做一放射状切口，然后用剪刀锐性剥离静脉丛，修剪两侧皮瓣，使之呈一小“V”字形切口。"},{"t":"p","x":"外痔剥离时要选好切口，照顾外痔部分的整体关系，手术中注意保留适当的黏膜和皮肤，以防术后肛门直肠狭窄。术后处理参见内痔的“贯穿结扎法”。"},{"t":"img","src":"img/fig/f1134.jpg","alt":"图11-34混合痔外剥内扎术"},{"t":"p","x":"4.其他疗法参见内痔、外痔的“其他疗法”。"}],"entries":["e0740"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.保持大便通畅，养成每天定时排便的习惯，蹲厕时间不宜过长。2.避免久坐久立，负重远行。"},{"t":"p","x":"3.保持肛门局部清洁卫生，防止便秘或腹泻的发生。4.饮食宜清淡，多喝开水，多食蔬菜水果，忌食辛辣刺激性食物。"},{"t":"p","x":"5.进行适当的活动和肛门功能锻炼。有痔核脱出时应及时复位，可用热敷、卧床休息、外涂润滑剂、提肛等方法。"},{"t":"p","x":"便血量较多时应停止排便，可用棉球填塞压迫止血，出血不止或复位困难者应及时到医院诊治。"}],"entries":["e0741"]}]},{"id":"d1102","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"肛痈","displayName":"肛痈","parentId":"","printedPage":221,"pdfPage":236,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肛痈是肛管直肠周围间隙发生急、慢性感染而形成的脓肿。在古代医学文献中，肛痈因发病部位的不同而有不同的称谓，如“脏毒”“悬痈”“坐马痈”“跨马痈”等。"},{"t":"p","x":"其临床特点是多发病急骤，疼痛剧烈，伴寒战高热，破溃后大多形成肛漏。本病可发生于任何年龄、但以20～40岁的青壮年居多，婴幼儿也时有发生，男性多于女性。"},{"t":"p","x":"本病相当于西医学的肛门直肠周围脓肿。由于其发生的部位不同而有不同的名称，如肛周皮下脓肿、坐骨直肠间隙脓肿、括约肌间隙脓肿(又名黏膜下脓肿)、肛提肌上间隙脓肿等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因过食肥甘、辛辣之品，湿热内生，下注大肠，蕴阻肛门；或因肛周破损染毒，致经络阻塞、气血凝滞，壅遏不行，化热腐肉而成痈；"},{"t":"p","x":"亦有因肺脾亏虚，湿浊结聚，或阴虚内热，毒邪乘虚下注、结于肛周，郁久化热，肉腐成脓所致。1.热毒蕴结肛门周围突然肿痛，持续加剧，肛周红肿，触痛明显，质硬，皮肤焮热；"},{"t":"p","x":"伴有恶寒发热，便秘溲赤；舌红，苔薄黄，脉数。"},{"t":"p","x":"2.火毒炽盛肛门周围肿痛剧烈，持续数日，痛如鸡啄，难以入寐；肛周红肿，按之有波动感或穿刺有脓；"},{"t":"p","x":"伴有恶寒发热，口干便秘，小便困难；舌红，苔黄，脉弦滑。"},{"t":"p","x":"3.阴虚毒恋肛周肿痛、皮色暗红，成脓时间长，溃后脓出稀薄，疮口难敛；伴有午后潮热，心烦口干，盗汗；"},{"t":"p","x":"舌红，少苔，脉细数。西医学认为，本病多系肛隐窝感染后，炎症沿肛门腺导管延至肛门腺体，继而向肛门直肠周围间隙蔓延所致。"},{"t":"p","x":"其致病菌多为大肠杆菌，其次为金黄色葡萄球菌和链球菌，偶有厌氧菌和结核杆菌。"}],"entries":["e0742","e0743"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现发病男性多于女性，尤以青壮年为多，主要表现为肛门周围皮肤发红、疼痛、肿胀、结块，伴有不同程度的全身症状。"},{"t":"p","x":"由于脓肿的部位和深浅不同，症状也有差异。如肛提肌以上的间隙脓肿位置深隐，全身症状重而局部症状轻；"},{"t":"p","x":"肛提肌以下的间隙脓肿部位浅，局部红、肿、热、痛明显而全身症状较轻或无。"},{"t":"h","lv":3,"x":"(2)专科检查肛门指诊可触及压痛、肿块、隆起或波动感。"},{"t":"p","x":"(3)分类根据脓肿发生的部位及直肠周围间隙的不同，肛痈可分为以下4种(图11-35)：肛周皮下脓肿：发生于肛门周围的皮下组织内，为最常见的一种脓肿(图11-36)。"},{"t":"p","x":"脓肿一般不大，局部红、肿、热、痛明显，脓成按之有波动感，全身症状轻微。肿块反复出现，可自行缓解或破溃。"},{"t":"p","x":"肛门镜检查可发现脓液从肛隐窝底部或慢性肛裂处排出。若患者疼痛，一般不行肛门镜检查。"},{"t":"img","src":"img/fig/f1136.jpg","alt":"图11-36肛周皮下脓肿"},{"t":"img","src":"img/fig/f1135.jpg","alt":"图11-35肛周脓肿的分类"},{"t":"p","x":"坐骨直肠间隙脓肿：是肛管直肠周围脓肿中常见的一种。发生于肛门与坐骨结节之间(图11-"},{"t":"p","x":"37)。"},{"t":"p","x":"初起肛门部不适或微痛、逐渐出现发热、畏寒、头痛、食欲不振等症状，继而局部症状加剧。肛门有灼痛或跳痛感、排便、咳嗽、行走时加剧、甚则坐卧不安。"},{"t":"p","x":"视诊可发现患侧皮肤红肿，范围较大、双侧明显不对称。括约肌间隙脓肿：由Eisenhammcr在1966年首次描述，发生于肛门括约肌间隙，占肛管直肠周围脓肿的2%～5%、临床较为少见(图11-38)。"},{"t":"p","x":"其症状与肛门后深部脓肿相似，但直肠坠胀感更为明显、可伴骶尾部钝痛并放射至下肢，尾骨与肛门间常有明显深压痛。触诊常可触及黏膜下触痛性包块。"},{"t":"p","x":"约25%的患者合并肛裂、若在肛窦隐窝处发现脓液，即可确诊。"},{"t":"img","src":"img/fig/f1138.jpg","alt":"图11-38括约肌间隙脓肿"},{"t":"img","src":"img/fig/f1137.jpg","alt":"图11-37坐骨直肠间隙脓肿"},{"t":"img","src":"img/fig/f1139.jpg","alt":"图11-39肛提肌上间隙脓肿"},{"t":"p","x":"肛提肌上间隙脓肿：该脓肿发生于肛提肌以上，包括直肠后间隙脓肿和高位肌间脓肿，临床较为少见，且临床表现比前述类型的脓肿更加隐匿(图11-39)。"},{"t":"p","x":"可能表现为臀部或腰部疼痛，体格检查没有任何脓肿相关的阳性发现，需进行进一步的CT或MRI检查。本病5～7天成脓。"},{"t":"p","x":"若成脓期逾月，溃后脓出色灰稀薄，不臭或微臭，无发热或低热，应考虑结核性脓肿。"},{"t":"p","x":"(4)辅助检查 ①血常规检查：根据血常规检查结果，可判断感染程度。"},{"t":"p","x":"白细胞总数及中性粒细胞比例可有不同程度的增高。"},{"t":"p","x":"②超声检查：B超检查对肛门直肠周围脓肿的早期诊断有重要意义，操作简单、使用方便、无痛苦，可以准确地判断脓肿的位置及大小、分布，对微小脓肿也可发现。"},{"t":"p","x":"可以明确肛门直肠周围脓肿的大小范围、位置及其与肛门括约肌和肛提肌的关系。对难以确诊的高位脓肿或复合脓肿有较高诊断价值。"},{"t":"p","x":"③脓腔穿刺：对于部位较深，难以判断是否成脓者，可在局麻下用粗针(16号)于脓肿中心处或压痛最明显处刺人抽吸。"},{"t":"p","x":"如有脓液抽出，即可确诊定位。如未抽到脓液，则有两种可能，即尚未成脓或部位不准确。"},{"t":"p","x":"部位不准确可再行穿刺。"},{"t":"p","x":"④脓液细菌培养及药敏试验：可以了解病原菌的种类、性质、药敏，并为临床诊断、治疗及判断预后等提供依据。"},{"t":"p","x":"常以革兰阴性菌为主，大多数为需氧菌和厌氧菌混合。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-5)"},{"t":"table","img":"img/tab/t1105.jpg","cap":"表11-5肛痈与肛周毛囊炎、疖肿、骶前畸胎瘤、骶骼关节结核性脓肿、肛周坏死性筋膜炎的鉴别"}],"entries":["e0744"]},{"title":"治疗","blocks":[{"t":"p","x":"肛痈的治疗在于脓成则应尽早切开引流，这是控制感染的关键。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110201","name":"热毒蕴结证","clinic":"肛门周围突然肿痛，持续加剧，肛周红肿，触痛明显，质硬，皮肤焮热；伴有恶寒发热，便秘溲赤；舌红，苔薄黄，脉数","treat":"清热解毒","formula":"仙方活命饮、黄连解毒汤加减。若有湿热之象，如舌苔黄腻、脉滑数等，可合用萆薢渗湿汤","formulaNames":["仙方活命饮","黄连解毒汤"]},{"t":"syn","sid":"s110202","name":"火毒炽盛证","clinic":"肛周肿痛剧烈，持续数日，痛如鸡啄，难以入寐；肛周红肿，按之有波动感或穿刺有脓；伴恶寒发热，口干便秘，小便困难；舌红，苔黄，脉弦滑","treat":"清热解毒透脓","formula":"透脓散加减","formulaNames":["透脓散"]},{"t":"syn","sid":"s110203","name":"阴虚毒恋证","clinic":"肛周肿痛，皮色暗红，成脓时间长，溃后脓出稀薄，疮口难敛；伴有午后潮热，心烦口干，盗汗；舌红，苔少，脉细数","treat":"养阴清热，祛湿解毒","formula":"青蒿鳖甲汤合三妙丸加减。肺虚者加沙参、麦冬；脾虚者加白术、山药、扁豆；肾虚者加龟甲、玄参，生地黄改熟地黄","formulaNames":["青蒿鳖甲汤","三妙丸"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起以消法为主，可外敷清热解毒、软坚散结类药物，以促使炎症局限或消散。"},{"t":"p","x":"实证用金黄膏、黄连膏外敷、位置深隐者可用金黄散调糊浙肠；虚证用冲和膏或阳和解凝膏外敷。"},{"t":"p","x":"(2)成脓宜早期切开引流、并根据脓肿部位深浅和病情缓急选择手术方法。"},{"t":"p","x":"(3)溃后溃脓后、应以提脓祛腐、生肌收口为主。"},{"t":"p","x":"开始需化腐提脓，用九一丹纱条引流；待脓尽腐脱、疮面红活、则用生肌散纱条促进愈合。日久成漏者按肛漏处理。"},{"t":"p","x":"3.手术疗法脓成则应尽早切开引流、引流要通畅，不留死腔。对发生在肛提肌以下的低位脓肿、如已找到可靠的内口。应争取一次性手术处理，以防形成肛瘘。"},{"t":"p","x":"对发生在肛提肌以上的脓肿，如尚未找到可靠的内口、宜先切开排脓、待形成肛瘘后再行二次手术。"},{"t":"p","x":"(1)手术方法"},{"t":"p","x":"1)脓肿一次切开法"},{"t":"p","x":"适应证：浅部脓肿。操作方法：患者取截石位。"},{"t":"p","x":"在麻醉下，常规消毒铺巾，通过指诊、确定脓肿的范围和内口的位置；先在脓肿顶部，考虑引流通畅的部位，沿皮肤走行做放射状切口，切开皮肤和皮下组织，敞开脓腔、放尽脓液。"},{"t":"p","x":"将一手食指插入肛内作引导，另一手用细探针从切口经脓腔由内口探出，注意用力要轻，以免造成假道。若内口不明显，可将深大、充血的肛窦，或挤压脓腔时有冲击感的脓腔最薄弱处作为内口处理。"},{"t":"p","x":"在不损伤肛管直肠环的原则下，沿探针做放射状切开，切开脓腔与内口间的组织、并将切口略向肛窦上方延长，使其成为平坦创口，搔刮内口，去除感染的肛窦及肛腺组织。若切口的黏膜出血、可用细丝线结扎止血或电止血。"},{"t":"p","x":"伤口开放引流，有时可切除部分皮肤，使引流通畅。若黏膜下脓肿、用肛门镜伸入直肠，显露脓肿，用电刀或手术刀做纵切口，切开脓肿排出脓液。"},{"t":"p","x":"术毕、伤口内放置纱条，外用塔纱加压包扎。术后酌情使用抗生素，进食流质饮食两天，控制大便48小时，便后用苦参汤坐浴。"},{"t":"p","x":"每日便后用纱条换药，也可酌情使用化腐提脓药和生肌敛口药，直至痊愈。"},{"t":"p","x":"2)一次切开挂线法"},{"t":"p","x":"适应证：高位脓肿，如坐骨直肠窝脓肿、肛提肌上脓肿及马蹄形脓肿等。操作方法：患者取截石位。"},{"t":"p","x":"在麻醉下，检查确定脓肿的范围和内口位置：在切开脓腔前挤压脓腔，用肛门镜扩开肛门，观察是否有肛窦(内口)溢出脓液，若有，即可确定为内口位置。"},{"t":"p","x":"也可将探针做成钩状，从与脓腔同一方位的齿状线处寻找深大、充血的可疑肛窦，若能钩入，可初步确定内口。如内口和脓肿在同一方位，可沿皮肤走行做放射状切口。"},{"t":"p","x":"先在肛缘外与脓肿相应部位，选择引流通畅的位置，做一放射状小切口，用止血钳分开脓腔，放出脓液。然后用一手食指伸入肛内引导，一手持探针从小切口探人，寻找内口。"},{"t":"p","x":"注意不要过于用力，以免造成假道。将探针从内口或可疑肛窦处探出，由内口与脓肿的小切口之间，沿皮肤走行做放射状切口，切开皮肤和皮下组织，敞开内口和脓腔，显露肛管直肠环。"},{"t":"p","x":"然后将丝线一端结扎在探针外端近球部处，另一端拴在橡皮筋上，再由内口拖出，用止血钳将橡皮筋勒紧所通过的肛管直肠环部，以达到切割引流的目的。再用丝线于止血钳下将橡皮筋结扎固定，防止滑脱。"},{"t":"p","x":"肛管部位的切口和脓腔内，放置纱条填充引流。"},{"t":"p","x":"3)分次手术"},{"t":"p","x":"适应证：适用于体质虚弱或不愿住院治疗的深部脓肿患者。操作方法：切口应在压痛或波动感明显部位，尽可能靠近肛门，切口呈弧状或放射状，须有足够长度，用纱布条引流，以保持引流通畅。"},{"t":"p","x":"待形成肛漏后，再按肛漏处理。病变炎症局限和全身情况良好者，如发现内口，可采用切开挂线法，以免二次手术。"},{"t":"p","x":"(2)术后处理酌情应用清热解毒、托里排脓的中药或抗生素及缓泻剂。"},{"t":"p","x":"术后每次便后用苦参汤坐浴，换药。挂线一般约10天自行脱落，10天后未脱落者可酌情紧线或剪除，此时创面已修复浅平，再经换药后可愈合。"},{"t":"p","x":"各种方式的手术在术后须注意有无高热、寒战等，如有则应及时处理。"},{"t":"p","x":"(3)术中注意事项 ①定位要准确：一般在脓肿切开引流前应先穿刺，待抽出脓液后再行切开引流。"},{"t":"p","x":"②切口：原则上切口应紧靠肛缘。以缩短潜在瘘管的长度并确保引流通畅。"},{"t":"p","x":"浅部脓肿宜行放射状切口。深部脓肿若行弧形切口、切口应在括约肌外侧、避免损伤括约肌；"},{"t":"p","x":"若行放射状多切口，除与内口对应的切口外、其余切口近端应在括约肌外侧。"},{"t":"p","x":"③引流要彻底：切开脓肿后要用手指去探查脓腔，分开脓腔内的纤维间隔、以利于引流。"},{"t":"p","x":"④预防肛漏形成：术中如能找到原发性感染的肛隐窝，应尽可能切开或切除，以防止肛漏形成。"},{"t":"p","x":"⑤一旦确诊、应及时切开排脓，以免脓肿向深部和周围组织蔓延；"},{"t":"p","x":"不应等待硬结变软或局部红肿，不可拘泥于有无波动感而延迟切开排脓。"},{"t":"p","x":"⑥对高位复杂性脓肿、女性前侧脓肿、若有瘘管形成，以切开引流或挂线引流为主，不推荐做一期手术。"},{"t":"p","x":"此外，术中如确实找不到内口，不应勉强行一次性根治术，可仅做切开引流。"}]}],"entries":["e0745","e0746","e0747","e0748","e0749"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.少食辛辣刺激食物，保持大便通畅、防止便秘和腹泻，避免损伤肛门，注意肛门清洁。2.积极防治肛门病变，如肛隐窝炎、肛腺炎、肛乳头炎、直肠炎、痔等。"},{"t":"p","x":"3.患病后应及早治疗、防止炎症范围扩大。"}],"entries":["e0750"]}]},{"id":"d1103","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"肛漏","displayName":"肛漏","parentId":"","printedPage":225,"pdfPage":240,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肛漏是指直肠或肛管与肛门周围皮肤相通所形成的异常通道，也称为肛管直肠瘘，简称肛瘘。"},{"t":"p","x":"古代文献又称“痔漏”“漏疮”“穿肠漏”等。肛漏一般由原发性内口、漏管和继发性外口三部分组成，也有仅具内口或外口者。"},{"t":"p","x":"内口为原发性，绝大多数在肛管齿状线处的肛窦内；外口是继发的，在肛门周围皮肤上，常不止一个。"},{"t":"p","x":"肛漏多是肛痈的后遗症。临床上分为特异性或非特异性两类。"},{"t":"p","x":"其临床特点是以局部反复流脓、疼痛、瘙痒为主要症状，并可触及或探及瘘管通向肛门或直肠。发病率仅次于痔，在我国占肛肠病患者总数的1.67%～3.60%，发病高峰年龄在20～40岁，婴幼儿发病亦不少见。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"肛痈溃后，余毒未尽，留连肉腠，疮口不合，日久成漏；或因肺脾两虚，气血不足，以及虚劳久嗽，肺肾阴虚，湿热乘虚流注肛门，久则穿肠透穴为漏。"},{"t":"p","x":"1.湿热下注肛痈溃后，湿热未清，瘀久不散，热盛肉腐成脓，则肛门流脓，脓质稠厚，肛门灼热；病邪留连肉腠而为漏患。"},{"t":"p","x":"2.正虚邪恋正虚日久，不能托毒外出，湿热留恋，久不收口，形成漏患。3.阴液亏虚肺脾肾三阴亏损，邪乘下位，郁久肉腐化脓，溃破成漏。"},{"t":"p","x":"西医学认为，肛瘘和肛门直肠周围脓肿为肛周间隙化脓性感染的两个病理阶段，急性期为肛门直肠周围脓肿，慢性期为肛瘘。肛瘘多为一般化脓性感染所致，少数为特异性。"}],"entries":["e0751","e0752"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病不论性别、年龄及体质的强弱均可发生，但以成年人为多见。"},{"t":"p","x":"通常有肛痈反复发作史，并有自行溃破或曾切开引流的病史。流脓：流脓不止、久不收口为本病的特征。"},{"t":"p","x":"一般新形成的肛漏流脓较多，有粪臭味，色黄而稠；久之则脓水逐渐减少，时有时无。"},{"t":"p","x":"若过于疲劳或嗜食辛辣刺激性食物时，则脓水增多；若内、外口及漏管较粗大时，可有少量粪便和气体从外口流出；"},{"t":"p","x":"若突然感觉肛门部肿胀疼痛者，常常表示有急性感染或有新的支管形成。疼痛：当漏管通畅时，一般不觉疼痛，而仅有局部坠胀不适感。"},{"t":"p","x":"若外口自行闭合，脓液积聚，可出现局部皮肤发红、肿胀、疼痛，严重的或有寒热；若溃破后脓水流出，症状可迅速减轻或消失。"},{"t":"p","x":"瘙痒：由于脓液不断刺激肛门周围皮肤，可引起瘙痒、有时可伴发肛门湿疮。"},{"t":"h","lv":3,"x":"(2)专科检查"},{"t":"p","x":"肛门视诊：可见外口。外口凸起较小者，多为化脓性：外口较大、凹陷。周围皮肤暗紫，皮下有穿凿性者，应考虑复杂性或结核性肛漏。"},{"t":"p","x":"低位肛漏可在肛周皮下触及条索状物通向肛内，用力按压常有脓液从外口溢出：高位或结核性者一般不易触及。直肠指检：在肛管的后侧、齿状线附近摸到中心凹陷的小硬结，有轻微压痛。往往是肛漏的原发性内口。"},{"t":"h","lv":3,"x":"(3)分类"},{"t":"p","x":"1)1975年全国统一分类标准1975年全国首届肛肠学术会议制定了肛漏的统一分类标准，以外括约肌深部划线为标志、漏管经过此线以上者为高位，在此线以下者为低位。"},{"t":"p","x":"其分类如下：低位单纯性肛漏：只有1个漏管，并通过外括约肌深层以下，内口在肛窦附近。"},{"t":"p","x":"低位复杂性肛漏：漏管在外括约肌深层以下，有2个以上外口，或2条以上管道，内口在肛窦部位。高位单纯性肛漏：仅有1条管道，漏管穿过外括约肌深层以上，内口位于肛窦部位。"},{"t":"p","x":"高位复杂性肛漏：有2个以上外口及管道有分支窦道，其主管道通过外括约肌深层以上，有1个或2个以上内口者。"},{"t":"p","x":"2)Parks分类现在临床较为常用的是Parks分类(图11-40)。"},{"t":"p","x":"英国学者于1976年提出Parks分类法、对肛瘘的临床诊治具有较好的指导意义。该分类的依据是瘘管走行与肛门括约肌的解剖关系，据此将肛瘘分为以下4种类型。"},{"t":"p","x":"括约肌间肛瘘：多为低位肛瘘，约占45%。瘘管只穿过肛门内括约肌，位置较低。"},{"t":"p","x":"内口多位于齿状线部位，外口常只有1个，距离肛门3～5cm。主瘘管有时会形成一些小支管，这些支管位于肛门括约肌环和纵行肌之间，上端可能是闭合的盲端，也可能穿过括约肌和直肠黏膜，形成较高位置的括约肌间瘘。"},{"t":"p","x":"经括约肌肛瘘：可以为低位或高位肛瘘，约占30%，大多是坐骨直肠间隙脓肿引流后形成。瘘管穿过肛门内、外括约肌的浅部和深部之间，内口多在齿状线处，外口常不止1个，且支管互相沟通。"},{"t":"p","x":"外口距肛缘较远，约为5cm。括约肌上肛瘘：为高位肛瘘，少见，约占20%。"},{"t":"p","x":"瘘管向上穿过肛提肌，达肛管直肠环以上，然后向下经过坐骨直肠窝穿透皮肤。内口多在齿状线处，外口距肛门较远。"},{"t":"p","x":"括约肌外肛瘘：较少见，约占5%。瘘管穿过肛提肌直接与直肠相通。"},{"t":"p","x":"该类型肛瘘多为非腺源性感染所致，常继发于克罗恩病、肠结核、溃疡性结肠炎、直肠癌或外伤。因此，在治疗时需要注意其原发病灶。"},{"t":"h","lv":3,"x":"(4)肛漏的发展规律"},{"t":"p","x":"Goodsall规律：将肛门两侧的坐骨结节画一条横线，当漏管外口在横线之前距离肛缘4cm以内，内口在齿状线处与外口位置相对，其管道多为直行；"},{"t":"p","x":"如外口在距离肛缘4cm以外(图11-41)，或外口在横线之后，内口多在后正中齿状线处，其漏管多为弯曲或马蹄形。"},{"t":"img","src":"img/fig/f1140.jpg","alt":"图11-40肛瘘Park分类及其亚型"},{"t":"img","src":"img/fig/f1141.jpg","alt":"图11-41根据Goodsall规律的典型瘘管"},{"t":"p","x":"(5)辅助检查 ①碘化油造影检查：通过X线碘化油管道造影检查，可显示瘘管走行、深浅、有无分支、与直肠是否相通及与直肠周围脏器的关系等。"},{"t":"p","x":"②亚甲蓝染色检查：通过从外口注入亚甲蓝稀释液，一方面可观察到直肠腔内有无亚甲蓝染色、确定是否有内口及内口的位置；"},{"t":"p","x":"另一方面根据注入的液体量可观察管道的长度及管腔的大小。"},{"t":"p","x":"③直肠腔内超声检查：可以发现条索状管道及内口的位置，为手术提供依据。"},{"t":"p","x":"④CT瘘管成像：可了解肛周解剖结构，结合成像可立体显示瘘管的轨迹、分支和内口等；"},{"t":"p","x":"多层螺旋CT扫描联合三维重建技术可进一步提高诊断的准确性。"},{"t":"p","x":"⑤MRI：对软组织分辨率高、能较准确地显示肛门内外括约肌、肛提肌和耻骨直肠肌的解剖结构，在显示残余脓腔、瘘管及其与肛提肌、内外括约肌、肛门周围组织的解剖关系等方面具有明显优势，可协助进行肛瘘的诊断分类，对指导手术具有较高的价值。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-6)"},{"t":"table","img":"img/tab/t1106.jpg","cap":"表11-6肛漏与肛门部化脓性汗腺炎、骶前畸胎瘤溃破、克罗恩病肛瘘的鉴别"}],"entries":["e0753"]},{"title":"治疗","blocks":[{"t":"p","x":"一般以手术治疗为主；内治法多用于手术前后，以增强体质、减轻症状、控制炎症发展，"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110301","name":"湿热下注证","clinic":"肛周经常流脓液，脓质稠厚，肛门胀痛，局部灼热；肛周有溃口，按之有索状物通向肛内；舌红，苔黄腻，脉弦或滑","treat":"清热利湿","formula":"二妙丸合萆薢渗湿汤加减","formulaNames":["二妙丸","萆薢渗湿汤"]},{"t":"syn","sid":"s110302","name":"正虚邪恋证","clinic":"肛周流脓液，质地稀薄，肛门隐隐作痛、外口皮色暗淡，漏口时溃时愈；肛周有溃口，按之质较硬，或有脓液从溃口流出，且多有索状物通向肛内；伴神疲乏力；舌淡，苔薄，脉","treat":"托里透毒。9·","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"syn","sid":"s110303","name":"阴液亏损证","clinic":"肛周溃口，外口凹陷，漏管潜行，局部常无硬索状物可扪及。脓出稀薄；可伴有潮热盗汗，心烦口干；舌红、少苔，脉细数","treat":"养阴清热","formula":"青蒿鳖甲汤加减。肺虚者加沙参、麦冬，脾虚者加白术、山药","formulaNames":["青蒿鳖甲汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)肛漏脓水淋漓、肛周潮湿者、可用苦参汤煎水，坐浴熏洗。"},{"t":"p","x":"(2)肛漏脓出不畅、发作频繁者，可用药线引流法，以药捻蘸九一丹等药自外口插入漏管，提脓拔毒引流。"}]},{"t":"sub","title":"3.手术疗法肛瘘确诊后均需要手术治疗，手术方式可分","blocks":[{"t":"p","x":"为损伤括约肌的手术和保留括约肌功能的手术。前者包括挂线疗法、切开疗法和肛瘘切除术等；"},{"t":"p","x":"后者包括括约肌间瘘管结扎术、直肠黏膜肌瓣推进修补术和经吻合器肛瘘内口闭合术(图11-42)等。手术成败的关键在于正确找到内口，并准确处理内口和内口上方的漏管；"},{"t":"p","x":"否则创口就不能愈合，即使暂时愈合，日久又会复发。"},{"t":"p","x":"(1)挂线疗法此法早在明代就已采用。"},{"t":"p","x":"《古今医统大全·复斋治论》曰：“药线日下，肠肌随长，僻处既补，水逐线流，未穿疮"},{"t":"img","src":"img/fig/f1142.jpg","alt":"图11-42经吻合器肛瘘内口闭合术"},{"t":"p","x":"孔，鹅管内消。”简要叙述了本疗法具有简便、经济、肛门功能影响小、瘢痕小、引流通畅等优点。"},{"t":"p","x":"适应证：适用于高位肛漏、婴幼儿肛漏，亦作为复杂性肛漏切开疗法或切除疗法的辅助方法。禁忌证：肛门周围有皮肤病者，漏管仍有酿脓现象存在者，有严重的肺结核、梅毒等或极度虚弱者，有癌变者。"},{"t":"p","x":"操作方法：椎管内麻醉或局部浸润麻醉，取俯卧位或截石位。常规消毒，先在球头探针尾端缚扎一橡皮筋，再将探针从漏管外口轻轻地向内探入，将食指伸入肛管协助探针，在肛管齿状线附近找到内口，并由内口将探针探出；"},{"t":"p","x":"若是高位肛漏，则寻找到漏管顶端，探针从顶端向肠腔做人工漏口探出，之后将探针弯曲，从肛门口拉出，使橡皮筋经过漏管外口进入漏管。"},{"t":"p","x":"由内口拉出后，提起橡皮筋，切开漏管内、外口之间的皮肤及皮下组织，拉紧橡皮筋，紧贴皮下切口用止血钳夹住，在止血钳下方用粗丝线收紧橡皮筋并双重结扎之，然后在结扎线外1.5cm处剪去多余的橡皮筋。"},{"t":"p","x":"松开止血钳，用生理盐水纱布条填塞伤口压迫止血，外垫纱布，宽胶布固定(图11-43)。若以药线挂线，则将药线收紧后打一二扣活结，以备后续紧线；"},{"t":"p","x":"也可将药线的一端穿入另一段药线内，由肛门牵出，使线在漏管周围成为双股线，然后收紧，打一活结，每隔1～2天紧线1次，直至挂线脱落。"},{"t":"p","x":"挂线疗法的作用机制：通过药线或橡皮筋的异物刺激，诱发局部炎症反应和纤维化，使括约肌断端与周围组织粘连固定；同时慢性勒割作用可产生压迫性缺血坏死，逐渐分离括约肌并伴随纤维化修复，减少功能障碍。"},{"t":"p","x":"挂线还具备引流作用，固定于病灶深部可减轻感染；并有标志作用，明确外口与内口的关系，为瘘管切开提供准确定位。"},{"t":"p","x":"其优点是方法简便、经济、安全，对括约肌功能影响小，不易引起肛门失禁，减少组织缺损和畸形、瘢痕小，复发率低。但不足之处在于橡皮筋结扎疼痛明显且持续时间长，药线虽痛感较轻但常需紧线或切除残余组织，增加不适；"},{"t":"p","x":"同时患者有异物感，分泌物多，清洁困难，创面愈合时间长，且挂线处可遗留凹陷。"}]},{"t":"sub","title":"4.提起橡皮筋","blocks":[{"t":"img","src":"img/fig/f1143.jpg","alt":"图11-43橡皮筋挂线疗法"},{"t":"p","x":"(2)切开疗法"},{"t":"p","x":"适应证：低位单纯性肛漏和低位复杂性肛漏；高位肛漏在切开时，必须配合挂线疗法，以免造成肛门失禁。"},{"t":"p","x":"禁忌证：同挂线疗法。操作方法：椎管内麻醉或局部浸润麻醉，取俯卧位或截石位。"},{"t":"p","x":"常规消毒后，先在肛门内塞入一块盐水纱布，再用钝头针头注射器由漏管外口注入1%亚甲蓝，如纱布染有颜色，则可有助于寻找内口，也便于在手术时辨认漏管走向。"},{"t":"p","x":"将有槽探针从漏管外口轻轻插入，然后沿探针走行切开皮肤和皮下组织及漏管外壁，使漏管部分敞开，再将有槽探针插入漏管残余部分。同样方法切开探针的表面组织。"},{"t":"p","x":"直到整个漏管完全切开为止。漏管全部敞开后用刮匙将漏管壁上染蓝色的坏死组织和肉芽组织刮除。"},{"t":"p","x":"修剪创口两侧的皮肤和皮下组织，形成一口宽底小的创面，使引流通畅。仔细止血，创面填塞生理盐水纱布条，外垫纱布，宽胶布压迫固定。"},{"t":"p","x":"(3)括约肌间瘘管结扎术(ligation of thc intcrsphincteric fistula tract, LIFT)适应证：适用于低位/高位经括约肌肛瘘。"},{"t":"p","x":"操作方法：在腰硬联合或局麻下，取截石位或俯卧位，常规消毒铺巾。必要时自外口注入稀释亚甲蓝或置探针以示踪瘘管。"},{"t":"p","x":"在括约肌间沟内口投影处做3～4cm弧形切口，锐钝分离进入括约肌间隙，环形分离并完整游离主瘘管，以牵引线标记。于近、远端分别用2-0/3-0可吸收线双重结扎后切断瘘管，近端残端加强缝合关闭内口(图11-44)。"},{"t":"p","x":"远端残段搔刮清理，必要时扩大外口引流。彻底止血。分层缝合切口，置纱条引流并外覆无菌败料加压包扎。"},{"t":"p","x":"操作中注意沿肌纤维分离，以保护括约肌；既往挂线者可于炎症控制后同期取出并完成LIFT。"},{"t":"img","src":"img/fig/f1144.jpg","alt":"图11-44括约肌间瘘管结扎术"},{"t":"p","x":"(4)直肠黏膜肌瓣推进修补术适应证：复杂性肛瘘。"},{"t":"p","x":"操作方法：在腰硬联合或全身麻醉下，取截石位，常规肛门及直肠内消毒。沿齿状线以上做弧形切口，切取一片含黏膜及部分黏膜下组织的矩形或梯形推移瓣，宽度略大于瘘口。"},{"t":"p","x":"游离推移瓣并保持基底血供，将瘘管内口周围瘢痕组织彻底切除或搔刮后关闭内口。将推移瓣下移覆盖修补区，用可吸收线间断缝合固定。"},{"t":"p","x":"术中注意保护括约肌结构，保持瓣体血供良好，必要时置引流物并外覆无菌敷料加压包扎(图11-45)。"},{"t":"img","src":"img/fig/f1145.jpg","alt":"图11-45直肠推移辫切口-游离-缝合示意图"},{"t":"p","x":"(5)手术时注意事项 ①探针由外口探入时不能使用暴力，以免造成假道。"},{"t":"p","x":"②如漏管在肛管直肠环下方通过，可以一次全部切开漏管。"},{"t":"p","x":"如漏管通过肛管直肠环的上方，必须加用挂线疗法。"},{"t":"p","x":"③漏管若在外括约肌深、浅两层之间通过，该处肌肉未形成纤维化时，不能同时切断两处外括约肌。"},{"t":"p","x":"④高位肛漏通过肛尾韧带时可以做纵行切开，不能横行切断肛尾韧带，以免造成肛门向前移位。"},{"t":"p","x":"(6)术后处理 ①术后须保持大便通畅，必要时可给予润下剂。"},{"t":"p","x":"②术后疼痛者可给予止痛剂或采用耳针疗法。"},{"t":"p","x":"③每天便后用苦参汤坐浴、换药。"},{"t":"p","x":"④一般挂线后橡皮筋在7天左右可以脱落，若3周不脱落，可以剪开；"},{"t":"p","x":"若结扎橡皮筋变松，需要再紧线1～2次，直至脱落。"},{"t":"p","x":"⑤伤口必须从基底部开始生长，防止表面过早粘连封口，形成假愈合。"},{"t":"p","x":"⑥管道切开或挂开后，改用生肌散纱条或生肌玉红膏纱条换药至收口。"},{"t":"p","x":"⑦肛漏在切开或挂开后可有少量脓水流出，四周肿胀逐渐消散。"},{"t":"p","x":"如仍有较多脓水，应检查有无支管或残留的管道。"},{"t":"p","x":"⑧如有局部感染，应及时予以治疗。"}]}],"entries":["e0754","e0755","e0756","e0757","e0758","e0759","e0760"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.经常保持肛门清洁，养成良好的卫生习惯。2.发现肛痈，宜早期治疗，可以防止后遗肛漏。"},{"t":"p","x":"3.肛漏患者应及早治疗，避免外口堵塞而引起脓液积聚，排泄不畅，引发新的支管。"}],"entries":["e0761"]}]},{"id":"d1104","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"肛周坏死性筋膜炎","displayName":"肛周坏死性筋膜炎","parentId":"","printedPage":231,"pdfPage":246,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肛周坏死性筋膜炎是一种发生于肛周、会阴及阴囊部，以皮下组织和筋膜坏死为特征的感染性疾病。"},{"t":"p","x":"其临床特点是呈急性、进行性、坏死性。本病多见于男性，平均发病年龄为50.9岁，发病率较低，但其临床病死率较高，文献报道病死率为9%～25%。"},{"t":"p","x":"在古代中医文献中本病有多个名称，如“肛疽”“烂疔”“脏毒”等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生多因皮肉破损，感染毒气，致火毒之邪侵袭；或因过食醇酒厚味及辛辣刺激之品，湿热内生，下迫大肠，以致毒聚肌肤，蕴结肛门，热盛肉腐而成；"},{"t":"p","x":"或因肛痈失治误治，火毒炽盛，失于遏制，走窜入营血。若正气内虚，火毒炽盛，正不胜邪，毒不外泄，反陷于里，客于营血，内传脏腑，则容易导致内陷危证。"},{"t":"p","x":"西医学认为，本病是由多种细菌混合感染、需氧菌与厌氧菌协同作用的结果。最常见的有大肠埃希杆菌、葡萄球菌、克雷伯菌、梭状芽孢杆菌及念珠菌等。"},{"t":"p","x":"易感因素包括糖尿病、周围性血管疾病、肾功能衰竭、恶性肿瘤，以及营养不良或肥胖、滥用毒品、长期使用免疫抑制剂等。"}],"entries":["e0762","e0763"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现初起肛门周围红、肿、热、痛，继而出现皮肤紫黑、溃烂、脓水稀薄恶臭，迅速向会阴部及周围蔓延，严重者会蔓延至胸腹部、腰背部及下肢，甚至出现局部张力性水疱，局部可触及波动感或捻发音。"},{"t":"p","x":"全身出现持续发热、寒战、面色苍白、脉洪数等。病情急剧恶化，可出现神昏谵语、烦躁嗜睡、心悸胸闷、气粗喘急、汗多肢冷等内陷表现。"},{"t":"p","x":"(2)辅助检查血常规、C反应蛋白、降钙素原检查；生化全套检查；"},{"t":"p","x":"影像学检查，包括B超、CT和MRI检查；组织病理学检查。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-7)"},{"t":"table","img":"img/tab/t1107.jpg","cap":"表11-7肛周坏死性筋膜炎与肛痈、囊痈、脱囊的鉴别"}],"entries":["e0764"]},{"title":"治疗","blocks":[{"t":"p","x":"本病应中西医结合救治，内治、外治并用，以手术治疗为主。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110401","name":"热毒炽盛证","clinic":"肛周及会阴部肿痛剧烈，肿势可向阴囊蔓延，皮肤焮红肿胀成片，按之有波动感；可伴有恶寒发热，面赤口干，小便困难；舌红，苔薄黄，脉数","treat":"清热解毒，凉血消肿","formula":"黄连解毒汤合凉血地黄汤加减","formulaNames":["黄连解毒汤","凉血地黄汤"]},{"t":"syn","sid":"s110402","name":"正虚邪盛证","clinic":"肛周、会阴及阴囊脓肿破溃，溃后脓出恶臭，夹有败絮样物质，周围皮色暗红，或坏死呈紫黑色；可伴有神疲乏力；舌淡、苔薄、脉濡","treat":"扶正祛邪、托毒消肿","formula":"托里消毒散加减","formulaNames":["托里消毒散"]},{"t":"syn","sid":"s110403","name":"气血两虚证","clinic":"腐肉已脱，脓液稀薄，肉色灰淡，疮口难敛；可伴神疲乏力，面色无华；舌淡，苔薄白，脉沉细无力","treat":"益气养血，收敛生肌","formula":"固本养荣汤加减。阴虚者加青蒿、鳖甲、知母，肾虚者加龟甲、玄参、熟地黄","formulaNames":["固本养荣汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初起宜清热解毒消肿，选用金黄散调油外敷患处。"},{"t":"p","x":"(2)中期自行溃破或切开引流后，可用双氧水及生理盐水反复冲洗创面。"},{"t":"p","x":"待创面脓性渗出减少，脓腐减少，改用生肌玉红膏纱条换药。"},{"t":"p","x":"(3)后期脓腐脱尽，肉芽组织新鲜，以生肌收口为主，用红油膏、生肌散换药。"},{"t":"p","x":"3.手术疗法一旦诊断明确，应及时手术治疗。"},{"t":"p","x":"(1)清创引流"},{"t":"p","x":"操作方法：麻醉后常规消毒。从病灶中心切开，从最严重的区域逐渐向外扩展，彻底清除坏死组织，确保创面通畅引流。"},{"t":"p","x":"从皮肤的外观观察，坏死区域通常远远超出最初预期的范围，应充分切开减压引流，切口可行对口引流及拖线引流，对深部的腔隙予置管引流。"},{"t":"p","x":"(2)术中注意事项 ①清创应彻底，以可见健康组织出血为度。"},{"t":"p","x":"②引流要通畅，有深部腔隙应置管引流。"},{"t":"p","x":"③术中应取多处组织进行病理活检和细菌培养。"},{"t":"p","x":"④密切监测生命体征。"},{"t":"p","x":"(3)术后处理 ①应加强营养。"},{"t":"p","x":"②根据术后疼痛的程度，给予适当的镇痛治疗。"},{"t":"p","x":"③若创面脓腐及坏死组织较多或红肿范围加大时，可再次清创引流。"}]},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)抗生素治疗：早期、足量、联合使用广谱抗生素。"},{"t":"p","x":"(2)负压伤口疗法。"},{"t":"p","x":"(3)高压氧治疗。"},{"t":"p","x":"(4)危急重症处理：若发展为脓毒性休克、多器官功能衰竭，应及时给予液体复苏、抗休克、纠正多器官功能衰竭等治疗。"},{"t":"p","x":"(5)并发症处置：如因基础疾病诱发者，应积极治疗原发病。"}]}],"entries":["e0765","e0766","e0767","e0768","e0769","e0770"]}]},{"id":"d1105","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"肛裂","displayName":"肛裂","parentId":"","printedPage":232,"pdfPage":247,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肛管皮肤全层裂开并形成感染性溃疡者称为肛裂。中医学将本病称为“钩肠痔”“裂痔”“裂肛痔”“脉痔”等。"},{"t":"p","x":"如《外科大成·痔漏》云：“钩肠痔，肛门内外有痔，折缝破烂，便如羊粪，粪后出血，秽臭大痛⋯⋯”其临床特点是肛门周期性疼痛、出血、便秘。多见于20～40岁的青壮年，好发于截石位6、12点处，而发于12点处者又多见于女性。"},{"t":"p","x":"在肛门部疾病中，肛裂的发病率位居第三。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因阴虚津液不足或脏腑热结肠燥，而致大便秘结，粪便粗硬，排便努挣，使肛门皮肤裂伤，湿热蕴阻，染毒而成。《医宗金鉴·外科心法要诀·痔疮》曰：“肛门围绕、折纹破裂、便结者，火燥也。”"},{"t":"p","x":"1.血热肠燥常因饮食不节、恣饮醇酒、过食辛辣厚味。以致燥热内结。耗伤津液，无以下润大肠、则大便干结；临厕努责、使肛门裂伤而致便血等。"},{"t":"p","x":"2.阴虚津亏素有血虚，血虚津乏生燥，肠道失于濡润，可致大便燥结，损伤肛门而致肛裂；阴血亏虚则生肌迟缓，疮口不易愈合。"},{"t":"p","x":"3.气滞血瘀气为血之帅、气行则血行，气滞则血瘀。热结肠燥，气机阻滞而运行不畅，气滞则血瘀阻于肛门、使肛门紧缩、便后肛门刺痛明显。"},{"t":"p","x":"西医学认为。肛裂的发生与解剖、外伤、感染及内括约肌痉挛等因素有关。"}],"entries":["e0771","e0772"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现主要表现为便时疼痛。呈撕裂样疼痛或灼痛、排便后数分钟疼痛逐渐减轻或消失，称为疼痛间歇期。"},{"t":"p","x":"随后乂因括约肌持续性痉挛而剧烈疼痛，往往持续数小时方能逐渐缓解。同时可见大便时出血，一般为滴血，量少或仅附着于粪便表面。"},{"t":"p","x":"患者常有习惯性便秘，干燥粪便常使肛门皮肤撕裂而引起肛裂、又因恐惧大便时的肛裂疼痛而不愿定时排便，产生“惧便感”，又使便秘加重，形成恶性循环。"},{"t":"p","x":"(2)专科检查以肛门视诊为主，用两拇指将肛缘皮肤向两侧轻轻分开，并嘱患者放松肛门，可见肛管有纵行裂口或纵行梭形溃疡，多位于截石位6点或12点处，常伴有赘皮外痔、肛乳头肥大等。"},{"t":"p","x":"必要时可行直肠指诊及肛门镜检查，疼痛剧烈的需在局麻下进行。"},{"t":"h","lv":3,"x":"(3)临床分期根据不同病程及局部表现，肛裂分为以下两期："},{"t":"p","x":"早期肛裂：发病时间较短，仅在肛管皮肤上见有一小的梭形溃疡，创面浅而色鲜红，边缘整齐，有弹性。陈旧性肛裂：病程较长，反复发作，溃疡色淡白，底深，边缘呈“缸口”增厚，底部形成平整较硬的灰白组织(栉膜带)。"},{"t":"p","x":"由于裂口周围组织的慢性炎症，常可伴发结缔组织性外痔(又称赘皮痔)、单口内瘘、肛乳头肥大、肛窦炎、肛乳头炎等。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-8)"},{"t":"table","img":"img/tab/t1108.jpg","cap":"表11-8肛裂与结核性溃疡、肛门皲裂、梅毒性溃疡的鉴别"}],"entries":["e0773"]},{"title":"治疗","blocks":[{"t":"p","x":"肛裂的治疗以纠正便秘、止痛和促进溃疡愈合为目的。早期肛裂一般采用保守治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110501","name":"血热肠燥证","clinic":"大便二三日一行、质干硬，便时肛门疼痛，便时滴血或手纸染血，裂口色红；腹部胀满，溲黄；舌偏红。脉弦数","treat":"清热润肠通便","formula":"凉血地黄汤合脾约麻仁丸加减。出血较多者，加侧柏炭；大便干硬者，加番泻叶","formulaNames":["凉血地黄汤","脾约麻仁丸"]},{"t":"syn","sid":"s110502","name":"阴虚津亏证","clinic":"大便干结、数日一行。便时疼痛，点滴下血，裂口深红；口干咽燥，五心烦热；舌红，苔少或无苔、脉细数","treat":"养阴清热润肠","formula":"润肠汤加减、便头干者、加肉苁蓉；口干较甚，加天花粉、石斛","formulaNames":["润肠汤"]},{"t":"syn","sid":"s110503","name":"气滞血瘀证","clinic":"肛门刺痛明显、便时便后尤甚，肛门紧缩，裂口色紫暗；舌紫暗，脉弦或涩","treat":"理气活血、润肠通便","formula":"六磨汤加减。疼痛剧烈者，加红花、桃仁、赤芍等","formulaNames":["六磨汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)熏洗法每次便后用苦参汤或花椒食盐水坐浴，也可用1:5000高锰酸钾液坐浴，有促进血液循环、保持局部清洁、减少刺激的作用。"},{"t":"p","x":"此法乃肛裂外治之首步，至关重要。通过温热药液的熏洗，可有效清洁肛门皱褶内残留的粪便，减少异物对溃疡面的持续刺激与感染风险；"},{"t":"p","x":"同时温热作用能缓解内括约肌的痉挛性收缩，减轻疼痛，为后续用药创造良好条件。中药坐浴方中，苦参能清热燥湿、杀虫止痒，花椒可止痛，共奏清热解毒、活血止痛之效。"},{"t":"p","x":"(2)外敷法坐浴后用生肌玉红膏蘸生肌散涂于裂口，每天1～2次。"},{"t":"p","x":"具有活血祛腐、解毒镇痛、润肤生肌等作用。生肌玉红膏出自《外科正宗》，具有活血解毒、祛腐生肌之功，配合生肌散可加速陈旧性肛裂内坏死组织的脱落和新肉的生长。"},{"t":"p","x":"西医学认为，硝酸甘油软膏等血管扩张剂可通过局部松弛内括约肌，降低肛管静息压，改善局部血液循环，从而打破“疼痛-痉挛-更痛”的恶性循环，促进裂口愈合。临床应根据肛裂的分期和中西医学诊断合理选择外用药物。"},{"t":"p","x":"(3)封闭法于长强穴(属督脉，邻近肛门)用0.5%罗哌卡因或1%利多卡因做扇形注射，隔天1次，5次为1个疗程。"},{"t":"p","x":"亦可于裂口基底部注入长效止痛液或复方利多卡因注射液，每周1次。此法属于神经阻滞疗法，旨在通过药物阻断病理性疼痛刺激的传导，并长效松弛痉挛的内括约肌。"},{"t":"p","x":"于长强穴行扇形注射，可阻断肛周感觉神经，迅速缓解疼痛；同时，局部麻醉药本身也可使肌肉松弛，打破“疼痛-痉挛-更痛”的恶性循环，为裂口愈合创造宽松的病理环境。"},{"t":"p","x":"该疗法适用于疼痛剧烈，经熏洗、外敷效果不佳的早期或陈旧性肛裂。"},{"t":"p","x":"(4)肉毒素注射疗法为西医学一种有效的微创治疗手段。"},{"t":"p","x":"将A型肉毒杆菌毒素精确注射于肛裂基底及内括约肌部位，其强效的化学性神经阻滞作用可显著抑制内括约肌的过度痉挛，使肛管压力持久性下降，从而有效缓解疼痛，极大改善局部血供，为肛裂的自愈提供长达数月(通常3～6个月)的窗口期。"},{"t":"p","x":"该疗法的优点是操作简便、创伤小、副作用少，尤其适用于对传统保守治疗无效而又畏惧手术的患者。3.手术疗法陈旧性肛裂和非手术疗法治疗无效的早期肛裂，可考虑手术治疗，并根据不同情况选择不同的手术方法。"},{"t":"p","x":"(1)内括约肌侧切术"},{"t":"p","x":"适应证：适用于不伴有结缔组织外痔、皮下瘘等的陈旧性肛裂，无肛门失禁的患者。操作方法：取侧卧位或截石位。"},{"t":"p","x":"局麻或腰俞麻醉下、肛内常规消毒、术者用食指探查找到括约肌间沟、用手术刀在肛缘侧方皮肤行2cm弧形切口，然后用血管钳找到并暴露内括约肌，将内括约肌分离到齿状线、再将部分内括约肌切断。最后进行止血、手术线缝合伤口。"},{"t":"p","x":"(2)肛裂切除加括约肌松解术适应证：适用于陈旧性肛裂、伴有结缔组织性外痔、肛乳头肥大等。"},{"t":"p","x":"操作方法：取侧卧位或截石位。"},{"t":"p","x":"局麻或腰俞麻醉下，肛内常规消毒，在肛裂正中做纵行切口，上至齿状线，切断栉膜带及部分内括约肌环形纤维，下端向下适当延长，切断部分外括约肌皮下部纤维，使引流通畅，同时将赘皮外痔、肥大肛乳头等一并切除，修剪溃疡边缘发硬的瘢痕组织，形成一底小顶大的“V”字形开放创口。"},{"t":"p","x":"在肛门后位偏左或偏右位置距肛缘1.5cm处做一纵行切口，深达皮下，以止血钳显露内括约肌下缘，在直视下用两把血管钳夹住内括约肌下缘后切断，切口一般不缝合，以红油膏纱条嵌压引流，再用纱布覆盖固定。"},{"t":"p","x":"(3)纵切横缝法"},{"t":"p","x":"适应证：适用于陈旧性肛裂伴有肛管狭窄者。操作方法：取侧卧位或截石位。"},{"t":"p","x":"局麻或腰俞麻醉下，肛内常规消毒，沿肛裂正中做一纵行切口，上至齿状线上0.5cm，下至肛缘外0.5cm，切断栉膜带及部分内括约肌纤维；如有潜行性皮下瘘管、赘皮痔、肛乳头肥大、肛窦炎也一并切除；"},{"t":"p","x":"修剪裂口创缘，再游离切口下端的皮肤，以减少张力，彻底止血；然后用细丝线从切口上端进针，稍带基底部组织，再从切口下端皮肤穿出，横行缝合，一般缝合3～4针，外盖红油膏纱布，纱布压迫，胶布固定。"},{"t":"p","x":"术后应嘱患者进流质饮食或软食2日，控制大便1～2日。便后用中药坐浴或1:5000高锰酸钾液坐浴，肛内注入九华膏换药，5～7日拆线。"},{"t":"p","x":"4.其他疗法在肛裂的保守治疗中，中成药作为内治法的重要补充，临床上可根据辨证分型合理选用，以缓解症状、润通大便并促进创面愈合。"},{"t":"p","x":"对于血热肠燥证，治宜清热凉血、润肠通便，可选用槐角丸等，此类成药多含槐角、大黄、火麻仁等成分，能清泄肠道实热，适用于便血明显、大便干硬伴腹部胀满者。"},{"t":"p","x":"阴虚津亏证则治以养阴生津、润肠通便，常用增液颗粒，其多富含玄参、生地黄、麦冬等滋阴养血之品，能增液行舟，适用于口干咽燥、虚性便秘者。"},{"t":"p","x":"气滞血瘀证需行气活血、化瘀止痛，可选用血府逐瘀胶囊配合润肠药物治疗，以改善局部循环、缓解括约肌痉挛，适用于病程较长、肛门刺痛剧烈、裂口紫暗者。临床须严格遵循辨证论治原则，辨清虚实寒热，对证选药；"},{"t":"p","x":"同时明确中成药多属辅助手段，若属陈旧性肛裂，仍需手术疗法，方能取得最佳疗效。"}]}],"entries":["e0774","e0775","e0776","e0777","e0778"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.注意肛门清洁卫生。2.大便干结时，适度运动增加肠道蠕动，多食蔬菜及水果，或每次餐前半小时口服适量蜂蜜水(糖尿病除外)，防止大便干燥，避免粗硬粪便擦伤肛门。"},{"t":"p","x":"3.养成定时排便习惯。4.积极治疗便秘及其他肛门疾病。"}],"entries":["e0779"]}]},{"id":"d1106","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"脱肛","displayName":"脱肛","parentId":"","printedPage":235,"pdfPage":250,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"脱肛是肛管、直肠黏膜、直肠全层，甚至部分乙状结肠向下移位的一种疾病。此名首见于《神农本草经》。"},{"t":"p","x":"古文献又称“人州出”“脱肛痔”等。其临床特点是努挣后肠黏膜或肠管全层脱出，不出血或有少量淡红色血性黏液，常伴肛门失禁或便秘。"},{"t":"p","x":"脱肛常见于儿童、老年人及多次分娩或有长期便秘、慢性腹泻者。直肠黏膜松弛下移未脱出于肛门外者，称为内脱垂；脱出于肛门外者，称为外脱垂。"},{"t":"p","x":"外脱垂又分为黏膜层脱垂(不完全脱垂)和肠管全层脱垂(完全脱垂)。本病相当于西医学的“直肠脱垂”。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多因脾虚气陷、肛门失其固摄而发。湿热实邪可加重病势，临证亦可见虚实夹杂之证。"},{"t":"p","x":"1.脾虚气陷小儿先天不足，气血未旺，或老年气血衰退，或因劳倦、久病体虚、小儿气血未充、老年气血衰退、妇人生产努责，以致气血不足，中气下陷，不能固摄而成。2.湿热下注素本气虚，摄纳失司，复染湿热而脱。"},{"t":"p","x":"西医学认为，本病多因先天性盆底解剖缺陷、便秘等导致长期腹压增加，慢性消耗性疾病或营养吸收障碍，中枢或外周神经系统疾病等，导致盆底及会阴部支持固定直肠能力减弱而发。"}],"entries":["e0780","e0781"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现 ①以肠黏膜或肠管全层脱出为主症，脱出物为淡红色，可见放射状或环形黏膜皱襞。"},{"t":"p","x":"早期脱出，便后能自行还纳，渐渐需手托或平卧方能回纳，日久失治，咳嗽、下蹲或行走时也可脱出。"},{"t":"p","x":"②肛门坠胀不适感。"},{"t":"p","x":"③黏液分泌物增多，可诱发肛门瘙痒和湿疹。"},{"t":"p","x":"④反复脱出可致肛门括约肌功能下降，导致不同程度肛门失禁。"},{"t":"p","x":"⑤排便困难，便后不尽感。"},{"t":"p","x":"⑥若脱垂未及时回纳，可出现疼痛，脱出肠管肿胀发紫、糜烂坏死等。"},{"t":"p","x":"(2)专科检查蹲位检查有助于明确病情。"},{"t":"p","x":"嘱患者取蹲位做排便动作，屏气时观察是否有直肠黏膜或直肠壁脱出肛门外，检查脱出物长度。"},{"t":"p","x":"(3)辅助检查直肠指诊、肛管直肠测压、肌电图检查可帮助判断肛门功能情况。"},{"t":"p","x":"排粪造影可了解是否有直肠黏膜内脱垂。伴有阴道脱垂或尿失禁患者，须做尿动力学和妇科检查。"},{"t":"h","lv":3,"x":"(4)分度直肠脱垂可分为三度。"},{"t":"p","x":"I度脱垂：直肠黏膜脱出，脱出物长3～5cm，色淡红，触之柔软，无弹性，不易出血，便后可自行回纳。"},{"t":"p","x":"Ⅱ度脱垂：直肠全层脱出，脱出物长5～10cm，色淡红，呈圆锥状，表面为环状而有层次的黏膜皱襞，触之较厚，有弹性，肛门松弛，便后需用手回纳。"},{"t":"p","x":"Ⅲ度脱垂：直肠及部分乙状结肠脱出，脱出物长10cm以上，呈圆柱形，触之很厚，肛门松弛无力。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-9)"},{"t":"table","img":"img/tab/t1109.jpg","cap":"表11-9脱肛与内痔脱出、直肠息肉的鉴别"}],"entries":["e0782"]},{"title":"治疗","blocks":[{"t":"p","x":"脱肛治疗以辨证论治为大法。虚证为主者，治以补中升陷、益气升提；虚实兼杂者当虚实兼顾；"},{"t":"p","x":"实证为主者，以清化湿热为主。必要时，行手术治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110601","name":"脾虚气陷证","clinic":"便时肛门肛内肿物脱出，轻重程度不一、色淡红；伴有肛门坠胀、大便带血，神疲乏力，食欲不振，甚则头昏耳鸣、腰膝酸软；舌淡，苔薄白、脉细弱","treat":"补气升提、收敛固摄","formula":"补中益气汤加减","formulaNames":["补中益气汤"]},{"t":"syn","sid":"s110602","name":"湿热下注证","clinic":"肛内肿物脱出，色紫暗或深红，甚则表面溃烂，肛门坠痛，肛内有灼热感；舌红，苔黄腻，脉洪数","treat":"清热利湿","formula":"萆薢渗湿汤或葛根芩连汤加减","formulaNames":["萆薢渗湿汤","葛根芩连汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"熏洗、外敷按证型辨证用药，先熏后洗，必要时可外敷治疗。3.手术疗法适用于Ⅱ、Ⅲ度脱肛者。"},{"t":"p","x":"分为经腹及经会阴入路两类。根据手术目的，分为直肠悬吊固定、肛门紧缩和脱垂肠管切除三大类。"},{"t":"p","x":"手术方法很多，如腹腔镜腹侧直肠补片固定术(laparascopic ventral mesh rectopexy,LVMR)、经会阴直肠乙状结肠切除术(Altemeier术)、黏膜剥除肌层折叠术(Delorme术)等；"},{"t":"p","x":"但各有优缺点，没有哪一种手术方法可用于所有的患者。"}]},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)注射疗法适用于小儿或年老体弱者。"},{"t":"p","x":"作用原理：药物刺激→无菌性炎症→纤维化→粘连固定脱垂组织。禁忌证：直肠炎、腹泻、肛周炎及持续性腹压增加者。"},{"t":"p","x":"1)黏膜下注射法分黏膜下层点状和柱状注射法。"},{"t":"p","x":"适应证：I、Ⅱ度脱肛，I度脱肛效果最好。操作方法：齿状线上1cm环形选择2～3个平面或纵行选择3～6行，每个平面或每行选择3～6点，每点注药0.2～0.3mL，总量为6～10mL。"},{"t":"p","x":"柱状注射是在肛外直肠黏膜3、6、9、12点齿状线上1cm的黏膜下层，长短视脱出长度而定，每柱药量2～3mL，注射完毕送回肛内。"},{"t":"p","x":"2)直肠周围注射法"},{"t":"p","x":"适应证：Ⅱ、Ⅲ度脱肛。操作方法：距肛缘1.5cm的3、6、9点进针，用细长腰穿针头和20mL注射器吸入药液20mL，通过坐骨直肠窝、肛提肌，进入骨盆直肠间隙。"},{"t":"p","x":"以针尖在直肠壁外自由摆动为准，缓慢注入药物6～8mL，使药液呈扇形均匀散开。"},{"t":"p","x":"(2)针灸疗法体针及电针足三里、八醪穴等穴位；"},{"t":"p","x":"艾灸百会、长强等穴位；也可在股内侧肌群及臀中肌等浮针治疗。"}]}],"entries":["e0783","e0784","e0785","e0786","e0787"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.纠正便秘及努挣排便等不良习惯。2.避免经阴道分娩造成的会阴部神经及肌肉损伤。"},{"t":"p","x":"3.指导患者及时将脱出物回纳，避免脱出物嵌顿坏死。"}],"entries":["e0788"]}]},{"id":"d1107","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"息肉痔","displayName":"息肉痔","parentId":"","printedPage":237,"pdfPage":252,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"息肉痔是指发生于直肠黏膜上的赘生物，是一种常见的直肠良性肿瘤。"},{"t":"p","x":"历代文献中有“息肉痔”“悬胆痔”“垂珠痔”“樱桃痔”等病名。其临床特点为肿物蒂小质嫩，其色鲜红、便后出血。"},{"t":"p","x":"可分为单发性和多发性两种，前者多见于儿童，后者多见于成年人。随年龄增长，患病率增加。"},{"t":"p","x":"若很多息肉积聚在一段或全段大肠者，称为息肉病。本病少数可恶变，尤以多发性息肉者恶变率较高。"},{"t":"p","x":"本病相当于西医学的直肠息肉。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"息肉的发生与饮食不节、劳倦内伤、情志失调及先天禀赋不足等因素有关。1.风伤肠络风性善行而数变，且风常夹热，热伤肠络，血不循经，溢于脉外则便血。"},{"t":"p","x":"2.气滞血瘀饮食不节、劳倦过度，导致脾胃运化功能不足，湿邪内生，下注大肠，经络阻塞、瘀血，浊气凝聚不散，气滞血瘀，日久而发为息肉。"},{"t":"p","x":"3.脾气亏虚先天禀赋不足或思虑过度，忧思不解，郁结伤脾，脾气不行，水湿不化，津液聚而成痰，痰气郁结于大肠、则化生息肉。西医学认为，本病的发生可能与遗传、饮食、肠道炎症和物理刺激等有关。"}],"entries":["e0789","e0790"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现因息肉的大小及位置高低而不同。"},{"t":"p","x":"位置较高的小息肉一般无症状；低位带蒂息肉，大便时可脱出肛门外，小的能自行回纳，大的便后需用手推回，常伴有排便不畅、下坠，或有里急后重感。"},{"t":"p","x":"多发性息肉常伴腹痛、腹泻，排出血性黏液便，久之则体重减轻、体弱无力、消瘦、贫血等。若息肉并发溃疡及感染，可有大便次数增加，里急后重，便后出血，伴血性黏液排出。"},{"t":"p","x":"(2)专科检查肛门指诊和肛门镜检查对低位息肉有重要诊断价值。"},{"t":"p","x":"可发现黏膜表面隆起性病变，质地柔软，色淡红或深红。多发性息肉则可触及直肠腔内有葡萄串样、大小不等的球形肿物，指套染血或附有血性黏液。"},{"t":"p","x":"结肠镜检查并取活体组织行病理检查，可进一步明确诊断。"},{"t":"p","x":"(3)分类根据组织病理学，息肉可分为肿瘤性息肉和非肿瘤性息肉。"},{"t":"p","x":"肿瘤性息肉又分为腺瘤性息肉和锯齿状病变两大类，非肿瘤性息肉有炎症性、错构瘤性、化生性等类型。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-10)"},{"t":"table","img":"img/tab/t1110.jpg","cap":"表11-10息肉痔与直肠癌、肛乳头肥大、内痔的鉴别诊断"}],"entries":["e0791"]},{"title":"治疗","blocks":[{"t":"p","x":"本病发现后应及早切除治疗，根据病情辅以中药辨证内服，多发性息肉者配合外治法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110701","name":"风伤肠络证","clinic":"便血鲜红，滴血，带血；息肉表面充血明显，脱出或不脱出肛外；舌质红，苔薄白或薄黄，脉浮数","treat":"清热凉血，祛风止血","formula":"槐角丸加减","formulaNames":["槐角丸"]},{"t":"syn","sid":"s110702","name":"气滞血瘀证","clinic":"肿物脱出肛外，不能回纳、疼痛甚。息肉表面紫暗；舌紫，脉涩","treat":"活血化瘀、软坚散结","formula":"少腹逐瘀汤加减","formulaNames":["少腹逐瘀汤"]},{"t":"syn","sid":"s110703","name":"脾气亏虚证","clinic":"肿物易于脱出肛外，表面增生粗糙，或有少量出血，肛门松弛；舌质淡，苔莎，脉弱","treat":"补益脾胃","formula":"参苓白术散加减","formulaNames":["参苓白术散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"灌肠适用于多发性息肉。选用具有收敛、软坚散结作用之药液，如6%明矾液50mL，保留灌肠、每天1次。"},{"t":"p","x":"或用乌梅、海浮石各12g，五倍子6g，牡蛎、夏枯草各30g，紫草、贯众各15g，浓煎为150～200mL，每次取50mL，保留灌肠，每天1次。"}]},{"t":"sub","title":"3.手术疗法","blocks":[{"t":"p","x":"(1)内镜下治疗根据息肉形态及大小，可采用活检钳切除、圈套器切除、内镜下黏膜切除术(endoscopic mucosal resection,EMR)及内镜黏膜下剥离术(endoscopic submucosal disp,ESD)等。"},{"t":"p","x":"(2)结扎法适用于低位带蒂息肉。"},{"t":"p","x":"(3)套扎法本法是通过器械将小乳胶圈套人息肉根部，利用胶圈较强的弹性阻止血液循环，促使息肉缺血、坏死、脱落。"},{"t":"p","x":"(4)直肠结肠切除术对高位多发性腺瘤，必要时可考虑做直肠结肠切除术。"}]}],"entries":["e0792","e0793","e0794","e0795","e0796","e0797"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.高纤维、低脂肪饮食，减少红肉和加工肉的摄入量，避免过量饮酒和吸烟，是降低结直肠息肉风险的重要措施。定期筛查也是预防结直肠息肉的重要手段。"},{"t":"p","x":"2.息肉脱出肛外要及时回纳，切不可盲目牵拉，以免撕伤或断裂而造成大出血。"}],"entries":["e0798"]}]},{"id":"d1108","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"便秘","displayName":"便秘","parentId":"","printedPage":239,"pdfPage":254,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"便秘是临床上由多种原因引起的一种常见的消化道症候群，表现为排便次数减少、粪质干硬和(或)排便困难。"},{"t":"p","x":"其中排便次数减少指每周排便少于3次，排便困难包括排便费力、排出困难、排便不尽感、排便费时、肛门直肠有堵塞感或需手法辅助排便等。临床上便秘一般指功能性便秘，包括慢传输型便秘、排便障碍型便秘、混合型便秘(两者兼而有之)。"},{"t":"p","x":"这一类疾病的共同特点是出口处(肛门、远端直肠)有梗阻因素存在，而且这些梗阻因素仅在行使排便功能时才显露出来，安静状态下并无明显异常可见。"},{"t":"p","x":"便秘在《内经》中称之为“后不利”，如《素问·厥论》所言“太阴之厥，则腹满胀，后不利”。清代程国彭《医学心悟·大便不通》将便秘分为“实闭、虚闭、热闭、冷闭”四种类型，对临床具有指导意义。"},{"t":"p","x":"本病男女均可发病，但多见于多产的女性。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"便秘多是由于排便习惯不良，临厕努责，妇女多产，会阴产伤，以及年老身体功能渐衰导致正常解剖结构改变，或气机阻滞，或湿热下注，或气阴两虚，或阳虚寒凝，日久肠胃受损，大便排出不畅或排便不尽、排便困难、肛门直肠有堵塞感。"},{"t":"p","x":"1.脾虚气陷素体虚弱，身体羸瘦，或老年人气血衰退，或妇女分娩用力耗气，致中气不足，升举无力，固摄失司，使盆腔组织或盆底肌肉松弛而发生便秘。"},{"t":"p","x":"2.气机阻滞忧愁思虑过度，情志不舒，或久坐少动，而致气机郁滞，不能宣达，于是通降失常，肛周功能不调，粪便排出困难。"},{"t":"p","x":"3.湿热下注平素嗜食辛辣炙之品，辛辣之物易酿湿生热，湿邪重滞，热邪灼津，下注肛周，致肛门盆底肌肉收缩不良而发便秘。"},{"t":"p","x":"4.气阴两虚劳倦饮食内伤，或病后、产后及年老体虚之人，气阴两亏，气虚则大肠传送无力，阴虚则津枯不能滋润大肠，致秘结不通，排出不畅。"},{"t":"p","x":"5.阳虚寒凝凡阳虚体弱，或年高体衰，则阴寒内生，留于肠胃，于是凝阴固结，致阳气不通，津液不行，故肠道艰于传送、致排出困难。"},{"t":"p","x":"西医学认为，这一类疾病的发生与性别、年龄、女性分娩情况、肛管直肠环及盆底肌肉异常、不良的排便习惯有关。"}],"entries":["e0799","e0800"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现 ①排便过程不顺利、包括大便量少、便质干结，排出困难三个方面；"},{"t":"p","x":"②排便困难，伴有一些特殊的症状，如长期排便费力、直肠肛门坠胀及堵塞感、便不尽感，甚者需要手法帮助排便；"},{"t":"p","x":"③7天内排便少于2～3次。"},{"t":"p","x":"根据不同的情况又有不同的表现。"},{"t":"p","x":"1)直肠内脱垂指直肠黏膜层或全层套叠入远端直肠腔或肛管内而未脱出肛门的一种功能性疾病。"},{"t":"p","x":"多见于中老年人，女性多于男性。主要表现：①排便困难：直肠排空困难，有排便不尽感、肛门阻塞感、且用力越大，阻塞感越重，常需手法辅助排便；"},{"t":"p","x":"②疼痛：有些患者排便时肛门疼痛、下腹部或骶部疼痛；"},{"t":"p","x":"③黏液血便：偶有血便或黏液便；"},{"t":"p","x":"④大便失禁：多因阴部神经损伤引起不同程度的大便失禁。"},{"t":"p","x":"另外，部分患者伴有精神症状，多为抑郁或焦虑。直肠指检时直肠黏膜较为松弛，偶可扪及套叠环。"},{"t":"p","x":"肛门镜检查有时可见直肠黏膜充血、水肿、溃疡。"},{"t":"p","x":"2)直肠前突本病主要见于女性，以中老年患者居多。"},{"t":"p","x":"由于直肠前壁向阴道突出，排便时压力向阴道方向而不向肛门口，粪块积存于前突的直肠内而造成梗阻(图11-46)。主要表现是排便困难，肛门口处梗阻感，排便时肛门处压力分散感及排空不全感；"},{"t":"p","x":"部分患者需用手在肛门周围或阴道内加压，甚至需将手指插入肛门内协助排便，有的患者将卫生纸卷或肥皂条插入肛门诱导排便；部分患者有便血、肛门疼痛等。"},{"t":"p","x":"直肠指检时肛管上端直肠前壁可扪及圆形或椭圆形凹陷的薄弱区，嘱患者做大力排便动作，该凹陷区变深。"},{"t":"img","src":"img/fig/f1146.jpg","alt":"图11-46直肠前突"},{"t":"p","x":"3)会阴下降综合征指盆底肌肉异常松弛引起的一系列临床症状群。"},{"t":"p","x":"主要表现：①排便困难：患者自觉直肠内有梗阻感，排便时间长、费力、排空障碍，结果导致经常做无效的用力努挣动作，部分患者排便时使用手法辅助排便；"},{"t":"p","x":"②便血及便黏液；"},{"t":"p","x":"③会阴部胀痛，久站后可有难以定位的后缘深部不适，平卧或睡眠时减轻，疼痛与排便无明显关系；"},{"t":"p","x":"④大便失禁；"},{"t":"p","x":"⑤小便失禁及阴道脱垂：部分女性患者有功能性排尿异常，多为应力性失禁，常伴有不同程度的阴道脱垂。"},{"t":"p","x":"检查可见用力排便时会阴低于坐骨结节平面；直肠指检时肛管张力低，伴发黏膜内脱垂时，可触及直肠末端黏膜堆积；"},{"t":"p","x":"直肠镜检偶见直肠前壁黏膜脱垂或溃疡。"},{"t":"p","x":"4)盆底失弛缓综合征是指盆底横纹肌和平滑肌由于神经支配异常或反射异常，排便时盆底肌不松弛甚至反常收缩，引起进行性排便困难。"},{"t":"p","x":"涵盖了“盆底痉挛综合征”“耻骨直肠肌综合征”及“内括约肌失弛缓”等概念。主要表现：①长期进行性排便困难：长期使用导泻剂帮助排便，有些是自幼年起病；"},{"t":"p","x":"②过度用力排便：排便时肛门梗阻感，常用手指插入肛门刺激排便，部分患者排便时需过度用力而大汗淋漓，越用力粪便排出越困难，甚至排气困难；"},{"t":"p","x":"③大便变细：与便质无关、粪便量少，甚至细如铅笔芯；"},{"t":"p","x":"④排便时间延长：常需半小时以上；"},{"t":"p","x":"⑤心理精神异常：部分患者可伴随紧张、疑虑、易怒、抑郁、焦虑等症状。"},{"t":"p","x":"肛门指检时肛管张力较高。模拟排便动作时肛管不松弛反而收缩，停止排便动作时肛管可松弛。"},{"t":"p","x":"上述疾病可以单见，严重者兼见。"},{"t":"p","x":"(2)辅助检查结肠镜检查、肛管测压、肛肠肌电图、结肠传输试验、排粪造影、球囊逼出试验等检查有助于疾病的诊断。"},{"t":"p","x":"其中排粪造影是一种诊断肛门直肠部及盆底肌功能性疾病的重要检查方法，即患者排空大便后，将一定量的钡剂注入被检查者的直肠内，嘱患者行排便动作，做X线检查，在符合生理状态下对肛门直肠部及盆底肌做静态及动态观察，主要用于诊断肛门直肠的功能性疾病，如直肠前突、直肠内脱垂、会阴下降综合征、盆底失弛缓综合征等，是决定治疗方式的可靠依据之一。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-11)"},{"t":"table","img":"img/tab/t1111.jpg","cap":"表11-11便秘的鉴别诊断"}],"entries":["e0801"]},{"title":"治疗","blocks":[{"t":"p","x":"本病应首选保守治疗。经过系统的保守治疗后，大多数患者可缓解或减轻症状。"},{"t":"p","x":"如经保守治疗无效，可考虑采取外科手术治疗，但须慎重。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110801","name":"脾虚气陷证","clinic":"大便不干，便条不粗，但排出困难；伴有神疲乏力，少气懒言，食少纳呆；舌淡，苔白，脉弦","treat":"补气润肠，健脾升阳","formula":"黄芪汤加减。气虚明显者，倍黄芪；食欲不振者，加焦三仙","formulaNames":["黄芪汤"]},{"t":"syn","sid":"s110802","name":"气机阻滞证","clinic":"大便秘结，欲便不能，甚则便条不粗仍排出困难；兼嗳气频作，胸胁痞满，甚则腹中胀痛，纳食减少；舌淡，苔薄腻，脉弦","treat":"顺气行滞通便","formula":"六磨汤加减。嗳气严重者，加旋覆花、代赭石；胀痛明显者，加延胡索、川楝子","formulaNames":["六磨汤"]},{"t":"syn","sid":"s110803","name":"湿热下注证","clinic":"排便困难，直肠内有梗阻、坠胀感，会阴部灼热感，粪便夹有黏液，偶有血便；伴有口干、烦躁；舌红，苔黄腻，脉滑数","treat":"清热导滞，润肠通便","formula":"麻子仁丸加减。津伤明显者，加生地黄、麦冬；烦热不甚，便通而不爽者，可用青麟丸","formulaNames":["麻子仁丸"]},{"t":"syn","sid":"s110804","name":"气阴两虚证","clinic":"老年体弱之人，虽有便意，但临厕努挣乏力，挣则汗出气短，面色苍白；兼有恶心，烦热盗汗，神疲乏力，懒言；舌淡红，苔薄而少，脉细","treat":"益气养阴通便","formula":"八珍汤加减。本方为四君子汤合四物汤而成，平补气血，可加何首乌、肉苁蓉以助益气养阴通便之效","formulaNames":["八珍汤"]},{"t":"syn","sid":"s110805","name":"阳虚寒凝证","clinic":"大便艰涩、排出困难；小便清长，面色苍白，四肢不温，喜热怕冷，腹中冷痛或腰脊酸冷；舌淡，苔白，脉沉迟","treat":"温阳通便","formula":"济川煎加肉桂。若老人虚冷便秘，可用半硫丸；若脾阳不足，中焦虚寒，可用理中丸加味；若肾阳不足，尚可选用金匮肾气丸或右归丸","formulaNames":["济川煎"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"灌肠常用大黄、芒硝、桃仁、当归等中药煎剂灌肠或保留灌肠。"}]},{"t":"sub","title":"3.手术疗法","blocks":[{"t":"p","x":"(1)手术原则由于目前评价手术方法的效果较为困难。"},{"t":"p","x":"所以，本节疾病必须经过系统的非手术治疗失败后方可进行手术治疗。决定进行手术治疗不但要基于患者的症状，而且要依据物理检查发现和对排粪造影等检查过程中排空情况的客观分析。"},{"t":"p","x":"便秘的原因往往不是单一的，多数是复合因素。因此，术前应详细检查，认真分析，以便采取合适的手术治疗方案。"},{"t":"p","x":"(2)手术方法"},{"t":"p","x":"1)直肠内脱垂常见术式"},{"t":"p","x":"硬化剂注射疗法(经肛门直肠黏膜下和直肠周围注射术)：黏膜下注射时根据情况可选用点状注射或柱状注射。直肠黏膜胶圈套扎术(结扎术)：本法适用于直肠中段或远段黏膜内脱垂。"},{"t":"p","x":"在齿状线上方黏膜脱垂处做3行胶圈套扎，每行1～3处，最多套扎9处，以去除部分松弛的黏膜。必要时可在套扎部位黏膜下加注硬化剂。"},{"t":"p","x":"吻合器痔上黏膜环切钉合术(procedure for prolapse and hemorrhoids,PPH)：将PPH吻合器经肛管扩张器将其头端插入到荷包缝合线的上方，收紧缝线，击发的同时切除松弛的黏膜并钉合吻合口。"},{"t":"p","x":"此外，还有经腹直肠固定术。可参见脱肛、内痔的手术方式及硬化剂注射方法。"},{"t":"p","x":"2)直肠前突常见术式"},{"t":"p","x":"闭式修补法(Block法)：按前突大小，用血管钳钳夹直肠黏膜，用可吸收线从齿状线处自下而上连续缝合直肠黏膜及其肌层，修补缺损。"},{"t":"p","x":"吻合器经肛门直肠切除术(stapled transanal rectal resection, STARR)：在直肠前壁做2～3个半荷包缝合，将前壁拉入吻合器内并切除，同时保护直肠后壁；采用同样的方法切除直肠后壁。"},{"t":"p","x":"套扎或注射治疗：行前突部位套扎或硬化剂注射治疗，也可两种疗法同时使用。"},{"t":"p","x":"经阴道切开直肠前突修补术：在阴道后壁做一椭圆形切口(长5～6cm，宽1.5～2cm)，向两侧游离阴道黏膜至肛提肌，在直肠表面的筋膜下，荷包缝合或间断结节缝合修补直肠前突部位。然后，间断结节缝合肛提肌，修剪、缝合阴道黏膜。"},{"t":"p","x":"3)盆底失弛缓综合征耻骨直肠肌部分切除术患者折刀位或俯卧位。"},{"t":"p","x":"从尾骨尖向下做正中切口至肛缘上方，逐层切开，暴露尾骨尖，即为耻骨直肠肌上缘标志。术者左手食指进入直肠，向上顶起耻骨直肠肌，于直肠外游离耻骨直肠肌，注意不要损伤直肠壁。"},{"t":"p","x":"用两把止血钳相距1.5～2cm夹住游离好的耻骨直肠肌，将两钳间肌束切除，使成“V”形缺损，若仍能触及纤维束，则应予切除。更换手套，伤口冲洗后置橡皮片引流，逐层缝合创口。"},{"t":"p","x":"会阴下降综合征尚无较优良的术式，常需盆底重建。"}]},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)一般治疗纠正不良饮食习惯，注意多食用粗纤维食品及蔬菜、水果；"},{"t":"p","x":"晨起一次性饮温白开水500mL，可以促进肠道蠕动，引发便意；纠正不良的排便习惯，定时排便，每次排便时间控制在3～5分钟内。"},{"t":"p","x":"(2)针灸治疗主穴多选大肠俞、天枢、脾俞、三阴交等。"},{"t":"p","x":"阳气不足者可加艾灸，可在针刺的基础上加灸神阙、气海。"},{"t":"p","x":"(3)耳穴压豆选取直肠、内分泌、三焦、大肠等穴。"},{"t":"p","x":"(4)穴位埋线常取八醪、天枢、中谬和下醪等穴。"},{"t":"p","x":"(5)大肠水疗通过水疗仪将恒温的过滤水以恒定压力注入结肠，软化肠内大便并排出。"},{"t":"p","x":"(6)生物反馈疗法该疗法的原理是通过工程技术手段，把一些不被人体感知的生理及病理性活动(如肛门括约肌的舒缩活动)转变成易于理解和识别的信号，并以此为参照，在治疗师的指导下，自我调节、调整、训练排便的动作和过程。"},{"t":"p","x":"同时，通过治疗师与患者之间的交流达到心理调节的作用。该疗法是目前治疗盆底失弛缓综合征的常用方法。"},{"t":"p","x":"(7)精神心理治疗部分患者因病史较长，出现焦虑、抑郁等精神心理障碍，应及时进行心理干预。"}]}],"entries":["e0802","e0803","e0804","e0805","e0806","e0807","e0808","e0809","e0810"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.正确认识便秘，调整心态，保持良好的情绪。2.注意饮食的合理性，保证食物的量、质及多样性。"},{"t":"p","x":"3.养成良好的排便习惯，缩短排便时间。4.切忌滥用和久用泻药，否则易致药物依赖性便秘或大肠黑变病。"}],"entries":["e0811"]}]},{"id":"d1109","kind":"main","chapterId":"ch11","chapterNo":"第十一章","chapterName":"肛肠疾病","name":"锁肛痔","displayName":"锁肛痔","parentId":"","printedPage":243,"pdfPage":258,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"锁肛痔是发生在肛管直肠的恶性肿瘤，病至后期，肿瘤阻塞，肛门狭窄，排便困难，犹如锁住肛门一样，故称为锁肛痔。"},{"t":"p","x":"《外科大成》中对本病的症状和预后做了详细描述：“锁肛痔，肛门内外如竹节锁紧，形如海蜇，里急后重，便粪细而带扁，时流臭水。”本病相当于西医学的肛管直肠癌。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"湿热下注，火毒内蕴，气滞血瘀，结而为肿，是本病之标；正气不足，脾肾两亏，乃本病之本。"},{"t":"p","x":"1.湿热蕴结忧思抑郁，脾胃失和，或饮食不洁、久痢久泻、息肉虫积损伤脾胃，运化失司，湿热内生，浸淫肠道，下注肛门，蕴毒积聚，结而为肿。2.气滞血瘀病久则湿热壅阻大肠，腑气不畅，气血湿毒瘀滞凝结。"},{"t":"p","x":"3.气阴两虚疾病后期，久泻久痢或肿块耗伤气血，致气阴两虚。西医学认为，直肠癌多为腺癌，好发于直肠中、下段；"},{"t":"p","x":"肛管癌原发于肛管皮肤，多为鳞状细胞癌。肛门部瘢痕组织、湿疣、肛瘘等病变亦可诱发癌变。"},{"t":"p","x":"其病因不明，可能与慢性炎症、腺瘤癌变、膳食习惯与致癌物质等有关。"}],"entries":["e0812","e0813"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病的发病年龄多在40岁以上，偶见于青年人，其早期特点是便血、大便习惯改变。"},{"t":"p","x":"初期表现为直肠黏膜或肛门皮肤有突起小硬结，无明显症状，病情进一步发展可出现以下一系列改变。便血：是直肠癌最常见的早期症状。"},{"t":"p","x":"大便带血，血为鲜红或暗红，量不多，常同时伴有黏液，呈持续性，此时常被误认为“痔疮”。病情进一步发展，可出现大便次数增多，有里急后重、排便不尽感，粪便中有血、脓、黏液，并有特殊的臭味。"},{"t":"p","x":"排便习惯改变：也是直肠癌常见的早期症状。表现为排便次数增多、便意频繁、有排便不尽感等。"},{"t":"p","x":"有时为便秘，同时肛门内有不适或下坠感。大便变形：病程后期因肠腔狭窄，粪便少、大便形状变细、变扁，并出现腹胀、腹痛、肠鸣音亢进等肠梗阻征象。"},{"t":"p","x":"转移征象：首先是直接蔓延、后期穿过肠壁，侵入膀胱、阴道壁、前列腺等邻近组织，若侵及膀胱、尿道时，有排尿不畅及尿痛、尿频。侵及骶前神经丛时，在直肠内或骶骨部可有剧烈持续性疼痛，并向下腹部、腰部或下肢放射。"},{"t":"p","x":"另外，可经淋巴向上转移至沿直肠上静脉走行的淋巴结。10%～15%的患者在确诊时癌症已经过门静脉血行转移至肝脏，出现肝肿大、腹水和黄疸等。"},{"t":"p","x":"晚期患者可出现食欲不振、全身衰弱无力、贫血、极度消瘦等恶病质表现。肛管癌较少见，早期肿块较小，可活动，呈现疣状；"},{"t":"p","x":"进一步发展，在肛门部可看到突起包块或溃疡，基底不平，质硬，并可能有卫星转移结节和腹股沟淋巴结转移。"},{"t":"p","x":"(2)专科检查直肠指检是诊断直肠癌最重要的方法，60%～70%的直肠癌位于手指可触及的部位(≤7cm)，肿瘤较大时指检可以清楚地扪到肠壁上的硬块、巨大溃疡或肠腔狭窄，退指后可见指套上染有血、脓和黏液。"},{"t":"p","x":"指检发现癌肿时要扪清大小、范围、部位和固定程度，以便决定治疗方法。凡是出现原因不明的便血、腹泻及体重减轻的患者均应行直肠指诊、直肠镜检查及活组织检查。"},{"t":"p","x":"(3)辅助检查 ①大便潜血检查：是最简单的检查方法之一，常作为大规模普查手段，或作为高危人群直肠癌的初筛手段。"},{"t":"p","x":"②直肠镜或乙状结肠镜检查：对所有指检可疑或已明确无疑的直肠癌均应进行直肠镜或乙状结肠镜检查，不仅可以看到直肠内病变的范围，更重要的是取活组织进行病理检查，以确定诊断。"},{"t":"p","x":"③直肠腔内超声：对5000多例直肠癌的荟萃分析显示，腔内超声对T分期的敏感性为81%～96%，特异性为91%～98%。"},{"t":"p","x":"④盆腔增强MRI：不但能评估肿瘤浸润肠壁的深度、淋巴结是否转移，更重要的是能准确分辨直肠系膜、筋膜是否受累。"},{"t":"p","x":"⑤胸腹盆增强CT：主要用于评估多发于肝、肺的远处转移。"},{"t":"p","x":"多数大于1cm的肝、肺病变可以通过CT准确判定是否转移。盆腔CT对软组织的分辨能力低于MRI。"},{"t":"p","x":"⑥全身PET-CT：主要被推荐用于已有淋巴结转移或术后检查提示可疑复发、转移的结直肠癌。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表11-12)"},{"t":"table","img":"img/tab/t1112.jpg","cap":"表11-12直肠癌与直肠息肉、溃疡性结肠炎、痢疾的鉴别"}],"entries":["e0814"]},{"title":"治疗","blocks":[{"t":"p","x":"本病一经诊断，应及早采取根治性手术治疗。中医辨证论治具有重要的治疗作用，尤其是放、化疗及术后、中晚期患者采用中医药治疗，能有效地提高5年生存率，降低放、化疗的毒副作用，增强机体抗病能力、改善生活质量，提高临床远期疗效。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s110901","name":"湿热蕴结证","clinic":"肛门坠胀，便次增多、大便带血，色泽暗红，或夹黏液，或下痢赤白，里急后重；舌红，苔黄腻，脉滑数","treat":"清热利湿","formula":"槐角地榆丸加减","formulaNames":["槐角地榆丸"]},{"t":"syn","sid":"s110902","name":"气滞血瘀证","clinic":"肛周肿物隆起，触之坚硬如石，疼痛拒按，或大便带血，色紫暗，里急后重，排便困难；舌紫暗，脉涩","treat":"行气活血","formula":"桃红四物汤合失笑散加减","formulaNames":["桃红四物汤","失笑散"]},{"t":"syn","sid":"s110903","name":"气阴两虚证","clinic":"面色无华，消瘦乏力，便溏或排便困难，便中带血，色紫暗，肛门坠胀；或伴心烦口干，夜间盗汗；舌红或绛，苔少，脉细弱或细数","treat":"益气养阴，清热解毒","formula":"四君子汤合增液汤加减","formulaNames":["四君子汤","增液汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)灌肠 ①苦参20g，青黛10g，血竭9g，全蝎9g，枯矾6g，儿茶12g，鸦胆子5g(打碎)。"},{"t":"p","x":"将上方药物加水600mL，煎至200mL左右。从肛门插入肛门管20～30cm深，注药后保留2～3小时。"},{"t":"p","x":"每日1～2次，30日为1个疗程。"},{"t":"p","x":"②生大黄20g，黄柏15g，栀子15g，蒲公英30g，金银花20g，红花15g，苦参20g。"},{"t":"p","x":"方法同上。"},{"t":"p","x":"③败酱草、白花蛇舌草等浓煎保留灌肠，每日2次，每次40mL。"},{"t":"p","x":"(2)敷药肛管癌溃烂者，外敷九华膏或黄连膏等。"},{"t":"p","x":"3.手术疗法对能切除的肛管直肠癌应尽早行根治性切除术。适用于癌肿局限在直肠壁或肛管，或有区域淋巴结转移的患者。"},{"t":"p","x":"已侵犯的子宫、阴道壁也可以同时切除。当晚期肛管直肠癌已广泛转移，不能行根治性手术时，可行乙状结肠造瘘术，以解除梗阻，减轻患者痛苦。"},{"t":"p","x":"常用的手术方式有局部切除术、Dixon术、APR术(Miles术)、Hartmann术等(图11-47～图11-49)。"},{"t":"img","src":"img/fig/f1147.jpg","alt":"图11-47 Dixon术的切除范围"},{"t":"img","src":"img/fig/f1148.jpg","alt":"图11-48 APR术(Miles术)的切除范围"},{"t":"img","src":"img/fig/f1149.jpg","alt":"图11-49 Hartmann术的切除范图"}]},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)新辅助治疗对于T期或淋巴结转移的直肠癌患者，都应该进行术前的新辅助治疗。"},{"t":"p","x":"该治疗可以降低肿瘤的分期、提高RO切除率；提高保肛率；减少术中肿瘤播散的风险；"},{"t":"p","x":"评估肿瘤对治疗的敏感性。"},{"t":"p","x":"(2)辅助治疗直肠癌辅助治疗的核心目的有三个：①降低局部复发风险：针对手术无法完全清除的、可能残留在肠壁周围或区域淋巴结内的微小肿瘤病灶，通过辅助治疗(如放疗、化疗)进一步杀灭，减少肿瘤在原发部位附近再次生长的概率。"},{"t":"p","x":"②降低远处转移风险：清除术前可能已通过血液、淋巴系统扩散到身体其他器官(如肝、肺)但影像学无法检测到的“微小转移灶”，避免这些隐匿病灶发展为临床可见的远处转移瘤。"},{"t":"p","x":"③改善长期生存预后：通过上述两点，辅助治疗可显著提升患者的无病生存率和总生存率；"},{"t":"p","x":"尤其对术前分期较晚、术后病理提示有高危因素(如切缘阳性、淋巴结清扫不足)的患者，是改善预后的关键手段。"},{"t":"p","x":"(3)针灸治疗 ①取截根、长强穴，可配三阴交、大肠俞、天枢、足三里。"},{"t":"p","x":"每次分别取主穴及配穴2～3个，取毫针针刺得气后提插捻转，中等强度，留针15～45分钟，隔日1次。"},{"t":"p","x":"②取足三里、三阴交穴。"},{"t":"p","x":"采用国产DBJ-1型微波针灸仪进行微波针灸，每次20分钟，每日1次，10次为1个疗程。"},{"t":"p","x":"③取利尿穴、膀胱穴，可配曲骨、中极、关元、气海、肾俞、次膠等穴。"},{"t":"p","x":"每次取穴2～3个，实证用泻法，虚证用补法。每日1次。"}]}],"entries":["e0815","e0816","e0817","e0818","e0819","e0820"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗肛门部病变，一旦发现肛门不适，肛缘有硬结、出血或肿痛，应及时检查，尽可能做到早期发现，早期治疗。2.40岁以上患者出现排便习惯改变及便血，应尽早检查。"}],"entries":["e0821"]}]},{"id":"d1200","kind":"chapter","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"本章概述","displayName":"泌尿男性生殖系疾病·本章概述","parentId":"","printedPage":248,"pdfPage":263,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"泌尿、男性生殖系统包括泌尿系统(肾、输尿管、膀胱)和男性生殖系统(睾丸、附睾、输精管、前列腺、精囊、阴囊、阴茎等)及两者的同一通道即尿道。泌尿系统功能的外在表现，中医学称为溺窍；"},{"t":"p","x":"男性生殖系统功能的外在表现，中医学称为精窍。精、溺二窍由肾所主，但与其他脏腑的生理功能亦密切相关。"},{"t":"p","x":"《素问·上古天真论》载：“肾者主水，受五脏六腑之精而藏之，故五脏盛乃能泻。”《证治汇补·遗精》曰：“遗精之主宰在心，精之藏制在肾。"},{"t":"p","x":"《素问·灵兰秘典论》曰：“三焦者，决渎之官，水道出焉。膀胱者，州都之官，津液藏焉，气化则能出矣。"},{"t":"p","x":"《素问·经脉别论》云：“饮入于胃，游溢精气，上输于脾；脾气散精，上归于肺；"},{"t":"p","x":"通调水道，下输膀胱。”由此可见，精与溺的生成和排泄均与五脏六腑有关。"},{"t":"p","x":"其功能如此，其形态(即前阴各部)亦与脏腑相关，《外科真诠·治疮疡要诀》将其划分为：玉茎(阴茎)属肝；马口(尿道)属小肠；阴囊属肝；"},{"t":"p","x":"肾子(附睾、睾丸)属肾；子系(精索)属肝。"}],"entries":["e0822"]},{"title":"病因病理","blocks":[{"t":"p","x":"泌尿男性生殖系疾病的发生是因各种致病因素导致脏腑功能失常而引起，同时与风、寒、暑、湿、燥、火六淫及疫疠之毒密切相关；而男子以精为本，在外感六淫中，湿、热、寒邪更易与精气相搏而致病。"},{"t":"h","lv":3,"x":"1.脏腑功能失常"},{"t":"p","x":"(1)心心为君主之官，为君火，主血脉而藏神，开窍于舌，与小肠相表里，易受火邪扰动。"},{"t":"p","x":"心火亢盛，移热小肠，表现为心烦舌糜，小便短赤，发为热淋；心主血脉，如心火亢盛，灼伤血络，迫血妄行，下出阴窍，则为血淋、尿血；"},{"t":"p","x":"肾精需心火温煦，若心火下劫，肾水妄动，或心火亢旺，肾水不济，心肾不交，可出现精浊、血精等。"},{"t":"p","x":"(2)肝肝藏血，主疏泄，又主筋，筋得其养乃能运动有力，玉茎为宗筋所聚，若肝郁疏泄失职，筋失其养，可发生阳痿；"},{"t":"p","x":"气郁化火，肝火亢盛，灼伤肾水而使肝木失养，疏泄失司，精窍之道被阻而致不能射精。肝脉络阴器，肝失疏泄，气滞血瘀，水液不行，湿热浊精阻于肝经，可致子痈、囊痈、水疝、癃闭等。"},{"t":"p","x":"(3)脾脾为后天之本，主运化，为气血生化之源。"},{"t":"p","x":"若脾虚不能将水谷精微输布于各脏腑器官，致使其功能失调，表现在泌尿生殖方面为遗尿、遗精、阳痿、不育等。脾虚不能运化水液，水液积聚外肾，可形成水疝；"},{"t":"p","x":"湿聚成痰，滞于阴茎，则发为阴茎痰核；蓄于膀胱，则为癃闭。"},{"t":"p","x":"脾虚不摄，水精下流，则发为尿浊；脾不统血，可致血尿。"},{"t":"p","x":"(4)肺肺主气，司呼吸，主宣降，为水之上源，使水道通调而下行膀胱。"},{"t":"p","x":"若肺失宣降，影响水液代谢，水道不利，可发生癃闭。肺气虚弱，不能制下，可发生小便失禁或遗尿。"},{"t":"p","x":"(5)肾肾藏精，主生殖，为水之下源，与膀胱相表里，开窍于二阴。"},{"t":"p","x":"肾精亏损，阴虚生内热，热扰精室，可致遗精、早泄；相火下移膀胱，可发为热淋、血淋；"},{"t":"p","x":"火扰精室可发为精浊，灼伤血络可出现血精、尿血；灼津为痰，聚于前阴，发为阴茎痰核或子痰；"},{"t":"p","x":"肾阳不足，精关不固，可致白浊、遗精、早泄；肾精亏虚，可引起不育；"},{"t":"p","x":"阳虚宗筋痿而不用，可发生阳痿；肾阳虚衰，膀胱气化失司，开合失常，可引起癃闭、尿失禁等。"},{"t":"p","x":"故精、溺二窍之生理病理与肾和膀胱的关系最为密切。"},{"t":"h","lv":3,"x":"2.外感六淫及疫毒"},{"t":"p","x":"(1)湿湿为阴邪，其性重浊黏滞。"},{"t":"p","x":"湿邪致病，使气机升降失调，经络阻滞不畅而精气受阻。湿邪易抑遏和损伤阳气，阳气被伤则精亦受损。"},{"t":"p","x":"湿性重浊、易伤人下焦，故《素问·太阴阳明论》云：“伤于湿者，下先受之。"},{"t":"p","x":"《灵枢·百病始生》云：“清湿则伤下。”男性生殖泌尿器官位于人体下部，病变脏腑多涉及肝、肾、膀胱及其经络循行之处。"},{"t":"p","x":"湿邪入侵，依来源之不同，又分内湿、外湿、寒湿、疫湿、湿热等。外湿多在人体正气先虚的前提下，由外界工作、居住等环境潮湿所致；"},{"t":"p","x":"内湿多因素体脾虚、又嗜食肥甘，过度疲劳、忧思伤脾，致脾失健运而湿由内生。湿邪久郁，遇阳盛之体则转化为湿热、湿热下注蕴结膀胱、气化不行，则成淋证、癃闭；"},{"t":"p","x":"湿热遏久，转成湿毒，下注前阴可发疳疮、肾囊风；如遇阴盛之体，则从寒化而为寒湿，可致寒疝；"},{"t":"p","x":"脾阳失运，聚液成痰，湿仍结于前阴，可致精索囊肿、阴茎硬结；结于乳房则成乳疬等。"},{"t":"p","x":"湿邪之为病，其临证多以阴部重坠，小腹、腰低胀满，小便浑浊、不利、阴潮湿、舌苔腻，脉濡滑为其特征。"},{"t":"p","x":"(2)热热与火常互称，热为火之渐，火为热之极。"},{"t":"p","x":"热为阳邪，其性炎上，易伤阴精，易损脉络而动血、耗血。《素问·阴阳应象大论》云：“热胜则肿。"},{"t":"p","x":"《医学启源·六气病解·淋》注：“小便涩痛，热客膀胱，郁结而不能渗泄故也。”《杂病源流犀烛·前阴后阴病源流》云：“一曰阴纵，亦名阴挺，由前阴受热，则玉茎挺长不收，或肿胀而痿。"},{"t":"p","x":"热邪入侵，依来源之不同，可分为外热、内热、实热、虚热、热毒等。外热为外感火热之邪，或感受四时不正之气，化火而致，常见睾丸肿痛、茎中痛痒。"},{"t":"p","x":"内热多因脏腑气血失调，五志化火，热自内生，或过食辛辣刺激之品，或过服温燥助阳药物，耗伤过多阴精阴液而成，内热可影响肝肾、冲任等脏腑和经络，使气血失调而出现阳强、房事茎痛等。"},{"t":"p","x":"实热以局部红肿、痛、淋浊、茎痛、高热、舌红、脉数有力为特点，虚热则以潮热、盗汗、遗精、血精、舌红少苔、脉细数为特点。"},{"t":"p","x":"(3)寒寒为阴邪，易戕伤阳气，其性收引凝滞。"},{"t":"p","x":"《素问·举痛论》云：“寒气客于厥阴之脉，厥阴之脉者，络阴器系于肝，寒气客于脉中，则血泣脉急，故胁肋与少腹相引痛矣。”寒邪入侵，依其来源之不同，又有外寒和内寒之分，肝经之脉循股入毛中，过阴器，抵少腹。"},{"t":"p","x":"外寒为寒邪犯于肝脉，使经脉气血凝滞，运行受阻，失于通畅，则见少腹阴冷胀痛、睾丸坠胀或阴囊湿冷、腹外疝、阳缩、舌润滑苔白、脉沉弦或迟。"},{"t":"p","x":"内寒多为男子素体阳虚，加之生活不节、过食生冷，而致气虚阳微，脏腑虚寒，生化功能不足，而出现阳痿、阳缩遗精、不射精或精液清冷等病证。"},{"t":"p","x":"(4)疫疫疠是一种易于传染扩散的病邪，常易化腐伤肉，成脓溃烂，多因男女不洁净之性交或外生殖器不洁而感染成疾。"},{"t":"p","x":"疫疠致病，传染性强，且病证较为相似。《本草纲目·草部》云：“男女淫猥，湿热之邪积畜既深，发为毒疮，遂致互相传染。"},{"t":"p","x":"临床常见梅毒、淋病、下疳、尖锐湿疣及子痈、囊痈等。以下体灼热、瘙痒、灼痛，阴茎溃烂、红肿、疮疹、流脓，脉数，苔黄腻等为特征。"}],"entries":["e0823"]},{"title":"辨证论治","blocks":[{"t":"p","x":"泌尿、男性生殖系疾病种类较多，证候表现有异有同。仅将其常见证型及治法归纳如下。"},{"t":"p","x":"1.湿热下注证湿热邪毒下注，蕴结二窍，则变生诸疾。本证主要表现为尿频，尿急，茎中热痛，尿液黄赤，血淋，白浊，阴囊红肿热痛，附睾、睾丸肿痛，囊内积液，外阴多汗味臊等。"},{"t":"p","x":"治法为清利湿热。溺窍异常多为膀胱湿热，用八正散、导赤散等加减；"},{"t":"p","x":"精窍异常多为脾肾湿热，用程氏萆薢分清饮加减；肝经湿热用龙胆泻肝汤加减。"},{"t":"p","x":"2.气血瘀滞证多见于病久之后，主要表现为睾丸硬结，少腹、会阴、睾丸胀痛或刺痛，排尿困难或闭塞不通，或尿中有血块等。治法为行气活血。"},{"t":"p","x":"气滞为主者，用橘核丸、枸橘汤加减；血瘀为主者，用代抵当丸、活血散瘀汤加减。3.浊痰凝结证浊痰结于前阴，表现为附睾慢性肿块或阴茎结节，皮色不变，不痛或微痛。"},{"t":"p","x":"若浊痰化热，局部可发红发热，伴有疼痛，或化脓破溃；浊痰滞于溺窍，可出现排尿淋沥不畅，尿线变细；"},{"t":"p","x":"浊痰阻于精窍，可不射精。治法为化痰散结。"},{"t":"p","x":"寒痰凝结者，当温阳化痰散结，用阳和汤、橘核丸、化坚二陈丸加减；浊痰化热者、当清热化痰散结。用消核丸加减；"},{"t":"p","x":"精窍痰凝者，当通窍化痰散结，用苍附导痰汤加减。4.肾阴不足证肾阴不足，相火偏亢，常表现为腰膝酸痛、头目眩晕、盗汗失眠、五心烦热、血精、精浊等。"},{"t":"p","x":"治法为滋补肾阴、常用方剂为六味地黄丸、知柏地黄丸、大补阴丸等。5.肾阳虚衰证肾阳不足，气化失司，常表现为形寒肢冷、腰膝酸痛、小便清长、夜尿频多、阳痿不举、精冷不育等。"},{"t":"p","x":"治法为温补肾阳，常用方剂为金匮肾气丸、右归丸、济生肾气丸等。另外，尚有脾肾两虚、中气下陷、心火炽盛、肺失宣降、寒湿凝聚、肝郁气滞、心肾不交等证，详见各节。"}],"entries":["e0824"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.科学管理，避免过劳与刺激，节制性事，戒除不良习惯，避免物理与化学损伤。2.疏导压力，维护心理健康，主动情绪管理，积极释放压力，建立治疗信心。"},{"t":"p","x":"3.培养健康生活习惯，均衡营养，充足饮水，规律作息和适度运动。"}],"entries":["e0825"]}]},{"id":"d1201","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"子痈","displayName":"子痈","parentId":"","printedPage":250,"pdfPage":265,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"子痈是指睾丸及附睾的化脓性疾病。"},{"t":"p","x":"中医学称睾丸和附睾为“肾子”，故以名之。因睾丸和附睾解剖位置毗邻，炎症往往相互影响。"},{"t":"p","x":"临证中分为急性子痈与慢性子痈，以睾丸或附睾肿胀疼痛为特点。本病相当于西医学的急、慢性附睾炎或睾丸炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.湿热下注外感六淫或过食辛辣炙煿，湿热内生，或房事不洁，外染湿热秽毒，或跌仆闪挫，肾子受损，经络阻隔，气血凝滞，郁久化热，发为本病。"},{"t":"p","x":"2.气滞痰凝郁怒伤肝，情志不畅，肝郁气结，经脉不利，血瘀痰凝，结于肾子，则为慢性子痈。西医学认为本病病因复杂，其病因包括感染性、非感染性、医源性、特发性、精索静脉曲张等。"},{"t":"p","x":"发病机制主要是致炎因子、病原菌、理化因素等引起血-附睾屏障和血-睾屏障的破坏。"}],"entries":["e0826","e0827"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"急性子痈：病程一般小于6周，发病急，多为单侧，附睾或睾丸肿痛，突然发作，疼痛程度不一，行动或站立时加重。疼痛可沿输精管放射至腹股沟及下腹部，伴有恶寒发热、口渴欲饮、尿黄便秘等症状。"},{"t":"p","x":"附睾可触及肿块，触痛明显。化脓后，若波及阴囊，可见阴囊红肿热痛，可有波动感。"},{"t":"p","x":"溃破或切开引流后，脓出毒泄，症状消退迅速，疮口容易愈合。慢性子痈：临床较多见，病程多在3个月以上。"},{"t":"p","x":"患者常有阴囊部隐痛、发胀、下坠感，疼痛可放射至下腹部及同侧大腿根部，可有急性子痈发作史。检查可触及附睾增大、变硬，伴轻度压痛，同侧输精管增粗。"},{"t":"p","x":"根据致病因素的不同，慢性子痈的症状差异较大。其中布鲁菌并发附睾炎大多累及单侧附睾，除了表现发热、多汗、乏力等布鲁菌病常见症状外，还可出现不同程度的阴囊疼痛、红肿、下腹疼痛及泌尿系感染症状；"},{"t":"p","x":"性传播疾病所致附睾炎患者可表现为尿道炎症状或尿道分泌物增多，也可无明显临床症状。"},{"t":"p","x":"(2)辅助检查尿常规和尿培养应作为本病基本的检查项目。"},{"t":"p","x":"急性子痈者，血白细胞总数增高，尿中可有白细胞。尿液或尿道分泌物可做细菌培养或淋球菌、支原体、衣原体检验。"},{"t":"p","x":"C反应蛋白、红细胞沉降率升高可支持诊断。阴囊超声对附睾炎的诊断比单纯尿液分析更准确，超声多提示患侧附睾体积增大，以头尾部增大明显，回声减低或增高，可伴有睾丸体积增大，实质回声不均匀，患侧附睾、睾丸内高血流信号。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-1)"},{"t":"table","img":"img/tab/t1201.jpg","cap":"表12-1子痈与卵子瘟、子痰的鉴别"}],"entries":["e0828"]},{"title":"治疗","blocks":[{"t":"p","x":"急性子痈在辨证论治的同时，可配合使用抗生素；慢性子痈以中医药治疗为主，可显著缓解临床症状，减少并发症。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120101","name":"湿热下注证","clinic":"多见于成年人，发病突然。睾丸或附睾肿大疼痛，阴囊皮肤红肿，焮热疼痛，少腹抽痛，局部触痛明显，脓肿形成时按之应指；伴恶寒发热；苔黄腻，脉滑数","treat":"清热利湿，解毒消肿","formula":"枸橘汤或龙胆泻肝汤加减。阴囊水肿明显者，加车前子、川木通；已成脓者，加透脓散；疼痛剧烈者，加延胡索、川楝子","formulaNames":["枸橘汤","龙胆泻肝汤"]},{"t":"syn","sid":"s120102","name":"气滞痰凝证","clinic":"附睾结节，子系粗肿，轻微触痛，或牵引少腹不适；多无全身症状；舌淡或有瘀斑，苔薄白或腻，脉弦滑","treat":"疏肝理气，化痰散结","formula":"橘核丸加减。结节难消者，加三棱、莪术、夏枯草；阴囊积液者，加茯苓、泽泻","formulaNames":["橘核丸"]},{"t":"p","x":"舌淡或有瘀斑，苔薄白或腻，脉弦滑。治法：疏肝理气，化痰散结。"},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)急性子痈未成脓者可用金黄散或玉露散水调匀冷敷；"},{"t":"p","x":"病灶有波动感，穿刺有脓者，应及时切开引流；脓稠、腐肉较多时，可选用九一丹或八二丹药线引流；"},{"t":"p","x":"脓液已净者可外用生肌白玉膏。"},{"t":"p","x":"(2)慢性子痈葱归溻肿汤坐浴或冲和膏外敷。"},{"t":"p","x":"3.其他疗法急性子痈主张早期应用抗生素，在药敏试验未获结果前，可选用抗菌谱较广的抗生素。对于疼痛明显的患者，可应用非甾体抗炎药止痛治疗。"},{"t":"p","x":"慢性子痈保守治疗无效且局部疼痛剧烈，反复发作影响工作生活者，在充分评估生育因素的前提下，可考虑行附睾切除术。此外，超短波理疗和直流中药离子导入疗法等物理疗法亦可酌情使用。"}]}],"entries":["e0829","e0830","e0831","e0832"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.外生殖器有包茎、龟头炎、尿道狭窄等，应及时治疗。2.急性子痈患者应卧床休息并兜起阴囊。"},{"t":"p","x":"切开排脓者要注意引流通畅。"}],"entries":["e0833"]}]},{"id":"d1202","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"囊痈","displayName":"囊痈","parentId":"","printedPage":252,"pdfPage":267,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"囊痈是发于阴囊部位的急性化脓性疾病。"},{"t":"p","x":"其临床特点是阴囊红肿疼痛，皮紧光亮，寒热交作，形如瓢状。《外科大成》云：“夫褒痈者，阴囊红热肿痛也。"},{"t":"p","x":"本病相当于西医学的阴囊蜂窝织炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"多因坐卧湿地，外感湿毒，或囊痒搔抓，外伤染毒，或饮食不节，过食膏粱厚味，脾失健运，湿热内生，湿热毒邪阻于肝肾之络，致使阴囊部气血壅滞，乃成痈肿。西医学认为，本病是由于各种原因导致阴囊皮肤及肉膜的弥漫性化脓性炎症。"},{"t":"p","x":"由于阴囊皮肤皱襞较多，潮湿温暖，易藏污纳垢，致细菌隐藏繁殖，或因外伤致阴囊部皮肤破损，细菌侵入，导致阴囊炎症，加之阴囊组织疏松，炎症难以局限，往往累及整个阴囊。"},{"t":"p","x":"且本病病原菌多为金黄色葡萄球菌，少数为溶血性链球菌、厌氧菌或腐败性细菌。"}],"entries":["e0834","e0835"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现初起阴囊部出现红肿、灼热，压痛明显，腹股沟淋巴结肿大。"},{"t":"p","x":"阴囊肿胀进展较快，甚则肿大如瓢，坠胀疼痛。可伴有发热畏寒、口干、喜冷饮、小便赤热、大便干结等全身症状。"},{"t":"p","x":"若治疗不及时，身热不退，肿痛不减，可致成脓。"},{"t":"p","x":"(2)辅助检查血常规检查白细胞总数及中性粒细胞比例增高。"},{"t":"p","x":"C反应蛋白升高及血沉速度加快。阴囊超声显示阴囊皮下组织内存在液性暗区。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-2)"},{"t":"table","img":"img/tab/t1202.jpg","cap":"表12-2囊痈与子痈、脱囊的鉴别"}],"entries":["e0836"]},{"title":"治疗","blocks":[{"t":"p","x":"多以清热利湿为主。脓成后佐以透脓之品。"},{"t":"p","x":"早期宜配合抗生素治疗，成脓后必要时手术切开引流。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120201","name":"湿热下注证","clinic":"阴囊红肿焮热，坠胀疼痛，拒按，酿脓时局部胀痛、跳痛，指压有应指感；伴发热，口干喜冷饮，小便赤热；舌红，苔黄腻或黄燥，脉弦数或紧数","treat":"清热利湿，解毒消肿","formula":"龙胆泻肝汤或泻热汤加减。未成脓、疼痛明显者，加川楝子、延胡索；发热较甚者，加虎杖、蒲公英。已成脓者、加天花粉、白芷、皂角刺。溃脓后，加黄芪、川芎、当归","formulaNames":["龙胆泻肝汤","泻热汤"]},{"t":"p","x":"溃脓后，加黄芪、川芎、当归。2.外治疗法未成脓者，用玉露散、金黄散或双柏散凉水调糊冷敷。"},{"t":"p","x":"若红肿范围较大者，用三黄汤(大黄、黄柏、黄芩)煎汤冷湿敷，适当频换敷料，保持冷湿，以消肿止痛。亦可用50%芒硝溶液湿敷患处。"},{"t":"p","x":"已成脓者、应及时切开引流，注意避免损伤鞘膜与睾丸。"}],"entries":["e0837","e0838"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.注意个人卫生，勤沐浴，勤换贴身衣物，夏季尤宜。2.及时处理阴囊部外伤，注意保持阴囊部的清洁及干燥。"},{"t":"p","x":"3.勿饮酒，忌食鱼腥和辛辣炙煿食物。"}],"entries":["e0839"]}]},{"id":"d1203","kind":"attach","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"脱囊","displayName":"囊痈·脱囊","parentId":"d1202","printedPage":253,"pdfPage":268,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"脱囊，又称“囊脱”“阴囊毒”“囊发”等，是指突然发生在阴囊的急性炎性坏疽。临床起病急，阴囊红肿、紫黑，迅速溃烂，甚则可整个阴囊皮肤腐脱，睾丸外露。"},{"t":"p","x":"本病发病多因卫生条件差导致阴囊皮肤不洁，或阴囊湿疹因抓挠损伤，或外伤阴囊，感受湿热火毒、致使阴囊气血壅遏，肉腐血败，久则耗损气血，以致气阴两虚。初起阴囊肿胀，阴囊皮肤发红发亮，自觉阴囊灼热剧痛，触之有捻发音。"},{"t":"p","x":"1～2天后，阴囊皮肤紧张湿裂，其色紫黑，阴囊迅速溃烂，流血样污水或脓液，最后腐肉脱落，睾丸外露。血常规检查可见白细胞及中性粒细胞增高，创面细胞培养可有溶血性链球菌、金黄色葡萄球菌、大肠杆菌、厌氧链球菌等。"},{"t":"p","x":"X线可发现阴囊软组织有气体。B超显示阴囊壁甚至阴茎皮肤弥漫性水肿增厚，睾丸周围积液，阴囊壁内有气体，但睾丸、附睾正常。"},{"t":"p","x":"本病常需与囊痈、阴囊急性丹毒等相鉴别。治疗本病，初期当清热利湿、解毒消肿，用龙胆泻肝汤加减；"},{"t":"p","x":"中期当清热泻火、凉血解毒、托毒透脓，用清瘟败毒饮加透脓散加减；后期当益气养阴、清解余毒，用益气养阴汤加减。"},{"t":"p","x":"本病凶险，应中西医结合治疗。一旦出现坏死，应立即手术。"},{"t":"p","x":"平素应少食肥甘厚味，清淡饮食，戒烟酒，防止湿热内生。同时注意避免阴囊外伤，及时治疗阴囊皮肤疾病如阴囊湿疹、股癣、生殖器疱疹等原发病，有效防止继发感染。"}],"entries":["e0840"]}]},{"id":"d1204","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"子痰","displayName":"子痰","parentId":"","printedPage":253,"pdfPage":268,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"子痰是发于肾子的疮痨性疾病。"},{"t":"p","x":"其临床特点是附睾尾部有慢性硬结，逐渐增大，形成脓肿，溃破后脓液稀薄如痰，并夹有败絮样物质，易成窦道，经久不愈。中医文献称之为“穿囊漏”。"},{"t":"p","x":"本病相当于西医学的附睾结核。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"因肝肾亏损，脉络空虚，浊痰乘虚下注，结于肾子；或阴虚内热，相火偏旺，灼津为痰，阻于经络，痰瘀互结而成。"},{"t":"p","x":"抑或肾阳不足，命门火衰，不能温煦经脉，致寒痰凝滞于下。浊痰日久，郁而化热，热胜肉腐可成脓。"},{"t":"p","x":"若脓水淋漓，病久不愈，阴损及阳，可出现阴阳两虚、气血两亏之候。西医学认为，本病为结核杆菌感染所致，多继发于身体其他部位的结核病灶。"},{"t":"p","x":"病变一般表现为附睾尾部出现肉芽肿性炎症，肉芽肿中心因缺血导致凝固性坏死，质地类似奶酪。故其主要病理改变为干酪样坏死及纤维化。"},{"t":"p","x":"脓肿渐大溃破穿透阴囊皮肤，形成经久不愈的窦道或瘘管。结核侵犯输精管亦可导致其管壁增厚，质地变硬变粗，呈串珠状改变。"}],"entries":["e0841","e0842"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多发于中青年人，以20～40岁者居多。"},{"t":"p","x":"初起自觉阴囊坠胀，附睾尾部有不规则的局限性结节，质硬，触痛不明显，结节常与阴囊皮肤粘连。日久结节逐渐增大，可形成脓肿，溃破后脓液清稀，或夹有豆腐渣样絮状物，易反复发作，形成经久不愈的窦道。"},{"t":"p","x":"输精管增粗变硬，呈串珠状。常有五心烦热、午后潮热、盗汗、倦怠乏力等全身症状。"},{"t":"p","x":"一般呈慢性过程，少数急性发作。多有泌尿系统或其他系统的结核病史。"},{"t":"p","x":"(2)辅助检查尿常规检查可有红细胞、白细胞及脓细胞，红细胞沉降率多增高。"},{"t":"p","x":"脓液培养有结核杆菌生长。阴囊超声提示附睾尾部肿大，内部回声欠均，见低回声结节或钙化灶，后期出现液性暗区。"},{"t":"p","x":"亦可见明显的输精管串珠样改变。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-3)"},{"t":"table","img":"img/tab/t1203.jpg","cap":"表12-3子痰与慢性子痈、精液囊肿的鉴别"}],"entries":["e0843"]},{"title":"治疗","blocks":[{"t":"p","x":"“扶正”与“祛邪”相结合，以化痰软坚散结贯穿始终，分期辨证论治。同时应用西药抗结核治疗6个月以上。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120401","name":"浊痰凝结证","clinic":"见于初起硬结期。肾子处坠胀不适，附睾硬结，子系呈串珠状肿硬；无明显全身症状；舌淡，苔薄，脉滑","treat":"温经通络，化痰散结","formula":"阳和汤加减，配服小金丹。疼痛较甚者，加延胡索、没药；畏寒怕冷，阳痿者，加淫羊藿、肉苁蓉","formulaNames":["阳和汤","配服小金丹"]},{"t":"p","x":"肾子处坠胀不适，附睾硬结，子系呈串珠状肿硬；无明显全身症状；舌淡，苔薄，脉滑。治法：温经通络，化痰散结。"},{"t":"syn","sid":"s120402","name":"阴虚内热证","clinic":"见于中期成脓期。病程日久，肾子硬结逐渐增大并与阴囊皮肤粘连，阴囊红肿疼痛，触之可有应指感；伴低热，盗汗，倦怠；舌红，少苔，脉细数","treat":"养阴清热，除湿化痰，佐以透脓解毒","formula":"滋阴除湿汤合透脓散加减。阴虚火旺者，加牡丹皮、女贞子、墨旱莲等；乏力头晕，脓出不畅者、加皂角刺、黄芪等；口渴较甚者，加贝母、天花粉、黄芩、地骨皮等","formulaNames":["滋阴除湿汤","透脓散"]},{"t":"p","x":"舌红，少苔，脉细数。治法：养阴清热，除湿化痰，佐以透脓解毒。"},{"t":"syn","sid":"s120403","name":"气血两亏证","clinic":"见于后期溃脓期。脓肿破溃，脓液稀薄，夹有败絮样物质，疮口凹陷，形成漏管，反复发作，经久不愈；虚热不退、面色无华，腰膝酸软；舌淡，苔白，脉沉细无力","treat":"益气养血，化痰消肿","formula":"十全大补汤加减，兼服小金丹。脓肿破溃，脓液稀薄、淋漓不尽者，加用托里消毒散","formulaNames":["十全大补汤","小金丹"]},{"t":"p","x":"脓肿破溃，脓液稀薄、淋漓不尽者，加用托里消毒散。2.外治疗法未成脓者宜消肿散结，外敷冲和膏，每天1次；"},{"t":"p","x":"已成脓者及时切开引流；窦道形成者可选用腐蚀平胬药物，如五五丹及七三丹制成药线或药条，外盖黄连膏。"},{"t":"p","x":"脓已尽，疮口肉芽新鲜者，可用生肌散外掺，外盖生肌玉红膏纱布。3.其他疗法积极应用抗结核治疗，常用药物有异烟肼、利福平、吡啖酰胺、乙胺丁醇等，一般主张遵循联合用药、规范化、足疗程的原则。"},{"t":"p","x":"规范化用药后，结核病灶未能得到有效控制，应考虑手术治疗，行附睾切除术或附睾病灶切除术，尽可能保留睾丸且术后仍需抗结核治疗半年至1年。"}],"entries":["e0844","e0845","e0846","e0847"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.重视结核病的预防与调护。2.如阴囊坠胀疼痛明显者，可用阴囊托托起阴囊，以缓解症状。"}],"entries":["e0848"]}]},{"id":"d1205","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"阴茎痰核","displayName":"阴茎痰核","parentId":"","printedPage":255,"pdfPage":270,"syndromeCount":1,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"阴茎痰核是指阴茎海绵体白膜发生纤维化硬结的一种疾病。"},{"t":"p","x":"其临床特点是阴茎背侧可触及条索或斑块状结节，阴茎勃起时伴有弯曲或疼痛。《外科理例》中的囊痈医案中，有“一弱人茎根结核如大豆许，劳则肿痛”的记载，类似本病。"},{"t":"p","x":"本病相当于西医学的阴茎硬结症。75%以上患者于45～65岁发病，全球的患病率为0.4%～9%，发病率随年龄的增高而增加。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"阴茎为宗筋所聚，太阳、阳明之所合，多气多血之络。阴茎痰核的病位在阴茎，涉及肝、脾、肾等脏。"},{"t":"p","x":"病性以实证居多，或虚实互兼。病因病机比较复杂，或气滞血瘀，或饮食劳倦，脾失健运，或禀赋不足，肾虚精弱，或外伤茎络。"},{"t":"p","x":"其基本病理变化多为肝郁、脾虚、肾虚、痰瘀凝聚宗筋。痰浊凝结情志不畅，肝气郁结，气机失调，聚液成痰。"},{"t":"p","x":"或长期饮食不节，过食肥甘厚味，脾失健运，湿聚成痰。或久居潮湿之地，外感寒湿之邪，脾为湿困，酿生痰浊。"},{"t":"p","x":"或先天禀赋不足，肾虚精弱，水湿不行，聚湿生痰。或外伤瘀血，伤及茎络，气滞血瘀日久，痰浊内生。"},{"t":"p","x":"痰浊凝聚宗筋，遂生本病。西医学对于阴茎硬结症的病因尚不明确。"},{"t":"p","x":"目前认为本病与阴茎部明显或隐性外伤、感染、Dupuytren挛缩、遗传性患病体质、尿道器械操作、高血压、糖尿病、痛风、Paget病、染色体异常、结缔组织病、自身免疫疾病、维生素E缺乏，以及使用β受体阻滞剂等有关。"}],"entries":["e0849","e0850"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"临床表现本病多见于中年男性。阴茎背侧可触及硬结或条索状斑块，无压痛，大小不一、单发或数个不等，发展缓慢，一般不会破溃。"},{"t":"p","x":"阴茎勃起时有疼痛或弯曲变形、严重者可影响性交，甚至引起阳痿。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-4)"},{"t":"table","img":"img/tab/t1204.jpg","cap":"表12-4阴茎痰核与阴茎癌(肾岩)、硬下疳(一期梅毒)、软下疳的鉴别"}],"entries":["e0851"]},{"title":"治疗","blocks":[{"t":"p","x":"本病疗程较长，应内治与外治相结合进行综合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120501","name":"痰浊凝结证","clinic":"阴茎背侧可触及条索状结块，皮色不变，温度正常，无明显压痛，阴茎勃起时可发生弯曲或疼痛；舌淡、边有齿印，苔薄白，脉滑","treat":"温阳通脉，化痰散结","formula":"阳和汤合化坚二陈丸加减。湿浊较重者，加苍术、厚朴；久病脾虚者，加党参、山药","formulaNames":["阳和汤","化坚二陈丸"]},{"t":"p","x":"湿浊较重者，加苍术、厚朴；久病脾虚者，加党参、山药。2.外治疗法阳和解凝膏或黑退消外敷。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)口服药物根据情况可选用糖皮质激素、维生素E、对氨基苯甲酸钾、丙卡巴肼、秋水仙碱、他莫昔芬、辅酶Q0等。"},{"t":"p","x":"(2)硬结区域注射治疗局部注射溶组织梭状芽孢杆菌胶原蛋白酶、干扰素、维书帕米等药物，可抑制组织纤维化，但要防止出血。"},{"t":"p","x":"(3)局部理疗包括低能量体外冲击波治疗、离子导入疗法、机械牵引、放射治疗等，有一定效果。"},{"t":"p","x":"(4)手术治疗适应证包括稳定期患者、阴茎畸形和勃起功能障碍(erectile dysfunction,ED)严重妨碍性交的患者、广泛钙化者、保守治疗无效超过12个月者。"},{"t":"p","x":"手术方法包括阴茎白膜折叠术、硬结切开/切除+补片移植术和阴茎支撑体植入术，应根据勃起硬度和弯曲程度，选择适当的术式。"},{"t":"p","x":"(5)心理治疗阴茎痰核重者，硬结较大，勃起伴有疼痛，患者往往合并焦虑烦躁，医生在药物治疗的同时，应积极进行心理治疗。"}]}],"entries":["e0852","e0853","e0854"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗动脉粥样硬化、高血压、糖尿病等。适当补充各类维生素，尤其是维生素E。"},{"t":"p","x":"忌酒辛辣刺激性食物，养成健康的生活习惯。避免阴茎外伤。"},{"t":"p","x":"2.保持阴茎局部清洁，内裤宜宽松、柔软。外敷药物应固定好部位，避免药物脱落面不能取得疗效。"},{"t":"p","x":"患病后应正确了解病情，避免情志因素诱发性功能障碍。"}],"entries":["e0855"]}]},{"id":"d1206","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"水疝","displayName":"水疝","parentId":"","printedPage":257,"pdfPage":272,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"水疝是指阴囊内有水湿停滞、以不红不热、状如水晶为特征的一种疾病。"},{"t":"p","x":"张子和在《儒门事亲》中首次提出了“水疝”之名：“水疝，其状肾囊肿痛，阴汗时出，或囊肿而状如水晶，或囊痒而燥出黄水，或少腹中按之作水声。得于饮水醉酒，使内过劳，汗出而遇风寒湿之气，聚于囊中，故水多，令人为卒疝。"},{"t":"p","x":"宜以逐水之剂下之。”本病相当于西医学的睾丸或精索鞘膜积液。"},{"t":"p","x":"按病程和起病情况分为急性和慢性两种；按照发病时期又可分为原发性与继发性，原发性以婴幼儿较常见，继发性成年人占多数。"},{"t":"p","x":"单侧多见，好发于中青年。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"水疝的发生多与肝、脾、肾相关。肾主水司气化，脾主运化，肝主疏泄，足厥阴肝经循阴器而行。"},{"t":"p","x":"故肝寒不疏，脾虚不运，肾虚失约，或先天禀赋不足，水液输布失常，循肝经下注于阴器而成水疝；或饮食失节，内生湿热，下注于肾囊而成；或跌仆损伤，血络受阻，水液不行而成。"},{"t":"p","x":"总之，本病发生的关键是阴囊内水液输布异常，蓄水过多。如《圣济总录·阴疝统论》云：“水气盛则津液内结，谓之水癫。”"},{"t":"p","x":"1.脏气虚损小儿先天不足，肾气亏虚，后天脾胃失调，脾肾阳虚，气化失司，水液输布异常，水湿之邪聚于肾囊。《医方考·七疝门》曰：“肾气虚，则湿胜而流坎者势也，故令肾囊肿大如水晶。”"},{"t":"p","x":"2.感受寒湿久坐湿地，或寒冬涉水，或居处潮湿，日久感受寒湿之邪，结于肾囊而病水疝。《疡科心得集·辨囊痈悬痈论》曰：“又有一种水疝，肿痛而皮色光亮，无热无红，内有聚水，宜用针针之，引去水气则安，内服五苓等利湿之药。”"},{"t":"p","x":"3.肝经气滞足厥阴肝经循阴器而行。情志不畅，肝气郁结，疏泄失常，气机不利，水湿内停，聚久化热，湿热之邪循肝经下注于肾囊而致水疝。"},{"t":"p","x":"《儒门事亲·疝本肝经宜通勿塞状》曰：“岂知诸疝，皆归肝经。”4.手术、跌仆损伤或其他因素导致局部脉络受损，血脉瘀阻，水液不行，停聚肾囊而成水疝。"},{"t":"p","x":"西医学认为，本病有先天、后天之分。先天性因素为胎儿时睾丸下降而腹膜鞘状突全部或部分未闭锁；"},{"t":"p","x":"后天因素为睾丸、附睾、精索的感染，外伤，肿瘤或寄生虫病等。其病理是鞘膜之间或邻近器官在病因的作用下，鞘膜腔内渗出过多浆液或吸收障碍，使腔内液体潴留增多。"}],"entries":["e0856","e0857"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现起病缓慢，多为单侧发生，阴囊肿大，可触及光滑而柔软的肿物，呈球形或卵圆形，犹如囊内盛水，一般无压痛。"},{"t":"p","x":"睾丸和附睾可因积液包裹而不易扪及。肿胀严重时，阴囊光亮如水晶，坠胀不适。"},{"t":"p","x":"先天性交通性鞘膜积液平卧时按压肿块可逐渐缩小或消失，站立时又复增大，或少腹部按之有水声。巨大鞘膜积液可使阴囊明显增大，阴茎内陷。"},{"t":"p","x":"(2)辅助检查肿物透光试验可为阳性(若积液为血性、脓性、乳糜性或鞘膜明显增厚者，透光试验可为阴性)，穿刺可抽出积液。"},{"t":"p","x":"若怀疑睾丸肿瘤者，禁忌穿刺。B超检查有助于确定阴囊内肿块是囊性或实性。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-5)"},{"t":"table","img":"img/tab/t1205.jpg","cap":"表12-5水疝与狐疝、精液囊肿、睾丸肿瘤的鉴别"}],"entries":["e0858"]},{"title":"治疗","blocks":[{"t":"p","x":"治以疏肝、健脾、益肾、除湿为主，兼瘀者化瘀，兼热者泄热；并可配合外治、手术等疗法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120601","name":"肾气亏虚证","clinic":"多见于先天性水疝之婴幼儿。阴囊肿大，甚则亮如水晶，不红不热，不痛，睡卧时缩小，站立、哭叫时增大；舌淡，苔薄白，脉细弱","treat":"温肾通阳，化气行水","formula":"济生肾气丸、真武汤加减。少腹胀痛者加乌药、木香、小茴香","formulaNames":["济生肾气丸","真武汤"]},{"t":"syn","sid":"s120602","name":"寒湿凝聚证","clinic":"发病缓慢，阴囊肿胀逐渐加重，久则皮肤顽厚，肿胀严重时阴茎内缩，影响排尿和性交，伴阴囊发凉潮湿、坠胀不适；腰酸乏力；舌淡，苔白腻，脉沉弦","treat":"疏肝理气，祛寒化湿","formula":"陈苓汤、加减导气汤、水疝汤等加减","formulaNames":["陈苓汤","加减导气汤"]},{"t":"syn","sid":"s120603","name":"湿热下注证","clinic":"发病较快，阴囊肿大，皮肤潮湿而红热；伴小便短赤，或有睾丸肿痛及全身发热；舌红，苔黄，脉滑数或弦数","treat":"清热化湿","formula":"大分清饮、清解汤加减","formulaNames":["大分清饮","清解汤"]},{"t":"syn","sid":"s120604","name":"瘀血阻络证","clinic":"多有睾丸损伤或睾丸肿瘤病史。阴囊肿大坠痛，睾丸胀痛，积液可呈红色，透光试验多为阴性；舌紫暗或有瘀点，脉沉涩","treat":"活血化瘀，行气利水","formula":"活血散瘀汤或桃红四物汤加减。痛甚者加延胡索、没药","formulaNames":["活血散瘀汤","桃红四物汤"]},{"t":"p","x":"阴囊肿大坠痛，睾丸胀痛，积液可呈红色，透光试验多为阴性；舌紫暗或有瘀点，脉沉涩。治法：活血化瘀，行气利水。"},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)敷药法湿热型用金黄散，以水调敷患处；寒湿型用回阳玉龙膏，以酒蜜调敷患处。"},{"t":"p","x":"(2)热熨法用小茴香、橘核各100g，研粗末炒热，装布袋内热熨患处，每次20～30分钟，每日2～3次。"},{"t":"p","x":"用于婴儿水疝或继发性水疝属寒证者。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"手术疗法成人鞘膜积液较多，肿块较大，经保守治疗无效时，可采用手术治疗。目前最常用的术式是睾丸鞘膜翻转术或鞘膜切除术。"}]}],"entries":["e0859","e0860","e0861","e0862","e0863","e0864","e0865"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.应清淡饮食，保持心情舒畅，节制房事；应居处于干燥之地，少涉冷水，忌坐湿地；"},{"t":"p","x":"早诊断，早治疗、防止病情加重；积极治疗睾丸炎等原发病；避免外伤。"},{"t":"p","x":"2.在治疗过程中，应注意休息，劳作有度，保持良好心态。可用阴囊托带兜起阴囊，以利积液吸收。"},{"t":"p","x":"外敷中药治疗时，要注意阴囊皮肤的清洁。术后注意局部干燥清洁，避免感染。"}],"entries":["e0866"]}]},{"id":"d1207","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"尿石症","displayName":"尿石症","parentId":"","printedPage":259,"pdfPage":274,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"尿石症、又称泌尿系结石。其临床特点是尿中时夹砂石，小便滞涩不畅或尿不能卒出，痛引少腹或尿时中断，或腰痛牵引少腹，连及外阴、尿中带血。"},{"t":"p","x":"本病男性多于女性，男女发病率约为3:1。我国长江以南为高发地区之一。"},{"t":"p","x":"本病属于中医学“石淋”的范畴。早在《五十二病方》中就有“病已，类石如泔从前出”等类似石淋症状的记载。"},{"t":"p","x":"《诸病源候论·石淋候》中提到“石淋者，淋而出石也。肾主水，水结则化为石，故肾客沙石。"},{"t":"p","x":"肾为热所乘，热则成淋。其状，小便茎中痛，尿不得卒出，时自痛引小腹、膀胱里急，沙石从小便道出，甚者水道塞痛，令闷绝。"},{"t":"p","x":"对石淋的病因病机、症状表现等进行了详细阐述。本病相当于西医学的泌尿系结石，包括上尿路结石(肾结石、输尿管结石)和下尿路结石(膀胱结石和尿道结石)，是泌尿外科十分常见且容易复发的疾病。"},{"t":"p","x":"流行病学调查显示：我国肾结石的发病率约为6.4%；结石的5年复发率最高可达50%,10年复发率甚至可达80%～90%。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多由下焦湿热、气滞血瘀或肾气不足引起，病位在肾、膀胱和溺窍，与肝、脾功能失调密切相关。肾虚为本，湿热、气滞血瘀为标。"},{"t":"p","x":"其基本病理变化多为湿热蕴结、气滞血瘀、肾气不足、肾阴亏虚，导致砂石结聚，阻滞水道。1.湿热蕴结长期饮食不节，嗜食肥甘厚味，损伤脾胃，脾失健运，湿浊内生，郁而化热；"},{"t":"p","x":"或外感湿热之邪，蕴结下焦，注于膀胱。湿热之邪煎熬尿液、结为砂石，发为本病。"},{"t":"p","x":"2.气滞血瘀情志不遂，肝气郁结，疏泄失常，气机不利，尿液排泄不畅，形成砂石。结石阻滞气机，气血运行不畅，瘀血内停。"},{"t":"p","x":"3.肾气不足先天禀赋不足，或年老体衰，或久病耗伤，或房劳过度，导致肾气亏虚。肾主水，肾虚膀胱气化不利，水道不畅，形成砂石。"},{"t":"p","x":"4.肾阴亏虚久病伤阴，或房事不节，损及肾阴，或情志内伤，气郁化火，煎灼真阴，或过服温燥渗利之品，耗伤阴液，导致肾阴不足，虚火内生，煎熬尿液，结为砂石。"},{"t":"p","x":"西医学认为，影响结石形成的因素很多，如年龄、性别、种族、遗传、地理位置、饮食习惯、气候和职业等。身体的代谢异常、尿路的梗阻、感染、异物和药物的使用等，是结石形成的常见病因。"},{"t":"p","x":"结石的成分以草酸钙最常见，磷酸盐、尿酸盐、碳酸盐次之，胱氨酸结石则罕见。通常尿路结石以多种盐类混合形成。"},{"t":"p","x":"草酸钙结石质硬，尿路平片易显影。磷酸钙、磷酸镁铵结石与尿路感染和梗阻有关。"},{"t":"p","x":"尿酸结石与尿酸代谢异常有关，纯尿酸结石不被尿路平片所显影。胱氨酸结石是罕见的家族性遗传性疾病，X光平片亦不显影。"}],"entries":["e0867","e0868"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"上尿路结石：包括肾和输尿管结石。典型的临床症状是突然发作的腰部或腰腹部绞痛和血尿，其程度与结石的部位、大小及移动情况等有关。"},{"t":"p","x":"绞痛发作时疼痛剧烈，患者可出现恶心、呕吐、冷汗、面色苍白等症状。疼痛为阵发性，并沿输尿管向下放射至下腹部、外阴和大腿内侧。"},{"t":"p","x":"检查时肾区有叩击痛，各相应输尿管点可有压痛。结石较大或固定不动时，可无疼痛，或仅为钝痛、胀痛，常伴有肾积水或感染。"},{"t":"p","x":"绞痛发作后出现血尿，多为镜下血尿，肉眼血尿较少，或有排石现象。有时活动后镜下血尿是上尿路结石唯一的临床表现。"},{"t":"p","x":"结石合并感染时，可有尿频、尿急、尿痛；伴发急性肾盂肾炎或肾积脓时、可有发热、畏寒、寒战等全身症状。"},{"t":"p","x":"双侧上尿路结石或孤肾伴输尿管结石引起完全梗阻时，可导致无尿。膀胱结石：典型症状为排尿中断，并引起疼痛，放射至阴茎头和远端尿道。"},{"t":"p","x":"此时患儿常手握阴茎，蹲坐哭叫、经变换体位又可顺利排尿。多数患者平时有排尿不畅、尿频、尿急、尿痛和终末血尿。"},{"t":"p","x":"前列腺增生继发膀胱结石时，排尿困难加重。尿道结石：主要表现为排尿困难、排尿费力，呈点滴状，或出现尿流中断及急性尿潴留。"},{"t":"p","x":"排尿时疼痛明显，可放射至阴茎头部，后尿道结石可伴有会阴和阴囊部疼痛。"},{"t":"p","x":"(2)辅助检查B超检查简便、经济、无创伤，可发现直径2mm以上的结石。"},{"t":"p","x":"但由于受肠道内容物的影响，对输尿管中下段结石的敏感性较低。尿路X线平片(kidney ureter bladder,KUB)可发现90%左右的阳性结石，能够大致确定结石的大小、形态、数量和位置。"},{"t":"p","x":"静脉尿路造影(intravenousurography,IVU)、CT扫描、磁共振等检查都有助于临床诊断。尿常规检查多见有红细胞。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-6)"},{"t":"table","img":"img/tab/t1206.jpg","cap":"表12-6尿石症与胆囊炎、急性阑尾炎(肠痈)的鉴别"}],"entries":["e0869"]},{"title":"治疗","blocks":[{"t":"p","x":"结石直径<6mm且表面光滑，无肾功能损害者，可采用中药排石；对于较大结石可先行体外震波碎石，再配合中药治疗。"},{"t":"p","x":"初起宜宣通清利，日久则配合补肾活血、行气导滞之剂。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120701","name":"湿热蕴结证","clinic":"腰痛或少腹痛，或尿流突然中断，尿频，尿急，尿痛，小便混赤，或为血尿；口干欲饮；舌红，苔黄腻，脉弦数","treat":"清热利湿，通淋排石","formula":"三金排石汤加减。血尿较重者，加琥珀粉、三七粉；疼痛甚者，加延胡索、乳香、没药","formulaNames":["三金排石汤"]},{"t":"syn","sid":"s120702","name":"气血瘀滞证","clinic":"发病急骤，腰腹胀痛或绞痛，疼痛向外阴部放射，尿频，尿急，尿黄或赤；舌暗红或有瘀斑，脉弦或弦数","treat":"理气活血，通淋排石","formula":"金铃子散合石韦散加减。疼痛较重者加桃仁、乳香、没药；血尿较重者，加琥珀粉、三七粉","formulaNames":["金铃子散","石韦散"]},{"t":"syn","sid":"s120703","name":"肾气不足证","clinic":"结石日久，留滞不去，腰部胀痛，时发时止，遇劳加重，疲乏无力，尿少或频数不爽；或面部轻度浮肿；舌淡苔薄，脉细无力","treat":"补肾益气，通淋排石","formula":"济生肾气丸加减","formulaNames":["济生肾气丸"]},{"t":"syn","sid":"s120704","name":"肾阴亏虚证","clinic":"腰腹隐痛、便干尿少；头晕目眩，耳鸣、心烦咽燥，腰膝酸软；舌红苔少，脉细数","treat":"滋阴补肾，通淋排石","formula":"六味地黄丸加减。伴明显湿热者，可合用四妙丸","formulaNames":["六味地黄丸"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)外科治疗根据结石大小及部位选择术式，结石直径<2cm首选体外冲击波碎石术(extracorporeal shock wave lithotripsy,ESWL)和经输尿管镜碎石术(urcteroscopic lithotripsy,URS)；结石直径>2cm首选经皮肾镜取石术(percutaneous nephrolithotomy, PCNL).在极少数情况下，由于解剖异常而无法进行PCNL者可考虑行腹腔镜取石术。"},{"t":"p","x":"(2)非手术治疗"},{"t":"p","x":"饮食疗法：减少能增加尿磷和镁离子水平的食物和维生素补充剂。酸化尿液：可口服氯化铵、硫酸铵、甲硫氨酸或抗坏血酸，将尿液pH维持在6.2以下，以利于溶解残留结石并预防新结石形成。"},{"t":"p","x":"但长期应用存在低钾血症和酸中毒风险，合并代谢性酸中毒者禁用酸化尿液治疗。治疗期间应注意避免使用碱化尿液的药物。"},{"t":"p","x":"脲酶抑制剂治疗：脲酶抑制剂能够抑制尿素水解，降低尿液pH和氨的浓度，在减少结石形成的同时也能增强抗菌药物疗效。对产脲酶的病原微生物导致的感染性结石患者，应在感染严重时联合使用脲酶抑制剂。"},{"t":"p","x":"应注意药物不良反应，包括震颤、皮疹、脱发、胃肠道反应、贫血和静脉炎等。经皮溶石治疗：仅可作为内镜碎石手术的辅助治疗方法，而且需严格控制适应证，避免各类并发症的发生。"}]}],"entries":["e0870","e0871","e0872","e0873","e0874","e0875"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.每天饮水量2000～3000mL，并及时排尿，防止尿液浓缩。若能饮用磁化水则更为理想，可以预防结石发生。"},{"t":"p","x":"2.应调节饮食，合理摄入蛋白质，有助于上尿路结石的预防；避免进食过多钙质，不宜进食过多菠菜、竹笋、苋菜之类富含草酸的食物。"},{"t":"p","x":"痛风患者应少食动物内脏、肥甘之品，避免引起尿酸升高。3.及时治疗尿路感染，解除尿路梗阻。"},{"t":"p","x":"4.常用金钱草、玉米须代茶饮，有助于细小结石排出和预防结石形成。"}],"entries":["e0876"]}]},{"id":"d1208","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"男性不育症","displayName":"男性不育症","parentId":"","printedPage":261,"pdfPage":276,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"男性不育症是指育龄夫妇同居一年以上，性生活正常，未采取任何避孕措施，女方有受孕能力，由于男方原因而致女方不能怀孕的一类疾病。"},{"t":"p","x":"据资料统计，已婚夫妇不能生育者占10%～20%，其中女方原因占50%～60%，男方原因占30%～50%，男女双方的原因占20%～25%。中医古籍称本病为“男子绝子”“无子”“无嗣”等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"中医学认为，男性不育症与肾、心、肝、脾等脏有关，而其中与肾脏关系最为密切。大多由于精少、精弱、死精、无精、精稠、阳痿及不射精等所引起。"},{"t":"p","x":"男性不育症的病机以脏腑亏虚为本，痰饮水湿瘀滞为标。1.禀赋不足肾为先天之本，肾藏精，主生殖，若先天禀受薄弱，肾气不足，命门火衰，导致不育。"},{"t":"p","x":"或元阴不足，精血亏虚，阴虚火旺，相火偏亢，精热黏稠不化；或房劳过度、精血耗散，则精少精弱。"},{"t":"p","x":"上述因素均可导致不育。2.房事劳伤恣情纵欲、房劳过度，或年少无知，频繁手淫，耗气伤精，精室亏虚，导致不育。"},{"t":"p","x":"3.饮食不节嗜饮酒浆、膏粱厚味、伤及脾胃。肾精无以滋养，或水湿痰浊内生，精道不通，阻于精室，生化受阻，均可导致不育。"},{"t":"p","x":"4.七情所伤情志不遂，思虑伤脾、恼怒伤肝，脾失健运，痰湿内生，或肝木失养，宗筋拘急，致精窍之道被阻，肾精不足，气滞血瘀，精液无以生化，导致不育。此外，久病劳倦，气血亏虚，或久病之后，气虚不复，精亏血少，亦导致不育。"},{"t":"p","x":"西医学认为，男性不育症的病因繁多，主要包括精子运动相关基因的突变、染色体异常、线粒体基因缺陷、膜离子通道蛋白改变、精子鞭毛超微结构及功能异常、睾丸及附睾增大、生殖道感染、精索静脉曲张、其他系统疾病(如甲状腺疾病、肥胖等)、环境因素、生活习惯、饮食及心理因素等。"}],"entries":["e0877","e0878"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现对不育症的诊断应从以下两个方面进行。"},{"t":"p","x":"病史：详细了解患者的职业、既往史、个人生活史、婚姻史、性生活情况，以及过去精液检查结果和配偶健康状况等。"},{"t":"p","x":"还应了解有无与放射线、有毒物品接触史及高温作业史，有无腮腺炎并发睾丸炎、精索静脉曲张病史，有无其他慢性病及长期服药情况，是否经常食用棉籽油，有无酗酒、抽烟习惯等。体格检查：检查的重点是全身发育情况和外生殖器。"},{"t":"p","x":"如体型，发育营养状况，胡须、腋毛、阴毛分布，乳房发育等情况；阴茎的发育，睾丸位置及其大小、质地、有无肿物或压痛，附睾、输精管有无结节、压痛或缺如，精索静脉有无曲张等。"},{"t":"p","x":"(2)辅助检查检查内容主要包括精液常规或分析、精液生化测定、精子凝集试验、睾丸活组织检查、输精管道的X线检查、生殖内分泌测定、遗传学检查、精子DNA损伤检测、精子非整倍体检测、精子染色质检测、应用CASA系统评估精子超活化运动、检测精液白细胞介素、评估射精顺序等。"},{"t":"p","x":"WHO(第6版)“夫妇在停止使用避孕措施后12个月内妊娠的男性精液参数分布”见表12-7，精子染色质结构完整性检测结果参考范围及相关临床意义见表12-8。"},{"t":"table","img":"img/tab/t1207.jpg","cap":"表12-7《世界卫生组织人类精液检查与处理实验室手册》(第6版)精液质量主要参数"},{"t":"table","img":"img/tab/t1208.jpg","cap":"表12-8精子染色质结构完整性检测结果参考范围及相关临床意义"},{"t":"p","x":"2. 鉴别诊断应判断不育的原因在男方而不在女方，或男女双方都存在不育的因素，进一步检查并明确病因。"}],"entries":["e0879"]},{"title":"治疗","blocks":[{"t":"p","x":"古方多宗从肾论治。《石室秘录·十六论子嗣》提出治不育六法，曰：“精寒者温其火，气衰者补其气，痰多者消其痰，火盛者补其水，精少者添其精，气郁者舒其气，则男子无子者可以有子，不可徒补其相火也。"},{"t":"p","x":"本病多以补益肾精为本，驱除外邪为辅，主要治则为标本同治。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120801","name":"肾阳虚衰证","clinic":"性欲减退，阳痿早泄，精子数少、成活率低、活动力弱，或射精无力；伴腰酸腿软，疲乏无力，小便清长；舌质淡，苔薄白，脉沉细","treat":"温补肾阳，益肾填精","formula":"金匮肾气丸合五子衍宗丸加减。阳虚症状较甚者，可加肉桂、鹿茸；疲乏无力甚者，加黄芪、西洋参","formulaNames":["金匮肾气丸","五子衍宗丸"]},{"t":"syn","sid":"s120802","name":"肾阴不足证","clinic":"遗精滑泄，精液量少，精子数少，精子活动力弱或精液黏稠不化，畸形精子较多；头晕耳鸣，手足心热，甚则潮热盗汗；舌质红，少苔，脉沉细","treat":"滋补肾阴，益精养血","formula":"左归丸合五子衍宗丸加减。潮热盗汗甚者，加鳖甲、银柴胡","formulaNames":["左归丸","五子衍宗丸"]},{"t":"syn","sid":"s120803","name":"肝郁气滞证","clinic":"性欲低下，阳痿不举，或性交时不能射精，精子稀少、活力下降；精神抑郁，两胁胀痛，嗳气泛酸；舌质暗，苔薄，脉弦细","treat":"疏肝解郁","formula":"柴胡疏肝散加减。胁痛明显者，加川楝子；有气郁化火征象者，加生地黄、牡丹皮","formulaNames":["柴胡疏肝散"]},{"t":"syn","sid":"s120804","name":"湿热下注证","clinic":"阳事不兴或勃起不坚，精子数少或死精子较多；小腹急满、小便短赤；舌苔薄黄，脉弦滑","treat":"清热利湿","formula":"程氏萆薢分清饮加减。精子较少者，可加西洋参；小腹胀满甚者，可加郁金、川楝子","formulaNames":["程氏萆薢分清饮"]},{"t":"syn","sid":"s120805","name":"气血两虚证","clinic":"性欲减退，阳事不兴，或精子数少、成活率低、活动力弱；神疲倦怠，面色无华；舌质淡，苔薄白，脉沉细无力","treat":"补益气血","formula":"十全大补汤加减。除辨证论治外，还可根据精液检查情况“辨精用药”，如精子成活率低、活动力差者，加淫羊藿、巴戟天、菟丝子、生黄芪等；死精、畸形精子多者，加土茯苓、重楼等；精液中有脓细胞者，加蒲公英、红藤、黄柏等；精液不液化而呈团块状者。加泽泻、牡丹皮、麦冬、当归、生地黄等","formulaNames":["十全大补汤"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)西药治疗根据病情、可选用人绒毛膜促性腺激素(hCG)、睾酮、克罗米芬、精氨酸、左卡尼汀、维生素类、硫酸锌糖浆等。"},{"t":"p","x":"(2)手术治疗可用于因精索静脉曲张、输精管权阻等所致的不育症。"},{"t":"p","x":"(3)辅助生殖技术(assisted reproductive technology,ART)对于保守治疗无效的少精、弱精、无精症等、可考虑辅助生殖技术等。"},{"t":"p","x":"(4)针灸治疗选肾俞、关元、膀胱俞、三阴交等穴，毫针平补平泻，每次15～30分钟，每日或隔日1次。"}]}],"entries":["e0880","e0881","e0882","e0883","e0884","e0885","e0886"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.提倡进行婚前教育，宣传生殖生理方面的有关知识，科学指导青年男女正确认识两性关系，夫妻和睦、性生活和谐。性生活适度，性交次数不要过频，也不宜相隔时间太长，否则影响精子质量。"},{"t":"p","x":"如果能利用女方排卵时间进行性交，可提高受孕概率。2.消除有害因素的影响，对接触放射线、有毒物品或高温环境而致不育者，可适当调动工作。"},{"t":"p","x":"勿过量饮酒及大量吸烟，不食棉籽油。"}],"entries":["e0887"]}]},{"id":"d1209","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"阳痿","displayName":"阳痿","parentId":"","printedPage":264,"pdfPage":279,"syndromeCount":8,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"阳痿是指男性除未发育成熟或已到性欲衰退时期外，性交时阴茎不能勃起，或虽勃起但勃起不坚，或勃起不能维持，以致不能进行或完成性交全过程的一种疾病。"},{"t":"p","x":"《内经》中称为“阴痿”“筋痿”，直至明代周之干首次以“阳痿”命名该病，在《慎斋遗书·阳痿》中有“阳痿多属于寒”的记载。本病相当于西医学的勃起功能障碍。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.肝气郁结肝主筋，足厥阴肝经绕阴器而行；宗筋作强也有赖于肝血之濡养。情志不遂，思欲过度，忧思郁怒，或多愁善感，或居家失和，以致日久伤肝，肝失疏泄，气机阻滞，肝郁气结，血不达宗筋，则宗筋不聚，乃成阳痿。"},{"t":"p","x":"2.湿热下注过食醇酒厚味，脾胃运化失常，聚湿生热，湿热下注，经络阻滞，气血不荣宗筋，乃成阳痿。或强力入房，忍精不射，而致败精瘀滞精道，酿为湿热；"},{"t":"p","x":"或交合不洁，湿热毒邪盘踞肝脉，体内湿热困阻，以致经脉失畅，宗筋失于气血充养，致其弛纵，发而成痿。或久居湿地，或湿热外侵，蕴结肝经，下注宗筋，发为阳痿。"},{"t":"p","x":"3.脾胃虚弱若素体禀赋虚弱，久病体虚或病后失养，劳倦内伤过度，损及脾胃，脾失运化，气血化源不足，可致宗筋失养而成阳痿。"},{"t":"p","x":"4.气血瘀阻多因下腹、阴部外伤，或手术所致创伤，导致局部气血瘀阻，或伤及经脉导致脉络不畅、不通，或久病生瘀，或年老体弱，败精阻络等，导致宗筋失于充养，渐致痿弱废用。"},{"t":"p","x":"5.心脾两虚心乃君主之官，情欲萌动，阳事之举，必赖心火之先动。脾生血，为后天之源，脾之经筋聚于阴器。"},{"t":"p","x":"宗筋作强有赖于脾血之濡养。过思多虑，损伤脾胃，气血不足，宗筋失养而成阳痿；"},{"t":"p","x":"忧虑伤心，心血暗耗，则心难行君主之令，从而阴茎痿软而不举。"},{"t":"p","x":"6.惊恐伤肾同房之时，突发变故，猝受大惊大恐，或初次性交，恐惧不能，或非婚同居、顾虑重重，或因偶有不举而疑虑丛生，恐惧再败等，惊恐伤于心肾，气机逆乱，气血不达宗筋、不能作强，则阳事不举。"},{"t":"p","x":"7.肾阴亏虚肾藏精，主生殖，开窍于二阴；宗筋作强有赖于肾精之濡养。若因素体阴虚，或相火偏旺，平素恣情纵欲，房事过频，而致肾精匮乏，阴虚火旺，此类患者虽阳道易举，但勃而不坚，难行房事。"},{"t":"p","x":"8.肾阳不足先天肾阳不足或恣情纵欲、房事过度，或频繁自慰，或早婚，或年老体弱，或劳倦过度，久病伤肾，均可造成肾之精气虚损，命门火衰，则宗筋无以作强而致阳事不举。"},{"t":"p","x":"西医学认为，本病是一个复杂的病理状态，涉及多个系统和因素，包括心理、精神、生活习惯、疾病、手术外伤及某些器质性病变等。"}],"entries":["e0888","e0889"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现在有性刺激和性欲的情况下，阴茎不能勃起或勃起不坚，勃起时间短促，很快疲软，以致不能进行或完成性交，并持续3个月以上。"},{"t":"p","x":"但须除外阴茎发育不良引起的性交不能。常有神疲乏力、腰膝酸软、畏寒肢冷，或夜寐不安、精神苦闷、胆怯多疑，或小便不畅、滴沥不尽等症。"},{"t":"p","x":"目前多采用国际勃起功能评分五项(IIEF-5)和勃起硬度评分(EHS)来评定阳痿的程度，参见"},{"t":"table","img":"img/tab/t1209.jpg","cap":"表12-9和表12-10。"},{"t":"p","x":"注：IIEF-5总分为25分，≥22分为勃起功能正常。轻度ED:12～21分；中度ED:8～11分：重度ED:<8分。"},{"t":"table","img":"img/tab/t1210.jpg","cap":"表12-10勃起硬度评分(EHS)"},{"t":"p","x":"(2)辅助检查西医学认为，勃起功能障碍有功能性与器质性之别。"},{"t":"p","x":"除常规检查尿液、性激素外，还可做夜间阴茎勃起试验和视听刺激勃起检测；或进行多普勒超声、阴茎动脉测压、阴茎海绵体注射血管活性药物、阴茎海绵体造影等检查，确定有无阴茎血流障碍。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-11)"},{"t":"table","img":"img/tab/t1211.jpg","cap":"表12-11阳痿与早泄、假性阳痿的鉴别"}],"entries":["e0890"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s120901","name":"肝气郁结证","clinic":"阳事不兴，或举而不坚；心情抑郁，烦躁易怒，胸胁胀满，善太息；苔薄白，脉弦","treat":"疏肝解郁","formula":"逍遥散加减","formulaNames":["逍遥散"]},{"t":"syn","sid":"s120902","name":"湿热下注证","clinic":"阴茎痿软；阴囊潮湿，瘙痒腥臭，睾丸坠胀作痛；小便色黄，尿道灼痛，胁胀腹闷，肢体困倦，泛恶口苦；舌红苔黄腻，脉滑数","treat":"清利湿热","formula":"萆薢渗湿汤加减","formulaNames":["萆薢渗湿汤"]},{"t":"syn","sid":"s120903","name":"脾虚胃弱证","clinic":"临房阴茎举而不坚；纳食减少，脘腹饱闷，身体倦怠，四肢乏力，面色萎黄；舌淡，苔薄，脉沉弱","treat":"补脾益胃","formula":"参苓白术散加减","formulaNames":["参苓白术散"]},{"t":"syn","sid":"s120904","name":"气血瘀阻证","clinic":"多有动脉硬化、糖尿病或阴部外伤及盆腔手术史，阳事不兴或勃起不坚，性欲淡漠；舌质暗有瘀斑，脉沉涩或弦","treat":"行气活血，通脉振阳","formula":"桃红四物汤加减","formulaNames":["桃红四物汤"]},{"t":"syn","sid":"s120905","name":"心脾两虚证","clinic":"阳痿不举；心悸，失眠多梦，神疲乏力，面色无华，食少纳呆，腹胀便溏；苔薄白，脉细弱","treat":"补益心脾","formula":"归脾汤加减","formulaNames":["归脾汤"]},{"t":"syn","sid":"s120906","name":"惊恐伤肾证","clinic":"阳痿不振；心悸易惊，胆怯多疑，夜多服梦，常有被惊吓史；苔薄白，脉弦细","treat":"益肾宁神","formula":"启阳娱心丹加减","formulaNames":["启阳娱心丹"]},{"t":"syn","sid":"s120907","name":"肾阴亏虚证","clinic":"阳事不举，或举而不坚，多由正常而逐渐不举，终至痿软不起；伴腰膝酸软，眩晕耳鸣，失眠多梦，遗精，形体消瘦；舌红少津，脉细数","treat":"滋阴补肾","formula":"左归丸或二地鳖甲煎加减","formulaNames":["左归丸","二地鳖甲煎"]},{"t":"syn","sid":"s120908","name":"肾阳不足证","clinic":"阳事不举，或举而不坚，精薄清冷；神疲倦怠，形寒肢冷，阴部冷凉，面色无华，头晕耳鸣，腰膝酸软，小便清长；舌淡胖，苔薄白，脉沉细","treat":"温肾助阳","formula":"右归丸加减","formulaNames":["右归丸"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)针灸疗法选关元、气海、肾俞、三阴交、命门、肝俞等穴毫针平补平泻，每次20～30分钟，隔日1次。"},{"t":"p","x":"(2)西药治疗根据病情可选用口服药物PDE5抑制剂、激素类药物如睾酮等。"},{"t":"p","x":"(3)手术治疗包括血管手术、假体植入术。"},{"t":"p","x":"此外，还有真空勃起装置(VED)、体外低能量冲击波治疗、海绵体内血管活性药物注射、心理疏导等疗法。"}]}],"entries":["e0891","e0892","e0893","e0894","e0895","e0896","e0897","e0898","e0899","e0900"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.宜调畅情志，心态平和，怡情养心。2.注意饮食搭配，少食醇酒肥甘，避免湿热内生。"}],"entries":["e0901"]}]},{"id":"d1210","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"血精","displayName":"血精","parentId":"","printedPage":267,"pdfPage":282,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"血精又称“精血”“行房出血”等，是指精液中夹有血液的疾病。其临床特点是精液中含有血液，根据精液中含血量的多少，可表现为肉眼血精或镜下血精。"},{"t":"p","x":"常与精浊同时发病。血精首见于《诸病源候论·虚劳精血出候》，曰：“肾藏精，精者血之所成也。"},{"t":"p","x":"虚劳则生七伤六极，气血俱损，肾家偏虚，不能藏精，故精血俱出也。”本病相当于西医学的精囊炎，有急性和慢性之分。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"血精的病位在精室。其病因或热入精室，或外伤跌仆，或脾肾气虚，血失统摄。"},{"t":"p","x":"基本病理变化为精室血络受损，血溢脉外，随精并出。1.湿热下注外感湿热毒邪，或嗜食辛辣厚味、醇酒炙煿之品，均可导致湿热内生，蕴结下焦，熏蒸精室，灼伤血络，迫血妄行，精血同下。"},{"t":"p","x":"2.阴虚火旺先天禀赋不足，或过服温燥助阳之品，或房劳过度，耗伤阴精，阴虚火旺，灼伤血络，血溢脉外，血随精出。"},{"t":"p","x":"3.瘀血阻络跌仆闪挫，伤及精室血络，络破血溢，或病久入络，瘀血内停，阻滞血络，或强力人房，逼令精出，精室血络受损，瘀血败精阻络等，均可导致血不循经，溢于精室，随精并出。"},{"t":"p","x":"4.脾肾两虚思虑无穷，劳倦过度，或久病体虚，房事不节，均可致脾肾两虚，气不统血摄精，精血俱出。"}],"entries":["e0902","e0903"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于成年男性，尤其是同时伴有前列腺炎者。"},{"t":"p","x":"部分患者有性交过频或性交持续时间过长、燥热饮食刺激等诱因。主要症状为排出的精液中含有血液，呈粉红色、暗红色或夹有血丝。"},{"t":"p","x":"可伴有下腹部及会阴部不适，或出现性欲减退、早泄等症状。急性期可伴有寒战、发热等全身表现。"},{"t":"p","x":"(2)专科检查直肠指检急性者可触及肿大的精爽腺，触痛明显，有波动感和压痛；"},{"t":"p","x":"慢性者压痛不明显、周围界限不清，部分患者精囊质地较硬。"},{"t":"p","x":"(3)辅助检查精液镜检可见大量红细胞，或并见脓细胞，精子大多数死亡或少精或无精子。"},{"t":"p","x":"血常规、尿常规、经直肠超声、CT、精囊镜检查和精囊腺造影(急性期禁行精嚢造影)等有助于明确诊断。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-12)"},{"t":"table","img":"img/tab/t1212.jpg","cap":"表12-12血精与慢性前列腺炎、急性膀胱炎、精囊肿瘤的鉴别"}],"entries":["e0904"]},{"title":"治疗","blocks":[{"t":"p","x":"本病治疗当以止血为原则。然其病有虚实之分和热、瘀、虚之不同，临证之时应审因辨证，分别施以凉血止血、养血止血、益气止血、祛瘀止血等法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s121001","name":"湿热下注证","clinic":"精液红色或暗红色或棕褐色，少腹、会阴及睾丸部疼痛或不适，射精时加剧；可伴有尿频、尿急，排尿灼热或疼痛，小便黄热，余沥不尽，或有白浊；舌红，苔黄腻，脉滑数或洪数","treat":"清热利湿，凉血止血","formula":"龙胆泻肝汤加减。出血较重者，加大蓟、小蓟；疼痛较甚者，加乌药、川楝子；火毒较甚者，加水牛角、牡丹皮","formulaNames":["龙胆泻肝汤"]},{"t":"syn","sid":"s121002","name":"阴虚火旺证","clinic":"精血相混，色鲜红，夹有碎屑状陈旧血块，或镜下精液中有红细胞，会阴部坠胀或阴茎中灼痛；伴头晕耳鸣，腰膝酸软，潮热盗汗，心烦口干，小便短黄；舌红少津，苔薄黄，脉细数","treat":"滋阴降火，凉血止血","formula":"知柏地黄丸合二至丸加减。出血甚者，加蒲黄炭、棕榈炭","formulaNames":["知柏地黄丸","二至丸"]},{"t":"syn","sid":"s121003","name":"瘀血阻络证","clinic":"精中带血，血色暗红，夹有血丝、血块，射精时精道疼痛较重，有阴部外伤史；伴少腹、会阴及睾丸部疼痛；舌质紫暗或有瘀点瘀斑，苔薄，脉涩","treat":"活血止血，祛瘀止痛","formula":"桃红四物汤合失笑散加减。疼痛甚者，加三七粉、牛膝","formulaNames":["桃红四物汤","失笑散"]},{"t":"syn","sid":"s121004","name":"脾肾两虚证","clinic":"精液淡红，或镜下见红细胞；伴有性欲减退或阳痿早泄；面色少华，神疲乏力，失眠多梦，腰膝酸软；舌淡而胖，脉细无力","treat":"补肾健脾，益气摄血","formula":"大补元煎合归脾汤加减。出血明显者，加血余炭、阿胶；遗精早泄者，加芡实、金樱子","formulaNames":["大补元煎","归脾汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)用野菊花、苦参、马齿苋、败酱草、马鞭草各30g，水煎坐浴，每晚1次。"},{"t":"p","x":"用于血精湿热下注者。"},{"t":"p","x":"(2)用金黄散15～30g，加山芋粉或藕粉适量，水200mL调成糊状，微冷后保留灌肠，每日1次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)中成药 ①龙胆泻肝丸，用于血精肝经湿热者；"},{"t":"p","x":"②知柏地黄丸，用于血精阴虚火旺者；"},{"t":"p","x":"③云南白药，用于各种证型，尤其适用于瘀血阻滞者；"},{"t":"p","x":"④归脾丸，用于血精反复不愈属气血不足、心脾两虚者。"},{"t":"p","x":"(2)西药治疗急性精囊炎根据细菌培养和药敏结果选择抗生素，慢性期可采用抗炎药物、经直肠微波理疗、热水坐浴及精囊前列腺按摩等综合措施治疗。"},{"t":"p","x":"血精日久不愈，反复发作者，可用止血药物、常用维生素K口服或肌内注射。10天为1个疗程。"},{"t":"p","x":"(3)针灸治疗取会阴、肾俞等穴。"},{"t":"p","x":"采用泻法，重刺激，不留针。每日针刺1次，10次为1个疗程。"},{"t":"p","x":"(4)心理治疗血精患者多感恐惧和惊慌，在运用其他方法治疗时，须向患者解释本病的发生、发展、转归，消除其顾虑。"}]}],"entries":["e0905","e0906","e0907","e0908","e0909","e0910","e0911"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.未病时，保持规律的性生活，房事不能过频，避免酒后尤其是醉酒后同房；少饮酒，少食辛辣燥热食物，保持大便通畅；避免不洁性交；"},{"t":"p","x":"预防会阴外伤，避免长时间骑车；积极防治尿道炎、前列腺炎等泌尿生殖系疾病。"},{"t":"p","x":"2.已病后，急性期禁止精道检查和精囊前列腺按摩，暂停房事；慢性期可适度房事，每次持续时间不宜过长。"},{"t":"p","x":"保持心情舒畅。避免久坐及长时间骑车。"},{"t":"p","x":"饮食以清淡为主，禁酒，忌辛辣刺激之品。"}],"entries":["e0912"]}]},{"id":"d1211","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"精浊","displayName":"精浊","parentId":"","printedPage":269,"pdfPage":284,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"精浊是精室在邪毒或其他致病因素作用下产生的一种疾病。常见症状是尿频、尿急、尿痛，偶见尿道溢出少量乳白色液体，并伴有会阴、腰骶、小腹、腹股沟等部隐痛不适等。"},{"t":"p","x":"好发于中青年男性。本病相当于西医学的前列腺炎。"},{"t":"p","x":"临床上有急性和慢性、有菌性和无菌性、特异性和非特异性的区别，其中以慢性无菌性非特异性前列腺炎最为多见，其特点是发病缓慢、病因病理复杂、症状表现多样、体征不典型、病情顽固、缠绵难愈。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"急性者多由饮食不节，嗜食醇酒肥甘，酿生湿热；或因外感湿热之邪，壅聚于下焦而成。慢性者多由相火妄动，所愿不遂，或忍精不泄，肾火郁而不散，离位之精化成白浊；"},{"t":"p","x":"包皮过长或房事不洁，精室空虚，湿热从精道内侵，湿热壅滞；或久坐致气血瘀阻而成。"},{"t":"p","x":"病久伤阴、肾阴暗耗，可出现阴虚火旺证候；或病久情志内伤，肝气郁结而发病；"},{"t":"p","x":"亦有体质偏阳虚者、久则火势衰微，易见肾阳不足之象。久病入络、精室脉络瘀阻，败精瘀浊与湿热互结，是精浊反复发作、缠绵难愈的主要原因。"},{"t":"p","x":"西医学认为、本病的发生与致病菌或病原微生物感染、尿液反流、异常的盆底神经肌肉活动及内分泌异常、免疫、心理等因素有关。"}],"entries":["e0913","e0914"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现急性者发病较急，突发寒战高热，尿频、尿急、尿痛，腰骶部及会阴部疼痛，或伴有直肠刺激征。"},{"t":"p","x":"形成脓肿时常发生尿潴留。直肠指检前列腺饱满肿胀，压痛明显，温度增高。"},{"t":"p","x":"慢性者临床症状表现不一、患者可出现不同程度的尿频、尿急、尿痛、尿不尽、尿道灼热，腰骶、小腹、会阴及睾丸等处坠胀隐痛。晨起、排尿终末或大便时尿道偶见有少量白色分泌物。"},{"t":"p","x":"部分病程较长患者可出现阳痿、早泄、遗精或射精痛等，或伴头晕耳鸣、失眠多梦、腰酸乏力等症状。直肠指检前列腺多正常大小，或稍大或稍小，质软或软硬不均，轻度压痛。"},{"t":"p","x":"(2)辅助检查急性者尿道口溢出分泌物镜检有大量脓细胞，涂片可找到细菌。"},{"t":"p","x":"慢性者前列腺按摩液镜检白细胞每高倍视野在10个以上，但白细胞数量与症状严重程度之间无明显相关性，卵磷脂小体减少或消失。若不能取得前列腺液时，可取精液检查，白细胞计数>1×10⁶/mL为异常。"},{"t":"p","x":"“四杯法”及“两杯法”可用于病原体定位检查。前列腺液培养有利于病原菌诊断。"},{"t":"p","x":"细菌性前列腺炎者前列腺液培养有较固定的致病菌生长，慢性非细菌性前列腺炎者细菌培养呈阴性。超声波检查多表现为内部回声强弱不均，可见增强的光斑及结节回声，被膜回声欠清晰。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-13)"},{"t":"table","img":"img/tab/t1213.jpg","cap":"表12-13精浊与慢性子痈(附睾炎)、精癃、精囊炎的鉴别"}],"entries":["e0915"]},{"title":"治疗","blocks":[{"t":"p","x":"主张综合治疗，注意调护。临床以辨证论治为主，抓住肾虚(本)、湿热(标)、瘀滞(变)三个基本病理环节，分清主次，权衡用药。"},{"t":"p","x":"此外，精浊(慢性前列腺炎)患者多有或轻或重的抑郁倾向，甚至是抑郁症的表现，其基本病机为肝郁。因此，不论何因、何证或病程新久，均可适当加入疏肝解郁之品。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s121101","name":"湿热蕴结证","clinic":"尿频、尿急、尿痛，尿道灼热感，排尿末或大便时尿道偶有白浊，会阴、腰骶、睾丸、小腹坠胀疼痛；苔黄腻，脉滑数","treat":"清热利湿","formula":"八正散或龙胆泻肝汤加减。疼痛较甚者，可加川楝子、醋延胡索等","formulaNames":["八正散","龙胆泻肝汤"]},{"t":"syn","sid":"s121102","name":"气滞血瘀证","clinic":"病程较长，少腹、会阴、睾丸、腰骶部坠胀疼痛，尿不尽；舌暗或有瘀斑，苔白或莎黄，脉沉涩","treat":"活血祛瘀，行气止痛","formula":"前列腺汤加减。疼痛甚者，可加醋延胡索、三七粉、牛膝等","formulaNames":["前列腺汤"]},{"t":"syn","sid":"s121103","name":"阴虚火旺证","clinic":"尿末或大便时尿道口有白色分泌物溢出，尿道不适，阳事易举，遗精或血精；腰膝酸软，头晕耳鸣，失眠多梦；舌红少苔，脉细数","treat":"滋阴降火","formula":"知柏地黄汤加减。伴血瘀者，可加当归、丹参等","formulaNames":["知柏地黄汤"]},{"t":"syn","sid":"s121104","name":"肾阳虚损证","clinic":"排尿淋沥，稍劳后尿道即有白色分泌物溢出；腰膝酸冷，阳痿，早泄，形寒肢冷；舌淡胖边有齿痕，苔白，脉沉细","treat":"补肾助阳","formula":"右归丸或济生肾气丸加减。伴有脾虚症状，可加黄芪、炒白术等","formulaNames":["右归丸","济生肾气丸"]},{"t":"syn","sid":"s121105","name":"肝气郁结证","clinic":"胸胁或少腹胀闷，或见会阴部、外生殖区、下腹部、耻骨区、腹股沟区、腰低部及肛周坠胀不适、隐隐作痛，小便淋沥不尽；或伴善太息、性情急躁、焦虑抑郁等，或见阳痿、早泄，症状随情绪波动加重；舌淡红，苔薄白，脉弦","treat":"疏肝解郁，理气止痛","formula":"柴胡疏肝散加减。伴血瘀疼痛者，可加醋延胡索、五灵脂等","formulaNames":["柴胡疏肝散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)坐浴朴硝30g，野菊花15g，黄柏20g，血竭9g，苏木10g。"},{"t":"p","x":"煎汤坐浴，温度不宜超过45℃，每晚1次，每次15分钟左右。亦可温水坐浴。"},{"t":"p","x":"未生育者不宜坐浴。"},{"t":"p","x":"(2)肛门内用药野菊花栓、前列安栓或解毒活血栓塞入肛门内3～4cm，每次1枚，每日1～2次。"},{"t":"p","x":"(3)保留灌肠应用解毒活血、行气止痛、消肿散结中药浓煎150mL左右，微冷后(约42℃)保留灌肠，每日1次。"},{"t":"p","x":"适用于湿热蕴结或气滞血瘀证。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)西药治疗针对病原体，根据药敏试验合理选用抗生素，或用α受体阻滞剂、非甾体抗炎药、抗抑郁药或抗焦虑药、M受体拮抗剂、植物药等。"},{"t":"p","x":"(2)前列腺按摩慢性前列腺炎可行前列腺按摩，每周1次。"},{"t":"p","x":"(3)物理疗法可采用生物反馈、电生理治疗、磁疗、超短波理疗、局部超短波透热或局部有效抗生素离子透入治疗。"},{"t":"p","x":"(4)针灸疗法选肾俞、关元、膀胱俞、三阴交等穴，毫针平补平泻，每次15～30分钟，每日或隔日1次。"},{"t":"p","x":"(5)手术疗法适用于急性前列腺炎已形成前列腺脓肿者。"},{"t":"p","x":"(6)心理治疗对有明显心理困扰者，建议进行心理治疗。"}]}],"entries":["e0916","e0917","e0918","e0919","e0920","e0921","e0922","e0923"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.急性前列腺炎应卧床休息，禁忌前列腺按摩。2.前列腺按摩时用力不宜过大，按摩时间不宜过长，也不宜过于频繁，以每周1次为宜。"},{"t":"p","x":"3.禁烟酒，忌过食肥甘及辛辣炙炒之品。4.生活规律，劳逸结合，避免频繁的性冲动，不要久坐或骑车时间过长。"}],"entries":["e0924"]}]},{"id":"d1212","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"精癃","displayName":"精癃","parentId":"","printedPage":272,"pdfPage":287,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"精癃是中老年男性的常见疾病之一，其临床特点以尿频、夜尿次数增多、排尿困难为主，严重者可发生尿潴留或尿失禁，甚至出现肾功能受损。本病相当于西医学的良性前列腺增生症。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的病理基础是年老肾气虚衰，膀胱气化不利，血行不畅，与肾和膀胱的功能失调有关。肾气虚衰是该病发生的根本，瘀血、湿热、痰浊等是疾病发展过程中产生的病理产物，它们彼此影响，互为因果。"},{"t":"p","x":"1.脾肾两虚年老脾肾气虚，推动乏力，不能运化水湿，终致痰湿凝聚，阻于尿道而生本病。2.气滞血瘀前列腺部位是肝经循行之处，肝气郁结，疏泄失常，可致气血瘀滞，阻塞尿道；"},{"t":"p","x":"或年老之人，气虚阳衰，不能运气行血，久之气血不畅，聚而为痰，痰血凝聚于水道；或憋尿过久，败精瘀浊停聚不散、凝滞于溺窍，致膀胱气化失司而发为本病。"},{"t":"p","x":"3.湿热蕴结若水湿内停、郁而化热，或饮食不节酿生湿热，或外感湿热，或恣饮醇酒聚湿生热等，均可致湿热下注，蕴结不散，瘀阻于下焦，诱发本病。西医学认为，有功能的睾丸和年龄的增长是前列腺增生发生的两个必备条件。"},{"t":"p","x":"但关于前列腺增生发病机制的学说较多，如雌一雄激素协同致病学说、前列腺生长因子学说、胚胎再唤醒学说等，但这些学说均尚未得到定论。"}],"entries":["e0925","e0926"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于50岁以上的男性患者。"},{"t":"p","x":"逐渐出现进行性尿频，以夜间为明显，并伴排尿困难，尿线变细。部分患者由于尿液长期不能排尽，导致膀胱残余尿增多而出现假性尿失禁。"},{"t":"p","x":"在发病过程中，常因受寒、劳累、憋尿、便秘等而发生急性尿潴留。严重者可引起肾功能损伤而出现肾功能不全的一系列症状。"},{"t":"p","x":"有些患者可并发尿路感染、膀胱结石、疝气或脱肛等。"},{"t":"p","x":"(2)辅助检查直肠指检前列腺常有不同程度的增大，表面光滑，中等硬度而富有弹性，中央沟变浅或消失。"},{"t":"p","x":"经直肠或腹部超声、CT、膀胱镜及尿流动力学等检查可以协助诊断。此外，血清前列腺特异性抗原(prostate-specific antigen,PSA)、前列腺体积、最大尿流率、残余尿量的检测可预测本病的临床进展。"},{"t":"p","x":"(3)症状评估目前临床常用国际前列腺症状评分(intenational prostate symptom score, IPSS)及生活质量评分(quality of life score,QOL)对本病进行诊断评估。"},{"t":"p","x":"IPSS是目前国际公认的判断本病症状严重程度的最佳手段。QOL可了解患者对其目前下尿路症状水平的主观感受、受下尿路症状困扰的程度及是否能够忍受。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表12-14)"},{"t":"table","img":"img/tab/t1214.jpg","cap":"表12-14精瘤与前列腺癌、神经源性膀胱的鉴别"}],"entries":["e0927"]},{"title":"治疗","blocks":[{"t":"p","x":"中医治疗应以通为用、补肾益气、活血利尿是其基本的治疗法则。出现并发症时应采用中西医结合疗法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s121201","name":"湿热下注证","clinic":"小便频数黄赤，尿道灼热或涩痛，排尿不畅，甚或点滴不通，小腹胀满；或大便干燥，口苦口黏；舌暗红，苔黄腻，脉滑数或弦数","treat":"清热利湿，消癃通闭","formula":"八正散加减。少腹疼痛明显者，可加三棱、莪术、丹参、水蛭、桃仁等；尿血者，可加藕节、蒲黄炭、小蓟等","formulaNames":["八正散"]},{"t":"syn","sid":"s121202","name":"中气不足证","clinic":"尿频，滴沥不畅，尿线细，甚或夜间遗尿或尿闭不通；或见小便浑浊如米泔；或肢体浮肿；神疲乏力，纳谷不香，面色无华，便溏脱肛；舌淡，苔白，脉细无力","treat":"补脾益气，温化膀胱","formula":"补中益气汤加减。小便失禁者，可加桑螵蛸、煅龙骨、煅牡蛎等","formulaNames":["补中益气汤"]},{"t":"syn","sid":"s121203","name":"气滞血瘀证","clinic":"小便不畅，尿线变细或点滴而下，或尿道涩痛，闭塞不通，或小腹胀满隐痛，会阴或睾丸胀痛、刺痛，偶有血尿；舌质暗或有瘀点瘀斑，苔白或薄黄，脉弦或涩","treat":"行气活血，通窍利尿","formula":"沉香散加减。伴血尿者，酌加大蓟、小蓟、三七；瘀甚者，可加蜣螂虫","formulaNames":["沉香散"]},{"t":"syn","sid":"s121204","name":"肾虚瘀阻证","clinic":"尿频尿急，夜尿增多，排尿无力，尿线细，排尿时间延长；伴腰膝酸痛或小腹、会阴、耻骨区、腰骶及肛周疼痛；舌淡紫，苔白，或有齿痕，脉细涩或细滑","treat":"补肾活血，化瘀通窍","formula":"金匮肾气丸合补肾通窍汤加减。偏阴虚内热者，去附子、肉桂，加知母、黄柏","formulaNames":["金匮肾气丸","补肾通窍汤"]},{"t":"p","x":"偏阴虚内热者，去附子、肉桂，加知母、黄柏。2.外治疗法多为急则治标之法，必要时可行导尿术。"},{"t":"p","x":"(1)脐疗法独头蒜1个，生栀子3枚，盐少许，将其捣烂如泥，敷脐部；"},{"t":"p","x":"或以葱白适量，捣烂如泥，加少许麝香和匀，敷脐部，外用胶布固定；或以食盐250g炒热，布包熨脐腹部，冷后再炒再熨。"},{"t":"p","x":"(2)灌肠法大黄15g，泽兰、白芷各10g，肉桂6g。"},{"t":"p","x":"煎汤150mL，每日保留灌肠1次。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术疗法当精癃导致以下并发症时，建议采取外科手术治疗："},{"t":"p","x":"①反复尿潴留(至少在一次拔管后不能排尿或两次尿潴留);"},{"t":"p","x":"②反复血尿，药物治疗无效；"},{"t":"p","x":"③反复泌尿系感染；"},{"t":"p","x":"④膀胱结石；"},{"t":"p","x":"⑤继发性上尿路积水(伴或不伴肾功能损害);"},{"t":"p","x":"⑥合并腹股沟疝、严重痔疮或脱肛。"},{"t":"p","x":"经典的手术方式有经尿道前列腺电切术(transurcthral resection of the prostate,TURP)、前列腺摘除术等，目前TURP仍是前列腺增生治疗的“金标准”。"},{"t":"p","x":"(2)中成药桂枝茯苓丸，用于精癃气滞血瘀者；补中益气丸，用于精癃中气不足者。"},{"t":"p","x":"(3)西药治疗常用的有α受体阻滞剂、5α还原酶抑制剂、β，受体激动剂、植物制剂。"},{"t":"p","x":"PDE5抑制剂较少单独用于前列腺增生患者。"},{"t":"p","x":"(4)物理疗法如微波、射频、激光等。"},{"t":"p","x":"(5)针灸疗法主要用于尿潴留患者，可针刺中极、归来、三阴交、膀胱俞、足三里等穴，强刺激，反复捻转提插。"},{"t":"p","x":"体虚者灸气海、关元、水道等穴。"}]}],"entries":["e0928","e0929","e0930","e0931","e0932","e0933"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.注意不要憋尿，保持大便通畅。2.慎起居，避风寒，忌饮酒及少食辛辣刺激性食物。"},{"t":"p","x":"3.避免长时间压迫会阴部，如久坐、骑车等。"}],"entries":["e0934"]}]},{"id":"d1213","kind":"main","chapterId":"ch12","chapterNo":"第十二章","chapterName":"泌尿男性生殖系疾病","name":"前列腺癌","displayName":"前列腺癌","parentId":"","printedPage":274,"pdfPage":289,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"前列腺癌是好发于老年男性的恶性肿瘤，因早期症状不明显而常被漏诊。其发病率存在显著的地域和种族差异。"},{"t":"p","x":"我国前列腺癌的发病率远低于欧美国家，但近年来呈上升趋势，且增长比欧美国家更为迅速。在世界范围内，根据2020年GLOBOCAN统计，其发病率在男性所有恶性肿瘤中位居第2位，仅次于肺癌。"},{"t":"p","x":"本病常见于50岁以上的男性，属中医学“瘤瘕”的范畴。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"前列腺癌是外邪、内伤、饮食、脏腑功能失调等多种因素综合作用导致机体阴阳失调，正气亏虚，气血阻于经络，而引起局部气滞、血瘀、痰凝、湿聚、热毒等互结而成。脾肾亏虚为本，湿热下注、痰瘀闭阻等因素加速了疾病的进展。"},{"t":"p","x":"西医学认为，本病的发生是先天胚系基因易感性、后天体系基因突变和微观、宏观环境因素相互作用的结果。年龄、种族、遗传性为前列腺癌的危险因素。"},{"t":"p","x":"有前列腺癌家族史者发病率较高且发病年龄更早。在外源性危险因素中，睾酮及雌激素等水平紊乱与前列腺癌的发病密切相关，雄激素暴露程度与前列腺癌的发生密切相关。"},{"t":"p","x":"其他的外源性因素，如高动物脂肪饮食、维生素E摄入不足等，会影响从潜伏型前列腺癌到临床型前列腺癌的进程。"}],"entries":["e0935","e0936"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现早期前列腺癌症状常不明显，当癌肿侵犯膀胱颈或阻塞尿道时，可见尿频、尿急、尿流缓慢、排尿不尽等下尿路症状，严重者可能出现急性尿潴留、血尿、尿失禁等。"},{"t":"p","x":"前列腺癌骨转移时常见骨骼疼痛、病理性骨折、贫血等症。"},{"t":"p","x":"(2)辅助检查直肠指检对前列腺癌的早期诊断有重要价值。"},{"t":"p","x":"前列腺特异性抗原(PSA)检查常用于前列腺癌筛查，前列腺癌的确诊需通过前列腺穿刺活检取得组织病理诊断。此外，经直肠前列腺超声、CT、MRI、骨扫描等检查可协助诊断及进行肿瘤分期。"},{"t":"h","lv":3,"x":"2.鉴别诊断"},{"t":"p","x":"前列腺增生症见精癃与前列腺癌的鉴别诊断。"}],"entries":["e0937"]},{"title":"治疗","blocks":[{"t":"p","x":"本病应根据前列腺癌的临床与病理分期、风险分组及患者自身因素采取合适的治疗方案，可配合中医辨证论治及其他治疗方法。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s121301","name":"湿热蕴结证","clinic":"小便频数、色黄，尿道灼热或刺痛、排尿不畅；或大便干燥，口苦口黏；舌质暗红，苔黄腻，脉滑数或弦数","treat":"清热利湿，解毒通淋","formula":"八正散加减。癌毒盛者，可加半枝莲、白花蛇舌草等","formulaNames":["八正散"]},{"t":"syn","sid":"s121302","name":"脾肾亏虚证","clinic":"尿频，排尿无力，尿线变细，小便淋沥不畅，严重者尿闭不通；精神疲乏无力，面色无华，胃纳差，大便溏泻；舌淡，苔白，脉细无力","treat":"补益脾肾，解毒化瘀","formula":"补中益气汤加减。食欲不振者，可加焦山楂、焦神曲、炒鸡内金；呕吐者，可加竹茹、姜半夏；泄泻加重者，可加肉豆葱、补骨脂","formulaNames":["补中益气汤"]},{"t":"syn","sid":"s121303","name":"痰瘀闭阻证","clinic":"小便点滴不出，甚或尿血；面色晦暗，纳差，大便黏滞不爽；舌紫暗，苔白腻，脉涩","treat":"软坚散结，祛瘀化痰","formula":"膈下逐瘀汤加减。疼痛剧烈者，可酌加三棱、莪术等","formulaNames":["膈下逐瘀汤"]},{"t":"syn","sid":"s121304","name":"气血两虚证","clinic":"多见于疾病晚期，消瘦，神疲乏力，面色㿠白；舌淡，苔白，脉细弱","treat":"补益气血，培补肾元","formula":"十全大补汤加减。遗尿者，可加芡实、桑螵蛸等；汗出者，可加浮小麦、龙骨、牡蛎等","formulaNames":["十全大补汤"]},{"t":"sub","title":"2.其他疗法","blocks":[{"t":"p","x":"(1)手术治疗对于低中危患者推荐行根治性前列腺切除术，对于肿瘤负荷较低的高危LPCa(局限在前列腺包膜内)推荐行根治性前列腺切除术，但建议行扩大盆腔淋巴结清扫，同时应考虑患者年龄及身体状况等因素。"},{"t":"p","x":"(2)内分泌治疗任何去除雄激素和抑制雄激素活性的治疗均可称为内分泌治疗，包括手术和药物去势。"},{"t":"p","x":"适用于转移性前列腺癌的治疗。"},{"t":"p","x":"(3)外放射治疗和手术治疗一样，是前列腺癌的根治性治疗手段。"},{"t":"p","x":"适用于各期前列腺癌患者。"},{"t":"p","x":"(4)化疗是去势抵抗前列腺癌的重要治疗手段。"},{"t":"p","x":"目前常用以多西他赛或卡巴他赛为基础的化学治疗方案。"}]}],"entries":["e0938","e0939","e0940","e0941","e0942","e0943"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.控制体重，避免高脂肪饮食。2.坚持中西医结合治疗，提高生存质量。"}],"entries":["e0944"]}]},{"id":"d1300","kind":"chapter","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"本章概述","displayName":"周围血管及淋巴管疾病·本章概述","parentId":"","printedPage":277,"pdfPage":292,"syndromeCount":0,"pages":[{"title":"本章概述","blocks":[{"t":"p","x":"周围血管疾病是指发生于心、脑血管以外的血管疾病，可分为动脉病和静脉病。"},{"t":"p","x":"动脉病包括血栓闭塞性脉管炎、动脉硬化性闭塞症、动脉栓塞、多发性大动脉炎、动脉瘤等，另外还包括肢端动脉舒缩功能紊乱疾病、如雷诺病、红斑性肢痛症等；静脉病包括血栓性浅静脉炎、深静脉血栓形成、深静脉瓣膜功能不全、静脉曲张等。"},{"t":"p","x":"淋巴管疾病如淋巴水肿等。中医学将周围血管疾病统称为“脉管病”。"},{"t":"p","x":"中医外科学在周围血管病及淋巴管疾病的诊治方面积累了丰富的临床理论和经验。"}],"entries":["e0945"]},{"title":"常见症状及体征","blocks":[{"t":"p","x":"1.疼痛肢体疼痛是周围血管疾病的常见症状，包括运动性疼痛(间歇性跛行)、持续性疼痛(静息痛)。其主要由动脉供血不足和静脉高压淤血引起。"},{"t":"p","x":"(1)运动性疼痛(间歇性跛行)表现为患者在以一定速度行走一定距离后，下肢的某个部位出现酸胀感及痉挛感，迫使患者停步，休息1～5分钟后症状缓解或消失，再次行走又出现同样的症状。"},{"t":"p","x":"一般来讲，持续行走的距离越短，病情越严重。从开始行走到出现疼痛的距离称为跛行距离，从出现疼痛后休息到疼痛缓解的时间称为缓解时间。"},{"t":"p","x":"出现间歇性跛行的动脉闭塞性疾病常见的有血栓闭塞性脉管炎、动脉硬化性闭塞症和糖尿病足等。需要指出的是，静脉性疾病和有些非动脉闭塞病变，如骼-股静脉闭塞、髋或膝关节炎等，也可发生间歇性跛行。"},{"t":"p","x":"因此，对有间歇性跛行者，必须检查有无动脉供血不足和静脉性疾病的其他征象。"},{"t":"p","x":"(2)持续性疼痛(静息痛)是指肢体在静止状态下产生的疼痛，疼痛持续存在，尤以夜间为甚。"},{"t":"p","x":"静息痛可以突然发生，如急性动脉栓塞；也可逐步发展而来，如血栓闭塞性脉管炎和动脉粥样硬化闭塞症等。"},{"t":"p","x":"持续性疼痛的发生常提示病变及缺血的程度均已加重，已接近失代偿的阶段。动脉性静息痛主要是由于供血障碍引起缺血性神经炎而使肢体持续性疼痛。"},{"t":"p","x":"疼痛表现为持续性钝痛，伴有间歇性剧烈刺痛，可向肢体远端放射，伴有麻木、厥冷或烧灼、蚁行、针刺等感觉异常。症状多夜晚加重，患者常抱膝而坐，借以缓解疼痛。"},{"t":"p","x":"当肢体因缺血引起营养障碍性溃疡或坏疽时，疼痛程度更加剧烈。营养障碍性静息痛的特点：夜间疼痛剧烈、持续，端坐抱膝，呻吟不止，有时也有短暂的间歇期，数分钟后再发，影响睡眠，肢体下垂时可略减轻疼痛。"},{"t":"p","x":"静脉性静息痛的疼痛程度较动脉性为轻，常伴有静脉回流障碍的其他表现，并可因平卧休息或抬高患肢而缓解。2.温度异常皮肤温度变化主要取决于肢体的供血情况。"},{"t":"p","x":"动脉闭塞性病变多为肢端寒冷、闭塞程度越重，距离闭塞平面越远，寒冷越明显。静脉病变多为下肢潮热感，下垂时更明显。"},{"t":"p","x":"检测患肢皮温时，患者需处于25℃左右的温度环境中，15～30分钟后再进行测定。3.颜色异常供血不足或血管舒缩失常而致的皮色改变包括苍白、紫绀和潮红等。"},{"t":"p","x":"静脉淤血时，渗出于血管外的红细胞崩解可造成色素沉着。某些血管疾病以皮肤颜色改变为主要临床表现、如雷诺病，由于指(趾)小动脉和毛细血管阵发性收缩和扩张而产生指(趾)阵发性发白、发紫和发红。"},{"t":"p","x":"检查患肢皮色时，应尽可能利用天然光线，在室温为25℃左右的环境中进行观察。4.感觉异常周围血管疾病所发生的感觉异常除疼痛外，还有潮热和寒冷、怠倦感、麻木、针刺或蚁行感等。"},{"t":"p","x":"5.结构异常主要包括皮肤及其附件营养障碍、动脉搏动减弱或消失、浅静脉曲张等。"},{"t":"p","x":"肢体增粗或萎缩、肢体肿胀多发生于下肢、静脉淤滞性肿胀一般为凹陷性水肿，按之较软，愈向远侧愈明显，多伴色素沉着、皮下组织炎症和纤维化、“足靴区”溃疡等。如深静脉血栓形成、下肢深静脉瓣膜功能不全、下肢静脉曲张等。"},{"t":"p","x":"淋巴水肿后期呈“象皮腿”伴肿胀。肢体或趾(指)变细、瘦小、萎缩均是由于局部动脉血液供应不足，长期缺乏必要的营养，加之疾病造成机体疼痛等限制了患肢活动等因素所造成。"},{"t":"p","x":"萎缩是慢性动脉功能不全的重要体征。肢体主要动脉搏动的改变、是诊断周围动脉疾病的重要体征。"},{"t":"p","x":"6.溃疡和坏疽缺血性溃疡是由动脉病变引起、由于动脉闭塞病变影响皮肤血液循环，以致组织缺氧而形成溃疡。"},{"t":"p","x":"淤积性溃疡多由静脉病变引起，常见于下肢静脉曲张和下肢深静脉瓣膜功能不全，静脉血液回流障碍导致局部淤积性缺氧、从而并发溃疡。肢体出现坏疽病灶、提示血液循环供应局部的营养不足以维持静息时组织的代谢需要，以致发生不可逆变化。"},{"t":"p","x":"如无继发感染，坏疽区因液体蒸发和吸收，可形成“干性坏疽”；如并发感染则形成“湿性坏疽”、坏死组织受细菌作用而崩解、化脓，有恶臭。"}],"entries":["e0946"]},{"title":"检查方法","blocks":[{"t":"p","x":"周围血管及淋巴管疾病的检查是获取临床信息的重要手段，临证时应重点检查皮肤温度、皮肤颜色、肢体营养状况、有无肢体的肿胀增粗或萎缩、有无肿块、有无溃疡或坏疽等。周围血管及淋巴管疾病的检查包括两大类，即临床检查和辅助检查。"},{"t":"p","x":"1.临床检查包括常规体格检查(如皮肤温度、营养状态、血管搏动等)和血管功能试验。"},{"t":"p","x":"影响皮肤温度的因素很多，当某部皮温较对侧及同侧其他部分明显降低时(相差大于2℃)，则提示该部动脉血流减少，可见于动脉栓塞、慢性动脉闭塞性疾病。"},{"t":"p","x":"若某部皮温较对侧或同侧其他部位明显升高，则提示该部动脉或静脉血流量增加，如深静脉血栓形成、红斑性肢痛症、动静脉瘘等。测定皮温的方法有扪诊法、半导体或数字皮温计、红外线热像仪等。"},{"t":"p","x":"营养状况的检查应重点观察肢体皮肤及附件、肌肉有无营养障碍性改变，如皮肤松弛、变薄、脱屑，汗毛稀疏、变细、停止生长或脱落，趾(指)甲生长缓慢、变脆、增厚并出现甲峭、嵌甲，以及肌肉萎缩等表现。"},{"t":"p","x":"动脉搏动和血管杂音的听诊是检查动脉性疾病的重要步骤，受检动脉为桡动脉、尺动脉、肱动脉、股动脉、腘动脉、足背动脉、胫后动脉。"},{"t":"p","x":"检查时应注意感测动脉搏动的强度，动脉的性质(如硬度、有无弯曲、结节、震颤)，血管杂音的部位及强度等。常用的血管功能试验："},{"t":"p","x":"(1)皮肤指压试验用手指压迫指(趾)端或甲床，观察毛细血管充盈时间，可了解肢端动脉血液供应情况。"},{"t":"p","x":"(2)肢体位置试验当肢体体位发生改变，观察皮肤颜色的变化，可借助此试验帮助了解肢体动脉血液供应情况。"},{"t":"h","lv":3,"x":"(3)运动试验间歇性跛行是慢性动脉供血不足的特征性症状。"},{"t":"p","x":"(4)大隐静脉瓣膜功能试验(Trenddenburg试验)用于检查大隐静脉瓣膜功能。"},{"t":"p","x":"(5)深静脉通畅试验(Perthes试验)用于检查深静脉通畅情况。"},{"t":"p","x":"(6)直腿伸踝试验(Homan's征)和压迫腓肠肌试验(Neuhof征)二者均为小腿深静脉血栓形成的体征。"},{"t":"p","x":"(7)冷水试验和握拳试验本试验可诱发雷诺病患者出现苍白→紫绀→潮红的皮色改变。"},{"t":"p","x":"2.辅助检查周围血管及淋巴管疾病常用的辅助检查包括理化检查、无损伤检查和影像学检查等。"},{"t":"h","lv":3,"x":"(1)理化检查常用的理化检查有血液流变、血脂、血凝等。"},{"t":"p","x":"血液流变检查：可表明血液流变学的变化，多见于血栓闭塞性脉管炎、动脉硬化闭塞症、多发性大动脉炎等。血凝检测：能够提示机体的凝血状态，血栓性疾病者往往表现为凝血功能亢进，而出血性疾病者则多表现为凝血功能减弱。"},{"t":"p","x":"血脂检测：检测指标有血清甘油三酯、总胆固醇、高密度脂蛋白、低密度脂蛋白、载脂蛋白等。血脂异常是动脉粥样硬化的重要原因之一，而在疾病治疗过程中，对于血脂的控制也越来越受到关注。"},{"t":"p","x":"(2)无损伤性检查临床常用的无损伤性检查有彩色多普勒超声、连续波多普勒超声、节段血压及压力指数测定、X线平片检查、CT血管成像、MRI血管成像、激光多普勒血流灌注成像、经皮氧分压等。"},{"t":"p","x":"对于血管外科疾病的诊断技术，目前来说血管造影仍是主要检测手段之一，但由于其有创及可重复性差的特点，并不能作为常规及随访监测的检查方法。"},{"t":"p","x":"临床上应用较为广泛的仍是无创检查，其中最重要的就是彩色多普勒超声，由于其能提供血管的解剖和血流动力学的信息，目前已成为血管疾病诊断最为重要的技术之一。"},{"t":"p","x":"(3)血管造影检查通过向血管内注入造影剂和利用影像设备来显示血管及其分支，根据血管的解剖形态学变化和血流动力学的改变对疾病进行诊断的方法称为血管造影，包括静脉造影和动脉造影。"},{"t":"p","x":"虽然近年来超声、CT和MRI在血管成像方面有很大的提高，但在临床实际工作中，在显示动脉，尤其是动脉小分支方面仍以数字减影血管造影为“金标准”。"},{"t":"p","x":"静脉造影应用广泛，主要有下肢深静脉顺行造影和逆行造影、经曲张浅静脉造影及各种经静脉插管造影等。"}],"entries":["e0947"]},{"title":"病因病机","blocks":[{"t":"p","x":"周围血管及淋巴管疾病的病因可分为内因与外因两大类。外因包括外感六淫、特殊毒邪(烟毒)、外伤等；"},{"t":"p","x":"内因包括饮食不节、情志内伤、脏腑经络功能失调、劳伤虚损等。周围血管及淋巴管疾病的病机特点是血瘀。"},{"t":"p","x":"血脉瘀滞破坏了人体气血的正常循环，从而引发各种不同的病理变化。在分析其病机时应注意邪、虚、瘀三者相互作用、互为因果的变化关系。"},{"t":"p","x":"其中邪既可以是外因，又可以是血瘀后的病理产物(如瘀血、痰浊、水湿)；虚既是受邪的条件，也可能是血瘀伤正的结果；瘀往往是因邪而致，也有的是因虚而成。"},{"t":"p","x":"所以在邪、瘀、虚的病理变化过程中，出现多种多样的组合，导致血管病变的发生和变化，形成了临床上的各种证候。虽然血管及淋巴管病的病变部位多数在血管及淋巴管的某一局部，但与脏腑气血有密切的关系。"},{"t":"p","x":"因为脏腑功能失调则会出现运血无力，统摄无权，疏泄失常，使血液及淋巴液不能正常运行而发生病变；反之，血脉瘀阻也会使各脏腑失去濡养而虚损。"},{"t":"p","x":"气血虚衰与血管及淋巴管病的关系更是直接的。此外，周围血管及淋巴管疾病的病因病机尚有禀赋不耐、遗传因素、冲任失调等，临证时亦不能忽视。"}],"entries":["e0948"]},{"title":"治疗","blocks":[{"t":"p","x":"1.内治周围血管及淋巴管疾病虽然病因多端，但常有诸如寒、湿、热之有余，或气、血、阴、阳之不足，它们都离不开血瘀这个基本病机。《素问·阴阳应象大论》曰：“血实宜决之。"},{"t":"p","x":"《素问·至真要大论》曰：“疏其血气，令其调达，而致和平。”因此，活血化瘀就成为周围血管及淋巴管疾病总的治则。"},{"t":"p","x":"应用活血化瘀总治则时，还必须结合寒热虚实的不同，灵活应用理气活血化瘀、益气活血化瘀、散寒活血化瘀、清热活血化瘀、祛湿活血化瘀、补血活血化瘀等一些常用的治法。"},{"t":"p","x":"(1)理气活血化瘀法适用于肝郁气滞血瘀证。"},{"t":"p","x":"凡周围血管疾病有气滞血瘀表现者均可应用，尤宜于病情随情志刺激而变化，或疾患使患者忧郁者。"},{"t":"p","x":"(2)益气活血化瘀法适用于气虚血瘀证。"},{"t":"p","x":"主要表现除有血瘀征象外，多为病久且伴体倦、纳差、气短、心悸、舌淡苔白、脉虚弱无力等。常见于动脉狭窄、闭塞性疾病和深静脉血栓形成及血栓性深静脉炎的后期。"},{"t":"p","x":"(3)散寒活血化瘀法即用温热的药物配合活血化瘀药物，解除寒凝，促使经脉舒通，血活瘀化。"},{"t":"p","x":"合乎“寒者热之”“血得温则行”之义。其中，温经通阳活血化瘀法适用于外寒客络血瘀证，补阳益气活血化瘀法适用于阳虚内寒血瘀证。"},{"t":"p","x":"由于内外之寒常相引而互相影响，进而凝血成瘀，临床表现错杂却有主次之分，论治时应细辨而酌情配伍。"},{"t":"p","x":"(4)清热活血化瘀法即用寒凉的药物配合活血化瘀药物，清解热邪，以使络宁血活瘀化，是“热者寒之”之义。"},{"t":"p","x":"在具体应用清热活血化瘀法时，必须首先分清热之为实为虚、在气在血，灵活应用清热凉血活血化瘀、清热解毒活血化瘀、养阴清热活血化瘀三法。"},{"t":"p","x":"清热凉血活血化瘀法适用于血热血瘀证，清热解毒活血化瘀法适用于热毒瘀滞证，养阴清热活血化瘀法适用于阴虚血瘀证。对于素体虚寒者、尽管外邪或瘀血已经化热，亦应慎用苦寒，以免伤伐阳气。"},{"t":"p","x":"(5)祛湿活血化瘀法即用燥湿或渗利的药物配合活血化瘀药物，以祛湿而通利气机，促使血活瘀化。"},{"t":"p","x":"因湿为阴邪，易阻气机而致血瘀。在具体应用祛湿活血化瘀治法时，又须分别出清热利湿活血化瘀、健脾利湿活血化瘀、温肾利湿活血化瘀三法。"},{"t":"p","x":"清热利湿活血化瘀法适用于湿热瘀滞证，健脾利湿活血化瘀法适用于脾虚湿瘀证，温肾利湿活血化瘀法适用于肾虚湿瘀证。以上各证均常见于深静脉血栓形成及深静脉回流障碍。"},{"t":"p","x":"(6)补血活血化瘀法即用补血的药物配合活血化瘀药物，以增血液而充盈脉道，促使血活瘀化。"},{"t":"p","x":"适用于血虚血瘀证。主要表现除有血瘀征象外，多为病久且伴头晕、面色萎黄或苍白、唇爪色淡、心悸、舌淡、脉细等。"},{"t":"p","x":"常见于动脉狭窄、闭塞性疾病的早期或后期。除活血化瘀之外，根据辨证论治的原则，针对患者不同疾病及疾病的不同阶段，还经常使用温经散寒、清热利湿、清热解毒等治法。"},{"t":"p","x":"2.外治周围血管及淋巴管疾病的外治与其他外科疾病一样，可以根据病情选用熏洗、箍围、浸渍、热烘等外治法。在周围血管疾病中，对坏疽的清创处理不同于其他外科疾病，必须顾及患肢的供血情况。"},{"t":"p","x":"清创必须在全身情况得到改善的条件下才能进行。在清创时要掌握以下原则：急性炎症期不做清创处理，炎症控制后适当清除坏死组织，在坏死组织的界限清楚后彻底清创。"},{"t":"p","x":"常用的清创方法有“鲸吞法”与“蚕食法”。所谓“鲸吞法”，即在麻醉下将失活组织自坏死与存活分界处进行清除。"},{"t":"p","x":"所谓“蚕食法”，就是在换药时视其具体情况逐渐地将能清除的坏死组织清除。“蚕食”坏死组织时可应用化腐生肌中药，这些药物应用得当能起到祛腐生新的作用。"},{"t":"p","x":"3.介入、手术疗法周围血管及淋巴管疾病在某些情况下还可运用介入、手术方法治疗，目前临床上应用比较广泛。"}],"entries":["e0949"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.防寒保暖。注意四肢末梢(手足)的保暖，避免在寒冷潮湿环境中久坐久卧。"},{"t":"p","x":"2.注意劳逸结合，“久卧伤气，久行伤筋”。过劳耗气，气虚无力推动血行；过逸则气机不畅，同样导致血瘀。"}],"entries":["e0950"]}]},{"id":"d1301","kind":"main","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"臁疮","displayName":"臁疮","parentId":"","printedPage":280,"pdfPage":295,"syndromeCount":2,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"臁疮是指发生于小腿臃骨部位的慢性皮肤溃疡。"},{"t":"p","x":"在古代文献中还有“裤口疮”“裙风”(《证治准绳》)、“烂腿”(《外科证治全书》)等名，俗称“老烂脚”。多见于久立久行者、常为筋瘤的后期并发症。"},{"t":"p","x":"主要发于双小腿内、外侧的下1/3处。其临床特点是经久难以收口，或虽经收口，每易因损伤而复发，与季节无关。"},{"t":"p","x":"本病相当于西医学的下肢慢性溃疡。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多由久站或过度负重而致小腿筋脉横解、青筋显露、瘀停脉络、久而化热，或小腿皮肤破损染毒，湿热下注而成，疮口经久不愈。《医宗金鉴·外科心法要诀》谓：“臁疮当分内外廉，外廉易治内难痊。"},{"t":"p","x":"外属三阳湿热结、内属三阴虚热缠。法宜搜风除湿热，外贴三香夹纸饯。"},{"t":"p","x":"西医学认为、下肢深、浅静脉及交通支静脉的结构异常，肢体远端的静脉压力持续增高是小腿皮肤营养性改变和溃疡的主要机制，而长期站立、腹压过高和局部皮肤损伤是溃疡的诱发因素。"}],"entries":["e0951","e0952"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于久立、久行者、常为筋瘤的后期并发症之一。"},{"t":"p","x":"初起小腿肿胀、沉重感、局部青筋怒张，朝轻暮重，逐渐加重，或出现浅静脉炎、淤积性皮炎、等一系列静脉功能不全表现、继而在小腿下1/3处(足靴区)内侧或外侧持续漫肿、苔藓样变，自行破溃或抓破后糜烂、滋水淋漓，溃疡形成；"},{"t":"p","x":"当溃疡扩大到一定程度时，边缘趋于稳定，周围红肿，或日久不愈，或经常复发。临床上常通过深静脉通畅试验、浅静脉和交通支静脉瓣膜功能试验等方法，进一步了解小腿溃疡的发病原因。"},{"t":"p","x":"后期疮口下陷、边缘高起，形如缸口，疮面肉色灰白或秽暗，滋水秽浊，疮面周围皮色暗红或紫黑，或四畔起湿疹而痒，日久不愈。或继发感染，周围红肿、疮面腐苔，脓水浸淫。"},{"t":"p","x":"或并发出血。严重时溃疡可扩大、加深，上至膝，下到足背，深达骨膜。"},{"t":"p","x":"少数患者可因缠绵多年不愈，蕴毒深沉而导致岩变。"},{"t":"p","x":"(2)辅助检查血常规检查一般正常，少数可有白细胞计数增高。"},{"t":"p","x":"临床上多用彩色多普勒超声、下肢CT静脉造影(CTV)、下肢磁共振静脉造影(MRV)、下肢静脉造影等方法检查其下肢静脉情况。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-1)"},{"t":"table","img":"img/tab/t1301.jpg","cap":"表13-1臁疮与结核性臁疮、臁疮恶变、放射性臁疮的鉴别"}],"entries":["e0953"]},{"title":"治疗","blocks":[{"t":"p","x":"中医学认为臁疮是本虚标实之证，气虚血瘀为基本病机，益气活血以消除下肢瘀血是治疗的关键。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s130101","name":"湿热下注证","clinic":"小腿筋聚怒张，局部发痒、红肿、疼痛，继则破溃，脓水浸淫，疮面腐暗，四周漫肿灼热；伴口渴，便秘，小便黄赤；舌红，苔黄腻，脉滑数","treat":"清热利湿，和营解毒","formula":"二妙丸合五神汤加减。水肿明显者、加茯苓皮、冬瓜皮利湿；胀痛明显者，加木瓜、丝瓜络通络止痛","formulaNames":["二妙丸","五神汤"]},{"t":"syn","sid":"s130102","name":"气虚血瘀证","clinic":"病程日久、疮面苍白，肉芽色淡、周围皮色暗黑、板硬；肢体沉重，倦怠乏力；舌淡紫或有瘀斑，苔白，脉细涩无力","treat":"益气活血，祛瘀生新","formula":"补阳还五汤合四妙汤加减。瘀阻甚者，加乳香、没药、延胡索通络","formulaNames":["补阳还五汤","四妙汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"祛腐阶段可选用掺药(九一丹、八二丹等)、油膏(金黄膏、生肌玉红膏、湿润烧伤膏、红油膏等)、蚕食清创术、中药熏洗及漏溃疗法(可选用清热利湿解毒中药煎剂熏洗，或复方黄柏液等)。"},{"t":"p","x":"生肌阶段可选用掺药(生肌散)、油膏(生肌玉红膏等)、中药熏洗及溻渍疗法(益气活血生肌中药煎剂)。"},{"t":"p","x":"(1)初期局部红肿、破溃、渗液较多者，宜用洗药。"},{"t":"p","x":"如马齿苋、黄柏、大青叶，煎水温湿敷。局部红肿、少量脓腐者，可中药熏洗后，加少量九一丹撒布于疮面上，再盖金黄膏。"},{"t":"p","x":"(2)后期久不收口，皮肤乌黑，疮口凹陷，疮面腐肉不脱，时流污水，用八二丹麻油调后摊贴疮面。"},{"t":"p","x":"腐肉已脱而露新肉者，用生肌散外盖生肌玉红膏。周围有湿疹者，用青黛散调麻油盖贴。"},{"t":"p","x":"药物治疗后宜用弹力绷带、并抬高患肢，以利静脉回流，减轻水肿，促使溃疡愈合。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)植皮术经久不愈的溃疡，在溃疡面清洁或溃疡切除后进行植皮，也可在静脉手术完成后植皮，能加快溃疡愈合速度。"},{"t":"p","x":"但疑有恶变时，应在病理切片证实后，按皮肤癌进行治疗。"},{"t":"p","x":"(2)静脉手术包括浅静脉手术、深静脉瓣膜修复或重建术、交通支静脉结扎术、静脉转流术或各种腔内治疗等。"},{"t":"p","x":"主要原则是纠正静脉反流和梗阻，缓解静脉高压，以促进溃疡愈合。静脉反流的治疗中，常见下肢浅静脉、穿通静脉和深静脉三个系统受累。"},{"t":"p","x":"对下肢浅静脉和穿通静脉瓣膜功能不全治疗的主要原则是去除曲张静脉，切除轴向浅静脉及阻断相关的病理性穿通静脉。对于静脉梗阻，腔内治疗已替代开放手术成为深静脉闭塞/髂静脉压迫的主要治疗方式。"}]}],"entries":["e0954","e0955","e0956","e0957","e0958"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.患足宜抬高，不宜久立久行。2.疮口愈合后宜经常用医用弹力袜或弹力绷带保护之，避免损伤，预防复发。"}],"entries":["e0959"]}]},{"id":"d1302","kind":"main","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"青蛇毒","displayName":"青蛇毒","parentId":"","printedPage":282,"pdfPage":297,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"青蛇毒是发生于肢体浅静脉的血栓性、炎性病变。"},{"t":"p","x":"其临床表现以肢体浅静脉呈条索状突起、色赤、形如蚯蚓、硬而疼痛为特征，多发于青壮年，以四肢为多见，次为胸腹壁。"},{"t":"p","x":"本病是一种常见病、多发病，与季节无关，男女均可罹患。"},{"t":"p","x":"本病相当于西医学的血栓性浅静脉炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病多由湿热蕴结、寒湿凝滞、痰浊瘀阻、脾虚失运、外伤血脉等因素，致使气血运行不畅，留滞脉中而发病。"},{"t":"p","x":"《医宗金鉴·外科心法要诀》称本病为“黄鳅痈”，谓：“此证生在小腿肚里侧，疼痛硬肿，长有数寸，形如泥鳅，其色微红，由肝、脾二经湿热凝结而成。”"},{"t":"p","x":"1.湿热蕴结饮食不节，恣食膏粱厚味、辛辣刺激之品，脾胃功能受损，水湿失运、火毒内生，湿热积毒下注脉中；或由寒湿凝于脉络，蕴久生热而成。"},{"t":"p","x":"2.肝气郁滞情志抑郁，恚怒伤肝，肝失条达，疏泄不利，气郁日久，由气及血，脉络不畅，瘀血停积。3.外伤筋脉长期站立、跌仆损伤、刀割针刺、外科手术等均可致血脉受损，恶血留内，积滞不散、致生本病。"},{"t":"p","x":"总之、本病外由湿邪为患、与热而蕴结，与寒而凝滞，与内湿相合困脾而生痰，是病之标；经脉受损、气血不畅，络脉瘀阻，为病之本。"}],"entries":["e0960","e0961"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多见于筋瘤后期，部位则以四肢多见(尤其多见于下肢)，次为胸腹壁等处。"},{"t":"p","x":"1)初期(急性期)在浅层脉络(静脉)径路上出现条索、硬块，患处疼痛，皮肤发红，触之较硬、扪之发热，按压疼痛明显，肢体沉重。"},{"t":"p","x":"一般无全身症状。"},{"t":"p","x":"2)后期(慢性期)患处遗有一条索状物，其色黄褐，按之如弓弦，可有按压疼痛，或结节破溃形成臁疮。"},{"t":"p","x":"临床上常见以下3种类型：肢体血栓性浅静脉炎：临床最为常见，下肢多于上肢。"},{"t":"p","x":"主要是累及一条浅静脉，沿着发病的静脉出现疼痛、红肿、灼热感，常可扪及结节或硬索状物，有明显压痛。当浅静脉炎累及周围组织时，可出现片状区域性硬块结节，则为浅静脉周围炎。"},{"t":"p","x":"患者可伴有低热，站立时疼痛尤为明显。患处炎症消退后，局部可遗留色素沉着或无痛性纤维硬结，一般需1～3个月后才能消失。"},{"t":"p","x":"胸腹壁浅静脉炎：多为单侧胸腹壁出现一条索状硬物，长10～20cm，皮肤发红、轻度刺痛，肢体活动时局部可有牵掣痛，用手按压条索两端，皮肤上可出现一条凹陷的浅沟，炎症消退后遗留皮肤色素沉着。一般无全身症状。"},{"t":"p","x":"游走性血栓性浅静脉炎：多发于四肢，即浅静脉血栓性炎症呈游走性发作，当一处炎性硬结消失后，其他部位的浅静脉又出现病变，具有游走、间歇、反复发作的特点。可伴有低热、全身不适等。"},{"t":"p","x":"若全身反应较重者，应考虑全身血管炎、结缔组织病、内脏疾病及深静脉病变等。"},{"t":"p","x":"(2)辅助检查血常规检查一般正常，少数可有白细胞计数增高，部分患者可出现血沉加快。"},{"t":"p","x":"超声多普勒检查可确定局部浅静脉炎是否已有血栓形成。血液流变学检查可反映全血黏度。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-2)"},{"t":"table","img":"img/tab/t1302.jpg","cap":"表13-2血栓性浅静脉炎与瓜藤缠、结节性脉管炎的鉴别"}],"entries":["e0962"]},{"title":"治疗","blocks":[{"t":"p","x":"本病早期以清热利湿为主，后期以活血散结为主。同时应积极治疗静脉曲张等原发疾病，并配合外治以提高疗效、防止复发。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s130201","name":"湿热瘀阻证","clinic":"患肢可见静脉曲张团突出、疼痛、色红、肿胀、灼热，可摸到硬结节或条索状物；可伴有全身不适、发热症状；苔黄腻或厚腻，脉滑数","treat":"清热利湿、解毒通络","formula":"二妙散合茵陈赤小豆汤加减。发于上肢加桑枝；发于下肢加牛膝；红肿消退，疼痛未减者，加赤芍、泽兰、地龙、忍冬藤","formulaNames":["二妙散","茵陈赤小豆汤"]},{"t":"syn","sid":"s130202","name":"血瘀湿阻证","clinic":"患肢疼痛、肿胀、皮色红紫，活动后尤甚，小腿部挤压刺痛或胀痛，或见条索状物，按之柔韧或如弓弦；舌有瘀点、瘀斑，脉沉细或沉涩","treat":"活血化瘀，行气散结","formula":"活血通脉汤加鸡血藤、桃仁、忍冬藤。发于上肢加桂枝；发于下肢加牛膝，兼服四虫丸","formulaNames":["活血通脉汤"]},{"t":"syn","sid":"s130203","name":"肝郁蕴结证","clinic":"胸腹壁有条索状物，固定不移，刺痛、胀痛，或牵掣痛；伴胸闷、嗳气等；舌质淡红或有瘀点、瘀斑，苔薄，脉弦或弦涩","treat":"疏肝解郁，活血解毒","formula":"柴胡清肝汤或复元活血汤。疼痛重者，加三棱、鸡血藤、忍冬藤等","formulaNames":["柴胡清肝汤","复元活血汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)初期可用消炎软膏或金黄散软膏外敷，每日换药1次。"},{"t":"p","x":"局部红肿渐消者可选用拔毒膏贴敷。"},{"t":"p","x":"(2)后期可用熏洗疗法，药物组成：当归尾12g，白芷9g，羌活9g，独活9g，桃仁9g，红花12g，海桐皮9g，威灵仙12g，生艾叶15g，生姜60g。"},{"t":"p","x":"水煎后熏洗。有活血通络、疏风散结之功。"},{"t":"p","x":"3.其他疗法部分病例可采取手术切除病灶及物理疗法。针灸疗法有一定疗效。"}]}],"entries":["e0963","e0964","e0965","e0966","e0967"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.急性期患者应卧床休息，以减轻疼痛。适当抬高患肢，若下床则可穿医用弹力袜，以减轻下肢水肿。"},{"t":"p","x":"2.病变早期不宜久站、久坐。3.饮食宜清淡，忌食辛辣、鱼腥之品，戒烟。"}],"entries":["e0968"]}]},{"id":"d1303","kind":"main","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"股肿","displayName":"股肿","parentId":"","printedPage":284,"pdfPage":299,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"股肿是指血液在深静脉血管内发生异常凝固，从而引起静脉阻塞、血液回流障碍的疾病。"},{"t":"p","x":"其主要表现为肢体肿胀、疼痛、局部皮温升高和浅静脉怒张等，在急性期可并发肺栓塞而危及生命，后期可遗留血栓后综合征(post-thrombotic syndrome, PTS)。本病相当于西医学的下肢深静脉血栓形成。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病主要是因气滞、气虚或血脉损伤，以致肢体气血运行不畅，瘀血阻于脉络，脉络滞塞不通，营血回流受阻，水津外溢，聚而为湿，发为本病。1.血脉损伤跌打损伤、手术等可直接伤害人体，使局部气血凝滞，瘀血流注于下肢而发生本病。"},{"t":"h","lv":3,"x":"2.久卧伤气产后或因长期卧床，肢体气机不利，气"},{"t":"p","x":"滞、血瘀于经脉之中、营血回流不畅而发本病。《医宗金鉴·外科心法要诀》曰：“产后与闪挫，瘀血作肿者，瘀血久滞于经络、忽发则木硬不热，微红。"},{"t":"p","x":"较明确地指出了本病的病因和发病特点。"},{"t":"h","lv":3,"x":"3.气虚血瘀多因年老、肥胖、瘤、岩等、致使患者"},{"t":"p","x":"气虚、气为血帅，气虚则无力推动营血运行，下肢又为血脉之末，故易发生血脉阻塞。"},{"t":"img","src":"img/fig/f1301.jpg","alt":"图13-1深静脉血栓形成模式图"},{"t":"p","x":"西医学认为、血流滞缓、静脉壁损伤和血液凝固性增高是静脉血栓形成的三大因素，而外伤、手术、分娩、肿瘤等可直接诱发本病。"},{"t":"p","x":"近年研究发现，炎症因子(如IL-6、TNF-α)参与血栓机化过程，与中医学“瘀热互结”病机相关(图13-1)。"}],"entries":["e0969","e0970"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现股肿多发生在左下肢。"},{"t":"p","x":"多见于肢体外伤、骨折、长期卧床、产后、肿瘤和其他血管疾病，以及各种手术、血管内导管术后。发病较急，主要表现为单侧下肢突发性广泛性粗肿、胀痛，行走不利，可伴低热。"},{"t":"p","x":"后期可出现浅静脉扩张、曲张，肢体轻度浮肿，小腿色素沉着、皮炎、臁疮等，即血栓后综合征(PTS)的表现。由于阻塞的静脉部位不同，临床表现不一。"},{"t":"p","x":"小腿深静脉血栓形成：肢体疼痛是其最主要的临床症状之一。肢体肿胀一般以踝及小腿部为主，行走时加重，腓肠肌压痛，一般无全身表现。"},{"t":"p","x":"临床称为周围型。下肢伸直并略抬高，检查者用手握住患者的足背部用力使踝关节背屈，使跟腱拉紧腓肠肌，患者感到小腿部后方出现疼痛，即为霍曼征(Homan's sign)阳性。"},{"t":"p","x":"尼霍夫征(Neuhof)阳性(按压腓肠肌有增厚、硬结和触痛)也具有重要诊断意义。骼股静脉血栓形成：突然性、广泛性、单侧下肢粗肿是本病的临床特征。"},{"t":"p","x":"疼痛性质为胀痛，部位可为全下肢，以患肢的骼窝、股三角区疼痛明显，甚至可连及同侧腰背部或会阴部。平卧时减轻，站立时加重。"},{"t":"p","x":"疾病初期主要是表浅静脉扩张，皮色暗红，如为急性血栓形成并广泛地使髂股静脉闭塞，则可出现患肢皮色的广泛青紫，临床上称为股青肿，是下肢深静脉血栓形成最严重的类型，可导致静脉性坏疽、休克；"},{"t":"p","x":"若表现为全下肢明显肿胀、剧痛、苍白，伴动脉痉挛，则称为股白肿。后期可在患肢侧的下腹部、髋部、会阴部见到曲张的静脉；"},{"t":"p","x":"疾病后期部分患者出现营养性改变，主要表现在患肢小腿的足靴区部位，呈脱屑、瘙痒、色素沉着、湿疹和溃疡等。临床称为中央型。"},{"t":"p","x":"混合型深静脉血栓形成：是指血栓起源于小腿肌肉内的腓肠静脉丛，顺行性生长、蔓延扩展至整个下肢静脉主干，或由原发性骼股静脉血栓形成逆行扩展到整个下肢静脉者。临床上称之为混合型。"},{"t":"p","x":"以前者较为多见，常发于手术后。临床表现兼具小腿深静脉和骼股静脉血栓形成的特点。"},{"t":"p","x":"另外，本病早期可出现急性股动脉痉挛(疼痛性股蓝肿)和肺动脉栓塞两种危重并发症，应引起高度重视。"},{"t":"p","x":"深静脉血栓形成后综合征：是指深静脉血栓形成后期，由于血液回流障碍，或血栓机化再通后静脉瓣膜被破坏，血液倒流，回流不畅，引起肢体远端静脉高压、淤血而产生的一系列临床表现，包括肢体肿胀、浅静脉曲张、皮肤色素沉着、脂性硬皮病、湿疹，直至溃疡形成。"},{"t":"p","x":"(2)辅助检查 ①彩色多普勒超声检查：是诊断下肢深静脉血栓形成的首选无创性检查方法，灵敏度、准确性均较高，适用于筛查和监测。"},{"t":"p","x":"②血浆D-二聚体测定：含量升高有助于急性下肢深静脉血栓形成的筛查，但特异性较低，阴性结果对排除急性血栓更有价值。"},{"t":"p","x":"③CT静脉造影(CTV)或磁共振静脉造影(MRV)：准确性高，尤其适用于评估骼静脉、下腔静脉等盆腔及腹部静脉血栓，以及疑似深静脉血栓形成合并肺动脉栓塞(pulmonary embolism,PE)的患者。"},{"t":"p","x":"④静脉造影：虽为有创检查，但仍是诊断下肢深静脉血栓形成的“金标准”，能最准确地判断血栓的有无、范围、形态及侧支循环状况。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-3)"},{"t":"table","img":"img/tab/t1303.jpg","cap":"表13-3股肿、原发性下肢深静脉瓣膜功能不全、淋巴水肿的鉴别"}],"entries":["e0971"]},{"title":"治疗","blocks":[{"t":"p","x":"本病治疗强调分期与辨证相结合。急性期以清热利湿、活血化瘀为主，重在控制血栓蔓延、缓解症状、预防肺栓塞；"},{"t":"p","x":"慢性期及后遗症期以益气健脾、活血通络为主，重在改善循环、减轻症状、预防复发。临床一般采用中西医结合的方法进行治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s130301","name":"湿热下注证","clinic":"发病较急，患肢粗肿、皮温升高、皮色发红、疼痛，活动受限；舌质红，苔黄腻，脉弦滑数","treat":"清热利湿，活血化瘀","formula":"四妙勇安汤加味","formulaNames":["四妙勇安汤"]},{"t":"syn","sid":"s130302","name":"血脉瘀阻证","clinic":"患肢肿胀，皮色紫暗，固定性压痛，肢体青筋怒张；舌质暗或有瘀斑，苔白，脉弦或涩","treat":"活血化瘀，通络止痛","formula":"活血通脉汤加减","formulaNames":["活血通脉汤"]},{"t":"syn","sid":"s130303","name":"气虚湿阻证","clinic":"患肢肿胀日久，朝轻暮重，活动后加重，休息抬高下肢后减轻，倦怠乏力；青筋迂曲，或伴小腿色素沉着、淤积性皮炎，或起湿疹，或成溃疡；倦怠乏力；舌淡边有齿痕，苔薄白或白腻，脉沉细或沉缓","treat":"益气健脾，祛湿通络","formula":"参苓白术散加味","formulaNames":["参苓白术散"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)急性期可用冰硝散外敷，具有清热消肿、止痛之效。"},{"t":"p","x":"注意：急性期严禁热敷、按摩或挤压患肢，以防血栓脱落。"},{"t":"p","x":"(2)侵性期及后遗症期可用活血化瘀、通络止痛之中药煎汤，待水温适宜(约40℃)后外洗患肢。"},{"t":"p","x":"对于已发生溃疡者，应根据疮面情况换药，参照“赈疮”处理。3.其他疗法西医治疗深静脉血栓形成主要包括抗凝、溶栓、手术取栓及介入治疗。"},{"t":"p","x":"对于发生急性肺栓塞和疼痛性股白肿、股青肿者，必须采用中西医结合的方法积极救治。"}]}],"entries":["e0972","e0973","e0974","e0975","e0976"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.对高危患者(如长期卧床、术后、产后、恶性肿瘤、既往有下肢深静脉血栓形成病史等)，应鼓励其主动或被动活动足踝(如踝泵运动)、尽早下床活动。2.术后可在床上进行踝泵运动；"},{"t":"p","x":"可适当垫高下肢以利回流；严禁随意按摩小腿肌肉，以免引发肺栓塞。"},{"t":"p","x":"3.急性期应绝对卧床休息，并抬高患肢。发病1个月内乃至整个抗凝治疗期间不宜做剧烈活动或患肢按摩，务必防栓子脱落引起肺栓塞。"},{"t":"p","x":"4.发病后期或进入慢性期后，可使用合适的压力等级的弹力绷带或医用弹力袜，以促进静脉血液回流、减轻症状，预防和减轻血栓后综合征(PTS)。穿戴时间建议在晨起下床前，睡前脱下。"},{"t":"p","x":"5.定期复查血管超声及凝血功能、监测并发症。"}],"entries":["e0977"]}]},{"id":"d1304","kind":"main","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"脱疽","displayName":"脱疽","parentId":"","printedPage":287,"pdfPage":302,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"脱疽是指发于四肢末端，严重时趾(指)节坏疽脱落，又称“脱骨疽”。"},{"t":"p","x":"其临床特点是好发于四肢末端，以下肢多见。初起患肢末端发凉、怕冷、苍白、麻木，可伴间歇性跛行；继则疼痛剧烈；"},{"t":"p","x":"日久患趾(指)坏死变黑，甚至趾(指)节脱落。部分患者起病急骤，进展迅速，预后严重，须紧急处理。"},{"t":"p","x":"在《灵枢·痈疽》中即有关于本病的记载，曰：“发于足趾，名脱痈，其状赤黑，死不治；不赤黑，不死。不衰，急斩之，不则死矣。"},{"t":"p","x":"中医文献中，与“脱疽”相关的病名还有“脉痹”及“筋疽”。脉痹始见于《素问·痹论》，其指出痹“在于脉则血凝而不流”，涵盖了全身以“血脉瘀阻”为病机的一类疾病。"},{"t":"p","x":"筋疽病名最早见于《刘涓子鬼遗方》，指发于椎旁或踝关节等处的痈疽。而相当部分的糖尿病足患者足部已出现坏疽，但其病足缺血性特征并不明显，且坏疽处可见到肌腱有不同程度的变性、坏死，病足坏死呈湿性。"},{"t":"p","x":"鉴于此，20世纪80年代奚九一教授提出了“糖尿病足肌腱变性坏死症”这一概念及“筋疽”的中医病名。脱疽涵盖了西医学的血栓闭塞性脉管炎、下肢动脉硬化性闭塞症、糖尿病足及急性动脉栓塞等疾病。"},{"t":"p","x":"随着生活方式的改变，下肢动脉硬化性闭塞症和糖尿病足的发病率明显升高，而血栓闭塞性脉管炎的发病率呈下降趋势。"}],"entries":["e0978"]}]},{"id":"d1304a","kind":"sub","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"血栓闭塞性脉管炎","displayName":"脱疽·血栓闭塞性脉管炎","parentId":"d1304","printedPage":287,"pdfPage":302,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"血栓闭塞性脉管炎是一种中小动静脉的周期性、节段性、慢性炎症病变，是以血管腔发生狭窄、闭塞，引起局部组织缺血、坏死，肢体末端脱落为病变过程的疾病。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的基本病机是血脉瘀阻，内因脾肾阳气不充、气血虚亏或肝肾阴虚，外因烟毒及寒湿损伤。脾肾阳气不足，不能温养四肢，复受寒湿之邪，则气血凝滞，经络阻塞；"},{"t":"p","x":"脾虚生湿酿痰，痰湿重浊黏腻，最易损伤阳气，阻遏气机，致血运失其畅达，久则湿邪化热，湿痰热互结、亦可瘀阻经脉，使血脉滞而不通；肝肾亏虚，阴虚热盛津伤可致血脉涩滞；"},{"t":"p","x":"气血不足则血行无力致血脉瘀阻。血脉瘀阻，四肢气血不充，失于濡养则皮肉枯槁，坏死脱落。"},{"t":"p","x":"总之，本病的发生以肝脾肾亏虚为本，瘀血、痰饮、寒浊和热毒为标，气血凝滞、经脉阻塞为其主要病机。西医学认为本病病因不太清楚，发病机制比较复杂，认为其是一种自身免疫性疾病。"},{"t":"p","x":"主要与吸烟、寒冷、外伤、感染、血管调节障碍及内分泌紊乱等因素有关。"}],"entries":["e0979","e0980"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现血栓闭塞性脉管炎好发于青壮年，以20～40岁男性多见。"},{"t":"p","x":"多发于寒冷季节或常在寒冷季节加重，常先一侧下肢发病、继而累及对侧，少数患者可累及上肢。患者多有受冷、受潮、嗜烟、外伤等病史。"},{"t":"p","x":"根据疾病的发展过程，临床一般可分为三期。一期(局部缺血期)：患肢末端发凉、怕冷、麻木、酸痛，间歇性跛行。"},{"t":"p","x":"患肢可出现轻度肌肉萎缩，皮肤干燥、皮温稍低于健侧、皮肤指压试验可见充盈缓慢，足背动脉、胫后动脉搏动减弱，部分患者小腿可出现游走性红硬条索(游走性浅静脉炎)。"},{"t":"p","x":"二期(营养障碍期)：患肢发凉、怕冷、麻木、坠胀疼痛，间歇性跛行加重，并出现静息痛。患肢肌肉明显萎缩，皮肤干燥，汗毛脱落，趾甲增厚且生长缓慢，皮肤苍白或潮红或紫绀，患侧足背动脉、胫后动脉搏动消失。"},{"t":"p","x":"三期(坏死期或坏疽期)：坏疽可先为一趾或数趾，逐渐向上发展，合并感染时足趾紫红肿胀、溃烂坏死，呈湿性坏疽；或足趾发黑、干瘪，呈干性坏疽。"},{"t":"p","x":"病程日久，患者可出现疲乏无力、不欲饮食、口干、形体消瘦，甚则壮热神昏。根据肢体坏死的范围，可将坏疽分为三级：一级坏疽局限于足趾或手指部位；"},{"t":"p","x":"二级坏疽局限于足跖部位；三级坏疽发展至足背、足跟、踝关节及其上方。"},{"t":"p","x":"(2)辅助检查彩色多普勒超声、CT血管成像(computed tomography angiography, CTA)、数字减影血管造影(digital subtraction angiography, DSA)等影像学检查及血脂、血糖等实验室检查有助于鉴别诊断。"},{"t":"p","x":"踝肱指数(ankle-brachial index,ABI)有助于判断缺血程度及预后。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-4、表13-5)"},{"t":"table","img":"img/tab/t1304.jpg","cap":"表13-4脱疽相关疾病的临床鉴别"},{"t":"table","img":"img/tab/t1305.jpg","cap":"表13-5血栓闭塞性脉管炎与雷诺综合征的鉴别"}],"entries":["e0981"]},{"title":"治疗","blocks":[{"t":"p","x":"中医以辨证论治为主，活血化瘀法贯穿始终。对于部分发病较急的患者，可及时采取手术和中西医结合治疗。"},{"t":"p","x":"治疗原则主要是改善肢体血液循环、缓解疼痛，挽救肢体。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s1304a01","name":"寒湿阻络证","clinic":"患趾(指)喜暖怕冷，麻木，酸胀疼痛，多走则疼痛加剧，稍歇痛减，皮肤苍白，触之发凉、趺阳脉搏动减弱；舌淡，苔白腻，脉沉细","treat":"温阳散寒，活血通络","formula":"阳和汤加减。阳虚甚者，可加制附子、肉桂","formulaNames":["阳和汤"]},{"t":"syn","sid":"s1304a02","name":"血脉瘀阻证","clinic":"患趾(指)酸胀疼痛加重，夜难入寐，步履艰难，患趾(指)皮色暗红或紫暗，下垂更甚，皮肤发凉干燥，肌肉萎缩，趺阳脉、太溪脉搏动消失；舌暗红或有瘀斑，苔薄白，脉弦涩","treat":"活血化瘀，通络止痛","formula":"桃红四物汤加减。可加活血破瘀、通络止痛效果较强的虫类药，如蜈蚣、全蝎、土鳖虫等","formulaNames":["桃红四物汤"]},{"t":"syn","sid":"s1304a03","name":"湿热毒盛证","clinic":"患肢剧痛，日轻夜重，局部肿胀，皮肤紫暗，浸淫蔓延，溃破腐烂，肉色不鲜；身热口干，便秘溲赤；舌红，苔黄腻，脉弦数","treat":"清热利湿，解毒活血","formula":"四妙勇安汤加减。水肿明显者，加冬瓜皮、猪苓、防己；痛剧者，加全蝎、蜈蚣、土鳖虫","formulaNames":["四妙勇安汤"]},{"t":"syn","sid":"s1304a04","name":"热毒伤阴证","clinic":"皮肤干燥，汗毛脱落，趾(指)甲增厚变形，肌肉萎缩，趾(指)呈干性坏疽；口干欲饮，便秘溲赤；舌红，苔黄，脉弦细数","treat":"清热解毒，养阴活血","formula":"顾步汤加减","formulaNames":["顾步汤"]},{"t":"syn","sid":"s1304a05","name":"气阴两虚证","clinic":"病程日久，坏死组织脱落后疮面久不愈合，肉芽暗红或淡而不鲜；倦怠乏力，口渴不欲饮，面色无华，形体消瘦，五心烦热；舌淡尖红，少苔，脉细无力","treat":"益气养阴","formula":"黄芪鳖甲汤加减","formulaNames":["黄芪鳖甲汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)未溃重在保护，避免使用刺激性药物、外伤。"},{"t":"p","x":"中药外敷或涂擦：可选用冲和膏、红灵丹油膏外敷；或用红灵酒少许揉擦患肢足背、小腿，每次20分钟，每日2次。"},{"t":"p","x":"中药熏洗：可用活血止痛散熏洗，亦可用当归15g，独活30g，桑枝30g，威灵仙30g，煎水熏洗，每日1次。针灸疗法：用附子、干姜、吴茱萸各等份，研末，蜜调，敷于患足涌泉穴；"},{"t":"p","x":"艾灸、刮痧、穴位注射、电针等均可选用。"},{"t":"p","x":"(2)已溃 ①对于干性坏疽，应消毒后包扎，控制感染，限期手术治疗。"},{"t":"p","x":"②疮面渗出物和分泌物多、臭秽时，应收敛解毒，以三黄熏洗剂(黄连、黄柏、黄芩、十大功劳、虎杖、地榆)煎汤浸渍或湿敷。"},{"t":"p","x":"③脓液减少，坏死组织难以脱落者，可先用油膏(如生肌玉红膏、湿润烧伤膏等)祛腐生肌；"},{"t":"p","x":"难以液化者，采取蚕食清创方法，逐步清除。"},{"t":"p","x":"④待脓腐尽、创面转洁，肉芽鲜红者，改用生肌膏外敷以生肌敛疮。"},{"t":"p","x":"⑤溃疡久不愈合，肉芽灰淡者，可选用中药熏洗疗法配合温阳益气类药膏，以促进生肌收口。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)手术治疗"},{"t":"p","x":"清创术：待坏死组织与正常组织分界清楚，近端炎症控制后，可行坏死组织清除术，骨断面宜略短于软组织断面。趾(指)切除缝合术：坏死组织与健康组织分界清楚，炎症控制，血运改善时，可行趾(指)切除缝合术或半足切除缝合术。"},{"t":"p","x":"截肢术：严重的肢体坏疽、感染无法控制者，根据患肢血运情况可行膝下或膝上截肢术。血运重建术：采用开放手术或血管介入治疗改善肢体供血，阻止坏疽发生或降低截肢平面。"},{"t":"p","x":"开放手术包括动脉切开取栓术、动脉内膜剥脱术、动脉旁路移植术、静脉动脉化等。血管介人治疗包括经皮腔内血管成形术、血管腔内减容术、药物球囊扩张成形术、血管内支架成形术等。"},{"t":"p","x":"(2)中成药常用的有通塞脉片、脉管康复片、血府逐瘀胶囊等。"},{"t":"p","x":"(3)西医治疗 ①扩张血管，可选用贝前列素钠片、盐酸沙格雷酯片、前列地尔等。"},{"t":"p","x":"②抗感染，并发溃疡感染者根据脓液培养结果选用抗生素治疗。"},{"t":"p","x":"③镇痛，使用吲哚美辛(消炎痛)、强痛定、曲马多、吗啡类药物。"},{"t":"p","x":"近年来，脊髓电刺激疗法在下肢缺血性疾病镇痛中取得较好疗效。"}]}],"entries":["e0982","e0983","e0984","e0985","e0986","e0987","e0988","e0989"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.戒烟，并远离吸烟环境，少食辛辣炙煿及醇酒之品。2.注意保暖，鞋袜宜宽大舒适，每天用温水泡洗双足。"},{"t":"p","x":"避免足部的外伤或感染。3.患侧肢体运动锻炼可促进患肢侧支循环形成。"},{"t":"p","x":"方法：患者仰卧，抬高下肢45°～60°，保持2～3分钟，然后两足下垂床沿4～5分钟，同时两足及足趾向下、上、内、外等方向运动10次，再将下肢平放4～5分钟。每日运动3次。"},{"t":"p","x":"坏疽感染时制动。"}],"entries":["e0990"]}]},{"id":"d1304b","kind":"sub","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"下肢动脉硬化闭塞症","displayName":"脱疽·下肢动脉硬化闭塞症","parentId":"d1304","printedPage":290,"pdfPage":305,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"下肢动脉硬化闭塞症是由于下肢动脉粥样硬化斑块形成，引起动脉内膜增厚、管腔狭窄或闭塞，病变肢体血液供应不足，继而引起下肢间歇性跛行、皮温降低、疼痛乃至发生溃疡或坏死的慢性进展性疾病。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病的发生以饮食不节为主要病因，脾虚为本，寒湿外伤为标，血脉瘀阻为其基本病机。饮食不节，首伤脾胃。"},{"t":"p","x":"脾胃受伤，一则气血生化不足，血行失动力而致瘀，肌肉失温煦濡养；二则脾虚失运，痰饮内生；"},{"t":"p","x":"三则脾虚失运水湿内生，湿性黏滞，滞涩脉道。以上病理终致血脉瘀阻。"},{"t":"p","x":"寒主收引，湿性黏滞，均为阴邪，易伤阳气，故外受寒湿可加重病情，而外伤感邪则可致变证。血脉瘀阻，气不能通达内外则现脉络阴寒之象。"},{"t":"p","x":"血不能通达荣养脏腑、充养四肢，加之瘀久化热而现阴血不足，燥热内生而见脉络瘀热之证。复感外邪，化热而现脉络热毒证。"},{"t":"p","x":"西医学认为，本病的发生与高血脂、高血压、糖尿病和吸烟等因素密切相关。脂质代谢紊乱、血管内皮功能障碍是重要的发病因素。"}],"entries":["e0991","e0992"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现本病多发于40岁以上人群，多伴有高血脂、高血压等慢性疾病。"},{"t":"p","x":"本病的主要症状有间歇性跛行、静息痛、肢冷。主要体征有皮肤温度降低、发绀、干燥、脱屑、光薄或皲裂，趾甲增厚、变形、生长缓慢，汗毛稀少或脱落，趾腹弹性下降；"},{"t":"p","x":"足背和胫后动脉搏动减弱或消失，严重者可出现股、腘动脉搏动减弱或消失；趾端或肢体溃疡、坏疽等。"},{"t":"p","x":"(2)辅助检查彩色多普勒超声检查为无创的初步检查方法。"},{"t":"p","x":"确诊和拟定外科手术或腔内治疗方案，根据需要进一步行磁共振血管成像(magnetic resonance angiography,MRA)、CT血管成像(CTA)、数字减影血管造影(DSA)等检查。"},{"t":"p","x":"踝肱指数(ABI)检查有助于判断缺血程度及预后。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-6、表13-7)"},{"t":"table","img":"img/tab/t1306.jpg","cap":"表13-6下肢动脉硬化闭塞症与神经源性跛行的鉴别"},{"t":"table","img":"img/tab/t1307.jpg","cap":"表13-7下肢动脉硬化闭塞症与下肢动脉栓塞的鉴别"}],"entries":["e0993"]},{"title":"治疗","blocks":[{"t":"p","x":"本病晚期治疗难度大，疗效不佳，手术进行血管搭桥或介入治疗都有相应的适应证和局限性，因此，早发现、早治疗尤为重要。中医辨证施治可改善患者血管弹性，促进侧支循环建立，延缓病情的发展。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"p","x":"本病分型证治可参照血栓闭塞性脉管炎辨证论治。需要注意的是，此病多发于老年"},{"t":"p","x":"人，中医学认为老年人宗气渐衰，治疗时尤应注重扶助正气。2.外治疗法参照血栓闭塞性脉管炎外治。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)参照血栓闭塞性脉管炎。"},{"t":"p","x":"(2)植皮术：点状或邮票状植皮术适用于创面过大，难以自行愈合，但经治疗后血液循环改善，感染已被控制，肉芽新鲜者。"}]}],"entries":["e0994","e0995"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.参照血栓闭塞性脉管炎的预防与调护。2.积极治疗高脂血症、高血压病等慢性疾病。"},{"t":"p","x":"3.对风湿性心脏病或心房颤动的患者，应进行规范的抗凝治疗。"}],"entries":["e0996"]}]},{"id":"d1304c","kind":"sub","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"糖尿病足","displayName":"脱疽·糖尿病足","parentId":"d1304","printedPage":291,"pdfPage":306,"syndromeCount":0,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"糖尿病足是指糖尿病患者由于合并神经病变及各种不同程度的血管病变而导致足部感染、溃疡形成和(或)深部组织的破坏。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病继发于消渴病。消渴病的病机以肝肾阴虚、气阴(血)两伤、燥热偏盛为主。"},{"t":"p","x":"消渴病病程迁延，一则阴损及阳，阴阳俱虚，多表现为脾肾阳虚；二则病久入络，血脉瘀阻。"},{"t":"p","x":"肝肾亏虚，阴虚燥热、热盛津伤可致血脉涩滞；气血不足则血行无力致血脉瘀阻；"},{"t":"p","x":"脾肾阳虚、阳不通，血不行致血脉瘀阻。此外、寒、痰、湿等病理产物及外邪也可痹阻脉络，致血脉瘀阻。"},{"t":"p","x":"气血津液无法敷布，最终导致经脉失养、脉络瘀阻，肌肉失养、进而导致了坏疽的发生。湿热邪毒相合，甚至可现内陷危象。"},{"t":"p","x":"总之、本病的病因病机不外标本两端、本虚是指久病消渴致脏腑、气血、阴阳亏虚，标实是指病久致瘀、致痰、致湿、化毒。基本病机为血脉瘀阻。"},{"t":"p","x":"西医学认为、糖尿病发生肢体坏死是神经病变、肢体缺血和感染三个因素共同作用所致。其中高血糖是基础、血管病变和神经病变是关键，感染是起因。"}],"entries":["e0997","e0998"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现除糖尿病本身的临床表现外，糖尿病足还表现为以下临床特点："},{"t":"p","x":"1)缺血早期皮肤瘙痒、干燥、弹性差，汗毛脱落，皮温降低，皮色苍白，色素沉着。"},{"t":"p","x":"趾甲生长缓慢、变形、肥厚、脆裂，失去光泽。下肢肌肉萎缩，肌张力差。"},{"t":"p","x":"患足发凉、怕冷、麻木、疼痛，在寒冷季节或夜间加重，趺阳脉、太溪脉明显减弱或不可触及，肢体抬高试验为阳性。"},{"t":"p","x":"2)感染足部或肢体远端局部软组织皮肤糜烂，初为水疱或浅溃疡，继之溃烂深入肌腱和肌层，破坏骨质，组织坏死腐烂，形成脓腔和窦道，排出秽臭分泌物，周围肿胀，以湿性坏疽为主。"},{"t":"p","x":"根据局部表现、坏疽可分为干性坏疽、湿性坏疽和混合性坏疽。干性坏疽：足部皮肤苍白、发凉，足趾发黑、变干，足趾疼痛。"},{"t":"p","x":"常发生于足及趾的背侧。此型在糖尿病足中较为少见。"},{"t":"p","x":"湿性坏疽：病位多在足底胼胝区、跖骨头、足跟、足背等足部压力支撑点和易摩擦处。病变程度不一、由浅表溃疡至严重坏疽，局部皮肤红肿；"},{"t":"p","x":"严重时伴有体温升高、恶心、腹胀等全身症状。此型为糖尿病足的主要类型。"},{"t":"p","x":"混合性坏疽：同一肢端的不同部位同时呈现干性坏疽和湿性坏疽。此型临床上较为多见。"},{"t":"p","x":"3)周围神经病变主要包括运动障碍足、无痛足和灼热足综合征。"},{"t":"p","x":"运动障碍足表现为某一神经支配区域感觉障碍和运动减弱或消失。"},{"t":"p","x":"无痛足是指袜套型感觉迟钝和麻木，同时伴有振动觉及精细触觉的减退。"},{"t":"p","x":"灼热足综合征表现为痛觉敏感，患处针刺样、刀割样、烧灼样疼痛，夜间或遇热时加重。"},{"t":"p","x":"4)夏科关节好发于足和踝关节，表现为软组织肿胀、轻微疼痛、跖骨头下陷、跖趾关节弯曲、关节半脱位畸形，形成弓形足、槌状趾、鸡爪趾。"},{"t":"p","x":"(2)辅助检查参照下肢动脉硬化闭塞症；"},{"t":"p","x":"还应做血常规、血糖、细菌培养和药敏、神经电生理检查，以及CT、MRI等。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-8)"},{"t":"table","img":"img/tab/t1308.jpg","cap":"表13-8糖尿病神经病变与其他神经病变的鉴别"},{"t":"p","x":"第十三章周图血管及淋巴管疾病"}],"entries":["e0999"]},{"title":"治疗","blocks":[{"t":"p","x":"应整体治本、局部治标，采取中西医结合综合治疗措施，药物疗法结合切开减压、清创、引流、血管介入手术等；治疗和护理、预防结合，控制病情发展，减少病残。"},{"t":"p","x":"注重内科支持治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"h","lv":3,"x":"(1)分型证治参照血栓闭塞性脉管炎辨证论治。"},{"t":"p","x":"(2)注意糖尿病足溃脓时常配合托法。"},{"t":"p","x":"如为脓出不畅实证，宜透托，方选透脓散加减；如见疮形平塌，根盘散漫，难溃难腐，或溃后脓水稀少，坚肿不消，并出现精神不振、面色无华、脉数无力等，可益气托毒，方选托里消毒散加减；"},{"t":"p","x":"如见疮形漫肿无头，疮色灰暗不泽，化脓迟缓，或局部肿势已退，腐肉已尽，而脓水灰薄，或偶带绿色，新肉不生，不知疼痛，伴自汗肢冷、腹痛便泄、精神萎靡、脉沉细、舌质淡胖、脉沉细等，可温阳托毒，方选神功内托散加减。"},{"t":"p","x":"2.外治疗法参照血栓闭塞性脉管炎外治。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)基础疾病的治疗针对糖尿病及其并发症采取相应的处理。"},{"t":"p","x":"(2)手术疗法"},{"t":"p","x":"1)切开减压湿性坏疽，脓液潴留，切开减压并通畅引流是首务。"},{"t":"p","x":"2)清创如为干性坏疽，坏死界限清楚，可采用鲸吞清创术，在麻醉下尽可能彻底地清除坏死组织。"},{"t":"p","x":"如为湿性坏疽，且切开减压后，可采用药刀结合蚕食清创方法。原则：①先清除远端坏死组织，再清除近端坏死组织；"},{"t":"p","x":"②液化的坏死组织应先清除，未液化的坏死组织后清除；"},{"t":"p","x":"③坏死皮肤、肌腱等软组织先清除，死骨后清除；"},{"t":"p","x":"④炎症完全消退或控制，坏死组织与健康组织分界明显后再做彻底清除，但应注意局部的血液供应状况。"},{"t":"p","x":"如为混合性坏疽，则鲸吞清创方法和药刀结合蚕食清创方法同用。其余参照血栓闭塞性脉管炎。"}]}],"entries":["e1000","e1001"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.积极治疗糖尿病、高血压、冠心病等慢性疾病。2.调节饮食，控制血糖。"},{"t":"p","x":"3.每日检查足部，做好足部的护理。4.建议使用专为糖尿病患者设计的用于减压的鞋子，穿鞋前要仔细检查鞋内有无异物，避免足部受到压迫。"},{"t":"p","x":"尽量使用棉袜。5.保持皮肤润滑，及时处理胼胝。"},{"t":"p","x":"修剪趾甲避免损伤，一旦出现足部外伤亦应及时处理。"}],"entries":["e1002"]}]},{"id":"d1305","kind":"main","chapterId":"ch13","chapterNo":"第十三章","chapterName":"周围血管及淋巴管疾病","name":"淋巴水肿","displayName":"淋巴水肿","parentId":"","printedPage":293,"pdfPage":308,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"淋巴水肿是淋巴液回流障碍导致淋巴液在皮下组织持续积聚，甚则引起纤维组织增生的一种慢性进展性疾病。"},{"t":"p","x":"其临床特点是好发于四肢，以下肢常见，表现为肢体肿胀，早期多呈凹陷性水肿，休息或患肢抬高后水肿减轻，后期患部皮肤及皮下组织纤维增生，汗腺、皮脂腺均遭到破坏，皮肤粗糙增厚，坚如象皮，故又称“象皮肿”，并可继发感染，形成溃疡，少数可恶变。"},{"t":"p","x":"清代王士雄《归砚录》载：“凡水乡农人多患脚气，俗名大脚风⋯⋯此因伤络瘀凝，气亦阻痹，风、湿、热杂合之邪，袭入而不能出也。”本病属于中医学“大脚风”“象皮腿”的范畴。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病主要是由于摄生不慎，久居湿地，寒湿之邪入侵，留恋不去，日久化热，流注下肢，阻塞经络；或脾虚水停，痰湿内生，阻遏气机，经络阻塞不通，气血瘀滞不行所致。"},{"t":"p","x":"初期多为脾虚寒湿阻络，湿热蕴滞；病程日久，则多为痰湿阻络，气滞血瘀。西医学认为，本病根据发病原因可分为两大类：①原发性淋巴水肿：由淋巴管发育异常所致。"},{"t":"p","x":"②继发性淋巴水肿：正常淋巴管因后天原因而阻塞，常见原因有感染、损伤及恶性肿瘤浸润或阻塞。"},{"t":"p","x":"淋巴管阻塞后所引起的病理变化大致相同、开始是阻塞远端的淋巴管扩张，瓣膜破坏，淋巴液淤积，由于淋巴液的蛋白含量较高而易凝结，有利于成纤维细胞的增生，因而皮内和皮下组织产生大量纤维、加重淋巴管的阻塞，脂肪组织被大量纤维组织代替，皮肤及皮下组织极度增厚。"}],"entries":["e1003","e1004"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现淋巴水肿的病因不同，临床表现各有其特点。"},{"t":"p","x":"1)原发性淋巴水肿"},{"t":"p","x":"早发性淋巴水肿：是原发性淋巴水肿中最常见的一种类型。30岁以下的青少年女性多见。"},{"t":"p","x":"起病初期肿胀局限于足及踝部，月经期时、长时间站立、劳累时水肿可加重。休息及患肢抬高后水肿则减轻。"},{"t":"p","x":"病变可向上蔓延至小腿，少数患者可达整个下肢。一般累及单侧肢体。"},{"t":"p","x":"病变后期肢体可明显增粗，皮肤、皮下组织增厚、变硬，但很少发生溃疡。遗传性淋巴水肿：在同一家庭中可有多人患此病。"},{"t":"p","x":"发病于出生后，常累及一侧肢体，往往局限在小腿以下。"},{"t":"p","x":"2)继发性淋巴水肿"},{"t":"p","x":"丝虫病性淋巴水肿：丝虫病在我国东南沿海地区较为流行，患者年龄在20～50岁之间，男性较多见。丝虫感染初期均有发热及局部胀痛等主要表现。"},{"t":"p","x":"反复的丝虫感染可使受累的淋巴管狭窄、闭塞，以致在后期出现淋巴水肿。细菌感染性淋巴水肿：有反复发作丹毒的病史，屡次发作后造成了淋巴管的阻塞，引起淋巴水肿，多见于下肢。"},{"t":"p","x":"初为凹陷性水肿，以后皮肤及皮下组织纤维增生，汗腺、皮脂腺遭到破坏，皮肤粗糙，硬如皮革。有时表面呈桑椹状，出现疣状增生物。"},{"t":"p","x":"有些患者的皮肤可裂开，渗出淋巴液。少数可发生慢性溃疡。"},{"t":"p","x":"肿瘤性淋巴水肿：淋巴系统恶性肿瘤和淋巴转移性肿瘤，可以阻塞淋巴管而发生淋巴水肿。水肿呈无痛性、进行性发展，初起于肢体近端，以后延伸到远端。"},{"t":"p","x":"有时原发灶小，不易发觉，而淋巴水肿却可以比较明显，因"},{"t":"img","src":"img/fig/f1302.jpg","alt":"图13-2乳腺癌术后淋巴水肿形成示意图"},{"t":"p","x":"此对于原因不明的淋巴水肿患者应注意肿瘤存在的可能性，必要时可行淋巴结活检。淋巴结清除术及放射治疗后淋巴水肿：临床上较常见的是乳腺癌根治术后引起的上肢淋巴水肿，一般在术后肢体开始活动时即有近侧上肢的轻度水肿(图13-2)。"},{"t":"p","x":"放射治疗，X线使组织纤维化，阻塞淋巴管，亦可引起淋巴水肿，可在术后数年发生。"},{"t":"p","x":"(2)辅助检查 ①X线淋巴管造影：是诊断淋巴系统疾病重要的检查手段之一。"},{"t":"p","x":"②放射性核素淋巴造影：可见到淋巴影迹增深、增粗、外渗、阻断、侧支形成征象。"},{"t":"p","x":"淋巴结转移者，还可见到淋巴结影迹增大。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表13-9)"},{"t":"table","img":"img/tab/t1309.jpg","cap":"表13-9淋巴水肿、全身疾病性水肿、深静脉血栓性水肿的鉴别"}],"entries":["e1005"]},{"title":"治疗","blocks":[{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s130501","name":"脾虚湿阻证","clinic":"患肢明显水肿，压之凹陷，不易随手而起，肿痛；舌淡胖，边有齿痕，苔白腻，脉濡","treat":"健脾利湿，活血通络","formula":"人参健脾丸合参苓白术散加减","formulaNames":["人参健脾丸","参苓白术散"]},{"t":"syn","sid":"s130502","name":"湿热下注证","clinic":"患肢皮肤焮红灼热，边界清楚，肿胀，疼痛；伴有寒战、发热，骨节酸痛；舌红，苔黄腻，脉滑数","treat":"清热利湿，活血消肿","formula":"萆薢渗湿汤合五神汤加减","formulaNames":["萆薢渗湿汤","五神汤"]},{"t":"syn","sid":"s130503","name":"痰瘀阻滞证","clinic":"患肢肿胀、增粗变硬，皮肤增厚、粗糙，按之即起，状如象皮；或伴有溃疡，久不愈合；可伴面色少华，乏力；舌淡暗或有瘀斑，苔薄白，脉弦涩或沉涩","treat":"健脾化痰，活血通络","formula":"桃红四物汤合四君子汤加减","formulaNames":["桃红四物汤","四君子汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)中药熏洗是常用的外治方法，适用于淋巴水肿患者。"},{"t":"p","x":"组成：桂枝10g，鸡血藤15g，金银花15g，苏木15g，红花15g，透骨草30g，千年健15g，乳香15g，没药15g，干姜15g，花椒10g，樟脑15g(分两次后下)。"},{"t":"p","x":"用法：将上药装入布口袋内，缝制好，撒以少量白酒或黄酒、用水2000mL煎汤，初煎可煮沸10分钟后，去火，以热气熏患处，待药液温度适宜时，再淋洗或泡洗患处；或将药袋置于患处热熨，待第二煎煮沸即可，用法同上。"},{"t":"p","x":"每剂用2天，每天1次，每次30分钟以上。"},{"t":"p","x":"(2)穴位贴敷配合黄芪、桂枝等中药贴敷，可增强疗效。"},{"t":"p","x":"3.其他疗法间歇性充气加压(intermittent pneumatic compression, IPC)被推荐作为辅助物理治疗手段。"},{"t":"p","x":"低水平激光治疗(low-level laser therapy,LLLT)可用于软化纤维化组织，改善淋巴回流。"}]}],"entries":["e1006","e1007","e1008","e1009","e1010"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.抬高患肢30°。下床活动时应穿松紧适宜的医用弹力袜，或用弹力绷带缠患肢，促进淋巴液回流。"},{"t":"p","x":"2.低盐、高蛋白、富含维生素饮食，控制体重，避免肥胖加重淋巴负担。急性期患者应注意减少进水量。"},{"t":"p","x":"3.积极预防丹毒、丝虫感染。"}],"entries":["e1011"]}]},{"id":"d1401","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"冻疮","displayName":"冻疮","parentId":"","printedPage":297,"pdfPage":312,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"冻疮是人体遭受寒邪侵袭所引起的局部或全身性损伤，临床上以暴露部位的局部性冻疮为常见。其临床特点是局部性冻疮以局部肿胀发凉、瘙痒、疼痛、皮肤紫斑或起水疱、溃烂，气候转暖后自愈、易复发；"},{"t":"p","x":"全身性冻伤以体温下降，四肢僵硬，甚则阳气厥脱为主要表现，严重者可危及生命。本病名始见于《诸病源候论·冻烂肿疮候》，曰：“严冬之月，触冒风雪，寒毒之气，伤于肌肤，血气壅涩，因即疡冻、焮赤疼肿，便成冻疮。"},{"t":"p","x":"局部性冻疮常根据受冻部位不同，分别称为“水浸足”“水浸手”“战壕足”“冻烂疮”等。本病相当于西医学的冻伤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病主因寒冷侵袭，外感风雪寒毒，血气壅涩，内因气血虚弱、阳气不足。潮湿、大风、久坐不动易诱发。"},{"t":"p","x":"寒性凝滞，损伤卫阳，致营卫失和，轻则血泣不通，营阴外溢，见水肿、水疱、痛痒而为冻疮；重则血脉闭阻，肌肤筋骨失养坏死。"},{"t":"p","x":"若瘀久化热或感邪毒，则热毒蕴结，肉腐成脓，溃烂成疮，损及筋骨。暴寒可致阳气厥脱，营卫结涩，危及生命。"},{"t":"p","x":"骤冷骤热亦致气血逆乱，营卫失调而坏死。西医学认为，寒冷使皮肤血管收缩、局部缺血缺氧、代谢失常，久之血管麻痹扩张、淤血、血浆渗出，引起局部组织水肿、水疱形成及组织坏死、溃疡形成。"}],"entries":["e1012","e1013"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现以儿童、妇女和末梢血液循环不良者多见。"},{"t":"p","x":"有在低温环境下长时间停留受冻史。"},{"t":"p","x":"1)局部性冻疮好发于四肢末端、面部和耳郭等暴露部位，多呈对称性。"},{"t":"p","x":"轻者初起患处苍白发凉、刺痛，继则出现红肿硬结或斑块，伴灼痛、麻木、瘙痒；重者皮肤呈灰白或紫暗，出现水(血)疱或肿块，疼痛剧烈或感觉迟钝、消失。"},{"t":"p","x":"若紫血疱破溃，则渗液流脓，形成溃疡，严重者可损伤肌肉、筋骨。根据冻疮复温解冻后的损伤程度，可将其分为以下4度。"},{"t":"p","x":"I度(红斑性冻疮)：损伤在表皮层。局部皮肤红斑、水肿，自觉发热、瘙痒或灼痛，5～7天开始干燥脱屑，愈后不留瘢痕。"},{"t":"p","x":"Ⅱ度(水疱性冻疮)：损伤达真皮层。皮肤红肿更加显著，有水疱或大疱形成，疱内液体色黄或呈血性。"},{"t":"p","x":"疼痛较剧烈，对冷、热、针刺感觉不敏感。若无感染，局部干燥结痂，2～3周脱痂愈合，一般无瘢痕。"},{"t":"p","x":"Ⅲ度(腐蚀性冻疮)：损伤达全皮层或深及皮下组织，创面由苍白变为黑褐色、皮肤温度极低，触之冰冷，痛觉迟钝或消失。一般呈干性坏疽，坏死皮肤周围红肿、疼痛，可出现血性水疱。"},{"t":"p","x":"若无感染，坏死组织干燥成痂，脱落后形成肉芽创面，愈合后遗留瘢痕。IV度(坏死性冻疮)：损伤深达肌肉、骨骼。"},{"t":"p","x":"表现类似Ⅲ度冻疮。局部组织坏死、分为干性坏疽和湿性坏疽。"},{"t":"p","x":"干性坏疽表现为坏死组织周围有炎症反应，肢端坏死脱落后可致残；并发感染后成湿性坏疽，可有发热、寒战等全身症状，甚至发生内陷而危及生命。"},{"t":"p","x":"2)全身性冻伤初起全身血管收缩、寒战；"},{"t":"p","x":"随后体温下降、患者出现肤色苍白、发绀、反应迟饨、乏力嗜睡；继而发展为肢体麻木、僵硬，视听障碍，意识模糊，呼吸浅快，脉搏细弱，知觉消失，甚至昏迷、心律失常，呼吸衰竭而死亡、需紧急救治。"},{"t":"p","x":"(2)辅助检查对于IV度冻疮，X线检查可评估骨坏死。"},{"t":"p","x":"出现湿性坏疽或合并肺部感染时，血常规及降钙素原升高可提示感染。创面脓液需行细菌培养及药敏试验以指导用药。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表14-1)"},{"t":"table","img":"img/tab/t1401.jpg","cap":"表14-1冻疮与雷诺综合征、类丹毒的鉴别"}],"entries":["e1014"]},{"title":"治疗","blocks":[{"t":"p","x":"本病治疗以温经散寒、补阳通脉为原则。I度、Ⅱ度冻疮以外治为主，Ⅲ度、IV度冻疮要内外合治。"},{"t":"p","x":"有坏疽者需手术清创，甚至截趾(指)。全身性冻伤要立即抢救复温，采取综合措施抢救。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140101","name":"寒凝血瘀证","clinic":"局部麻木冷痛，肤色青紫或暗红，肿胀结块，或有水疱，发痒，手足冰冷；舌淡苔白，脉沉或沉细","treat":"温经散寒，养血通脉","formula":"当归四逆汤或桂枝加当归汤加减。可加黄芪、丹参、红花","formulaNames":["当归四逆汤","桂枝加当归汤"]},{"t":"syn","sid":"s140102","name":"寒盛阳衰证","clinic":"时时寒战，四肢厥冷，感觉麻木，幻听幻视，意识模糊，蜷卧嗜睡，呼吸微弱，甚则神志不清；舌淡紫苔白，脉微欲绝","treat":"回阳救脱，散寒通脉","formula":"四逆加人参汤或参附汤加味","formulaNames":["四逆加人参汤","参附汤"]},{"t":"syn","sid":"s140103","name":"寒凝化热证","clinic":"冻伤后局部坏死，疮面溃烂流脓，四周红肿色暗，疼痛加重；伴发热口干；舌红苔黄，脉数","treat":"清热解毒，活血止痛","formula":"四妙勇安汤加味。热盛者，加蒲公英、紫花地丁；气虚者，加黄芪；疼痛甚者，加延胡索、炙乳香、炙没药等","formulaNames":["四妙勇安汤"]},{"t":"syn","sid":"s140104","name":"气虚血瘀证","clinic":"神疲体倦，气短懒言，面色少华，疮面不敛，疮周暗红漫肿，麻木；舌淡，苔白，脉细弱或虚大无力","treat":"益气养血，祛瘀通脉","formula":"人参养荣汤或八珍汤合桂枝汤加减","formulaNames":["人参养荣汤","八珍汤","桂枝汤"]},{"t":"p","x":"舌淡，苔白，脉细弱或虚大无力。治法：益气养血，祛瘀通脉。"},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)I度、Ⅱ度冻疮红肿痒痛、未溃者，可予云香精液、红灵酒或生姜辣椒酊等轻揉按靡，每日数次；"},{"t":"p","x":"或外涂冻疮膏或阳和解凝膏。有水疱者，局部消毒后放出疱液，外涂冻疮膏、红油膏或生肌白玉膏等。"},{"t":"p","x":"(2)Ⅲ度、IV度冻疮局部消毒抽吸疱液后用红油膏纱布包扎；"},{"t":"p","x":"溃烂者，用湿润烧伤膏外涂或制成油纱条，或红油膏掺八二丹外敷祛腐；后期可选用生肌药物如湿润烧伤膏、红油膏等生新；"},{"t":"p","x":"严重坏死者需手术清创。肢端坏疽界限清楚后可行截肢(趾、指)术。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)急救和复温全身性冻伤患者需迅速脱离寒冷环境，脱除湿冷衣物(冻结者待复温后处理)。"},{"t":"p","x":"用40～42℃温水浸泡患肢或浸浴全身15～30分钟，至皮温接近正常。可饮姜汤、糖水等温热饮料，必要时静脉输注温热(不超过37℃)的葡萄糖注射液、低分子右旋糖酐等。"},{"t":"p","x":"禁用雪搓、火烤或冷水浴。"},{"t":"p","x":"(2)西医治疗复温后防治休克、感染及器官衰竭，维持呼吸、循环稳定，纠正内环境紊乱；"},{"t":"p","x":"广泛Ⅱ度及以上冻疮需注射破伤风抗毒素。重症者加强营养支持，保护心、脑、肾功能。"}]}],"entries":["e1015","e1016","e1017","e1018","e1019","e1020","e1021"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强耐寒锻炼，冬天注重保暖防护，户外工作者穿戴防寒装备，尤其是加强手、足、耳、鼻等暴露部位的保护，涂抹防冻霜，户外作业时间不宜过长，应适当活动促进血液循环。2.冻疮未溃发痒时切忌用力搔抓，防止皮肤破伤感染。"}],"entries":["e1022"]}]},{"id":"d1402","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"烧伤","displayName":"烧伤","parentId":"","printedPage":299,"pdfPage":314,"syndromeCount":5,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"烧伤是由于热力(火焰、灼热的气体、液体或固体)、电能、化学物质、放射线等作用于人体而引起的一种急性损伤性疾病，常伤于局部，波及全身，可出现严重的全身性并发症。"},{"t":"p","x":"其临床特点是创面局部以红斑、肿胀、疼痛、水疱、渗出焦痂为主要表现，严重者伴有高热、烦躁不安、口渴喜饮、少尿或无尿，甚则呼吸浅快、神昏谵语，若不及时救治或治疗不当可危及生命。"},{"t":"p","x":"在古代一般以火烧和汤烫者居多，故又称为“水火烫伤”“汤火疮”“汤泼火伤”“火烧疮”等。本病西医学也称烧伤。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"热力直接损伤皮肤致局部气血凝滞、经络阻塞，营卫不从，卫失固护，营阴外渗而为水疱、渗出。轻则阴津亏耗，重则阴伤阳脱而致脱证；"},{"t":"p","x":"火毒内陷可攻脏腑而致陷证；后期多见脾胃虚弱和气血亏虚。"},{"t":"p","x":"总之，烧伤以热伤营卫为基本病机，阴津耗伤、阴伤阳脱、火毒内陷、脾胃虚弱和气血虚损为主要病机环节，且烧伤始终伴随着正邪交争、气血凝滞、经络阻塞、营卫失和、脏腑功能失调，以及渗出、腐、脓、毒、虚等的变化。重者可致死亡。"},{"t":"p","x":"西医学认为，烧伤因高温致组织变性坏死形成创面，严重者早期可出现低血容量性休克、在体液回吸收期引起脓毒血症，甚至多器官功能障碍导致死亡，深度创面需植皮修复。"}],"entries":["e1023","e1024"]},{"title":"辨病","blocks":[{"t":"p","x":"诊断有明确的烧伤史，诊断时应了解受伤原因及烧伤环境，根据烧伤面积、深度、部位、年龄、原因、有无复合伤及基础疾病等综合判断伤情。"},{"t":"p","x":"(1)临床表现轻度烧伤的面积较小，一般无全身表现，仅有局部皮肤潮红、肿胀，剧烈灼痛，或有水疱。"},{"t":"p","x":"重度烧伤面积大、烧伤深、多因火毒炽盛，入于营血，甚至内攻脏腑而出现严重的全身症状。病程一般分为三期："},{"t":"p","x":"1)早期(休克期)往往发生在烧伤后48小时之内，主要由体液大量渗出和剧烈疼痛引起。"},{"t":"p","x":"创面疼痛、水疱、焦痂和大量体液渗出；患者症见烦躁不安、口渴喜饮、呼吸短促、尿少等津伤之象；"},{"t":"p","x":"重者面色苍白，身疲肢冷、脉微欲绝，呈现气随津脱的亡阴亡阳危候。"},{"t":"p","x":"2)中期(感染期)此时创面出现坏死斑或出血点，脓腐增多，脓液黄稠腥臭或淡黄稀薄，或呈绿色；"},{"t":"p","x":"有焦痂者，焦痂软化潮湿，或痂下积脓；患者症见壮热烦渴，寒战，躁动不安，呼吸浅快，甚则神昏谵语，腹胀便秘，小便短赤，呈现“火毒内陷”的动态演变过程。"},{"t":"p","x":"此期可分为以下3个阶段："},{"t":"p","x":"①伤后3～7天的体液回吸收期：随着组织间液返回血管，火毒内陷(细菌进入血循环);"},{"t":"p","x":"②烧伤后2～4周焦痂自溶脱痂期：大量焦痂脱落，出现新鲜创面，创面继发感染；"},{"t":"p","x":"③烧伤1个月后的恢复期：患者消耗严重，气阴两伤，正气虚损，抵抗力低下，火热余毒乘虚内陷脏腑。"},{"t":"p","x":"3)后期(修复期)患者形体消瘦，神疲乏力，纳谷不香，腹胀便溏，低热盗汗，舌红或淡红，脉细或细弱无力。"},{"t":"p","x":"此期创面基本愈合，以“正虚余毒”为特点，深Ⅱ度烧伤愈合后留有轻度瘢痕。Ⅲ度烧伤愈合后产生大量瘢痕或畸形愈合；"},{"t":"p","x":"若创面较大，如不经植皮，多难愈合，有时可形成顽固性溃疡。"},{"t":"h","lv":3,"x":"(2)烧伤面积的计算"},{"t":"p","x":"1)中国新九分法按全身体表面积划分为11个9%的等份，另加1%，构成100%的体表面积。"},{"t":"p","x":"即成人头、面、颈部为9%，双上肢为2×9%，躯干前后包括会阴部为3×9%，双下肢包括臀部为5×9%+1%=46%(图14-1、表14-2)。"},{"t":"h","lv":3,"x":"1.5"},{"t":"h","lv":3,"x":"1.5"},{"t":"h","lv":3,"x":"4.25"},{"t":"h","lv":3,"x":"1.25"},{"t":"h","lv":3,"x":"5.25: 5.25"},{"t":"h","lv":3,"x":"3.25 3.25"},{"t":"h","lv":3,"x":"1.75_"},{"t":"img","src":"img/fig/f1401.jpg","alt":"图14-1烧伤面积计算中国新九分法"},{"t":"table","img":"img/tab/t1402.jpg","cap":"表14-2烧伤面积计算中国新九分法"},{"t":"p","x":"*成人女性的臀部和双足各占6%。"},{"t":"p","x":"2)手掌法不论性别、年龄，患者并指的掌面约占体表面积的1%。"},{"t":"p","x":"如医者的手掌大小与患者相近，可用医者手掌估算(图14-2)。此法可辅助九分法，用于小面积或散在烧伤面积的计算。"},{"t":"p","x":"3)儿童烧伤面积计算法小儿的躯干和双上肢的体表面积所占百分比与成人相似，特点是头大下肢小；"},{"t":"p","x":"随着年龄的增长，其比例也不同。12岁以下儿童，年龄越小，头越大，下肢越小。"},{"t":"p","x":"可按下法计算：头面颈部面积百分比：[9+(12-年龄)]%双下肢包括臀部面积百分比：[46-(12-年龄)]%"},{"t":"p","x":"(3)烧伤深度的判断目前临床上有多种分法，最常用的是三度四分法(图14-3、表14-3)，即I度、Ⅱ度(又分为浅Ⅱ度和深Ⅱ度)、Ⅲ度。"},{"t":"p","x":"其中I度、浅Ⅱ度烧伤一般称为浅度烧伤，深Ⅱ度和Ⅲ度烧伤则属深度烧伤。浅深"},{"t":"p","x":"度度度度"},{"t":"img","src":"img/fig/f1402.jpg","alt":"图14-2手掌法"},{"t":"img","src":"img/fig/f1403.jpg","alt":"图14-3三度四分法"},{"t":"table","img":"img/tab/t1403.jpg","cap":"表14-3烧伤深度识别(三度四分法)"},{"t":"p","x":"I度烧伤一般不计算烧伤面积，但烧伤的深度可因时间、条件而继续发展，如在烧伤后48小时左右，I度烧伤可因组织反应继续进行而转变为浅Ⅱ度；同时，烧伤创面由于副损伤、创面感染及处理不当等可加深创面。"},{"t":"p","x":"因此，在烧伤48小时后和创面愈合过程中，应分别对损伤深度重新复核。"},{"t":"p","x":"(4)烧伤伤情的判断应根据面积、深度、部位、年龄、原因及有无复合伤和基础疾病等综合判断、最基本的两个方面是烧伤面积和深度。"},{"t":"p","x":"烧伤面积越大、越深就越严重，反之则轻。为了对烧伤严重程度有一个基本估计，作为设计治疗方案的参考，可采用下表的分度方法(表14-4):"},{"t":"table","img":"img/tab/t1404.jpg","cap":"表14-4烧伤伤情分度"},{"t":"p","x":"注：已经发生休克等并发症、呼吸道烧伤或有较重的复合伤均属重度烧伤。已有严重并发症者属特重烧伤。"},{"t":"p","x":"(5)辅助检查 ①血、尿常规检查：烧伤后常出现白细胞计数上升和中性粒细胞比例增高，并出现中毒颗粒；"},{"t":"p","x":"大面积或中等程度以上烧伤早期可出现血液浓缩现象；血浆中游离血红蛋白升高，常出现血红蛋白尿。"},{"t":"p","x":"②血液生化检查：休克时可出现电解质紊乱、低蛋白血症、酸中毒等，肝、肾功能出现继发性损害时可出现异常。"},{"t":"p","x":"③创面分泌物及血培养加药物敏感试验可明确感染病原菌及敏感药物。"},{"t":"p","x":"④降钙素原测定可作为感染严重程度的参考指标之一。"},{"t":"p","x":"⑤血气分析、心电图等可作为烧伤后的监测指标。"}],"entries":["e1025"]},{"title":"治疗","blocks":[{"t":"p","x":"小面积轻度烧伤可单用外治法。大面积重度烧伤必须内外兼治，中西医结合治疗。"},{"t":"p","x":"内治以清热解毒、益气养阴为主；外治在于正确处理烧伤创面，保持创面清洁，预防和控制感染。"},{"t":"p","x":"对于深度烧伤，多需手术切(削)痂，必要时植皮以促进创面愈合，减少瘢痕形成。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140201","name":"火毒伤津证","clinic":"烧伤后出现壮热烦躁，口干喜饮，便秘尿赤；舌红绛而干，苔黄或黄糙、或舌光无苔，脉洪数或弦细数","treat":"清热解毒、益气养阴","formula":"白虎加人参汤加减。口干甚者，加鲜石斛、天花粉；便秘加生大黄；尿赤加白茅根、淡竹叶等","formulaNames":["白虎加人参汤"]},{"t":"p","x":"舌红绛而干，苔黄或黄糙、或舌光无苔，脉洪数或弦细数。治法：清热解毒、益气养阴。"},{"t":"syn","sid":"s140202","name":"阴伤阳脱证","clinic":"烧伤后出现神疲倦卧，面色苍白，呼吸气微，表情淡漠，嗜睡，自汗肢冷，体温不高反低，尿少；全身或局部水肿，创面大量液体渗出；舌淡暗，苔灰黑，或舌淡嫩，无苔，脉微欲绝或虚大无力","treat":"回阳救逆，益气护阴","formula":"四逆汤、参附汤合生脉散加味。冷汗淋漓者，加煅龙骨、煅牡蛎、黄芪、白芍、炙甘草等","formulaNames":["四逆汤","参附汤","生脉散"]},{"t":"syn","sid":"s140203","name":"火毒内陷证","clinic":"烧伤后壮热不退，口干唇燥，躁动不安，大便秘结，小便短赤；舌红绛而干，苔黄或黄糙，或焦干起刺，脉弦数。若火毒传心，可见烦躁不安，神昏谵语；若火毒传肺，可见呼吸气粗，鼻翼扇动、咳嗽痰鸣，痰中带血；若火毒传肝，可见黄疸，双目上视，痉挛抽搐；若火毒传脾，可见腹胀便结，便溏黏臭，恶心呕吐，不思饮食，或有呕血、便血；若火毒传肾，可见浮肿，尿血或尿闭","treat":"清营凉血，清热解毒","formula":"清营汤或犀角地黄汤加减。神昏谵语者，加服安宫牛黄丸或紫雪丹；气粗咳喘加生石膏、知母、贝母、桔梗、鱼腥草、桑白皮、鲜芦根；抽搐加羚羊角粉(冲)、钩藤、石决明；腹胀便秘、恶心呕吐者，加大黄、玄明粉、枳实、厚朴、大腹皮、木香；呕血、便血者，加地榆炭、侧柏炭、槐花炭、白及、三七、藕节炭；尿少或尿闭者，加白茅根、车前子、泽泻；血尿加大小蓟、黄柏炭、琥珀等","formulaNames":["清营汤","犀角地黄汤"]},{"t":"syn","sid":"s140204","name":"气血两虚证","clinic":"疾病后期，火毒渐退，低热或不发热，精神疲倦，气短懒言，形体消瘦，面色无华，食欲不振，自汗盗汗；创面肉芽色淡，愈合迟缓；舌淡，苔薄白或薄黄，脉细弱","treat":"补气养血，兼清余毒","formula":"托里消毒散加减。食欲不振者，加神曲、麦芽、鸡内金、薏苡仁、砂仁","formulaNames":["托里消毒散"]},{"t":"syn","sid":"s140205","name":"脾虚阴伤证","clinic":"疾病后期，火毒已退，脾胃虚弱，阴津耗损，面色萎黄，纳呆食少，腹胀便溏，口干少津，或口舌生糜；舌暗红而干，苔花剥或光滑无苔，脉细数","treat":"补气健脾，益胃养阴","formula":"益胃汤合参苓白术散加减","formulaNames":["益胃汤","参苓白术散"]},{"t":"p","x":"舌暗红而干，苔花剥或光滑无苔，脉细数。治法：补气健脾，益胃养阴。"},{"t":"p","x":"2.外治疗法烧伤后先进行现场急救、清创，然后根据创面深浅、大小、部位等、选用包扎、暴露等疗法。烧伤发生于四肢或面积较小者，一般采用包扎疗法；"},{"t":"p","x":"发生于头面、会阴，或面积较大，或伴有明显感染者，多采用暴露疗法。烧伤外治的中药较多，如紫草油膏、京万红油膏、石榴皮煎液等，适用于轻度表浅烧伤的处理，可根据临床实际选用。"},{"t":"p","x":"(1)浅度烧伤重点在防止感染。"},{"t":"p","x":"小面积创面可外涂湿润烧伤膏、紫草油膏等、暴露或包扎。较大面积的Ⅱ度烧伤，如水疱完整，则抽出疱内液体；"},{"t":"p","x":"如皮肤破损或水疱已破者、则剪去破损疱皮、外用湿润烧伤膏，每日数次。"},{"t":"p","x":"(2)深度烧伤小面积创面可外涂湿润烧伤膏、紫草油膏、生肌白玉膏等；"},{"t":"p","x":"渗出较多或感染时用三黄洗剂外洗或湿敷；创面有坏死组织时需药刀结合蚕食清创；"},{"t":"p","x":"大面积深度创面应早期切痂、削痂植皮，或培植肉芽后植皮。"},{"t":"p","x":"(3)烧伤湿性医疗技术以湿润烧伤膏为治疗药物、以湿润暴露疗法为治则，以启动自身潜能再生细胞、原位干细胞培植皮肤为核心的一项技术，是现代治疗烧伤的重要方法之一。"},{"t":"p","x":"其将烧伤组织置于生理湿润环境下，以液化方式排除创面坏死组织，通过烧伤湿性医疗技术激活皮肤自身潜能再生细胞，实现原位培植皮肤组织；通过原位干细胞培植或组织培植的方式使皮肤等组织再生，以达到使烧伤创面愈合的目的。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)现场急救目标是尽快消除致伤原因，脱离现场，以及采取挽救生命的救治措施。"},{"t":"p","x":"包括迅速脱离热源、保护受伤部位，维护呼吸道通畅等。注意有无复合伤，对大出血、开放性气胸、骨折等，应施行相应的急救处理。"},{"t":"p","x":"(2)转送对重度烧伤患者简单包扎后，尽快建立静脉输液通道抗休克，保持呼吸道通畅，必要时行气管插管或切开，送至就近医院救治。"},{"t":"p","x":"大面积严重烧伤早期应避免长途转送，提倡送至就近医院治疗并请上级医院提供技术支持。"},{"t":"p","x":"(3)休克的防治轻度烧伤一般不发生休克。"},{"t":"p","x":"烧伤病情越严重，休克出现就越早、越重。严重烧伤多在烧伤后6～12小时发生休克，特重度烧伤可在伤后2小时发生休克。"},{"t":"p","x":"因烧伤早期休克基本上是低血容量性休克，故处理宜补充平衡盐溶液和血浆等。"},{"t":"p","x":"(4)全身性感染的防治包括：及时而积极地纠正休克，维护机体的防御功能，保护肠黏膜的组织屏障；正确处理创面；"},{"t":"p","x":"根据创面培养及药敏结果合理选择抗菌药物；营养支持疗法等。"},{"t":"p","x":"(5)营养支持严重烧伤后，机体代谢反应和能量消耗相应增加。"},{"t":"p","x":"同时，烧伤创面的修复也需要更多的营养补充。因此，营养支持是烧伤治疗的重要组成部分。"},{"t":"p","x":"(6)防瘢处理及功能锻炼深度创面愈合后须穿量身定做的弹力套防瘢痕，必要时行后期瘢痕整形治疗，同时宜早期行关节等功能部位的康复锻炼。"},{"t":"p","x":"(7)心理干预与人文关怀对于大面积烧伤患者需尽早进行心理干预，使患者能够逐步适应创伤后的生活，重建信心，最终返回社会。"}]}],"entries":["e1026","e1027","e1028","e1029","e1030","e1031","e1032"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.加强劳动保护，开展防火、安全用电等知识的宣传教育。烧伤病房要定时通风，保持清洁，限制人员进出以防交叉感染，接触患者的敷料、被单、物品等注意灭菌。"},{"t":"p","x":"2.精心护理，勤翻身，防止创面长期受压。烧伤创面愈合后，暴露部位1个月内避免阳光直晒，以免加重色素沉着。"},{"t":"p","x":"深度烧伤创面愈合后期，注意加强功能锻炼及防瘢治疗。"}],"entries":["e1033"]}]},{"id":"d1403","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"毒蛇咬伤","displayName":"毒蛇咬伤","parentId":"","printedPage":304,"pdfPage":319,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"毒蛇咬伤是指人体被毒蛇咬伤，其毒液由伤口进入人体内而引起的一种急性全身性中毒性疾病。"},{"t":"p","x":"本病发病急，变化快，若不及时救治，常可危及生命。我国每年被毒蛇咬伤者为10万～30万人次，其发病率在南方地区较高。"},{"t":"p","x":"目前我国已发现蛇类300余种，其中毒蛇100余种，剧毒蛇有10余种。每种毒蛇可同时含有多种不同毒素，根据毒素对机体的效应分为神经毒素、血液毒素和细胞毒素。"},{"t":"p","x":"毒素成分的多少或有无随蛇种而异。常见毒蛇按所含主要毒素分类：①神经毒类蛇：银环蛇、金环蛇、眼镜王蛇和海蛇等；"},{"t":"p","x":"②血液毒类蛇：尖吻蝮蛇、竹叶青蛇、蝮蛇、蝰蛇、原矛头蝮蛇等；"},{"t":"p","x":"③细胞毒类蛇：中华眼镜蛇等。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"1.中医病因病机《普济方·蛇伤》载：“夫蛇，火虫也、热气炎极，为毒至甚。”蛇毒系风、火二毒。"},{"t":"p","x":"风者善行数变，火者生风动血、耗伤阴津。风毒偏盛，每多化火；火毒炽盛，极易生风。"},{"t":"p","x":"风火相煽则邪毒鸱张，必客于营血或内陷厥阴，形成严重的全身性中毒症状(图14-4)。"},{"t":"p","x":"(1)风毒风为阳邪、其性开泄、易袭阳位。"},{"t":"p","x":"风邪侵入人体，先中经络，肌肉失去气血濡养，可见眼睑下垂、张口困难、颈项不适等；风毒深入脏腑，气血逆乱，上冲于脑，可致烦躁、神志不清等。"},{"t":"p","x":"(2)火毒心主火，心主血脉、火毒之邪最易归心。"},{"t":"p","x":"热盛肉腐，肉腐成脓，可见肿胀、坏死、溃烂；火毒可耗血动血，迫血妄行，致皮下瘀斑及各种出血；"},{"t":"p","x":"继而热扰心神，出现烦躁不安、惊厥、昏迷等。"},{"t":"p","x":"(3)风火毒风助火势，火可生风。"},{"t":"p","x":"风者善行数变，痹阻经络，深中脏腑；火者生风动血、耗伤津液。风火相煽则邪毒鸱张，可耗血动血，出现溶血、出血症状；"},{"t":"p","x":"热极生风，则有谵语、抽掐等症状。"},{"t":"img","src":"img/fig/f1404.jpg","alt":"图14-4毒蛇咬伤的病因病机示图"},{"t":"h","lv":3,"x":"2.西医病因病理"},{"t":"p","x":"(1)蛇毒的一般理化性质蛇毒是一种复杂的蛋白质混合物，含有多种毒蛋白和酶类物质。"},{"t":"p","x":"新鲜毒液黏稠、透明或淡黄色，含水65%～85%，比重1.030～1.080，加热至65℃以上易被破坏。"},{"t":"p","x":"新鲜蛇毒呈弱酸性，腥苦味，与空气接触易生泡沫，在常温下24小时变性，冰箱内保存15～30天毒性不变，干燥蛇毒可保持原毒力25年以上。凡能使蛋白质沉淀、变性的强酸、强碱、氧化剂、还原剂、消化酶及重金属盐类，均能破坏蛇毒。"},{"t":"h","lv":3,"x":"(2)蛇毒的有毒成分"},{"t":"p","x":"1)神经毒主要为α-神经毒素和β-神经毒素等，前者竞争乙酰胆碱受体，后者抑制乙酰胆碱释放，阻滞神经-肌肉接头而引起弛缓性麻痹，表现为眼睑下垂、吞咽困难，继而呼吸肌麻痹、呼吸衰竭。"},{"t":"p","x":"2)血液毒血液毒种类繁多，成分复杂，具有强烈的溶组织、溶血和抗凝作用，导致出凝血功能障碍，表现为各种出血。"},{"t":"p","x":"蛇毒蛋白酶：直接或间接作用于血管壁，破坏血管壁的相关结构，诱导缓激肽、组胺、5-羟色胺等释放，直接损害毛细血管内皮细胞，抑制血小板聚集。蛇毒溶血因子：直接作用于血细胞膜，使其渗透性和脆性增加。"},{"t":"p","x":"磷脂酶A：水解血液中的卵磷脂而成为溶血卵磷脂，产生溶血作用。蛇毒促凝因子：促使血液凝固和微循环血栓形成，继而引起弥散性血管内凝血(disseminatedintravascular coagulation, DIC)。"},{"t":"p","x":"类凝血酶：具有类似凝血酶的活性，既可促进纤维蛋白单体生成、又可激活纤溶系统、在蛇毒纤维蛋白溶解酶的共同作用下，引起去纤维蛋白血症，亦称类DIC反应。"},{"t":"p","x":"3)细胞毒"},{"t":"p","x":"蛋白质水解酶：损害血管壁内皮细胞，增加管壁的通透性，导致血浆外渗、组织水肿、局部肌肉坏死，甚至深部组织溃烂。"},{"t":"p","x":"心脏毒：可致细胞破坏、组织坏死，轻者局部肿胀，严重者出现皮肤、肌肉大片坏死、可深达筋膜、肌肉和骨膜，导致患肢功能障碍，还可直接引起心肌损害、甚至心肌细胞变性坏死、导致心搏动障碍、心室纤颤、心肌坏死，最终导致心力衰竭。"},{"t":"p","x":"透明质酸酶：溶解细胞与纤维间质、破坏结缔组织的完整性，促使蛇毒从咬伤局部向其周围迅速扩散、吸收。"},{"t":"p","x":"(3)蛇毒的体内过程毒蛇咬人时，其毒液通过管状或沟状的毒牙注入人体皮下组织，主要由淋巴吸收再进入血液循环分布全身，分子较小的神经毒等也可直接进入血液循环被吸收。"},{"t":"p","x":"蛇毒不能穿透完好的皮肤和黏膜、但黏膜在蛇毒作用下发生炎症反应后吸收蛇毒；蛇毒还可以通过原有炎症、破损或有溃疡的黏膜。"},{"t":"p","x":"蛇伤早期，咬伤局部毒素比较集中、浓度相对较高，故可借助其中的透明质酸酶的作用，使之易于扩散、穿透及吸收。"}],"entries":["e1034","e1035"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)病史"},{"t":"p","x":"咬伤的时间：询问患者被蛇咬伤的具体日期、时间、治疗经过。咬伤的地点及蛇之形态：根据不同蛇类活动的地点，结合患者所诉的蛇之形态，协助判断蛇的种类。"},{"t":"p","x":"咬伤的部位：注意咬伤部位并与其他因皮炎、疖肿、外伤所致的皮损区别开。患者神志清楚时，问诊一般不难；"},{"t":"p","x":"如患者神志不清，或局部症状不明显，则需认真查找并鉴别伤口的部位及性质，同时了解院前急救的处理情况。宿因：应着重询问伤者是否有其他系统的慢性疾病史，特别应询问是否有肝炎、肾炎、高血压、心脏病等，以判断患者预后。"},{"t":"p","x":"(2)局部症状被毒蛇咬伤后，患部一般有较大而深的牙痕，不同毒蛇咬伤的牙痕各有特点(图14-5)。"},{"t":"p","x":"神经毒类蛇咬伤：局部不红不肿，无渗液，微痛，或麻木。常易被忽视而得不到及时处理。"},{"t":"p","x":"血液毒类蛇咬伤：伤口出血不止，肢体肿胀、疼痛，皮下出血、瘀斑，并可出现水疱、血疱。细胞毒类蛇咬伤：局部剧痛，伤口周围皮肤迅速肿胀，可扩展至整个肢体，常有水疱，严重者迅速变黑坏死，形成溃疡。"},{"t":"img","src":"img/fig/f1405.jpg","alt":"图14-5毒蛇与无毒蛇的特征鉴别"},{"t":"h","lv":3,"x":"(3)全身症状"},{"t":"p","x":"神经毒类蛇咬伤：主要表现为神经系统受损害，多在咬伤后1～6小时出现症状。"},{"t":"p","x":"轻者有头晕、胸闷、四肢无力等，严重者出现瞳孔散大、视物模糊、言语不清、牙关紧闭、吞咽困难、昏迷、呼吸减弱或停止、脉象迟弱或不整、血压下降，最后呼吸麻痹而死亡。"},{"t":"p","x":"血液毒类蛇咬伤：主要表现为血液系统受损害，出现寒战发热、全身肌肉酸痛、皮下和/或内脏出血(尿血、血红蛋白尿、便血、衄血和/或吐血)，继而可以出现贫血、黄疸等；严重者可出现休克、循环衰竭。"},{"t":"p","x":"细胞毒类蛇咬伤：主要表现为继发性心肌损害，出现心功能不全：横纹肌溶解可出现肌红蛋白尿合并肾功能不全；病情恶化可出现全身炎症反应综合征，甚至多器官功能障碍综合征。"},{"t":"p","x":"(4)辅助检查主要包括血常规、尿常规及24小时尿量、凝血功能、血生化(包括心肌酶、肝肾功能、血糖等)、电解质系列、血气分析等，另外应注意观察心电图、肌电图、胸部X线检查等有无异常。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表14-5)"},{"t":"table","img":"img/tab/t1405.jpg","cap":"表14-5毒蛇咬伤与无毒蛇咬伤、蜂篮伤、蜈蚣咬伤的鉴别"}],"entries":["e1036"]},{"title":"治疗","blocks":[{"t":"p","x":"毒蛇咬伤是一种严重疾患，在咬伤早期能否及时有效地进行抢救和处理，影响到病情转归和预后。"},{"t":"p","x":"内外并治、排毒解毒、防毒内陷扩散为本病的治疗宗旨。"},{"t":"h","lv":3,"x":"1.急救"},{"t":"p","x":"(1)脱离、解压被毒蛇咬伤后，应保持镇定，立即远离被蛇咬伤的地方，切勿企图捕捉或追打蛇；"},{"t":"p","x":"去除患部的各种受限物品，以免因后续肿胀而无法取出。"},{"t":"p","x":"(2)制动、包扎患肢制动并下垂，以减少毒素的吸收和扩散。"},{"t":"p","x":"神经毒类蛇咬伤推荐使用绷带加压固定法或加压垫法对患肢进行包扎固定；止血带、绳索等传统绑扎方法可能增加局部毒素的吸收，显著增加肢体坏死风险，不推荐使用。"},{"t":"p","x":"(3)冲洗、清创早期可采用清水或生理盐水等反复冲洗伤口，以洗去周围黏附的毒液。"},{"t":"p","x":"常规消毒后，沿牙痕纵行切开1.5cm，或做“十”字形切口，深达皮下，如有毒牙遗留应取出，同时以过氧化氢溶液反复多次冲洗，使伤口处蛇毒被破坏，并促进局部排毒。"},{"t":"p","x":"但须注意，若被尖吻蝮蛇、蝰蛇咬伤后，伤口流血不止，且有全身出血现象，则不宜扩创，以免发生失血性休克。"},{"t":"p","x":"(4)针刺、火罐排毒患肢肿胀明显时，可于手指蹼间(八邪穴)或足蹼间(八风穴)皮肤消毒后，用三棱针或粗针头与皮肤平行刺入约1cm，迅速拔出后将患肢下垂，并由近心端向远端挤压以排除毒液；"},{"t":"p","x":"但被蝰蛇、尖吻蝮蛇咬伤时应慎用，以防出血不止。或在患肢肿胀最明显处，消毒后散刺数个针眼，避开血管及神经，然后用火罐吸附于点刺部位，留罐5～10分钟，以达到减轻局部肿胀和促进蛇毒排泄的作用。"},{"t":"p","x":"(5)封闭疗法毒蛇咬伤后及早应用利多卡因溶液加胰蛋白酶局部环封。"},{"t":"p","x":"方法：胰蛋白酶2000U加入1%利多卡因5～20mL中，在牙痕中心及周围做浸润注射或在肿胀部位上方做环状封闭。"},{"t":"p","x":"(6)局部用药经排毒方法治疗后，可用0.02%呋喃西林溶液或0.1%乳酸依沙吖啶溶液湿敷伤口，保持湿润引流，以防创口闭合。"},{"t":"p","x":"同时可用鲜草药外敷，如半边莲、马齿苋、七叶一枝花、八角莲、蒲公英、芙蓉叶等。敷药时不可封住伤口，以防阻碍毒液流出，保持药物新鲜与湿润、避免局部感染；"},{"t":"p","x":"还可用内服的蛇药片捣碎水调外涂。对已有水疱或血疱者，可先用无菌注射器吸出渗出液、再进行湿敷。"},{"t":"p","x":"(7)口服解毒药金银花、野菊花、蒲公英、紫花地丁、车前草、半枝莲、半边莲、甘草、七叶一枝花，选择上药数味水煎口服，或一次性口服食醋150～200mL。"},{"t":"p","x":"2.辨证论治根据“治蛇不泄，蛇毒内结、二便不通，蛇毒内攻”的原则，采用祛风解毒、凉血止血、利尿通便的治法。"},{"t":"h","lv":3,"x":"(1)风毒证"},{"t":"p","x":"证候：局部伤口不红不肿不痛、仅有皮肤麻木感；"},{"t":"p","x":"全身症状有头昏、眼花、嗜睡、气急，严重者呼吸困难、四肢麻痹、张口困难、眼睑下垂、神志模糊甚至昏迷；舌苔薄白，舌质红，脉弦数。"},{"t":"p","x":"治法：活血通络，驱风解毒。"},{"t":"p","x":"方药：活血驱风解毒汤加减(经验方)。"},{"t":"p","x":"早期，加车前草、泽泻、木通等利尿排毒；大便不畅，加生大黄、厚朴通便泄毒；"},{"t":"p","x":"咬伤在下肢加独活，咬伤在上肢加羌活，作为引经之药；视物模糊，瞳孔散大，加青木香、菊花；"},{"t":"p","x":"动风抽搐，加蜈蚣、蝉蜕、全蝎以搜风镇惊。"},{"t":"h","lv":3,"x":"(2)火毒证"},{"t":"p","x":"证候：局部肿痛严重，伴有水疱、血疱或瘀斑，严重者出现局部组织坏死；"},{"t":"p","x":"全身症状可见恶寒发热、烦躁、咽干口渴、胸闷心悸、胁肋胀痛、大便干结、小便短赤或尿血；舌质红，苔黄，脉滑数。"},{"t":"p","x":"治法：泻火解毒，凉血活血。"},{"t":"p","x":"方药：龙胆泻肝汤合五味消毒饮加减。"},{"t":"p","x":"小便短赤、血尿，加白茅根、茜草、车前草、泽泻等利尿止血；发斑、吐血、衄血，加犀角(水牛角代)以加强凉血化斑解毒之功；"},{"t":"p","x":"烦躁抽搐，加羚羊角、钩藤以凉肝息风；局部肿胀甚，加赤小豆、冬瓜皮、泽泻以利水消肿。"},{"t":"h","lv":3,"x":"(3)风火毒证"},{"t":"p","x":"证候：局部肿胀较重，一般多有创口剧痛，或有水疱、血疱、瘀斑、瘀点或伤处溃烂；"},{"t":"p","x":"全身症状有头晕、头痛、眼花、寒战发热、胸闷心悸、恶心呕吐、大便秘结、小便短赤，严重者烦躁抽搐，甚至神志昏愦；舌苔白黄相兼，后期苔黄，舌质红，脉弦数。"},{"t":"p","x":"治法：清热解毒，凉血息风。"},{"t":"p","x":"方药：黄连解毒汤合五虎追风散加减。"},{"t":"p","x":"吞咽困难，加玄参、山豆根、射干以清热利咽；烦躁不安或抽搐，加羚羊角、钩藤、珍珠母以镇静安神息风；"},{"t":"p","x":"瞳孔缩小，视物模糊，加青木香、菊花；神志昏愦，加服安宫牛黄丸。"},{"t":"h","lv":3,"x":"(4)蛇毒内陷证"},{"t":"p","x":"证候：毒蛇咬伤后失治误治，出现高热、躁狂不安、惊厥抽搐或神昏谵语；"},{"t":"p","x":"局部伤口由红肿突然变成紫暗或紫黑，肿势反而稍减；舌质红绛，脉细数。"},{"t":"p","x":"治法：清营凉血解毒。"},{"t":"p","x":"方药：清营汤加减。"},{"t":"p","x":"神昏谵语、痉厥抽搐者，加服安宫牛黄丸或紫雪丹，若正气耗散，正不胜邪，导致心阳衰微，出现面色苍白、淡漠神昏、汗出肢冷，则宜用参附汤以益气回阳。"},{"t":"h","lv":3,"x":"3.外治疗法"},{"t":"p","x":"(1)初起蛇伤外敷散(经验方，由七叶一枝花、雄黄、五灵脂、天南星、川芎、黄柏、白芷、明矾、芒硝等9种药物组成)外敷。"},{"t":"p","x":"功用：清热解毒，消肿止痛。用法：将上药研成粉末，醋调外搽患处，每日3次。"},{"t":"p","x":"适用于毒蛇咬伤致局部肿痛者，但局部溃烂严重者禁用。"},{"t":"p","x":"(2)溃后后期形成的蛇伤溃疡宜扩创引流、用八二丹或九一丹药线引流，外敷金黄膏，待脓净后改用生肌玉红膏掺生肌散外敷。"},{"t":"h","lv":3,"x":"4.其他疗法"},{"t":"h","lv":3,"x":"(1)中成药季德胜蛇药片、蛇伤解毒片口服，首次剂量加倍。"},{"t":"p","x":"(2)隔蒜灸将约0.3cm厚、直径4～5cm的独头蒜(用针扎孔数个)置于创口或咬伤处，上置圆锥形艾炷，点燃灸之、每次灸3～5壮，每日灸3次，连续3日。"},{"t":"p","x":"适用于毒蛇咬伤早期。"},{"t":"p","x":"(3)中药熏洗选择具有活血通络、利湿消肿作用的中药(如刘寄奴、苏木、威灵仙、红花、冰片、明矾、伸筋草、透骨草等)熏洗患处。"},{"t":"p","x":"操作方法：将中药装入纱布袋，加入清水进行煎煮，煎出药液2～3L，过滤药渣、将药液倒入熏洗盆中，先熏蒸30分钟，再浸泡肢体20分钟，每日1次。适用于毒蛇咬伤肢体肿胀、关节功能活动受限者。"},{"t":"h","lv":3,"x":"5.西医治疗"},{"t":"h","lv":3,"x":"(1)一般治疗适当予以补液，维持水、电解质平衡。"},{"t":"p","x":"(2)抗蛇毒血清特异性高，效果确切，应用越早疗效越好。"},{"t":"p","x":"但对脑、心、肾等实质性器官已发生器质性改变者，则难以奏效。使用剂量的多少应根据该血清的效价和该种毒蛇排毒量来决定，一般应大于中和排毒量所需要的剂量。"},{"t":"p","x":"同时可配合使用糖皮质激素，如氢化可的松、地塞米松等，减轻过敏反应。"},{"t":"p","x":"(3)破伤风抗毒素、马破伤风免疫球蛋白毒蛇口腔及毒牙内可能带有破伤风梭菌，可使用破伤风抗毒素、马破伤风免疫球蛋白预防破伤风。"},{"t":"p","x":"应与抗蛇毒血清至少间隔1小时后使用，以避免过敏或不良反应重叠。"}],"entries":["e1037"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.宣传普及毒蛇咬伤的预防知识，让群众了解和掌握毒蛇的活动规律，特别是毒蛇咬伤后的自救方法。2.毒蛇咬伤初期，接受抗蛇毒血清治疗后，应抬高患肢，以利于消肿；"},{"t":"p","x":"避免走动，以防毒液扩散。"}],"entries":["e1038"]}]},{"id":"d1404","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"破伤风","displayName":"破伤风","parentId":"","printedPage":309,"pdfPage":324,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"破伤风是指皮肉破伤，风毒之邪乘虚侵入而引起的以全身或局部肌肉强直性痉挛和阵发性抽搐为特征的急性疾病。"},{"t":"p","x":"外伤所致者又称金创痉，产后发生者称产后痉，新生儿断脐所致者称小儿脐风或脐风撮口。临床上以外伤所致者最常见。"},{"t":"p","x":"本病名首见于唐代蔺道人《仙授理伤续断秘方·医治整理补接次第口诀》，曰：“若破，用风流散填疮口，绢片包之，不可见风着水，恐成破伤风。"},{"t":"p","x":"其临床特点是有皮肉破伤史，有一定的潜伏期，以发作时呈现全身或局部肌肉的强直性痉挛和阵发性抽搐为主要特征。可伴有发热，但神志始终清楚，多因并发症而死亡。"},{"t":"p","x":"西医学亦称本病为破伤风。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病是因皮肉破伤，感受风毒之邪所引起。风为阳邪，善行数变，通过经络、血脉人里传肝，外风引动内风，导致肝风内动，筋脉失养而出现牙关紧闭、角弓反张、四肢抽搐等；"},{"t":"p","x":"如不及时控制，必然导致脏腑功能失和，筋脉拘急不止，甚至造成呼吸、循环衰竭和全身衰竭而危及生命。西医学认为，本病是由破伤风梭菌从伤口侵入人体而致病。"},{"t":"p","x":"当机体抵抗力降低或免疫力低下时，细菌在伤口局部迅速繁殖，并产生大量外毒素。外毒素主要为痉挛毒素，能引起随意肌紧张和痉挛。"}],"entries":["e1039","e1040"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现潜伏期一般为7～8天，短者24小时之内，长者数月或数年不等。"},{"t":"p","x":"潜伏期越短，预后越差。前驱期一般为1～2天，患者常出现头痛、头晕、乏力、咀嚼无力、肌肉发紧、反射亢进等；"},{"t":"p","x":"伤口往往干陷无脓，周围皮肤暗红，创口疼痛并有紧张牵制感。"},{"t":"p","x":"1)典型症状"},{"t":"p","x":"肌肉强直性痉挛：患者开始感到咀嚼不便，咀嚼肌紧张酸痛、然后出现张口困难、牙关紧闭。面部表情肌痉挛呈“苦笑”面容；"},{"t":"p","x":"颈项肌痉挛时颈项强直，头略向后仰，不能做点头动作；咽喉部肌肉痉挛可引起吞咽困难；"},{"t":"p","x":"背腹肌痉挛时腰部前凸，头和足后屈，呈角弓反张状；膈肌和肋间肌痉挛可出现呼吸困难、甚至窒息；"},{"t":"p","x":"膀胱括约肌痉挛可引起排尿困难，甚至尿潴留。阵发性抽搐：是在肌肉持续性痉挛的基础上发生的，轻微的刺激，如声音、光亮、震动、饮水、注射等均可诱发强烈的阵发性抽搐。"},{"t":"p","x":"每次发作可持续数秒、数分钟不等，发作时患者面色苍白，口唇发绀，呼吸急促，口吐白沫，流涎，磨牙，头频频后仰，四肢抽搐不止，全身大汗淋漓，十分痛苦，但神志始终清醒。"},{"t":"p","x":"强烈的肌肉痉挛和抽搐有时可使肌肉断裂、出血，甚至发生骨折、脱位和舌咬伤等。持续的呼吸肌和膈肌痉挛可造成呼吸骤停，患者死亡原因多为窒息、心力衰竭或肺部并发症。"},{"t":"p","x":"2)非典型发作症状仅出现破伤部位局部的肌肉强直，不延及全身。"},{"t":"p","x":"3)常见并发症包括肺部并发症、窒息、酸中毒。"},{"t":"p","x":"此外，突然和强烈的肌痉挛可以引起肌肉撕裂、出血、骨折、脱位、便秘和尿潴留。"},{"t":"h","lv":3,"x":"(2)辅助检查脓液培养可有破伤风梭菌生长。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表14-6)"},{"t":"table","img":"img/tab/t1406.jpg","cap":"表14-6破伤风与化脓性脑膜炎、狂犬病、癫痫的鉴别"}],"entries":["e1041"]},{"title":"治疗","blocks":[{"t":"p","x":"破伤风的发生发展甚为迅速，死亡率高，必须坚持中西医结合治疗。中医治疗以息风、镇痉、解毒为原则。"},{"t":"p","x":"西医治疗应尽快消除毒素来源和中和体内游离毒素，有效地控制和解除痉挛，保持呼吸道通畅，必要时行气管切开，不能进食者可鼻饲，防治并发症等。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140401","name":"风毒在表证","clinic":"轻度吞咽困难和牙关紧闭，全身肌肉痉挛，或只限于破伤部位局部肌肉痉挛，抽搐较轻，间歇期较长；舌淡苔薄白，脉弦数","treat":"祛风镇痉","formula":"玉真散合五虎追风散加减","formulaNames":["玉真散","五虎追风散"]},{"t":"syn","sid":"s140402","name":"风毒入里证","clinic":"发作频繁而间歇期短，全身肌肉痉挛，抽搐，牙关紧闭，角弓反张，高热，大汗淋漓，面色青紫，呼吸急促，痰涎壅盛；或伴胸闷腹胀，大便秘结，小便短赤或尿闭；舌红或红绛，苔黄或黄糙，脉弦数","treat":"祛风止痉，清热解毒","formula":"木萸散加减","formulaNames":["木萸散"]},{"t":"syn","sid":"s140403","name":"阴虚邪留证","clinic":"疾病后期，抽搐停止，倦怠乏力，头晕，心悸，口渴，面色苍白或萎黄，时而汗出，牙关不适，偶有痉挛或屈伸不利，或肌肤有蚁行感；舌淡红苔少，脉细弱无力","treat":"益胃养津，疏通经络","formula":"沙参麦冬汤加减","formulaNames":["沙参麦冬汤"]},{"t":"p","x":"2.外治疗法在控制痉挛和应用破伤风抗毒素(清创前在伤口周围注射破伤风抗毒素5000～10000IU)后进行彻底清创术，以消除毒素来源，清除坏死组织和异物，开放创口，充分引流，用3%过氧化氢溶液冲洗伤口和湿敷；"},{"t":"p","x":"亦可外敷玉真散，隔日换药1次。创面有残余坏死组织时，可外用七三丹、红油膏；"},{"t":"p","x":"创面干净，脓尽新生，用生肌散、生肌白玉膏。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)一般处理将患者隔离于安静的暗室。"},{"t":"p","x":"保持呼吸道通畅，及时吸出口鼻、咽腔的分泌物。因喉头痉挛或痰涎壅盛不易吸出而导致呼吸困难或窒息时，应及时行气管切开。"},{"t":"p","x":"轻症患者在发作间歇期尽量鼓励自行进食，重症患者要定时鼻饲，保证水和营养的摄入。也可行全胃肠外营养。"},{"t":"p","x":"(2)西医治疗强调多学科协作(急诊科、ICU、感染科、麻醉科等)，核心目标包括：①中和游离毒素(使用抗破伤风免疫球蛋白或抗毒素)。"},{"t":"p","x":"②控制感染(抗生素治疗)。"},{"t":"p","x":"③缓解肌肉痉挛(镇静、肌松药物)。"},{"t":"p","x":"④生命支持(机械通气、重症监护)。"},{"t":"p","x":"⑤彻底清创(减少破伤风梭菌繁殖环境)"},{"t":"p","x":"⑥预防并发症(如肺炎、自主神经功能紊乱)。"},{"t":"p","x":"(3)针刺疗法牙关紧闭，取下关、颊车、合谷、内庭；"},{"t":"p","x":"角弓反张，取风池、风府、大椎、长强、承山、昆仑；四肢抽搐，取曲池、外关、合谷、后溪、风市、阳陵泉、太冲、申脉。"},{"t":"p","x":"采用泻法，留针15～20分钟。"}]}],"entries":["e1042","e1043","e1044","e1045","e1046"]},{"title":"预防与调护","blocks":[{"t":"p","x":"隔离患者。保持环境安静，避免声、光、风等外界刺激，必要的治疗应争取在安静环境下进行。"}],"entries":["e1047"]}]},{"id":"d1405","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"肠痈","displayName":"肠痈","parentId":"","printedPage":311,"pdfPage":326,"syndromeCount":3,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"肠痈是指发生于肠道的痈肿，属“内痈”之范畴。"},{"t":"p","x":"该病可发生于任何年龄，以青壮年为多，男性多于女性，发病率居外科急腹症之首。肠痈之病名最早见于《素问·厥论》，曰：“少阳厥逆⋯⋯发肠痈不可治，惊者死。"},{"t":"p","x":"《金匮要略》总结了肠痈辨证论治的基本规律，推出了大黄牡丹汤等有效方剂，至今仍为后世医家所应用。本病的临床特点是转移性右下腹疼痛，伴发热、恶心、呕吐，右下腹压痛、拒按。"},{"t":"p","x":"本病相当于西医学的急、慢性阑尾炎。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"饮食不节、暴急奔走或跌仆损伤、情志所伤、寒温不适均可损伤肠胃、导致肠道传化失司、糟粕停滞，气机不畅，气滞血瘀，瘀久化热，热胜肉腐而成痈肿。西医学认为，本病的发生与其解剖和生理特点密切相关。"},{"t":"p","x":"阑尾是细长而游离的管腔结构、血供为终末动脉，易发生扭曲，异物梗阻压迫而致血运障碍、造成黏膜坏死、细菌人侵而形成炎症。"}],"entries":["e1048","e1049"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"1)初期腹痛多起于脐周或上腹部，数小时后腹痛转移并固定在右下腹部，疼痛呈持续性、进行性加重。"},{"t":"p","x":"70%～80%的患者有典型的转移性右下腹痛的特点，但也有一部分病例发病开始即出现右下腹痛。右下腹压痛是本病常见的重要体征，压痛点通常在麦氏点，可随阑尾位置变异而改变，但压痛点始终在一个固定的位置上。"},{"t":"p","x":"一般可伴有发热，体温在38℃左右，恶心纳减。舌苔白腻，脉弦滑或弦紧等。"},{"t":"p","x":"2)酿脓期若病情发展，渐至化脓、则腹痛加剧、右下腹明显压痛、反跳痛，局限性腹皮挛急，或右下腹可触及包块。"},{"t":"p","x":"壮热不退，体温39℃以上，恶心呕吐，纳呆，口渴，便秘或腹泻。舌红，苔黄腻、脉弦数或滑数。"},{"t":"p","x":"3)溃脓期腹痛扩展至全腹，腹皮挛急，全腹压痛、反跳痛。"},{"t":"p","x":"伴恶心呕吐，大便秘结或似痢不爽；壮热自汗、体温39～40℃，口干唇燥。舌质红或绛，苔黄糙，脉洪数或细数。"},{"t":"p","x":"4)变证"},{"t":"p","x":"慢性肠痈：本病初期腹痛较轻，身无寒热或微热，病情发展缓慢，苔白腻，脉迟紧；或有反复发作病史者，多数为阑尾腔内粪石阻塞所致。"},{"t":"p","x":"腹部包块：在发病4～5天后，身热不退，腹痛不减，右下腹出现压痛性包块(阑尾周围脓肿)，或在腹部其他部位出现压痛性包块(肠间隙、膈下或盆腔脓肿)，多为湿热瘀结、热毒结聚而成。"},{"t":"p","x":"湿热黄疸：本病在发病过程中可出现寒战、高热、肝肿大和压痛、黄疸，延误治疗可发展为肝痈。"},{"t":"p","x":"内、外瘘形成：腹腔脓肿形成后若治疗不当，少数病例脓肿可向小肠或大肠内穿溃，亦可向膀胱、阴道或腹壁穿破，形成各种内瘘或外瘘，脓液从瘘管排出。"},{"t":"p","x":"(2)辅助检查 ①血常规检查：初期多数患者白细胞计数及中性粒细胞比例增高；"},{"t":"p","x":"在酿脓期和溃脓期，白细胞计数常升至18×10/L以上。"},{"t":"p","x":"②尿常规检查：盲肠后位阑尾炎可刺激右侧输尿管，尿中可出现少量红细胞和白细胞。"},{"t":"p","x":"③超声可发现肿大的阑尾或脓肿，CT的灵敏度优于超声，尤其是阑尾周围脓肿的诊断，腹腔穿刺检查对诊断有一定帮助。"},{"t":"p","x":"钡剂灌肠摄片检查对慢性阑尾炎诊断有意义。脓液细菌培养及药敏试验有助于确定致病菌的种类，有针对性地选用抗菌药物。"},{"t":"p","x":"2.鉴别诊断急性阑尾炎与胃、十二指肠溃疡穿孔及右侧输尿管结石的鉴别见表14-7。同时须与妇产科疾病异位妊娠、卵巢滤泡或黄体囊肿破裂、卵巢蜒肿扭转、急性输卵管炎相鉴别。"},{"t":"p","x":"此外，有时还须与急性胃肠炎、右侧肺炎和胸膜炎、急性胆囊炎、急性肠系膜淋巴结炎等疾病进行鉴别。"},{"t":"table","img":"img/tab/t1407.jpg","cap":"表14-7急性阑尾炎与胃、十二指肠溃疡穿孔及右侧输尿管结石的鉴别"}],"entries":["e1050"]},{"title":"治疗","blocks":[{"t":"p","x":"六腑以通为用，通腑泄热是治疗肠痈的主要法则。病情严重者、及时采取手术。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140501","name":"瘀滞证","clinic":"转移性右下腹痛，右下腹局限性压痛或拒按；伴恶心、纳差，可有轻度发热；苔白腻，脉弦滑或弦紧","treat":"行气活血，通腑泄热","formula":"大黄牡丹汤合红藤煎剂加减。第十四章其他外科疾病","formulaNames":["大黄牡丹汤","红藤煎剂"]},{"t":"syn","sid":"s140502","name":"湿热证","clinic":"腹痛加剧，右下腹或全腹压痛、反跳痛，腹皮挛急，右下腹可摸及包块；壮热，纳呆，恶心呕吐，便秘或腹泻；舌红苔黄腻，脉弦数或滑数","treat":"通腑泄热，利湿解毒","formula":"复方大柴胡汤加减","formulaNames":["复方大柴胡汤"]},{"t":"syn","sid":"s140503","name":"热毒证","clinic":"腹痛剧烈，全腹压痛、反跳痛，腹皮挛急；高热不退或恶寒发热，时时汗出，烦渴，恶心呕吐，腹胀，便秘或似痢不爽；舌红绛而干，苔黄厚干燥或黄糙，脉洪数或细数","treat":"通腑排脓，养阴清热","formula":"大黄牡丹汤合透脓散加减","formulaNames":["大黄牡丹汤","透脓散"]},{"t":"p","x":"2.外治疗法无论脓已成或未成，均可选用金黄散、玉露散或双柏散，用水或蜜调成糊状，外敷右下腹。"},{"t":"p","x":"还可采用通里攻下、清热解毒等中药肛滴，如大黄牡丹汤、复方大柴胡汤等煎剂150～200mL，直肠内缓慢滴入，以达到通腑泄热排毒的目的。"},{"t":"p","x":"3.特殊类型肠痈的治疗小儿肠痈、老年肠痈、妊娠期急性肠痈、异位肠痈等应结合自身特点辨证论治，并采取相应的西医治疗。"},{"t":"sub","title":"4.其他疗法","blocks":[{"t":"p","x":"(1)一般疗法 ①输液：对禁食或脱水或有水、电解质紊乱者，应静脉补液予以纠正。"},{"t":"p","x":"②胃肠减压：阑尾穿孔并发弥漫性腹膜炎伴有肠麻痹者，应行胃肠减压。"},{"t":"p","x":"③抗菌药物：腹膜炎体征明显或中毒症状较重者，可选用广谱抗菌药物。"},{"t":"p","x":"(2)针刺疗法可作为辅助治疗方法，具有促进肠蠕动、促使停滞物排出、改善血运、止痛、退热、提高人体免疫机能等作用。"},{"t":"p","x":"主穴：双侧足三里或阑尾穴。配穴：发热，加曲池、合谷或尺泽放血；"},{"t":"p","x":"恶心呕吐，加内关、中脘；痛剧，加天枢；腹胀，加大肠俞、次。均取泻法，每次留针0.5～1小时，每隔15分钟强刺激1次，每日2次。"},{"t":"p","x":"加用电针可提高疗效。"},{"t":"p","x":"(3)手术疗法西医治疗急性阑尾炎的原则是早期行手术治疗，随着微创技术的发展，可选用腹腔镜阑尾切除术。"}]}],"entries":["e1051","e1052","e1053","e1054","e1055"]},{"title":"预防与调护","blocks":[{"t":"p","x":"避免饮食不节和食后剧烈运动，养成规律性排便习惯。"}],"entries":["e1056"]}]},{"id":"d1406","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"胆石症","displayName":"胆石症","parentId":"","printedPage":313,"pdfPage":328,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"胆石症是指湿热浊毒与胆汁互结成石，阻塞于胆道而引起的疾病。"},{"t":"p","x":"胆石症在中医学中属于“胆胀”“胁痛”“结胸”“黄疸”等范畴。《灵枢·经脉》曰：“胆足少阳之脉⋯⋯是动则病口苦，善太息，心胁痛，不能转侧。"},{"t":"p","x":"流行病学调查表明，我国胆结石患病率为0.9%～10.1%，平均为5.6%。女性患病率高于男性，并随年龄增长而增加。"},{"t":"p","x":"根据胆石的外观和化学成分，分为胆固醇结石、胆色素结石、混合结石三类。随着生活水平的提高、饮食结构的改变，我国的胆结石发病已经由以胆色素结石为主逐渐转变为以胆固醇结石为主。"},{"t":"p","x":"本病相当于西医学的胆囊结石或肝内外胆管结石。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"情志不遂，饮食失节，或蛔虫上扰，肝胆气机不畅，肝失疏泄，郁久化热，湿热蕴蒸于肝胆，湿热浊毒与胆汁互结，日久而成砂石，阻塞胆道而发病。"},{"t":"p","x":"或久病耗阴，劳欲过度，或由于各种原因引起精血亏损，水不养木，肝阴不足，疏泄失常，累及胆腑，精汁通降不畅、久积成石。若郁久化热，可致胆汁溢于肌肤而发黄。"},{"t":"p","x":"西医学认为，胆结石的发生与饮食结构有关，肝内外胆管结石与胆道梗阻、感染、胆汁淤积等因素密切相关。"}],"entries":["e1057","e1058"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"h","lv":3,"x":"(1)临床表现"},{"t":"p","x":"腹痛：结石嵌顿于胆囊颈部或胆总管下端可出现急性发作性胆绞痛，疼痛多位于右胁下、胃脱或膻中。大多餐后发生，尤其是进油腻食物或腹部受震动易诱发，可痛引肩背。"},{"t":"p","x":"多为阵发性疼痛，或持续性疼痛阵发性加重、可为钝痛、绞痛、剧痛、常伴恶心、呕吐、自汗。若胆石移行损伤胆道内壁，引起胆道出血，可有呕血或黑便。"},{"t":"p","x":"右上腹压痛、墨菲征(Murphy征)阳性。发热和寒战：是胆道结石染毒的表现。"},{"t":"p","x":"黄疸：为结石引起胆道梗阻所致。一般较轻或呈波动性。"},{"t":"p","x":"消化道反应：表现为腹胀、嗳气、厌油腻食物、口苦、反酸等。"},{"t":"p","x":"(2)辅助检查血常规检查可见白细胞总数升高，以中性粒细胞升高为主；"},{"t":"p","x":"B超、X线、CT、MRI对于该病的诊断有重要意义，尤其是无症状结石。2.鉴别诊断胆石症与急性胰腺炎、胃十二指肠穿孔、蛔厥、肝痈的鉴别见表14-8。"},{"t":"p","x":"胆石症还须与其他急腹症，如急性肠梗阻、急性肠扭转、肠穿孔、急性阑尾炎并发穿孔、肠系膜血管栓塞或血栓形成、女性右侧宫外孕及卵巢囊肿蒂扭转等疼痛性疾病相鉴别，超声检查、X线腹部平片、尿常规等有助于鉴别。"},{"t":"table","img":"img/tab/t1408.jpg","cap":"表14-8胆石症与急性胰腺炎、胃十二指肠穿孔、蛔厥、肝痈的鉴别"}],"entries":["e1059"]},{"title":"治疗","blocks":[{"t":"p","x":"六腑以通为用，疏肝利胆、清热利湿、通里攻下、活血解毒是主要治法。胆石症急性发作期应以攻邪为主，通降为先。"},{"t":"p","x":"病情危重者应选择手术和中西医结合治疗。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140601","name":"肝郁气滞证","clinic":"右上腹间歇性绞痛或闷痛，有时可向右肩背部放射，右上腹有局限性压痛；伴低热、口苦，食欲减退；舌质淡红，苔薄白或微黄，脉弦紧","treat":"疏肝利胆，理气开郁","formula":"金铃子散合大柴胡汤加减","formulaNames":["金铃子散","大柴胡汤"]},{"t":"syn","sid":"s140602","name":"肝胆湿热证","clinic":"右上腹有持续性胀痛，多向右肩背部放射，右上腹肌紧张，有压痛，有时可摸到肿大之胆鬟；伴高热、恶寒、口苦咽干、恶心呕吐、不思饮食，部分患者出现身目发黄；舌质红，苔黄腻，脉弦滑或弦数","treat":"疏肝利胆，清热利湿","formula":"茵陈蒿汤合大柴胡汤加减","formulaNames":["茵陈蒿汤","大柴胡汤"]},{"t":"syn","sid":"s140603","name":"肝胆脓毒证","clinic":"右上腹硬满灼痛、痛而拒按，或可触及肿大的胆囊；黄疸日深，壮热不止；舌质红绛，苔黄燥，脉弦数。严重者四肢厥冷，脉微细而数","treat":"泻火解毒，养阴利胆","formula":"茵陈蒿汤合黄连解毒汤加减","formulaNames":["茵陈蒿汤","黄连解毒汤"]},{"t":"syn","sid":"s140604","name":"肝阴不足证","clinic":"胁肋隐痛，绵绵不已，可向右肩背部放射，遇劳加重；口干咽燥，心中烦热，两目干涩，头晕目眩；舌红少苔，脉弦细","treat":"滋阴柔肝，养血通络","formula":"一贯煎加减","formulaNames":["一贯煎"]},{"t":"p","x":"2.外治疗法芒硝30g，生大黄60g，均研细末，大蒜头1个，米醋适量，共捣成糊状，布包外敷于胆囊区。"},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针灸疗法"},{"t":"p","x":"体针：取阳陵泉、胆囊穴、中脘、太冲、胆俞等穴，每次选2～3穴，用泻法或平补平泻法，每次留针30分钟，每日2次。耳针：选用交感、神门、肝、胆、十二指肠，针刺或耳穴敷贴。"},{"t":"p","x":"耳穴压豆法：用耳穴探测仪探查耳穴压痛点后敷贴王不留行籽，每日按压数次。"},{"t":"p","x":"(2)西医疗法"},{"t":"p","x":"西药治疗：静脉输液以纠正水电解质和酸碱平衡失调；合理选用抗菌药物；"},{"t":"p","x":"疼痛发作时，应选用解痉止痛剂及吗啡类止痛药。溶石治疗：胆囊结石可口服鹅去氧胆酸或熊去氧胆酸，疗效不确切。"},{"t":"p","x":"手术治疗：胆嚢结石通常均需手术(腹腔镜胆囊切除术为常规手术方式)治疗，肝内外胆管结石多数也需要手术治疗，如胆道探查术、十二指肠镜下oddi括约肌切开取石术、胆道镜下胆囊切开取石术等。"},{"t":"p","x":"急性胆囊炎若发生严重并发症，如化脓性胆囊炎、化脓性胆管炎，可以先行手术造口或十二指肠镜下鼻胆管引流术。中医药治疗在胆石症手术患者的围手术期干预，可明显降低残石率，减少复发率，并提高患者生活质量。"}]}],"entries":["e1060","e1061","e1062","e1063","e1064","e1065"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.提倡合理饮食，不宜过饱，忌食生冷及不易消化的食物，一般以进食低脂流质、半流质饮食为宜。2.如患者病情变化而需要手术，应做好手术前准备。"}],"entries":["e1066"]}]},{"id":"d1407","kind":"main","chapterId":"ch14","chapterNo":"第十四章","chapterName":"其他外科疾病","name":"痛风","displayName":"痛风","parentId":"","printedPage":315,"pdfPage":330,"syndromeCount":4,"pages":[{"title":"概述・病因病机","blocks":[{"t":"p","x":"痛风是由于体内嘌呤代谢障碍、尿酸生成过多和/或尿酸排泄减少、致血中尿酸浓度增高所引起的一组异质性疾病。其临床特点为高尿酸血症，特征性急性关节炎反复发作，关节滑液的血细胞内可找到尿酸钠结晶，痛风石形成。"},{"t":"p","x":"本病属中医学“痹证”“历节”“脚气”“痛风”等范畴。本病名首见于梁代陶弘景《名医别录·上品》，曰：“独活，微温，无毒。"},{"t":"p","x":"主治诸贼风，百节痛风无久新者。”西医学亦称本病为痛风。"},{"t":"h","lv":3,"x":"病因病机"},{"t":"p","x":"本病发病以脾肾两虚为本，湿热毒瘀为标，证属正虚邪实。《景岳全书·脚气》中认为，本病外由阴寒水湿，湿邪袭皮肉筋脉，内由平素肥甘过度，湿壅下焦；"},{"t":"p","x":"寒与湿邪相结，郁而化热，停留肌肤；病变部位红肿潮热、久则骨蚀。"},{"t":"p","x":"西医学认为，痛风最重要的生化基础是高尿酸血症。"}],"entries":["e1067","e1068"]},{"title":"辨病","blocks":[{"t":"h","lv":3,"x":"1.诊断"},{"t":"p","x":"(1)临床表现痛风多见于40岁以上的男性、女性多在围绝经期后发病，近年呈年轻化趋势。"},{"t":"p","x":"其自然病程分期如下：无症状高尿酸血症期：无明显症状，仅血尿酸升高。"},{"t":"p","x":"急性期及间歇发作期：即急性痛风性关节炎，典型发作于深夜因剧痛惊醒，12小时左右达高峰，呈撕裂样、刀割样或咬噬样，受累关节及周围红、肿、热、痛，功能受限，数天至2周内自行缓解。"},{"t":"p","x":"首次发作多侵犯单关节，以第一跖趾关节或指关节累及最常见，可伴发热、寒战等全身症状，以及白细胞升高、血沉增快等体征。间歇发作期：为症状缓解后的无症状阶段，症状趋不典型。"},{"t":"p","x":"慢性期：表现为皮下痛风石和慢性痛风石性关节炎，因长期高尿酸血症致单钠尿酸盐晶体沉积。皮下痛风石好发于耳郭、关节周围等，为黄白色赘生物，破溃后排出白色粉状物，经久不愈。"},{"t":"p","x":"关节内痛风石可致骨质破坏、周围组织纤维化，表现为持续肿痛、畸形及功能障碍，可伴急性发作。肾脏病变和其他共病期：包括慢性痛风肾病(尿浓缩功能下降，晚期致肾功能不全)、尿酸性肾石病及急性肾衰竭(尿酸结晶梗阻尿路)。"},{"t":"p","x":"其他共病包括代谢综合征、心脑血管疾病。"},{"t":"p","x":"(2)辅助检查血尿酸男性>7mg/dl(416μmol/L)、女性>6mg/dl(358μmolL)为高尿酸血症。"},{"t":"p","x":"尿酸测定可区分生成过多型(占10%)与排泄减少型(占90%)。偏振光显微镜可见针状/杆状单钠尿酸盐晶体。"},{"t":"p","x":"影像学检查中，X线、CT示急性期软组织肿胀、慢性期骨质破坏；MRI定位深部沉积物；"},{"t":"p","x":"超声可见痛风结节典型表现。"},{"t":"h","lv":3,"x":"2.鉴别诊断(表14-9)"},{"t":"table","img":"img/tab/t1409.jpg","cap":"表14-9痛风与类风湿关节炎、创伤性关节炎、化脓性关节炎、假性痛风关节炎的鉴别"}],"entries":["e1069"]},{"title":"治疗","blocks":[{"t":"p","x":"痛风的治疗原则是标本兼顾，急则治其标，缓则治其本，内治和外治同施。急性期以控制关节红肿热痛症状为主，内治清热除湿、活血通络，外治消肿通络止痛。"},{"t":"p","x":"缓解期以扶正为主，兼以驱邪，内治补益肝肾、通络活血，外治活血通络、宣痹止痛。"},{"t":"h","lv":3,"x":"1.辨证论治"},{"t":"syn","sid":"s140701","name":"湿热阻痹","clinic":"下肢小关节卒然红肿热痛、拒按，触之局部灼热，得凉则舒；伴发热口渴，心烦不安，溲黄；舌红苔黄腻、脉滑数","treat":"清热除湿，活血通络","formula":"四妙散合宣痹汤加减","formulaNames":["四妙散","宣痹汤"]},{"t":"syn","sid":"s140702","name":"风寒湿痹","clinic":"肢体、关节疼痛，或呈游走性疼痛，或呈关节剧痛，痛处不移，或肢体关节重着肿痛，肌肤麻木，于阴雨天加重；舌苔薄白，脉弦紧或濡缓","treat":"温经散寒，祛风化湿","formula":"乌头汤加减","formulaNames":["乌头汤"]},{"t":"syn","sid":"s140703","name":"痰瘀阻滞","clinic":"关节肿胀，甚则关节周围漫肿，局部酸麻疼痛，或见“块凛”硬结不红；伴有目眩，面浮足肿，胸脘痞闷；舌胖质暗，苔白腻，脉缓或弦滑","treat":"活血化瘀，化痰通络","formula":"身痛逐瘀汤加减","formulaNames":["身痛逐瘀汤"]},{"t":"syn","sid":"s140704","name":"肝肾阴虚","clinic":"病久屡发，关节痛如被杖，局部关节变形，昼轻夜重，肌肤麻木不仁，步履艰难，筋脉拘急，屈伸不利；头晕耳鸣，颧红口干；舌红少苔，脉弦细或细数","treat":"补益肝肾，通络止痛","formula":"独活寄生汤加减","formulaNames":["独活寄生汤"]},{"t":"sub","title":"2.外治疗法","blocks":[{"t":"p","x":"(1)膏药外敷 ①消肿止痛膏(组成：朱砂、雄黄、冰片、黄连、五倍子，共捣为膏)外敷，能改善关节红肿热痛之症，使痛风性关节炎得到迅速改善。"},{"t":"p","x":"②风火软膏(组成：防风、大葱、白芷、川乌各60g，共捣为膏)用调热黄酒敷冷痛处，有祛风通痹止痛的功效，主治急、慢性期痛风。"},{"t":"p","x":"(2)散剂外敷当归散(组成：防风、当归、藁本、独活、荆芥穗、牡荆叶各30g。上药为粗末，盐120g同炒热，袋盛熨之)，有祛风除湿、活血止痛的功效。"},{"t":"p","x":"主治慢性期痛风。"},{"t":"p","x":"(3)药酒外搽伸筋草12g，透骨草12g，川桂枝9g，羌活12g，独活12g，川乌9g，草乌9g，全当归12g，紫草9g，红花9g，桑枝9g，虎杖9g，络石藤9g，地鳖虫6g。"},{"t":"p","x":"诸药用高粱酒1.5kg浸泡，约1周后外用。功效：祛风除湿，活血通络，宣痹止痛。"},{"t":"p","x":"热水洗患处后用此酒轻擦患处，每次10分钟，每日2～3次。"}]},{"t":"sub","title":"3.其他疗法","blocks":[{"t":"p","x":"(1)针刺治疗有活血、通络、止痛的功效。"},{"t":"p","x":"①主穴取肾俞、气海俞、膀胱俞、关元、三阴交。"},{"t":"p","x":"配穴取离患部1～2寸的阿是穴。手法：用平补平泻，中等量刺激。"},{"t":"p","x":"②急性期取患侧隐白、大敦、太冲、三阴交、太溪、照海、阿是穴，恢复期取双侧太冲、三阴交、太白、太溪、照海、足三里、肝俞、肾俞。"},{"t":"p","x":"手法：急性期隐白、大敦点刺放血，余穴针刺用泻法；恢复期用平补平泻法。"},{"t":"p","x":"(2)西药治疗西医治疗痛风需分期干预。"},{"t":"p","x":"急性期：需迅速控制关节炎发作，患者应卧床休息、抬高患肢并冷敷，及早足量使用非甾体抗炎药(一线用药)、秋水仙碱(传统药物，注意不良反应)或糖皮质激素(用于不耐受前两者或肾功能不全者)，已用降尿酸药者不停用。"},{"t":"p","x":"间歇期和慢性期：以长期控制血尿酸，预防复发及关节、肾脏损害为目标，用黄嘌呤氧化酶抑制剂(抑制尿酸生成)或促尿酸排泄药(适用于肾功能正常、排泄减少型)。肾脏病变者需用别嘌醇降尿酸、碱化尿液并保持尿量。"},{"t":"p","x":"避免影响尿酸排泄的利尿剂。加强共病治疗。"},{"t":"p","x":"痛风石期可行痛风石剔除、关节矫形手术。"}]}],"entries":["e1070","e1071","e1072","e1073","e1074","e1075","e1076"]},{"title":"预防与调护","blocks":[{"t":"p","x":"1.饮食是诱发痛风发病的关键因素、进低嘌呤低能量饮食，戒酒，多饮水，每日饮水2000mL以上。2.控制体重，规律运动，减少富含果糖饮料的摄入。"}],"entries":["e1077"]}]}],"stats":{"chapters":9,"cards":132,"pages":498,"diseases":124,"syndromes":322,"figs":67,"tables":119,"chars":241481}};
